export default [{"id":1,"question":"يقول تعالى: لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا [هود:7]، فهل يُفهم من هذه الآية: أنَّ المهم هو حُسن العمل دون النظر إلى كثرته ودوامه؟","title":"معنى قوله تعالى: {ليبلوكم أيُّكم أحسنُ عملاً}","answer":"الجواب: هذا يدل على أنَّ الحُسن أهم، إحسان العمل أهم من كثرته، وإن كانت الكثرةُ مطلوبةً، لكن الأهم من الكثرة إحسان العمل.\nولهذا قيل لأبي علي ابن الفُضيل بن عياض: يا أبا علي، ما معنى أحسن العمل؟ قال: \"أخلصه وأصوبه\"، قيل: ما أخلصه؟ وما أصوبه؟ قال: «إنَّ العمل إذا كان خالصًا ولم يكن صوابًا لم يُقبل، وإن كان صوابًا ولم يكن خالصًا فلم يُقبل، حتى يكون خالصًا صوابًا\"، قيل: يا أبا علي، ما هو الخالص الصواب؟ قال: \"الخالص: أن يكون لله، والصواب: أن يكون على السنة\".\nفالاهتمام بإحسان العمل أعظم وأوْلى من الكثرة، فكون المؤمن يهتم بإخلاص العمل وتنقيته من الرياء وغيره من أنواع الشرك، ويهتم بمُطابقته للشريعة، وألا يكون فيه ابتداعٌ؛ هذا أهم من الكثرة، وإذا صحَّ له هذا فليُكثر من العمل الذي صحَّ له فيه هذا -صحَّ له فيه الإخلاص، وصحَّ له فيه الصدق- أما أن يهتم بالكثرة من غير عنايةٍ بالإخلاص وعنايةٍ بالصدق -يعني: المُتابعة- فهذا لا، يجب أن يكون الاهتمام بالإخلاص والمُتابعة أعظم من الكثرة.","link":"https://binbaz.org.sa/fatwas/2746/معنى-قوله-تعالى-ليبلوكم-ايكم-احسن-عملا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0251.mp3","categories":["التفسير"]},{"id":94,"question":"يقول بعضُ المُفسرين في تفسير قول الله : فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى [الأعلى:9] أي: ذَكِّرْ حيث تنفع التذكرة؟","title":"معنى قوله تعالى: {فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى}","answer":"الجواب: هذا ليس بشرطٍ، إنما هو وصفٌ أغلبيٌّ، يعني: تَعْظُم الفرضية والوجوب عند انتفاع الناس بالذِّكْرى، وإنما هو أمرٌ بالتذكير، عسى أن ينتفعوا، ولهذا جاء في الآيات الأخرى: فَذَكِّرْ إِنَّمَا أَنْتَ مُذَكِّرٌ [الغاشية:21]، وَذَكِّرْ فَإِنَّ الذِّكْرَى تَنْفَعُ الْمُؤْمِنِينَ [الذاريات:55].\nفالإنسان يُذكِّر، والنفع بيد الله، لكن إذا نفعت الذِّكْرى يكون الوجوب أشدَّ، وتكون الفائدةُ أعظم، فإذا رأى منه الانتفاع والاستفادة فالواجب عليه أن يتضاعف ويَقْوَى ويَكْبُر.","link":"https://binbaz.org.sa/fatwas/3111/معنى-قوله-تعالى-فذكر-ان-نفعت-الذكرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0071.mp3","categories":["التفسير"]},{"id":159,"question":"الزنا يُعتبر من الآفات الاجتماعية الخطيرة في المجتمع، أرجو التعليق لما في الزنا من مخاطر اجتماعية؟","title":"ما أخطار الزنا والمنكرات على المجتمع؟","answer":"الجواب: الزنا وشرب المُسكرات كله من الآفات الاجتماعية، من أخبثها وأعظمها شرب المسكرات، وتعاطي الحشيش والحبوب المُسكرة المُخدرة، وتعاطي التدخين بأنواعه، كله من الآفات، والزنا أقبح وأعظم -والعياذ بالله- وهكذا اللّواط، كله من الآفات الخبيثة التي يجب الحذر منها ومن وسائلها، والله يقول: وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا ۝ إِلَّا مَنْ تَابَ الآية [الفرقان:68- 70].\nوثبت عن رسول الله عليه الصلاة والسلام أنه قال: لا يزني الزاني حين يزني وهو مؤمن، ولا يسرق السارق حين يسرق وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن، ولا ينتهب نهبةً ذات شرفٍ يرفع الناسُ إليه فيها أبصارَهم حين ينتهبها وهو مؤمن، هذا الحديث الصحيح يدل على شدَّة الوعيد في هذا، وأن الزاني والسارق وشارب الخمر والنَّاهب لأموال الناس إنما يفعل هذا لزوال إيمانه، وعدم وجود الإيمان، وهذا الإيمان هو الإيمان الكامل والإيمان الواجب مع أصل الإيمان، ولكن أطلقه النبيُّ من باب الوعيد، من باب التَّحذير.\nوقد غلط في هذا الخوارج، واحتجوا بهذا الحديث على كفره، واحتجت المُعتزلة بهذا الحديث على أنه مُخلَّدٌ في النار، وقد غلطا جميعًا، ولكنَّ أهل السنة والجماعة يقولون: إن هذا من باب الوعيد، فأطلقه النبيُّ ﷺ ونُطلقه من باب الوعيد والتَّحذير مع الإيمان، بأن أصل الإيمان معه، أصل الإيمان مع السارق، ومع الزاني، ومع شارب الخمر، لا نُكفِّره إلا إذا استحلَّ هذه الأمور، إذا استحلَّ الزنا وقال: إنه حلالٌ، أو استحلَّ الخمر، أو استحلَّ السرقة؛ يكون كافرًا، يكون مُرْتَدًّا -نعوذ بالله.\nأما ما دام يعرف أنه مُحرَّم، ويعرف أنه عاصٍ بزناه، وأن السرقة حرام، والزنا حرام، والمسكر حرام، وأشباه ذلك، ولكنه غلبه هواه وغلبته شهوته حتى فعل ما فعل، مع إيمانه بأنه محرم؛ فنقول: إنَّ هذا نفى الإيمان الواجب، وأن أصل الإيمان باقٍ، ومعه أصل الإسلام، وهو مسلمٌ عاصٍ، مؤمن عاصٍ، خلافًا للخوارج، وخلافًا للمُعتزلة.\nهذا قول أهل السنة والجماعة في هذه المسائل، يقولون: مؤمن بإيمانه، فاسق بكبيرته، ويقولون: مؤمن عاصٍ، ويقولون: فاسقٌ، ولا يقولون: كافر، ولا: مُخَلَّد في النار، إلَّا إذا استحلَّ ذلك، فإذا استحلَّ الزنا والخمر ونحوهما صار كافرًا عند أهل السنة والجماعة جميعًا.","link":"https://binbaz.org.sa/fatwas/3696/ما-اخطار-الزنا-والمنكرات-على-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0152.mp3","categories":["التفسير"]},{"id":184,"question":"يسأل: ماذا قُدِّم للشباب، والحقوق عليه كثيرة؟ وماذا قُدِّم لنا؟","title":"ما واجبات الشباب؟ وما حقوقهم؟","answer":"الجواب: قد قُدِّم له خيرٌ كثيرٌ، ولا سيَّما في هذه البلاد، قُدمت لهم بحمد الله الدراسات الواسعة المجانية، فقد يُساعدوا عليها، ويُعانوا عليها، وهُيئت لهم فرص ليتعلم ويعمل ويدعو إلى الله ، فهو بحمد الله في هذه البلاد قد هُيئت له الفرصة، وقُدمت له أسباب النجاح، ولكن المصيبة العظمى أن يتكاسل، وأن يضعف، وألا يحفظ وقته.\nنعم قد يُقال: إنَّ كثرة المواد قد تُضعفه، لكن مَن جدَّ واجتهد وصابر سوف يكون له من الفهم والعلم والتوفيق والخير ما ليس لغيره، وإلا فلا شكَّ أنه قُدِّم له في هذه البلاد الشيء الكثير، وتُسند له أمور كثيرة، وأُعين على طلب العلم.\nأما في البلاد الأخرى فالأمور لا شكَّ أنها مختلفة، لا شكَّ أنَّ في البلاد الأخرى الشباب يدفع من ماله في طلب العلم، وقد يعجز عن ذلك، وقد لا يقوى، لكن هنا في هذه البلاد وفي بلادٍ أخرى قد يُعان الشباب، وقد يُفسح له المجال من جهاتٍ كثيرةٍ، ولكنه قد يتأخَّر، وقد يتكاسل، وقد يتقاعس، وقد يفرح بالوظيفة وينتهز فرصة التَّخرج، ولا تكون عنده من العناية التامَّة ما تجعله إمامًا وتجعله قدوةً صالحةً، بل همّه أن ينجح ويتوظَّف وانتهينا، ولا حول ولا قوةَ إلا بالله.","link":"https://binbaz.org.sa/fatwas/3757/ما-واجبات-الشباب-وما-حقوقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0187.mp3","categories":["التفسير"]},{"id":190,"question":"مَن هم ذوو الأرحام المذكورون في كتاب الله؟ أرجو إيضاحهم","title":"من ذوو الأرحام المذكورون في القرآن؟","answer":"الجواب: يقول الله سبحانه: وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ [الأنفال:75]، فهم القرابات، الأرحام هم الأقارب من جهة أبيك ومن جهة أمك يُقال لهم: أولو الأرحام.\nكان الميراثُ في أول الإسلام بين المُهاجرين، ثم نسخ الله ذلك وجعله للرحم: للأقارب، مع الزوجة والزوج، فقال سبحانه: وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ، فأخوك وأختك وعمّك وأخوك من أمك وأمك وجداتك كلهم من ذوي الأرحام.\nثم هم أقسام: بعضهم يرث، وبعضهم لا يرث، فالوالدان والأجداد والجدَّات والأولاد والإخوة جميعهم من الورثة، وهكذا الأعمام.","link":"https://binbaz.org.sa/fatwas/3764/من-ذوو-الارحام-المذكورون-في-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0195.mp3","categories":["التفسير"]},{"id":223,"question":"أنا طالبٌ في المرحلة الثانوية، واخترتُ لي رفقةً صالحةً، لكن والدي يمنعني من السير معهم ومن مُصاحبتهم، ولقد قال لي: سأشتري لك سيارةً وافعل ما تشاء، اشرب الدخان، وغير ذلك، لكن لا تمشِ مع هؤلاء، فما قولكم في ذلك؟","title":"ما يفعل من يمنعه أبوه من الرفقة الصالحة؟","answer":"الجواب: يقول النبيُّ ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوقٍ في معصية الخالق، فلا يُطاع أبوك، ولا غير أبيك، ولا السلطان، ولا الأمير، ولا الزوج، ولا الزوجة، فيما يُخالف شرعَ الله. لكن تصحب الطيبين، وتُحسن الأسلوبَ مع أبيك، والكلام معه بلطفٍ وأسلوبٍ جيدٍ، وتعتذر إليه وتقول: يا والدي، كذا وكذا وكذا، بالأسلوب الحسن، هؤلاء إخوتي في الله، أتذاكر معهم، وأستفيد منهم، وأقضي بعض وقتي في صُحبتهم؛ لأنَّ هذا ينفعني في ديني، وأرجو منك عدم منعي من ذلك، وعدم التأثر من ذلك، فتعمل هذا وهذا، لا تزال مع أبيك بالاعتذار والكلام الطيب، ومع زملائك الطيبين بالصحبة والمُرافقة والمُذاكرة، فتجمع بين الأمرين.\nفلا تكن عنيفًا مع والدك، ولا سيّئ الخلق مع والدك، لا، كن لينًا مع والدك، كن أرضًا لينةً، طيب الخلق، طيب الكلام، فقد قال الله سبحانه في حقِّ الوالدين الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:15]، فعليك أن تصحبه بالخير، ولكن لا تُطعه فيما يضرّك وفيما يُخالف شرع الله .","link":"https://binbaz.org.sa/fatwas/4063/ما-يفعل-من-يمنعه-ابوه-من-الرفقة-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0230.mp3","categories":["التفسير"]},{"id":240,"question":"يسأل عن تفسير قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنْفُسَكُمْ لَا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105]، يقول بأن بعض الناس يتَّخذ هذه الآية ذريعةً لعدم الأمر بالمعروف والنَّهي عن المنكر، فما رأي فضيلتكم؟","title":"تفسير آية: (يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنْفُسَكُمْ)","answer":"الجواب: هذه الآية قد علَّق عليها أميرُ المؤمنين أبو بكر الصديق  في أول خلافته لما خطب الناسَ قال: \"أيها الناس، إنَّكم تقرؤون هذه الآية وتضعونها في غير موضعها، وإني سمعتُ الرسول ﷺ يقول: إنَّ الناس إذا رأوا المُنكر فلم يُغيروه أوشك أن يعمَّهم الله بعقابه\"، وتلا قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنْفُسَكُمْ لَا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ.\nفبيَّن  أنَّ عدم وقوع الضَّرر مقيدٌ بالهداية: لَا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ، والهداية إنما تتم بأداء الواجبات وترك المحارم، ومن الواجبات: الأمر بالمعروف والنَّهي عن المنكر، فلا يكفي أنك أن تكون مهتديًا إلا بأداء الواجب: الأمر بالمعروف والنَّهي عن المنكر، وإلا فلستَ بمُهتدٍ فيضرّك ذلك.\nلَا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ إذا أمرتَ بالمعروف، ونهيتَ عن المنكر، وأديتَ الواجبات، وتركتَ المُحرمات؛ لا يضرُّك مَن ضلَّ بعد ذلك، ليس بيدك الأمر: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، إنما الواجب عليك التَّبليغ والبيان والأمر والنَّهي، فإذا لم يسمع منك مَن بلَّغتَه ومَن أمرتَه ودعوتَه لا يضرُّك ذلك: إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56].","link":"https://binbaz.org.sa/fatwas/4119/تفسير-اية-يا-ايها-الذين-امنوا-عليكم-انفسكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0250.mp3","categories":["التفسير"]},{"id":345,"question":"قال الله تعالى: وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَابٍ أَلِيمٍ [الحج:25]، ما معنى الإلحاد هنا؟ وهل المقصود به في المسجد الحرام فقط أو في الحرم؟","title":"تفسير: (وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ..}","answer":"الجواب: المقصود الحرم؛ لأنَّ كله يسمى المسجد الحرام، والإلحاد هو الميل، يقال: ألحد: مال، ومنه تسمية اللَّحد في القبر؛ لأنه يميل إلى الجهة القبلية، فالإلحاد هو الميل عن الحقِّ، ولهذا قال بعده: بِظُلْمٍ إيضاح، بِإِلْحَادٍ بِظُلْمٍ، والظلم يشمل الشرك، ويشمل المعاصي، فالشرك يُسمَّى: ظلمًا، كما قال : إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13]، وقال سبحانه: وَالْكَافِرُونَ هُمُ الظَّالِمُونَ [البقرة:254]، وتُسمَّى المعاصي أيضًا: ظلمًا، ويُسمَّى العدوان على العباد: ظلمًا، اتَّقوا الظلم، فإنَّ الظلم ظلمات يوم القيامة، فمَن أراد فيه المعصية دخل تحت هذه الآية وإن لم يعملها، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4433/تفسير-ومن-يرد-فيه-بالحاد-بظلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0398.mp3","categories":["التفسير"]},{"id":364,"question":"كنتُ في العاشرة من عمري وقام والدي يريد ضربي عند أمرٍ ووقع على الأرض، فدعوتُ عليه وقلتُ: عثرك الله، فطردني وضربني، وأبلغ من العمر الآن ثلاثين عامًا، ووالدي قد تُوفي، ولعله محرّج ويسأل؟","title":"بم يُنصح من عقَّ والده عندما كان صغيراً؟","answer":"الجواب: عليك التوبة إلى الله، ولو كنت في حال الصغر قبل التَّكليف فلا حرج عليك إن شاء الله، ولكن تُكثر له من الدعاء والاستغفار والرحمة، تقول: اللهم اغفر له، اللهم ارحمه، اللهم اجزه عني خيرًا، والحمد لله، وأنت حينذاك ليس عليك حرجٌ من جهة التَّكليف؛ لقول النبي ﷺ: رُفِعَ القلمُ عن ثلاثةٍ: عن النائم حتى يستيقظ، وعن الصغير حتى يبلغ، وعن المجنون حتى يفيق، وأنت حينذاك لست مُكلَّفًا، نسأل الله أن يعفو عنك، ولكن تدعو له كثيرًا.","link":"https://binbaz.org.sa/fatwas/4613/بم-ينصح-من-عق-والده-عندما-كان-صغيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0419.mp3","categories":["التفسير"]},{"id":375,"question":"أجد من والداي كثيرًا من المُخالفات، لدرجة تبلغ الكفر، فهل أهجرهم أم ماذا؟ مع العلم أني أنصحهم وأُبين لهم.","title":"كيف يُنصح للوالدين في مخالفات تصل للكفر؟","answer":"الجواب: الواجب على الولد مع والديه وإن كانا كافرين أن يُصاحبهما بالمعروف، كما قال الله جلَّ وعلا: وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:15]، فالوالدان لهما حقٌّ عظيمٌ، فلا يجوز هجرهما، ولا إيذاؤهما، وإن كانا كافرين، ولكن يُصاحبهما بالنَّصيحة والتَّوجيه والصِّلة وأسباب هدايتهما؛ لعلَّ الله يهديهما بأسبابه، ولو كانا كافرين، كما سمعت في الآية.\nفالوالدان لهما شأنٌ عظيمٌ غير شأن بقية الأقارب، فالواجب على الولد أن يسعى في صلاح والديه، وأن يجتهد في أسباب هدايتهما، وأن يُقابلهما بالمعروف والكلام الطيب والسيرة الحميدة، وأن يُعاملهما بما يستطيع مما يجلبهما إلى الخير، ويقودهما إلى الحقِّ والهدى، ولا يهجرهما، ولا يُؤذيهما، ولا يسبّهما، قال الله تعالى: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلَاهُمَا فَلَا تَقُلْ لَهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23- 24]، ولم يخصّ ذلك بالوالدين المسلمين.\nفالوالدان لهما حقٌّ عظيمٌ تجب مراعاته، وإن كان الوالدان مسلمين أحقّ وأكبر حقًّا، ولكن هؤلاء أيضًا لهم حقٌّ، ولهم واجب العناية، لعلَّ الله يهديهما ويردّهما إلى الصواب.","link":"https://binbaz.org.sa/fatwas/4635/كيف-ينصح-للوالدين-في-مخالفات-تصل-للكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0431.mp3","categories":["التفسير"]},{"id":397,"question":"أخ يسأل ويقول: أشرتم جزاكم الله خيرًا، على أنَّ مَن صلَّى ركعتين في الحرم الشريف فإنَّها بمئة ألف ركعةٍ، فهل مَن صلى في داخل الحرم ولو خارج الحرم -بمعنى: في حدود مكة المكرمة وحدود الحرم- يحتسب له هذا الثواب؟ وهل هو القول الصحيح في ذلك؟","title":"ما حدود الحرم التي يعمُّها الأجر المضاعف؟","answer":"الجواب: قد تنازع العلماء في ذلك: فمن قائلٍ أنه يختصُّ التَّضعيف بما حول الكعبة وفي داخل المسجد المحيط بها. والقول الثاني: أنه يعمُّ جميع أجزاء الحرم، وأن جميع الحرم يُسمَّى: المسجد الحرام.  والأدلة على هذا أظهر، فالتَّضعيف يعمُّ جميع أجزاء الحرم، هذا هو الصواب، هذا هو الأظهر.","link":"https://binbaz.org.sa/fatwas/4789/ما-حدود-الحرم-التي-يعمها-الاجر-المضاعف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0454.mp3","categories":["التفسير"]},{"id":398,"question":"ما تفسير قوله تعالى: سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ [الإسراء:1]، وقد كان الإسراء من بيت أمّ هانئ؟","title":"من أين كان الإسراء بالنبي ﷺ؟","answer":"الجواب: هذا من الأدلة على أنَّ المسجد الحرام يُطلق على جميع الحرم، هذا من أدلة القول الثاني، وأن المضاعفة تعمُّ جميع أجزاء الحرم؛ لأنَّ الله قال: سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ، وهو أُسري به من بيت أم هانئ، أو من بيته ﷺ، على الخلاف، وليس بيت أم هانئ في داخل المسجد، فعُلم بذلك أن جميع الحرم يُسمَّى: المسجد الحرام.  كذلك قوله جلَّ وعلا: هُمُ الَّذِينَ كَفَرُوا وَصَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ وَالْهَدْيَ مَعْكُوفًا أَنْ يَبْلُغَ مَحِلَّهُ [الفتح:25]، فسمَّى الحرم كله: مسجدًا حرامًا، وقوله: سَوَاءً الْعَاكِفُ فِيهِ وَالْبَادِ [الحج:25]، وصف للحرم كله.","link":"https://binbaz.org.sa/fatwas/4792/من-اين-كان-الاسراء-بالنبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0455.mp3","categories":["التفسير"]},{"id":440,"question":"أثناء المباريات الرياضية أو اللعب الحماسي ينزلق بعضُ الناس فيقع في السبِّ والشتم واللَّعن، فما حكم ذلك؟ وكيف يُتخلَّص منه؟","title":"ما حكم ما يحدث بالملاعب من سبٍّ ولعن؟","answer":"الجواب: الواجب على المؤمن وعلى اللاعب أن يتماسك أينما كان، وألا ينجرف مع الناس، وألا يتأسَّى بأهل الانحراف، بل يضبط نفسه ويُجاهدها، ولا يحمله إيذاء غيره له أو سبّ غيره له أو تثبيط غيره له أو ما أشبه ذلك على أن يسُبَّ ويلعن ويشتم ويُعوِّد لسانه ما لا ينبغي، بل يجب أن يكون عنده التَّحمل والصبر ولو أساء إليه غيره، حتى لا يُعوِّد لسانه ما لا ينبغي من الشتم والسبِّ والكذب وغير ذلك. فالإنسان قد يغضب إذا وجد من غيره ما يُغضبه، لكن يحتاج إلى تحمّلٍ، يقول النبيُّ ﷺ: ليس الشديد بالصّرعة، إنما الشديد الذي يملك نفسَه عند الغضب، ويقول عليه الصلاة والسلام: سباب المسلم فسوقٌ، وقتاله كفرٌ متَّفق على صحته، ويقول عليه الصلاة والسلام: لعن المؤمن كقتله، فالأمر عظيم، ويقول: ليس المؤمنُ بالطَّعَّان، ولا اللَّعَّان، ولا الفاحش، ولا البذيء.\nلكن إذا اقتصَّ لا حرج عليه، يقول عليه الصلاة والسلام: المستَبَّان ما قالا فعلى البادئ ما لم يعتدِ المظلوم، فإذا سبَّه إنسانٌ وردَّ عليه مثل مسبَّته فقط فلا حرج عليه، والإثم على البادئ، فإن زاد صارت الزيادة إثمها على الزائد، فإن صفح عنه وغفر كان أفضل، كما قال  في كتابه العظيم: وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ [الشورى:40]، فإذا قال لك: \"لعنك الله\"، أو: \"أخزاك الله\"، أو: \"قاتلك الله\"، فقلت له مثل قوله فقط من دون زيادةٍ فالإثم عليه، وإن صفحتَ وعفوتَ كان الأجر لك، وإن زدتَ صار إثم الزيادة عليك، قال لك: \"أخزاك الله\"، قلت: \"أخزاك الله ولعنك\"، زدته زيادة، فالزيادة إثمها عليك، قال: \"قاتلك الله\"، قلت له: \"قاتلك الله ولعنك\"، فالزيادة عليك.\nفالقصاص بقدر ما قال فقط بلا زيادةٍ: لا بأس بهذا قصاصًا، وعليه الإثم ما لم يعتدِ المظلوم، فإن اعتدى فعليه إثم عدوانه، ومَن عفا وأصلح كان أجره على الله، وصارت له العاقبة الحميدة، كما قال سبحانه: فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ[الشورى:40]، وقال النبيُّ ﷺ: ما زاد الله عبدًا بعفوٍ إلا عزًّا.","link":"https://binbaz.org.sa/fatwas/4865/ما-حكم-ما-يحدث-بالملاعب-من-سب-ولعن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0498.mp3","categories":["التفسير"]},{"id":550,"question":"الْخَبِيثَاتُ لِلْخَبِيثِينَ وَالْخَبِيثُونَ لِلْخَبِيثَاتِ يدخل تحت هذا: لا ينكح الزاني المجلود؟","title":"تفسير قوله تعالى: {الْخَبِيثَاتُ لِلْخَبِيثِينَ...}","answer":"الجواب: هذا لفظ عموم، الأغلب في هذا أنه للكفرة؛ لأن المسلم ليس بخبيث وإنْ كان عنده نقص.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6381/تفسير-قوله-تعالى-الخبيثات-للخبيثين","audio":"https://files.zadapps.info/binbaz.org.sa/maram116 - 02 - .mp3","categories":["التفسير"]},{"id":831,"question":"أخٌ يسأل -أحسن الله إليك- يقول تعالى: وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ [التوبة:105]، هذه الآية يحتجُّ بها كثيرٌ من الناس من طلاب العلم، فهل وردت في سببٍ خاصٍّ أو يجوز الاستشهاد بها في كل مناسبةٍ؟","title":"تفسير {وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ..}","answer":"الجواب: معناها واضح، يعني: يرى الله هذا في الدنيا، لكن المؤمنين والرسولﷺ إنما يراه في الآخرة، ما هو في الدنيا، الرسول ﷺ يرى عملَ الناس من زمانه الصحابة من حوله يراهم، لكن بعد موته لا يرى إلا ما يقدم يوم القيامة، فإن الأعمال تُنشر يوم القيامة ويعلمها الناس، ويُنادي عليهم في الموقف، ويعقد الدواوين أمامهم، ويقول المؤمن: هَاؤُمُ اقْرَءُوا كِتَابِيَهْ [الحاقة:19] الأعمال التي يعلمها المؤمنون يوم القيامة، ما هو في الدنيا.\nأما المؤمن: ما يعلم في الدنيا إلا مَن كان حوله حال حياته، النبي ﷺ إذا بعثه الله يوم القيامة ووقف على الحوض عليه الصلاة والسلام يسقي أمته، قال: فيُذاد أناسٌ عن حوضي، فيقول: يا ربّ، أصحابي، يا ربّ، أمتي، فيقال: إنك لا تدري ما أحدثوا بعدك، إنَّهم لم يزالوا مُرتدين على أعقابهم منذ فارقتهم، قال: فأقول كما قال العبدُ الصالح –يعني: عيسى عليه الصلاة والسلام: وَكُنْتُ عَلَيْهِمْ شَهِيدًا مَا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِي كُنْتَ أَنْتَ الرَّقِيبَ عَلَيْهِمْ وَأَنْتَ عَلَى كُلِّ شَيْءٍ شَهِيدٌ [المائدة:117].\nفالمراد بـفَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ: يراه الله في الدنيا والآخرة، ويعلمه جلَّ وعلا، والمؤمنون يرونه في الدنيا ما داموا يُشاهدون أعمالهم منذ زمانه...، والرسول ﷺ في حياته كذلك، ويراهم المؤمنون والرسول ﷺ يوم القيامة، فالآية تطبق على ما دلَّ عليه الشرعُ.","link":"https://binbaz.org.sa/fatwas/20859/تفسير-وقل-اعملوا-فسيرى-الله-عملكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0654معنى قوله تعالى وقل اعملوا فيسرى الله عملكم ورسوله والمؤمنون؟ ابن باز فتاوى المحاضرات.mp3","categories":["التفسير"]},{"id":846,"question":"طالب يسأل ويقول: فضيلة الشيخ، إني أحبك في الله، وأرجو منك أن تدعو لي بالتوفيق والثبات على هذا الدين.وسؤالي هو: إنه ورد في الآيات التي قرأها الطالبُ قوله تعالى: وَمَا يُؤْمِنُ أَكْثَرُهُمْ بِاللَّهِ إِلَّا وَهُمْ مُشْرِكُونَ [يوسف:106]، فما معنى الآية؟ وما المقصود بالشرك في الآية الكريمة؟","title":"لماذا لم ينفع المشركين إيمانُهم؟","answer":"الجواب: الشيخ: أولًا: أحبك الله الذي أحببتنا له، ونسأل الله أن يُصلح قلبك وعملك، ويُثبتنا وإياك على الهدى وسائر المستمعين.\nأما الآية: فقد أوضح العلماء معناها: ابن عباس وغيره، وأن معناها: أنهم تسألهم عمَّن خلق السماوات، مَن خلق الأرض؟ مَن خلقك؟ فيقولون: الله ربنا، الله خالقنا، الله، وهم مع هذا يعبدون الأصنام: كاللات والعُزَّى ونحو ذلك، ويستغيثون بها، ولها ينذرون، ولها يذبحون، فإيمانهم هذا هو توحيد الربوبية ينتقض ويفسُد بشركهم بالله ، لا ينفعهم، أبو جهل وأشباهه يؤمنون بأنَّ الله خالقهم ورازقهم وخالق السَّماوات والأرض، ولكن لم ينفعهم هذا؛ لأنهم أشركوا بالله بعبادة الأصنام.\nفهذا هو معنى الآية عند أهل العلم، يقول ابن عباس: تسألهم مَن خلق السماوات والأرض؟ فيقولون: الله، وهم مع هذا يعبدون غيره، فإيمانهم إيمان يفسد بشركهم، إيمانهم بأنَّ الله خالقهم ورازقهم وربهم وخالق السماوات وخالق الأرض؛ هذا إيمانٌ لو جاء معه النوعان الآخران -وهو توحيد الإلهية، وتوحيد الأسماء والصفات- لو كان معه النوعان الآخران نفعهم، لكن لما اختلَّ توحيدُهم لله بالعبادة بطل إيمانهم بالربوبية، كسائر الأعمال تبطل بالشرك: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، فجميع أنواع الإيمان ... وفي الآخرة وبغير ذلك مما أخبر الله به ورسوله يبطل بالشرك: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، قال سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ ۝ بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ [الزمر:65- 66].","link":"https://binbaz.org.sa/fatwas/20883/لماذا-لم-ينفع-المشركين-ايمانهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0678ما معنى قوله تعالى وما يؤمن أكثرهم بالله إلاَّ وهم مشركون,وما المقصود بالشرك في الآية؟ ابن باز.mp3","categories":["التفسير"]},{"id":850,"question":"ما الحقُّ في قوله تبارك وتعالى: يَوْمَ يُكْشَفُ عَنْ سَاقٍ وَيُدْعَوْنَ إِلَى السُّجُودِ فَلَا يَسْتَطِيعُونَ [القلم:42]؟","title":"تفسير قوله تعالى: {يوم يكشف عن ساق..}","answer":"الجواب: الرسول ﷺ فسَّر هذا بأنَّ المراد يوم يجيء الربُّ يوم القيامة، ويكشف للأمة عن ساقه، العلامة التي بينهم وبينه ، فإذا كشف عن ساقه عرفوه وتبعوه، وإن كانت الحرب يُقال لها: \"كشفت عن ساقٍ\" إذا اشتدَّت، لكن هذا معنى معروف لغوي، قاله أهل اللغة، ولكن في الآية الكريمة ينبغي أن يُفسَّر بما جاء في الحديث الشريف، وهو كشف الرب عن ساقه .\nوهذه من الصفات التي تليق بالله، لا يُشابه فيها خلقه جلَّ وعلا، كسائر الصِّفات فهو موصوف باليدين، بالقدم، بالعين، بالرحمة، بالرضا، بالغضب، بالسمع والبصر، كلها صفات حقّ، كلها تليق بالله جلَّ وعلا، لا يُشابه فيها خلقه . والعبد يُوصَف بذلك: يوصف بالسمع والبصر والعين، يوصف بالرضا والغضب، وباليد والقدم، ولكن ليست الصفةُ كالصفة، قال تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ [الشورى:11]، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4].\nهكذا يكشف عن ساق الطريق واحدة، كما أن يده لا تُشبه الأيدي، وسمعه لا يُشبه السمع، وهكذا علمه، وهكذا رحمته، وهكذا غضبه، وهكذا رضاه، فهكذا كشفه عن ساق، ووصفه بذلك، لا يُشبه سوق العباد وكشف العباد، بل شيء يليق بالله، لا يُشابه به خلقه ، فله الأسماء الحسنى، وله الصفات العلا على الوجه اللائق به جلَّ وعلا عند أهل السنة، لا يُشابه خلقه في شيءٍ من صفاته جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/20879/تفسير-قوله-تعالى-يوم-يكشف-عن-ساق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0674ما هو الحق في قوله تعالى يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون؟ ابن باز.mp3","categories":["التفسير"]},{"id":919,"question":"ما تفسير قول الله تعالى: إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلَائِكَةُ أَلَّا تَخَافُوا وَلَا تَحْزَنُوا وَأَبْشِرُوا بِالْجَنَّةِ الَّتِي كُنْتُمْ تُوعَدُونَ [فصلت:30]؟ ما المقصود بالاستقامة؟","title":"ما معنى {إن الذين قالوا ربنا الله ثم استقاموا}؟","answer":"الجواب: الاستقامة هي: الثبات على الحقِّ، والاستمرار عليه، يقول: ربنا الله ويستقيم، وليس مَن قال: ربي الله، ثم ترك الواجبات، وركب المحارم بالمستقيم، فالذي يقول: ربي الله، ويقول: لا إله إلا الله، وأشهد أن محمدًا رسول الله، ثم يتعاطى الفواحشَ من: الزنا والسَّرقات وظلم الناس وشرب المسكرات، هذا ليس بمستقيمٍ، هذا على خطرٍ عظيمٍ من دخول النار، ولهذا قال: ثُمَّ اسْتَقَامُوا أي: ثم استقاموا على طاعته وترك معصيته، هذه هي الاستقامة: ترك ما نهى الله عنه، وأداء ما أوجب الله.","link":"https://binbaz.org.sa/fatwas/20965/ما-معنى-ان-الذين-قالوا-ربنا-الله-ثم-استقاموا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0761ما تفسير قول الله تعالى أن الذين قالوا ربنا الله ثم استقاموا,وما المقصود بالاستقامة؟ ابن باز.mp3","categories":["التفسير"]},{"id":981,"question":"قال الله تعالى: أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ۝الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ۝لَهُمُ الْبُشْرَى فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ [يونس:62- 64]، ما معنى كلمة \"ولي\"؟ وما البُشرى التي لهم؟ وماذا يجب علينا نحن المسلمين نحو هؤلاء الأولياء؟","title":"ما معنى: {لَهُمُ الْبُشْرَى فِي الْحَيَاةِ الدُّنْيَا..}؟","answer":"الجواب: الأولياء هم المؤمنون، قال تعالى: أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ، فسَّرهم بقوله: الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ، وقال في سورة الأنفال: وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ [34].\nفأولياء الله هم أهل الإيمان من الرجال والنساء، أهل التقوى وطاعة الله ورسوله يُقال لهم: أولياء، ليسوا أهل الخُرافات من الصوفية، لا، أولياء الله هم أهل الطاعة، أهل الإيمان والتقوى، وإن كان مُزارعًا، وإن كان تاجرًا، وإن كان عبدًا مملوكًا، لا فرق في ذلك، مَن اتَّقى الله، واستقام على أمره، فهو وليّ الله، حرًّا أو عبدًا، رجلًا أو امرأةً، تاجرًا أو مُزارعًا، أو عابدًا أو طالب علمٍ، أو غير ذلك.\nأما خُرافات الصوفية الذين يتعبَّدون بالبدع، ويزعمون أنهم أولياء الله، فهذا جهلٌ صِرْفٌ وباطلٌ، وليسوا بأولياء الله إذا أعرضوا عن دينه ولم يستقيموا على أمره.\nوالواجب علينا حبُّهم في الله، الواجب على المؤمن أن يُحبَّ أولياء الله ويُواليهم، فإنَّهم أولياء الله، محبتهم في الله حقّ، يُحبهم في الله، ويدعو لهم بالثبات والتوفيق، وينتفع بعلمهم، إن كان عندهم علمٌ يستفيد من علمهم، ولهم البُشرى في الحياة الدنيا وفي الآخرة، لهم البشرى في الدنيا بالرؤيا الصَّالحة التي تُرى لهم، كما قال عليه الصلاة والسلام: ذهبت النبوةُ وبقيت المبَشِّرات، وهي الرؤيا الصَّالحة يراها المؤمنُ أو تُرى له، وهكذا البشرى من الله في كتابه العظيم، وسنة رسوله بأنَّ لهم الجنة، ولهم الكرامة، ولهم في الآخرة البشرى، عند الموت يُبَشَّرون بالجنة، وعند البعث والنُّشور وفي القبر؛ لأنهم أطاعوا الله ورسوله، واستقاموا على دين الله، فلهم البشرى في الدنيا وفي الآخرة بالجنة والكرامة والسعادة الأبدية، الله يجعلنا وإياكم منهم.","link":"https://binbaz.org.sa/fatwas/21027/ما-معنى-لهم-البشرى-في-الحياة-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0824قال تعالى الا أن أولياء الله لا خوف عليهم ولا هم يحزنون ما معنى كلمة ولي وما هي البشرى التي لهم؟.mp3","categories":["التفسير"]},{"id":1036,"question":"هل ورد في القرآن الكريم ما يدل من حيث التفسير على عذاب القبر أم دليله في حديث رسول الله ﷺ؟","title":"ما دليل عذاب القبر من القرآن الكريم؟","answer":"الجواب: جاء في الكتاب ما يدل على ذلك؛ لأنَّ الله يقول سبحانه في آل فرعون: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا [غافر:46]، هذا من عذاب القبر، تُعرض أرواحهم عليه وهم في البرزخ. وأما السنة فهي طافحة بهذا ومُتواترة بعذاب القبر.","link":"https://binbaz.org.sa/fatwas/21089/ما-دليل-عذاب-القبر-من-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0885هل ورد في القرآن الكريم على عذاب القبر؟ ابن باز فتاوى المحاضرات.mp3","categories":["التفسير"]},{"id":1062,"question":"كيف يكون التَّبديل المذكور في قوله تعالى: فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70]؟","title":"ما معنى {فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ}؟","answer":"الجواب:\nعلى ظاهره، إذا تاب المؤمنُ من سيئاته وآمن وعمل صالحًا جعل الله مكان كلِّ سيئةٍ حسنةً، فإذا كان عنده مئة سيئةٍ وتاب منها، أعطاه الله مكانها مئة حسنةٍ، بدَّل سيئاته حسنات: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ، فكل سيئةٍ الله يُعطي مكانها حسنةً؛ لتوبته منها، أتى بالحسنة وهي التوبة، فصارت محلَّ السيئة.","link":"https://binbaz.org.sa/fatwas/21121/ما-معنى-فاولىك-يبدل-الله-سيىاتهم-حسنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0917ما معنى قوله تعالى فأولئك يبدل الله سيئاتهم حسنات؟.mp3","categories":["التفسير"]},{"id":1157,"question":"أخٌ يسأل عن لفظة \"الوجه\" في قوله تبارك وتعالى: كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ [القصص:88]؟","title":"معنى ما جاء في آيات الوجه والمعية","answer":"الجواب:\nفيه فائدتان: إثبات الوجه والذات؛ لأنَّ إثبات الوجه إثباتٌ للذات من باب أوْلى، ولكن لشرف الوجه، وقصده سبحانه إثبات الوجه، عبَّر بالوجه ليعلم الناسُ أنَّ له وجهًا ويُؤمنوا بذلك.  وقال في الآية الأخرى: وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ [الرحمن:27]، ما هو معناه الوجه دون الذات، يعني: وجهه بذاته سبحانه كاملًا، فإنَّ الوجه بدون الذَّات غير صالحٍ، معناه: العدم.\nفالحاصل: أنَّ المقصود بهذا إثبات الوجه، وإثبات أمرٍ ثانٍ وهو الذات الكاملة المقدَّسة التي لا يُشبهها شيء، فإنه سبحانه له الكمال المطلق من كل الوجوه، فهو الكامل في ذاته وأسمائه وصفاته، وكما بيَّن أنَّ له يدًا، وأنَّ له سمعًا وبصرًا؛ بيَّن أنَّ له وجهًا، وأنه ذو الجلال والإكرام، وأن كلَّ شيءٍ هالكٌ إلا وجهه، يعني: إلا ذاته، بوجهه الكريم ، وبجميع صفاته: من وجهٍ وسمعٍ وبصرٍ وكلامٍ ويدٍ وقدمٍ، وغير هذا من صفاته سبحانه وتعالى.\nس: وسؤال مُرتبطٌ بما سبق، ويقول: فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ [البقرة:115]؟\nالشيخ: هذا فيه اختلافٌ: منهم مَن قال: المراد بوجهه الوجه المعروف، ومنهم مَن قال: المراد الجهة، أي: فثَمَّ جهة الله؛ لأنَّ العباد في الحقيقة إنما استقبلوا وجهَ الربِّ، وليس المقصود الكعبة، المقصود استقباله سبحانه وتعالى، والكعبة جُعلت لهم عَلَمًا لاستقباله سبحانه وتعالى، فأينما يُولِّي العبدُ فهو إلى جهة الله جلَّ وعلا؛ لأنه محيطٌ بخلقه، فوق العرش .\nوقال بعضُهم: فَثَمَّ وَجْهُ اللَّهِ يعني: جهة الله، فأنت مستقبلٌ وجهه، إذا خفيتْ عليك القبلةُ فصلِّ حيث كنتَ، اجتهد وصلِّ وأنت إلى جهة الله.\nوقال آخرون: معنى فَثَمَّ وَجْهُ اللَّهِ أنه  أمامك أينما صليتَ، كما في الحديث الصَّحيح: فإنَّ الله قِبَل وجهه إذا صلَّى، فلا ينصرف، بل يستقيم في صلاته، فإنَّ الله قبل وجهه؛ لأنه أينما كنتَ فالله قِبَل وجهك، وهو فوق العرش ، وهو قِبَل وجهك أينما كنتَ ؛ لأنه لا يُشبهه شيءٌ، وليس كمثله شيءٌ، فلا مانع من كونه قِبَل وجهك وأنت في الشام، وأنت في تركيا، وأنت في أمريكا، وأنت في المغرب، في الأقصى، إلى غير ذلك، فهو فوق العرش، فوق جميع الخلق، والمصلِّي إلى وجهه جلَّ وعلا وسبحانه وتعالى.\nس: أيضًا يسأل في قوله: وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ [الحديد:4]، هل هنا تأويل في المعية؟\nالشيخ: معناه عند أهل العلم: العلم؛ لأنه فوق العرش جلَّ وعلا عند أهل العلم جميعًا، كما حكاه ابنُ عبدالبر والطلمنكي وغيرهم من أهل العلم، وليس هذا من التأويل، بل هذا هو معناه، ليس معناه: أنه مختلطٌ بالخلق، فمَن قاله كفر، وإنما معناه: أنه فوق العرش، فوق جميع الخلق، وهو يعلمنا ويرى مكاننا، وهو أعلم بنا من أنفسنا، وأعلم بنا من جُلسائنا؛ لأنه لا تخفى عليه خافية .\nولهذا بدأ آية المعية بالعلم، وختمها بالعلم، قال تعالى: لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا [التوبة:40]، ليس معناه: أنه معهم في الغار، بل معهم بعلمه وكلاءته وتأييده ونصره: إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى [طه:46]، ليس معناه: أنه معهما عند فرعون، في بيته، وفي مجلسه، بل هو معهما بكلاءته لهما، وحفظه لهما، وتأييده لهما، ونصره لهما، ووضع الخوفَ والجبن والقلق والفزع في قلب فرعون.\nس: يقول: هل هذا تأويل؟\nالشيخ: ليس من التأويل، هذا معنى المعية.","link":"https://binbaz.org.sa/fatwas/21206/معنى-ما-جاء-في-ايات-الوجه-والمعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1002ما معنى قوله تعالى كل شيء هالك إلا وجهه وقوله تعالى وهو معكم أينما كنتم؟ ابن باز.mp3","categories":["التفسير"]},{"id":1228,"question":"قال تعالى: سَوَاءً الْعَاكِفُ فِيهِ وَالْبَادِ [الحج:25]، ما معنى هذه المُساواة؟ وفي أي شيءٍ تكون؟","title":"معنى قوله تعالى: {سَوَاءً الْعَاكِفُ فِيهِ وَالْبَادِ}","answer":"الجواب:\nعلى ظاهرها، يعني: أن البادي: الذي قدم إلى مكة، والعاكف فيه: المقيم فيها، هم سواء في وجوب احترام هذا المكان وتطهيره، وأنهم على خيرٍ عظيمٍ فيما يُؤدون من أعمالٍ وطاعات وعبادات، وأنه لا يجوز إيذاؤهم، بل يجب احترامهم، والكفّ عن أذاهم؛ لأنهم وفود بيت الله، وجيران بيته، هذا وافدٌ، وهذا جارٌ، إلا إذا اقتضت المصلحة الشرعية إبعاد أحدٍ لكونه ألحد في الحرم، أو يحصل به الأذى، أو لمصالح أخرى تقتضي أن يرجع إلى بلاده؛ لئلا يكثر المقيمون في مكة كثرةً تمنع من أن يتيسر لهم ما يقوم بحالهم ويُغنيهم عن غيرهم، فلهذا للدولة أن تأمر الحجاج بالرجوع إلى بلادهم بعد فراغهم من حجِّهم وأدائهم مناسكهم، لكن مَن أقام فيها عاكفًا أو من أهلها وأمكن بقاؤه ليتعبَّد، وليس منه أذى، هم سواء مع إخوانهم المقيمين السَّابقين.","link":"https://binbaz.org.sa/fatwas/21284/معنى-قوله-تعالى-سواء-العاكف-فيه-والباد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1027قال الله تعالى سواء العاكف فيه والباد ما معنى الآية؟ ابن ابز.mp3","categories":["التفسير"]},{"id":1241,"question":"ما معنى قوله تعالى: وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَابٍ أَلِيمٍ [الحج:25]؟","title":"معنى قوله تعالى: {وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ}","answer":"الجواب:\nعلى ظاهر الآية، الإلحاد: الميل عن الحقِّ، يُقال: \"ألحد\" إذا مال، ومنه تسمية اللَّحد في القبر؛ لأنه في الجانب الذي في جهة القبلة، سُمِّي: لحدًا، والملحدون هم الذين مالوا عن الحقِّ والصواب إلى الكفر والضَّلال، أو إلى المعصية.\nفالملحد في الحرم: هو العاصي والكافر، فمَن همَّ فيه بإلحادٍ بظلمٍ فهو متوعَّدٌ بالعذاب الأليم، ولهذا قال: وَمَنْ يُرِدْ فِيهِ، يُرِد: مُضمن معنى: يهمّ ويقصد، فإذا همَّ بالإلحاد فله الوعيد، فكيف إذا فعل؟! إذا كان مجرد الهمّ يستحق به الوعيد، وإذا فعل ذلك كان أشدَّ وأخطر وأعظم.\nوالإلحاد يشمل المعاصي وأنواع الكفر: الزاني في الحرم مُلحد، والمغتاب مُلحد، والنَّمَّام في الحرم ملحد، والذي يدعو غير الله مُلحد أعظم إلحادٍ، والذي يُرابي في الحرم مُلحد، والذي يعقّ والديه مُلحدٌ، والذي يقطع رحمه مُلحدٌ، وهكذا سائر المعاصي، لكن تتفاوت، الإلحاد يتنوع، بعضه أكبر من بعضٍ -نسأل الله العافية.\nس: هو يسأل: الضمير \"فيه\" الحرم: المسجد أو الحرم؟\nالشيخ: الحرم كله، جميع الحرم، ما هو المسجد، جميع الحرم.","link":"https://binbaz.org.sa/fatwas/21294/معنى-قوله-تعالى-ومن-يرد-فيه-بالحاد-بظلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1037ما معنى قوله تعالى ومن يرد فيه بإلحاد بظلم نذقه من عذاب أليم؟  ابن باز.mp3","categories":["التفسير"]},{"id":1259,"question":"بعض الناس يذبحون ليلة عرفة ذبيحةً ويُسمّونها: ذبيحة الأموات، فما حكمها؟","title":"حكم ما يُسمّى \"ذبيحة الأموات \" ليلة عرفة","answer":"الجواب:\nالذبيحة ليلة عرفة ما لها أصلٌ، لا نعرف لها أصلًا، لكن إذا ذبحوا من باب أنه يوم عظيم للصدقة، فعَشْر ذي الحجة كلها أيام عظيمة فاضلة، يقول النبيُّ ﷺ: ما من أيامٍ العمل الصالح فيهنَّ أحبّ إلى الله من هذه الأيام يعني: الأيام العشر، قالوا: ولا الجهاد في سبيل الله يا رسول الله؟ قال: ولا الجهاد في سبيل الله، إلا رجلٌ خرج بنفسه وماله ثم لم يرجع من ذلك بشيءٍ، هكذا جاء من حديث ابن عباسٍ عند البخاري رحمه الله.\nوفي حديث ابن عمر عند أحمد وآخرين عن النبي عليه السلام أنه قال: ما من أيام أعظم عند الله ولا أحبّ العمل فيهنَّ من هذه الأيام العشر، فأكثروا فيهنَّ من التَّهليل والتَّحميد والتَّكبير، وفي لفظٍ: ومن التَّسبيح.\nفهي أيام عظيمة، فإذا ذبح في يوم عرفة أو بعض الأيام الأخرى ليتصدق، لا لاعتقاد أنَّ هذا اليوم مخصوص، وأنها عبادة خاصَّة، لا، بل لعموم الفضل، يعني: يوم عظيم فاضل، فإذا ذبح يوم عرفة وتصدَّق، أو يوم الثامن، أو يوم السابع، أو السادس، أو في أول يومٍ، مثلما يذبح في رمضان لهذه الأيام الفاضلة ويتصدق؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/21315/حكم-ما-يسمى-ذبيحة-الاموات-ليلة-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1058بعض الناس بذبحون ليلة عرفة ويسمونها ذبيحة الأموات فما حكمها؟ ابن باز.mp3","categories":["التفسير"]},{"id":1260,"question":"كيف نُوفِّق بين قول الله تعالى: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، وبين قول النبي ﷺ: أبى الله أن يجعل لقاتل المؤمن توبةً؟","title":"هل صح حديثٌ في نفي توبة قاتل المؤمن؟","answer":"الجواب:\nالحمد لله، وصلَّى الله وسلَّم على رسول الله، وعلى آله وأصحابه.\nأما بعد: فقد أجمع العلماء رحمهم الله على أنَّ جميع الذنوب تصحّ التوبة منها، حتى الشرك الذي هو أعظم الذنوب قَبِلَ اللهُ توبةَ أهله، لما أسلموا وتابوا تاب اللهُ عليهم، قال تعالى في سورة الزمر: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]، أخبر سبحانه أنه يغفر الذنوب جميعًا –يعني: للتَّائبين- أجمع أهلُ العلم على أنَّ هذه الآية في التَّائبين، وأن الذنوب كلها تُغفر: الشرك وما دونه، حتى سبّ الأنبياء، وحتى سبّ الله، مَن تاب؛ تاب الله عليه.\nفالقتل دون ذلك، القتل دون الشرك، وقد نصَّ القرآنُ على توبة القاتل، قال تعالى: وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا  ۝  يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا  ۝  إِلَّا مَنْ تَابَ [الفرقان:68-70]، هذا نصُّ القرآن: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا، هذا يدخل فيه المشرك والقاتل والزاني بنصّ القرآن.\nأما الحديث: فهذا غير صحيحٍ: أبى الله أن يقبل التوبةَ من القاتل هذا ليس بصحيحٍ، إنما يُروى عن ابن عباس، وابن عباس في هذا غلَّطه العلماء، والصواب أنَّ القاتل مثل غيره تُقبل توبته، والقول بأنه لا تُقبل توبة القاتل قولٌ غلطٌ مرجوحٌ مخالفٌ للأدلة الصَّحيحة، وإن كان ابنُ عباسٍ  معروفَ المنزلة في العلم، وترجمان القرآن، وحبر الأمة، لكن ليس معصومًا، له أقوال خالف فيها غيرَه، والدليل مع غيره، منها هذه المسألة، وإنما قال ذلك للتَّغليظ على القاتل، ولكن التَّغليظ على القاتل ما يكون إلا بالشرع، لا بغير الشرع، فالقاتل إذا تاب؛ تاب الله عليه، كالكافر من باب أوْلى.\nلكن هنا نقطة في القاتل ينبغي التَّنبه لها، وهي: أنَّ حقَّ القتيل لا يضيع، حق الورثة يحصل لهم بالقصاص، أو بالدية إذا سمحوا بالدية، وحقّ الله سقط بالتوبة، وحقّ القتيل لا يضيع، يُرضيه الله عنه يوم القيامة، إذا تاب القاتلُ أرضَى اللهُ القتيلَ من فضله ، لا يضيع حقّه.","link":"https://binbaz.org.sa/fatwas/21314/هل-صح-حديث-في-نفي-توبة-قاتل-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1057كيف نوفق بين قوله أن الله لايغفر أن يشرك به وبين قول النبي أبى الله آن يجعل لقاتل المؤمن توبة.mp3","categories":["التفسير","شروح الحديث"]},{"id":1262,"question":"كيف نُوفق بين قول الله تعالى: وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ [المائدة:67]، وما ورد أنَّ النبي ﷺ مات من أثر السّم الذي وضعته له امرأةٌ يهوديةٌ؟ وما المقصود بعصمة الله تعالى له عليه الصلاة والسلام من الناس؟","title":"معنى قوله تعالى: {وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ}","answer":"الجواب:\nكلمة مجملة: وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ مجملة، قد عصمه سبحانه حتى بلَّغ الرسالة؛ لأن قبلها: يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ وَإِنْ لَمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ، فالمعنى: بلِّغ، والله يعصمك؛ حتى لا تضل في بلاغك.  وهو ﷺ معصومٌ فيما بلَّغه عن الله بإجماع المسلمين، وليس معصومًا أنه لا يُصيبه مرضٌ، كل الأنبياء يمرضون، وليس معصومًا ما يتعدَّى عليه أحدٌ، قد أُوذي في أحدٍ، وجُرح في أحدٍ عليه الصلاة والسلام، وكُسرت البيضة على رأسه، وآذاه المشركون في مكة، لكن يعصمه حتى يُبلِّغ رسالة ربِّه، حتى لا يكتم منها شيئًا، حتى لا يُمنع من ذلك، وقد بلَّغ الرسالة، وأدَّى الأمانة، وعصمه الله حتى بلَّغ الرسالة.  وليس معنى يَعْصِمُكَ: لا يُؤذيك أحدٌ، ولا يتعدَّى عليك أحدٌ، ولا تمرض، لا، العصمة معناها ما بيَّنتها الآيةُ الكريمة؛ لأنها بعد قوله: يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ، فقد بلَّغ الرسالة، وعصمه من الناس، فلم يُقتل ولم يمت حتى بلَّغ الرسالة عليه الصلاة والسلام، وإن تعدَّى عليه الناسُ في مكة، وإن تعدّوا عليه في أُحدٍ، وإن تعدّوا عليه في غير ذلك، لكن الله عصمه حتى بلَّغ، وقد مرض ومات مريضًا عليه الصلاة والسلام، وقد آذاه المشركون، لم يُعصم منهم، وقد آذوه يوم أحد، وآذوه في مواضع كثيرة عليه الصلاة والسلام، وآذوا الرسل.","link":"https://binbaz.org.sa/fatwas/21312/معنى-قوله-تعالى-والله-يعصمك-من-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1055كيف التوفيق بين قوله والله يعصمك من الناس وما ورد أن النبي مات من أثر سم.mp3","categories":["التفسير","شروح الحديث"]},{"id":1263,"question":"قول الله : وَلَقَدْ فَتَنَّا الَّذِينَ مِنْ قَبْلِهِمْ فَلَيَعْلَمَنَّ اللَّهُ الآية [العنكبوت:3]، وقول الله : وَمَا جَعَلْنَا الْقِبْلَةَ الَّتِي كُنْتَ عَلَيْهَا إِلَّا لِنَعْلَمَ مَنْ يَتَّبِعُ الرَّسُولَ [البقرة:143]، وقول الله : وَلِيَعْلَمَ الَّذِينَ نَافَقُوا وَقِيلَ لَهُمْ تَعَالَوْا الآية [آل عمران:167]، ما المقصود بالعلم في هذه الآيات وجزاكم الله خيرًا؟","title":"تفسير معنى \"العلم\" في مواضع من القرآن","answer":"الجواب:\nالله  يبتلي الناسَ بالسّراء والضّراء: أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ  ۝ وَلَقَدْ فَتَنَّا الَّذِينَ مِنْ قَبْلِهِمْ فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا وَلَيَعْلَمَنَّ الْكَاذِبِينَ [العنكبوت:2-3]، يبتليهم بالسراء والضراء، بالشدة والرخاء، بشرعية بعض الأحكام ثم نسخها.\nأما في الشريعة: فشرع القبلة إلى بيت المقدس، ثم نسخ ذلك، حتى يتبين مَن يتبع الحقَّ ممن يُصرُّ على الباطل، فالمسلمون تابعوا الحقَّ، وانقادوا للحقِّ، واستقبلوا القبلةَ، واليهود والنَّصارى أبوا وبقوا على ضلالهم، فاتَّضح أمرهم وباطلهم.\nوهكذا في الأحكام الأخرى، إذا شرع سبحانه حكمًا ثم نسخه؛ يتبين مَن ينقاد للحقِّ ممن لا ينقاد للحقِّ، وهكذا إذا بيَّن الحكم لشخصٍ وخفي على شخصٍ آخر؛ يتبين الصَّادق في طلب الحكم، طلب الدليل، وإزالة الجهل ممن يرضى بجهله وغفلته ويُعرض.\nوهكذا الشدّة والرخاء: بعض الناس في الرخاء يكون طيبًا، يستقيم، ولكن في الشدّة إذا جاء المرضُ أو جاء الفقرُ يضلّ عن الطريق ولا يصبر، فيجزع ويتسخط ويعصي، هذا في الشدة هلك.  وبعض الناس لا،ـ يستقيم في الشدة والرخاء، في السراء والضراء، يستقيم على طاعة الله ورسوله، ويتحمل، ولا تضله السّراء، ولا تضله الضراء، بل يستقيم في السراء ويشكر الله، وفي الضَّراء يصبر، كما قال النبيُّ ﷺ: عجبًا لأمر المؤمن، إن أمره كلَّه له خير، إن أصابته ضرَّاء صبر فكان خيرًا له، وإن أصابته سرَّاء شكر فكان خيرًا له ...، الاختبار والامتحان إما بالعلم والجهل، وإما بالشدة والرخاء، والسراء والضراء، وإما بشرع بعض الأحكام، كما في القبلة، وإما بغير هذا من أنواع الفتن: كأن يُسلط عليه بعض الناس يُؤذونه، فإما أن يصبر ويُعالج الأمور بالحكمة، وإما ألا يصبر، فالبلاء يتنوع، والسراء تتنوع.","link":"https://binbaz.org.sa/fatwas/21311/تفسير-معنى-العلم-في-مواضع-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1054ما المقصود بالعلم في هذه الآيه فليعلمن الله وقوله إلالنعلم من يتبع الرسول.mp3","categories":["التفسير"]},{"id":1266,"question":"هل قول الله تعالى عن العسل: فِيهِ شِفَاءٌ لِلنَّاسِ [النحل:69] دليلٌ على العموم أم بالإطلاق؟","title":"معنى قوله تعالى عن العسل: {فيه شفاء للناس}","answer":"الجواب:\nهذا الأصل، الأصل العموم، ولكن التجارب تُعطي تفصيلًا، التجارب والحلال وتحليل الأطباء والنظر تُعطي التفصيل، وإلا فالأصل أنه علاجٌ في كل شيءٍ، لكن الأطباء لا بد عند نظرهم وتفصيلهم لحال العسل وما يُناسبه من الأمراض، يكون لهم فيه تفصيل.  وهو علاجٌ ربانيٌّ، وهو معروفٌ مجرَّبٌ في أشياء ينفع فيها، والأطباء أعلم بالتفصيل، مجرَّبٌ في مسائل كثيرة مما تتعلق ببعض الباطنية، وتسهيل وتطهير المعدة، إلى غير ذلك، وجرَّبوه في أشياء.","link":"https://binbaz.org.sa/fatwas/21339/معنى-قوله-تعالى-عن-العسل-فيه-شفاء-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1082هل قول الله تعالى عن العسل فيه شفاء للناس دليل على العموم؟ ابن باز فتاوى.mp3","categories":["التفسير"]},{"id":1313,"question":"إذا أمرني والداي بأن أترك صُحبةً طيبةً وزملاء أخيارًا، وألا أُسافر معهم لأخذ عمرةٍ، مع العلم أنني في طريقي إلى الالتزام، فهل تجب عليَّ طاعتهم في هذه الحالة؟","title":"حكم طاعة الوالدين في ترك الصحبة الطَّيبِّة","answer":"الجواب:\nليس عليك طاعتهم فيما يضرُّك، يقول النبيُّ ﷺ: إنما الطاعة في المعروف، فالذي ينهاك عن صحبة الأخيار لا تُطعه، لا أبًا ولا غير أبٍ، ولا تُطعه في صحبه الأشرار أيضًا.  لكن تُخاطبهم بالتي هي أحسن، بالكلام الطيب: يا والدي، كذا، ويا أمي، كذا، هؤلاء طيبون، وهؤلاء أستفيد منهم، وأنتفع بهم، ويلين قلبي معهم، وأتعلم العلم، وأستفيد. ترد عليهم بالكلام الطيب، لا بالعنف والشدة، وإذا منعوك لا تُطعهم، ولكن لا تُخبرهم إذا كانوا يضرُّونك، لا تُخبرهم.  تَتَبَّع الأخيار، وسِرْ معهم، ولا تُعلمهم أنَّك ذهبتَ مع أولئك إذا كانوا يضرُّونك، ولكن لا تُطعهم إلا في الطاعة في المعروف، فإذا أمروك بصُحبة الأشرار أو أمروك بالتَّدخين أو بشرب الخمر أو بالزنا لا تُطعهم، لا تطعهم على المعصية أبدًا، لا أبًا ولا غيره، ولا سلطانًا ولا غيره، إنما الطاعة في المعروف.\nفإذا كان والداك يأمُرانك بأمرٍ لا يرضاه الله فلا تُطعهما في المعصية، ولكن خاطبهما بالتي هي أحسن، الله قال في الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، تقول: يا والدي، هداك الله، وفَّقك الله، أنا كذا، وأنا أنتفع بهؤلاء، يا والدتي كذا، تُخاطبهم بالتي هي أحسن، وبالكلام الطيب، والأسلوب الحسن.","link":"https://binbaz.org.sa/fatwas/21356/حكم-طاعة-الوالدين-في-ترك-الصحبة-الطيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1099هل يجب عليَّ طاعة الوالدين في ترك الصحبة الصالحة؟ ابن باز فتاوى.mp3","categories":["التفسير"]},{"id":1337,"question":"أنواع الصبر؟","title":"ما أنواع الصبر وحكم كل منها؟","answer":"الجواب:\nالصبر على الطاعة. ثم الصبر على المعصية. ثم الصبر على المصائب. كلها واجبة.","link":"https://binbaz.org.sa/fatwas/21428/ما-انواع-الصبر-وحكم-كل-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أنواع الصبر.mp3","categories":["التفسير"]},{"id":1338,"question":"إذا أحس الإنسان بألم وأخبر مَن حوله هل يعتبر من الجَزَع؟","title":"حكم الرُّقية والتداوي وإظهار المريض الألم","answer":"الجواب:\nلا، ما هو من الجَزَع، لا بأس، النبي ﷺ قال: واكَرْباه هذا نوع من الإخبار، وأم الطفل أخبرت أن ولدها في الاحتضار.\nس: ومن قال يجب على الشخص أن يتحدى المرض؟\nج: يعني يصبر، عبارته ما هي بزينة، ويحتسب، وإن تعالج فلا بأس، إن تعالج أو قرأ على نفسه أو قرأ عليه غيرُه فلا بأس، النبي عليه الصلاة والسلام رُقِي ورَقَى وعالج، والصحابة عالجوا، لا بأس، الحمد لله.\nس: وما ينبغي أن يقول هذه العبارة؟\nج: لا، هي عبارة سقيمة، عبارة عامية، الصبر والاحتساب طيب، لا بأس، وإن داوَى وعالج فلا بأس، العلاج سُنة؛ مستحب.","link":"https://binbaz.org.sa/fatwas/21429/حكم-الرقية-والتداوي-واظهار-المريض-الالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الصبر.mp3","categories":["التفسير"]},{"id":1342,"question":"قال تعالى: مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ وَمَنْ يُؤْمِنْ بِاللَّهِ يَهْدِ قَلْبَهُ [التغابن:11]؟","title":"تفسير {مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ..}","answer":"الجواب:\nيهدي قلبه يعني: يَشْرَح صدره للخير.  مثل ما قال علقمة بن قيس: هو الرجل تصيبه المصيبة فيعلم أنها من عند الله فيرضى ويُسَلِّم. يعني: يشرح صدره للخير، ويوفقه إلى الخير؛ حتى يطمئن قلبه، وحتى يرضى بالمصيبة، وحتى يأنس بها وينشرح صدره لها؛ يرجو ثوابها.","link":"https://binbaz.org.sa/fatwas/21433/تفسير-ما-اصاب-من-مصيبة-الا-باذن-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ وَمَنْ يُؤْمِنْ بِاللَّهِ يَهْدِ قَلْبَهُ.mp3","categories":["التفسير"]},{"id":1354,"question":"يقول الله : إِنَّ رَبَّكَ لَبِالْمِرْصَادِ [الفجر:14]؟","title":"تفسير قوله تعالى: {إِنَّ رَبَّكَ لَبِالْمِرْصَادِ}","answer":"الجواب:\nفي كل شيء، هذا عام، هو بالمرصاد لعباده، يعلم صالحهم من طالحهم، وسوف يصلون إليه وسوف يلقونه؛ فيجازيهم بأعمالهم، لا أحد يفوته.","link":"https://binbaz.org.sa/fatwas/21447/تفسير-قوله-تعالى-ان-ربك-لبالمرصاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى إِنَّ رَبَّكَ لَبِالْمِرْصَادِ.mp3","categories":["التفسير"]},{"id":1376,"question":"كفيل اشتهر بظلم العمال الذين تحت يديه، وظلمه يشمل حرمانهم من أجورهم فدعا بعضهم على هذا الكفيل وأكثروا من الدعاء، والآن هذا الكفيل يعاني من مرض خبيث نسأل الله لنا ولكم العافية، واحد من هؤلاء الذين نالوا هذا الظلم الكثير يتردد في العفو والسماح لما ناله من الظلم فما ينصح سماحتكم؟ وما هو ثواب وأجر من يعفو ويصفح في الدنيا والآخرة؟ لأن أهل الكفيل يطلبون ذلك.","title":"ما أجر العفو والصفح في الدنيا والآخرة؟","answer":"الجواب:\nفمن عفا وأصلح فجزاه الله خيرًا، العفو طيب، إذا عفو جزاهم الله خيرًا، الله يقول: وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى  [البقرة:237]، ويقول: فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ [الشورى:40]، ويقول النبي ﷺ: ما زاد الله عبدًا بعفو إلا عزًا يدعو له بالشفاء والعافية ويعطيهم حقوقهم، عليه أن يعطيه حقوقهم، لا يظلمهم، يدعون له، وعليه أن يعطوه حقوقهم؛ من أجل أن الظلم  وخيم حتى لو هو طيب عليه أن يعطيه حقوقهم وليس له أن يظلمهم؛ لأنهم فقراء وعمال فعليه أن يعطيهم حقوقهم ولو كان أصح ما في الدنيا، عليه أن يعطيهم حقوقهم.  فكيف إذا عُوقب وأصابته دعواتهم؟ فينبغي له أن يتوب إلى الله ويسأل ربه العافية ويبادر ويعطيهم حقوقهم، ولو سمحوا ولو دعوا له بالعافية، يجب أن يبادر وأن يعطيهم حقوقهم ويطلب منهم السماح؛ لأنه إذا كان قد ظلمهم بتأخير حقوقهم أو بجحد بعضها..، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21469/ما-اجر-العفو-والصفح-في-الدنيا-والاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أجر العفو والصفح في الدنيا والآخرة.mp3","categories":["التفسير"]},{"id":1377,"question":"الصواب في: وَجَاءَكُمُ النَّذِيرُ [فاطر:37]؟","title":"ما معنى قوله تعالى: {وَجَاءَكُمُ النَّذِيرُ}؟","answer":"الجواب:\nالنذير هو الرسل، الكتب والرسل.  وقال بعضهم: الشيب.  ولكن الصواب أن النُّذُر هم الرسل، ونذيرنا هو محمد عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21470/ما-معنى-قوله-تعالى-وجاءكم-النذير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التفسير.mp3","categories":["التفسير"]},{"id":1392,"question":"ما معنى قوله: لِتَشْقَى.. [طه:2]؟","title":"معنى آية {مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى}","answer":"الجواب:\nتتعب يعني، شرع الله العبادة ليستريح ويعبد الله، ويستريح بالعبادة لا يشقى بها.\nس: الربط بالكتاب العظيم مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى [طه:2] ؟\nج: لأن القرآن نزل ليستفيد المؤمن ويتعلم ويتقي ربه ويعمل بطاعة الله، ما أنزل لتكلف نفسك ما لا تطيق، أنزل لتعبد ربك بما تستطيع، فاتقوا الله ما استطعتم، ما أنزل لتعمل بضد التقوى وضد الاستطاعة.","link":"https://binbaz.org.sa/fatwas/21485/معنى-اية-ما-انزلنا-عليك-القران-لتشقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى.mp3","categories":["التفسير"]},{"id":1413,"question":"ما المقصود في الحكمة في قوله: وَاذْكُرْنَ مَا يُتْلَى فِي بُيُوتِكُنَّ مِنْ آيَاتِ اللَّهِ وَالْحِكْمَةِ.. [الأحزاب:34]؟","title":"معنى {الْحِكْمَةِ} في آية الأحزاب لبيت النبوة","answer":"الجواب:\nالحِكُمة: السُّنة.","link":"https://binbaz.org.sa/fatwas/21508/معنى-الحكمة-في-اية-الاحزاب-لبيت-النبوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالحكمة في قوله وَاذْكُرْنَ مَا يُتْلَى فِي بُيُوتِكُنَّ مِنْ آيَاتِ اللَّهِ وَالْحِكْمَةِ.mp3","categories":["التفسير"]},{"id":1529,"question":"يتيم -ابن أو ابنة- هل يكون له أجر الكفالة وهو تجب عليه نفقته؟","title":"هل يحصل أجر كفالة اليتيم لمن تجب نفقتهم؟","answer":"الجواب:\nاليتيم: مَن لا أبّ له، هذا اليتيم، وهو صغير فاقد الأب، فاليُتم له شرطان: أن يفقد الأب، وأن يكون دون البلوغ، هذا يُسمَّى يتيمًا، فيُحْسَن إليه إذا كان فقيرًا، فإذا لم يكن فقيرًا فليس هو في حاجة للناس، ويكون في حاجة إلى التربية الشرعية فقط.","link":"https://binbaz.org.sa/fatwas/21629/هل-يحصل-اجر-كفالة-اليتيم-لمن-تجب-نفقتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يحصل أجر كفالة اليتيم لمن تلزمه نفقتهم.mp3","categories":["التفسير"]},{"id":1531,"question":"بالنسبة لكفالة اليتيم: أحيانًا تصير هناك قسيمة لمدة سنة ولمدة سنوات، فهل لو كفله لمدة سنة يشمله الحديث؟","title":"هل يشمل فضلُ كفالة اليتيم الكفالة المؤقتة؟","answer":"الجواب:\nيُرجى له الخير إن شاء الله، لو ساهم في هذا الشيء يُرجى له الخير.","link":"https://binbaz.org.sa/fatwas/21631/هل-يشمل-فضل-كفالة-اليتيم-الكفالة-الموقتة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كفالة اليتيم الموقتة هل فيها أجر.mp3","categories":["التفسير"]},{"id":1536,"question":"ألا يقال: أن التسبيح باليدين أفضل من التسبيح باليد اليمنى؛ لأن التسبيح باليدين فيها أمر، والتسبيح باليد اليمنى فعل؟","title":"هل التسبيح باليدين أفضل أم باليمين وحدها؟","answer":"الجواب:\nالأمر واسع في هذا، تقول عائشة رضي الله عنها: \"كان يُعجبه التيمن في تنعله، وترجله، وطهوره، وفي شأنه كله\"، وفي حديثٍ رواه الترمذي وغيره: \"كان يعقد التسبيح باليمين\"، وأمر بعض النساء أن يعقدن بالأنامل، هذا يشمل اليدين، الأمر واسع في هذا.","link":"https://binbaz.org.sa/fatwas/21636/هل-التسبيح-باليدين-افضل-ام-باليمين-وحدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسبيح باليدين.mp3","categories":["التفسير"]},{"id":1555,"question":"قال رسول الله ﷺ: إنهن ناقصات عقل ودين، مع أن القرآن قال: إِنَّ كَيْدَكُنَّ عَظِيمٌ[يوسف:28]؟","title":"معنى ما جاء بالقرآن {إِنَّ كَيْدَكُنَّ عَظِيمٌ}","answer":"الجواب:\nهذا حكاه الله عن صاحب يوسف –العزيز-.  كيدكنَّ عظيم هذا نسبي، وكذلك قوله: إِنَّ كَيْدَ الشَّيْطَانِ كَانَ ضَعِيفًا [النساء:76] نسبي، بالنسبة إلى مَن استعان بالله، وتعوَّذ بالله، واعتصم بالله؛ فكيد الشيطان ضعيف.","link":"https://binbaz.org.sa/fatwas/21657/معنى-ما-جاء-بالقران-ان-كيدكن-عظيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث إنهن ناقصات عقل ودين وقول الله إن كيدكن عظيم.mp3","categories":["التفسير"]},{"id":1596,"question":"وَالْجَارِ ذِي الْقُرْبَى وَالْجَارِ الْجُنُبِ؟","title":"ما معنى: {وَالْجَارِ ذِي الْقُرْبَى وَالْجَارِ الْجُنُبِ}؟","answer":"الجواب:\nالجار القريب، والجار الجُنُب: البعيد يعني، يقول سبحانه: وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا وَبِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَالْجَارِ ذِي الْقُرْبَى وَالْجَارِ الْجُنُبِ [النساء:36]. الْجَارِ ذِي الْقُرْبَى له خصلتان: الجوار والقرب، يعني: تكون الصدقة فيه والهدية فيه لها جهتان: صدقة، وصلة. وَالْجَارِ الْجُنُبِ يعني: البعيد، الفقير الذي ما هو بقريب، تكون صدقة، يقول النبي ﷺ: الصدقة على ذي الرحم اثنتان: صدقة وصلة، وعلى الفقير -مَن ليس بذي رحم- صدقة.\nس: مع بُعْد القريب في الصلة يُقَدَّم على القريب في المنزل؟\nج: القريب يُقدَّم على البعيد، الصدقة على القريب صدقة وصلة، وعلى الأجنبي صدقة فقط: وَالْجَارِ ذِي الْقُرْبَى وَالْجَارِ الْجُنُبِالْجَارِ ذِي الْقُرْبَى قَبْل، هو الأول.","link":"https://binbaz.org.sa/fatwas/21700/ما-معنى-والجار-ذي-القربى-والجار-الجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله تعالى والجار ذي القربى والجار الجنب.mp3","categories":["التفسير"]},{"id":1598,"question":"ما الفضل في قوله تعالى: وَلَا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237] في آية الطلاق؟","title":"معنى قوله تعالى: {وَلَا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ}","answer":"الجواب:\nعام، يعم الفضل بالكلام، والصدقة، والإحسان، والشفاعة الطيبة بعد الفراق.\nس: بعد الفِراق الكُلّي؟\nج: لا تنسَى هي، ولا ينسَى هو.\nس: في الطلقة الأولى والثانية والثالثة؟\nج: يعني: لا ينسوا الفضل، من مكارم الأخلاق.","link":"https://binbaz.org.sa/fatwas/21702/معنى-قوله-تعالى-ولا-تنسوا-الفضل-بينكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير لفظ الفضل في قوله تعالى ولا تنسوا الفضل بينكم.mp3","categories":["التفسير"]},{"id":1601,"question":"هل صلة الرحم تكون من طريق الأم ومن طريق الأب؟","title":"هل صلة الرحم تكون من طريق الأم أم الأب؟","answer":"الجواب:\nنعم، الأعمام، والعمات، والأخوال، والخالات، سواء من طريق الأم، أو من طريق الأب، كلهم رحم.\nس: كذلك المرأة مثلًا إذا كانت مع زوجٍ، والزوج من غير الأقارب، فهل لها أن تصل رحمَها؟\nج: رحمها هي وأقاربها هي من جهة أمِّها وأبيها؟\nس: نعم.\nج: فأقارب زوجها صاروا أجانب، ما هم برحمٍ لها.\nس: مثلًا: أخوالها وأعمامها وهكذا، فالزوج مثلًا يرفض؟\nج: تصلهم من مالها لا من مال الزوج إلا بإذنه، من مالها هي.\nس: أقصد زيارتهم؟\nج: أو زيارتهم إلا بإذنه كذلك.\nس: بإذنه؟\nج: نعم.\nس: طيب، لو رفض الزوج ما عليه حرج؟\nج: إذا كان يرى المصلحة فلا بأس، والأحسن أن يُعينها على الخير، لكن إذا كان يخشى من زيارتها شرًّا فلا بأس أن يمنعها.","link":"https://binbaz.org.sa/fatwas/21705/هل-صلة-الرحم-تكون-من-طريق-الام-ام-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صلة الأرحام.mp3","categories":["التفسير"]},{"id":1604,"question":"ما الأفضل: طلب العلم، أو الجهاد في سبيل الله؟","title":"أيهما أفضل طلب العلم أو الجهاد في سبيل الله؟","answer":"الجواب:\nطلب العلم من الجهاد في سبيل الله، فيطلب العلم أولًا ثم يجاهد، فعليه أن يتفقَّه في الدِّين أولًا، إلا إذا تعيَّن الجهادُ وصار فرضَ عينٍ، وذلك إذا هجم العدو أو حضر الصَّفَّيْن، فعليه أن يُجاهد، وما دام في سعةٍ فعليه التَّفقه في الدين والتَّعلم حتى يعرف كيف يجاهد.","link":"https://binbaz.org.sa/fatwas/21708/ايهما-افضل-طلب-العلم-او-الجهاد-في-سبيل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما الأفضل طلب العلم أو الجهاد في سبيل الله.mp3","categories":["التفسير"]},{"id":1607,"question":"ما المُعتبر في صلة الرحم؟","title":"ما الأمور التي تتحقق بها صلة الرحم؟","answer":"الجواب:\nبما تيسَّر، ليس هناك شيءٌ محدودٌ، حتى ولو بالكلام الطيب إذا لم يكن عنده مالٌ، فالكلام الطيب يكفي، والذي عنده مال وهم محتاجون يصلهم بالمال.\nس: بالنسبة للمُراسلة والمكاتبة؟\nج: المراسلة من صلة الرحم إذا كانوا لا يستحقون الهجر.","link":"https://binbaz.org.sa/fatwas/21711/ما-الامور-التي-تتحقق-بها-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المعتبر في صلة الرحم.mp3","categories":["التفسير"]},{"id":1629,"question":"يقول أحد أرحامي: لا يكفيني سلامك، وإنما أن تقبل عزيمتي، ولا أستطيع أن أُلَبِّي عزيمته أو دعوته، فهل أكون واصِلًا أم قاطعًا؟","title":"حكم مَن منعه عائق من صلة الرحم","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/21734/حكم-من-منعه-عاىق-من-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلة الرحم بالسلام أو بالعزيمة وما العمل في حال وجد عائق.mp3","categories":["التفسير"]},{"id":1635,"question":"رجل أمه تأمره بطلاق زوجته، يقول: غازل زوجته، ثم تابت إلى الله، فهل أُطيع أمي؟","title":"حكم طاعة الوالدة في طلاق الزوجة","answer":"الجواب:\nإذا كانت لها أسباب: كأن تُؤذي أمه، أو سليطة اللسان، أو كذا؛ يُطلِّقها، أما إن كانت المرأةُ ما منها خلاف فيستسمح أمه بالكلام الطيب؛ لأنَّ الرسول ﷺ يقول: إنما الطاعة في المعروف، لكن يكون بالكلام الطيب، والأسلوب الحسن.","link":"https://binbaz.org.sa/fatwas/21740/حكم-طاعة-الوالدة-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم طاعة الوالدة في طلاق الزوجة.mp3","categories":["التفسير"]},{"id":1641,"question":"الخال هل هو أولى بالبِرِّ من العم؟","title":"هل يتساوى الأعمام والأخوال في حق البرّ؟","answer":"الجواب:\nالعم والخال متساويان، هذا أخو الأب، وهذا أخو الأم، أما الخالة فبمنزلة الأم، وهي أحقّ من العمَّة.","link":"https://binbaz.org.sa/fatwas/21746/هل-يتساوى-الاعمام-والاخوال-في-حق-البر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من الأولى بالبر العم أو الخال.mp3","categories":["التفسير"]},{"id":1645,"question":"إذا لم يبَرّ والديه وهما أحياء فهل ينفعه برُّهما وهما أموات؟","title":"هل ينفع البر بالوالدين بعد وفاتهما؟","answer":"الجواب:\nنعم، عليه التوبة من عقوقهما، وعليه برهما بعد موتهما، والتوبة إذا كان قد أساء إليهما في حياتهما.","link":"https://binbaz.org.sa/fatwas/21750/هل-ينفع-البر-بالوالدين-بعد-وفاتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ينفع البر بالوالدين بعد وفاتهما.mp3","categories":["التفسير"]},{"id":1648,"question":"مَن هم الأقارب الذين تجب صلتُهم؟","title":"من الأقارب الذين تجب صلتهم؟","answer":"الجواب:\nأقارب الأم والأب.\nس: فقط؟\nج: الأدنى فالأدنى، مثلما قال ﷺ لما سُئل: مَن أبرّ؟ قال: أمك، قال: ثم مَن؟ قال: أمك، قال: ثم مَن؟ قال: أمك، قال: ثم مَن؟ قال: أباك، قال: ثم مَن؟ قال: الأقرب فالأقرب، فالإخوة مُقدَّمون على عيالهم، وعيالهم مقدَّمون على الأعمام، والأعمام مقدَّمون على عيالهم، والأخوال مقدَّمون على عيالهم، وهكذا الأقرب فالأقرب، حسب التيسير: بالمال، أو بالكلام الطيب، أو بالزيارة، فكله طيب.\nس: الصَّالح والطالح منهم؟\nج: لا، الحق للصالح، والطالح من برِّه: نصيحته وتوجيهه إلى الخير وتأليفه، هذا من صلته.\nس: إذا كان فاسقًا؟\nج: من صلته أن: تدعوه إلى الله، وتُوجهه إلى الخير، وتأمره بالمعروف، وتنهاه عن المنكر، فهذا كله من صِلَتِه.","link":"https://binbaz.org.sa/fatwas/21753/من-الاقارب-الذين-تجب-صلتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأقارب الواجب صلتهم.mp3","categories":["التفسير"]},{"id":1656,"question":"إكرام الشيخ الكبير سواء كان من أهل الصلاح أو من غير أهل الصلاح؟","title":"هل إكرامُ الشيخ الكبير مُقَيَّد بصلاحه؟","answer":"الجواب:\nكُلٌّ على قَدْرِه:  أهل الصلاح لهم مقدارهم. والشيخ الكبير الذي ليس من أهل الصلاح: يُكرمه بالإحسان إليه، ودعوته إلى الله، وتعليمه، ورحمة حاله إن كان فقيرًا فيُساعده، وإن كان عاجزًا عن عصاه يُقدِّم له عصاه، ويُقدِّم له نعاله، كلّ هذا من الإحسان.","link":"https://binbaz.org.sa/fatwas/21761/هل-اكرام-الشيخ-الكبير-مقيد-بصلاحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إكرام الشيخ الكبير سواء كان من أهل الصلاح أو من غير أهل الصلاح.mp3","categories":["التفسير"]},{"id":1658,"question":"هل يُشرع للزائر أن يُخْبِر المزور أنه زاره في الله؟","title":"حكم إخبار الزائر المزور بأن زيارته في الله؟","answer":"الجواب:\nنعم، يُشْرَع له، يقول: زرتُك لأني أُحبّك في الله.","link":"https://binbaz.org.sa/fatwas/21763/حكم-اخبار-الزاىر-المزور-بان-زيارته-في-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد في زيارة أهل الخير ومُجالستهم.mp3","categories":["التفسير"]},{"id":1668,"question":"يقول الله تعالى: فَلَا تَخَافُوهُمْ وَخَافُونِ إِنْ كُنْتُمْ مُؤْمِنِينَ [آل عمران:175]، الخوف هنا؟","title":"معنى قوله تعالى: {فَلَا تَخَافُوهُمْ وَخَافُونِ}","answer":"الجواب:\nالخوف ثلاثة أقسام:\n\nالخوف الواجب.\n\nوالخوف الذي هو العبادة.\n\nوالخوف الطبيعي.\n\nخوف العبادة لا يصلح إلا لله ، ومَن خاف غير الله أن يسجر قلبه، أو أن يصدَّه عن الهدى بأسبابٍ خاصَّةٍ؛ فهذا شركٌ أكبر: فَلَا تَخْشَوُا النَّاسَ وَاخْشَوْنِ [المائدة:44]، أما إذا خافه من أجل شرِّه، واتَّقاه من أجل شرِّه، أو خاف لصوصًا وأخذ بالأسباب: كالحرس وغيره؛ فهذا لا بأس به، هذا من باب اتِّخاذ الأسباب، فلا يضر.\n\nأما إذا كان الخوفُ يحمله على ترك واجبٍ أو فعل معصيةٍ فهذا لا يجوز، كالذي يخاف من القتال، ويخاف أن يُقتل من غير عذرٍ شرعيٍّ، أو لا يأمر بالمعروف ولا ينهى عن المنكر؛ يخاف أن يُصيبه شيءٌ، هو جبن منه وضعف، وإلا ما شيء يوجب هذا الشيء، فهذا لا يجوز.\n\nأما الخوف الطبيعي وكونه يخاف المؤذيات: فيخاف الحية، ويخاف العقرب، ويتّخذ الأسباب، ويخاف اللصوص فيتخذ الحرس؛ فهذا لا بأس به.\nس: الخوف من الجِنّ؟\nج: يتعوذ بالله منه، ويأخذ بالأسباب: فيُسمِّي الله عند الدخول، ويقول: أعوذ بكلمات الله التامَّات من شرِّ ما خلق، إذا دخل المنزل، وإذا أصبح، وإذا أمسى، فيأخذ بالأسباب، مثلما يخاف من العدو فيأخذ بالأسباب.","link":"https://binbaz.org.sa/fatwas/21774/معنى-قوله-تعالى-فلا-تخافوهم-وخافون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الخوف في قوله تعالى فلا تخافوهم وخافون.mp3","categories":["التفسير"]},{"id":1680,"question":"بعض الناس إذا رأى مَن ظاهره الفقر والحاجة عند عالمٍ أو عند أميرٍ يقول: هؤلاء نصَّابون كذَّابون، فما أدري توجيهكم في هذا؟","title":"ما حكم مَن يَصُدُّ عن مساعدة الناس ويتهمهم؟","answer":"الجواب:\nلا يجوز هذا، الواجب عليه مساعدته على الخير، يقول: هذا ينبغي أن يرحم، وينبغي أن يُعطف عليه، إلا إذا كان يعرفه بالظلم، والعدوان؛ فينصحه، فإذا كان يعرف أنه غني، وأنه كذَّاب ينصحه؛ لأنه ما يجوز له السؤال، وهو مغنيه الله - نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21786/ما-حكم-من-يصد-عن-مساعدة-الناس-ويتهمهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب مساعدة أهل الخير والصلاح.mp3","categories":["التفسير"]},{"id":1695,"question":"قول الله تعالى: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ [النساء:48] هل يدخل فيه الشرك الأصغر؟","title":"ما جزاء مَن مات على الشرك الأصغر؟","answer":"الجواب:\nالظاهر - والله أعلم - أنه يدخل فيه الشرك الأصغر، لكن صاحبه لا يُخَلَّد في النار، إن دخلها لا يُخَلَّد، مثل الكبائر.","link":"https://binbaz.org.sa/fatwas/21801/ما-جزاء-من-مات-على-الشرك-الاصغر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل الشرك الأصغر في قوله تعالى إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ.mp3","categories":["التفسير"]},{"id":1697,"question":"ابن كثير رحمه الله تعالى عند قول الله : وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:69]، التَّخليد يعني: مؤقت أو ماذا؟","title":"معنى قوله تعالى: {وَيَخْلُدْ فِيهِ مُهَانًا}","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/21803/معنى-قوله-تعالى-ويخلد-فيه-مهانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الخلود في قوله تعالى وَيَخْلُدْ فِيهِ مُهَانًا.mp3","categories":["التفسير"]},{"id":1703,"question":"هنا التَّثبيت (في قوله تعالى: يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا..) يكون في السؤال عند القبر فقط أو مِن قَبْل؟","title":"معنى قوله تعالى: {يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا..}","answer":"الجواب:\nالتثبيت عنده وعند خروج الروح، فالمؤمن إذا حضره الأجلُ بُشِّر بالجنة، فتأتيه الملائكةُ تُبشره برحمة الله، فيُحب لقاء الله، ويحب الله لقاءه، والكافر بضد ذلك: يكره لقاءَ الله، ويكره اللهُ لقاءَه.\nس: قوله ﷺ في دعائه: يا مقلب القلوب ثبت قلبي على دينك هنا؟\nج: كل هذا من الدعاء الطيب كان يستعمله ﷺ اللهم يا مقلب القلوب ثبت قلبي على دينك هذا من الدعاء العظيم من جوامع الكلم، فإذا كان الرسول ﷺ يقول ذلك فغيره من باب أوْلى.","link":"https://binbaz.org.sa/fatwas/21809/معنى-قوله-تعالى-يثبت-الله-الذين-امنوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قوله تعالى يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالقَوْل الثَّابِتِ.mp3","categories":["التفسير"]},{"id":1719,"question":"ما المقصود بـ فَسَلِّمُوا عَلَى أَنْفُسِكُمْ.. [النور:61]؟","title":"معنى قوله تعالى: {فَسَلِّمُوا عَلَى أَنْفُسِكُمْ..}","answer":"الجواب:\nيعني: أهل البيت، فالذي ما فيه أحد ما يُسلِّم عليه، يعني: يُسلِّم على مَن في البيت.\nس: وإذا دخل في بيتٍ وأهله تاركين الصلاة، ففي هذا الموقف ماذا يفعل؟\nج: التاركين للصلاة ما هم بأهلٍ له، يُبْعِدهم ويُفارقهم، ليسوا بأهله.\nس: من باب صلة الرحم؟\nج: لا، يُجاهدهم حتى يُسْلِموا، ولا يبدأهم بالسلام.","link":"https://binbaz.org.sa/fatwas/21825/معنى-قوله-تعالى-فسلموا-على-انفسكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله تعالى فَسَلِّمُوا عَلَى أَنْفُسِكُمْ.mp3","categories":["التفسير"]},{"id":1790,"question":"قوله تعالى: لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ [البقرة:275] متى يكون هذا التَّخبط؟","title":"ما معنى: {كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ..}؟","answer":"الجواب:\nيوم القيامة، يقوم من قبره شبه المجنون، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21897/ما-معنى-كما-يقوم-الذي-يتخبطه-الشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قال تعالى إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ متى يكون هذا التَّخبط.mp3","categories":["التفسير"]},{"id":1791,"question":"قوله: فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ [البقرة:279]؟","title":"تفسير قوله تعالى: {فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ..}","answer":"الجواب:\nيعني: اعلموا.\nس: نوع الحرب هذه؟\nج: إشارة إلى شدة الكبيرة، وشدة المعصية، وأنهم مُحارِبُون لله، فالمعاصي حربٌ لله، لكن بالأخص الربا، نصَّ الله عليه، وإلا فالعُصاة محاربون؛ لأنَّهم عصوا وخالفوا.","link":"https://binbaz.org.sa/fatwas/21898/تفسير-قوله-تعالى-فاذنوا-بحرب-من-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ.mp3","categories":["التفسير"]},{"id":1802,"question":"تفسير الآية: وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَى [النساء:142] هل المقصود التأخر عن حضور المسجد؟","title":"معنى: {وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَى}","answer":"الجواب:\nهذا وهذا، كُسالى عن فعل الصلاة، حتى النافلة، وكُسالى عن الذهاب إلى المساجد، ما عندهم النشاط الكافي؛ لضعف الإيمان، ولهذا عندهم كسل عند أدائها في جماعةٍ، وكسل عند أدائها في البيت، ثم تركوها في البيت أيضًا.","link":"https://binbaz.org.sa/fatwas/21910/معنى-واذا-قاموا-الى-الصلاة-قاموا-كسالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله تعالى وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَى.mp3","categories":["التفسير"]},{"id":1875,"question":"إذا كان الشخص مريضًا في غيبوبةٍ، ولا يعرف مَن يزوره، هل يُزار؟","title":"هل يُزار المريض الغائب عن الوعي؟","answer":"الجواب:\nما هناك فائدة؛ لأن المقصود من الزيارة التحري عنه وسؤاله وإيناسه، وهذا ما فيه فائدة إلا الدعاء له؛ لأنك إذا زرته وهو يعقل يأنس بك، ويرى أنك تهتم به، وأما إذا لم يكن يشعر فلا فائدة للزيارة، وما يبقى إلا الدعاء له بالعافية والشفاء.\nس: الدعاء له بظهر الغيب؟\nج: بظهر الغيب لا بأس.\nس: القراءة عليه؟\nج: إذا قرأ عليه جزاه الله خيرًا، إذا قرأ عليه هذا معروف آخر غير الزيارة.","link":"https://binbaz.org.sa/fatwas/21984/هل-يزار-المريض-الغاىب-عن-الوعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيارة المريض الغائب عن الوعي.mp3","categories":["التفسير"]},{"id":1884,"question":"الآية خاصة في بني إسرائيل عامَّة: أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ أَنْفُسَكُمْ [البقرة:44]؟","title":"هل آية {أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ} خاصة أم عامة؟","answer":"الجواب:\nالحكم عام، الله ذكر لنا ذلك حتى نحذر صفاتهم الذميمة، مثلما قصَّ علينا أخبار الماضين، قصَّها علينا لنحذر الشر ونفعل الخير.","link":"https://binbaz.org.sa/fatwas/21994/هل-اية-اتامرون-الناس-بالبر-خاصة-ام-عامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قال تعالى أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ أَنْفُسَكُمْ هل الآية خاصة في بني إسرائيل أم عامَّة.mp3","categories":["التفسير"]},{"id":1886,"question":"الآية التي تقول: الَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ [النساء:37] نزلت في اليهود؟","title":"فيمن نزلت آية {الَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ..}؟","answer":"الجواب:\nفيهم وفي أشباههم، المقصود تحريم البخل، ومع البخل يأمر الناس بالبخل، البخل بالمال، والبخل بالعلم، كله.\nس: أيّهما أشد؟\nج: البخل بالعلم أشد: إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى مِنْ بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ أُوْلَئِكَ يَلْعَنُهُمُ اللَّهُ وَيَلْعَنُهُمُ اللَّاعِنُونَ [البقرة:159] نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21996/فيمن-نزلت-اية-الذين-يبخلون-ويامرون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فيمن نزلت الاية الَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ.mp3","categories":["التفسير"]},{"id":1889,"question":"قوله تعالى: إِنَّا عَرَضْنَا الْأَمَانَةَ عَلَى السَّمَاوَاتِ وَالْأَرْضِ [الأحزاب:72]؟","title":"معنى قوله تعالى: {إِنَّا عَرَضْنَا الْأَمَانَةَ..}","answer":"الجواب:\nحملها يعني، فالله جعل فيها إحساسًا: هل تحمل الأمانة أم لا؟ وإذا تكلَّم سبحانه أخذت السَّماوات منه رجفة، كل هذا من الإحساس، كذلك قول الله جل وعلا: تُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَنْ فِيهِنَّ وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ [الإسراء:44]، فهذا تسبيحٌ يليق بهم، ويناسبهم، يعلمه سبحانه، هكذا سجودهم، كله يعلمه سبحانه، والسجود يليق بهم، يعني أنهن يقلن: يا ربنا، لا تُحَمِّلنا الأمانة، ما نُريدها.","link":"https://binbaz.org.sa/fatwas/22000/معنى-قوله-تعالى-انا-عرضنا-الامانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله تعالى إِنَّا عَرَضْنَا الْأَمَانَةَ عَلَى السَّمَاوَاتِ وَالْأَرْضِ.mp3","categories":["التفسير"]},{"id":1995,"question":"الشاهد من الآية الزَّانِيَةُ وَالزَّانِي.. منع أخذ الشفاعة...","title":"معنى قوله تعالى: {وَلَا تَأْخُذْكُمْ بِهِمَا رَأْفَة}","answer":"الجواب:\nلأن الشفاعة أخذ رأفة، {تَأْخُذْكُمْ بِهِمَا رَأْفَة} يعني في ترك الحد، يشفع فيه أو ما يقيم الحد إلا الشيء الضعيف ما هو بحد شرعي، أو يُخَبِّيه على الناس... هذا نوع رأفة.\nس: موطن الدليل الشاهد في الآية؟\nالشيخ: وَلَا تَأْخُذْكُمْ بِهِمَا رَأْفَة [النور:2] الشافع أخذته رأفة.","link":"https://binbaz.org.sa/fatwas/22111/معنى-قوله-تعالى-ولا-تاخذكم-بهما-رافة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله تعالى ولا تأخذكم بهما رأفة.mp3","categories":["التفسير"]},{"id":2020,"question":"\"المُحْصَنات\" هل له مفهوم أو يدخل فيه الأبكار؟","title":"ما معنى الإحصان للرجال والنساء؟","answer":"الجواب:\nالعفيفات يعني.  أما المعروفات بالفاحشة: رَمْيُهن ما يوجب الحد، يوجب التعزير.\nس: ما هو بالمتزوجات؟\nالشيخ: لا، المحصنات العفيفات.  والمُحْصَن من الرجال هو العفيف.  ويطلق على المتزوج أيضًا والمتزوجة، لكن المراد هنا: العفيفات، المعروفات بالخير يعني.","link":"https://binbaz.org.sa/fatwas/22136/ما-معنى-الاحصان-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المقصود بالمحصنات.mp3","categories":["التفسير"]},{"id":2040,"question":"أيهما أفضل في الوقت الطويل في الفراغ: الذكر والتسبيح والتهليل أم قراءة القرآن؟","title":"ما الأفضل عمله في وقت الفراغ الطويل؟","answer":"الجواب:\nكله طيب، تارة كذا وتارة كذا، النبي تارة يسبح، وتارة يقرأ عليه الصلاة والسلام، كله طيب، كله خير، ما انشرح له صدره ونشط فيه يفعله.","link":"https://binbaz.org.sa/fatwas/22157/ما-الافضل-عمله-في-وقت-الفراغ-الطويل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استغلال وقت الفراغ الطويل.mp3","categories":["التفسير"]},{"id":2050,"question":"هل تفسير الجلالين توصون به؟ هل هو طيب؟","title":"ما الرأي في تفسير الجلالين؟ وهل يُوصى به؟","answer":"الجواب:\nطيب، ولكن فيه بعض الملاحظات، كنت كتبت عليه بعض الشيء ثم شُغلت ما كَمَّلت، فيه بعض الملاحظات لعله يتيسر تكميلها إن شاء الله.\nس: هل خرج منها شيء؟\nالشيخ: ما خرج، فيه ملاحظات في الصفات وبعض الأشياء، لعله يتيسر.\nطالب: خرج بعضها الشيخ عبدالرزاق.\nالشيخ: الشيخ عبد الرزاق كتب أشياء قليلة عن بعضها.","link":"https://binbaz.org.sa/fatwas/22168/ما-الراي-في-تفسير-الجلالين-وهل-يوصى-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رأي الشيخ بن باز في تفسير الجلالين.mp3","categories":["التفسير"]},{"id":2051,"question":"ما المراد بقوله تعالى: كَلَّا سَوْفَ تَعْلَمُونَ [التكاثر:3]؟","title":"تفسير قوله تعالى: (كَلَّا سَوْفَ تَعْلَمُونَ}","answer":"الجواب:\nمن باب الوعيد، سوف تعلمون ما فعلتم من التكاثر الذي ألهاكم عن الآخرة.","link":"https://binbaz.org.sa/fatwas/22169/تفسير-قوله-تعالى-كلا-سوف-تعلمون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى كلا سوف تعلمون.mp3","categories":["التفسير"]},{"id":2097,"question":"فَسَوْفَ يَلْقَوْنَ غَيًّا [مريم: 59]، ما معنى غَيًّا؟","title":"معنى قوله تعالى: {فَسَوْفَ يَلْقَوْنَ غَيًّا}","answer":"الجواب:\nفُسِّر الغي بالخسار والدّمار، وقيل: وادٍ في جهنم، خبيثٌ طعمه، بعيدٌ قعره -نسأل الله العافية- يعني: خسارةً وندمًا.","link":"https://binbaz.org.sa/fatwas/22215/معنى-قوله-تعالى-فسوف-يلقون-غيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى غَيًّا في قوله تعالى فَسَوْفَ يَلْقَوْنَ غَيًّا.mp3","categories":["التفسير"]},{"id":2114,"question":"ما تفسير قوله تعالى: وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا [يوسف:24] على الصحيح؟","title":"تفسير قوله تعالى: {وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا..}","answer":"الجواب:\nهمَّ بالفاحشة، وهمَّت بالفاحشة.\nس: لَوْلَا أَنْ رَأَى بُرْهَانَ رَبِّهِ [يوسف:24]؟\nج: رأى برهان ربِّه الذي منعه من الإقدام على الفاحشة.\nس: هل هو التقوى؟\nج: الله أعلم، فقد رأى ما يصدّه عن الباطل، ويُعينه على العِفَّة.","link":"https://binbaz.org.sa/fatwas/22232/تفسير-قوله-تعالى-ولقد-همت-به-وهم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الهم والبرهان في قوله تعالى وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا، وقوله لَوْلَا أَنْ رَأَى بُرْهَانَ رَبِّهِ.mp3","categories":["التفسير"]},{"id":2131,"question":"ما الصحيح في تفسير هذه الآية: وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ [الضحى:11]؟","title":"تفسير قوله تعالى: {وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ}","answer":"الجواب:\nيعني: يُثني على الله، ويقول أنه بخيرٍ، وأنه في نعمةٍ، ولا يجحد نعمةَ الله جلَّ وعلا، بل يذكر نعمة الله، وأنه بخير ونعمةٍ، على حسب ما عنده من الخير.\nس: نِعمة الدين أم الملبس؟\nج: نِعمة الدين والدنيا.\nس: أحيانًا يُنعم الله على إنسانٍ بنعمةٍ فيُكْثِر التَّحدث عنها؟\nج: إذا لم يقصد الرياء يقول: الحمد لله، أنا ممن يُحافظ على الصلاة، ممن يصوم رمضان، ممن حج البيت والحمد لله، على سبيل التَّحدث بنِعَم الله، لا على سبيل الرياء؛ فلا حرج في ذلك، أو يقول: أنا أبيع وأشتري والحمد لله وأتحرَّى الحلال، وأبتعد عن الربا والغشّ ونحو ذلك، حتى تكون في هذا نصيحةٌ لغيره.\nس: لو خاف ممن يسمعه؟\nج: المقصود أنه إذا دعت الحاجةُ والمصلحةُ إلى التَّحدث تحدث، ويقول: أعوذ بالله من شرِّ حاسدٍ إذا حسد، فلا يخاف إلا ربّه، ويتعوذ بالله من شرِّ كل ذي شرٍّ، ويتحدث بنِعم الله حتى لا يَجْحَد نعمةَ الله عليه.\nس: مَن كانت عادته أن يقول: أنا وأنا وأنا، هل يُنْصَح؟\nج: المقصود ألا يكون قصده الرياء، وإنما يتحدث بنِعم الله للشكر عليها وحثّ الناس على طلب الرزق، وأنه بخيرٍ، ولا يحتاج إلى ما عندهم.","link":"https://binbaz.org.sa/fatwas/22249/تفسير-قوله-تعالى-واما-بنعمة-ربك-فحدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ.mp3","categories":["التفسير"]},{"id":2136,"question":"أي الآيتين تنسخ الأخرى: قوله تعالى: لَا يَحِلُّ لَكَ النِّسَاءُ مِنْ بَعْدُ .. [الأحزاب:52]، وقوله تعالى: تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ .. [الأحزاب:51]؟","title":"تفسير قوله تعالي: {لَا يَحِلُّ لَكَ النِّسَاءُ مِنْ بَعْدُ}","answer":"الجواب:\nليس بينهما تعارض، يُرجي من يشاء، ويُطلق من يشاء، وقد حرَّم الله عليه النِّساء بعد التسع اللاتي كن عنده، لكن تقول عائشة رضي الله عنها أنه أُبيح له بعد ذلك.\nس: والراجح؟\nج: الله أعلم.","link":"https://binbaz.org.sa/fatwas/22254/تفسير-قوله-تعالي-لا-يحل-لك-النساء-من-بعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أي الآيتين تنسخ الأخرى قوله تعالى لَا يَحِلُّ لَكَ النِّسَاءُ مِنْ بَعْدُ ..، وقوله تعالى تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ..mp3","categories":["التفسير"]},{"id":2240,"question":"وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1].","title":"معنى قوله تعالى: {وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ}","answer":"الجواب:\nالويل: شدّة العذاب، كناية عن شدَّة العذاب: وَيْلٌ لِلْمُطَفِّفِينَ [المطففين:1]، وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ [المطففين:10]، الويل: إشارة إلى شدّة العذاب، يعني: لهم عذاب شديد. والهمَّاز اللَّمَّاز: الذي يهمز الناسَ ويلمزهم ويستهزئ بهم: تارةً بالكلام، وتارةً بالإشارة.\nس: يدخل فيه الذي يستهزئ بالدّين؟\nج: الذي يستهزئ بالدين أعظم.","link":"https://binbaz.org.sa/fatwas/22363/معنى-قوله-تعالى-ويل-لكل-همزة-لمزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالويل في قوله تعالى ويل...mp3","categories":["التفسير"]},{"id":2253,"question":"في قول الله : وَاضْرِبُوهُنَّ [النساء:34]؟","title":"ما معنى قوله تعالى: {وَاضْرِبُوهُنَّ}؟","answer":"الجواب:\nمن باب الرخصة: فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ.\nس: هل الكمال عدم الضرب؟\nج: نعم، إذا تيسر إصلاحهنَّ بغير الضرب فهو أوْلى.\nس: العفو عند عدم القدرة؟\nج: ما يُسمَّى: عفوًا، بل يُسمَّى: عجزًا، فالعفو يكون عند القُدرة، أمَّا إذا لم يملك القدرة فيُسمَّى: عجزًا.","link":"https://binbaz.org.sa/fatwas/22376/ما-معنى-قوله-تعالى-واضربوهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الضرب في قوله تعالى وَاضْرِبُوهُنَّ.mp3","categories":["التفسير"]},{"id":2279,"question":"في قوله: وَأُولِي الْأَمْرِ مِنْكُمْ [النساء:59] هل هم العلماء؟","title":"معنى قوله تعالى: {وَأُولِي الْأَمْرِ مِنْكُمْ..}","answer":"الجواب:\nنعم، العلماء والأمراء في المعروف.","link":"https://binbaz.org.sa/fatwas/22402/معنى-قوله-تعالى-واولي-الامر-منكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من هم أولياء الأمور في قوله تعالى وَأُولِي الْأَمْرِ مِنْكُمْ.mp3","categories":["التفسير"]},{"id":2290,"question":"كيف يمكن الجمعُ بين قول يوسف عليه السلام: اجْعَلْنِي عَلَى خَزَائِنِ الْأَرْضِ [يوسف:55]، وقول الرسول ﷺ: لا تسأل الإمارة؟","title":"الجمع بين موقف يوسف وعدم طلب الإمارة","answer":"الجواب:\nهذا إذا دعت المصلحةُ، وشَرْعُ مَن قبلنا شرعٌ لنا ما لم يأتِ شرعُنا بخلافه، فشرعنا جاء بالنَّهي عن تولي الخلافة، لكن ذكر العلماء أنه إذا تعيَّنت عليه واحتِيج إليه فلا بأس إذا رأى المصلحة في ذلك، لا للعلو في الأرض، ولا للفساد، ولا للطمع، ولكن لمصلحة المسلمين؛ تأسِّيًا بيوسف عليه الصلاة والسلام.\nس: وإذا رأى الرجلُ في نفسه أنه كفؤٌ لهذا؟\nج: إذا رأى المصلحة للمسلمين، وليس لنفسه هو، والأحوط أن لا يسأل.\nس: نهيه ﷺ لأبي ذرٍّ  ألا يدل على أنَّ هذا عامٌّ في الموظف الصَّغير أو الإمارة الكبيرة؟\nج: لا تُوَلَّيَنَّ مال يتيمٍ؛ هذا اليتيم، والإمارة لا تَأَمَّرَنَّ على اثنين؛ فيصير أميرًا.\nس: يعني: هو عامٌّ أم خاصٌّ فقط؟\nج: لا، ينبغي للضعيف أن يحذر حتى لا يضرَّ نفسه، ولا يضرَّ الناس.\nس: أليس كلام يوسف عليه السلام شرع مَن قبلنا؟\nج: شرعٌ لنا ما لم يأتِ شرعُنا بخلافه، وشرعنا نهى عن سؤال الإمارة.\nس: وهو شرع مَن قبلنا أليس كذلك؟\nج: شرع مَن قبلنا ما لم يأتِ شرعُنا بخلافه.","link":"https://binbaz.org.sa/fatwas/22413/الجمع-بين-موقف-يوسف-وعدم-طلب-الامارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين قوله تعالى اجْعَلْنِي عَلَى خَزَائِنِ الْأَرْضِ، وقول الرسول لا تسأل الإمارة.mp3","categories":["التفسير","شروح الحديث"]},{"id":2296,"question":"يقول الله : وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً.. [البقرة:125]، يسأل أحدُ الإخوان الموجودين من الأعاجم فيقول: ما معنى مثابةً؟","title":"معنى قوله تعالى {وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً..}","answer":"الجواب:\nيعني: يثوبون إليه جماعة بعد جماعةٍ، فيثوب إلى الشيء: يرجع إليه، كلما حجَّ يود أن يحجَّ ثانيةً، فكلما فرغ من الحج يتمنَّى أن يحجَّ حجةً أخرى، والعمرة كذلك.\nس: يقول: وجدتُ في أحد التَّفاسير –الظاهر أنها الصُّومالية: مثابةً أي: سياحةً؟\nج: لا، مثابة: يثوبون إليه، حجة بعد حجة، وعمرة بعد عمرة، ما يشبعون منه.","link":"https://binbaz.org.sa/fatwas/22420/معنى-قوله-تعالى-واذ-جعلنا-البيت-مثابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى المثابةً في قوله تعالى وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً.mp3","categories":["التفسير"]},{"id":2304,"question":"أفضل النساء على الصَّحيح: عائشة أم فاطمة أم خديجة؟","title":"مَنْ أفضل النساء على الصَّحيح؟","answer":"الجواب:\nظاهر النصوص أنَّ أفضلهنَّ عائشة؛ لقول النبي ﷺ: فضل عائشة على النِّساء كفضل الثَّريد على سائر الطعام، والمُفَضَّلات خمسٌ: عائشة، وفاطمة، وخديجة، ومريم بنت عمران، وآسيا بنت مُزاحم امرأة فرعون.","link":"https://binbaz.org.sa/fatwas/22428/من-افضل-النساء-على-الصحيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أفضل النساء على الصَّحيح.mp3","categories":["التفسير"]},{"id":2363,"question":"قوله تعالى: وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ [الإسراء:82] {مِنْ} هذه بيانية؟","title":"معنى {وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ للنَّاس}","answer":"الجواب:\nبيانية، كله شفاء، كما قال تعالى: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] قُلْ هُوَ أي: القرآن.\nس: يعني القصص التي في الرقية، يُقرأ به؟\nالشيخ: نعم؛ كله هدى.","link":"https://binbaz.org.sa/fatwas/22488/معنى-وننزل-من-القران-ما-هو-شفاء-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القرآن الكريم كله شفاء.mp3","categories":["التفسير"]},{"id":2392,"question":"هل يشهد للرجل بالصلاح بمجرد اعتياده للمساجد؟","title":"هل اعتياد المساجد يشهد لصاحبه بالصلاح؟","answer":"الجواب:\nمثل ما في الحديث هذا، وإن كان فيه لين، لكن الأدلة العامة تشهد لذلك؛ فإن الرجل المحافظ عليها لا شك أنه من خيرة الناس وأنه يشهد له بالخير؛ لأنه لا يحافظ عليها إلا مؤمن.","link":"https://binbaz.org.sa/fatwas/22517/هل-اعتياد-المساجد-يشهد-لصاحبه-بالصلاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اعتياد الرجل للمساجد هل يشهد له بالصلاح.mp3","categories":["التفسير"]},{"id":2393,"question":"التعمد للذهاب إلى المسجد الأبعد مع وجود المسجد القريب؟","title":"ما حكم من يتعمد الذهاب للمسجد الأبعد؟","answer":"الجواب:\nإذا كان مصلحة ما يخالف، إذا كان ذهابه إلى الأبعد ما يضر الأقرب ولا يسبب سوء ظن فلا بأس. أما إذا كان المسجد الأقرب يجمع الناس ويحصل به التذكير أو يحصل به موعظة لهم أو يخشونه فيحضر الناس جيرانه، يعني يكون في حضوره مصلحة؛ يصلي في الأقرب.\nس: من تتبع الصوت الجميل؟\nالشيخ: ما في بأس، مقصد صالح، مثل التراويح وأشباهها، صلاة الفجر، مقصود صالح.","link":"https://binbaz.org.sa/fatwas/22518/ما-حكم-من-يتعمد-الذهاب-للمسجد-الابعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعمد الذهاب إلى المسجد الأبعد مع وجود المسجد القريب.mp3","categories":["التفسير"]},{"id":2428,"question":"هل يُشْرَع تخصيص عمل صالح بعد الزَّوال؟","title":"هل يُشْرَع تخصيص عمل صالح بعد الزوال؟","answer":"الجواب:\nما ورد شيء إلا مثل هذا، الصلاة، إذا اشتغل بذكر الله طيّب، ذكر الله وطاعته في جميع الأوقات، لكن الصلوات أربعًا قبل الظهر هذا السُّنة، ولو صلى مائة ما في بأس، الأمر واسع من يوم تزول الشمس إلى أن يصلي العصر كله محل صلاة، لو يصلي مائة، هكذا الضحى كلها محل صلاة، لو صلى مائة وإلا مائتين ما في شيء، والليل كله محل صلاة. لكن المهم الشيء الذي حافظ عليه النبي ﷺ وندب إليه تكون العناية به أكثر، الرواتب، وهكذا أربعًا قبل العصر، وأربعًا قبل الظهر وبعد الظهر، وهكذا بين الأذانين وبين المغرب والعشاء، كلها سُنَّة، صلاة الضحى، كل هذه سُنَّة.","link":"https://binbaz.org.sa/fatwas/22556/هل-يشرع-تخصيص-عمل-صالح-بعد-الزوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشرع تخصيص عمل بعد الزوال.mp3","categories":["التفسير"]},{"id":2471,"question":"ساعة الاستجابة عند صعود الإمام المنبر؟","title":"متى ساعة الاستجابة في يوم الجمعة؟","answer":"الجواب:\nتأتي الأحاديث في هذا في الدرس الآخر إن شاء الله، وقت جلوسه على المنبر محل إجابة، إذا دعا في صلاته أو بين الخطبتين؛ هذا من أسباب الإجابة، كذلك بعد العصر إلى غروب الشمس لمن جلس ينتظر الصلاة؛ من ساعات الإجابة.","link":"https://binbaz.org.sa/fatwas/22600/متى-ساعة-الاستجابة-في-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى ساعة الاستجابة في يوم الجمعة.mp3","categories":["التفسير"]},{"id":2472,"question":"الوضوء في البيت؟","title":"هل الوضوء في البيت أفضل من غيره؟","answer":"الجواب:\nأفضل، كونه يتطهر في بيته ويستعد ويلبس أحسن ثيابه ويتطيّب؛هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/22601/هل-الوضوء-في-البيت-افضل-من-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الوضوء في البيت أفضل.mp3","categories":["التفسير"]},{"id":2479,"question":"التبكير إلى الجمعة هل هو من الأذان الأول أو من الإشراق؟","title":"متى يبدأ التبكير إلى الجمعة؟","answer":"الجواب:\nالأقرب -والله أعلم- من طلوع الشمس، هذا الأقرب.","link":"https://binbaz.org.sa/fatwas/22608/متى-يبدا-التبكير-الى-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون التبكير إلى الجمعة.mp3","categories":["التفسير"]},{"id":2529,"question":"هذا أعظم الناس شهادة عند رب العالمين (الذي قتله الدجال، كما في الحديث)؟","title":"معنى \"أعظم الناس شهادة\" في حديث الدجّال","answer":"الجواب: ظاهره أنه يموت بهذا أو بالقَتْلة التي قتله بها ثم أحياه الله، قد يكون أراد بهذا القَتْلة التي شقه نصفين، هذه قتلة، ولكن الله ردّ عليه فهو شهيد، أما إلقاؤه في النار التي يرى الناس أنها نار فتقدم أنه ماء طيب ما يضر، فلعل المراد بالشهادة التي حصلت له أولًا حين شقه نصفين، فإنها نوع من الشهادة، ثم رد الله عليه روحه، وشهد للناس أنه الدجال، وأنه ما ازداد فيه إلا بصيرة.","link":"https://binbaz.org.sa/fatwas/22660/معنى-اعظم-الناس-شهادة-في-حديث-الدجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أعظم الناس شهادة عند رب العالمين.mp3","categories":["التفسير"]},{"id":2555,"question":"فَاعْلَمْ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ ما معناها؟","title":"معنى قوله تعالى: {فَاعْلَمْ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ}","answer":"الجواب: فَاعْلَمْ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ وَاسْتَغْفِرْ لِذَنْبِكَ [محمد:19] يأمر نبيه أن يعلم أنه لا معبود حق إلا الله، يعني: اعلم يا محمد وعَلِّم الناس، كما قال تعالى: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62] المعنى: اعلم ذلك يقينًا وعَلِّم الناس، مثل ما قال جل وعلا: وَوَجَدَكَ ضَالًّا فَهَدَى [الضحى:7] كان على أمر الجاهلية فهداه الله وعَلّمه وأوحى إليه حتى صار قائد المؤمنين إلى الجنة ومُنْذر الكفار من عذاب الله ، وصار أفضل الناس بهذا الوحي العظيم والعبادة العظيمة.","link":"https://binbaz.org.sa/fatwas/22687/معنى-قوله-تعالى-فاعلم-انه-لا-اله-الا-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الآية فَاعْلَمْ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ..mp3","categories":["التفسير"]},{"id":2558,"question":"من هو المعنيّ بقوله تعالى قَالَ الَّذِي عِنْدَهُ عِلْمٌ مِنَ الْكِتَابِ أَنَا آتِيكَ بِهِ قَبْلَ أَنْ يَرْتَدَّ إِلَيْكَ طَرْفُكَ؟","title":"من المراد في آية: {الَّذِي عِنْدَهُ عِلْمٌ مِنَ الْكِتَابِ}","answer":"الجواب: الله أعلم؛ لأن الله سَخَّر لسليمان الشياطين من الجن والإنس جميعًا، سَخَّرهم له، والظاهر أنه من الجن، ما هو من الإنس.","link":"https://binbaz.org.sa/fatwas/22690/من-المراد-في-اية-الذي-عنده-علم-من-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من هو المعنيّ بقوله تعالى قَالَ الَّذِي عِنْدَهُ عِلْمٌ مِنَ الْكِتَابِ.mp3","categories":["التفسير"]},{"id":2607,"question":"كيف يمكن الجمع بين قوله: إِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ [التحريم:7] وحديث النبي ﷺ: لا يدخل الجنة أحَدُكُم بعمله قالوا: ولا أنت يا رسول الله؟ قال: ولا أنا إلا أن يتغمدني الله برحمته.","title":"معنى ودلالة {إِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ}","answer":"الجواب: هذه باءُ العِوَض، المَنْفِيَة باءُ العِوَض، أما المُثْبَتَة فباءُ السبب، يدخلون الجنة بأسباب أعمالهم، والمُعَوَّل فيها على عفو الله ورحمته جل وعلا، لا يدخل الجنة أحَدُكُم بعمله -يعني بِعِوَض- لأن عمله كله ما يقابل نعمة من نعم الله عليه سبحانه وتعالى في صحته وعافيته وما رزقه الله في الدنيا، فالأعمال الصالحة أسباب، هو الذي جعلها أسبابًا وأوجب بها الرحمة، هو ربنا ، فضلًا منه وإحسانًا جل وعلا، ولكن يتغَمَّدُهم الله برحمته بأسباب أعمالهم الصالحة.","link":"https://binbaz.org.sa/fatwas/22742/معنى-ودلالة-انما-تجزون-ما-كنتم-تعملون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين قوله تعالى إِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ، وحديث لا يدخل الجنة أحدكم بعمله..mp3","categories":["شروح الحديث","التفسير"]},{"id":2617,"question":"قوله : وَفِي الرِّقَابِ [البقرة:177] يدخل فيه الإعتاق؟","title":"هل قوله تعالى {وَفِي الرِّقَابِ} يشمل الإعتاق؟","answer":"الجواب: يعني: الصدقة، يعني: الزكاة، في عتق الرقاب.\nس: ويدخل فيه معاونة المُكاتَب؟\nج: نعم، يدخل فيه.","link":"https://binbaz.org.sa/fatwas/22752/هل-قوله-تعالى-وفي-الرقاب-يشمل-الاعتاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل الإعتاق في قوله تعالى وَفِي الرِّقَابِ.mp3","categories":["التفسير"]},{"id":2673,"question":"مَن يفْطِر ويتعشّى قبل صلاة المغرب؟","title":"حكم مَنْ يُفْطِر ويتعشّى قبل صلاة المغرب","answer":"الجواب: إذا كان الجماعة ما بتفوت، يُمْدِيه؛ لا بأس، أو يؤخِّر العَشاء؛ يُفطر ويروح يصلي مع الناس ثم يرجع للعشاء.\nس: لكن هل الأفضل تأخير العشاء؟\nالشيخ: إذا كانت الصلاة تفوته يؤخِّر العَشَاء حتى يصلي مع الجماعة، أما إذا كان جماعته يصيّفون، يٌمْدِيه يتعشّى؛ يتعشّى، الحمد لله.","link":"https://binbaz.org.sa/fatwas/22811/حكم-من-يفطر-ويتعشى-قبل-صلاة-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يفطر ويتعشى قبل صلاة المغرب.mp3","categories":["التفسير"]},{"id":2721,"question":"إن كان الجهاد فرض عين فهل يُقَدَّم على بر الوالدين؟","title":"هل يُقَدَّم الجهاد المفروض على بر الوالدين؟","answer":"الجواب: إذا كان فرض عين قُدِّم على الجميع، مثل: هجم العدو على البلد، أو كان بين الصفين، أو استنفره الإمام؛ هذا فرض عين في هذه الأحوال الثلاثة:  إذا هجم العدو البلد؛ وجب على الجميع الجهاد لدفعه حسب الطاقة. أو استنفرهم الإمام؛ وجب عليهم الجهاد. أو حضر الصفين؛ لا ينحرف، لا يُوَلِّي الأدبار.","link":"https://binbaz.org.sa/fatwas/22865/هل-يقدم-الجهاد-المفروض-على-بر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقدم الجهاد على بر الوالدين.mp3","categories":["التفسير"]},{"id":2728,"question":"مَنْ قُتل في معركة هل يسمى شهيدًا؟","title":"هل يُسمّى شهيدًا كل مَنْ قُتل في معركة؟","answer":"الجواب: سواء قتل في معركة وإلا خارج المعركة يسمى شهيدًا، إذا قتل في سبيل الله ولو خارج المعركة ولو عاش يومين ثلاث أربعة ثم مات فهو شهيد، لكن إذا قتل في المعركة لا يُغَسّل ولا يُصلى عليه، أما إذا عاش تأخر ثم مات يُغَسّل ويُصلى عليه.\nس: لكن يُقال: الشهيد فلان؟\nالشيخ: نعم، الشهيد فلان، شهداء بالحكم الشرعي، أما في الآخرة أمرهم إلى الله، لكن في الحكم الشرعي شهداء لا يُغِسّلون ولا يُصلى عليهم، وهكذا المقتول ظُلمًا يسمى شهيدًا وأمره إلى الله .","link":"https://binbaz.org.sa/fatwas/22874/هل-يسمى-شهيدا-كل-من-قتل-في-معركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من قتل في معركة هل يسمى شهيدا.mp3","categories":["التفسير"]},{"id":2729,"question":"الأفضل: العبادات البدنية كالصلاة، أم الجهاد؟","title":"هل الجهاد أفضل مِن سائر العبادات البدنية؟","answer":"الجواب: الجهاد أفضل، أفضل التطوع الجهاد؛ لما فيه من تعريض النفس والمال. والعلم مِن الجهاد، هذا ما هو بتطوع، هذا واجب، العلم، التعلم، واجب.\nس: العلم الكفائي؟\nالشيخ: تعلم العلم الذي يعرف به دينه ويعرف ما أوجب الله عليه وما حرم عليه، هذا واجب، أما الزيادة فالجهاد أفضل.","link":"https://binbaz.org.sa/fatwas/22875/هل-الجهاد-افضل-من-ساىر-العبادات-البدنية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجهاد أفضل أم العبادات البدنية.mp3","categories":["التفسير"]},{"id":2734,"question":"فضل الشهيد هل يدخل فيه الغريق؟","title":"هل يدخل الغريق في فضل الشهيد؟","answer":"الجواب: صاحب الغرق شهيد، صاحب الهدم والغرق شهادة.\nس: لكن دون الشهادتين.....؟\nالشيخ: الله أعلم، أمرهم إلى الله، هم شهداء، الذي يموت بالغَرَق أو بالحَرَق أو بالهدم أو بذات الجنب مثل ما قال ﷺ: الشهداء عند الله خمسة ذكر منهم الشهيد في سبيل الله، وجاء في رواية أخرى زيادة على ذلك.\nس: يشترط أن يكون مقاتلًا؟\nالشيخ: ولو ما قاتل، إذا خرج في الجهاد ومات في سبيل الله يُرجى له الشهادة، فضل الشهادة؛ لأنه قد عزم على الجهاد وأعدّ نفسه للجهاد.\nس: من عزم على الجهاد ثم مات والجيش في الطريق مرض ومات؟\nالشيخ: يُرجى له على نيته إن شاء الله.","link":"https://binbaz.org.sa/fatwas/22882/هل-يدخل-الغريق-في-فضل-الشهيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل الغريق في فضل الشهيد.mp3","categories":["التفسير"]},{"id":2746,"question":"قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ [النساء:59] هل المقصود: الأمراء والعلماء والمسؤول في العمل مثلًا الرئيس العام أو المدير العام...؟","title":"ما معنى {وَأُولِي الْأَمْرِ}؟ ومَن تشمل؟","answer":"الجواب: الآية تَعُمُّ على الصحيح، تَعُمُّ أولي الأمر من الأمراء وأولي الأمر من العلماء، يجب أن يُطاعوا في المعروف كلهم، لا في المعاصي.\nس: والرئيس العام أو المدير المسؤول؟\nالشيخ: من أولي الأمر، يُطاع في المعروف.","link":"https://binbaz.org.sa/fatwas/22894/ما-معنى-واولي-الامر-ومن-تشمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من هم أولي الأمر في قوله تعالى أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ.mp3","categories":["التفسير"]},{"id":2761,"question":"الإنفاق على الحجاج... كالإطعام وغيرها من الحاجات... هل يكون في سبيل الله...؟","title":"هل الإنفاق على الحجاج يُعَدُّ في سبيل الله؟","answer":"الجواب: في سبيل الله، يعني في طاعة الله، يكون ما هو مثل الجهاد، قال بعض أهل العلم: الحج في سبيل الله؛ لأنه يروى عن النبي ﷺ أن امرءًا من الأنصار أوصى بجمل في سبيل الله، فقال لزوجته: حجي عليه فإن الحج في سبيل الله. يُرجي له الخير العظيم.\nس:كذلك يزوّده ببعض الكتيبات أو الأشرطة النافعة يشمل هذا، أحسن الله إليك؟\nالشيخ: نعم؛ يُرجى فيه الخير؛ لأنه من باب البلاغ، من باب التبليغ، الشريط والخطبة والمكاتبة كلها تبليغ.","link":"https://binbaz.org.sa/fatwas/22909/هل-الانفاق-على-الحجاج-يعد-في-سبيل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنفاق على الحجاج هل يكون في سبيل الله.mp3","categories":["التفسير"]},{"id":2777,"question":"من مات بكارثة زلزال؟","title":"هل يدخل موتى الزلزال في \"صاحب الهدم\"؟","answer":"الجواب: الغالب يكون هدم، أصابه الهدم، أما صوت الزلزلة ما ورد في هذا شيء، صوت الزلزلة وصوت الرعد إذا ارتاع، والصاعقة. أما إذا سقط عليه السقف فهذا من جنس صاحب الهدم، سواء سقط عليه السقف أو الجدار فهذا يدخل في قوله: صاحب الهدم، أو هذا الذي أصابه دعسة السيارة، يتصادمون، أو تنقلب.","link":"https://binbaz.org.sa/fatwas/22925/هل-يدخل-موتى-الزلزال-في-صاحب-الهدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من مات بكارثة زلزال هل يكون من الهدم.mp3","categories":["التفسير"]},{"id":2778,"question":"هل الموت بمرض السرطان يعتبر مثل الطاعون؟","title":"هل الموت بالسرطان يدخل في المبطون؟","answer":"الجواب: لا، مرض السرطان غير.\nس: ما يقاس على المبطون؟\nالشيخ: يُرجَى له، لكن الطاعون مرض غير هذا، بُثُورٌ بعضُها في الراحة، وبعضها في..... ، بثور تشتعل عليها حارة ثم يموت بإذن الله.\nس: المبطون هو ذات الجنب؟\nالشيخ: المبطون، لا، بالنسبة لمرض البطن، ذات الجنب: مرض بالجنب، مرض يصيبه في جنبه.\nس: أي مرض في البطن؟\nالشيخ: ظاهر الحديث المبطون، ظاهره كل مرض يسبب موته وهو في البطن شهادة.","link":"https://binbaz.org.sa/fatwas/22926/هل-الموت-بالسرطان-يدخل-في-المبطون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الموت بمرض السرطان يقاس على المبطون.mp3","categories":["التفسير"]},{"id":2788,"question":"هل الحريق شهيد؟","title":"هل يدخل في الشهادة موتُ الحريق والنفاس؟","answer":"الجواب: جاء في بعض الروايات أنه شهيد، من مات بالحرق، ومن ماتت في النفاس جاء أيضًا.","link":"https://binbaz.org.sa/fatwas/22936/هل-يدخل-في-الشهادة-موت-الحريق-والنفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الحريق شهيد.mp3","categories":["التفسير"]},{"id":2825,"question":"بالنسبة للصدقة الجارية هل تنقطع بانقطاع السبب كانقطاع الماء عن البئر مثلًا؟ وكذلك العلم الذي يُنتفع به هل ينقطع بانقطاع السبب؟","title":"هل ينقطع أجر الصدقة والعلم بانقطاع السبب؟","answer":"الجواب: ما دام يُنتفع به فالأجر باق، وإذا انقطعت انقطع.\nس: ما يثبت الأجر؟\nالشيخ: ينقطع بانقطاع السبب.\nس: حديث الرسول ﷺ الذي قال: إذا مات الإنسان انقطع عمله إلا من ثلاث: صدقة جارية أو علم ينتفع به هل الصدقة الجارية والعلم الذي ينتفع به سواء، أو بينهما فرق؟\nالشيخ: الله أعلم، له أجره وبس، له أجره عند الله.","link":"https://binbaz.org.sa/fatwas/22974/هل-ينقطع-اجر-الصدقة-والعلم-بانقطاع-السبب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تنقطع الصدقة الجارية أو العلم ينتفع به بانقطاع السبب.mp3","categories":["التفسير"]},{"id":2835,"question":"هنا تعليق أشكل عليّ في قوله: فَلَمَّا آتَاهُمَا صَالِحًا جَعَلَا لَهُ شُرَكَاءَ فِيمَا آتَاهُمَا [الأعراف:190] قال: هنا يقال أن الشرك وقع منهما في الطاعة لا في العبادة، وأقول: الصحيح أن الشرك إنما وقع من حواء فقط دون آدم ؛ لأنه نبي وخليفة، والنبي لا يتأتى منه مثل هذا، والعرب تخاطب الواحد بالتثنية، وذلك شائع ذائع في لغتهم ومحاورتهم؟","title":"تفسير: {فَلَمَّا آتَاهُمَا صَالِحًا جَعَلَا لَهُ شُرَكَاءَ..}","answer":"الجواب: لا، غلط هذا، جعلا له نسبة إلى الشخصين، القول هذا غلط لآدم وحواء، ولكن هذا من الشرك الأصغر، سمعا في طاعته لمّا غلب عليهما حُبُّ الولد فسمياه عبدالحارث، هذا هو الصواب.\nس: وهنا قال في سطر: صرح بذلك في تفسير فتح البيان فارتفع الإشكال الذي حير العلماء في كل زمان؟\nالشيخ: ما في تحيير.","link":"https://binbaz.org.sa/fatwas/22984/تفسير-فلما-اتاهما-صالحا-جعلا-له-شركاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى فَلَمَّا آتَاهُمَا صَالِحًا جَعَلَا لَهُ شُرَكَاءَ فِيمَا آتَاهُمَا.mp3","categories":["التفسير"]},{"id":2876,"question":"إذا أتى قبل الأذان وأتى المؤذن: الأفضل أني أقرأ القرآن أو أني آتي بالسُّنة؟","title":"ماذا يُسَنُّ لمن حضر قبل الأذان وبعده؟","answer":"الجواب: تأتي بالراتبة؛ مثل الظهر أربع قبلها، وبين كل أذانين صلاة، فإذا أذّن فالسنة للحاضرين أن يأتوا بركعتين.\nس: ما في سنة راتبة مثلًا بعد (أذان) المغرب؟\nالشيخ: يأتي بركعتين ولَوْ، النبي ﷺ قال: بين كل أذانين صلاة، بين كل أذانين صلاة، وقال: صلوا قبل المغرب، صلوا قبل المغرب، ثم قال: لمن شاء كل هذا سنة بين الأذانين؛ المغرب والعشاء والعصر كذلك، وأما الظهر راتبة قبلها، والعصر يستحب قبلها أربع، والفجر راتبة قبلها بين الأذانين.","link":"https://binbaz.org.sa/fatwas/23031/ماذا-يسن-لمن-حضر-قبل-الاذان-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حضر قبل الأذان فهل يقرأ قرآن أو يأتي بالسنة.mp3","categories":["التفسير"]},{"id":2886,"question":"هل الأفضل الأذكار الواردة بعد صلاة الصبح أم قراءة القرآن؟","title":"هل الأفضل بعد الفجر الذِّكْر أم التلاوة؟","answer":"الجواب: الأفضل بعد السلام ما بَيَّنه النبي ﷺ، سنته عليه الصلاة والسلام إذا سلَّم الإمام يقول: أستغفر الله، ثلاثًا، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، وهكذا المأموم، ثم يأتي بالأذكار الشرعية.","link":"https://binbaz.org.sa/fatwas/23041/هل-الافضل-بعد-الفجر-الذكر-ام-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعد صلاة الصبح بعد صلاة الصبح أم قراءة القرآن.mp3","categories":["التفسير"]},{"id":2891,"question":"حديث أبي هريرة أن الأغنياء أفضل من الفقراء؟","title":"من الأفضل: الغني الشاكر أم الفقير الصابر؟","answer":"الجواب: إذا عملوا عمل الفقراء وزادوا عليهم بالصدقات، على حسب أعمالهم، كلما زادت الأعمال الصالحة زاد الفضل، فالغني الشاكر أفضل من الفقير الصابر؛ لأن عنده القدرة على المعاصي وعافاه الله منها واستعمل الطاعات.","link":"https://binbaz.org.sa/fatwas/23046/من-الافضل-الغني-الشاكر-ام-الفقير-الصابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأغنياء أفضل أم الفقراء.mp3","categories":["التفسير"]},{"id":2897,"question":"أرْذَل العُمُرِ؟","title":"ما معنى \"أرْذَل العُمُرِ\" في الحديث؟","answer":"الجواب: الهَرَم؛ يُخَرِّف، ما عاد يحسن.\nس: ما يقال إن أرذل العمر ما كان في معصية الله؟\nالشيخ: لا، أرذل العمر هو آخِرُه لِكَيْلَا يَعْلَمَ مِنْ بَعْدِ عِلْمٍ شَيْئًا [الحج:5] يصير تَعَبًا... ومشقة على أهله وعلى غيرهم.","link":"https://binbaz.org.sa/fatwas/23052/ما-معنى-ارذل-العمر-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو أرذل العمر.mp3","categories":["التفسير"]},{"id":2924,"question":"حديث أبي الدرداء الذي ورد في تفضيل ذكر الله  على كثير من الأعمال، على ماذا يُحمل، ورد في بعض الأحاديث تفضيل الجهاد؟","title":"هل ذِكْرُ الله أفضل من سائر أنواع العبادة؟","answer":"الجواب: مثل ما قال ابن القيم، على من فعل تلك الأعمال غافلًا عن ذكر الله، من فعلها غافلًا عن ذكر الله فالذاكر أفضل منه، ومن فعلها مع ذكر الله ومع الإخلاص لله؛ فهو أفضل؛ لأنه جمع بين الخصلتين.","link":"https://binbaz.org.sa/fatwas/23080/هل-ذكر-الله-افضل-من-ساىر-انواع-العبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفضيل ذكر الله على كثير من الأعمال.mp3","categories":["التفسير"]},{"id":2995,"question":"ابن القيم يقول: يستحب للإنسان أن يبدأ بمدافعة الخطرات السيئة؛ لئلا تتحول إلى هَمٍّ؟","title":"لماذا يُستحب للمؤمن مدافعة الخَطَرَات السيئة؟","answer":"الجواب: هذا واجب، مدافعتها واجبة، والتعوُّذ بالله من الشيطان؛ حتى لا تَسْتَحْكِم عليه.","link":"https://binbaz.org.sa/fatwas/23152/لماذا-يستحب-للمومن-مدافعة-الخطرات-السيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مدافعة الخطرات السيئة.mp3","categories":["التفسير"]},{"id":2998,"question":"قوله تعالى: مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ [ق:18]؟","title":"تفسير {مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ}","answer":"الجواب: يعني من الملائكة.\nس: معنى هذا أن المَلَك يكتب كل شيء؟\nالشيخ: نعم يُكتب كل شيء، لكن يُؤاخذ على ما فيه الخير والشر، إما حسنةٌ يُؤجر، وإما سيئةٌ يأثم، وما سوى ذلك يُلقى.","link":"https://binbaz.org.sa/fatwas/23156/تفسير-ما-يلفظ-من-قول-الا-لديه-رقيب-عتيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ.mp3","categories":["التفسير"]},{"id":3060,"question":"قول الله تعالى: وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ..  [الحجرات:13]؟","title":"معنى قوله تعالى: {وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ..}","answer":"الجواب: لِتَعَارَفُوا.. ما قال لِيَنِمّ بعضُكم على بعض، للتعارف، تقول: سالم ابن كذا، ومحمد من كذا، من قحطان، من كذا، من بريدة.","link":"https://binbaz.org.sa/fatwas/23220/معنى-قوله-تعالى-وجعلناكم-شعوبا-وقباىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى وجعلناكم شعوبا وقبائل.mp3","categories":["التفسير"]},{"id":3091,"question":"في قوله تعالى في سورة الجن: وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ فَإِنَّ لَهُ نَارَ جَهَنَّمَ خَالِدِينَ فِيهَا أَبَدًا [الجن:23] الخلود هنا -غفر الله لك- بعض الذين يسألون يقولون: الغِيبة والنميمة تدخل تحت هذا؟","title":"معنى الوعيد في آية الجن لمن عصى الله؟","answer":"الجواب: هذا عام، من باب الوعيد مع الإيمان أن من مات على التوحيد لا يَخْلُد في النار وإن دخلها، وهو تحت المشيئة؛ لأن النصوص يفسر بعضها بعضًا، مثل ما جاء الخلود في الزاني والقاتل، لكن خلودهم فيها إذا خلدوا لا يكون دائمًا، بل لهم أمَدٌ يخرجون فيه إلى الجنة، ولا يخلد في النار إلا الكفار.\nس: من باب الترهيب والتحذير؟\nالشيخ: من باب الترهيب والتحذير والوعيد.","link":"https://binbaz.org.sa/fatwas/23251/معنى-الوعيد-في-اية-الجن-لمن-عصى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالخلود في قوله تعالى وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ فَإِنَّ لَهُ نَارَ جَهَنَّمَ خَالِدِينَ فِيهَا أَبَدًا.mp3","categories":["التفسير"]},{"id":3141,"question":"مَنْ يُنكر على مَنْ يسمع الأغاني والمجلات والنظر إلى النساء يقول: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31]؟","title":"معنى الآية {إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ..}","answer":"الجواب: ما هو معناها إباحة المعاصي، معناها: أن اجتناب الكبائر من أسباب تكفير الصغائر.  والكبائر في تحديدها خلاف بين العلماء: ما هي الكبيرة؟ فالواجب الحذر من جميع المعاصي، الرسول ﷺ قال: ما نهيتكم عنه فاجتنبوه، وما أمرتكم فأتوا منه ما استطعتم، والله يقول: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا.. [الحشر:7]، فالواجب الانتهاء عما نهى الله عنه ورسوله، صغائر أو كبائر، جميع الذنوب، جميع المعاصي يجب الحذر منها.\nس: وإذا رددنا عليه وقلنا: لا صغيرة مع الإصرار وتكون في حكم الكبيرة؟\nالشيخ: كما قال ابن عباس، وأيضًا ما نهى الله عنه يجب أن يُجتنب، وأمر بأن نَجتنب ما نهانا عنه وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا.. [الحشر:7].","link":"https://binbaz.org.sa/fatwas/23303/معنى-الاية-ان-تجتنبوا-كباىر-ما-تنهون-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله تعالى إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ.mp3","categories":["التفسير"]},{"id":3258,"question":"أيهما أشد: لعنة الله أو غضب الله؟","title":"أيهما أشد: لعنة الله أو غضب الله؟","answer":"الجواب: كلها متقابلة، والمعنى: الطرد والإبعاد عن مظان الرحمة، الطرد عن رحمة الله، نسأل الله العافية، قال الله تعالى: إِنَّ اللَّهَ لَعَنَ الْكَافِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا [الأحزاب:64]، وقال: غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ [الفاتحة:7] فهم ملعونون ومغضوب عليهم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23422/ايهما-اشد-لعنة-الله-او-غضب-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهم أشد لعنة الله أو غضب الله.mp3","categories":["التفسير","مسائل متفرقة في العقيدة"]},{"id":3304,"question":"باب الدعاء، باب دعاؤكم إيمانكم؟","title":"معنى: {قُلْ مَا يَعْبَأُ بِكُمْ رَبِّي لَوْلَا دُعَاؤُكُمْ}","answer":"الجواب: قُلْ مَا يَعْبَأُ بِكُمْ رَبِّي لَوْلَا دُعَاؤُكُمْ [الفرقان: 77] في آية الفرقان يعني إيمانكم.\nس: يعني تفسير الدعاء بالإيمان؟\nالشيخ: هذا مراده، نعم.","link":"https://binbaz.org.sa/fatwas/23469/معنى-قل-ما-يعبا-بكم-ربي-لولا-دعاوكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير الدعاء بالإيمان.mp3","categories":["التفسير"]},{"id":3428,"question":"من قام في صلاة التراويح إلى ذلك (ثالثة بعد الثانية)؟","title":"حكم الزيادة فوق اثنتين في التراويح والقيام","answer":"الجواب: ينبه، ويجلس، ويسجد للسهو.\nس: لو أكمل؟\nالشيخ: لا الأفضل مثل ما قال النبي ﷺ: صلاة الليل مثنى مثنى، السنة له أن يجلس ويسجد للسهو، لقوله ﷺ: مثنى مثنى كما في الصحيحين.\nس: يجب أو الأفضل هذا؟\nالشيخ: والله الأحوط هو هذا، كثير من أهل العلم يقولون: يجوز له أن يصلي أربعًا، وبعضهم يقول: يتم أربعًا، ولكن ظاهر السنة هو هذا، ظاهر السنة أنه يصلي، يجلس ويسجد للسهو؛ لأن هذا هو المشروع له، أما كونه يجوز يصلى أربعًا هذا محل خلاف.\nس: في الليل فيه خلاف؟\nالشيخ: فيه خلاف.\nس: ولو في الليل؟\nالشيخ: في الليل والنهار نعم، لكن النهار الخلاف أسهل.\nس: ألم تختلف صفات صلاة الليل عن النبي ﷺ، مرة خمسة، ومرة أكثر من ذلك؟\nالشيخ: الوتر بالليل، النهار ما يصلي إلا شفعًا، النهار شفعًا، لمّا فاته الوتر بالليل صلى من النهار شفعًا عليه الصلاة والسلام.\nس: التراويح أحسن الله إليكم؟\nالشيخ: هذا في الليل.\nالطالب: أي نعم في الليل.\nالشيخ: إذا شاء صلى إحدى عشرة، وإذا شاء صلى ثلاث عشرة، وإذا شاء صلى ثلاثًا وثلاثين، أو ثلاثًا وأربعين، أو مائة وواحدة، الأمر واسع، صلاة الليل مثنى مثنى، لكن الأفضل إحدى عشرة، وثلاث عشرة؛ لفعله ﷺ.\nس: يقصد الركعات بسلام واحد؟\nالشيخ: هذا في الوتر خاصة، ما هو في الرباعية، الوتر خمس، سبع، أما أن يصلي ستًّا جميعًا، أو أربعًا جميعًا، ما عليه دليل، السنة تخالفه، النبي ﷺ يقول: صلاة الليل مثنى مثنى، يُستثنى من هذا إذا أوتر بخمس، أو بثلاث، أو بسبع، لا بأس.\nس: وقع الأمر بها عند مسلم صلوا مثنى مثنى في بعض ألفاظ حديث ابن عمر؟\nالشيخ: نعم.\nالطالب: في بعض ألفاظ حديث ابن عمر عند مسلم: صلوا مثنى مثنى.\nالشيخ: كذلك هذا معنى مثنى مثنى يستثنى من هذا الوتر؛ لأن الرسول هو الآمر بالمثنى، ومع هذا أوتر بخمس، وأوتر بثلاث، وأوتر بسبع فلا بأس، لكن لا يصلى أربعًا جميعًا، أو ستًا جميعًا، أو ثمان جميعًا، إلا إذا جلس في التشهد الأول كما فعل النبي ﷺ فإن في بعض الروايات لما صلّى سبعًا جلس في التشهد الأول في السادسة، وجلس في التشهد الأول بالثامنة، ثم أتى بالأخيرة، أما أن يخلي الأربع شفعًا، أو الست شفعًا، أو الثمان شفعًا: هذا خلاف السنة، ولاسيما في الليل.","link":"https://binbaz.org.sa/fatwas/23602/حكم-الزيادة-فوق-اثنتين-في-التراويح-والقيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم زيادة ثالثة في صلاة التراويح.mp3","categories":["التفسير"]},{"id":3700,"question":"المقصود بالضرب؟","title":"ما تفسير {وَاضْرِبُوهُنَّ} وكيفية الضرب؟","answer":"الجواب: الضرب الخفيف يعني على حسب اجتهاده، لا يكون فيه مشقة.","link":"https://binbaz.org.sa/fatwas/23890/ما-تفسير-واضربوهن-وكيفية-الضرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ، المقصود بالضرب.mp3","categories":["التفسير"]},{"id":3762,"question":"قول الله تعالى: وَلَا تَجْعَلُوا اللَّهَ عُرْضَةً لِأَيْمَانِكُمْ [البقرة:224]؟","title":"معنى الآية: {وَلَا تَجْعَلُوا اللَّهَ عُرْضَةً لِأَيْمَانِكُمْ}","answer":"الجواب: يعني: لا تحلفوا بالله لتمتنعوا عما شرع الله لكم، لا تجعلوا الأيمان عُرضة تمنعكم من الخير. ولهذا قال بعدها: أَنْ تَبَرُّوا وَتَتَّقُوا [البقرة:224] يعني: لا تجعلوا الأيمان مانعة لكم من الخير: والله ما أبر والدي، والله ما أصل أرحامي، والله ما أعود فلانا المريض، والله ما أصلي صلاة الضحى؛ كل هذا غلط، يُكَفِّر عن يمينه ويفعل الخير.","link":"https://binbaz.org.sa/fatwas/23955/معنى-الاية-ولا-تجعلوا-الله-عرضة-لايمانكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قول الله تعالى وَلَا تَجْعَلُوا اللَّهَ عُرْضَةً لِأَيْمَانِكُمْ.mp3","categories":["التفسير"]},{"id":3808,"question":"هناك بعض الناس -يا شيخ أحسن الله عملك- إذا نهيتَه عن شرب الدخان وحلق اللحية أو شيء من المعاصي قال: هذه قشور، هذه فروع، مش وقتها الآن؟","title":"حكم من يَعُدُّ الدخان وحلق اللحية من القشور؟","answer":"الجواب: على كل حال، هذا جاهل مُرَكَّب، يغلظ عليه، ويُبين له، هذا ما يقال في أمور الدين: قشور! كلها لبّ، وكلها خير، وكلها هدى، فهذا من جهله وقلَّة بصيرته.\nس: هو ينتسب إلى الدُّعاة؟\nج: ولو، ولو، يُوضّح له أنَّ هذا خطأ كبير، وهذا غلط عظيم، فليتُبْ إلى الله وليستغفر.","link":"https://binbaz.org.sa/fatwas/24009/حكم-من-يعد-الدخان-وحلق-اللحية-من-القشور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل شرب الدخان وحلق اللحية، من القشور أم أنها معاص واضحة.mp3","categories":["التفسير"]},{"id":3882,"question":"في قوله تعالى: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]؟","title":"هل تعمُّ {قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا..} كل تائب؟","answer":"الجواب: أجمع أهل العلم على أنها في التائبين؛ لأنه قال: يَغْفِرُ الذُّنُوبَ جَمِيعًا لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا وهذا يشمل الشرك وغيره، ما قال إلا الشرك، فهذا يعم الشرك وغيره، ولهذا أجمع العلماء على أنها في التائبين.  أما قوله تعالى: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] هذه في غير التائبين، هذه في الذين ماتوا على غير توبة.  وأما قوله: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53] هذه في التائبين؛ لأن الله عمم فيها وأطلق ولم يستثن شيئًا، بدليل أنه أطلق ولم يستثن الشرك، الشرك ما يغفر لمن مات عليه. ثم أمرهم بالإنابة يعني بالتوبة إلى الله ، والإنابة إليه جل وعلا؛ لأن هذا معنى {لَا تَقْنَطُوا..} لا تقنطوا، وأنيبوا.","link":"https://binbaz.org.sa/fatwas/24097/هل-تعم-قل-يا-عبادي-الذين-اسرفوا-كل-تاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ..mp3","categories":["التفسير"]},{"id":3941,"question":"قوله تبارك وتعالى: إِنَّ رَبَّكَ سَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَحِيم [الأنعام:165]؟","title":"تفسير {إِنَّ رَبَّكَ سَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَحِيم}","answer":"الجواب: يعني إذا شاء ، إذا شاء عجل.....، وانظر إذا أردت أن تعرف مثالاً واحدًا: قوم نوح عصوه، كم مكث فيهم؟ ألف سنة إلا خمسين عامًا، وهم يعادونه ويكذبونه ألف سنة إلا خمسين عامًا، تسعمائة وخمسين عامًا، هم أُمهلوا ثم جاءتهم العقوبة بالغرق، مدة طويلة تسعمائة وخمسين عامًا.  فرعون قيل إنه أمهل أربعمائة عام، عمّر أربعمائة عام، ولم يعاقب إلا بعد مدة طويلة..  هذا يدل على سعة حلم الله ، وأنه لا يُعاجل، وهنا يقول: ليس أحد أصبر على أذى من الله يدعون له الولد وهو يعافيهم ويرزقهم ، هؤلاء النصارى ملؤوا الأرض، يعافيهم ويرزقهم، وهم يقولون: إن الله ثالث ثلاثة، هكذا اليهود تجمعوا هنا وهنا وهنا وهم يقولون: عزير ابن الله، وقد اتخذوا أحبارهم ورهبانهم أربابًا من دون الله، وقد كذّبوا الرسل، وقتلوا الأنبياء، ومع هذا أمهل هؤلاء.\nس: معنى هذا أن قوم نوح عمّروا حتى أخذهم العذاب؟\nالشيخ: محتمل أن الكثير منهم عمّر، ومحتمل أن الكثير منهم مات قبل ذلك، المقصود أن العقوبة ما حلّت عليهم إلا بعد مدة طويلة.","link":"https://binbaz.org.sa/fatwas/24164/تفسير-ان-ربك-سريع-العقاب-وانه-لغفور-رحيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى إِنَّ رَبَّكَ سَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَحِيم.mp3","categories":["التفسير"]},{"id":3980,"question":"قول لوط: هَذَا يَوْمٌ عَصِيبٌ؟","title":"تفسير قول لوط عليه السلام: {هَذَا يَوْمٌ عَصِيبٌ}","answer":"الجواب: هذا ما هو من السب، هذا خبر مثل: هذا يوم حار، هذا يوم بارد، هذا من باب وصف الدهر.","link":"https://binbaz.org.sa/fatwas/24208/تفسير-قول-لوط-عليه-السلام-هذا-يوم-عصيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من السب قول لوط هَذَا يَوْمٌ عَصِيبٌ.mp3","categories":["التفسير"]},{"id":3998,"question":"بعضهم يخص هذا بأزواج النبي ﷺ؟","title":"ما تفسير قوله تعالى {وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا..}؟","answer":"الجواب: لا، ما عنده حجة، الآية عامة لا تخص أزواج النبي ﷺ، الحكم عام؛ لأنه قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فليست الطهارة مطلوبة لأزواج النبي خاصة، الطهارة مطلوبة للجميع لهن ولغيرهن، ولهذا في الآية الأخرى: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ [الأحزاب:59] فعمّ الجميع ، وهكذا قوله: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] يعني المؤمنين جميعًا.","link":"https://binbaz.org.sa/fatwas/24229/ما-تفسير-قوله-تعالى-واذا-سالتموهن-متاعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قوله تعالى وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ... هل هي خاصة بأزواج النبي.mp3","categories":["التفسير"]},{"id":4002,"question":"اللمم معناه البصر؟","title":"ما معنى {اللَّمَمَ} في الآية الكريمة؟","answer":"الجواب: اللمم مثل ما قال ابن عباس: فعل المعاصي الصغار: الَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ إِلَّا اللَّمَمَ [النجم:32] يعني إلا ما قد يقع منهم من السيئات الصغار فيغفرها الله لهم باجتناب الكبائر.  هذا معناه أن اللمم يعني الذي قد يلم به، قد يلم بالشيء وقد يريده، ويهتم به ويريد فعله، ثم يتذكّر عظمة الله ويتذكّر أن الله حرمه عليه؛ فيرجع؛ فيكتب له بهذا حسنة.","link":"https://binbaz.org.sa/fatwas/24234/ما-معنى-اللمم-في-الاية-الكريمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ إِلَّا اللَّمَمَ.mp3","categories":["التفسير"]},{"id":4035,"question":"أحسن الله إليكم قول الله تبارك وتعالى يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِي لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ... أمر الرسول ﷺ بالتبكير مع قول الله إِذَا نُودِي لِلصَّلَاةِ","title":"معنى الآية {إِذَا نُودِي لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ..}","answer":"الجواب: الوجوب إذا نودي، وأما السنة التبكير.\nس: متى الساعة الأولى؟\nالشيخ: الله أعلم، بعد صلاة الفجر أو بعد طلوع الشمس محتمل، والأقرب أنه بعد طلوع الشمس؛ لأن اليوم عند العرب ما بين طلوعها وغروبها، الصفرة مضمومة إلى الليل، وإن بكّر بعد صلاة الفجر فيُرجى له فيه الخير.","link":"https://binbaz.org.sa/fatwas/24271/معنى-الاية-اذا-نودي-للصلاة-من-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله تعالى يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِي لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ...mp3","categories":["التفسير"]},{"id":4062,"question":"تحريم المدينة كحرم إبراهيم، يشمل دخول الكفار إليها؟","title":"ما حكم دخول المشركين إلى المدينة؟","answer":"الجواب: هذا فيما بيَّن ﷺ في حديث مكة، تحريم صيدها...، أما دخول المشركين فليس الأمرُ في هذا واضح؛ لأنه ﷺ أقرَّ دخول المشركين، دخل عليه وفدُ نجران والنَّصارى، ووفد ثقيف وثنيُّون، فظاهر الأدلة أن هذا ليس مثل مكة.","link":"https://binbaz.org.sa/fatwas/24299/ما-حكم-دخول-المشركين-الى-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يحرم دخول المشركين إلى المدينة.mp3","categories":["التفسير"]},{"id":4072,"question":"... معنى: لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ [آل عمران:128]؟","title":"تفسير قوله تعالى: {لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ..}","answer":"الجواب: يعني: الأمر بيد الله، هذا معناه، يعني: ليس الأمر بيدك تَهْدِيهم أو تُهلكهم، الأمر بيد الله .","link":"https://binbaz.org.sa/fatwas/24311/تفسير-قوله-تعالى-ليس-لك-من-الامر-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله تعالى لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ.mp3","categories":["التفسير"]},{"id":4087,"question":"الآية في سورة هود مَن كَانَ يُرِيدُ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا...؟","title":"تفسير {مَن كَانَ يُرِيدُ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا..}","answer":"الجواب: هذه للكفار، المشهور عند العلماء أنها للكفار، وقيل: تعمّ المرائين بأعمالهم، فإنَّ أعمالهم تحبط، ولكن المشهور أنها نزلت في الكفار، ولكن عمومها يُوجب الحذر؛ لأنه قال: وَحَبِطَ مَا صَنَعُوا فِيهَا وَبَاطِلٌ مَا كَانُوا يَعْمَلُونَ [هود:16]، هذا ما ينطبق إلا على الكفار: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، لكن قد تعمّ المرائي فيما راءى، فإن ما راءى فيه يبطل ويحبط، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24327/تفسير-من-كان-يريد-الحياة-الدنيا-وزينتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى مَن كَانَ يُرِيدُ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا..mp3","categories":["التفسير"]},{"id":4105,"question":"رَقِيبٌ عَتِيدٌ.. اسم الملكين؟","title":"هل {رقيب عتيد} اسمان لمَلَكَيْن؟","answer":"الجواب: الظاهر أنه الملك الذي يكتب عليه سيئاته وحسناته، ملكان: ملك الحسنات، وملك السيئات، يحتمل أنه يشملهما.  ويحتمل أنَّ المراد جنس... رقيب عتيد...، فكلاهما رقيب، وكلاهما عتيد، وكلاهما مُعدّ لهذا الشيء، ملك كاتب الحسنات، وملك كاتب السيئات.","link":"https://binbaz.org.sa/fatwas/24345/هل-رقيب-عتيد-اسمان-لملكين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل رقيب عتيد، اسم للملكين.mp3","categories":["التفسير"]},{"id":4131,"question":"ما خطيئة نوح؟","title":"ما خطيئة نوح عليه السلام؟","answer":"الجواب: جاء في روايةٍ أخرى أنه سأل ربَّه نجاة ولده: إِنَّ ابْنِي مِنْ أَهْلِي وَإِنَّ وَعْدَكَ الْحَقُّ وَأَنْتَ أَحْكَمُ الْحَاكِمِينَ  ۝  قَالَ يَا نُوحُ إِنَّهُ لَيْسَ مِنْ أَهْلِكَ إِنَّهُ عَمَلٌ غَيْرُ صَالِحٍ فَلَا تَسْأَلْنِ مَا لَيْسَ لَكَ بِهِ عِلْمٌ إِنِّي أَعِظُكَ أَنْ تَكُونَ مِنَ الْجَاهِلِينَ [هود:45- 46].","link":"https://binbaz.org.sa/fatwas/24377/ما-خطيىة-نوح-عليه-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي خطيئة نوح عليه السلام.mp3","categories":["التفسير"]},{"id":4146,"question":"يُوفُونَ بِالنَّذْرِ [الإنسان:7]؟","title":"ما تفسير قوله تعالى: {يُوفُونَ بِالنَّذْرِ..}؟","answer":"الجواب: هذه نذور الطاعات التي نذورها لله من دون تعليقٍ، ومن دون شيءٍ، ومن دون قصدٍ، بل نذروها لله، يتقرَّبون بها إليه على الوجه الذي شرع، كما قال ﷺ: مَن نذر أن يُطيع الله فليُطِعْهُ، ولكنَّهم هم منهيُّون أن يبدؤوها، فإذا فعلوها وجب الوفاء إذا كان من طاعة الله جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/24394/ما-تفسير-قوله-تعالى-يوفون-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله تعالى يُوفُونَ بِالنَّذْرِ.mp3","categories":["التفسير","الأيمان والنذور"]},{"id":4152,"question":"المقصود بقوله تعالى: وَمَا جَعَلْنَا الرُّؤيَا الَّتِي أَرَيْنَاكَ إِلاَّ فِتْنَةً لِّلنَّاسِ؟","title":"تفسير {وَمَا جَعَلْنَا الرُّؤيَا الَّتِي أَرَيْنَاكَ إِلاَّ فِتْنَةً..}","answer":"الجواب: يعني: المشركين الذين كذَّبوه قالوا: كيف رأى كذا؟ وقال: إني رأيتُ الجنة، ورأيتُ النار، ورأيتُ جبرائيل على صفة كذا؟! في المعراج والإسراء رأى في بيت المقدس كذا، فأنكرها كثيرٌ من الناس، وفُتنوا بسبب ذلك، نسأل الله العافية: لَقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى [النجم:18].","link":"https://binbaz.org.sa/fatwas/24402/تفسير-وما-جعلنا-الرويا-التي-اريناك-الا-فتنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله تعالى وَمَا جَعَلْنَا الرُّؤيَا الَّتِي أَرَيْنَاكَ إِلاَّ فِتْنَةً لِّلنَّاسِ.mp3","categories":["التفسير"]},{"id":4194,"question":"مراجعة عمر يا شيخ (في آية الكلالة)؟","title":"لماذا كانت مراجعة عمر في آية الكلالة؟","answer":"الجواب: أشكلت عليه، الرجل العظيم قد يخفى عليه بعض الشيء. وفي هذا فائدة: أن الإنسان لا يستحي إذا خفي عليه بعض الشيء، ولا يستحي يسأل، ولا يقول أنا كبير أستحي، لا ـ يسأل، عمر سأل عن هذه المسألة كرر وألح فيها مع وضوحها؛ لأنه لم ينشرح صدره لمعناها، ما اتضح له الأمر حتى كرر، فالإنسان قد يكون عظيمًا وكبيرًا وعالمًا ولكن يخفى عليه بعض المسائل.\nس: طعن النبي له غضب؟\nالشيخ: ما هو بالظاهر، لا، من باب المداعبة.","link":"https://binbaz.org.sa/fatwas/24451/لماذا-كانت-مراجعة-عمر-في-اية-الكلالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مراجعة عمر بن الخطاب في آية الكلالة.mp3","categories":["شروح الحديث","التفسير"]},{"id":4206,"question":"س: هل الأمر هذا للتهديد..؟","title":"تفسير: {فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ}","answer":"الجواب: للتهديد، هذا في الآية للتهديد فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ [الكهف:29] للتهديد والتحذير، وأنكم لن تفوتوا الله ولن تعجزوه، لكن هنا فهو لبيان الحكم الشرعي وأن التوبة تجب ما قبلها، وليس المراد الإذن؛ لأن هذا معروف من الشرع بالنص والإجماع أنه ليس لأحد الإذن في المعاصي، وإنما المراد أنه ما دام بهذه الحالة التي ذكر، وأنه تاب ثم رجع ثم تاب ثم رجع فالتوبة الأخيرة كالتوبة السابقة تُقبل وتصح إذا استوفت شروطها، لكن في الغالب أن من أكثر من هذا قد يخذل ولا يوفق للتوبة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24468/تفسير-فمن-شاء-فليومن-ومن-شاء-فليكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأمر في قوله تعالى فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ..mp3","categories":["التفسير"]},{"id":4208,"question":"كل نفر له بيت في الجنة والنار؟","title":"هل لكل إنسان بيت في الجنة والنار؟","answer":"الجواب: نعم بحكمة الله  وهو يعلم أحوال هؤلاء وأحوال هؤلاء ، ولهذا إذا مات يرى مقعده من الجنة ويرى مقعده من النار، إذا مات المؤمن يقال له: هذا مقعدك من النار لو مِت على الكفر بالله، فلما مِت على الإسلام وقاك الله ذلك وأعطاك منزلاً في الجنة، وهكذا العكس فالمؤمن يزداد نعيمًا والكافر يزداد حسرة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24470/هل-لكل-انسان-بيت-في-الجنة-والنار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لكل إنسان بيت في الجنة والنار.mp3","categories":["التفسير"]},{"id":4212,"question":"الآية عامة: لَا تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِمَا أَتَوْا وَيُحِبُّونَ أَنْ يُحْمَدُوا بِمَا لَمْ يَفْعَلُوا [آل عمران:188]؟","title":"تفسير: {لَا تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِمَا أَتَوْا}","answer":"الجواب: عامة في أمثالهم، أما من أحب أن يُمدح بالحق والهدى فما هو داخل، لكن المقصود إذا كان فعل اليهود أو فعل المنافقين، يعني أبطن الشر وأظهر الخير؛ فهو داخل في الوعيد، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24476/تفسير-لا-تحسبن-الذين-يفرحون-بما-اتوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح قوله تعالى لَا تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِمَا أَتَوْا...mp3","categories":["التفسير"]},{"id":4214,"question":"تبدل الأرض غير الأرض، أو نفس الأرض تبدل؟","title":"ما تفسير {يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ..}؟","answer":"الجواب: تُغَيَّر، تبديلها تغييرها على غير حالها الأولى، لا جبال ولا أشجار ولا حفر، مستوية.","link":"https://binbaz.org.sa/fatwas/24478/ما-تفسير-يوم-تبدل-الارض-غير-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بتبديل الأرض في قوله تعالى يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ.mp3","categories":["التفسير"]},{"id":4217,"question":"أحسن الله إليك، قوله تعالى: وَقَدِمْنَا إِلَى مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاء مَّنثُورًا...","title":"هل يُجازى الكافر على فعل الخير في الدنيا؟","answer":"الجواب: هذا في الآخرة  هَبَاء مَّنثُورًا في الآخرة.  وأما في الدنيا: يُجزى في الدنيا ما يشاءه الله على أعماله، على صلة الرحم أو بره لوالديه أو إكرامه الضيف أو اعتاقه العبيد أو الصدقة على الفقراء، لا يضيع عند الله عمل، يُجزى بها في الدنيا.\nس: إذا كان الكافر يعمل هذه الأعمال الحسنة بغير حُسن نية...؟\nالشيخ: الظاهر - والله أعلم - أنه يعملها لله، هذا الكلام للذي في الله؛ لأن الكافر قد يعمل أشياء لله؛ يظن أنه مفيد، يظن أنه مهتدٍ، كما قال : إِنَّهُمُ اتَّخَذُوا الشَّيَاطِينَ أَوْلِيَاءَ مِنْ دُونِ اللَّهِ وَيَحْسَبُونَ أَنَّهُمْ مُهْتَدُونَ [الأعراف:30] قد يعملها يرجو ما عند الله من خُلف، من جود، ومن كرم؛ فيجازى بما يشاءه . أما الغافل الذي ما قصد الله في شيء وإنما يعمل حسب طبيعته وحسب رغبته؛ فهذا ما هو داخل في هذا، قد لا يُجزى بشيء.","link":"https://binbaz.org.sa/fatwas/24482/هل-يجازى-الكافر-على-فعل-الخير-في-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله وَقَدِمْنَا إِلَى مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاء مَّنثُورًا.mp3","categories":["التفسير","مسائل متفرقة في العقيدة"]},{"id":4279,"question":"كيف نجمع بين قوله تعالى: وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ [المائدة:44] وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الظَّالِمُونَ [المائدة:45]؟","title":"تفسير قوله تعالى: {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ..}","answer":"الجواب: هذا على ظاهره، من حكم بغير ما أنزل الله يستحله كفر، لكن هذا عند أهل السنة فيه تفصيل: من استحله كفر، ومن لم يستحله صار كفرًا دون كفر، كما قال ابن عباس ومجاهد والجمهور؛ من حكم بغير ما أنزل الله فهو ظالم كافر فاسق إذا استحله، أما إذا لم يستحله بل حكم لشبهة أو لهوى أو لرشوة فهذا يكون كفرًا أصغر، وظلمًا أصغر، وفسقًا أصغر، فلو حكم لقريبه أو أعطي مالًا وحكم بغير ما أنزل الله من أجل المال فهذا يكون فاسقًا، وعنده كفر أصغر، وظلم أصغر، وكفر أصغر. نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24549/تفسير-قوله-تعالى-ومن-لم-يحكم-بما-انزل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين قوله تعالى وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ، وقوله فَأُولَئِكَ هُمُ.mp3","categories":["التفسير"]},{"id":4280,"question":"قوله: وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ [الأحقاف:5] يدل على عدم سماع الموتى؟","title":"تفسير قوله تعالى: {وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ}","answer":"الجواب: نعم لا يسمعون، الآية صريحة إِنْ تَدْعُوهُمْ لَا يَسْمَعُوا دُعَاءَكُمْ [فاطر:14].","link":"https://binbaz.org.sa/fatwas/24550/تفسير-قوله-تعالى-وهم-عن-دعاىهم-غافلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/على ماذا يدل قوله تعالى وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ.mp3","categories":["التفسير"]},{"id":4286,"question":"الشياطين وصلوا إلى السماء، هل يستطيع الإنسان أيضًا أن يجد مقعدًا في السماء؟","title":"تفسير {وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِ}","answer":"الجواب: ظاهر القرآن أنه قد يجد وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِ [الجن:9] يعني حول السماء يركب بعضهم بعضًان وقد يكون معهم أشياء يجلسون عليها، وقد يكون هناك مقاعد يمكنهم فيها ما هو ممنوع، هو ممكن، الله أخبر عن هذا وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِ فَمَنْ يَسْتَمِعِ الْآنَ يَجِدْ لَهُ شِهَابًا رَصَدًا [الجن:9] هذه المقاعد ما يدرى ويش هذه المقاعد التي يقعدونها.\nس: أليست كُنَّا..؟\nج: يعني قبل الشهب، قبل أن يُرموا بالشهب، لما جاء الوحي شدد عليهم بالشهب حتى عجزوا عن الوصول إلى السماء.","link":"https://binbaz.org.sa/fatwas/24558/تفسير-وانا-كنا-نقعد-منها-مقاعد-للسمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يستطيع الإنسان أن يجد مقعد في السماء.mp3","categories":["التفسير","مسائل متفرقة في العقيدة"]},{"id":4292,"question":"قول الله : حَسَرَاتٍ [فاطر:8] وقول الله تبارك وتعالى: يَا حَسْرَةً عَلَى الْعِبَادِ [يس:30] ما معنى هذه الآيات؟","title":"معنى {حَسَرَاتٍ} و{يَا حَسْرَةً عَلَى الْعِبَادِ}؟","answer":"الجواب: حسرات عليهم في النار يعني، كل عاصٍ يَحْسُر يوم القيامة ويتمنى أنه أطاع الله، لكن لا تنفع، كل عاص يوم القيامة يتحسر ويتمنى أنه أطاع الله وأنه لم يطع الشيطان.\nس: يَا حَسْرَةً عَلَى الْعِبَادِ [يس:30]؟\nج: حسرة شديدة، يعني حسرة عليهم شديدة تصيبهم بسبب كفرهم.\nس: في الدنيا والآخرة، أم في الآخرة فحسب؟\nج: أشدها في الآخرة وعند خروج الروح وفي القبر، أما في الدنيا ففي غفلة وسهو، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24564/معنى-حسرات-ويا-حسرة-على-العباد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله تعالى حَسَرَاتٍ، وقوله يَا حَسْرَةً عَلَى الْعِبَادِ.mp3","categories":["التفسير"]},{"id":4308,"question":"قول من قال في قصة أهل الكهف: لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِدًا [الكهف:21] معناها؟","title":"معنى قوله تعالى: {لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِدًا}","answer":"الجواب: قَالَ الَّذِينَ غَلَبُوا عَلَى أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِدًا [الكهف:21] ظنوا أنها جائزة وأنها عبادة جهلًا منهم، وجاءت الشريعة بأن هذا منكر، الشريعة الإسلامية، قَالَ الَّذِينَ غَلَبُوا عَلَى أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِدًا [الكهف:21] هذا من جهلهم، تدل السنة على أن هؤلاء قالوه من جهلهم.","link":"https://binbaz.org.sa/fatwas/24582/معنى-قوله-تعالى-لنتخذن-عليهم-مسجدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله تعالى لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِدًا.mp3","categories":["التفسير"]},{"id":4329,"question":"معنى \"الجبت\" في اللغة؟","title":"معنى \"الجبت\" في اللغة","answer":"الجواب: الجبت من لا خير فيه من السحر وغيره، والصنم وغيره.\nس: الأصل في اللغة يا شيخ؟\nج: هو الشيء الذي لا خير فيه يطلق عليه جبت، يطلق على الصنم جبت، على الساحر جبت، وعلى كل ما يضر الناس ولا خير فيه يسمى جبتًا.","link":"https://binbaz.org.sa/fatwas/24604/معنى-الجبت-في-اللغة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الجبت في اللغة.mp3","categories":["التفسير"]},{"id":4404,"question":"هل من شكر النعمة أن الإنسان يتحدث بها يقول: إن الله أنعم علي بكذا، وأنعم علي بكذا؟","title":"هل من شكر النعمة التحدث بها؟","answer":"الجواب: وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ [الضحى:11] التحدث بها من شكرها على سبيل الشكر، على سبيل الاعتراف بنعم الله، ما هو على سبيل الخيلاء والتكبر.","link":"https://binbaz.org.sa/fatwas/24681/هل-من-شكر-النعمة-التحدث-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من شكر النعمة التحدث بها.mp3","categories":["التفسير"]},{"id":4593,"question":"الصلاة بين العشاءين هي ناشئة الليل؟","title":"ما المقصود بناشئة الليل؟","answer":"الجواب: يُروى عن بعض السلف أنه قال: إنها ناشئة الليل، لكن الأظهر والمعروف عند العلماء أنَّ ناشئة الليل هي التي بعد النوم، ينام بعض الشيء ثم يقوم، ناشئة الليل هي ما يقع بعد النوم، هذا هو المشهور عند العلماء.","link":"https://binbaz.org.sa/fatwas/24882/ما-المقصود-بناشىة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المقصود بناشئة الليل.mp3","categories":["التفسير"]},{"id":4597,"question":"إذا اقتصر على أذكار الصَّلوات هل يُؤدي عن السّلاميات؟","title":"هل تجزئ أذكار الصلاة عن صدقة السّلاميات؟","answer":"الجواب: ما تكمل ثلاثمئة وستين حتى يضمَّ إليها غيرها، أو يأتي بركعتي الضُّحى.\nس: ثلاثمئة وستون الصَّلوات الخمس يعني؟\nج: ثلاثمئة وستون مفصلًا.\nس: إذا أدَّى الصَّلوات الخمس وأذكار الصَّلوات الخمس؟\nج: على كل حالٍ، إذا فعل حسنات تُقابل الثلاثمئة وستين -ولو صدقات- مُستحبَّة، ما هي بفريضةٍ، والمقصود من هذا كله الاستكثار من الخير، والحثّ على الاستكثار من الخيرات، والمسارعة إلى الطَّاعات.","link":"https://binbaz.org.sa/fatwas/24886/هل-تجزى-اذكار-الصلاة-عن-صدقة-السلاميات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاقتصار على على أذكار الصَّلوات هل يُؤدي عن السّلاميات.mp3","categories":["التفسير"]},{"id":4598,"question":"أيّهما أفضل: طول القيام أم كثرة الركوع والسجود؟","title":"هل طول القيام أفضل أم الركوع والسجود؟","answer":"الجواب: طول القيام أفضل، كما فعل النبيُّ ﷺ، لكن لا يشقّ عليه، فأما إذا شقَّ عليه فيقتصد ويُكثر من الركوع والسجود أفضل.","link":"https://binbaz.org.sa/fatwas/24887/هل-طول-القيام-افضل-ام-الركوع-والسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيّهما أفضل طول القيام أم كثرة الركوع والسجود.mp3","categories":["التفسير"]},{"id":4674,"question":"قوله: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ يشمل حتى الصغار؟","title":"هل يجب على الصغار إتمام الحج والعمرة؟","answer":"الجواب: يشمل الذين أدخلهم أولياؤهم، أما هم فلا، ما يلزمهم شيء إذا كانوا بأنفسهم، لكن إذا أدخلهم وليُّهم هو محلّ كلام أهل العلم، إذا أدخلهم لزمه أن يُتمم بهم الذين دون السبع، أما إذا أحرموا بأنفسهم فلهم التَّحلل، لكن ينبغي له أن يُعلِّمه حتى يُكمل؛ لأنهم ليس عليهم فريضة، وقد يقال بوجوب الإتمام؛ لأنهم دخلوا فيه: كالحاج المتنفل، والمعتمر المتنفل، لو أنَّ الإنسان حجَّ مُتنفلًا أو اعتمر مُتنفلًا لزمه الإتمام، وقد يُقال في حقِّ الصبيان: إنَّ على وليهم أن يُلزمهم بالإتمام؛ لأنهم هم الذين أدخلوا، وإن كانوا غير مُكلَّفين، لكن بشيء عارض، مثلما يُمنعون من المعاصي وإن كانوا غير مُكلَّفين؛ لئلا يتلاعبوا، فالقول بهذا قول وجيه، لكن الأصل أنه لا يلزمهم، غير مُكلَّفين، لكن إذا دخلوا عُقلاء قد بلغوا السبعَ -هم من جهتهم دخلوا- ينبغي لوليِّهم أن يُؤكِّد عليهم أن يُكملوا، وإذا أدخلهم هو وهم دون السبع يلزمه، هو الذي يُكمل بهم؛ لأنه مسؤولٌ عنهم، كما يكفُّهم عن المحارم.","link":"https://binbaz.org.sa/fatwas/24966/هل-يجب-على-الصغار-اتمام-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ هل يشمل حتى الصغار.mp3","categories":["التفسير","حكم الحج والعمرة"]},{"id":4736,"question":"القيُّوم؟","title":"ما معنى اسم الله القيُّوم؟","answer":"القيوم الذي لم يزل كذلك، الأزلي والمستقبل: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255].","link":"https://binbaz.org.sa/fatwas/25053/ما-معنى-اسم-الله-القيوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى القيُّوم.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":4755,"question":"بالنسبة لقوله تعالى: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] يدخل فيها تارك الأوامر كالصَّلاة؟","title":"هل يدخل تارك الأوامر في: {إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ}؟","answer":"يدخل فيها تارك الأوامر، وفاعل النَّواهي، ما عدا الصلاة، فإنَّ الحقَّ أن تاركها كافر كفرًا أكبر، هذا هو الصواب فيه، أما الزكاة والصوم والحج فالجمهور على أنَّ تاركها من غير جحدٍ؛ لم يجحد وجوبها، ولكن تركها من غير جحدٍ، فهذا لا يكفر، ولكن يكون له حكم العُصاة -أهل الكبائر- وأما تارك الصلاة فاختلف العلماء فيه اختلافًا كبيرًا، ولكن الراجح والأصح أن تاركها كافر كفرًا أكبر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشِّرك ترك الصلاة خرَّجه مسلم في \"صحيحه\" من حديث جابرٍ ؛ ولقول النبي ﷺ أيضًا: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر خرَّجه الإمامُ أحمد وأهل السنن بإسنادٍ صحيحٍ عن بُريدة ؛ ولحديث: رأس الإسلام وعموده الصلاة؛ ولأحاديث أخرى: كحديث أنَّ النبي ﷺ بايع أصحابَه أن لا يُنازعوا الأمر أهله، قال: إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان، وفي اللَّفظ الآخر قال: ما أقاموا فيكم الصلاة، فدلَّ ذلك على أنَّ الذي لا يُقيم الصلاة قد أتى كفرًا بواحًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/25105/هل-يدخل-تارك-الاوامر-في-ان-الله-لا-يغفر-ان-يشرك-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل تارك الأوامر في قوله تعالى إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ... الآية.mp3","categories":["التفسير"]},{"id":4859,"question":"فسر بعضهم  قوله تعالى: وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ [المائدة:4] الجوارح هي الكواسر من الطير والسباع؟","title":"ما تفسير قوله تعالى {وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ}؟","answer":"مكلبين ومعلمين: الظاهر أن المعنى: معلمينها كيفية الكر والفر.\nس: خاصة بالكلاب هي الجوارح؟\nج: لا، معلمين، يعني يعلمونهن كيف يصدن.","link":"https://binbaz.org.sa/fatwas/25325/ما-تفسير-قوله-تعالى-وما-علمتم-من-الجوارح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير قوله تعالى وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ.mp3","categories":["التفسير"]},{"id":5016,"question":"أيّهما أفضل: الأخذ من بيت المال أو العمل باليد؟","title":"هل العمل أفضل أم الأخذ من بيت المال؟","answer":"الجواب: العمل أفضل إذا تيسَّر.","link":"https://binbaz.org.sa/fatwas/28829/هل-العمل-افضل-ام-الاخذ-من-بيت-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل العمل أفضل أم الأخذ من بيت المال؟.mp3","categories":["التفسير"]},{"id":5067,"question":"قال الله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ [آل عمران:200] المصابرة هذه أيش هي؟ على الحق؟","title":"معنى قوله تعالى: {اصْبِرُوا وَصَابِرُوا وَرَابِطُوا}","answer":"الجواب: مصابرة العدو، المصابرة: مصابرة الغير، مُتَعَدِية.\nس: والرباط؟\nج: الرباط: لزوم الثغور للدفاع عن المسلمين، والتقوى عامة يدخل فيها الصبر وغيره.","link":"https://binbaz.org.sa/fatwas/29363/معنى-قوله-تعالى-اصبروا-وصابروا-ورابطوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله تعالى اصبروا وصابروا ورابطوا.mp3","categories":["التفسير"]},{"id":5135,"question":"سائل يقول: يقول بعضُ المُفسرين في تفسير قول الله عزَّ وجل: فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى [الأعلى:9] أي: ذَكِّرْ حيث تنفع التذكرة؟","title":"ما معنى قوله تعالى: {فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى}؟","answer":"الجواب: هذا ليس بشرطٍ، إنما هو وصفٌ أغلبيٌّ، يعني: تعظُم الفَرْضية والوجوب عند انتفاع الناس بالذِّكْرى، وإنما هو أمرٌ بالتذكير، عسى أن ينتفعوا، ولهذا جاء في الآيات الأخرى: فَذَكِّرْ إِنَّمَا أَنْتَ مُذَكِّرٌ [الغاشية:21]، وَذَكِّرْ فَإِنَّ الذِّكْرَى تَنْفَعُ الْمُؤْمِنِينَ [الذاريات:55]. فالإنسان يُذكِّر، والنفع بيد الله، لكن إذا نفعت الذِّكْرى؛ يكون الوجوب أشدَّ، وتكون الفائدةُ أعظم، فإذا رأى منه الانتفاع والاستفادة يكون الواجب عليه يتضاعف ويَقْوَى ويَكْبُر.","link":"https://binbaz.org.sa/fatwas/30050/ما-معنى-قوله-تعالى-فذكر-ان-نفعت-الذكرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 71.mp3","categories":["التفسير"]},{"id":5251,"question":"","title":"تنبيهات تتعلق بطهارة المريض وصلاته","answer":"الجواب: فاتني شيءٌ ينبغي التَّنبيه عليه في الكلمة، وهو أنه يجب على المريض أن يُؤدي الصلاة في وقتها على أي حالٍ كان: إن قدر قائمًا فقائمًا، وإن لم يستطع صلَّى قاعدًا، فإن لم يستطع صلَّى على جنبه، فإن لم يستطع فمُستلقيًا، ولا يجوز له تأخير الصلاة إلى وقتٍ آخر كما يفعل بعضُ المرضى، يقول: أُؤخِّرها لعلي أُشفى وأُصليها على وجهٍ أكمل، لا، يجب على المريض أن يُصلي في الوقت على حسب حاله، يقول النبي ﷺ لبعض الصحابة لما كان مريضًا: صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنبٍ رواه البخاري في \"الصحيح\"، وزاد النَّسائي في روايةٍ: فإن لم تستطع فمُستلقيًا. هذا الواجب على المريض والمريضة، المرأة كذلك، الواجب الصلاة قائمًا إذا استطاع، فإن عجز الرجل أو المرأة صلَّى قاعدًا على أي صفةٍ كانت: قاعدًا مُتربِّعًا، أو غير ذلك، على أي حالٍ كان من القعود حسب حاله، فإن عجز عن القعود صلَّى على جنبه، والأفضل على جنبه الأيمن إذا تيسر، فإن لم يتيسر الأيمن فالأيسر، فإن عجز صلَّى مُستلقيًا على ظهره، ورجلاه إلى القبلة. ثم لا بد من الوضوء عند القُدرة، فإن لم يستطع تيمّم بالتراب، يكون عند سريره شيءٌ من التراب في إناءٍ، أو في كيسٍ، يتيمّم به عند عجزه عن الماء. وقد كتبنا لوزير الصحة منذ عامين أو ثلاثة فأصدر تعميمًا عامًّا -جاءتنا صورته- لجميع المستشفيات بوجوب اتِّخاذ شيء من التراب عند أَسِرَّة المرضى إذا عجزوا عن الماء؛ لقول النبي ﷺ: أُعْطِيتُ خمسًا لم يُعْطَهُنَّ أحدٌ قبلي: نُصرتُ بالرعب مسيرة شهرٍ، وجُعلتْ لي الأرض مسجدًا وطهورًا، فأيُّما رجلٍ من أمتي أدركته الصلاةُ فعنده مسجده وطهوره، وفي اللفظ الآخر: وجُعلت تُربتها لنا طهورًا إذا لم نجد الماء، والله يقول في كتابه العظيم: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43]، فالطيب وجه الأرض. فالواجب على المسؤولين في كل مُستشفى وفي هذا المستشفى أن يُعْنَوا بهذا الأمر، وعلى الأطباء والطبيبات أن يُعنوا بهذا الأمر، حتى لا يُنسى المريض، بل يُعلّم ويُوجّه بأن يُصلي على حاله: قاعدًا، وقائمًا، وعلى جنبٍ، على حسب طاقته: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وأن..... التيمم عند عدم قدرته على الماء، وأن يُصلي في الوقت، ولا بأس أن يجمع بين الصلاتين، لا بأس أن يجمع بين الظهر والعصر في وقت إحداهما، جمع تقديمٍ، أو جمع تأخير، ولا بأس أن يجمع بين المغرب والعشاء في وقت إحداهما، جمع تأخير، أو جمع تقديم، لا بأس بذلك من أجل المرض. نسأل الله للجميع التَّوفيق.","link":"https://binbaz.org.sa/fatwas/30700/تنبيهات-تتعلق-بطهارة-المريض-وصلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 889.mp3","categories":["التفسير"]},{"id":5281,"question":"أعظم الله مثوباتكم، سائل يقول: كيف نجمع بين قوله تعالى: إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ [البقرة: 173] وقوله تعالى: إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ [المائدة: 2]؟","title":"ما كيفية الجمع بين آيات المغفرة وشدة العقاب؟","answer":"الجواب: لا منافاة بين الآيتين، فهو شديد العقاب لمن خالف أمره وتعدى حدوده ولم يبال ولم يتب، وغفور رحيم لمن أناب إليه وتاب إليه وأقلع عن ذنوبه، فالتائب المقلع من الذنوب له المغفرة والرحمة، والمصر العاصي الذي لا يبالي يستحق العقوبة إلا أن يعفو الله عنه .[1]","link":"https://binbaz.org.sa/fatwas/30919/ما-كيفية-الجمع-بين-ايات-المغفرة-وشدة-العقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 001.mp3","categories":["التفسير"]},{"id":5285,"question":"يقول الله  في سورة الأحزاب: وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ [الأحزاب: 37] ما معنى قوله: وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ ما هي قصة هذه الآية، وما تفسيرها؟","title":"ما معنى قوله تعالى: {وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ}؟","answer":"الجواب: هذه نزلت في زيد بن حارثة كانت عنده زينب وهو مولى النبي ﷺ فشاروه فيها فأشار عليه النبي ﷺ بأن يمسك زوجته، وأن يستقيم معها؛ ولكن زيد رغب عنها، وأنزل في قصته فَلَمَّا قَضَى زَيْدٌ مِنْهَا وَطَرًا زَوَّجْنَاكَهَا [الأحزاب: 37] لما طلقها زيد وخرجت من العدة خطبها النبي ﷺ وتزوجها، فيظهر من الآية أنه كان في نفسه ﷺ شيء لو طلقها زيد لأخذها؛ لكنه ﷺ أشار عليه بأن يمسكها وأن يصبر عليها، ولكن زيد طابت نفسه منها فلما طلقها وخرجت من العدة تزوجها النبي ﷺ.[1]","link":"https://binbaz.org.sa/fatwas/30926/ما-معنى-قوله-تعالى-وتخفي-في-نفسك-ما-الله-مبديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 006.mp3","categories":["التفسير"]},{"id":5295,"question":"ما قولكم فيمن يصنِّف الناس بمجرد الظن إلى فِرَق ومذاهب؟ نرجو من سماحتكم نصيحة لهؤلاء الناس (هداهم الله).","title":"حكم مَنْ يصنّف الناس بالظن إلى فِرَق ومذاهب","answer":"الجواب: الواجب على العبد تقوى الله، ولا يصنِّف الناس إلا على بصيرة، على الوجه الذي صنَّفهم الله: فمن اتقى الله فهو مع المؤمنين، ومن كفر بالله فهو مع الكافرين، ومن تعاطى المعاصي فهو بَيْن بَيْن مع الظالمين لأنفسهم، فيقال له: فاسق، ويقال له: مؤمن ناقص الإيمان. هذه أقسام الناس: مؤمن، وكافر، ومُخَلِّط وهو الظالم لنفسه، هذه أقسام الناس، فمن اتقى الله فهو مع المؤمنين، ومن كفر بالله فهو مع الكافرين، ومن تعاطى المعاصي ولم يتب منها فهو مع المخلِّطين، مع الظالمين لأنفسهم، وهم تحت مشيئة الله  كما قال جل وعلا: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] وقال سبحانه: ثُمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ وَمِنْهُمْ مُقْتَصِدٌ وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ [فاطر:32] فالظالم لنفسه هو صاحب المعاصي.[1]","link":"https://binbaz.org.sa/fatwas/30944/حكم-من-يصنف-الناس-بالظن-الى-فرق-ومذاهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 015.mp3","categories":["التفسير"]},{"id":5319,"question":"يقول: قال أحد الإخوة أن الله  يُظلَم، واستشهد بقوله تعالى: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] فعندما تتعدى على حد من حدود الله فإنك تظلمه، ولكن ظلم يليق به سبحانه، فهل يصح مثل هذا القول؟","title":"ما معنى قوله تعالى: {إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ..}؟","answer":"الجواب: لا يُقال هذا، الله جل وعلا يقول: وَمَا ظَلَمُونَا وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ [البقرة:57] فالظلم وضع الأمور بغير موضعها، وهو لا يضر الله شيئًا، وإنما ظلموا أنفسهم، وتحملوا تبعة ذلك، ولهذا يقول: وَمَا ظَلَمُونَا وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ [البقرة:57] الظلم وضع الشيء في غير موضعه، فالمعاصي ظلم للنفس، والطاعات تسلية لها، والله لا يضره ظلمهم ولا معاصيهم، بل مضرته عليهم: إِنْ أَحْسَنْتُمْ أَحْسَنْتُمْ لِأَنْفُسِكُمْ وَإِنْ أَسَأْتُمْ فَلَهَا [الإسراء:7] مَنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ وَمَنْ أَسَاءَ فَعَلَيْهَا [فصلت:46].[1]","link":"https://binbaz.org.sa/fatwas/30983/ما-معنى-قوله-تعالى-ان-الشرك-لظلم-عظيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 040.mp3","categories":["التفسير"]},{"id":5327,"question":"ذكر الحافظ ابن كثير في البداية والنهاية في سيرة الإمام أحمد رحمه الله أن البيهقي روى عن الإمام أحمد أنه قال في قوله تعالى: وَجَاءَ رَبُّكَ [الفجر:22] قال: جاء أمره. انتهى ما ذكره ابن كثير. وقد ذكر الخلال عن الإمام أحمد أنه قال في صفات الله: نمرها كما جاءت لا كيف ولا معنى، فما يُقال في تلك الروايات؟","title":"ما معنى المجيء في قوله تعالى: {وَجَاءَ رَبُّكَ..}؟","answer":"الجواب: هذه الرواية خطأ، ولا تصح عن أحمد رحمه الله؛ لأن القاعدة عدم تأويل النصوص، ونُمِرُّها كما جاءت، فقوله: وَجَاءَ رَبُّكَ [الفجر:22] الأصل مجيئه سبحانه يوم القيامة، مثل ما قال سبحانه: هَلْ يَنْظُرُونَ إِلَّا أَنْ تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ رَبُّكَ أَوْ يَأْتِيَ بَعْضُ آيَاتِ رَبِّكَ [الأنعام:158] فهو جل وعلا يأتي يوم القيامة لفصل القضاء بين عباده مجيئًا يليق بجلاله، فلا يجوز التأويل. وهذا ذكره بعض المفسرين: جاء أمر ربك، وهذا غلط، ولو صح عن أحمد فهو غلط منه، فالنصوص الأخرى تدل على رجوعه عنه؛ لأن قاعدة أحمد والسلف الصالح والصحابة من قبله قاعدتهم: عدم التأويل وإمرار النصوص على ظاهرها من غير تكييف ولا تمثيل ولا تعطيل لأسماء الله وصفاته، هذا هو قاعدة السلف الصالح، فإذا جاءت رواية شاذة عن أحمد منهم؛ فهي إما باطلة وإما غلط فيها، من باب الغلط، وليس بمعصوم لا هو ولا غيره.[1]","link":"https://binbaz.org.sa/fatwas/30994/ما-معنى-المجيء-في-قوله-تعالى-وجاء-ربك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 048.mp3","categories":["مسائل متفرقة في العقيدة","التفسير"]},{"id":5336,"question":"ما تفسير قوله تعالى: يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ [الرعد: 39] هل المقصود أنه يمحو ما في القرآن أو ما في اللوح المحفوظ؟","title":"ما تفسير قوله تعالى {يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ..}؟","answer":"الجواب: المعنى: يمحو ما يشاء ويثبت مما شرع من الشرائع، ينسخ هذه، كما جرى فإنه سبحانه نسخ أحكامًا في مكة وكانت في المدينة على غير ذلك، كالقبلة كانوا في أول الهجرة قبل ذلك يستقبلون الشام ثم نسخت إلى الكعبة، وأشياء أخرى ذكر فيها النسخ، فالله ينسخ ما يشاء، وهكذا ما علّقه سبحانه على أشياء إذا وُجدت وقع الشيء، وإذا لم توجد لم يقع الشيء، فالله ينسخ ما يشاء ويثبت فيما مضى في علمه وقدره السابق، فيما مضى في علمه وقدره السابق تُرجع الأمور إليه ولا يُبدّل ولا يُغيّر.[1]","link":"https://binbaz.org.sa/fatwas/31009/ما-تفسير-قوله-تعالى-يمحو-الله-ما-يشاء-ويثبت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 057.mp3","categories":["التفسير"]},{"id":5392,"question":"متى تُبدل السيئات حسنات؟","title":"هل التوبة الصادقة تُبدل السيئات حسنات؟","answer":"الجواب: إذا تاب وعمل، إِلَّا مَن تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا [الفرقان:70]. س: التوبة الصادقة تُبدل السيئات حسنات؟ ج: نعم تُبَدَّل، مثل ما في الآيات الكريمات في الفرقان، إذا تاب وعمل صالحًا أبدل الله مكان كل سيئةٍ حسنة، وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا [الفرقان:70] يعني: زاد على التوبة وأتى بأعمالٍ صالحةٍ استدرك بها ما مضى.[1]","link":"https://binbaz.org.sa/fatwas/31135/هل-التوبة-الصادقة-تبدل-السيىات-حسنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 008.mp3","categories":["التفسير","الرقائق"]},{"id":5428,"question":"بالنسبة لتفسير قوله: وَلِلَّهِ الْمَثَلُ الأَعْلَى [النحل:60] ما التفسير الصحيح؟","title":"ما تفسير قوله تعالى: {وَلِلَّهِ الْمَثَلُ الأَعْلَى}؟","answer":"الجواب: يعني: الوصف الأعلى، الذي لا يُماثله شيء، لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ فله المثل الأعلى أي: الوصف الأعلى ؛ لأنَّه لا يُماثله شيء، فهو الكامل في ذاته وأسمائه وصفاته وأفعاله .[1]","link":"https://binbaz.org.sa/fatwas/31203/ما-تفسير-قوله-تعالى-ولله-المثل-الاعلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 041.mp3","categories":["التفسير"]},{"id":5431,"question":"قول الله : قُلْ هَلْ نُنَبِّئُكُمْ بِالْأَخْسَرِينَ أَعْمَالًا [الكهف:103] هل يدخل في ذلك المبتدعة؟","title":"هل يدخل المبتدعة في وصف (الْأَخْسَرِينَ أَعْمَالًا)؟","answer":"الجواب: لهم نصيب من الخسارة، لكن الخسارة التامَّة تكون للمشركين الكفار، لكن المبتدع فيه تفصيل، إن كفر فهو معهم، وإن لم يكفر فهو على خطرٍ لبدعته. س: المبتدع متى لا تُذكَر محاسنه؟ ج: مَن أظهر البدع يُحذَّر منه ويُعرَض عن المحاسن؛ لأنَّ المقصود التحذير من الشر، وليس بيان المحاسن.[1]","link":"https://binbaz.org.sa/fatwas/31200/هل-يدخل-المبتدعة-في-وصف-الاخسرين-اعمالا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 038.mp3","categories":["التفسير"]},{"id":5491,"question":"قوله تعالى: وَلَا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِنْ بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ [آل عمران:105]، هذه الآية يعني في اليهود والنَّصارى، وكذلك نجد أنَّ قريشًا لما جاءهم الرسول اختلفوا وتفرَّقوا، مع أنَّ ما عندهم علم مثل: اليهود والنصارى، نفس السبل، نفس الطريقة، يعني: أنكروا كما أنكر أصحابُ الكتاب.","title":"ما الفرق بين اختلاف الكفار واختلاف أهل الكتاب؟","answer":"الجواب: أولئك هم الأساس في الشرِّ، اليهود والنصارى اختلفوا بعدما جاءهم العلمُ، فالله ينهى الأمةَ أن تفعل مثلهم؛ لأنَّ الجهال ما عندهم علم، قريش وأشباههم ما عندهم علم، فالله ينهى أمة محمد أن تختلف كما اختلف أهلُ الكتاب من بعد ما جاءهم العلم، جاءتهم التَّوراة، وجاءهم الإنجيل، واختلفوا، ما اكتفوا بما أُنزل عليهم. أما اختلاف الكفرة فهذا اختلاف ما له أساس، اختلاف جهلةٍ ما عندهم أشياء يركّزون عليها، فإذا منع الاختلاف المركّز على شيءٍ؛ فالاختلاف المركّز على جهلٍ من باب أوْلى أن يُمنَع. س: طيب، نفس البينات التي جاءت هؤلاء هي التي جاءت هؤلاء؟ ج: لا، البيِّنات غير، هؤلاء ما عندهم بيِّنات، ما عندهم إلا الجهل، وقريش وأشباههم ما عندهم إلا الجهل، ما عندهم بيِّنات.[1]","link":"https://binbaz.org.sa/fatwas/31398/ما-الفرق-بين-اختلاف-الكفار-واختلاف-اهل-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 005.mp3","categories":["مسائل متفرقة في العقيدة","التفسير"]},{"id":5544,"question":"الآية لَا إِكْرَاهَ فِي الدِّينِ [البقرة:256] منسوخة بآية السَّيف؟","title":"هل نسخت آية السيف آية {لَا إِكْرَاهَ فِي الدِّينِ}؟","answer":"الجواب: قيل: منسوخة. وقيل: إنها في أهل الكتاب خاصةً. فيها قولان: أحدهما أنها في أهل الكتاب والمجوس، لا يُكرهون، بل يُخيرون بين الإسلام والجزية، فإن لم يُؤدوا الجزيةَ ولا الإسلام قُوتلوا، وأما بقية الناس فلا تخيير: إما الإسلام، وإما السيف. وقال آخرون: بل هي منسوخة، كان هذا أول الأمر، ثم شرع الله القتال والجهاد؛ لقوله سبحانه: وَقَاتِلُوهُمْ حَتَّى لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ [الأنفال:39]، فنُسخت بهذه الآية وما جاء في معناها.[1]","link":"https://binbaz.org.sa/fatwas/31487/هل-نسخت-اية-السيف-اية-لا-اكراه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 007.mp3","categories":["التفسير"]},{"id":5626,"question":"القوة والصفة؟","title":"ما تفسير قوله تعالى: {وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ..}؟","answer":"الجواب: نعم، اليد الصفة، وتُطلق على النِّعمة والقوة: وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ يعني: بقوةٍ: وَاذْكُرْ عَبْدَنَا دَاوُودَ ذَا الْأَيْدِ [ص:17] ذا القوة: أُولِي الْأَيْدِي وَالْأَبْصَارِ أولو القوة والبصر في دين الله. س: وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ يُفهم منها إثبات الأيدي لله؟ ج: القوة: وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ بقوةٍ، والله - جلَّ وعلا - له يدان: بَلْ يَدَاهُ مَبْسُوطَتَانِ [المائدة:64]، اليدان غير هنا: بَنَيْنَاهَا بِأَيْدٍ هنا بالقوة.[1]","link":"https://binbaz.org.sa/fatwas/31623/ما-تفسير-قوله-تعالى-والسماء-بنيناها-بايد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 001.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":5630,"question":"كيف يجمع بين عدم الهجر وبين قول الله : كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ [المائدة:79]؟","title":"ما مدة الهجر الشرعي وكيفيته؟","answer":"الجواب: هذا يُصاحبهم، يتّخذهم أصحابًا له، وأنت ما تتّخذهم أصحابًا، تتصل بهم للدَّعوة، ما هو للصحبة، تتصل بهم للدَّعوة والتوجيه والإرشاد، ما تصحبهم في مُنكراتهم، أما فعل بني إسرائيل فيصحبونهم في مُنكراتهم، ويتركون النَّهي، أما أنت فلا، إذا زرتَه تنهاه، وتأمره بالمعروف، وتنهاه عن المنكر، مرتين، ثلاثًا، لعله يهتدي، من دون أن تتّخذه صاحبًا؛ تأكل معه وتشرب معه. س: الهجر له مدّة؟ ج: حسب اجتهاد الهاجر، ما يتعين. س: لا يقرأ عليه السلام؟ ج: لا يُسلم عليه، ولا يُصافحه ولو مضت سنوات، إذا كان بقي على بدعته وعلى معاصيه الظَّاهرة، نعم. س: هل هناك مدّة معينة للنَّصيحة؟ ج: كلما لقيتَه تنصحه، كلما تيسر تنصحه، فإذا أصرَّ تهجره. س: الهجر في أمر الدنيا ثلاث ليالٍ؟ ج: يهجره في الكلام ثلاثة أيام، فإن هداه الله فالحمد لله، في حقِّه، التقصير في حقِّه، ما هو في حقِّ الله، في حقِّ الإنسان. س: مَن قال أنَّ الهجر في هذا الزمان لا يُفيد؟ ج: غلط، يفيد، إذا هجره أهلُ الخير وأهلُ الحلّ والعقد يُؤثر، وإذا ما أثَّر فالحمد لله برئت ذمَّتُك.[1]","link":"https://binbaz.org.sa/fatwas/31627/ما-مدة-الهجر-الشرعي-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 005.mp3","categories":["الدعوة والدعاة","التفسير"]},{"id":5776,"question":"ما هو تفسير الآية في قوله تعالى: حَتَّى إِذَا بَلَغَ أَشُدَّهُ وَبَلَغَ أَرْبَعِينَ سَنَةً [الأحقاف: 15]؟ ما هو صحة الكلام لقد سمعت أن أهل المدينة إذا بلغ منهم الشخص أربعين سنة تفرغ للعبادة؟","title":"الحث على العمل والاجتهاد في العبادة دائماً","answer":"الجواب: الآية واضحة في معناها، أما ما ورد عن أهل المدينة ما عندي خبر عن هذا، قد يكون بعض الناس فعله، لا أعلم هذا، الشرع يدل على أنه ينبغي للمؤمن أن يعمل أبدًا، ويجتهد في العبادة أبدًا، سواء كان ابن أربعين، أو ابن ستين، والآية لا تخالف ذلك.  الآية فيها أنه يشكر الله -جل وعلا- ويحمده، ويثني عليه  ويسأل الله الذرية الصالحة، وليس فيها أن يعطل العمل، بل فيها العمل وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ [الأحقاف:15].","link":"https://binbaz.org.sa/fatwas/1102/الحث-على-العمل-والاجتهاد-في-العبادة-داىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_108.mp3","categories":["التفسير","شروح الحديث"]},{"id":5958,"question":"يقول الله تعالى في سورة النساء: وَقَدْ نَزَّلَ عَلَيْكُمْ فِي الْكِتَابِ أَنْ إِذَا سَمِعْتُمْ آيَاتِ اللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا مَعَهُمْ حَتَّى يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ إِنَّكُمْ إِذًا مِثْلُهُمْ [النسا :140] إلى آخر الآية ما معنى الآية؟ وما صفة الاستهزاء، والكفر بها؟ وهل معنى ذلك الجلوس مع  أهل المعاصي، وحضور المنكرات، أم ماذا؟","title":"معنى قوله تعالى: (وقد نزل عليكم في الكتاب...)","answer":"الجواب: هذه آية تمنع من حضور المؤمنين من يخوض في آيات الله بغير حق، بل يجب عليه الإعراض عنهم، وعدم الجلوس معهم إذا خاضوا في الباطل بالمنكرات، يجب أن لا يجلس معهم إلا إذا أنكر عليهم، وأجابوا، وتركوا ما هم فيه، فهذا لا بأس.  أما إذا أصروا على البقاء في خوضهم الباطل، واستهزائهم بآيات الله، فيجب عليه أن يفارقهم، وإنكار ذلك بالفعل، والقول جميعًا. والاستهزاء بآيات الله معروف، والطعن فيها، والسخرية بها هذا كفر، وردة عن الإسلام، نعوذ بالله؛ فيجب الحذر من هؤلاء، ويجب الإنكار عليهم، والتشديد عليهم، ورفعهم إلى ولاة الأمور، حتى يردعوا عن باطلهم، وحتى يعاملوا بما يجب شرعًا.  وأما من أعلن المعاصي فهو أقل من ذلك، من أعلن المعاصي دون الشرك بالله، فيجب أن ينكر عليه أيضًا،ويخوف من أمر الله، ويحذر، لكن إذا أصر على إظهار المعاصي، لا يجلس معه أيضًا، بل يفارق، ولا يحضر؛ لأنه في مفارقته إنكار عليه بالقول، والفعل جميعًا.","link":"https://binbaz.org.sa/fatwas/1331/معنى-قوله-تعالى-وقد-نزل-عليكم-في-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_300.mp3","categories":["التفسير","شروح الحديث"]},{"id":6064,"question":"قال تعالى: بسم الله الرحمن الرحيم: وَقُلِ الْحَقُّ مِنْ رَبِّكُمْ فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ [الكهف: 29]، ويقول رسول الله ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، وأن محمدًا رسول الله إلى آخر الحديث، كيف يمكن التوفيق بين نص الآية، ونص الحديث، والرد على أعداء الإسلام الذين يدعون أن الإسلام انتشر بالسيف؟","title":"الجمع بين: {فَمَنْ شَاءَ فَلْيُؤْمِنْ} و «أمرت أن أقاتل الناس»","answer":"الجواب: هذه الآية مكية قبل أن يؤمر بالقتال، هذه الآية مكية من سورة الكهف، والكهف سورة مكية فيها الإعراض عن الكفرة، وعدم قتالهم، بل يدعو إلى الله من شاء آمن، ومن شاء كفر، يدعو إلى الله، ويعلم الناس الخير، فمن شاء آمن، وقبل، ومن شاء لم يقبل، وحسابه على الله. فأنت الآن بين الناس في غالب الدنيا هكذا ترشد الناس إلى الخير، وتعلمهم دين الله، فمن قبل منك؛ فالحمد لله، ومن لم يقبل فأمره إلى الله، ليس إليك، ليس عليك هداهم، ولكن الله يهدي من يشاء، إنما عليك البلاغ، وعلى الله الحساب  وأما النبي ﷺ فقال هذا بعدما هاجر، بعدما قوي، وعنده قوة، وعنده جيش، قال هذا الكلام أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، وأني رسول الله، ويقيموا الصلاة ويؤتوا الزكاة فإذا فعلوا ذلك؛ عصموا مني دماءهم، وأموالهم إلا بحق الإسلام، وحسابهم على الله. وقال -جل وعلا- في كتابه العظيم: فَإِذَا انْسَلَخَ الْأَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ فَإِنْ تَابُوا وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] هذا قاله الله -جل وعلا- لنبيه بعدما هاجر، وبعدما استقر المسلمون، وقوي المسلمون، وصار لهم جيش، وقوة، خاطبهم الله بهذا. فأنت إذا كان عندك جيش، وقوة تستطيع أن تقاتل بها أوروبا، وأمريكا؛ فقم بهذا الأمر، وما دمت لا تستطيع هذا؛ فعليك بالدعوة إلى الله، والإرشاد إليه، وتعليم الناس الخير، وإرشادهم إليه، واحفظ لسانك عما يضر الدعوة، وعما يفرق الكلمة، وعما يسبب المشاكل التي تحرم الناس الخير، وتوقعهم في الشر.","link":"https://binbaz.org.sa/fatwas/1474/الجمع-بين-فمن-شاء-فليومن-و-امرت-ان-اقاتل-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_404.mp3","categories":["التفسير","شروح الحديث"]},{"id":6068,"question":"هل الرسول ﷺ فسر شيئًا من القرآن الكريم؟","title":"تفسير النبي عليه الصلاة والسلام للقرآن","answer":"الجواب: نعم فسر شيئًا كثيرًا للصحابة، ووضح لهم شيئًا كثيرًا، وكان يقرأ عليهم القرآن -عليه الصلاة والسلام- ويبين لهم معناه تارة في المجالس، وتارة في الخطب، وتارة يقرئ عليه القرآن، ويبين -عليه الصلاة والسلام- ما يحتاج الناس إليه.  فكثير من الآيات فسرها -عليه الصلاة والسلام- وكثير منها، فسره الصحابة =رضي الله عنهم وأرضاهم- كابن مسعود، وابن عباس، وغيرهم، وهكذا التابعون على ما ظهر لهم من الآيات الأخرى؛ لأن القرآن يفسر بعضه بعضًا، ثم السنة تفسر ما خفي من القرآن. وهكذا يفسر بعض الكلمات مما علم من لغة العرب؛ فإن الله أنزله بلغتهم، بلسان العرب، فالكلمات التي تتعلق باللغة تفسر باللغة العربية، والأحكام تفسرها الآيات الأخرى؛ فإن القرآن يفسر بعضه بعضًا، وبعضها فسرتها السنة عن النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/1478/تفسير-النبي-عليه-الصلاة-والسلام-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_408.mp3","categories":["التفسير"]},{"id":6144,"question":"ورد في القرآن الكريم في هذه الآية: وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا [طه:130] ونجد أن بعضًا من الناس قبل غروب الشمس، وقبل صلاة الفجر منهم من يقوم بالتسبيح، ومنهم من يقوم بتلاوة القرآن، فأيهما أفضل؟","title":"معنى قوله تعالى: (وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ..)","answer":"الجواب:  المشهور عند العلماء أن هذه الآية في صلاة الفجر، وصلاة العصر، قبل طلوع الشمس، صلاة الفجر، وقبل غروبها صلاة العصر الفرائض يعني، ولا مانع من الأخذ بعمومها، فإذا سبح بعد الصبح قبل طلوع الشمس، وذكر الله كما قال سبحانه: فَسُبْحَانَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ [الروم:17]، وهكذا إذا ذكر الله بعد العصر، هذا كله خير، وطيب.  يسبح الله، ويهلله، ويستغفره، ويقرأ القرآن، كل هذا، فإن التسبيح تنزيه الله، يذكر في قراءة القرآن التسبيح، والتهليل، والتحميد، والاستغفار، فإن تسبيحه -جل وعلا- وسؤاله، والضراعة إليه، وقراءة كتابه عن إيمان، وعن قصد صالح، وعن تدبر في ذلك من التسبيح لله، والتنزيه له الخير العظيم.","link":"https://binbaz.org.sa/fatwas/1605/معنى-قوله-تعالى-وسبح-بحمد-ربك-قبل-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_499.mp3","categories":["التفسير"]},{"id":6164,"question":"إذا كان علماء الإسلام من السابقين، والمعاصرين لم يحيطوا بتفسير القرآن الكريم علمًا، فكيف يترجمونه إلى اللغات الأعجمية؟","title":"حكم ترجمة معاني القرآن مع عدم الإحاطة بتفسير القرآن","answer":"الجواب: يترجموا ما ظهر لهم، ما أحد يستطيع أن يقول: إنه أحاط علمًا بما في كتاب الله، وإنما يترجم ما يسر الله له، ففوق كل ذي علم عليم، فكل مفسر، وكل مترجم على حسب ما أعطاه الله من العلم يفسر، ويترجم، إذا كان عنده علم، ويجتهد، ويتقي الله، ولا يلزم من هذا أن يكون محيطًا، ولا يلزم من هذا أن يُمنع، كل حسب ما أعطاه الله من العلم، ولو قيل: لا تترجم، ولا تفسر، ولا يتكلم إلا من أحاط علمًا بالقرآن، والسنة، ما استفاد أحد.","link":"https://binbaz.org.sa/fatwas/1619/حكم-ترجمة-معاني-القران-مع-عدم-الاحاطة-بتفسير-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_510.mp3","categories":["التفسير"]},{"id":6372,"question":"قال تعالى: وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا [يوسف:24] إلى آخر الآية، فقال بعضهم: هم بضربها، وقال آخرون غير ذلك، نرجو توضيح الأمر؟","title":"معنى قوله تعالى: (وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا)","answer":"الجواب: الصواب أنه هم بها نفسها للوقوع بها، لا بضربها، وهمت به كذلك، يعني هم كل منهما بالآخر للجماع المحرم، والزنا، ولكن الله حفظه، وعصمه؛ لأنه من عباد الله المخلصين، والحمد لله -عليه الصلاة والسلام- والهم بالسيئة لا يؤاخذ عليها، إنما يؤاخذ بفعلها. ثبت عن رسول الله -عليه الصلاة والسلام،- أنه قال: إذا هم الرجل بالحسنة، فلم يفعلها؛ كتب الله له حسنة، وإذا هم بالسيئة، فتركها من جراء الله؛ كتبها حسنة إذا هم بالسيئة، ثم تركها من خوف الله، كتبها الله له بها حسنة، فيوسف من هذا الباب، هم، ثم تركها من أجل الله، فكتبها الله له بها أجرًا .","link":"https://binbaz.org.sa/fatwas/1959/معنى-قوله-تعالى-ولقد-همت-به-وهم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_746.mp3","categories":["التفسير"]},{"id":6382,"question":"قال تعالى: وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا [يوسف:24] إلى آخر الآية، فقال بعضهم: هم بضربها، وقال آخرون غير ذلك، نرجو توضيح الأمر؟","title":"معنى قوله تعالى: (وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا)","answer":"الجواب: الصواب أنه هم بها نفسها للوقوع بها، لا بضربها، وهمت به كذلك، يعني هم كل منهما بالآخر للجماع المحرم، والزنا، ولكن الله حفظه، وعصمه؛ لأنه من عباد الله المخلصين، والحمد لله -عليه الصلاة والسلام- والهم بالسيئة لا يؤاخذ عليها، إنما يؤاخذ بفعلها. ثبت عن رسول الله -عليه الصلاة والسلام،- أنه قال: إذا هم الرجل بالحسنة، فلم يفعلها؛ كتب الله له حسنة، وإذا هم بالسيئة، فتركها من جراء الله؛ كتبها حسنة إذا هم بالسيئة، ثم تركها من خوف الله، كتبها الله له بها حسنة، فيوسف من هذا الباب، هم، ثم تركها من أجل الله، فكتبها الله له بها أجرًا .","link":"https://binbaz.org.sa/fatwas/1959/معنى-قوله-تعالى-ولقد-همت-به-وهم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_746.mp3","categories":["التفسير"]},{"id":6536,"question":"ما معنى قول الله تعالى: وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ [الزخرف:36] إلى آخر الآية؟","title":"ما معنى: {وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا}؟","answer":"الجواب: الآية على ظاهرها، ما تحتاج تفسير، واضحة وَمَنْ يَعْشُ من يغفل، ويعرض عَنْ ذِكْرِ الرَّحْمَنِ يقيض له الشيطان -نسأل الله العافية- من غفل عن ذكر الله، وعن قراءة القرآن، وعن طاعة الله من الصلوات، وغيرها؛ قيض الله له الشياطين حتى تصده عن الحق، وحتى تلهيه في الباطل -نعوذ بالله- ومن قام بأمر الله، وأدى حق الله، واستعمل نفسه في ذكر الله، وطاعة الله؛ عافاه الله من الشيطان، وحفظه من الشياطين، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2387/ما-معنى-ومن-يعش-عن-ذكر-الرحمن-نقيض-له-شيطانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_920.mp3","categories":["التفسير"]},{"id":6651,"question":"معلوم من السنة أن الرسول ﷺ قد سحر، ولكن بعض المسلمين يلبس عليه بعض التساؤلات، والشبهات كيف يسحر الرسول، والله يقول له: وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ [المائدة:67]؟ وكيف يسحر وهو يتلقى الوحي عن ربه، ويبلغ ذلك المسلمين؟ فكيف يبلغ وهو مسحور، وقول الكفار، والمشركين: إِنْ تَتَّبِعُونَ إِلَّا رَجُلًا مَسْحُورًا [الإسراء:47] نرجو إيضاح وبيان هذه الشبهات؟","title":"الجمع بين: سحر النبي، وبين: {وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ}","answer":"الجواب: هذا ثبت في الحديث الصحيح أنه في المدينة بعدما استقر الوحي، واستقرت الرسالة، وقامت دلائل النبوة، وصدق الرسالة، ونصره الله على المشركين، وأذلهم، تعرض له بعض اليهود، يقال له: لبيد بن الأعصم، تعرض له بعض اليهود بأشياء؛ صار يخيل إليه أنه فعل بعض الشيء ولم يفعله، ولكن لم يزل -بحمد الله- لا عقله، ولا شعوره، ولا تمييزه، بل يحدث الناس ويكلم الناس، لكن إن أحس بشيء؛ أثر عليه بعض الأثر، كما قالت عائشة -رضي الله عنها-: إنه كان ربما يخيل إليه أنه فعل الشيء في البيت مع أهله، ولم يفعله، فجاءه الوحي من ربه  بطريق جبرائيل، وأخبروه بما وقع، فبعث من استخرج ذلك الشيء من بئر في محل الأنصار، وأزيل، وزال عنه ذلك بحمد الله، ولم يترتب على ذلك شيء مما يضر الناس، أو يخل بالرسالة، أو بالوحي، والله -جل وعلا- عصمه من الناس كما أخبر  مما يمنع من الرسالة، وتبليغ الرسالة. أما ما يصيب الرسل -كما أصاب من قبله- فقد أصابه مثل ما أصاب من قبله، وقد جرح يوم أحد، وكسرت البيضة على رأسه، ودخلت حلقات المغفر في وجنته -عليه الصلاة والسلام- وسقط في بعض الحفر التي هناك، وقد ضيقوا عليه في مكة تضيقًا شديدًا، وآذوه أذى كثيرًا، فقد أصابه شيء مما كتب الله عليه، ورفع الله به درجاته، وأعلى به مقامه، وضاعف في حسناته، ولكن الله عصمه منهم، فلم يمنعه من تبليغ الرسالة، ولم يقتلوه، ولم يحولوا بينه وبين الرسالة، بل بلغ الرسالة، وأدى الأمانة عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/2529/الجمع-بين-سحر-النبي-وبين-والله-يعصمك-من-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1024.mp3","categories":["شروح الحديث","التفسير"]},{"id":6662,"question":"قال تعالى: وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ [النساء:129] فهل نفهم من الآية عدم العدل، ونفيه، والاكتفاء بزوجة واحدة، أم ماذا نفهم من الآية؟","title":"ما معنى: {وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ}؟","answer":"الجواب: الله قال بعدها: فَلَا تَمِيلُوا كُلَّ الْمَيْلِ فَتَذَرُوهَا كَالْمُعَلَّقَةِ [النساء:129] المقصود أن الإنسان يتحرى العدل، ويجتهد في العدل، وقد يفوته بعض الشيء، فالذي لا يستطيعه يعفو الله عنه، من اجتهد، وبذل وسعه، واتقى الله، فما عجز عنه؛ معفو عنه فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] لا مع واحدة، ولا مع الجماعة، عليه أن يتقي الله، ويعدل في حق المرأة، ويعطيها حقها بنفقتها، وإحسان الخلق معها، الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] بعض الناس والعياذ [بالله] فظ غليظ، وعنيف، لا يحسن الخلق مع زوجته، ولا يكلمها كلامًا طيبًا، بل هو دائم العبوس، ودائم التغير، ودائم الأذى، ودائم السباب، والشتام، هذا شره كبير -والعياذ بالله- ولو ما معه إلا واحدة، كيف إذا كان معه جماعة؟! المقصود: أن الواجب عليه العشرة بالمعروف، الله يقول: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] فلا بد من المعاشرة الطيبة، وإذا بذل وسعه، واتقى الله، فالشيء الذي يغلبه يعفو الله عنه.","link":"https://binbaz.org.sa/fatwas/2570/ما-معنى-ولن-تستطيعوا-ان-تعدلوا-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1065.mp3","categories":["التفسير"]},{"id":6663,"question":"عندما ننصح بعض المنتسبين إلى العلم أنه لا بد أن نفرق بين مشيئة الله، وفعل الله، ثم مشيئته أيضًا، وفعله كما تقول: هذا من فضل الله، ثم من عملي، أو من فعل فلان، ولكنهم ردوا علينا بهذه الشبه، وهي قول الله تعالى: وَقَالُوا حَسْبُنَا اللَّهُ سَيُؤْتِينَا اللَّهُ مِنْ فَضْلِهِ وَرَسُولُهُ [التوبة: 59] فلم يفصل بين الله، ورسوله؟","title":"ما المقصود بالعطف في: {سَيُؤْتِينَا اللَّهُ مِنْ فَضْلِهِ وَرَسُولُهُ}؟","answer":"الجواب: هذا الإتيان من الله، ورسوله، هذا لأن الإتيان من الله ورسوله، فالله -جل وعلا- يعطي، والرسول -هو النائب في هذا- هو يعطي بأمر الله، أمره الله أن يعطي من بيت المال ما شاء  وقال: إِنَّا إِلَى اللَّهِ رَاغِبُونَ [التوبة:59] ولا قال إلى الرسول، فالإتيان من الله، ومن الرسول، وأما الحسب فهو لله، حسبنا الله، وإلى الله الرغبة  أما الإيتاء فالله يعطي، والرسول يعطي بأمر الله من بيت المال، ومما أعطاه الله من الأمور، فإذا قال: آتانا الله ورسوله، أو آتانا الرسول كذا، أو أعطانا كذا، فلا حرج في ذلك؛ لأن الإيتاء من الرسول إيتاء من الله؛ لأن الله أمره.","link":"https://binbaz.org.sa/fatwas/2533/ما-المقصود-بالعطف-في-سيوتينا-الله-من-فضله-ورسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1028.mp3","categories":["التفسير"]},{"id":6677,"question":"يقول تعالى: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3] ويقول في آية أخرى: وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ [النساء:129] فما تفسير ذلك؟","title":"الجمع بين آية التعدد وبين: {وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا}","answer":"الجواب: تقدم الجواب عن هذا، وأن الاستطاعة لا يمكن أن يقوم الإنسان بذلك، لكن عليه المستطاع، عليه ما يقدر، أما الحب -حب الإنسان في قلبه- فقد يحب هذه أكثر، وقد يجامع هذه أكثر، وقد يأنس بكلامها أكثر، فليس الأمر بيده، هذا يتعلق بالقلوب، وكان النبي يقسم بين نسائه -عليه الصلاة والسلام- ويقول: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك، ولا أملك هكذا يقول النبي ﷺ قال العلماء: معناها الحب، والمودة، وما ينشأ عن ذلك ، هذه أمور بيد الله.","link":"https://binbaz.org.sa/fatwas/2574/الجمع-بين-اية-التعدد-وبين-ولن-تستطيعوا-ان-تعدلوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1069.mp3","categories":["تعدد الزوجات","التفسير"]},{"id":6730,"question":"ما المقصود بالذكر الذي ورد في قوله تعالى: وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكًا [طه:124]؟","title":"المقصود بالذكر في قوله تعالى: (وَمَنْ أَعْرَضَ عَنْ ذِكْرِي)","answer":"الجواب: يعني القرآن، ذكر الله القرآن، وما صحت به السنة، فمن أعرض عن الكتاب العزيز، والسنة المطهرة؛ ناله هذا الوعيد، -نعوذ بالله- فالواجب على المؤمن أن يتقي الله، ويأخذ بذكر الله، ويعمل به، ويستعين بالله على ذلك، ومن ذلك سنة النبي ﷺ فإنها تفسر الذكر، وتوضح معناه، فهي من الذكر المنزل على النبي -عليه الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/2610/المقصود-بالذكر-في-قوله-تعالى-ومن-اعرض-عن-ذكري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1106.mp3","categories":["التفسير"]},{"id":6954,"question":"والدي يكنز أموالاً كثيرة، فضة، وورق، ولا يخرج زكاتها، علمًا بأني أنصحه، وأحذره من عذابها، ولكنه لم يسمع، وهو بخيل فيما أرى -والعلم عند الله- ما هو الذي يجب علي نحو والدي؟ كيف يخرج زكاتها وهي لها مدة ثلاثين سنة؟ كيف أقنعه حتى يزكيها؟ هل إذا أراد مني فلوسًا أعطيه، أم أرفض، علمًا أنه يريد كنزها؟ هل على والدتي ذنب إذا أخذت من ماله وهو لا يعلم، علمًا بأنه لا يرضى لشدة بخله -والعياذ بالله-؟","title":"نصيحة إلى من يكنز المال ولا يزكيه","answer":"الجواب: عليك أن تنصحه دائمًا بالكلام الطيب، والأسلوب الحسن؛ حتى يؤدي الزكاة، وإذا استعنت على هذا بأعمامك، وأخوالك حتى ينصحوه طيب، تقول لأخوالك وأعمامك وجيرانك الطيبين ينصحونه بالكلام الطيب، والأسلوب الحسن؛ لعل الله يهديه حتى يخرج الزكاة. وإذا كنت مليًّا تقول: يا أبي أنا أخرج عنك الزكاة، وإذا سمح لك؛ تؤدي عنه -وليس هذا بكثير في بر والدك- إذا سمح لك، وأنت ذو مال؛ تؤدي عنه، كالوكيل من مالك، ولا بأس، وتكون محسنًا في ذلك، فإن مات، ولم تؤدوا عنه، ولم يؤد؛ تؤدونها بعد الموت، تؤدون زكاتها بعدد السنين التي مضت من هذا المال المكنوز، تؤدونه عنه. وإذا أمكن أن يرفع أمره إلى المحكمة حتى تلزمه بذلك -إذا كان عندكم بينة على هذا- ورفعتم أمره إلى المحكمة حتى تلزمه؛ هذا لا بأس به، بل يجب رفع أمره حتى تلزمه المحكمة بأداء الواجب من زكاة ماله، أو هيئة الأمر بالمعروف. هذا من التعاون على البر والتقوى، لكن دون الشكوى، التعاون مع أخوالك، وأعمامك، وإخوتك الكبار، ومن يعزهم أبوك، تتعاونوا بالكلام الطيب، والأسلوب الحسن؛ حتى يزكي، يكون أولى من شكواه إلى المحكمة، وأحسن، وإذا استطعت أنت أن تزكي عنه من مالك بإذنه؛ فهذا أطيب، وأطيب.","link":"https://binbaz.org.sa/fatwas/2884/نصيحة-الى-من-يكنز-المال-ولا-يزكيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1332.mp3","categories":["التفسير","صدقة التطوع","مسائل متفرقة في الزكاة"]},{"id":6996,"question":"إنني شخص غير معتدل في حياتي، بحيث أعمل المعاصي وأتوب، وكلما مريت على معصية عملتها وأتوب بعدها، وعلى هذا الحال استمريت أكثر من نصف عمري، وفي النهاية عدت إلى رشدي، وتبت إلى الله، عسى الله أن يقبلها، وسؤالي هو: قول الله تعالى من سورة النساء: إِنَّ الَّذِينَ آمَنُوا ثُمَّ كَفَرُوا ثُمَّ آمَنُوا ثُمَّ كَفَرُوا ثُمَّ ازْدَادُوا كُفْرًا لَمْ يَكُنِ اللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًا[النساء:137] هل المقصود بهذه الآية الذي يتوب، ثم يعود، أفيدونا جزاكم الله خيرًا؟","title":"معنى قوله تعالى: (إِنَّ الَّذِينَ آمَنُوا ثُمَّ كَفَرُوا..)","answer":"الجواب: \n\nالآية الكريمة فيها ذم هؤلاء، وتحذيرهم، وبيان أن الله لا يغفر لهم، وقد فسر العلماء أن ثُمَّ ازْدَادُوا كُفْرًا [آل عمران:90] أي ثم استمروا في الكفر حتى الموت، يعني استمروا في الكفر، وزاد كفرهم حتى اتصل بالموت، فماتوا على كفرهم، وضلالهم؛ فلن يغفر الله لهم -نسأل الله العافية-. \n\nأما من تاب بعد كفره، فالله يتوب عليه، وهكذا بعد معصيته التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله، قال الله : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] والنبي  قال: التوبة تهدم ما كان قبلها، والإسلام يهدم ما كان قبله، فمن تاب بعد معاصيه، ولو كثرت، أو بعد كفره ولو كثر توبة صادقة نصوحًا، واستقام عليها حتى الموت؛ غفر الله له  حتى تطلع الشمس من مغربها، باب التوبة مفتوح إلى طلوع الشمس من مغربها -نسأل الله السلامة-.\n\nفعليك يا عبدالله أن تلزم التوبة، وإذا منَّ الله عليك بالتوبة فاحمد الله على ذلك، والزمها، لا تتابع الهوى، ولا تطع دعاة الباطل، وعلى رأسهم الشيطان، ولكن الزم التوبة، واحمد الله على ما من عليك به من التوبة، واحذر أن تعود إلى الفساد، والشر بعدما هداك الله للتوبة.","link":"https://binbaz.org.sa/fatwas/2905/معنى-قوله-تعالى-ان-الذين-امنوا-ثم-كفروا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1353.mp3","categories":["التفسير"]},{"id":7030,"question":"يقول الله تعالى: لَا إِكْرَاهَ فِي الدِّينِ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ [البقرة:256] إلى آخر الآية، وقال الأنصار: بايعنا الرسول ﷺ على السمع والطاعة في المنشط والمكره، كيف نوفق بين الإكراه في الحالتين؟","title":"الجمع بين: {لَا إِكْرَاهَ فِي الدِّينِ} و«الطاعة في المنشط والمكره»","answer":"الجواب:\n\nما بينهما اختلاف، بايع الرسول ﷺ على السمع والطاعة في كل أمورهم، في منشطهم ومكرههم وعسرهم ويسرهم أن يسمعوا ويطيعوا، ما هو معناه في الإكراه، معناه: أنهم يسمعون ويطيعون، ولو كان هذا الشيء يكرهونه، ويشق عليهم لأجل فقرهم، أو لأجل أسباب أخرى، متى أمر الرسول ﷺ أطاعوه وإن كان شيئًا قد يضرهم، ما عندهم مال ينفقون، ما عندهم مطايا، ما عندهم كذا، يكرهون من جهة الكراهة الطبيعية، من جهة المشقة الطبيعية، لا من جهة الإكراه.\n\nالإكراه شيء آخر، الإكراه كونه يضرب على هذا، أو يهدد بهذا الشيء أنه يفعله، وهو غير مشروع، هذا هو الإكراه، أما كونه يطيع ولي الأمر في منشطه وفي مكره، وفي عسره ويسره، طاعة لله، ومحبة لشرع الله، هو مشكور، ولو أطاعه وهو يمشي على رجليه في الجهاد مشكور بهذا؛ لأنه يريد فضل الله وثوابه .\n\nومعنى لَا إِكْرَاهَ فِي الدِّينِ [البقرة:256] تفسر بمعنيين:\n\nأحدهما: أن هذا كان قبل الجهاد، كان الناس لا يكرهون من دخل في الإسلام قبل، ومن أبى لا يقاتل، هذا أول الأمر، ثم شرع الله الجهاد للمسلمين، فمن دخل في الإسلام وإلا جوهد وقوتل؛ حتى يدخل في الإسلام أو يؤدي الجزية إن كان من أهلها، هذا قول.\n\nوالقول الثاني: معناه لا إكراه في الدين بالنسبة إلى أهل الجزية من اليهود والنصارى والمجوس، لا إكراه عليهم، بل يلزمون بالإسلام، أو بالجزية، فهي آية مطلقة، مخصوصة بآية الجزية، وأدلة الجزية، فمعنى لا إكراه في الدين لأهل الكتاب والمجوس إذا أدوا الجزية؛ فلا يكرهون، بل تقبل منهم الجزية، ويقرون على دينهم حتى يهديهم الله  فالمعنيان معروفان عند أهل العلم. \n\nالمعنى الأول: أن هذا كان قبل شرع الجهاد، يعني لا إكراه، إذا اعتزلونا ولم يقاتلونا؛ اعتزلناهم ولم نقاتلهم، هذا في أول الأمر في مكة، وفي أول الهجرة، من قاتل قتلناه، ودافعنا، ومن لم يقاتل لم ندفعه، ولم نكرهه، هذا في أول الأمر. \n\nثم شرع الله الجهاد، وأمر رسوله بالجهاد وقال الله في ذلك فَإِذَا انْسَلَخَ الْأَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ فَإِنْ تَابُوا وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] هذا آخر الأمر، أمرنا بالجهاد، وألا نتركهم حتى يدخلوا في دين الله إلا من يؤدي الجزية، فإذا بذل الجزية، وأعطى الجزية عن يد؛ قبلناها منه.","link":"https://binbaz.org.sa/fatwas/3017/الجمع-بين-لا-اكراه-في-الدين-والطاعة-في-المنشط-والمكره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1424.mp3","categories":["التفسير","شروح الحديث"]},{"id":7349,"question":"سمعت بعضهم يقول لماذا قال الله تعالى: وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ [البقرة:117] لماذا لم يقل كن فكان؛ لأنه قد مضى هذا الأمر؟","title":"ما معنى: {إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ}؟","answer":"الجواب: إذا قضى أمرًا يعني: إذا أراد أمرًا، سبق بعلمه أنه يكون، قال له: كن قبل أن يكون، ثم يكون بعد قوله الله له، كن فيكون، ما هو كن فكان لا، كن فيكون بعد أمر الله له.","link":"https://binbaz.org.sa/fatwas/3440/ما-معنى-اذا-قضى-امرا-فانما-يقول-له-كن-فيكون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1747.mp3","categories":["التفسير"]},{"id":7353,"question":"يُشْكلُ على كثير من الناس فهم هذه الآية، فنرجو من سماحتكم بيان معناها يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ [الرعد:39]؟","title":"ما معنى: {يَمْحُوا اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَاب}؟","answer":"الجواب: العلماء تكلموا في هذه الآية، وبينوا معناها، وأنها تعم أشياء كثيرة، تعم الذنوب والحسنات، يمحو الله ما يشاء من الذنوب والسيئات، ويبقي ما يشاء  على حسب حال العبد، فإذا أطاع الله -جل وعلا- واستقام على أمره؛ كتب الله له حسنات، ومحا عنه السيئات، وإذا تاب إلى الله؛ محا عنه السيئات.  وهكذا يمحو الله ما يشاء من الشرائع، وينسخها، ويثبت ما يشاء في وقت الرسول الذي بعثه الله، مثلما شرع الله لنا أولًا استقبال بيت المقدس، ثم شرع الله بعد ذلك أن نستقبل الكعبة، يمحو الله ما يشاء، ويثبت  من الشرائع، ومن الذنوب، والأوامر، والنواهي.  وقال بعضهم: هكذا بعض الأقدار المعلقة يمحو الله ما  يشاء من الأقدار المعلقة، ويثبت، أما الأقدار التي ما فيها حيلة قد سبق فيها علمه أنها تكون، فهذه ما تمحى، بل هي ثابتة، مثل الموت، ما أحد يسلم من الموت، هذا قدر سابق أنه لا بد منه، وكذلك الهرم لا بد منه لمن كتب الله له البقاء، لا بد ينتهي إلى الهرم، وفي الحديث: ما من داء إلا له دواء إلا الهرم وفي اللفظ الآخر: إلا الموت.","link":"https://binbaz.org.sa/fatwas/3441/ما-معنى-يمحوا-الله-ما-يشاء-ويثبت-وعنده-ام-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1748.mp3","categories":["التفسير"]},{"id":7360,"question":"سمعت بعضهم يقول لماذا قال الله تعالى: وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ [البقرة:117] لماذا لم يقل كن فكان؛ لأنه قد مضى هذا الأمر؟","title":"ما معنى: {إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ}؟","answer":"الجواب: إذا قضى أمرًا يعني: إذا أراد أمرًا، سبق بعلمه أنه يكون، قال له: كن قبل أن يكون، ثم يكون بعد قوله الله له، كن فيكون، ما هو كن فكان لا، كن فيكون بعد أمر الله له.","link":"https://binbaz.org.sa/fatwas/3440/ما-معنى-اذا-قضى-امرا-فانما-يقول-له-كن-فيكون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1747.mp3","categories":["التفسير"]},{"id":7363,"question":"إذا كان معنى الولاء هو الحب والقرب، فهل يكون هو معنى الولاء المذكور في الآية الكريمة: وَالَّذِينَ آمَنُوا وَلَمْ يُهَاجِرُوا مَا لَكُمْ مِنْ وَلَايَتِهِمْ مِنْ شَيْءٍ حَتَّى يُهَاجِرُوا [الأنفال: 72] فهل ينهى الله عن ولاية المؤمنين الذين لم يهاجروا؟","title":"ما معنى: {وَالَّذِينَ آمَنُوا وَلَمْ يُهَاجَرُوا مَا لَكُمْ مِنْ وَلايَتِهِمْ}؟","answer":"الجواب: الولاية تطلق على القُرب، فلان مولى فلان، يعني: قريبه يَوْمَ لَا يُغْنِي مَوْلًى عَنْ مَوْلًى شَيْئًا [الدخان:41] يعني قريب عن قريبه، وتطلق الولاية على الحب، والمجاملة، والمناصرة، ونحو ذلك، يقال: فلان والى فلانًا، يعني: نصره، وأيده، وأحبه.  والمراد بهذا النهي عن المحبة والنصرة، أما القرابة ما تضره، قرابته لو كان أخاه أو كان أباه أو كان ابنه ما يضره، المهم أن يبغضه في الله ولا يضره، ما ضر النبي ﷺ كون أبي لهب عمه وكون أبي طالب عمه، وهو قد ماتا على الكفر والضلال. ولا ضر إبراهيم كون أبيه كافرًا، ما ضر إبراهيم. المقصود: الضرر في موالاتهم ومحبتهم، أما قراباتهم ما تضر الإنسان، الذي يضره أن يواليهم، ويحبهم وهم على كفرهم، وضلالهم.","link":"https://binbaz.org.sa/fatwas/3448/ما-معنى-والذين-امنوا-ولم-يهاجروا-ما-لكم-من-ولايتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1754.mp3","categories":["التفسير"]},{"id":7416,"question":"نرجو من سماحة الوالد إعادة شرح قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6] إلى آخر الآية، كما قمتم بشرحها في مسجد الرئاسة، وجزاكم الله خيرًا؟","title":"تفسير قوله تعالى: (يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ)","answer":"الجواب: هذه الآية العظيمة لها شأن عظيم، وهي قوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ عَلَيْهَا مَلَائِكَةٌ غِلَاظٌ شِدَادٌ لَا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ [التحريم:6] الله سبحانه يأمر المؤمنين أن يقوا أنفسهم وأهليهم عذاب الله ، وإن كان جميع الناس مأمورين بهذا، لكن المؤمنين لهم خصوصية؛ لأنهم أعلم الناس بالله، وأقومهم بحقه، وأرعاهم لحدوده، فلهذا خاطبهم كثيرًا سبحانه بالأوامر التي يأمر بها فيقول: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا [الأحزاب:70]، يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ [آل عمران:102]، يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ [التوبة:119] في آيات كثيرة.  ويقول هنا: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6] وفي مواضع أخرى يأمر الناس؛ لأن الناس كلهم خلقوا ليعبدوا الله، وليمتثلوا أمره، وليحذروا عذابه، فيقول سبحانه: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا [النساء:1] هذا عام للكفار والمسلمين جميعًا، والنفس الواحدة أبونا آدم، خلقه الله من التراب، وخلق منها زوجها -زوجته حواء- خلقت منه، وهذا من آيات الله  وهو على كل شيء قدير. فيأمر الناس جميعًا أن يتقوا الله، فالكافر من تقوى الله أن يدخل في الإسلام، وأن يعتنق الإسلام، ويستقيم عليه، والمؤمن من تقوى الله أن يلزم التقوى ويستقيم عليها ويثبت عليها حتى الموت. ويقول: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظِيمٌ [الحج:1] يذكرهم بالساعة، يذكرهم بقيامها، وأنه لا بد منها، فيأمر الناس جميعًا كافرهم ومسلمهم أن يتقوا الله، ويقول: يَا أَيُّهَا النَّاسُ اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ هَلْ مِنْ خَالِقٍ غَيْرُ اللَّهِ [فاطر:3]، ويقول: يَا أَيُّهَا النَّاسُ إِنَّ وَعْدَ اللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا وَلَا يَغُرَّنَّكُمْ بِاللَّهِ الْغَرُورُ [فاطر:5].  ويقول: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]، ويقول سبحانه: يَا أَيُّهَا النَّاسُ أَنْتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ [فاطر:15]، ويقول: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا لَا يَجْزِي وَالِدٌ عَنْ وَلَدِهِ وَلَا مَوْلُودٌ هُوَ جَازٍ عَنْ وَالِدِهِ شَيْئًا إِنَّ وَعْدَ اللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا وَلَا يَغُرَّنَّكُمْ بِاللَّهِ الْغَرُورُ [لقمان:33] يعني الشيطان. فهذه الآيات فيها دعوة الناس إلى تقوى الله، والإيمان بما أخبر به، والاستقامة على دينه، والحذر من أن يغرهم الشيطان، أو تغرهم الدنيا بزهرتها وزينتها. وفي هذه الآية التي سئل عنها يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6] بماذا؟ بتقوى الله، وطاعة أمره، وترك نهيه  هذا طريق السلامة، إنما يقي العبد نفسه وأهله عذاب الله بالالتزام بالتقوى، والاستقامة على أمر الله، وترك محارم الله، وأن يقوم على أولاده، وأهل بيته وأقاربه، وخدمه الذين له سيطرة عليهم، وغير ذلك حتى يوصيهم بتقوى الله، حتى يأمرهم بتقوى الله، فعليك أيها المؤمن أن تقوم على نفسك وأن تجاهدها لله. وهكذا أهل بيتك من زوجة وولد، من ذكر وأنثى، وأخوات وغيرهم ممن في بيتك من أهلك، تقوم عليهم، وتوجههم إلى الخير، وتلزمهم بأمر الله، وتكفهم عن محارم الله، وبهذا تقيهم عذاب الله، وهذه النار وقودها الناس والحجارة، فاحذر أن تكون من هؤلاء الناس أنت وأهلك. ثم يذكر ويقول سبحانه: عَلَيْهَا مَلَائِكَةٌ غِلَاظٌ شِدَادٌ [التحريم:6] ما في طمع أنهم يرحمونك إذا أمر بك إلى النار، ما في طمع متى جاءت الأوامر من الله  لك ولأهلك بالنار، فإن هؤلاء الملائكة لا يرحمونك، ولا يرحمونهم، بل لا بد من التنفيذ، ثم هم مع ذلك لَا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ [التحريم:6] ما في رشوة ولا مداهنة، حراس الدنيا حراس السجون قد يرحمون، قد يأخذون الرشوة، ويطلقون السجين، لكن هؤلاء الملائكة لا، هؤلاء الملائكة مأمورون بإنفاذ الأوامر لَا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ [التحريم:6].  وهم غلاظ شداد لا قدرة لك على التخلص منهم، ولا التملص منهم، فمن أمر به إلى النار؛ فهو إليها، ولا حول ولا قوة إلا بالله، فالواجب الحذر اليوم، وأن تقي نفسك وأهلك من هذا البلاء العظيم، وأنت بحمد الله قد يسر لك الأمر، وبلغت الطريق، وعلمت ما هو السبيل، وهو أن تلزم توحيد ربك، والإخلاص له في عبادتك، واتباع رسوله ﷺ والاستقامة على ما جاء به من فعل الأوامر، وترك النواهي، والوقوف عند حدود الله حتى تلقى ربك، حتى الموت وأنت على ذلك، كما قال الله لنبيه ﷺ: وَاعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِينُ [الحجر:99] يعني الموت، قال في الآية الأخرى: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ [آل عمران:102].  يعني الزموا التقوى، يعني استقيموا عليها ولو عمرت ألف عام فاستقم حتى يأتيك الموت، لا تمل هكذا ولا هكذا، استقم على أداء الفرائض، وترك المحارم، والوقوف عند حدود الله ما دمت حيًا تعقل حتى تلقى ربك، هذا هو طريق النجاة، وهذا هو معنى الآية يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6].  قال بعض السلف: معنى ذلك: اتقوا الله، وأوصوهم بتقوى الله، وقال بعضهم: علموهم وأدبوهم، والمعنى متقارب، المعنى خذوا على أيديهم، وجوههم إلى الخير، ألزموهم بالحق، حذروهم من الباطل؛ حتى يستقيموا على هدى الله -جل وعلا- رزق الله الجميع التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/3481/تفسير-قوله-تعالى-يا-ايها-الذين-امنوا-قوا-انفسكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1785.mp3","categories":["التفسير"]},{"id":7477,"question":"هذه رسالة أرسلتها الأخت في الله (ع. ع) من السودان، تقول في رسالتها -هي أرسلت عدة أسئلة- السؤال الأول: يقول الله  في كتابه العزيز: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنََّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] تقول: أرجو توضيح معنى الآية، وخاصة في قوله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا [النور:31]؟","title":"معنى قوله تعالى: (وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ ...)","answer":"الجواب: الآية تكلم عنها أهل العلم، وبينوا أنه لا يجوز لها مد النظر إلى الرجال، بل عليها أن تغض بصرها، كما على الرجل أن يغض بصره عن النساء؛ لأن هذا قد يعرض الجميع للفتنة، وهذا النظر الذي يقصد أو يكون عن شهوة، أما النظر العابر الذي تنظر به إلى الطريق وإلى الناس في الطريق من غير قصد معين، فهذا لا يضر.  وهكذا الرجل ينظر إلى الطريق وينظر إلى النساء المارات في الطريق من غير قصد النظر إليهن وإلى زينتهن، وإنما القصد العبور في الطريق أو في المسجد أو ما أشبه ذلك، وبالأخص إذا كان لشهوة فإنه يحرم جداً، نظره إليها بشهوة أو نظرها إليه بشهوة؛ لأن هذا وسيلة الفتنة، وإذا كان بغير شهوة فلا يقصد ولا يدام. أما النظر العابر فلا يضر، وأما النظر الدائم الذي يحصل تعمده وقصده فهذا يخشى منه أن يجر إلى الشهوة فيمنع، بخلاف النظر العابر الذي لا يقصد فلا يضر، أو الفجأة الذي يفجأ الإنسان، ينظر إليها فجأة وهي كاشفة، فيصرف بصره ولا يضره ذلك، كذلك هي تصرف بصرها ولا تمد نظرها إلى الرجال وتغض بصرها، وإن كان لشهوة حرم بكل حال.\nوأما قوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] فالزينة: هي ما يظهر منه الفتنة، .......الفتنة من إظهار الشعر أو القلادة أو الوجه أو الصدر أو العضد أو الذراع أو اليد أو الكف أو القدمين أو الخلخال أو ما أشبه ذلك مما يفتن الناس، هذه الزينة، زينتها ما خلق الله فيها من الجمال كالوجه؛ جمال الوجه واليد والرأس ونحو ذلك، وهكذا ما تلبسه من الزينة؛ من قلادة، ومن أخراص في الأذنين، ومن خلاخل في الساقين، وما أشبه ذلك، فإن هذه كلها تسمى زينة. زينة متصلة: وهي الجمال، وزينة منفصلة: وهي ما تلبسه المرأة من الحلي في العنق والأيدي وأشباه ذلك، فهذه أشياء لا تبديها للرجال؛ لأنها تفتن الرجل، وقوله: إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] الشيء المعتاد؛ الملابس المعتادة التي لا تقصد للفتنة، فلا بأس بالنظر إليها؛ الملابس المعتادة، لا بأس بإبدائها، كالعباءة، .............. الذي عليها تمشي فيه، فينبغي ألا يكون ذلك فاتناً، يكون عادياً، ملابس عادية ليس فيها فتنة. نعم.","link":"https://binbaz.org.sa/fatwas/4322/معنى-قوله-تعالى-وقل-للمومنات-يغضضن-من-ابصارهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_004/00402.mp3","categories":["التفسير"]},{"id":7593,"question":"سماحة الشيخ: عبد العزيز ! في الأسبوع الماضي لما أجرينا معكم بعض الأسئلة والاستفسارات كان معنا رسالة للمستمعة (م. أ. ع) من تعز وبقي منها سؤال حول حديث من أحاديث المصطفى صلى الله عليه وسلم تقول: عن ما معنى الحديث التالي: عن ابن عباس رضي الله عنهما قال: قال رسول الله ﷺ: الفجر فجران؛ فجر يحرم الطعام وتحل فيه الصلاة، وفجر تحرم فيه الصلاة - أي: صلاة الصبح - ويحل فيه الطعام رواه ابن خزيمة، نرجو الإفادة عن معنى هذا الحديث، والسلام عليكم ورحمة الله وبركاته؟","title":"معنى قوله عليه الصلاة والسلام: (الفجر فجران...)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. \nأما بعد: \nهذا الحديث الصحيح عن رسول الله عليه الصلاة والسلام: الفجر فجران هذا معناه: أن الفجر الصادق هو الذي يستطيل الأفق ويعترض ويستنير ولا يزال يزيد نوره حتى يتضح الفجر، هذا هو الفجر الصادق الذي يحرم الطعام على الصائم وتحل فيه صلاة الفجر، أما الفجر الآخر الذي يستطيل في الأفق ويرتفع كذنب السرحان مستطيلاً ثم تعقبه الظلمة، فهذا يقال له: الفجر الكاذب، وهذا تحرم فيه الصلاة ويحل فيه الطعام للصائم؛ لأنه ليل، هذا الفرق بينهما، فالفجر الصادق فجر يستطيل في الأفق كجناحي الطائر، يعني يعترض ويمتد جنوباً وشمالاً حتى يزداد نوره ويتبين الفجر واضحاً، فهذا هو الفجر الصادق الذي يحرم فيه الطعام على الصائم وتحل فيه الصلاة لدخول وقتها. \nأما الفجر الكاذب فهو الذي يستطيل في الأفق يعني: يستطيل طولاً إلى جهة السماء كالعمود مستنيراً ثم يعقبه ظلمة، فهذا يقال له: الفجر الكاذب، الذي يغر الناس ويظنه بعض الناس الصبح وليس بالصبح، هذا الفجر لا تحل به الصلاة ولا يحرم به الطعام؛ لأنه فجر كاذب. نعم.","link":"https://binbaz.org.sa/fatwas/4646/معنى-قوله-عليه-الصلاة-والسلام-الفجر-فجران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02001.mp3","categories":["التفسير","شروح الحديث"]},{"id":7856,"question":"ونبدأ -يا سماحة الشيخ- برسالة المستمع (ح. س. م. س. غزواني) من بلغازي، ويسأل عن تفسير آية، يقول: ما تفسير قوله تعالى: إِنَّا عَرَضْنَا الأَمَانَةَ عَلَى السَّمَوَاتِ وَالأَرْضِ [الأحزاب:72] الآية؟","title":"ما معنى: {إِنَّا عَرَضْنَا الأَمَانَةَ عَلَى السَّمَوَاتِ وَالأَرْضِ}؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهذه الآية على ظاهرها، يخبر سبحانه أنه عرض الأمانة على السماوات والأرض والجبال يعني لحملها والأخذ بها، فأبين أن يحملنها وأشفقن منها وحملها الإنسان إنه كان ظلوماً جهولاً.\nوهذه الأمانة هي التكاليف التي كلف الله بها العباد من الأوامر والنواهي المتعلقة بحق الله والمتعلقة بحق العباد، فشأنها عظيم وخطرها كبير، وحملها الإنسان؛ لأنه كان ظلوماً جهولاً، هذا هو الغالب على بني آدم الظلم والجهل إلا من تعلم واستقام على أمر الله فخرج من حيز الجهل إلى العلم، ومن حيز الظلم إلى العدل والإنصاف والاستقامة، فالتكاليف كلها أمانات، الصلاة والزكاة والصيام، والحج، والجهاد، والأمر بالمعروف والنهي عن المنكر، والطهارة الصغرى والطهارة الكبرى، وغير ذلك مما أمر الله به ورسوله كلها أمانات، وهكذا ترك المحارم والحذر منها أمانة، الكف عن المحارم طاعة لله وتعظيماً لله من الأمانات، وهكذا أداء الودائع والرهون والعناية بها وصيانتها عن الأذى هي أمانة، فيجب على المؤمن أن يصونها وأن يؤديها كما أخذها من غير تفريط ولا إضاعة ولا عدوان، فمن قصر في شيء من ذلك فقد قصر في الأمانة وخانها، والخيانات تختلف بعضها أكبر من بعض، والله يقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27]، ومدح أهل الإيمان برعاية الأمانة فقال: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8]، هذا من وصف أهل الإيمان؛ لأن الله قال في أول الآيات: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، ثم ذكر صفات جليلة منها قوله سبحانه: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8]، فالواجب على المؤمن أن يرعى الأمانة والعهد، وأن يحذر الخيانة في جميع الأمانات، أمانات الله وأمانات عباده سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/5258/ما-معنى-انا-عرضنا-الامانة-على-السموات-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_055/05501.mp3","categories":["التفسير"]},{"id":7858,"question":"أيضاً يقول: ما تفسير قوله تعالى: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ [المؤمنون:5-6] الآية؟","title":"تفسير قوله تعالى: (وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ)","answer":"الجواب: هكذا، هذا من وصف المؤمنين في هذه الآيات، قال سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ ۝ وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ ۝ وَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ [المؤمنون:1-4] ثم قال سبحانه: )وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ( * )إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ( * )فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ( [المؤمنون:5-7]، فالمؤمن يحفظ فرجه عن الزنا والفواحش، ولا يأتي حاجته إلا من زوجته أو ملك يمينه، الزوجة معروفة، ملك اليمين: السرية التي يملكها بالشراء أو بالسبي وقت الجهاد الشرعي، أو يرثها، أو بالهبة، هذه هي ملك اليمين، الجارية التي يملكها بالملك الشرعي له أن يتسراها ويتصل بها كزوجته، فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ [المؤمنون:7] يعني ابتغى أن يقضي وطره وحاجته بالفرج من غير الزوجة وملك اليمين فهو عادي، يعني هو ظالم متعدي، ويؤخذ من هذا عند أهل العلم منع العادة السرية؛ لأنها خروج عن هذا السبيل وهي الاستمناء باليد، فهي محرمة وفيها مضار كثيرة فلا تجوز هذه العادة بل يجب أن تحارب وتترك، وليس للرجل أن يقضي وطره إلا من زوجته أو ملك يمينه على الوجه الشرعي، ثم هذه حاجة تقضى في الفرج في القبل لا في الدبر، لا يجوز أن تؤتى النساء في أدبارهن، لا الزوجة ولا ملك اليمين؛ لأن هذا من اللواط، وإنما تؤتى الزوجة في قبلها في حال الطهر لا في حال الحيض والنفاس بل في حال الطهر، فلا يجوز أن تؤتى في الحيض ولا في النفاس ولا حال كونها محرمة، ولا حال كونها صائمة صوماً مفترضاً، بل يجب أن يتجنب المؤمن ذلك وإنما يأتيها في وقت أباح الله له ذلك وهي طاهرة من الحيض والنفاس، ليست محرمة، ولا صائمة صوماً مفترضاً، فيقضي وطره من زوجته وملك يمينه، وليس له أن يأتيها في الدبر، وليس له أن يقضي وطره في الذكور وهو اللواط نعوذ بالله، كل هذا من المحرمات العظيمة، وإنما يقضي حاجته من زوجته في قبلها، وهكذا ..... ملك يمينه في غير الأوقات المحرمة، كالحيض والنفاس والإحرام وصيام الفرض. نعم.","link":"https://binbaz.org.sa/fatwas/5262/تفسير-قوله-تعالى-والذين-هم-لفروجهم-حافظون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_055/05502.mp3","categories":["التفسير"]},{"id":7860,"question":"له سؤال آخر -يا سماحة الشيخ- وأخير يقول فيه: ما تفسير غُلِبَتِ الرُّومُ [الروم:2]؟","title":"تفسير قوله تعالى: ( ألم غلبت الروم)","answer":"الجواب: على ظاهرها، الله يقول سبحانه وتعالى: بسم الله الرحمن الرحيم: الم ۝ غُلِبَتِ الرُّومُ ۝ فِي أَدْنَى الأَرْضِ وَهُمْ مِنْ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ ۝ فِي بِضْعِ سِنِينَ [الروم:1-4]، هذه حرب بين الروم وبين فارس أخبر الله سبحانه أنه غلب الروم في أدنى الأرض، ثم بعد غلبهم سيغلبون، يعني هذه حرب بين الروم وفارس كانت في عهد النبي صلى الله عليه وسلم فغلبت الروم أولاً، يعني تعدت عليها فارس ففرح بذلك الوثنيون ؛ لأن فارس وثنية تشبه حالة المشركين في عهد النبي صلى الله عليه وسلم من عباد الأوثان، وأما الروم فهم أهل كتاب وهم أقرب إلى المسلمين من الوثنيين، ولهذا قال في غلبة الروم لفارس: وَيَوْمَئِذٍ يَفْرَحُ الْمُؤْمِنُونَ ۝ بِنَصْرِ اللَّهِ يَنصُرُ مَنْ يَشَاءُ [الروم:4-5]، فهذا إخبار من الله سبحانه وتعالى إخبار صادق وقع هذا وهذا. نعم.","link":"https://binbaz.org.sa/fatwas/5266/تفسير-قوله-تعالى-الم-غلبت-الروم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_055/05504.mp3","categories":["التفسير"]},{"id":7928,"question":"هذه -الله يطول عمرك- رسالة وردتنا من القصيم من عيون الجوى، بعث بها المستمع (ب. س. ص)، يقول في رسالته وهي طويلة بعض الشيء يقول: السلام عليكم ورحمة الله وبركاته، صليت خلف إمام وأنا في طريقي إلى مقر عملي في صلاة المغرب، فقرأ بعد الفاتحة سورة تبت يدا أبي لهب، وبعد الفراغ من الصلاة سأله أحد المأمومين عن تفسير قوله تعالى: فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ [المسد:5]، فقال الإمام: معناها: ممتد، أي: معنى من مسد ممتد، وهو حين قرأ كلمة مسد نطقها بكسر السين مسد فرددت عليه حسب معرفتي من الدراسة أن معنى مسد أي: من مسد جهنم، أي: حرها ولهبها، فرد علي الإمام بغضب يقول: أنا أكبر منك وأعرف منك، علماً إنه ليس إمام رسمي في مسجد وإنما في الطريق فقط، ولم أرد عليه تقديراً لكبره ولحضور بعض المصلين معنا، فسكت وأنا غير راض عن ذلك، فهل علي إثم على سكوتي وأتركه يفسر على مزاجه كلام الله المطهر، ويقول: إنني التقيت به مرات في هذا المصلى في الطريق، أرجو الإفادة أثابكم الله وأعظم أجركم؟","title":"تفسير قوله تعالى: (في جيدها حبل من مسد)","answer":"الجواب: لا شك أن قوله تعالى: في جيدها يعني: في عنقها، حبل من مسد يعني: من النار، لكن تفسير المسد بالنص على المعنى المراد من كلام الله عز وجل يحتاج إلى العناية بكلام أهل التفسير، كتفسير ابن جرير وابن كثير والبغوي وتفسير الشوكاني ، فيمكن مطالعة هذه الكتب وأشباهها كـالقرطبي أيضاً يتضح كلام أهل التفسير في ذلك، ولاشك أن المراد هنا: أنه شيء من العذاب، المسد شيء من العذاب، حبل من مسد شيء من العذاب الذي تعذب به هذه المرأة بسبب عدائها للنبي ﷺ هي وزوجها وإيذائهما للنبي صلى الله عليه وسلم بما يحملان من الحطب ويلقيانه في طريقه عليه الصلاة والسلام.\nفالحاصل أن هذا الشيء يرجع فيه للتفسير لا لكلام الإمام هذا المسكين ولا غيره، بل يراجع بهذا كلام المفسرين كما تقدم ابن كثير وابن جرير والبغوي والقرطبي وأشباههم، فقد أوضحوا معنى ذلك وبينوا كلام المفسرين الأولين في ذلك، وهو بلا شك يدل على أنه عذاب فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ [المسد:5]، حبل من العذاب الذي وعد الله به أمثال هؤلاء، لكن تفسير مسد عين مسد ما هو ووجه التسمية هذا يحتاج إلى مطالعة كتب التفسير ولا يحضرني الآن كلام أهل التفسير في هذه الكلمة، وفي إمكان كل طالب علم أن يراجع كلام المفسرين ويعلم ما قالوا في هذا، فالحمد لله، الأمر قريب وواضح. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5438/تفسير-قوله-تعالى-في-جيدها-حبل-من-مسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_065/06503.mp3","categories":["التفسير"]},{"id":7939,"question":"سؤاله الثاني يقول فيه: نرجو تفسير معنى: يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ [يونس:31] مع مثال لذلك إن استطعتم؟","title":"تفسير قوله تعالى: (يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ ...)","answer":"الجواب: هذا من آيات الله ومن دلائل قدرته سبحانه وتعالى أنه يخرج الحي من الميت ويخرج الميت من الحي، هذه من آياته سبحانه وتعالى ومن دلائل قدرته العظيمة وأنه رب العالمين الخلاق العليم القادر على كل شيء، وأنه سبحانه وتعالى يحيي ويميت ويتصرف في خلقه كيف يشاء، وأنه المستحق للعبادة، وقد مثل أهل العلم لذلك بأشياء منها: إخراج المسلم من الكافر، يكون كافراً ويخرج الله من صلبه أحياء مسلمين، فإن المسلم حي والميت كافر في المعنى، فالله يخرج من المرأة الكافرة والرجل الكافر أولاداً مسلمين يهديهم الله ويصلحهم سبحانه وتعالى، وأبوهم وأمهم ليسوا كذلك.\nوكذلك يخرج الميت من الحي يكون مسلم فيولد له أولاد فيكفرون ولا يبقون على دين آبائهم وأمهاتهم بل يكونون على خلاف ذلك، ويعتنقون غير الإسلام، فيكون هذا إخراج ميت من حي.\nومن ذلك مما مثلوا به أيضاً.. إخراج الدجاجة من البيضة، الدجاجة حية حيوان والبيضة في حكم الموات أو الميت لأنها جماد، فالله جل وعلا يخرج منها حيواناً سميعاً بصيراً حياً وهذا واضح، والعكس كذلك يخرج الميت من الحي، هذا الميت البيضة والدجاجة حية فيخرج الله منها بيضة جماداً في حكم الميت والدجاجة حية، وهذا له نظائر، نعم. ومن أراد المزيد على ذلك فليراجع كتب التفسير على الآية الكريمة. نعم.","link":"https://binbaz.org.sa/fatwas/5464/تفسير-قوله-تعالى-يخرج-الحي-من-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_067/06703.mp3","categories":["التفسير"]},{"id":7969,"question":"أيضاً يقول: يوجد في القرآن الكريم آية في سورة النساء آية رقم ( 175 ) وتقول: بسم الله الرحمن الرحيم: فَلِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ يُبَيِّنُ اللَّهُ لَكُمْ أَنْ تَضِلُّوا وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ [النساء:176]، صدق الله العظيم، وفي تفسير الجلالين مكتوب، (أن لا تضلوا والله بكل شيء عليم)، صدق الله العظيم، أفيدونا جزاكم الله خيراً؟","title":"معنى قوله تعالى: (يُبَيِّنُ اللَّهُ لَكُمْ أَنْ تَضِلُّوا ...)","answer":"الجواب: هذه آية المواريث في الإخوة قال الله جل وعلا: وَإِنْ كَانُوا إِخْوَةً رِجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ يُبَيِّنُ اللَّهُ لَكُمْ أَنْ تَضِلُّوا [النساء:176]، يعني: كراهة أن تضلوا كما قال جماعة من المفسرين، مفعول لأجله محذوف وقال بعض المفسرين: لئلا تضلوا، وبعضهم قال: ألا تضلوا، المقصود: أن البيان لأجل ألا يضلوا، يبين الله لهم هذه الأشياء حتى لا يضلوا عن الصواب حتى لا يقعوا في الباطل، معنى: يبين الله أن تضلوا، يعني: لئلا تضلوا، أو كراهة أن تضلوا، هذا المعنى. نعم","link":"https://binbaz.org.sa/fatwas/5518/معنى-قوله-تعالى-يبين-الله-لكم-ان-تضلوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_070/07003.mp3","categories":["التفسير"]},{"id":7981,"question":"سؤالها الثاني: هذه رسالة من المستمعة أو السائلة (و. أ. ع) اليمن تعز، تقول في رسالتها: أشكركم على هذا البرنامج الذي أتمنى له كل التوفيق والنجاح لما فيه حل المشاكل الدينية والاجتماعية، وأرجو الإجابة على هذه الأسئلة: يقول الله سبحانه وتعالى في كتابه الحكيم: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، تقول: هل هذه الصلاة الوسطى هي العصر أم المغرب؟","title":"المقصود بالصلاة الوسطى","answer":"الجواب: الصواب أنها العصر، اختلف العلماء في ذلك لكن الصواب أنها العصر قد صح عن رسول الله عليه الصلاة والسلام من حديث ابن مسعود وغيره ومن حديث علي  أنها العصر هذا هو الصواب وقيل غير ذلك، لكن الصواب أنها العصر. نعم.","link":"https://binbaz.org.sa/fatwas/5527/المقصود-بالصلاة-الوسطى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07203.mp3","categories":["التفسير"]},{"id":8063,"question":"هو أيضاً يريد أن تذكرون له معنى هذه الآية: وَأَقِيمُوا الصَّلاةَ وَلا تَكُونُوا مِنَ الْمُشْرِكِينَ ۝ مِنَ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا [الروم:31-32]؟","title":"معنى قوله تعالى: (... الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا)","answer":"الجواب: يبين أن هذا من صفات المشركين، تفريق الدين والتشيع، كل شيعة لها رأي ولها كلام ولها أنصار، هكذا يكون المشركون وهكذا الكفار يتفرقون، وكل طائفة لها رئيس، ولها متبوع، تغضب لغضبه وترضى لرضاه، ليس همهم الدين وليس تعلقهم بالدين.\nأما المسلمون فهم يجتمعون على كتاب الله وسنة رسوله عليه الصلاة والسلام، وهدفهم هو اتباع الكتاب والسنة، وهم مجتمعون على ذلك معتصمون بحمد الله.\nأما غيرهم من الكفار فهم أحزاب وشيع، الله عز وجل يحذرنا أن نكون مثلهم، ويأمرنا أن نقيم الصلاة، وأن نستقيم على دين الله، وأن نجتمع على الحق، ولا نتشبه بأعداء الله المشركين، الذين فرقوا دينهم وكانوا شيعاً. وهكذا أصحاب البدع شابهوا المشركين، فرقوا دينهم وكانوا شيعاً، هذا معتزلي، هذا جهمي، هذا مرجئي، هذا شيعي، إلى غير ذلك، هذا تفرق في الدين، ومخالفة لما أمر الله به من الاعتصام بحبل الله، والاستقامة على دين الله، وعدم التنازع والفشل. نعم.","link":"https://binbaz.org.sa/fatwas/5859/معنى-قوله-تعالى-الذين-فرقوا-دينهم-وكانوا-شيعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_083/08304.mp3","categories":["التفسير"]},{"id":8084,"question":"سؤاله الثاني سؤال جواد يقول: قال الله تعالى في كتابه العزيز: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] ما المقصود بالناس في الآية الكريمة، هل هم المسلمون فقط أم سائر الناس، وإن كان الخطاب للمسلمين فقط فلماذا لم يخاطبون بلفظ المسلمين؟ نرجو من فضيلتكم الجواب الفصل في ذلك.","title":"ما المقصود بالناس في: {وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ}؟","answer":"الجواب: المراد هنا جميع الناس، كلهم واجب عليهم الحج لكن بشرط الإسلام، شرط أن يسلموا، فلو حجوا قبل الإسلام ما يصح، فالناس كلهم عليهم الحج، لكن المسلم عليه المبادرة به مع الاستطاعة؛ لأنه قد دخل في الإسلام فوجبت عليه أعمال الإسلام المفروضة من صلاة وزكاة وصوم وحج.\nأما الكفار فعليهم أن يسلموا وعليهم أن يقوموا بهذا الواجب، فهم مخاطبون بفروع الشريعة، مخاطبون بالصلاة والصوم والحج وغير ذلك، لكن لا تصح منهم حتى يأتوا بشرطها وهو الإسلام، بغير إسلام أعمالهم باطلة: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] فهم كلهم مخاطبون بأعمال الشريعة فروضها وفروعها، لكن لا تصح منهم هذه الفروع حتى يأتوا بالأصل وهو الشهادتان توحيد الله والإخلاص له والإيمان بأنه مستحق العبادة والشهادة للرسول صلى الله عليه وسلم بالرسالة؛ محمد ﷺ ولسائر النبيين والمرسلين، والإيمان بأنه خاتم النبيين وبأن كل ما أخبر الله به ورسوله حق، فلابد من هاتين الشهادتين؛ الشهادة بأنه لا إله إلا الله، أي: لا معبود حق إلا الله، فهو المعبود بالحق سبحانه وتعالى.\nوما عبده الناس من أصنام أو أموات أو أشجار أو أحجار كله باطل كما قال سبحانه: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62] الآية من سورة الحج.\nوكذلك لابد من الشهادة بأن محمداً رسول الله؛ محمد بن عبد الله بن عبد المطلب الهاشمي العربي المكي ثم المدني، لابد من الشهادة بأنه رسول الله حق وبأنه خاتم الأنبياء، فمن لم يأت بهاتين الشهادتين عن صدق وإيمان ما تصح صلاته ولا صومه ولا زكاته ولا حجه ولا سائر عباداته حتى يسلم حتى يدخل في دين الله بالشهادتين وبالإيمان بكل ما أخبر الله به ورسوله، فإذا أسلم وجب عليه أداء هذه الحقوق من صلاة وصوم وحج وغير ذلك. نعم. بشرط الاستطاعة.\nالمقدم: شكراً لفضيلة الشيخ عبدالعزيز.","link":"https://binbaz.org.sa/fatwas/5883/ما-المقصود-بالناس-في-ولله-على-الناس-حج-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_085/08507.mp3","categories":["التفسير"]},{"id":8094,"question":"أيضاً يقول: ما المقصود بالقانع والمعتر؟ وما حكم من لم يتصدق أو يهد من الأضحية؟","title":"حكم ترك التصدق والإهداء من الأضحية، ومعنى: {الْقَانِعَ وَالْمُعْتَرَّ}","answer":"الجواب: القانع والمعتر فيما ذكر أهل العلم. القانع: هو الذي يسأل يرفع يده ويسأل.\nوالمعتر: هو الذي يتعرض، ويظهر منه الرغبة في أن يعطى، ولكنه لا يرفع يده ولا يسأل.\nوالذي لا يتصدق من الضحية قد ترك أمراً واجباً؛ لأن الله قال: فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ [الحج:28] .. وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ [الحج:36]، فالواجب أن يعطي من الهدية، وأن يعطي من الضحية بعض الشيء، ويتصدق منها، وإذا قسمها أثلاثاً: تصدق بالثلث، وأكل الثلث وأهدى الثلث إلى بعض أقاربه وجيرانه، فهذا حسن، وإذا أكلها كلها فينبغي له أن يغرم ما يقابل جزءاً منها يتصدق به، مقابل ما أكل من حق الفقراء. نعم.","link":"https://binbaz.org.sa/fatwas/5886/حكم-ترك-التصدق-والاهداء-من-الاضحية-ومعنى-القانع-والمعتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08602.mp3","categories":["التفسير"]},{"id":8193,"question":"سؤالها الآخر تقول فيه: لقد قرأت حديث عن النبي ﷺ بما معناه: أن تنزهوا من البول، فإن أكثر عذاب القبر منه، ما معنى هذا؟","title":"ما معنى: «تنزهوا من البول فإن أكثر عذاب القبر منه»؟","answer":"الجواب: هذا حديث جيد، رواه الحاكم في صحيحه ورواه جماعة، ولفظه: استنزهوا من البول؛ فإن عامة عذاب القبر منه، وفي لفظ: أكثر عذاب القبر من البول، فمعناه: التحفظ، معناه: التحفظ من البول والحذر منه، فإذا أراد الإنسان يبول يبول في محل لين، أو في جحر من محل قضاء الحاجة، لئلا يطير إليه الرشاش رشاش البول، فالمرأة والرجل كذلك عليهما جميعاً أن يعتنيا بهذا الأمر، فيكون البول في محل لا يطشش على الإنسان، وإذا أصابه شيء منه، طشش على فخذه، أو طشش على قدمه، فيصب عليه الماء، ويغسله عن ما أصابه، يغسل ما أصابه، حتى يكون قد تحرز من البول، وإذا كان المحل لين كالأرض اللينة، أو وضع الفرج على نفس الجحر الذي يذهب فيه الماء، حتى لا يطشش عليه كفى ذلك، لكن بكل حال التنزه والتحرز طيب، فلو قدر أنه صادف البول حافة المحل البول فطشش على فخذ أو على ساق أو قدم، فإن المسلم والمسلمة عليهما أن يغسلا ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6002/ما-معنى-تنزهوا-من-البول-فان-اكثر-عذاب-القبر-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09303.mp3","categories":["التفسير","شروح الحديث"]},{"id":8194,"question":"سؤالها الآخر تقول فيه: لقد قرأت حديث عن النبي ﷺ بما معناه: أن تنزهوا من البول، فإن أكثر عذاب القبر منه، ما معنى هذا؟","title":"ما معنى: «تنزهوا من البول فإن أكثر عذاب القبر منه»؟","answer":"الجواب: هذا حديث جيد، رواه الحاكم في صحيحه ورواه جماعة، ولفظه: استنزهوا من البول؛ فإن عامة عذاب القبر منه، وفي لفظ: أكثر عذاب القبر من البول، فمعناه: التحفظ، معناه: التحفظ من البول والحذر منه، فإذا أراد الإنسان يبول يبول في محل لين، أو في جحر من محل قضاء الحاجة، لئلا يطير إليه الرشاش رشاش البول، فالمرأة والرجل كذلك عليهما جميعاً أن يعتنيا بهذا الأمر، فيكون البول في محل لا يطشش على الإنسان، وإذا أصابه شيء منه، طشش على فخذه، أو طشش على قدمه، فيصب عليه الماء، ويغسله عن ما أصابه، يغسل ما أصابه، حتى يكون قد تحرز من البول، وإذا كان المحل لين كالأرض اللينة، أو وضع الفرج على نفس الجحر الذي يذهب فيه الماء، حتى لا يطشش عليه كفى ذلك، لكن بكل حال التنزه والتحرز طيب، فلو قدر أنه صادف البول حافة المحل البول فطشش على فخذ أو على ساق أو قدم، فإن المسلم والمسلمة عليهما أن يغسلا ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6002/ما-معنى-تنزهوا-من-البول-فان-اكثر-عذاب-القبر-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09303.mp3","categories":["التفسير","شروح الحديث"]},{"id":8201,"question":"سؤاله الآخر يقول: ما معنى قوله تعالى: أَنِ اتَّبِعْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ [النحل:123]؟ وما هي الأسباب التي فرقت المسلمين إلى عدة مذاهب، أفيدونا عن ذلك جزاكم الله عنا خيراً؟","title":"ما معنى: {أَنِ اتَّبِعْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا}؟","answer":"الجواب: الله جل وعلا يأمر نبيه صلى الله عليه وسلم أن يتبع ملة إبراهيم، في الإخلاص لله وتوحيده، وتعظيم أمره ونهيه، والإعراض عن المشركين، ومعاداتهم وبغضهم في الله ، وهكذا الأمة مأمورة بذلك، كلها مأمورة بأن تعبد الله وحده: إِنَّ هَذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً وَأَنَا رَبُّكُمْ فَاعْبُدُونِ [الأنبياء:92].. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5].. وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5].. وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، إلى أمثال هذه الآيات، والله  خلق الخلق ليعبد وحده لا شريك له، وأمرهم بذلك، وأرسل الرسل عليهم الصلاة والسلام لدعوة الناس إلى توحيد الله، والإخلاص له.\nفالواجب على جميع أهل الأرض من جن وإنس، وعرب وعجم، وأغنياء وفقراء، وذكور وإناث، عليهم جميعاً أن يعبدوا الله وحده، وأن يخصوه بدعائهم، وخوفهم، ورجائهم، وصلاتهم، وصومهم، وصدقاتهم، وسائر عباداتهم، فهو المستحق لها : إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، ولا يجوز لهم أن يعبدوا معه آلهاً آخر، لا ملكاً مقرباً ولا نبياً مرسلاً، ولا يجوز لهم أيضاً أن يعبدوا أصحاب القبور، وأن يستغيثوا بهم، أو يعطوهم مدد، أو ينذروا لهم، أو يذبحوا لهم، ولا أن يعبدوا الأصنام والأشجار والأحجار والكواكب، لا! هذا كله باطل، كله شرك بالله .\nالواجب على جميع الثقلين أن يعبدوا الله وحده، فيخصوه سبحانه بجميع العبادات، من خوف ورجاء وصوم وصلاة وصدقة وذبح ونذر وغير ذلك، وعلى الأمة جميعاً أن تتفقه في هذا، وأن تعنى بهذا الأمر، ومن أهم الأمور: العناية بالقرآن العظيم؛ فإنه كتاب الله فيه الهدى والنور، وهو يوضح هذا الأمر، وهو يبين أن العبادة حق الله وحده، فعلى جميع المسلمين أن يعنوا بكتاب الله، وأن يتدبروه ويتعقلوه.\nوهكذا سنة الرسول ﷺ جاءت ببيان هذا الأمر، وأن العبادة حق الله وحده، فعلى أهل الإسلام أن يعظموا الله ويعبدوه وحده دون كل ما سواه، وأن يبلغوا الناس ذلك، وعلى علمائهم بالأخص أن يبلغوا الجهلة ما خفي عليهم، ويعلموهم ويرشدوهم حتى يستقيموا على دين الله، وحتى يعبدوا الله وحده، وعليهم أيضاً أن يبلغوا الناس الآخرين، بالطرق الممكنة والوسائل الممكنة دين الله، كما بلغت الرسل عليهم الصلاة والسلام.\nأما الاختلاف فيما بين أهل الأرض، فله أسباب كثيرة، والاختلاف الضار ما يتعلق في الأصول، أما المسائل الفقهية فالخلاف بين الناس فيها، فهذا أمر واقع، والنبي ﷺ بين ما يجب في هذا، وأن الواجب هو الاجتهاد وتحري الحق، ورد ما تنازع فيه الناس إلى الله والرسول، وكما قال سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59].\nوقال عليه الصلاة والسلام: إذا حكم الحاكم فاجتهد فأصاب فله أجران، وإذا حكم فاجتهد فأخطأ فله أجر، فمسائل الفروع يقع فيها خلاف، واشتباه الأمر، وعلى المسلمين فيها أن يعرضوها على الكتاب والسنة عند الاختلاف، فما دل عليه الكتاب والسنة وجب الأخذ به، والتمسك به، والرجوع إليه، دون ما خالفه. نعم.","link":"https://binbaz.org.sa/fatwas/6008/ما-معنى-ان-اتبع-ملة-ابراهيم-حنيفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_094/09402.mp3","categories":["التفسير"]},{"id":8248,"question":"هذه رسالة من أخونا عبيد الله خليفة البلادي من حليف، أخونا يسأل مجموعة من الأسئلة من بينها سؤال عن الآية الكريمة: إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ [فاطر:28] حبذا لو فسرتم لنا هذا الجزء من هذه الآية الكريمة؟","title":"تفسير قوله تعالى: (إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ)","answer":"الجواب: هذا ثناء من الله سبحانه على العلماء وبيان لعظم منزلتهم ولعظم فضلهم على الناس، والمراد بذلك العلماء بالله علماء الشريعة علماء القرآن والسنة الذين يخافون الله ويراقبونه هم المراد هنا، يعني الخشية الكاملة: إِنَّمَا يَخْشَى اللَّهَ [فاطر:28] يعني: الخشية الكاملة، خشيتهم أكمل من خشية غيرهم، وإلا فكل مؤمن يخشى الله، كل مسلم يخشى الله، لكنها تتفاوت وليست خشية العلماء المتبصرون علماء الحق علماء الشريعة ليست خشيتهم مثل خشية عامة المسلمين، بل هي أكمل وأعظم.\nولهذا يراقبون الله ويعلمون عباد الله، ويقفون عند حدود الله، وينفذون أوامر الله، فأعمالهم تطابق أقوالهم وتطابق علمهم، هم أكمل الناس خشية لله عز وجل، وليس معناها أن المؤمن الذي ليس بعالم لا يخشى الله، لا؛ مراد الرب جل وعلا حصر كمال مثلما قال جل وعلا: إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ آياتُهُ زَادَتْهُمْ إِيمَانًا وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ [الأنفال:2] الآية، ليس معناها أن الذي لا يوجل قلبه عند ذكر الله أو لا يزداد إيمانه عند ذكر الله ليس بمؤمن، لا، بل المراد أن هؤلاء هم المؤمنون الكمل، المؤمنون الذين لديهم كمال إيمان وقوة إيمان.\nوهكذا قوله جل وعلا: إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ ثُمَّ لَمْ يَرْتَابُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ فِي سَبِيلِ اللَّهِ أُوْلَئِكَ هُمُ الصَّادِقُونَ [الحجرات:15] معناه: المؤمنون الكمل الذين كمل إيمانهم، وليس معناه أن من لم يجاهد فلا إيمان له، بل له إيمان بقدره على حسب حاله وقدرته.\nفالمقصود من هذا كله بيان الكمال، كمال خشية الله وكمال الإيمان، وإلا فالمؤمنون جميعاً رجالاً ونساء وإن لم يكونوا علماء عندهم خشية لله، وعندهم إيمان، وعندهم تقوى، لكن المجاهدين والذين عندهم علم بالكتاب والسنة أكمل من غيرهم إيماناً، وأعظم إيماناً لما حصل في قلوبهم من الخير العظيم والخشية العظيمة التي حملتهم على أن علموا الناس الخير وعملوا به وصدقوا أقوالهم بأعمالهم وحملتهم خشيتهم لله على البدار بالجهاد في سبيله والصبر على تقديم أنفسهم للشهادة؛ لأنهم يعلمون أن هذا طاعة لله ورسوله. نعم.","link":"https://binbaz.org.sa/fatwas/6073/تفسير-قوله-تعالى-انما-يخشى-الله-من-عباده-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09813.mp3","categories":["التفسير"]},{"id":8294,"question":"تسأل سماحة الشيخ وتقول: لقد قال الله تعالى في كتابه العزيز: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ [النساء:145] ما المقصود بالمنافقين والنفاق في هذه الآية الكريمة، وأرجو أن تتفضلوا بإيضاح المعنى؟","title":"ما المقصود بالمنافقين في: {إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ}؟","answer":"الجواب: المراد بالمنافقين: هم الذين يتظاهرون بالإسلام وهم على غير الإسلام، يدعون أنهم مسلمون وهم في الباطن يكفرون بالله ويكذبون رسوله عليه الصلاة والسلام، هؤلاء هم المنافقون، سموا منافقين؛ لأنهم أظهروا الإسلام وأبطنوا الكفر، وهم مذكورون في قوله عز وجل: وَمِنَ النَّاسِ مَنْ يَقُولُ آمَنَّا بِاللَّهِ وَبِالْيَوْمِ الآخِرِ وَمَا هُمْ بِمُؤْمِنِينَ [البقرة:8]  ۝ يُخَادِعُونَ اللَّهَ وَالَّذِينَ آمَنُوا وَمَا يَخْدَعُونَ إِلَّا أَنفُسَهُمْ وَمَا يَشْعُرُونَ [البقرة:9]  ۝ فِي قُلُوبِهِمْ مَرَضٌ [البقرة:10] يعني: شك وريب فَزَادَهُمُ اللَّهُ مَرَضًا وَلَهُمْ عَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ [البقرة:10] الآيات من سورة البقرة في أولها، هم هؤلاء، وهم مذكورون في قوله جل وعلا: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ [النساء:142] يعني: ما عندهم إيمان: يُرَاءُونَ النَّاسََ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا ۝ مُذَبْذَبِينَ بَيْنَ ذَلِكَ لا إِلَى هَؤُلاءِ وَلا إِلَى هَؤُلاءِ [النساء:142-143] المعنى: أنهم مترددون بين الكفار والمسلمين، تارة مع الكفار إن ظهر الكفار وانتصروا، وتارة مع المؤمنين إن ظهروا وانتصروا، فليس عندهم ثبات ولا دين مستقيم ولا إيمان ثابت، بل هم مذبذبون بين الكفر والإيمان، وبين الكفار والمسلمين، وهم مذكورون في قوله جل وعلا: وَمَا مَنَعَهُمْ أَنْ تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ إِلَّا أَنَّهُمْ كَفَرُوا بِاللَّهِ وَبِرَسُولِهِ وَلا يَأْتُونَ الصَّلاةَ إِلَّا وَهُمْ كُسَالَى وَلا يُنفِقُونَ إِلَّا وَهُمْ كَارِهُونَ [التوبة:54]  ۝ فَلا تُعْجِبْكَ أَمْوَالُهُمْ وَلا أَوْلادُهُمْ إِنَّمَا يُرِيدُ اللَّهُ لِيُعَذِّبَهُمْ بِهَا فِي الْحَيَاةِ الدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَافِرُونَ [التوبة:55] هؤلاء هم المنافقون، نسأل الله العافية والسلامة.\nالسؤال: اللهم آمين. سماحة الشيخ تقول: إن لديها أسئلة كثيرة خاصة بها، وترجو أن تتصل بكم تلفونياً لكنها لا تعرف رقم الهاتف، هل يمكن أن تذكروه لها؟\nالشيخ: نعم نعم، الهاتف في المنزل: (4354444) هذا هاتف المنزل، بين المغرب والعشاء، أو في الساعة الثانية والنصف بعد الظهر إلى الساعة الثالثة، أو في الصباح يوم الخميس من الساعة العاشرة إلى الظهر، أو بعد صلاة الجمعة بنصف ساعة أو ثلثي ساعة إلى الساعة الثالثة، كل هذه أوقات مناسبة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6107/ما-المقصود-بالمنافقين-في-ان-المنافقين-في-الدرك-الاسفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10802.mp3","categories":["التفسير","مسائل متفرقة في العقيدة"]},{"id":8328,"question":"هذه رسالة من المرسل (ك. ح. ص) مصري يعمل بالمملكة، وقد عرضنا في حلقة مضت سؤالين له، وهذه بقية أسئلته يقول في أولها: قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] كيف نجمع بينها وبين قول الرسول ﷺ: كلكم راع وكلكم مسئول عن رعيته هذه خلاصة سؤاله؟","title":"الجمع بين: {عَلَيْكُمْ أَنفُسَكُمْ} وحديث: «كلكم راع»","answer":"الجواب: ليس بين الآية المذكورة الكريمة وبين الحديث الشريف المذكور تخالف ولا تضاد، بل الآية والحديث متفقان، الله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] المعنى: عليكم أن تجاهدوا أنفسكم، عليكم إصلاح أنفسكم فـ: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] أي: لا يضركم من ضل إذا أديتم الواجب بالأمر بالمعروف والنهي عن المنكر والقيام بما أوجب الله على العبد، فإن هذه هي الهداية، ما يكون العبد مهتدياً حتى يقوم بالواجب، وكونه يرعى من تحت يده ويقوم بما يلزم، وكونه يأمر بالمعروف وينهى عن المنكر ويدعو إلى الله كل هذا من طرق الهداية، فلا يكون مهتدياً حتى يؤدي ما أوجب الله عليه من الواجبات العينية والواجبات المتعلقة بالمجتمع من أمر بمعروف ونهي عن منكر، وغير هذا مما يلزم للمجتمع، فالحاصل أن قوله سبحانه: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] معناه إذا أديتم الواجب، ومن ترك الحبل على الغارب ولم يأمر بمعروف ولم ينه عن منكر، ولم يقم بحق الرعية ما أدى الواجب ولا اهتدى الهداية الكاملة، بل هدايته ناقصة غير تامة فيكون مؤاخذ بذلك، يكون هذا الرجل الذي قصر في الواجب يكون مؤاخذاً بما قصر فيه؛ لأن هدايته ناقصة، والله يقول: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] والذي لم يأمر بالمعروف ولم ينه عن المنكر، ولم يقم بالرعاية التي عليه ما يكون مهتدياً الهداية المطلقة الكاملة، بل تكون هدايته ناقصة ضعيفة فيها خلل فيؤاخذ بهذا الخلل وهذا النقص. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6138/الجمع-بين-عليكم-انفسكم-وحديث-كلكم-راع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20203.mp3","categories":["التفسير","شروح الحديث"]},{"id":8329,"question":"هذه رسالة من المرسل (ك. ح. ص) مصري يعمل بالمملكة، وقد عرضنا في حلقة مضت سؤالين له، وهذه بقية أسئلته يقول في أولها: قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] كيف نجمع بينها وبين قول الرسول ﷺ: كلكم راع وكلكم مسئول عن رعيته هذه خلاصة سؤاله؟","title":"الجمع بين: {عَلَيْكُمْ أَنفُسَكُمْ} وحديث: «كلكم راع»","answer":"الجواب: ليس بين الآية المذكورة الكريمة وبين الحديث الشريف المذكور تخالف ولا تضاد، بل الآية والحديث متفقان، الله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] المعنى: عليكم أن تجاهدوا أنفسكم، عليكم إصلاح أنفسكم فـ: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] أي: لا يضركم من ضل إذا أديتم الواجب بالأمر بالمعروف والنهي عن المنكر والقيام بما أوجب الله على العبد، فإن هذه هي الهداية، ما يكون العبد مهتدياً حتى يقوم بالواجب، وكونه يرعى من تحت يده ويقوم بما يلزم، وكونه يأمر بالمعروف وينهى عن المنكر ويدعو إلى الله كل هذا من طرق الهداية، فلا يكون مهتدياً حتى يؤدي ما أوجب الله عليه من الواجبات العينية والواجبات المتعلقة بالمجتمع من أمر بمعروف ونهي عن منكر، وغير هذا مما يلزم للمجتمع، فالحاصل أن قوله سبحانه: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] معناه إذا أديتم الواجب، ومن ترك الحبل على الغارب ولم يأمر بمعروف ولم ينه عن منكر، ولم يقم بحق الرعية ما أدى الواجب ولا اهتدى الهداية الكاملة، بل هدايته ناقصة غير تامة فيكون مؤاخذ بذلك، يكون هذا الرجل الذي قصر في الواجب يكون مؤاخذاً بما قصر فيه؛ لأن هدايته ناقصة، والله يقول: لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105] والذي لم يأمر بالمعروف ولم ينه عن المنكر، ولم يقم بالرعاية التي عليه ما يكون مهتدياً الهداية المطلقة الكاملة، بل تكون هدايته ناقصة ضعيفة فيها خلل فيؤاخذ بهذا الخلل وهذا النقص. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6138/الجمع-بين-عليكم-انفسكم-وحديث-كلكم-راع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20203.mp3","categories":["التفسير","شروح الحديث"]},{"id":8421,"question":"أخونا يسأل سؤال آخر عن تفسير قوله تعالى -أعوذ بالله من الشيطان الرجيم-: وَأَنَّا لَمَسْنَا السَّمَاءَ فَوَجَدْنَاهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا [الجن:8] هل الجن لمسوا السماء حقاً أم لا؟","title":"ما معنى: {وَأَنَّا لَمَسْنَا السَّمَاءَ} وما حقيقة لمس الجن للسماء؟","answer":"الجواب: القرآن أصدق الكلام، هو كلام الله عز وجل، والأصل في الكلام الحقيقة هذا هو الأصل، والله أخبر سبحانه أنهم قالوا: وَأَنَّا لَمَسْنَا السَّمَاءَ فَوَجَدْنَاهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا [الجن:8] ولم يرد عليهم، ولم يقل: كذبوا، فدل ذلك على أنهم لمسوها وصعدوا وارتفعوا حتى لمسوا السماء؛ فإنهم يسترقون السمع، ويركب بعضهم فوق بعض بإذن الله الذي قواهم على هذا سبحانه وتعالى، فلهذا أخبر عنهم بما أخبر حيث أخبر عنهم بأنهم قالوا: وَأَنَّا لَمَسْنَا السَّمَاءَ فَوَجَدْنَاهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا [الجن:8] فالأمر حقيقة، وهذا يدل على إمكان ذلك، وأنه يمكن لمس السماء، لكن لا يمكن دخولها إلا بإذن من الله ، ولهذا لما عرج بالنبي ﷺ إلى السماء لم يدخلها إلا بإذن ومعه جبرائيل عليه الصلاة والسلام، فاستأذن جبرائيل فأذن له الحرس، فدخل جبرائيل ودخل النبي عليه الصلاة والسلام في كل سماء بإذن. نعم.","link":"https://binbaz.org.sa/fatwas/6305/ما-معنى-وانا-لمسنا-السماء-وما-حقيقة-لمس-الجن-للسماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11812.mp3","categories":["التفسير"]},{"id":8468,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (ع. س) أخونا يسأل مجموعة من الأسئلة، في سؤاله الأول يقول: أرجو أن تتفضلوا بالإجابة على الأسئلة التالية وهي كما يلي:ما الفرق بين الآيات الكريمة: في الآية الخامسة عشرة من سورة الجن قال الله تعالى: وَأَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَبًا[الجن:15] وفي الآية السابعة من سورة الممتحنة قال تعالى: إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8] وفي الآية الثانية والأربعين من سورة المائدة قال الله تعالى: فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [المائدة:42].","title":"الفرق بين القاسط والمقسط","answer":"الجواب: القسط -الذي أمر الله بالحكم به-: هو العدل، والمقسطون: هم أهل العدل الذين يعدلون في حكمهم وفي أهليهم وفيما ولاهم الله عليه، يقال: أقسط إذا عدل في الحكم، وأدى الحق ولم يجر.\nأما القاسط: فهذا هو الجائر والظالم، يقال له: قسط يقسط قسطاً فهو قاسط إذا جار وظلم، ولهذا قال تعالى: وَأَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَبًا [الجن:15] يعني: الظالمون (وأما القاسطون) الظالمون الجائرون المتعدون لحدود الله، فهم الذين توعدهم الله بأن يكونوا حطباً لجهنم.\nفأما المقسطون (بالميم) المقسطون: من أقسط من الرباعي فهؤلاء هم أهل العدل، هم الموفقون المهديون الذين يعدلون في حكمهم وفي أهليهم، وفيما ولاهم الله عليه، ولهذا قال سبحانه: إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [المائدة:42] يعني: يحب أهل العدل والاستقامة والإنصاف، ومن هذا قوله في الحديث الصحيح: المقسطون على منابر من نور يوم القيامة، الذين يعدلون في حكمهم وفي أهليهم وماا ولوا نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6481/الفرق-بين-القاسط-والمقسط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_124/12402.mp3","categories":["التفسير"]},{"id":8518,"question":"هذه رسالة وردتنا من السائل حسن عبد الستار أبو زيد، سوداني مقيم في ليبيا، يقول في رسالته: ورد في سورة الكهف على لسان الرجل الصالح في قصته مع موسى عليه السلام، في قوله تعالى: أَمَّا السَّفِينَةُ فَكَانَتْ لِمَسَاكِينَ يَعْمَلُونَ فِي الْبَحْرِ [الكهف:79] إلى قوله تعالى: ذَلِكَ تَأْوِيلُ مَا لَمْ تَسْطِعْ عَلَيْهِ صَبْرًا [الكهف:82] لاحظت أنه عند السفينة قال: فَأَرَدْتُ أَنْ أَعِيبَهَا [الكهف:79] وعند ذكر الأبوين المؤمنين: فَأَرَدْنَا أَنْ يُبْدِلَهُمَا رَبُّهُمَا [الكهف:81] وعند ذكر قصة اليتيمين صاحبي الجدار: فَأَرَادَ رَبُّكَ [الكهف:82] فما الفرق بين التعابير الثلاثة، وهل ذلك يعني أن للرجل الصالح إرادة في الأمر مع إرادة الله؟","title":"توجيه ألفاظ الإرادة في قصة الخضر مع موسى","answer":"الجواب: الصحيح أن هذا الرجل هو الخضر صاحب موسى عليه السلام أنه نبي، هذا هو الصحيح فيه، وليس مجرد رجل صالح بل الصحيح فيه أنه نبي؛ ولهذا قال: وَمَا فَعَلْتُهُ عَنْ أَمْرِي [الكهف:82] أي: عن أمر الله ، وجاء في القصة نفسها في الصحيح أنه قال لـموسى: إنك على علم من علم الله علمك الله إياه لا أعلمه أنا، وأنا على علم من علم الله علمنيه لا تعلمه أنت فهو من الأنبياء؛ ولهذا قال: فَأَرَادَ رَبُّكَ أَنْ يَبْلُغَا أَشُدَّهُمَا [الكهف:82] وقال: وَمَا فَعَلْتُهُ عَنْ أَمْرِي [الكهف:82] والرسول هو الذي يعلم إرادة الله إذا جاءه الوحي بذلك، وفي قصة السفينة نسب الأمر إليه فَأَرَدْتُ أَنْ أَعِيبَهَا [الكهف:79] هذا والله أعلم؛ لأن الرب ينسب إليه الشيء الطيب، والعيب ظاهره ليس من الشيء الطيب، فنسبه إلى نفسه قال: فَأَرَدْتُ أَنْ أَعِيبَهَا [الكهف:79] وهذا عيب يراد منه الإصلاح، يراد منه أن تسلم السفينة حتى لا يأخذها الملك؛ لأنه كان يأخذ كل سفينة صالحة سليمة، فأراد الخضر أن يعيبها لتسلم من هذا الملك، ليراها معيبة خاربة تسلم من شره وظلمه، فلما كان ظاهر الأمر لا يناسب ولا يليق بإضافته لله نسبه إلى نفسه فقال: فَأَرَدْتُ أَنْ أَعِيبَهَا [الكهف:79].\nالمقدم: وعند ذكر الأبوين المؤمنين: فَأَرَدْنَا أَنْ يُبْدِلَهُمَا رَبُّهُمَا [الكهف:81]؟\nالشيخ: كذلك لما كان أمراً طيباً نسبه إلى نفسه؛ لأنه مأمور من جهة الله  أردنا وذكر نون الجمع لأنه نبي، والنبي رجل عظيم، فناسب أن.. أردنا؛ ولأنه عن أمر الله وعن توجيه الله، فناسب أن يقال فيه: أردنا، ولأنه عمل طيب، فناسب أن يقال فيه: أردنا؛ لأنه كان شيء طيب ومناسب، فيه مصلحة، ولما كان أمر اليتيمين فيه خير عظيم وصلاح لهما ومنفعة لهما قال: فَأَرَادَ رَبُّكَ [الكهف:82] فنسب الخير إليه سبحانه وتعالى، وهذا من جنس قول الجن في سورة الجن، حيث قال سبحانه عن الجن: وَأَنَّا لا نَدْرِي أَشَرٌّ أُرِيدَ بِمَنْ فِي الأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا [الجن:10] فالشر لم يضفه إليه ، أَشَرٌّ أُرِيدَ بِمَنْ فِي الأَرْضِ لم يضفه إلى الله، ولما جاء الرشد قال: أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا [الجن:10] فنسبه إلى الله سبحانه وتعالى؛ لأن الرشد خير ومنفعة، فنسب إلى الله، والشر لا ينسب إليه؛ ولهذا في الحديث: والشر ليس إليك وهذا من الأدب الصالح، من آداب الجن في هذا المؤمنين، ومن آداب الخضر عليه الصلاة والسلام قال في العيب: فَأَرَدْتُ أَنْ أَعِيبَهَا [الكهف:79] وفي اليتيمين: فَأَرَادَ رَبُّكَ [الكهف:82] وهذا من الأدب الصالح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6585/توجيه-الفاظ-الارادة-في-قصة-الخضر-مع-موسى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20302.mp3","categories":["التفسير"]},{"id":8558,"question":"له سؤال ثانٍ في هذه الرسالة يقول: للنبي ﷺ يوم القيامة ثلاث شفاعات فلمن تجوز الشفاعة الأولى والثانية والثالثة؟","title":"أنواع شفاعات النبي صلى الله عليه وسلم يوم القيامة","answer":"الجواب: له ﷺ ثلاث شفاعات خاصة به عليه الصلاة والسلام، إحداها الشفاعة العظمى في أهل الموقف يوم القيامة، فيشفع لهم حتى يقضى بينهم، وهذا هو المقام المحمود الذي قال فيه سبحانه: عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا [الإسراء:79].\nفهذا المقام المحمود الذي يبعثه الله يوم القيامة، وهو أنه يشفع في أهل الموقف عليه الصلاة والسلام، .. يشفع إلى الله أن يقضي بينهم في هذا الموقف العظيم حتى ينصرف كل إلى ما كتب الله له.\nالشفاعة الثانية: الشفاعة في أهل الجنة حتى يدخلوا الجنة، فإنهم لا يدخلونها إلا بشفاعته عليه الصلاة والسلام، فيشفع إلى ربه فيؤذن لهم في دخول الجنة.\nالشفاعة الثالثة: خاصة بعمه أبي طالب ، يشفع في عمه أبي طالب أن يخفف عنه، قال ﷺ: إنه وجده في غمرات النار، فشفع له حتى صار في ضحضاح من النار فالرسول ﷺ شفع لعمه أبي طالب فقط في التخفيف لا في الخروج؛ لأنه كافر مات كافراً، هذا الذي عليه أهل العلم والتحقيق، أنه مات كافراً ، أراده النبي ﷺ عند موته أن يقول: لا إله إلا الله، فأبى، وقال: هو على ملة عبد المطلب ، نعوذ بالله، فمات على الكفر بالله.\nفالرسول ﷺ شفع له بأن يكون في ضحضاح من النار، بسبب ما حصل من نصره للنبي ﷺ وتعبه وحمايته له عليه الصلاة والسلام، حرص ﷺ أن يسلم ولكن لم يقدر له الإسلام، فصار هذا من الآيات الدالة على أنه ﷺ لا يملك هداية أحد، الهداية بيد الله ، هو الذي يهدي من يشاء، ولهذا لما مات عمه أبو طالب على الكفر أنزل الله في حقه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56] وقال سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272] .. لهذا شفع فيه أن يكون في ضحضاح من النار يغلي منه دماغه نسأل الله العافية، فقد قال ﷺ: أهون الناس عذاباً يوم القيامة أبو طالب ؛ فإنه في ضحضاح من النار يغلي منه دماغه أو كما قال عليه الصلاة والسلام، وفي لفظ آخر يقول ﷺ: إن أهون أهل النار عذاباً يوم القيامة من يكون له نعلان من نار يغلي منهما دماغه، فهو يرى أنه أشد الناس عذاباً وهو أهونهم عذاباً نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خير، هذه ثلاث شفاعات التي تفضلتم ببيانها خاصة به عليه الصلاة والسلام، معنى هذا أن هناك شفاعات أخرى؟\nالشيخ: نعم، في شفاعات أخرى، في شفاعة فيمن دخل النار وأن لا يدخلها، ... أن يخرج منها ومن لم يدخلها أن لا يدخلها من العصاة، فإن العصاة قسمان: قسم يعفى عنه قبل دخول النار بالشفاعة أو برحمة الله ، وعفوه جل وعلا، وقسم يدخلون النار بمعاصيهم وسيئاتهم ثم بعدما يمضي عليهم ما شاء الله في النار يخرجون منها بشفاعة الشفعاء أو برحمة الرب سبحانه المجردة من دون شفاعة أحد؛ لأنه كتب جل وعلا أنه لا يخلد فيها إلا الكفرة، النار لا يخلد فيها إلا الكفار، أما العصاة فإنهم يمكثون فيها ما شاء الله ثم يخرجون، هذا هو الذي عليه أهل الحق، أهل السنة والجماعة ، أن العصاة لا يخلدون في النار، بل يمكثون فيها ما شاء الله ثم يخرجهم الله من النار إلى نهر يقال له: نهر الحياة ، فينبتون فيه كما تنبت الحبة في حميل السيل، وهؤلاء الذين يخرجون من النار أقسام:\nمنهم من يخرج بشفاعة النبي صلى الله عليه وسلم، وهم أقسام، ومنهم من يخرج بشفاعة غيره من الأنبياء، ومنهم من يخرج بشفاعة الملائكة، ومنهم من يخرج بشفاعة المؤمنين والأفراط، ومنهم من يبقى في النار حتى يخرجه الله برحمته جل وعلا من دون شفاعة أحد، فإذا شفع الشفعاء وانتهى أمرهم يخرج الله من النار من كان فيها من بقية أهل التوحيد، الذين ماتوا على بعض السيئات والمعاصي، فيخرجهم سبحانه من النار فضلاً منه ورحمة سبحانه وتعالى.\nالمقدم: جزاكم الله خيراً، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/6637/انواع-شفاعات-النبي-صلى-الله-عليه-وسلم-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20610.mp3","categories":["التفسير","التوسل والشفاعة"]},{"id":8619,"question":"له سؤال ثالث في هذه الرسالة يقول فيه: قال الله تعالى: لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالأَنصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ [التوبة:117] إلى قوله : يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ [التوبة:119] يسأل عن تفسير الآيات القرآنية الكريمة؟","title":"معنى قوله تعالى: (لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ ...)","answer":"الجواب: معناها واضح، يخبر سبحانه أنه تاب على النبي ﷺ والمهاجرين والأنصار بسبب أعمالهم الطيبة، واتباعهم للرسول ﷺ في ساعة العسرة وهي غزوة تبوك، فأخبر أنه تاب عليهم وأكد التوبة مرة أخرى بسبب أعمالهم الطيبة، وبسبب جهادهم في سبيل الله، فتاب عليهم وعفا عنهم وغفر لهم سبحانه وتعالى بسبب أعمالهم الصالحة، وتوبتهم الصادقة، وهكذا الثلاثة الذين خلفوا وهم: كعب بن مالك ، وصاحباه، تخلفوا عن غزوة تبوك بسبب شيء من الكسل والتساهل حتى فاتهم الغزو وصار تخلفهم بدون عذر، فلما قدم النبي ﷺ من تبوك وسألهم أخبروه أنه لا عذر لهم، وإنما هو تساهل حتى فرط الأمر، فأمر النبي ﷺ بهجرهم وعدم تكليمهم حتى يقضي الله فيهم، فمر عليهم خمسون ليلة وهم مهجورون لا يكلمهم أحد، ثم أنزل الله توبتهم في هذه الآيات في قوله: وَعَلَى الثَّلاثَةِ [التوبة:118] .\nفتاب الله عليهم وكلمهم النبي ﷺ وأمر الناس وأذن لهم بتكليمهم بسبب الصدق؛ ولهذا قال تعالى: اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ [التوبة:119] فالصدق عاقبته حميدة، والكذب عاقبته وخيمة، فهؤلاء الثلاثة صدقوا وصبروا فتاب الله عليهم وعفا عنهم . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6747/معنى-قوله-تعالى-لقد-تاب-الله-على-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21013.mp3","categories":["التفسير"]},{"id":8626,"question":"والرسالة الأولى في حلقة هذه الليلة وردتنا من المرسل (م. ن. ك) مدرس مصري بالجمهورية العربية اليمنية، يقول في رسالته: قال الله تبارك وتعالى في سورة النور أعوذ بالله من الشيطان الرجيم: الْخَبِيثَاتُ لِلْخَبِيثِينَ وَالْخَبِيثُونَ لِلْخَبِيثَاتِ وَالطَّيِّبَاتُ لِلطَّيِّبِينَ وَالطَّيِّبُونَ لِلطَّيِّبَاتِ أُوْلَئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ [النور:26] وقال تعالى في سورة النور أيضاً: الزَّانِي لا يَنكِحُ إلَّا زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لا يَنكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَلِكَ عَلَى الْمُؤْمِنِينَ [النور:3]، أود من فضيلتكم تفسير هاتين الآيتين الكريمتين، وفقكم الله؟","title":"تفسير قوله تعالى: (الْخَبِيثَاتُ لِلْخَبِيثِينَ...)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهاتان الآيتان الكريمتان استنبط منهما أهل العلم أنه لا ينبغي للمؤمن أن يتزوج الزانية حتى تتوب؛ لأن الزنا خبث، والزواني خبيثات، فينبغي للمؤمن أن يتحرى في زواجه النساء الطيبات المعروفات بالعفة والاستقامة في دينهن، ولهذا قال عليه الصلاة والسلام: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك فصاحبات الدين هن الطيبات المعروفات بالعفة والاستقامة وحسن السيرة وحسن العقيدة، أما المعروفات بالانحراف والفسق والفساد فينبغي للمؤمن أن يتجنبهن؛ لأنهن خبيثات من جهة السيرة ومن جهة العمل.\nولا ينبغي للمؤمنة أيضاً أن تنكح الخبيث المعروف بالفسق وعدم الاستقامة؛ لتعاطيه المسكرات، أو لكونه يرتكب الفواحش من الزنا واللواط، فينبغي للمؤمنة أن تتجنب هذا الصنف من الناس، وأن لا ترضى بالزواج عليه، وإذا وقع في هذا البلاء، بأن كان طيباً ثم وقع في الخبث مثل شرب المسكرات.. في الزنا.. في اللواط، صار لها الفسخ، صار لها عذر أن تطلب الفسخ والمفارقة؛ لأنه صار خبيثاً بعدما كان طيباً، والله يقول جل وعلا: الْخَبِيثَاتُ لِلْخَبِيثِينَ [النور:26] ويقول: وَالطَّيِّبَاتُ لِلطَّيِّبِينَ [النور:26] ويقول: الزَّانِي لا يَنكِحُ إلَّا زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لا يَنكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَلِكَ عَلَى الْمُؤْمِنِينَ [النور:3].\nفالواجب على المسلمة أن تتقي الله، وأن تتوب إلى الله مما وقع منها من زنا أو غيره من الفساد والمعاصي حتى تكون طيبة، وعلى الزاني كذلك والعاصي والفاسق أن يتوب إلى الله حتى يكون من الطيبين وحتى يزول عنه الخبث، وخبث المعاصي خبث شديد وخطير، وأعظم من ذلك خبث الكفر نعوذ بالله والشرك، وأطيب الطيب طيب الإيمان والتقوى والاستقامة، فالطاعات كلها طيب، والإيمان والتقوى كله طيب، والمؤمن هو الطيب، فالواجب على كل مسلم وكل مسلمة العناية بالأسباب التي تجعلهما من الطيبين، والحذر من المعاصي والسيئات التي تنقلهما إلى صفة الخبثاء، نسأل الله للجميع الهداية. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6760/تفسير-قوله-تعالى-الخبيثات-للخبيثين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21101.mp3","categories":["التفسير"]},{"id":8631,"question":"يقول: قال الله تعالى: وَإِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَابَّةً مِنَ الأَرْضِ تُكَلِّمُهُمْ أَنَّ النَّاسَ كَانُوا بِآيَاتِنَا لا يُوقِنُونَ [النمل:82] ما تفسير هذه الآية الكريمة، جزاكم الله خير؟","title":"تفسير قوله تعالى: (وَإِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ ...)","answer":"الجواب: جاء في الأحاديث الصحيحة عن رسول الله ﷺ: أنها دابة تخرج في آخر الزمان، عند طلوع الشمس من مغربها، قبلها بقليل أو بعدها بقليل مثلما قال الله جل وعلا، والله أعلم بمكثها في الأرض، ولكنها تخرج في آخر الزمان، وتكلم الناس كما قال الله ، وأما تفاصيل أخبارها فليس في تفاصيل أخبارها أحاديث معلومة مفصلة فيما أعلم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6769/تفسير-قوله-تعالى-واذا-وقع-القول-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21110.mp3","categories":["التفسير"]},{"id":8635,"question":"والرسالة الأولى في حلقة هذه الليلة وردتنا من المرسل (م. ن. ك) مدرس مصري بالجمهورية العربية اليمنية، يقول في رسالته: قال الله تبارك وتعالى في سورة النور أعوذ بالله من الشيطان الرجيم: الْخَبِيثَاتُ لِلْخَبِيثِينَ وَالْخَبِيثُونَ لِلْخَبِيثَاتِ وَالطَّيِّبَاتُ لِلطَّيِّبِينَ وَالطَّيِّبُونَ لِلطَّيِّبَاتِ أُوْلَئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ [النور:26] وقال تعالى في سورة النور أيضاً: الزَّانِي لا يَنكِحُ إلَّا زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لا يَنكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَلِكَ عَلَى الْمُؤْمِنِينَ [النور:3]، أود من فضيلتكم تفسير هاتين الآيتين الكريمتين، وفقكم الله؟","title":"تفسير قوله تعالى: (الْخَبِيثَاتُ لِلْخَبِيثِينَ...)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهاتان الآيتان الكريمتان استنبط منهما أهل العلم أنه لا ينبغي للمؤمن أن يتزوج الزانية حتى تتوب؛ لأن الزنا خبث، والزواني خبيثات، فينبغي للمؤمن أن يتحرى في زواجه النساء الطيبات المعروفات بالعفة والاستقامة في دينهن، ولهذا قال عليه الصلاة والسلام: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك فصاحبات الدين هن الطيبات المعروفات بالعفة والاستقامة وحسن السيرة وحسن العقيدة، أما المعروفات بالانحراف والفسق والفساد فينبغي للمؤمن أن يتجنبهن؛ لأنهن خبيثات من جهة السيرة ومن جهة العمل.\nولا ينبغي للمؤمنة أيضاً أن تنكح الخبيث المعروف بالفسق وعدم الاستقامة؛ لتعاطيه المسكرات، أو لكونه يرتكب الفواحش من الزنا واللواط، فينبغي للمؤمنة أن تتجنب هذا الصنف من الناس، وأن لا ترضى بالزواج عليه، وإذا وقع في هذا البلاء، بأن كان طيباً ثم وقع في الخبث مثل شرب المسكرات.. في الزنا.. في اللواط، صار لها الفسخ، صار لها عذر أن تطلب الفسخ والمفارقة؛ لأنه صار خبيثاً بعدما كان طيباً، والله يقول جل وعلا: الْخَبِيثَاتُ لِلْخَبِيثِينَ [النور:26] ويقول: وَالطَّيِّبَاتُ لِلطَّيِّبِينَ [النور:26] ويقول: الزَّانِي لا يَنكِحُ إلَّا زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لا يَنكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَلِكَ عَلَى الْمُؤْمِنِينَ [النور:3].\nفالواجب على المسلمة أن تتقي الله، وأن تتوب إلى الله مما وقع منها من زنا أو غيره من الفساد والمعاصي حتى تكون طيبة، وعلى الزاني كذلك والعاصي والفاسق أن يتوب إلى الله حتى يكون من الطيبين وحتى يزول عنه الخبث، وخبث المعاصي خبث شديد وخطير، وأعظم من ذلك خبث الكفر نعوذ بالله والشرك، وأطيب الطيب طيب الإيمان والتقوى والاستقامة، فالطاعات كلها طيب، والإيمان والتقوى كله طيب، والمؤمن هو الطيب، فالواجب على كل مسلم وكل مسلمة العناية بالأسباب التي تجعلهما من الطيبين، والحذر من المعاصي والسيئات التي تنقلهما إلى صفة الخبثاء، نسأل الله للجميع الهداية. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6760/تفسير-قوله-تعالى-الخبيثات-للخبيثين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21101.mp3","categories":["التفسير"]},{"id":8725,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع آدم السوداني مقيم برياض الخضراء، أخونا يسأل عن تفسير بعض آيات من القرآن الكريم بدأها بالسؤال عن تفسير قوله تعالى: أعوذ بالله من الشيطان الرجيم الم ۝ غُلِبَتِ الرُّومُ ۝ فِي أَدْنَى الأَرْضِ وَهُمْ مِنْ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ [الروم:1-3] أرجو من فضيلة الشيخ تفسير هذه الآية الكريمة، ومن هم الروم المذكورون فيها؟","title":"المقصود بالروم في قوله تعالى: {الم * غُلِبَتِ الرُّومُ}","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فـالروم هم النصارى المعروفون، وكانت الحالة بينهم وبين الفرس سجال في الحرب، يدال هؤلاء على هؤلاء تارة وهؤلاء على هؤلاء تارة، فأخبر الله  أنهم غلبوا -يعني: غلبتهم الفرس- في أدنى الأرض وهم من بعد غلبهم سيغلبون في بضع سنين، فوقع ذلك فغلبت الروم الفرس وكان ذلك في أول المبعث حين كان النبي ﷺ بمكة عليه الصلاة والسلام، وكان ذلك من الآيات والدلائل على صدقه ﷺ وأنه رسول الله حقًا إذ وقع الأمر كما أخبر به في كتابه العظيم.\nالله جل وعلا هو العالم بالمغيبات، ويخبر نبيه بما يشاء منها  كما أخبره عن كثير مما يكون في آخر الزمان، وكما أخبره عما كان فيما مضى من الزمان من أخبار عاد وثمود وقوم نوح وفرعون وقومه وغير ذلك، وكما أخبره أيضًا عليه الصلاة والسلام بما يكون يوم القيامة وحال أهل الجنة وحال أهل النار إلى غير ذلك، فهذا من جملة الأخبار الغيبية التي أخبر بها القرآن فوقعت كما أخبر، وكان ذلك من علامات صدق رسوله محمد عليه الصلاة والسلام. نعم.\nالمقدم: جزاك الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6875/المقصود-بالروم-في-قوله-تعالى-الم-غلبت-الروم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/16101.mp3","categories":["التفسير"]},{"id":8726,"question":"يسأل أيضًا عن تفسير قوله تعالى: وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ ۝ وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّى عَادَ كَالْعُرْجُونِ الْقَدِيمِ ۝ لا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ وَلا اللَّيْلُ سَابِقُ النَّهَارِ وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ [يس:38-40].","title":"تفسير قوله تعالى: {وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ...}","answer":"والمقصود أنها تجري لمستقر لها ذاهبة وآيبة، ومستقرها سجودها تحت العرش في سيرها طالعة وغاربة، ذلك تقدير العزيز العليم، هو الذي قدر هذا سبحانه وتعالى، العزيز المنيع الجناب الغالب لكل شيء، العليم بأحوال خلقه سبحانه وتعالى.\nوَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ [يس:39] الله جعل القمر له منازل كما أن الشمس لها منازل، في كل ليلة له منزلة وهي الثمانية وعشرون منزلة، ويقال لها: ثمانية وعشرون نوءًا، يعني: نجمًا ينزلها كل ليلة، والليلة التاسعة والعشرين ليلة الاستصغار؛ وليلة الثلاثين كذلك إذا لم يهل، فقد يهل في الثلاثين ويكون الشهر ناقصًا، وقد يستكمل الشهر فلا يهل إلا في الليلة الحادية والثلاثين، وإذا كان في آخر الشهر ضعف نوره وصار في آخر الشيء كالعرجون القديم، والعرجون هو: العسب الذي يكون في قدو التمر ينحني ويكون كالعرجون القديم يعني: منحنيًا ضعيفًا نوره ضعيف، وقد يذهب نوره بالكلية في آخر الشهر حتى لا يبقى له نور وإنما يبقى صورة خلقته، هذه من آيات الله سبحانه وتعالى.\nلا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ وَلا اللَّيْلُ سَابِقُ النَّهَارِ [يس:40] لما ذكر أن القمر مقدر منازل، وهكذا الشمس تجري لمستقر لها؛ ذكر أن الليل والنهار جاريان يعني كما أمر الله، والشمس والقمر جاريان كما أمر الله سبحانه وتعالى، فالشمس لا تدرك القمر والقمر كذلك لا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ وَلا اللَّيْلُ سَابِقُ النَّهَارِ [يس:40] يعني: كل من هذه المخلوقات لها مقدار بإذن الله سبحانه وتعالى لا تتجاوزه، لا تتجاوزه أبدًا بل هي في سيرها تسير سيرًا متقنًا؛ وهكذا القمر، وهكذا الليل والنهار، فالشمس لا تخرج في سلطان القمر ولا تذهب بنور القمر، والقمر كذلك لا يذهب بنورها ولا يطلع في سلطانها، كل له وقت وكل له سلطان، فالشمس سلطانها في النهار والقمر سلطانه بالليل، لا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ يعني: تحيط به وتقضي عليه وتذهب بنوره ليس لها سلطان في هذا فسلطانها في النهار، والقمر كذلك لا يذهب بنورها، هو له سلطان ولها سلطان، كل في فلك يسبح، كل في فلكه الذي قدره الله له سبحانه وتعالى، وهكذا الليل والنهار، هذا في وقته يأتي بظلامه والنهار في وقته يأتي بضيائه، لا يسبق هذا هذا ولا هذا هذا، كل منهما له سير مقدر لا يزيد عليه ولا ينقص عنه إلا بإذن الله، فتارة يزيد الليل وينقص النهار، وتارة بالعكس، يتقارضان في مدة أربع وعشرين ساعة، هذا ينقص تارة ويزيد الآخر تارة، ثم يأتي العكس فينقص هذا ويزيد هذا؛ ولهذا يقول جل وعلا: وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ ۝ وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّى عَادَ كَالْعُرْجُونِ الْقَدِيمِ ۝ لا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ وَلا اللَّيْلُ سَابِقُ النَّهَارِ وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ [يس:38-40]. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6876/تفسير-قوله-تعالى-والشمس-تجري-لمستقر-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/161002.mp3","categories":["التفسير"]},{"id":8839,"question":"أخ سوداني أيضًا يقول عوض الله جبران عثمان، أخونا يسأل عن تفسير قوله تعالى: بَرَاءَةٌ مِنَ اللَّهِ وَرَسُولِهِ إِلَى الَّذِينَ عَاهَدتُّمْ مِنَ الْمُشْرِكِينَ [التوبة:1]؟","title":"ما معنى: {بَرَاءَةٌ مِنَ اللَّهِ وَرَسُولِهِ إِلَى الَّذِينَ}؟","answer":"الجواب: هذه الآية نزلت في آخر حياة النبي ﷺ، وكان الرسول ﷺ قد عاهد بعض المشركين إلى مدد معلومة، وبعضهم بينه وبينه عهد مطلق، وبعضهم لا عهد له، فأنزل الله هذه الآية فيها البراءة من المشركين، وفيها نبذ العهود إليهم؛ ولهذا قال سبحانه: بَرَاءَةٌ مِنَ اللَّهِ وَرَسُولِهِ إِلَى الَّذِينَ عَاهَدتُّمْ مِنَ الْمُشْرِكِينَ ۝ فَسِيحُوا فِي الأَرْضِ أَرْبَعَةَ أَشْهُرٍ [التوبة:1-2] الآية.\nفالله أمره جل وعلا أن يتبرأ منهم، ومن كان له عهد فهو إلى مدته، ومن كان عهده مطلق أو لا عهد له جعل الله له أربعة أشهر، وبعث الصديق  وعلي  ومن معهما في عام تسع من الهجرة ينادون في الموسم: من كان له عهد عند رسول الله ﷺ فهو على مدته، ومن لم يكن له عهد أو له عهد مطلق فله أربعة أشهر، بعدها يكون حربًا للرسول ﷺ إلا أن يدخل في الإسلام.\nفهذا هو معنى الآية عند أهل العلم. نعم.","link":"https://binbaz.org.sa/fatwas/6994/ما-معنى-براءة-من-الله-ورسوله-الى-الذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16509.mp3","categories":["التفسير"]},{"id":8840,"question":"أيضًا يسأل عن تفسير الآية الرابعة من السورة الكريمة: إِلَّا الَّذِينَ عَاهَدتُّمْ مِنَ الْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْئًا وَلَمْ يُظَاهِرُوا عَلَيْكُمْ أَحَدًا فَأَتِمُّوا إِلَيْهِمْ عَهْدَهُمْ إِلَى مُدَّتِهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُتَّقِينَ [التوبة:4]؟","title":"تفسير قوله تعالى: {إِلَّا الَّذِينَ عَاهَدتُّمْ مِنَ الْمُشْرِكِينَ ...}","answer":"الجواب: على ظاهرها، الذي له عهد أمره الله أن يتم عهدهم لهم، ما لم يغيروا وينقضوا العهد أو يظاهروا أعداء المسلمين، فإن ظاهروهم وجب قتالهم، وإذا نقضوا العهد كذلك؛ ولهذا لما ساعدت قريش بني بكر على خزاعة انتقض عهد قريش وبنو بكر، وحاربهم النبي ﷺ غزا مكة وفتحها عام ثمانية للهجرة لنقضهم العهد؛ لأن خزاعة كانت في حلف رسول الله ﷺ وعهده، وكانت بنو بكر في عهد قريش وحلفهم، فهددت بنو بكر خزاعة، يعني: تعدت عليهم وأتوهم بغتة، هجموا عليهم بغتة فجأة وقاتلوهم، وهم في حلف رسول الله ﷺ، فاستنجدوا بالرسول ﷺ، وطلبوا منه أن ينصرهم ووعدهم النصر، وكانت قريش قد ساعدتهم بالمال والسلاح؛ فلهذا غزاهم النبي ﷺ وفتح الله عليه مكة لنقضهم العهد، وكان قد عاهدهم عشر سنين، فلما نقضوا العهد بمساعدتهم لبني بكر انتقض عهدهم، وغزاهم النبي ﷺ وفتح الله عليه. نعم.","link":"https://binbaz.org.sa/fatwas/6995/تفسير-قوله-تعالى-الا-الذين-عاهدتم-من-المشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16510.mp3","categories":["التفسير"]},{"id":8907,"question":"نعود أيضاً إلى رسالة الأخ مصطفى محمد كاكاو ياسين من العراق أخونا يسأل في هذه الحلقة عن قول الحق تبارك وتعالى أعوذ بالله من الشيطان الرجيم : وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:68 - 69]، هل المقصود في الآية أن يفعل الإنسان الكبائر الثلاث ثم يخلد في النار أم المقصود إذا ارتكب إحدى هذه الكبائر يخلد في النار، فمثلاً ارتكب جريمة القتل مثلاً هل يخلد في النار أو لا، نرجو أن تتفضلوا بالتفسير المفصل لهذه الآية الكريمة؟","title":"ما معنى: {فَلا رَفَثَ وَلا فُسُوقَ وَلا جِدَالَ فِي الْحَجِّ}؟","answer":"الجواب: هذه الآية العظيمة فيها التحذير من الشرك والقتل والزنا وأن أصحاب هذه الجرائم متوعدون بما قاله الله سبحانه: وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا [الفرقان:68] ، قيل: إنه وادي في جهنم، وقيل: المعنى (أثاماً) يعني: إثماً كبيراً عظيماً، ولهذا فسره بقوله: يُضَاعَفْ لَهُُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:69] هذا جزاء من اقترف هذه الجرائم الثلاث؛ أنه يضاعف له العذاب ويخلد في العذاب مهاناً لا مكرماً، وهذه الجرائم الثلاث مختلفة في المراتب، فجريمة الشرك هي أعظم الجرائم وهي أعظم الذنوب وصاحبها مخلد في النار أبد الآباد لا يخرج من النار أبداً، كما قال الله سبحانه في كتابه العظيم: مَا كَانَ لِلْمُشْرِكِينَ أَنْ يَعْمُرُوا مَسَاجِدَ اللَّهِ شَاهِدِينَ عَلَى أَنفُسِهِمْ بِالْكُفْرِ أُوْلَئِكَ حَبِطَتْ أَعْمَالُهُمْ وَفِي النَّارِ هُمْ خَالِدُونَ [التوبة:17]، نعوذ بالله، وقال سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَاا كَانُوا يَعْمَلُونَ [الأنعام:88]، قال : وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ[الزمر:65]، قال في حقهم: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37]، والآيات في هذا كثيرة.\nفالمشرك إذا مات على شركه ولم يتب فإنه مخلد في النار والجنة عليه حرام والمغفرة عليه حرام بإجماع المسلمين، قال تعالى: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ [المائدة:72]، وقال سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْْ يَشَاءُ [النساء:48]، فجعل المغفرة حراماً على المشرك إذا مات على شركه، أما ما دون الشرك فهو معلق، ما دون الشرك فهو تحت مشيئة الله سبحانه وتعالى.\nفالخلاصة: أن المشرك إذا مات على شركه فهو مخلد في النار أبد الآباد بإجماع أهل العلم، وذلك مثل الذي يعبد الأصنام ويستغيث بها، أو الأشجار أو الأحجار أو الكواكب أو الشمس أو القمر أو غير ذلك، أو يعبد الأموات الذين يسمونهم بالأولياء أو يعبد الأنبياء أو يعبد الملائكة يستغيث بهم وينذر لهم، يطلبهم المدد والعون عند قبورهم أو بعيداً من قبورهم، مثلما يقول بعضهم: يا سيدي فلان! اشف مريضي، المدد المدد يا سيدي البدوي، يا سيدي عبد القادر، يا رسول الله! المدد المدد، أو يا حسين، أو يا فاطمة، أو يا ست زينب أو غير ذلك ممن يدعوهم المشركون، هذا كله من الشرك الأكبر والعياذ بالله! إذا مات عليه صاحبه صار من أهل النار نعوذ بالله والخلود فيها.\nأما الجريمة الثانية: وهي القتل، والثالثة: وهي الزنا، هاتان الجريمتان دون الشرك معصيتان، فإذا كان من تعاطاهما لم يستحلهما يعلم أنهما محرمان، يعلم أن هاتين الجريمتين معصيتان محرمتان ولكن حمله الغضب أو الهوى أو ما أشبه ذلك على إقدامه على القتل بسبب البغضاء والعداوة أو أسباب أخرى، وحمله الهوى والشيطان على الزنا وهو يعلم أن القتل محرم بغير حق وأن الزنا محرم، فهاتان الجريمتان توجبان النار، وغضب الله  إلا أن يعفو الله عن صاحبهما لأعمال صالحة أو توبة قبل الموت، فإذا تاب عفا الله عنه، وقد يعفى عنه لأعمال صالحة كثيرة له أو بشفاعة الشفعاء أو بدعاء المسلمين له.. إلى غير ذلك، وقد يعذب في النار على قدر المعاصي التي مات عليها، وهذا واقع لكثير من الناس؛ يعذبون على معاصيهم ثم يخرجهم الله من النار برحمته سبحانه وتعالى، تارة بأسباب الشفعاء كشفاعة نبينا صلى الله عليه وسلم وشفاعة الملائكة والأفراط والمؤمنين، وقد يخرج الإنسان من النار بشفاعة هؤلاء بعدما يمضي فيها ما كتب الله له من العذاب.\nويبقى في النار أقوام من أهل التوحيد لا تنالهم شفاعة الناس فيخرجهم الله سبحانه وتعالى برحمته جل وعلا؛ لأنهم ماتوا على توحيد على إيمان ولكن لهم أعمال خبيثة ولهم معاصي دخلوا بها النار، فإذا طهروا منها ومضت المدة التي كتب الله عليهم أخرجوا من النار رحمة من الله عز وجل ويلقون في نهر يقال له: نهر الحياة، من أنهار الجنة، ينبتون فيه كما تنبت الحبة من حميل السيل، فإذا تم خلقهم أدخلهم الله الجنة، وبهذا يعلم أن العاصي كالقاتل والزاني لا يخلد خلود الكفار بل خلود خاص غير خلود الكفار، يقول سبحانه: وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:69] هذا خلود متنوع مختلف، فخلود المشرك هذا خلود دائم ليس لهم منه محيص وليس لهم منها مخرج كما قال جل وعلا: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167]، هكذا في سورة البقرة.\nوقال سبحانه: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37] هكذا في سورة المائدة، فالرب عز وجل بين لنا أنهم لا يخرجون من النار، يعني: الكفرة، أما العصاة فيخرجون إذا تمت المدة التي كتب الله عليهم، يخرجون من النار إما بشفاعة الشفعاء وإما بمجرد رحمته سبحانه وتعالى يعني: رحمة الله جل وعلا من دون شفاعة أحد، فإن بقايا أهل التوحيد في النار يخرجهم الله منها بدون شفاعة أحد بل برحمته سبحانه وتعالى فلا يبقى في النار إلا أهلها وهم الكفرة، فتطبق عليهم ولا يخرج منهم أحداً بعد ذلك نسأل الله العافية، ويسمى وجود العصاة في النار مدة طويلة يسمى: خلوداً، عند العرب الإقامة الطويلة تسمى خلود، كما في قول بعض الشعراء:\nأقاموا فأخلدوا .................\nيعني: طولوا الإقامة، فالمقيم طويلاً يسمى مخلد، ويقال: أخلد في المكان يعني: طول فيه الإقامة، فالزاني والقاتل تكون إقامتهما أكثر من غيرهما من العصاة، والقتل أقبح وأشر من الزنا، والزنا من أعظم الجرائم لما فيه من الفساد في الأرض، فهما جريمتان عظيمتان يحصل لأصحابهما الخلود في النار خلود يليق بهما على حسب معاصيهما، فهو خلود له نهاية وهكذا خلود الذي يقتل نفسه يخلد في النار لكن خلود له نهاية بخلاف خلود الكافر فإنه لا نهاية له، أما العاصي من الزاني والقاتل نفسه والقاتل لغيره هؤلاء يطول مكثهم في النار ويكثر لكنهم يخرجون بإذن الله ومشيئته سبحانه وتعالى بعد مضي المدة التي كتبها الله عليهم وهم فيها متفاوتون بعضهم أطول من بعض على حسب كثرة معاصيهم وكثرة تساهلهم بأمر الله واستخفافهم بحقه، على حسب هذا تكون الإقامة مع أنها لا تستمر بل لها نهاية فهو خلود له نهاية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7063/ما-معنى-فلا-رفث-ولا-فسوق-ولا-جدال-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_141/14103.mp3","categories":["التفسير"]},{"id":8920,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الرياض وباعثها أخونا أبو صلاح الدين، أخونا بدأ رسالته يقول: أحب أن أقدم لكم جزيل الشكر بعد الله وأدعو الله لكم أن يغفر لكم ويسدد خطاكم ويبارك لكم في أعماركم.ثانياً: أود منكم جزاكم الله خيراً أن تنقلوا سلامي وتحياتي لجميع العلماء المشاركين في هذا البرنامج، وأخص منهم سماحة الشيخ الوالد الكريم عبد العزيز بن باز وأخبره أني والله أحبه في الله وأدعو له دائماً في ظهر الغيب أن يجمعنا الله في الجنة، جعلك الله من أهلها والمسلمين آمين، وبعد: فلي عدة أسئلة أحب الإجابة عنها ولكم منا الدعاء:أولاً: أرجو شرح معنى هذه الآية التي احترت في فهم معناها كثيراً والقول الراجح في تفسيرها يقول الحق تبارك وتعالى: أعوذ بالله من الشيطان الرجيم: فَأَمَّا الَّذِينَ شَقُوا فَفِي النَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ ۝ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَوَاتُ وَالأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِمَا يُرِيدُ ۝ وَأَمَّا الَّذِينَ سُعِدُوا فَفِي الْجَنَّةِ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَوَاتُ وَالأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ عَطَاءً غَيْرَ مَجْذُوذٍ [هود: 106-108]، هل يفهم من هذا أن من دخل الجنة يخرج منها إذا شاء الله، وهل نسخت هاتان الآيتان بشيء من القرآن إذ أنهما وردتا في سورة مكية؟","title":"ما معنى: {فَأَمَّا الَّذِينَ شَقُوا فَفِي النَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ}؟","answer":"","link":"https://binbaz.org.sa/fatwas/7077/ما-معنى-فاما-الذين-شقوا-ففي-النار-لهم-فيها-زفير-وشهيق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_142/14201.mp3","categories":["التفسير"]},{"id":8924,"question":"بارك الله فيكم، سنعود إلى بقية أسئلتك يا أخ أبو إبراهيم من البحرين في حلقة قادمة إن شاء الله، وننتقل إلى رسالة أحد الإخوة يقول: أحمد هذال الدحين أخونا يرجو تفسير قول الحق تبارك وتعالى: أعوذ بالله من الشيطان الرجيم: إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ [فاطر:28]؟","title":"العلماء الربانيون هم أهل خشيته سبحانه","answer":"الجواب: هذه الآية آية عظيمة وهي تدل على أن العلماء وهم العلماء بالله والعلماء بدينه وبكتابه العظيم وسنة رسوله الكريم، هؤلاء هم أشد الناس خشية لله وهم أكمل الناس خشية لله، فالمعنى (إنما يخشى الله) يعني: الخشية الكاملة، هم العلماء بالله الذين عرفوا ربهم بأسمائه وصفاته سبحانه وعظيم حقه، وتبصروا في شريعته وعرفوا ما عنده من النعيم لمن اتقاه وما عنده من العذاب لمن عصاه وخالف أمره، فهم لكمال علمهم بالله وكمال بصيرتهم بحقه هم أشد الناس خشية لله، هم أكمل الناس خوفًا من الله وخشية له سبحانه وتعالى، وليس معناه أنه لا يخشى الله إلا العلماء؛ لا، فكل مسلم يخشى الله، كل مؤمن ومؤمنة يخشى الله، كل مؤمن يخشى الله كل مؤمنة تخشى الله وتخاف الله، المسلمون كلهم يخافون الله لكن الخوف متفاوت ليسوا على حد سواء، فكل ما كان المؤمن أبصر بالله وأعلم بالله كان خوفه لله أكثر.\nوهكذا المؤمنة كلما كانت أعلم بالله وأعلم بصفاته وعظيم حقه كان خوفها من الله وكان خشيتها لله أكمل من غيرها، وكلما قل العلم وقلت البصيرة قل الخوف من الله وقلت الخشية لله سبحانه وتعالى، فالناس متفاوتون في هذا الباب حتى العلماء متفاوتون، كلما كان العالم أقوم بحق الله وكلما كان العالم أعلم بالله وبدينه وأعلم بأسمائه وصفاته صارت خشيته لله أكمل، وكلما نقص العلم نقصت الخشية لله، ولكن جميع المؤمنين والمؤمنات كلهم يخشون الله سبحانه وتعالى على حسب علمهم ودرجاتهم في الإيمان مقل ومستكثر، ولهذا يقول جل وعلا: إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُوْلَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ ۝ جَزَاؤُهُمْ عِنْدَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ذَلِكَ لِمَنْ خَشِيَ رَبَّهُ [البينة: 7-8].\nويقول سبحانه: إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ [الملك:12]، فهم مأجورون على خشيتهم لله وإن كانوا غير علماء وإن كانوا من العامة، لكن الكمال في الخشية يكون للعلماء لكمال بصيرتهم وكمال علمهم بالله، تكون خشيتهم لله أعظم، وبهذا يتضح معنى الآية وأن معناها: إِنَّمَا يَخْشَى اللَّهَ [فاطر:28] يعني: الخشية الكاملة، الخشية الكاملة العظيمة إنما تكون من أهل العلم بالله وأهل البصيرة الذين عظموا الله وعظموا حقه وعرفوا صفاته وأسماءه فهم أكمل الناس خشية لله سبحانه وتعالى وبقية المؤمنين والمؤمنات هم على حسب علمهم وتقواهم في الخشية لله والخوف منه سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/7081/العلماء-الربانيون-هم-اهل-خشيته-سبحانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_142/14205.mp3","categories":["التفسير"]},{"id":8925,"question":"جزاكم الله خيراً، الرسالة التالية وصلت إلى البرنامج من العراق وباعثها أخونا: مصطفى محمد كاكاو ياسين أخونا يسأل عن قول الحق تبارك وتعالى: أَفَأَمِنُوا مَكْرَ اللَّهِ فَلا يَأْمَنُ مَكْرَ اللَّهِ إِلَّا الْقَوْمُ الْخَاسِرُونَ [الأعراف:99]؟الجواب: على ظاهرها: أَفَأَمِنُوا مَكْرَ اللَّهِ فَلا يَأْمَنُ مَكْرَ اللَّهِ إِلَّا الْقَوْمُ الْخَاسِرُونَ [الأعراف:99].","title":"تفسير قوله تعالى: (أَفَأَمِنُوا مَكْرَ اللَّهِ ...)","answer":"الجواب: على ظاهرها: أَفَأَمِنُوا مَكْرَ اللَّهِ فَلا يَأْمَنُ مَكْرَ اللَّهِ إِلَّا الْقَوْمُ الْخَاسِرُونَ [الأعراف:99].\nالمقصود من هذا التحذير من مكر الله سبحانه وتعالى، ومكر الله كونه يملي لهم ويستدرجهم بالنعم والخيرات وهم مقيمون على معاصيه وعلى خلاف أمره فهم جديرون بأن يؤخذوا على غرة ويعاقبون على غرة بسبب غفلتهم عن الله وإقامتهم على معاصيه وأمنهم من عقابه وغضبه.\nفالمعنى: احذروا ذلك، المعنى احذروا هذا الأمن وابتعدوا عنه، فالأمن من مكر الله خطر عظيم والقنوط من رحمة الله خطر عظيم، فالواجب ألا يقنط وألا يأمن بل يكون المؤمن في سيره إلى الله بين الخوف والرجاء فلا يقنط وييئس، ولا يأمن مكر الله وعقوبته ويخلد إلى البطالة والمعاصي ولكن يجب أن يكون بين ذلك، يسير إلى الله في هذه الدار ويعمل في هذه الدار بين الخوف والرجاء، فيذكر عظمته وشدة عقابه لمن خالف أمره فيخافه ويخشاه سبحانه وتعالى، ويذكر عظيم رحمته وحلمه وعظيم جوده وكرمه فيرجو إحسانه سبحانه وتعالى، ويرجو كرمه وجوده فهو بين هذا وهذا، بين الخوف والرجاء حتى يلقى ربه سبحانه وتعالى، أما الآمن الغافل المعرض الذي لا يخشى الله ولا يخشى عقابه بل هو ساه لاه في معاصيه وغفلاته فهذا على خطر أن يؤخذ على غرة فيخسر الدنيا والآخرة نعوذ بالله، يعني على خطر يؤخذ على معاصيه وعلى غير توبة فيخسر الدنيا والآخرة ويبوء بالنار والعذاب الأليم نعوذ بالله من النار، نسأل الله السلامة. نعم.","link":"https://binbaz.org.sa/fatwas/7082/تفسير-قوله-تعالى-افامنوا-مكر-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_142/14206.mp3","categories":["التفسير"]},{"id":8963,"question":"الرسالة التالية وصلت إلى البرنامج من دمشق وباعثها أحد الإخوة من هناك يقول: أخوكم أحمد الحوري ، أخونا له مجموعة من الأسئلة في سؤاله الأول يقول: قال  في كتابه العزيز: لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ [النساء:105]، هل معنى هذا أن الله أمر رسوله ﷺ بأن يحكم بكتاب الله ولا يجتهد رأيه فيما لم ينزل عليه كتاب، وهل اجتهد رسول الله ﷺ؟","title":"تفسير قوله تعالى: {لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ}","answer":"الجواب: الله جل وعلا أمره أن يحكم بينهم بما أنزل الله، قال سبحانه: وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنزَلَ اللَّهُ [المائدة:49]، فهو مأمور أن يحكم بينهم بما أنزل الله، وكان يحكم بينهم بما أنزل الله عليه الصلاة والسلام، فإذا لم يكن هناك نص عنده اجتهد عليه الصلاة والسلام وحكم بما يظهر له من الأدلة الشرعية، كما قال في الحديث الصحيح: إنكم تختصمون إلي فلعل بعضكم أن يكون ألحن بحجته من بعض، فمن قضيت له بحق أخيه فإنما أقطع له قطعة من النار فليحملها أو ليذرها، فمعنى هذا: أنه قد يجتهد في الحكم؛ لأنه لم ينزل عليه فيه شيء، فمن عرف أن الحكم ليس بمطابق وأن الشهود زور فقد أخذ قطعة من النار، فليحذر ذلك وليتق الله في ذلك، ولو كان الرسول هو الحاكم عليه الصلاة والسلام؛ لأن الحاكم ليس له إلا الظاهر من ثقة الشهود وعدالة الشهود، أو يمين المدعى عليه.\nفإذا كان المدعي أحضر شهودًا يعلم أنهم قد غلطوا ولو كانوا ثقات يعلم أنهم قد غلطوا وأن الحق ليس له ولكنه كاذب، أو يعلم أنهم شهود زور ولكن القاضي اعتبرهم عدولًا لأنهم عدلوا عنده وزكوا عنده فإن هذا المال الذي يحكم به له أو القصاص كله باطل بالنسبة إليه، وهو قد تعدى حدود الله وظلم وإن حكم له القاضي؛ لأن القاضي ليس له إلا الظاهر، ولهذا قال ﷺ: فمن قطعت له من حق أخيه شيئًا فإنما أقطع له قطعة من النار.\nفالنبي ﷺ يحكم بما أنزل الله فيما أوحاه الله إليه، وما لم يكن فيه نص اجتهد فيه عليه الصلاة والسلام حتى يتأسى به الأمة. نعم.","link":"https://binbaz.org.sa/fatwas/7120/تفسير-قوله-تعالى-لتحكم-بين-الناس-بما-اراك-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17309.mp3","categories":["التفسير"]},{"id":8988,"question":"ننتقل إلى رسالة أخرى وموضوع آخر، الرسالة من المستمع (ح. ف. ح) طالب علم في مكة المكرمة، عرضنا له سؤال في حلقة مضت، وفي هذه الحلقة يسأل ويقول: قال الله تعالى: إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]، وقال ﷺ: كمل من الرجال كثير، ولم يكمل من النساء إلا مريم بنت عمران، وآسية بنت مزاحم، وفاطمة بنت محمد، وخديجة... الحديث، هل هناك تعارض بين الآية والحديث؟ وما معنى الكمال في الحديث؟","title":"معنى الكمال في حديث «كمل من الرجال كثير ولم...»","answer":"الجواب: ليس بين الآية والحديث المذكور وما جاء في معناه تعارض، فالآية تبين لنا أن أكرم الناس عند الله أتقاهم، لا أعظمهم نسبًا ولا أكثرهم مالا، ولا أرفعهم وظيفة، يقول جل وعلا: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ [الحجرات:13]، فأكرم الناس عند الله وأفضلهم عنده أتقاهم له، معنى أتقاهم: يعني: أقومهم بحقه، بطاعته سبحانه وترك معصيته جل وعلا وهم الرسل عليهم الصلاة والسلام، ثم العلماء المستقيمون على طاعة الله وتقواه، وهم طبقات، ثم الأكمل فالأكمل والأفضل فالأفضل في طاعة الله عز وجل.\nفالمقصود أن أكمل الناس بعد الرسل هم أتقاهم، هم أكمل الناس وأكرم الناس عند الله ، ولما سئل النبي ﷺ عن أكرم الناس قال: أتقاهم.\nأما فضل خديجة وآسية ومريم بنت عمران وعائشة كذلك وفاطمة، كل هذا مسلم، وصحت به السنة وليس فيه معارضة، خديجة رضي الله عنها أم المؤمنين، وهي أم أكثر أولاد النبي عليه الصلاة والسلام، وهكذا فاطمة بنته عليه الصلاة والسلام، وهكذا مريم بنت عمران أم عيسى عليه الصلاة والسلام، وهكذا آسية بنت مزاحم امرأة فرعون ، وهكذا عائشة رضي الله عنها كلهم من كمل النساء، والكامل من النساء أقل من الكامل من الرجال، فالكمل في الرجال كثيرون ومن النساء قليلون، ولهذا بين لهم النبي ﷺ بهذا الحديث والكمال بالنظر إلى تقوى الله والقيام بحقه ، وقال في عائشة رضي الله عنها، يقول ﷺ: فضل عائشة على النساء كفضل الثريد على سائر الطعام، والثريد: هو الخبز واللحم، خبز الحنطة واللحم يقال له: ثريد، وهذا الطعام هو أفضل الطعام وأنفعه اللحم والحنطة البر.\nالمقصود أن عائشة لها فضل كبير، وخديجة كذلك، ومريم ، وآسية ، وفاطمة ، هؤلاء الخمس هم أكمل النساء وأفضل النساء، وهن متساويات في الفضل.\nوقد اختلف العلماء في تقديم بعضهن على بعض، ويكفينا أنهن أفضل النساء رضي الله عنهن وأرضاهن ورحمهن، وكمالهن من جهة تقواهن لله وقيامهن بحقه، واستقامتهن على دينه، لكن الكمل من الرجال في تقوى الله والقيام بحقه أكثر؛ لأنهم أصبر على التقوى، وهم أعلم بالله في الأغلب، وأكثر اطلاعًا على كتاب الله وسنة رسوله عليه الصلاة والسلام، وأكثر اطلاعًا على حلقات العلم وأسفارًا لطلب العلم، فلهذا يغلب على الرجال أن يكون علمهم أكثر من علم النساء وكمالهم أكثر بسبب ما حباهم الله من القوة على طلب العلم والحرص على تحصيله، ولما جبل عليه النساء من الضعف من بعض النواحي والعجز عن تحصيل العلوم من كل وجه، لما يعتريهن من الحمل والولادة وحاجات البيت وحاجات الزوج وغير ذلك.\nفالمقصود أن الكمل من الرجال بنص النبي ﷺ أكمل من الكمل من النساء، لأن الكمل من النساء قليلون لأسباب كثيرة والكمل من الرجال كثيرون، ولا تعارض بين الحديث وبين الآية الكريمة، نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7146/معنى-الكمال-في-حديث-كمل-من-الرجال-كثير-ولم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_175/17504.mp3","categories":["التفسير","شروح الحديث"]},{"id":9030,"question":"مع مطلع هذه الحلقة نعود إلى رسالة الأخ أحمد الحوري من دمشق، أخونا عرضنا بعضًا من أسئلته في حلقة مضت، وفي هذه الحلقة له مجموعة من الأسئلة يقول: قال تعالى في كتابه العزيز: وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ اللَّهِ وَلَوْ أَنَّهُمْ إِذْ ظَلَمُوا أَنفُسَهُمْ جَاءُوكَ فَاسْتَغْفَرُوا اللَّهَ وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا ۝ فَلا وَرَبِّكَ لا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا [النساء:64-65]، والسؤال هو: إن بعض المسلمين يأخذون بهذه الآية أنه لا حرج على المسلم أن يذهب ويشد الرحل إلى قبر الرسول ﷺ يسأله أن يستغفر له رسول الله ﷺ وهو في قبره، فهل هذا العمل صحيح كما قال تعالى، وهل معنى جَاءُوكَ باللغة أنه جاءوك في حياتك أم في موتك، وهل يرتد المسلم عن الإسلام إذا لم يحكم سنة رسول الله ﷺ؟ وهل التشاجر هنا على الدنيا أم على الدين؟","title":"طلب الاستغفار من النبي عليه الصلاة والسلام بعد موته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه الآية الكريمة فيها حث الأمة على المجيء إليه إذا ظلموا أنفسهم بشيء من المعاصي أو وقعوا فيما هو أكبر من ذلك من الشرك أن يجيئوا إليه تائبين نادمين حتى يستغفر لهم عليه الصلاة والسلام، وهذا المراد به في حياته ﷺ وهو يدعو المنافقين وغيرهم إلى أن يأتوا إليه ليعلنوا توبتهم ورجوعهم إلى الله  ويطلبوا منه عليه الصلاة والسلام أن يسأل الله أن يقبل توبتهم وأن يصلح أحوالهم، ولهذا قال: وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ اللَّهِ [النساء:64]، طاعة الرسل بإذن الله، من أذن الله وأراد هدايته اهتدى، ومن لم يرد الله هدايته لم يهتد، فالأمر بيده ، ما شاء كان وما لم يشأ لم يكن، وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:29]، ثم قال: وَلَوْ أَنَّهُمْ إِذْ ظَلَمُوا أَنفُسَهُمْ جَاءُوكَ يعني: النبي عليه الصلاة والسلام فَاسْتَغْفَرُوا اللَّهَ يعني: تائبين نادمين لا بمجرد القول، وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ يعني: دعا لهم بالمغفرة لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا فهو حث للعباد على أن يأتوا إلى النبي ﷺ ليعلنوا عنده توبتهم وليسأل الله لهم، وليس المراد بعد وفاته ﷺ كما يظنه بعض الجهال! لا، بعد موته لا يؤتى لهذا الغرض وإنما يؤتى للسلام عليه لمن كان في المدينة، أو وصل إليها من خارجها لقصد الصلاة في المسجد والقراءة فيه ونحو ذلك، فإذا أتى المسجد سلم على النبي ﷺ وعلى صاحبيه، لكن لا يشد الرحل من أجل زيارة القبر فقط بل من أجل المسجد وتكون الزيارة للقبر الشريف وقبري الصديق و عمر تابعة لزيارة المسجد؛ لقوله ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى، فالقبور لا يشد لها الرحال، ولكن متى وصل إلى المسجد وفي نيته السلام على الرسول ﷺ وعلى صاحبيه أو ليس في نيته ذلك فإنه يشرع له أن يسلم على النبي ﷺ وأن يسلم على صاحبيه رضي الله عنهما، لكن لا يشد الرحل لأجل زيارة القبر فقط للحديث السابق.\nوأما يتعلق بالاستغفار والتوبة فهذا يكون في حياته لا بعد وفاته، والدليل على هذا أن الصحابة  وأرضاهم لم يفعلوا ذلك وهم أعلم الناس بالنبي ﷺ وأفقه الناس، ولأنه ﷺ لا يملك ذلك بعد وفاته عليه الصلاة والسلام كما قال عليه الصلاة والسلام: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له، وأخبر عليه الصلاة والسلام أن من صلى عليه تعرض صلاته عليه، عليه الصلاة والسلام، هذا شيء خاص فيما يتعلق بالصلاة عليه عليه الصلاة والسلام، قال: من صلى علي صلى الله عليه بها عشرًا، وقال عليه الصلاة والسلام: أكثروا علي من الصلاة يوم الجمعة فإن صلاتكم معروضة علي، قيل: يا رسول الله! وكيف تعرض عليك وقد أرمت-يعني: بليت-؟! قال: إن الله حرم على الأرض أن تأكل أجساد الأنبياء.\nفهذا خاص بالصلاة عليه عليه الصلاة والسلام، وفي اللفظ الآخر: إن لله ملائكة سياحين يبلغونني عن أمتي السلام فهذا شيء خاص بالصلاة والسلام عليه عليه الصلاة والسلام أنه يبلغ ذلك، وأما أن يأتي من ظلم نفسه ليتوب عند القبر وليستغفر عند القبر فهذا لا أصل له بل هو منكر ولا يجوز، وهو وسيلة إلى الشرك، وسيلة إلى أن يأتي فيسأله الشفاعة ويسأله شفاء المريض أو كذا أو كذا، أو يسأله أن يدعو له وهذا لا يجوز؛ لأن هذا ليس من خصائصه عليه الصلاة والسلام بعد وفاته ولا من خصائص غيره، فكل من مات لا يدعى ولا يطلب منه الشفاعة لا النبي ولا غيره عليه الصلاة والسلام، وإنما الشفاعة تطلب من النبي في حياته ﷺ، يقول الرجل: يا رسول الله! اشفع لي أن يغفر الله لي؟ اشفع لي أن يشفي الله مريضي، أن يرد غائبي، أن يعطني كذا وكذا.\nوهكذا يوم القيامة بعد البعث والنشور؛ لأنهم أحياء فإن المؤمنين يأتون آدم ليشفع لهم حتى يقضى بينهم ويعتذر، ويحيلهم إلى نوح فيعتذر نوح ثم يحيلهم نوح إلى إبراهيم فيعتذر، ثم يحليهم إبراهيم إلى موسى فيعتذر، ثم يحيلهم موسى إلى عيسى فيعتذر عليهم الصلاة والسلام، ثم يحيلهم عيسى عليه الصلاة والسلام إلى محمد ﷺ فيقول: أنا لها، فيتقدم ويسجد تحت العرش عليه الصلاة والسلام ويحمد ربه بمحامد عظيمة، ثم يشفع في أهل الموقف حتى يقضى بينهم.\nوهكذا يشفع في أهل الجنة حتى يدخلوا الجنة؛ لأنه حي قائم موجود، أما في البرزخ بعد وفاته ﷺ فلا يسأل الشفاعة ولا يسأل أن يستغفر للناس، ولا يسأل شفاء المريض ولا رد الغائب، ولا غير ذلك من الأمور، وهكذا بقية الأموات لا يسألون شيئًا من هذه الأمور، بل يدعى لهم ويستغفر لهم إذا كانوا مسلمين. نعم.\nكذلك قوله جل وعلا: فَلا وَرَبِّكَ لا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ [النساء:65] الآية على ظاهرها، يعني لا يجوز للمسلمين أن يخرجوا عن شريعة الله بل يجب عليهم أن يحكموا شرع الله في كل شيء، فيما يتعلق بالعبادات، وفيما يتعلق بالمعاملات وفي جميع الشئون، لأن الله يقول : وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنزَلَ اللَّهُ [المائدة:49]، ويقول : أَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ اللَّهِ حُكْمًا لِقَوْمٍ يُوقِنُونَ [المائدة:50] ويقول سبحانه: وَمَنْ لَمْ يَحْكُمْ بِمَا أَنزَلَ اللَّهُ فَأُوْلَئِكَ هُمُ الْكَافِرُونَ [المائدة:44]، وَمَنْ لَمْ يَحْكُمْ بِمَا أَنزَلَ اللَّهُ فَأُوْلَئِكَ هُمُ الظَّالِمُونَ [المائدة:45]، وَمَنْ لَمْ يَحْكُمْ بِمَا أَنزَلَ اللَّهُ فَأُوْلَئِكَ هُمُ الْفَاسِقُونَ [المائدة:47] .\nهذا عام في جميع الشئون، ولهذا قال سبحانه: فَلا وَرَبِّكَ لا يُؤْمِنُونَ يعني: المسلمون، حَتَّى يُحَكِّمُوكَ يعني: محمد ﷺ، يعني يحكموا سنته بعد وفاته، يحكموه في حياته ﷺ وبعد وفاته يكون التحكيم لسنته مع القرآن العظيم، حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ يعني: فيما تنازعوا فيه، هذا هو الواجب عليهم أن يحكموا القرآن الكريم والرسول ﷺ في حياته، وبعد وفاته سنته التي هي شرح القرآن وهي تفسير القرآن والدالة على معانيه، حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا [النساء:65] يعني: يجب أن تنشرح صدورهم وأن لا يبقى في صدورهم حرج من حكمه عليه الصلاة والسلام؛ لأن حكمه هو الحق الذي لا ريب فيه، فالواجب التسليم له وانشراح الصدر بذلك وعدم الحرج، بل يسلم المؤمن لذلك تسليمًا كاملًا راضيًا بحكم الله مطمئنًا إليه.\nهذا هو الواجب على جميع المسلمين فيما شجر بينهم من الدعاوى والخصومات سواء كانت متعلقة بالعبادات أو بالأموال أو بالأنكحة أو بالطلاق أو بغيرها من شئونهم. نعم.\nالمقدم: جزاكم الله خيرًا. الإيمان هنا شيخ عبدالعزيز فَلا وَرَبِّكَ لا يُؤْمِنُونَ، الإيمان هل هو الكامل، يعني كمال الإيمان أو الإيمان مطلقًا؟\nالشيخ: أصل الإيمان بالنسبة إلى تحكيم الشريعة والرضا بها والإيمان بأنها الحكم بين الناس فلابد من هذا، فمن زعم أن هناك شيئًا يحكم بغير ذلك وأنه يجوز أن يتحاكم الناس إلى سوالف الآباء والأجداد، أو إلى القوانين الوضعية التي وضعها الرجال سواء كانت شرقية أو غربية، من زعم أن هذا يجوز فإن الإيمان منتفٍ عنه، كفر أكبر، فإذا رأى أن شرع الله لا يجب تحكيمه ولكن لو حكم كان أفضل وإلا لا يجب تحكيمه أو يرى أن القانون أفضل، أو يرى أن القانون مساوٍ لحكم الله، كل هذا ردة عن الإسلام، وهي ثلاثة أحوال:\nالحال الأولى: أن يقول: إن الشرع أفضل ولكن لا مانع من تحكيم غير الشرع، هذا ردة أيضًا ولو قال: إن الشرع أفضل.\nالثانية: أن يقول: الشرع والقانون سواء ولا فرق ، هذا ردة أيضًا.\nوالحال الثالثة: أن يقول: القانون أفضل وأولى من الشرع، وهذا أردأ الثلاثة وأقبحها وهو كفر أيضًا وردة عن الإسلام.\nأما الذي يرى أن الواجب تحكيم الشرع وأنه لا يجوز تحكيم القوانين ولكنه حكم بغير ما أنزل الله لهوى في نفسه ضد المحكوم عليه أو لرشوة أو ما أشبه ذلك من الأسباب، وهو يعلم أنه ظالم ومخطئ ومخالف للشرع، فهذا يكون نفي الإيمان في حقه نفي الإيمان الواجب لا أصل الإيمان؛ لأنه مؤمن، مسلم بأن حكم الله هو حق، وأنه عاصٍ بعمله ولكنه حمله حب المال حتى حكم بغير ما أنزل الله بسبب الرشوة أو بسبب العداوة بينه وبين المحكوم عليه، أو لمحبة المحكوم له وقرابته ونحو ذلك، فيكون هذا منكرًا عظيمًا وكبيرة عظيمة ونوعًا من الكفر لكنه مثل ما قال ابن عباس: «كفر دون كفر، وظلم دون ظلم، وفسق دون فسق»، وهكذا قال مجاهد وجماعة، قالوا: إن الحكم في هذا كفر أصغر وفسق أصغر وظلم أصغر؛ لأنه مؤمن بحكم الله ومقتنع به يعلم أنه الحق وأن ما حكم به حكم باطل، وأنه عاصٍ لله فلهذا صار بذلك ناقص الإيمان ضعيف الإيمان قد نفي الإيمان عنه نفيًا للإيمان الواجب الكامل لا نفيًا لأصله الذي يجعله مرتدًا، وهذا هو الحق الذي عليه جمهور أهل العلم وهو الذي لا ريب فيه أنه معتمد. نعم.\nالمقدم: بارك الله فيكم، الواقع شيخ عبد العزيز هذه القضية لها أهميتها ولاسيما عند المسلم الذي يحس بأن لأخيه المسلم عليه حقًا، يبدو لي أنه في حاجة إلى مزيد من الطرح وفي حاجة إلى مزيد من البحث ولاسيما أن هناك أناسًا يعتقدون أنهم من المؤمنين ويعتقدون أنهم من المسلمين، والشريعة لا تجد طريقها في التحكيم بينهم؟\nالشيخ: هذا لاشك إنه من المنكرات العظيمة وهذا وقعت فيه دول كثيرة الآن منتسبة للإسلام، فهي بهذا العمل إذا كانت ترى أن حكم القانون أفضل وأولى، أو أنه مساوٍ لحكم الله، أو أنه يجوز الحكم به فهذا كفر أكبر ردة عن الإسلام نعوذ بالله بإجماع المسلمين لا نزاع في هذا، وإنما الكلام فيما إذا كانوا يعلمون أنهم مخطئون وأنهم عاصون بهذا الأمر ولكن فعلوه لهوى أو لإرضاء بعض الشعب، أو لأسباب أخرى فعلوه لا يعتقدون حل ما فعلوا بل يعلمون أنهم عاصون فيما فعلوا ولكن فعلوه كما يفعل القاضي الذي أخذ الرشوة، أو حكم لقريبه على غير قريبه وهو يعلم أنه عاصي وأنه مخالف لحكم الله، فإنه لا يرتد بذلك بل يكون عاصيًا، وقد أتى كفرًا دون كفر وظلمًا دون ظلم وفسقًا دون فسق، وهذا معنى كلام السلف في هذا كـابن عباس وغيره. نعم.\nالمقدم: بارك الله فيكم، كيف يرى سماحة الشيخ إثارة هذا الموضوع فترة بعد أخرى، ولاسيما أنه هناك أناسًا قد لا يعلمون بهذا التفصيل؟\nالشيخ: إثارته مهمة جدًا لينتبه العالم الإسلامي لهذا الأمر، ولينتبه الحكام نسأل الله لنا ولهم الهداية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7188/طلب-الاستغفار-من-النبي-عليه-الصلاة-والسلام-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_177/17701.mp3","categories":["مسائل متفرقة في العقيدة","التفسير"]},{"id":9031,"question":"أخونا في موضوعه هذا أهمية ولاشك كما يقدرها سماحتكم يسأل في النهاية ويقول: هل التشاجر هنا على الدنيا أم على الدين فِيمَا شَجَرَ بَيْنَهُمْ [النساء:65]؟","title":"المراد بالتشاجر في قوله تعالى: (فِيمَا شَجَرَ بَيْنَهُمْ)","answer":"الجواب: مثل ما تقدم عام يعم المشاجرة التي تقع بين الناس في أمور دنياهم في البيع والشراء والجنايات وأشباه ذلك، وقد تكون مشاجرة في معرفة حكم الله، في العبادات أو غيرها، فيتشاجرون فهذا يقول: هذا حرام، وهذا يقول: هذا مباح، وهذا يقول: هذا واجب، وهذا يقول: غير واجب، فالمرد في هذا إلى كتاب الله وسنة رسوله لا إلى أهواء الناس وعاداتهم وآرائهم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7189/المراد-بالتشاجر-في-قوله-تعالى-فيما-شجر-بينهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_177/17702.mp3","categories":["التفسير"]},{"id":9075,"question":"الرسالة الأولى وردت إلى البرنامج من المستمع: عثمان موسى أحمد من جيبوتي يقول في رسالته: وفي سؤاله الأول: أرجو أن تعطونا تفسيراً واضحاً لقول الحق تبارك وتعالى: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ وَلا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذَا أَمِنتُمْ فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ [البقرة:196] أفيدونا أفادكم الله؟","title":"تفسير قوله تعالى: (وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد: هذه الآية الكريمة أصل عظيم في الحج والعمرة، يقول الله : وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196] الآية، احتج بها العلماء على أن الواجب على من دخل في الحج والعمرة أن يتمهما، وأنه ليس له الخروج منهما بل يجب عليه إتمامهما، فإذا أحرم بالحج وجب عليه تمام الحج، وإذا أحرم بالعمرة وجب عليه تمامها، وليس له الخروج منها إلا بالطريقة الشرعية، وهي أداء الأنساك التي شرع الله في الحج والعمرة، فإذا لبى بالحج لم يخرج منه حتى يقف بعرفات وحتى يرمي الجمرة يوم العيد، ثم يحلق ويتحلل التحلل الأول، ثم بعد الطواف والسعي يتم له التحلل الكامل، هذا هو الذي شرعه الله سبحانه وتعالى، فالحاج حين يحرم بالحج يبقى حراماً، لا يتطيب ولا يقص أظفاره، ولا يأخذ من شعره، ولا يأتي أهله ولا يصيد إلى غير ذلك مما حرم الله في الإحرام.\nفإذا وقف بعرفات في يوم التاسع، بات في مزدلفة ليلة العاشر، ثم في الصباح يرمي الجمرات، جمرة العقبة بسبع حصيات كما رماها النبي ﷺ، ثم بعد ذلك يشرع له أن ينحر هدياً إن كان عنده هدي ذبح، وإن لم يكن عنده ذبح أو لم يتيسر له حلق أو قصر وتحلل، يحلق رأسه أو يقصر أطرافه بالمقراض ويتحلل، وهذا يقال له: التحلل الأول، ثم بعدما يطوف ويسعى في يوم العيد أو بعده يتم حله من حجه الحل الكامل. بالتحلل الأول يباح له الطيب ولبس المخيط ونحوهما ما عدا النساء، وإذا طاف وسعى بعد الحلق والرمي حل الحل كله، حل له الطيب والنساء وجميع محظورات الإحرام، وبهذا تم حجه وعليه أن يكمل، ما بقي عليه من رمي الجمار أيام التشريق، وعليه مع ذلك المبيت في منى إن لم يعذر عن ذلك بمرض ونحوه، وعليه مع ذلك أن يطوف طواف الوداع عند كماله حجه، وعند إرادته السفر.\nوهكذا العمرة إذا أحرم بها ليس له أن يتحلل منها حتى يطوف ويسعى ويقصر أو يحلق، فإذا طاف بالبيت العتيق سبعة أشواط، وصلى خلف المقام ركعتين وسعى بين الصفا والمروة سبعة أشواط ثم حلق أو قصر تمت عمرته، وهذا معنى قوله سبحانه: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196] ثم قال تعالى: فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] إذا أحصر ساغ له حينئذٍ أن يتحلل؛ لأنه معذور، ساغ له أن يتحلل قبل أن يطوف ويسعى، مثلما أحصر النبي ﷺ في يوم الحديبية ومنعه كفار مكة أن يدخل مكة، فنحر هديه وحلق رأسه وتحلل، وأمر أصحابه بذلك.\nوفي هذا المعنى يقول الله جل وعلا: فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] يعني: فاذبحوا ما تيسر من الهدي، وهو شاة واحدة عن الرجل والمرأة، وبدنة عن سبعة، وبقرة عن سبعة، .. هكذا المحصر يفعل إذا منع من مكة، منع من دخولها بعدو أو غيره مما يمنع من دخول مكة، أو مرض منعه حتى لا يستطيع على الراجح الدخول والعمل يتحلل فينحر هدياً: شاة، أو بقرة، أو بدنة، لكن الشاة عن الواحد فقط، أما البدنة والبقرة فتكون عن الواحد وعن السبعة، وإن ذبحها واحد فلا بأس، وإن ذبحها اثنان فلا بأس، وإن ذبحها ثلاثة فلا بأس، وإن ذبحها سبعة فلا بأس، يعني: البدنة والبقرة تجزئان عن الواحد وعن اثنين وعن ثلاثة وعن أربعة وعن خمسة وعن ستة وعن سبعة.\nأما الشاة الواحدة من الضأن أو من المعز فإنها لا تجزئ إلا عن واحد، إما رجل وإما امرأة فقط في الحج، ثم قال: وَلا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ [البقرة:196] معناه: أن المحصر لا يحلق حتى يذبح، هذا في المحصر إذا أحصر فإنه ينحر أولاً ثم يحلق، ولا يبدأ بالحلق، بل يبدأ بالنحر؛ ولهذا أمر النبي ﷺ أصحابه أن ينحروا ثم يحلقوا.\nأما في الحج فله أن يبدأ بالحلق، لا بأس يجوز كما بين النبي ﷺ فإنه: سئل عمن حلق قبل أن يذبح؟ فقال: لا حرج عليه الصلاة والسلام لكن الأفضل في الحج أنه ينحر أول ثم يحلق، هذا هو الأفضل، لكن لو حلق قبل أن يذبح أو حلق قبل أن يرمي أجزأ ذلك، أما المحصر فلا، المحصر لابد أن يبدأ بالنحر ثم يحلق للآية الكريمة.\nأما قوله سبحانه: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ [البقرة:196] فهذا في حق من أصيب بالمرض، الذي يحتاج معه إلى حلق الرأس أو إلى لبس المخيط، أو إلى الطيب، فهذا له رخصة أن يحلق رأسه كما فعل كعب بن عجرة في عهد النبي ﷺ، فإنه آذاه رأسه فرخص له النبي ﷺ أن يحلق رأسه ويصوم ثلاثة أيام أو يذبح شاة أو يتصدق بثلاثة آصع لستة مساكين كل مسكين له نصف الصاع، وهذا تفسير الآية الكريمة: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ [البقرة:196] وهو ثلاثة أيام أَوْ صَدَقَةٍ [البقرة:196] وهي إطعام ستة مساكين، أَوْ نُسُكٍ [البقرة:196] وهي ذبح شاة، هذا في حق من احتاج إلى لبس المخيط أو غيره من المحظورات، فإنه يلبس المخيط عند الحاجة أو يتطيب عند الحاجة بسبب المرض، أو يحلق رأسه عند الحاجة بسبب المرض، وعليه أن يفعل واحدة من هذه الثلاث: إما أن يذبح شاة، وإما أن يتصدق بشيء .... إطعام ستة مساكين، لكل مسكين نصف الصاع من التمر أو نحوه، من الأرز والحنطة ونحو ذلك من قوت البلد، أو يصوم ثلاثة أيام، هذه الأشياء الثلاثة التي أرادها الرب  في قوله سبحانه: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ [البقرة:196] فسرها النبي ﷺ في حديث كعب بن عجرة.\nثم بين  حكم المتمتع، و.. المتمتع بالعمرة إلى الحج عليه أن يهدي، إذا تمتع بالعمرة إلى الحج يعني: أحرم بالعمرة في أشهر الحج في شوال أو ذي القعدة أو ذي الحجة، ثم حج من عامه فهذا يسمى: متمتع فعليه أن يهدي ذبيحة يذبحها أيام العيد عن تمتعه، وهي شاة أو سبع بدنة، أو سبع بقرة، فإن لم يستطع صام عشرة أيام، ثلاثة أيام في الحج يعني: في مكة أيام الحج قبل عرفات، وإن لم يتيسر صامها أيام التشريق على الصحيح، الثلاثة بعد العيد ..، وسبعة إذا رجع إلى أهله، فإن لم يستطع ذلك لمرض أو غيره صام العشرة كلها عند أهله ولا شيء عليه، بدلاً من الهدي والله ولي التوفيق.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7229/تفسير-قوله-تعالى-واتموا-الحج-والعمرة-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_225/22501.mp3","categories":["التفسير"]},{"id":9080,"question":"كما وصلت إلى البرنامج الرسالة التالية من المستمع علي حسن عبد الرحيم خالد من الجمهورية اللبنانية يقول فيها: أرجو أن تتفضلوا بتوضيح معنى الآية الكريمة في قوله : فَلا رَفَثَ وَلا فُسُوقَ وَلا جِدَالَ فِي الْحَجِّ [البقرة:197] فقد تحدث أحياناً خصومات بين بعض الحجاج، ويحصل جدال بينهم أرجو الإفادة، هل هناك إثم في ذلك وما هي الكفارة، أفيدونا أفادكم الله؟","title":"ما معنى قوله: {فَلا رَفَثَ وَلا فُسُوقَ وَلا جِدَالَ فِي الْحَجِّ}؟","answer":"الجواب: يقول الله سبحانه: الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ فَمَنْ فَرَضَ فِيهِنَّ الْحَجَّ فَلا رَفَثَ وَلا فُسُوقَ وَلا جِدَالَ فِي الْحَجِّ [البقرة:197] ويقول النبي ﷺ: من حج لله فلم يرفث ولم يفسق رجع كيوم ولدته أمه.\nفهذا يدلنا على أن الحاج لا ينبغي له أن يرفث ولا يفسق ولا يجادل، بل ينبغي له أن يشتغل بذكر الله، وطاعة الله ، والكلام الطيب النافع، ويبتعد عما لا ينبغي من الرفث والفسوق والجدال؛ لأنه في عبادة عظيمة، فينبغي له احترامها وصيانتها، عما لا ينبغي، والرفث: هو الجماع للزوجة قبل التحلل من الإحرام، قبل أن يرمي الجمرة ويحلق ويطوف ويسعى إن كان عليه سعي، وقبل أن تفعل ذلك هي أيضاً، فليس لهما الجماع إلا بعد الفراغ من أعمال الحج المهمة التي تترتب على التحلل وهي رمي الجمرة يوم العيد والحلق أو التقصير مع طواف الإفاضة والسعي لمن كان عليه سعي، فإن فعل هذه الأمور أو زوجته إن كانت فعلت هذه الأمور حل لهما الجماع، وإلا فهو محرم عليهم، وهو الرفث، كما قال الله سبحانه: أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ [البقرة:187] الرفث: هو الجماع، وهكذا ما يدعو إليه من الكلام، يسمى: رفث، كالتحدث معها في الجماع وتقبيلها ولمسها وأشباه ذلك مما يتعلق بالجماع كله رفث. أما الفسوق: فهي المعاصي من السب والشتم، والكذب، والربا وشهادة الزور والعقوق للوالدين أو أحدهما وقطيعة الرحم، وغير هذا من سائر المعاصي، يجب اجتنابها دائماً دائماً، ولكن في الحج يكون أشد، المعاصي يجب اجتنابها، فإنها فسوق، ...... أن تجتنب في الحج وفي غيره، وفي كل مكان وزمان، لكنها في الحج تكون أشد تحريماً وأشد إثماً، فالواجب على الحاج أن يجتنب كل معصية.\nأما الجدال فهو نوعان: نوع يتعلق بمشاعر الحج ومواسم الحج وأعمال الحج، فقد أوضحها الله فلا جدال فيها، فلا ينبغي أن يجادل فيها، قد أوضح الله معالم الحج، وأوضح أنساك الحج وأحكامه، فلا يجوز الجدال في ذلك، بل يجب على المسلمين أن يتأسوا بنبيهم ﷺ في ذلك وأن يحجوا كما حج، في جميع الأمور في الوقوف بعرفة في المبيت بمزدلفة المبيت في منى.. رمي الجمار.. الطواف والسعي إلى غير هذا، فليس هناك حاجة إلى الجدال فقد وضح الله الأمر.\nالنوع الثاني: الجدال بين الناس والخصومات بين الناس فلا ينبغي الجدال بينهم مما يسبب الشحناء والفتنة أو المضاربة أو القتال، إذا أفضى التحدث إلى الجدال ينبغي أن يترك، ولا ينبغي أن يتوسع في ذلك، يتحدث الإنسان مع أخيه في شئونه وحاجاته، لكن متى آل الأمر إلى الجدال والشدة والمراء الذي قد يفضي إلى المضاربة أو إلى الشحناء فإنه ينبغي تركه، هكذا ينبغي للمؤمن مع إخوانه في الحج أن يتجنبوا نوعي الجدال، حتى تكون حجتهم سليمة وبعيدة عما يؤثر عليها من رفث أو فسوق أو جدال، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7247/ما-معنى-قوله-فلا-رفث-ولا-فسوق-ولا-جدال-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22609.mp3","categories":["التفسير"]},{"id":9106,"question":"الرسالة الأولى وردت إلى البرنامج من المستمع الحاج: فاضل محمد إكرام من الجمهورية التركية، يقول في رسالته ويبدؤها بقول الحق : أُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وَطَعَامُهُ مَتَاعًا لَكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ الْبَرِّ مَا دُمْتُمْ حُرُمًا [المائدة:96] ويستفسر هل معنى ذلك: أنه يجوز للحاج أن يصطاد السمك ويأكل منه، ويطلب أن تتفضلوا بشرح معنى الآية الكريمة ولكم جزيل الشكر والثواب؟","title":"معنى قوله تعالى: (أُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ..)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، نبينا محمد وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فالله جل وعلا يقول في كتابه العظيم: أُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وَطَعَامُهُ مَتَاعًا لَكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ الْبَرِّ مَا دُمْتُمْ حُرُمًا [المائدة:96] الآية، فربنا  قد أباح للحرم صيد البحر، وحرم عليهم صيد البر، فالمحرم له أن يصيد صيد البحر من السمك ويأكله، له صيده وله أكله، صيده ما يصيده فيه، وطعامه ما يطفو عليه من السمك الميت، فإن البحر: هو الطهور ماؤه، الحل ميتته كما قاله النبي ﷺ قال في البحر: هو الطهور ماؤه، الحل ميتته فما يطفو عليه هو طعام من السمك الصغار والكبار، من أخذه فهو حل له، وما يصيده فيه بأنواع الآلات والشباك فهو حل له أيضاً، سواءً كان محرماً أو حلالاً بنص الآية الكريمة، أما صيد البر فلا، كالضباء والأرانب ونحوها، ليس للمحرم أن يصيد صيد البر، وإن كان في غير الحرم، وليس له صيد الحرم أيضاً سواءً كان محرماً أو حلالاً، صيد البر لا يجوز للمحرم إذا كان في غير الحرم، وإذا كان في الحرم حرم على المحرم وعلى غير المحرم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7255/معنى-قوله-تعالى-احل-لكم-صيد-البحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22701.mp3","categories":["التفسير"]},{"id":9164,"question":"السؤال الثالث والأخير في رسالة الأخ صالح سعد العوفي من المدينة المنورة، يقول فيه: ما تفسير قول الله : إِِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ [القصص:76] الآية، أفيدونا أفادكم الله؟","title":"تفسير قوله تعالى: (إِِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ)","answer":"الجواب: هذه الآية في قصة قارون ، قال له قومه: لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ [القصص:76] المراد بذلك: الفرح الذي يصحبه الكبر، والبغي على الناس، والعدوان، والبطر، هذا المنهي عنه فرح البطر والكبر.\nأما الفرح بفضل الله وبرحمته ونعمه وإحسانه، هذا مشروع، كما قال الله : قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُوا هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ [يونس:58] فالمؤمن يفرح أن الله هداه للإسلام، وأن الله أعانه على صلاة الجماعة، وأن الله أعانه على بر والديه، وصلة أرحامه، وأعانه على فعل الخير، هذا مشروع، ينبغي له أن يفرح بذلك، وأن يسر، بل يجب عليه أن يفرح بذلك، ويغتبط بهذا، ويحمد الله على ذلك.\nأما الفرح المذموم، فهو الفرح الذي يصحبه الكبر والتعاظم، والبطر، واحتقار الناس، هذا هو المذموم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7330/تفسير-قوله-تعالى-ان-الله-لا-يحب-الفرحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23212.mp3","categories":["التفسير"]},{"id":9169,"question":"السؤال الثالث والأخير في رسالة الأخ صالح سعد العوفي من المدينة المنورة، يقول فيه: ما تفسير قول الله : إِِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ [القصص:76] الآية، أفيدونا أفادكم الله؟","title":"تفسير قوله تعالى: (إِِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ)","answer":"الجواب: هذه الآية في قصة قارون ، قال له قومه: لا تَفْرَحْ إِنَّ اللَّهَ لا يُحِبُّ الْفَرِحِينَ [القصص:76] المراد بذلك: الفرح الذي يصحبه الكبر، والبغي على الناس، والعدوان، والبطر، هذا المنهي عنه فرح البطر والكبر.\nأما الفرح بفضل الله وبرحمته ونعمه وإحسانه، هذا مشروع، كما قال الله : قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُوا هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ [يونس:58] فالمؤمن يفرح أن الله هداه للإسلام، وأن الله أعانه على صلاة الجماعة، وأن الله أعانه على بر والديه، وصلة أرحامه، وأعانه على فعل الخير، هذا مشروع، ينبغي له أن يفرح بذلك، وأن يسر، بل يجب عليه أن يفرح بذلك، ويغتبط بهذا، ويحمد الله على ذلك.\nأما الفرح المذموم، فهو الفرح الذي يصحبه الكبر والتعاظم، والبطر، واحتقار الناس، هذا هو المذموم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7330/تفسير-قوله-تعالى-ان-الله-لا-يحب-الفرحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23212.mp3","categories":["التفسير"]},{"id":9176,"question":"يقول العزيز الحكيم: قَدْ أَفْلَحَ الْمُؤْمِنُونَ [المؤمنون:1] إلى قوله تعالى: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ [المؤمنون:5-6]، ما معنى قوله تعالى: أوْ مَا مَلَكَتْ أَيْمَانُهُمْ [المؤمنون:6]، وهل هو في وقتنا الحاضر أم أنها على وقت الرسول ﷺ؟","title":"معنى قوله تعالى: (أوْ مَا مَلَكَتْ أَيْمَانُهُمْ)","answer":"الجواب: هذه الآيات آيات عظيمات، وصف بها سبحانه أهل الإيمان الموعودين بالفردوس أعلى الجنة، قال سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، والفلاح: هو الظفر والفوز بكل خير والسعادة، ووصفهم بالخشوع في الصلاة يعني الإقبال عليها والطمأنينة فيها وإحضار القلب.\nوَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ [المؤمنون:3]، يعني: أعرضوا عن كل ما لا ينبغي عن الشرك والمعاصي وكل شيء لا فائدة فيه، أعرضوا عنه واشتغلوا بما ينفعهم من الأعمال والأقوال.\nوَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ[المؤمنون:4]، زكاة المال وزكاة الجاه والنفس، فالمؤمن يزكي نفسه بطاعة الله ورسوله، ويزكي جاهه بالشفاعة في الخير والنفع للناس، ويزكي ماله بأداء الحق الذي فيه من الزكوات.\nوَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ [المؤمنون:5-6]، المؤمن هكذا والمؤمنة هكذا، فالمؤمن يحفظ فرجه إلا من زوجته أو ما ملكت يمينه، والمؤمنة كذلك تحفظ فرجها إلا من زوجها وسيدها وهو الذي ملكها ملكاً شرعياً، هذا معنى الآية: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ[المؤمنون:5-6]، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7336/معنى-قوله-تعالى-او-ما-ملكت-ايمانهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15010.mp3","categories":["التفسير"]},{"id":9193,"question":"أرجو لو تكرمتم تفسير قول الله سبحانه وتعالى من سورة النازعات وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40-41]، وما هي الأمور التي تنهى النفس عن الهوى؟ وهل يكون عمل المرأة من هذه الأمور التي يجب نهي النفس عنها في حالة عدم احتياج المرأة للعمل مادياً؟ أرجو إفادتي مأجورين، والسلام عليكم ورحمة الله وبركاته.","title":"تفسير قوله تعالى: (وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ ...)","answer":"الجواب: الآية عظيمة ومعناها واضح، يقول سبحانه: وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى[النازعات:40-41]، قبلها قوله سبحانه: فَأَمَّا مَنْ طَغَى ۝ وَآثَرَ الْحَيَاةَ الدُّنْيَا ۝ فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَى ۝ وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ [النازعات:37-40] يعني: خاف مقامه بين يدي الله فلهذا نهى نفسه عن هواها يعني: هواها المحرم، (ونهى النفس عن الهوى) (أل) بدل المضاف إليه، يعني: عن هواها الذي حرم الله عليها، فهذا هو الذي له الجنة والكرامة، فإن النفس قد تميل إلى الزنا، قد تميل إلى الخمر، قد تميل إلى الربا، قد تميل إلى ظلم الناس، قد تميل إلى أشياء أخرى مما حرمها الله وتهوى ذلك لأسباب، فإذا وفق الله المؤمن أو المؤمنة لمحاربة هذا الهوى ومخالفته وعدم الانصياع إليه صار هذا من أسباب دخول الجنة، وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى [النازعات:40] يعني: خاف وقوفه بين يدي الله؛ فلهذا نهى نفسه عن هواها، يعني: زجرها عن هواها، وخالفها وألزمها بالحق وكبح جماحها حتى لا تقع فيما حرم الله من الزنا أو شرب المسكر أو تعاطي الربا، أو الغيبة أو النميمة أو العقوق للوالدين، أو قطيعة الرحم، أو ظلم الناس في أموالهم ودمائهم وأعراضهم إلى غير هذا، هذا الذي نهى نفسه عن هواها وألزمها بالحق خوفًا من الله وطلباً لمرضاته له الجنة والكرامة، الله المستعان.\nالمقدم: تسأل أختنا تقول: عمل المرأة إذا لم تكن محتاجة للمادة هل يعد من الهوى أو لا؟\nالشيخ: عملها لا يعد من الهوى إذا كان عملاً شريفاً سليماً بين النساء الذي ليس فيه خلطة بالرجال، وليس فيه إسفار لها عن محاسنها وإنما تعمل عملاً مباحاً بين أخواتها النساء ليس فيه ظلم ولا عدوان ولا ارتكاب محرم، وزوجها راض إن كان لها زوج فلا بأس ليس فيه شيء، ليس هذا من الهوى، فالعمل يختلف؛ فإن كان في معاصي الله وجب تركه، وإن كان عملًا يفضي بها إلى الاختلاط مع الرجال وإظهار محاسنها للرجال كان أيضاً منكراً يجب منع النفس عن هواها في هذا، أما إذا كان عملًا مباحاً أو شرعيًا بين أخواتها فلا بأس، مثل مدرسة للبنات، مثل ممرضة للنساء، مثل طبيبة للنساء، لا بأس في هذا ولا حرج والحمد لله. نعم.\nالمقدم: بارك الله فيكم، وإن لم تكن محتاجة للمادة كما تعلمون؟\nالشيخ: ولو كانت غير محتاجة تأخذ المال لزيادة ثروتها أو للصدقة به أو لغير هذا من الأسباب الحسنة.\nالمقدم: طيب، المهم الشروط التي تفضلتم بذكرها؟\nالشيخ: نعم، نعم.","link":"https://binbaz.org.sa/fatwas/7353/تفسير-قوله-تعالى-واما-من-خاف-مقام-ربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15106.mp3","categories":["التفسير"]},{"id":9223,"question":"السؤال الرابع والأخير في رسالة المستمع (ب. ل. د) من العراق محافظة التأميم، يقول فيه: ما معنى قول الله : إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] صدق الله العظيم؟","title":"ما معنى: {إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ}؟","answer":"الجواب: هذه الآية العظيمة فيها شرف للنبي صلى الله عليه وسلم، وبيان منزلته عند الله، وأنها منزلة عظيمة، ولهذا قال: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ [الأحزاب:56] الصلاة من الله ثناؤه على عبده في الملأ الأعلى، ثناؤه عليه، وذكره بأوصافه الجميلة عند الملائكة، هكذا صلاة الله على عبده كما قال أبو العالية وجماعة من السلف، وتطلق الصلاة من الله على الرحمة، كما قال سبحانه: هُوَ الَّذِي يُصَلِّي عَلَيْكُمْ وَمَلائِكَتُهُ [الأحزاب:43] يعني: يرحمكم ويثني عليكم سبحانه وتعالى، فثناء الله على عبده عند الملائكة هو ذكر أوصافه الجميلة العظيمة، هذه صلاة الله على عبده، ويدخل فيها أيضاً رحمته لعباده، وإحسانه إليهم .\nوالملائكة صلاتهم الدعاء، دعاؤهم للمصلى عليه، وترحمهم عليه وثناؤهم عليه، يقال له: صلاة، كما في الحديث: الملائكة تصلي على أحدكم ما دام في مصلاه، تقول: اللهم اغفر له، اللهم ارحمه، اللهم تب عليه فصلاتهم على الرسول دعاؤهم له، عليه الصلاة والسلام.\nونحن مأمورون بأن نصلي عليه عليه الصلاة والسلام، قال الله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] فنحن مأمورون أن نصلي عليه ونسلم، فنقول: اللهم صل عليه وسلم، ﷺ، ونصلي عليه في صلاتنا، في التشهد الأخير اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد هكذا علم النبي ﷺ أصحابه، ولو قال: اللهم صل على سيدنا محمد، لا بأس، لكن لم يرد في الأحاديث ذكر السيد في قراءتها في الصلاة، إنما علم أصحابه أن يقولوا: اللهم صل على محمد .. إلى آخره، عليه الصلاة والسلام.\nويستحب أن يقول هذا على الصحيح، حتى في التشهد الأول بعد الشهادتين، بعدما يأتي بالشهادة يصلي على النبي ﷺ ثم ينهض إلى الثالثة على الأرجح؛ لعموم الأحاديث الواردة عن رسول الله عليه الصلاة والسلام في ذلك.\nوهكذا يشرع لنا ويتأكد أن نصلي عليه كثيراً يوم الجمعة وليلتها، وهكذا يشرع لنا عند ذكره -إذا مر ذكره عليه الصلاة والسلام- أن نصلي عليه بل يجب؛ لقوله ﷺ: رغم أنف امرئ ذكرت عنده فلم يصل علي هذا يدل على وجوب الصلاة عند ذكره عليه الصلاة والسلام.\nوهكذا بعد الأذان -إذا فرغ المؤذن- قال: لا إله إلا الله، يقول هو والمستمع: اللهم صل وسلم على رسول الله اللهم رب هذه الدعوة التامة والصلاة القائمة آت نبينا محمد الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدته إنك لا تخلف الميعاد لقوله ﷺ لما سئل عما يقوله حين يسمع المؤذن، قال: قولوا كما يقول المؤذن، ثم صلوا علي، فإنه من صلى علي واحدة صلى الله عليه بها عشراً، ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة وفي اللفظ الآخر، يقول ﷺ: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدته، إنك لا تخلف الميعاد، حلت له شفاعتي يوم القيامة هذا كله مما شرعه الله لنا  في حقه عليه الصلاة والسلام.\nفينبغي للمؤمن والمؤمنة الإكثار من الصلاة والسلام على رسول الله عليه الصلاة والسلام في الليل والنهار، وأن يكثر من ذلك المؤمن في الجمعة وليلتها، وإذا سمع ذكره صلى عليه عليه الصلاة والسلام، وهكذا في الصلاة، في التشهد الأول والتشهد الأخير، والصلاة على النبي ﷺ في التشهد الأخير واجبة عند جمع من أهل العلم، وقال آخرون: ركن من أركان الصلاة في التشهد الأخير، فينبغي للمؤمن أن يحرص على ذلك، وألا يدع ذلك، صلى الله وسلم عليه وعلى آله وأصحابه صلاة وسلاماً دائمين إلى يوم الدين. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7389/ما-معنى-ان-الله-وملاىكته-يصلون-على-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_233/23309.mp3","categories":["التفسير"]},{"id":9275,"question":"أختنا أيضًا تسأل سؤالًا آخر وتقول: أريد اسمًا لتفسير للقرآن الكريم؟الشيخ: ايش؟المقدم: تسأل عن كتاب في التفسير؟","title":"أفضل كتب التفسير","answer":"الجواب: الكتب في التفسير كثيرة، ومن أحسنها بل أحسنها تفسير ابن كثير رحمه الله، وتفسير البغوي وابن جرير هذه كتب عظيمة ونافعة ومفيدة وهي أحسن التفاسير كذلك تفسير الشوكاني كتاب طيب ومفيد، والجلالين تفسير مختصر مفيد فيه بعض الأخطاء، فإذا كانت عندها بصيرة تعرف الأخطاء في الصفات ونحوها فلا بأس وإلا تسأل عما قد يشكل عليها، ولا سيما ما قد يكون فيه من التأويل لصفات الله وأسمائه، أو بعض الأخطاء في الأحكام، فطالبة العلم التي عندها بصيرة تعرف ذلك وإلا فتسأل، وأحسن ما يكون تفسير ابن كثير، هو تفسير عظيم لكنه قد يكون فيه صعوبة على التي ليس عندها بصيرة وليس عندها مزيد علم؛ لأنه كتاب مطول. نعم.\nالمقدم: البغوي مع الخازن سماحة الشيخ؟\nالشيخ: البغوي طيب.","link":"https://binbaz.org.sa/fatwas/7437/افضل-كتب-التفسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_183/18305.mp3","categories":["التفسير"]},{"id":9296,"question":"وفي آخر رسالته أضاف سؤالاً رابعاً قال فيه: قال تعالى: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] فيسأل عن معنى الاستواء؟","title":"معنى قوله تعالى:(الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى)","answer":"الجواب: قوله : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، فسره علماء السنة بأنه العلو والارتفاع، يعني: ارتفع فوق العرش وعلا فوقه سبحانه وتعالى بدون كيف، أهل السنة والجماعة وهم أصحاب النبي ﷺ وأتباعهم بإحسان يقولون في صفات الرب : إن الواجب إثباتها وإمرارها كما جاءت بلا كيف، يعني: نثبتها لله ونؤمن بها وأنها حق، ولكن لا نكيفها، لا نقول: إنها بكيفية كذا وكيفية كذا، سئل مالك بن أنس إمام دار الهجرة في زمانه، وأحد الأئمة الأربعة، سئل رحمة الله عليه عن قوله جل وعلا: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى ، كيف استوى؟ فأطرق طويلاً ثم قال رحمه الله: الاستواء معلوم، والكيف مجهول، والإيمان به واجب، فالواجب على أهل العلم والإيمان، وعلى جميع المسلمين أن يؤمنوا بأسماء الله وصفاته التي جاءت في القرآن العظيم أو السنة الصحيحة، وأن يمروها كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، بل يؤمنون بأنها صفات الله وأنها أسماؤه وأنها حق، وأن معانيها حق يليق بالله جل وعلا، معانيها تليق بالله لا يشابه خلقه في شيء من صفاته سبحانه وتعالى.\nفالاستواء: هو العلو والارتفاع فوق العرش، وهو معلوم من حيث اللغة العربية، ولكن كيفيته مجهولة، ما نعلم كيف استوى، ولكن نقول: إنه استوى على عرشه وارتفع فوق عرشه ارتفاعاً يليق بجلاله وعظمته لا يشابه الخلق في صفاتهم، لا في الاستواء ولا في غيره؛ لقوله : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] ؛ ولقوله : فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74] وقوله سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، فهو سبحانه الكامل في ذاته وأسمائه وصفاته وأفعاله لا شبيه له، ولا سمي له، ولا كفء له، ولا ند له سبحانه وتعالى.\nهذا هو الواجب على أهل الإسلام أن يؤمنوا بهذه الصفات الاستواء والرحمة، والسمع والبصر، والغضب والوجه، واليد والقدم، والأصابع وغير هذا من صفاته سبحانه وتعالى، كلها يجب إثباتها لله على الوجه اللائق بالله من غير تحريف ولا تعطيل لصفات الله، ولا تكييف لها، ولا تمثيل لها، بل يقال: إنها حق، وإنها ثابتة لله على الوجه اللائق به ، لا يشابه خلقه في شيء من صفاته جل وعلا؛ لأنه سبحانه وتعالى لا مثيل له، لا في ذاته، ولا في صفاته . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7464/معنى-قوله-تعالىالرحمن-على-العرش-استوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23607.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":9316,"question":"تسأل أيضا وتقول: يقول الله جل شأنه: إِنَّا عَرَضْنَا الأَمَانَةَ عَلَى السَّمَوَاتِ وَالأَرْضِ وَالْجِبَالِ فَأَبَيْنَ أَنْ يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا الإِنْسَانُ إِنَّهُ كَانَ ظَلُومًا جَهُولًا [الأحزاب:72]، ما معنى الأمانة في الآية الكريمة؟","title":"معنى الأمانة في قوله تعالى: (إِنَّا عَرَضْنَا الأَمَانَةَ ...)","answer":"الجواب: الأمانة تفسر بأمرين: أحدهما: فرائض الله وحقوق الله، من صلاة وصوم وجهاد ونحو ذلك، يقال لها: أمانة، وهكذا التكليف بما حرم الله على عباده أن يمتنع عنه الإنسان أمانة، والأمر الثاني: حاجات الناس وحقوق الناس من الودائع والعواري والرهون، هذه يقال لها: أمانة أيضاً، فالله جل وعلا عرض الأمانة على السموات والأرض والجبال أن يتحملوا هذه الأمانة فخافت من ذلك، وأشفقت من ذلك، وحملها المكلف من بني آدم .\nفالواجب على بني آدم المكلفين أن يعتنوا بهذه الأمانة، وأن يتقوا الله فيها، فيؤدوا فرائض الله كما شرع الله، ويجتنوا محارم الله تعظيماً لله وخوفاً منه ، ويؤدوا حق العباد من ديون ورهون وعواري، وودائع، عليهم أن يؤدوا الحق الذي عليهم، وأن يحذروا غضب الله ، فإن الخيانة توجب غضب الله، والتقصير المتعمد يوجب غضب الله.\nفالواجب أداء الفريضة كما شرع الله، وترك المحارم كما شرع الله، وأداء حقوق العباد وعدم بخسها من وديعة أو رهن أو غير ذلك. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7492/معنى-الامانة-في-قوله-تعالى-انا-عرضنا-الامانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23709.mp3","categories":["التفسير"]},{"id":9346,"question":"أخيراً يقول الأخ آدم عبد الله أبكر من تشاد، هل التوسل يجوز بالجاه وبالبركة وبالحرمة، كأن يقول الإنسان: اللهم افعل لي كذا بجاه الشيخ فلان، أو ببركة الشيخ فلان، أو بحرمة محمد ﷺ ونحو ذلك أفيدونا أفادكم الله؟","title":"حكم التوسل بجاه الأنبياء والصالحين","answer":"الجواب: التوسل بالجاه والبركة والحرمة والحق، ليس بجائز عند جمهور أهل العلم؛ لأن التوسلات توقيفية، لا يجوز منها إلا ما أجازه الشرع، ولم يرد في الشرع ما يدل على هذه التوسلات، فلا يقول الإنسان: اللهم اغفر لي بحق فلان، بحق محمد أو بحق الصالحين، أو بحق الأنبياء أو بجاه الأنبياء أو بحرمة الأنبياء، أو بركة الأنبياء أو بحق الصالحين أو بركة الصالحين أو بركة علي أو بركة الصديق ، أو بركة عمر ، أو حق الصحابة أو حق فلان وفلان كل هذا لا يحوز، هذا خلاف المشروع وهو بدعة وليس بشرك لكنه بدعة، لم يرد في الأسئلة التي دعا بها النبي صلى الله عليه وسلم، ودعا بها أصحابه ، وإنما يتوسل بما شرعه الله من أسماء الله سبحانه وصفاته، ومن توحيده، والإخلاص له والأعمال الصالحات، هذه الوسائل قال الله تعالى: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، فتقول: اللهم اغفر لي برحمتك إنك أنت الغفور الرحيم، اللهم ارحمني يا أرحم الراحمين، اللهم أحسن إلي، اللهم أدخلنا الجنة برحمتك وفضلك وإحسانك، اللهم أنجني من النار، واعف عني يا رحمان يا رحيم يا عفو يا كريم وما أشبه ذلك، أو بالتوحيد والإخلاص لله، تقول: اللهم اغفر لي، لأني أشهد أنك أنت الله لا إله إلا أنت، لأنك الواحد الأحد مستحق العبادة، أو تقول: اللهم أني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت كما جاء في الحديث الشريف بهذا السؤال فلا بأس بهذا، هذا وسيلة شرعية، أو بأعمالك الطيبة، تقول: اللهم اغفر لي بإيماني بك ومحبتي لك، أو بإيماني بنبيك ومحبتي له عليه الصلاة والسلام، اللهم ارحمني بطاعتي لك واتباعي لشريعتك، اللهم ارحمني ببر والدي، اللهم ارحمني بعفتي عن الفواحش، اللهم ارحمني بأداء الأمانة، ونصحي لله ولعباده وما أشبه ذلك، ومن هذا الباب ما ثبت في الصحيحين عن ابن عمر رضي الله تعالى عنهما: عن النبي ﷺ: أن ثلاثة آواهم المبيت إلى غار -وفي رواية: آواهم المطر إلى غار- في الجبل فدخلوا فيه، فانحدرت عليهم صخرة من أعلى الجبل فسدت الغار عليهم، وكانت صخرة عظيمة لم يستطيعوا دفعها، فقالوا فيما بينهم: إنه لن ينجيكم من هذه الصخرة إلا أن تدعوا الله بصالح أعمالكم، فدعوا الله سبحانه وتعالى فقال أحدهم: اللهم إنه كان لي أبوان شيخان كبيران، وكنت لا أغبق قبلهما أهلاً ولا مالاً، والغبوق اللبن الذي يسقاه يشربه الناس بعد العشاء وكان هذا من عادات العرب، سقي الضيوف والأهل اللبن في الليل، يقول: كنت لا أغبق قبلهما أهلاً ولا مالاً، وإنه نأى بي طلب الشجر ذات ليلة فلم أرح عليهما إلا في آخر الليل يعني إلا متأخراً، فوجدهما نائمين، فوقف والقدح على يديه ينتظر استيقاظهما فلم يستيقظا حتى برق الفجر، قال: اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة بعض الشيء، لكنهم لا يستيطعون أن يخرجوا، وقال الثاني: اللهم إني كانت لي ابنة عم أحبها كأشد ما يحب الرجال النساء، وإني راودتها على نفسها فأبت علي، ثم إنها ألمت بها سنة -يعني: حاجة- فجاءت إلي تطلب الرفد، فقلت لها: إلا أن تمكني من نفسك، فاتفق معها على مائة وعشرين دينار -جنيه- فمكنته من نفسها فلما جلس بين رجليها قالت له: اتق الله ولا تفض الخاتم إلا بحقه، فقام خائفاً من الله وترك الذهب وترك الفاحشة، ثم قال: اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة زيادة لكنهم لا يستيطعون الخروج، ثم قال الثالث: اللهم إنه كان لي أجراء فأعطيت كل أجير حقه إلا واحداً ترك أجره فربيته له، فنميته له حتى صار منه إبل وبقر وغنم ورقيق، ثم جاء يطلب أجره فقلت له: كل ما ترى من أجرك، فقال: اتق الله ولا تستهزئ بي، قلت: إني لا أستهزئ بك، كله من أجرك فاستاقه كله، اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة وخرجوا بأسباب هذه الدعوات وهذه الأعمال الصالحات.\nفالدعاء بهذا وأشباهه دعاء طيب لا بأس، ووسيلة صالحة، أما الدعاء بحق فلان، أو جاه فلان، أو بركة فلان، أو حرمة فلان، فهذا لا أصل له، ولم تأت به السنة، فالواجب تركه وليس من الشرك لكنه من البدع، فالواجب تركه، هذا هو الصواب الذي عليه جمهور أهل العلم، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7511/حكم-التوسل-بجاه-الانبياء-والصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23807.mp3","categories":["التفسير","التوسل والشفاعة"]},{"id":9399,"question":"المستمع عيسى محمد صالح سوداني مقيم في دولة قطر يسأل عن تفسير قوله تعالى: أعوذ بالله من الشيطان الرجيم: إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ ظَالِمِي أَنفُسِهِمْ قَالُوا فِيمَ كُنتُمْ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الأَرْضِ قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا فَأُوْلَئِكَ مَأْوَاهُمْ جَهَنَّمُ وَسَاءَتْ مَصِيرًا [النساء:97]؟","title":"ما معنى: {إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ ظَالِمِي أَنفُسِهِمْ}؟","answer":"الجواب: هذه الآية ذكر علماء التفسير أنها نزلت فيمن جلس بين أظهر المشركين ولم يهاجر من دون عذر، فإنه قد ارتكب إثمًا عظيمًا بإجماع المسلمين كما ذكر ذلك الحافظ ابن كثير رحمه الله وغيره، فالملائكة تقول لهم: أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا [النساء:97] يعني: لماذا لم تهاجروا تتركوا بلاد الشرك؟\nوهذه البلاد التي لا يظهر فيها الإنسان دينه ولا يستطيع أن يظهر دينه، فهذا لا يجوز له الإقامة بينهم ، بل يجب عليه أن يهاجر؛ إلا إذا كان عاجزًا لكونه لا يهتدي السبيل، وليس عنده نفقة لمن يدله على الطريق، هذا معذور؛ لقوله سبحانه: إِلَّا الْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ لا يَسْتَطِيعُونَ حِيلَةً وَلا يَهْتَدُونَ سَبِيلًا [النساء:98] لا يستطيع حيلة لعدم النفقة، ولا يهتدون السبيل لعدم دلالة الطريق لو خرجوا: فَأُوْلَئِكَ عَسَى اللَّهُ أَنْ يَعْفُوَ عَنْهُمْ وَكَانَ اللَّهُ عَفُوًّا غَفُورًا [النساء:99] فهؤلاء هم الذين جلسوا في بلاد الشرك ولم يهاجروا مع القدرة فالله توعدهم بجهنم نسأل الله العافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7564/ما-معنى-ان-الذين-توفاهم-الملاىكة-ظالمي-انفسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_188/18805.mp3","categories":["التفسير"]},{"id":9479,"question":"وردت إلى البرنامج الرسالة التالية من بعض الإخوة من السودان يسألوا في رسالتهم عن الشرك بالمفهوم، ويطلبوا تفسير هذه الآية، قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ [المائدة:35] صدق الله العظيم، أفيدونا بالصواب ولكم الأجر والثواب من الله تعالى؟","title":"ما معنى: {اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ}؟","answer":"الجواب: الشرك على اسمه هو تشريك غير الله مع الله في العبادة، كأن يدعو الأصنام يستغيث بهم، ينذر لهم، يصلي لهم، يصوم لهم، يذبح لهم، يذبح للبدوي، يذبح للعيدروس، يذبح لفلان، يصلي لفلان، يطلب المدد من الشيخ عبد القادر، من الرسول ﷺ، من العيدروس في اليمن، من أشباه ذلك من سائر المعبودين من دون الله، هذا يقال له: شرك.\nوهكذا إذا دعا الكواكب أو الجن أو استغاث بهم أو طلبهم مدد، أو ما أشبه ذلك.\nفإذا فعل شيء من هذه العبادات مع المخلوقين أو مع الأموات صار هذا شركًا بالله ، قال الله جل وعلا: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، قال سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65].\nومن الشرك أيضًا: أن يعبد غير الله عبادة كاملة، فإنه يسمى شركًا ويسمى كفرًا، فمن أعرض عن الله بالكلية وجعل عبادته لغير الله للأشجار أو الأحجار أو الأصنام أو الجن أو بعض الأموات ممن يسمونهم بالأولياء، يعبدهم يصلي لهم يصوم لهم وينسى الله بالكلية هذا أعظم كفرًا وأشد كفرًا وأشد شركًا، نسأل الله العافية.\nوهكذا من ينكر وجود الله، ويقول: إنه ليس هناك إله والحياة مادة، كـالشيوعيين والملاحدة المنكرين وجود الله، هؤلاء أكفر الناس وأضلهم، وأعظمهم شركًا وضلالًا نسأل الله العافية.\nفالمقصود أن هذه الاعتقادات وأشباهها كلها تسمى شركًا وتسمى كفرًا بالله .\nوقد يغلط بعض الناس لجهله فيسمي دعوة الأموات والاستغاثة بهم وسيلة، هذا غلط، هذه وسيلة للكفر ما هي بوسيلة مباحة، الله جل وعلا يقول: اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ [المائدة:35] الوسيلة القربة يعني: بطاعته، هذه الوسيلة عند أهل العلم جميعًا، الوسيلة التقرب إلى الله بطاعته، فالصلاة قربى إلى الله وسيلة، الذبح لله وسيلة كالضحايا والهدايا، الصوم وسيلة، الصدقات وسيلة، ذكر الله وقراءة القرآن وسيلة، هذا معنى قوله جل وعلا: اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ وَجَاهِدُوا فِي سَبِيلِهِ [المائدة:35] يعني: ابتغوا إلى القرب إليه بطاعته، هكذا قال ابن جرير وابن كثير و البغوي وغيرهم من أئمة التفسير.\nالمعنى: التمسوا القربة إليه بطاعته، وابتغوها اطلبوها أينما كنتم بما شرع الله لكم من صلاة وصوم وصدقات وغير ذلك.\nوهكذا قوله في الآية الأخرى: أُوْلَئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ [الإسراء:57] ليبتغوا من ربهم القرب يعني بطاعته، وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ [الإسراء:57] هكذا الرسل وأتباعهم، في التقرب إلى الله بالوسائل التي شرعها من جهاد من صوم من صلاة من ذكر من قراءة القرآن إلى غير هذا من وجوه الوسيلة.\nأما ظن بعض الناس أن الوسيلة هي التعلق بالأموات والاستغاثة بالأولياء والنذر لهم هذا خطأ وظن باطل، وهذا اعتقاد المشركين الذين قال فيهم سبحانه: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] هذا عمل المشركين، يدعون الأموات ويستغيثون بالجن، ويستغيثون بالملائكة ويدعون أنهم وسائلهم إلى الله.\nوقال تعالى في كتابه الكريم: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] قال الله سبحانه: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3] فسماهم كذبة كفرة، كذبة في قولهم أنها تقرب من الله، وكفرة في قولهم: إن الله أمرهم بهذا، ... ، فهو سبحانه لم يأمر بهذا، فهم كذبة في قولهم كفرة في فعلهم، ولهذا قال جل وعلا: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3]، مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا [الزمر:3]، فهي لا تقربهم ولا تدنيهم من الله بل تبعدهم من الله ومن رحمته ، فهم كذبة في هذا القول، كفرة في هذا الفعل الذي نسبوه إلى الله وجعلوه دينًا له .\nوالله يقول: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2] ويقول: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، وهذا معنى لا إله إلا الله، فَاعْلَمْ أَنَّهُ لا إِلَهَ إِلَّا اللَّهُ [محمد:19].","link":"https://binbaz.org.sa/fatwas/7641/ما-معنى-اتقوا-الله-وابتغوا-اليه-الوسيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19205.mp3","categories":["التفسير"]},{"id":9583,"question":"تسأل أيضاً وتقول: كتاب (صفوة التفاسير) كثيراً ما أقرأ فيه وهناك من يعاتبني على هذا ويحذرني منه، فأفيدوني ماذا أفعل؟","title":"تقييم كتاب: صفوة التفاسير","answer":"الجواب: كتاب (صفوة التفاسير) كتاب مفيد جمع فيه مؤلفه نقولاً كثيرة من تفاسير العلماء، وفيه بعض الملاحظات والمؤاخذات التي نرجو أن يصححها المؤلف في المستقبل، فيه أشياء تلاحظ عليه من جهة بعض التأويل، وأشياء قد لاحظها بعض أهل العلم عليه، والعزيمة منه أنه سوف يصحح كلما هناك من خطأ، ونسأل الله أن يعينه على ذلك. نعم.\nالمقدم: بارك الله فيكم .","link":"https://binbaz.org.sa/fatwas/7757/تقييم-كتاب-صفوة-التفاسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24812.mp3","categories":["التفسير"]},{"id":9589,"question":"تسأل أيضاً وتقول: كتاب (صفوة التفاسير) كثيراً ما أقرأ فيه وهناك من يعاتبني على هذا ويحذرني منه، فأفيدوني ماذا أفعل؟","title":"تقييم كتاب: صفوة التفاسير","answer":"الجواب: كتاب (صفوة التفاسير) كتاب مفيد جمع فيه مؤلفه نقولاً كثيرة من تفاسير العلماء، وفيه بعض الملاحظات والمؤاخذات التي نرجو أن يصححها المؤلف في المستقبل، فيه أشياء تلاحظ عليه من جهة بعض التأويل، وأشياء قد لاحظها بعض أهل العلم عليه، والعزيمة منه أنه سوف يصحح كلما هناك من خطأ، ونسأل الله أن يعينه على ذلك. نعم.\nالمقدم: بارك الله فيكم .","link":"https://binbaz.org.sa/fatwas/7757/تقييم-كتاب-صفوة-التفاسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24812.mp3","categories":["التفسير"]},{"id":9631,"question":"هذا السائل من الأردن عمان سيد محمود عبد السلام يقول: أسأل عن قوله : وَاللَّهُ يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ وَيُرِيدُ الَّذِينَ يَتَّبِعُونَ الشَّهَوَاتِ أَنْ تَمِيلُوا مَيْلًا عَظِيمًا ۝ يُرِيدُ اللَّهُ أَنْ يُخَفِّفَ عَنْكُمْ وَخُلِقَ الإِنسَانُ ضَعِيفًا [النساء: 27، 28] أرجو منكم الإفادة عن هذه الآية مأجورين؟","title":"معنى قوله تعالى: (وَاللَّهُ يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ ...)","answer":"الجواب: هذه هي الإرادة الشرعية، يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ يعني: يريد شرعًا، يحب ذلك شرعًا أن يتوب عليكم، وقدره ماض في الناس، لكن يحب أن يتوب عليكم، يحب سبحانه أن يتوب على عباده وأن يرحمهم وأن ينصرهم وأن يبارك لهم جل وعلا، وقد يفعل ذلك وقد لا يفعل ذلك، هو يريده شرعًا يريد أن يتوب عليكم يريد أن يبين لكم سنن الذين من قبلكم، هذا يريد أن يوضح لعباده الحق، يريد من عباده أن يهتدوا وأن يستقيموا على الحق، يريد من عباده أن يحافظوا على الصلاة في الجماعة، يريد من عباده أن يبروا والديهم وأن يطيعوا ولاة أمرهم بالمعروف، كل هذه يريدها شرعاً، ولكن قد يقع قدرًا وقد لا يقع، قد سبق في علم الله قد يسبق في علم الله أنه لا يقع من هذا الشخص هذا الشخص زيد بن فلان مأمور ببر والديه، مأمور بصلة الرحم، مأمور بطاعة ولاة الأمور لكن قد يقع منه خلاف ذلك، قد يكون سبق في علم الله أن الله أراد منه أن يقع خلاف ذلك، قدر عليه أنه يعق ويعصي ولا يبر ولا يسمع ويطيع، وهو سبحانه أراد منه شرعًا أن يستقيم على الحق، أراد منا شرعًا أن نصلي وأن نصوم وأن نزكي وأن نبر والدينا، وأن نحذر المعاصي، لكن منا من فعل ومنا من لم يفعل، على حسب ما مضى به القدر السابق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7791/معنى-قوله-تعالى-والله-يريد-ان-يتوب-عليكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27202.mp3","categories":["التفسير"]},{"id":9655,"question":"هذه رسالة وردت إلى البرنامج من الأخت السائلة (م. ن. و) من مكة المكرمة، تقول في رسالتها: أسأل عن معنى قول الله : قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ [المجادلة:1] أطلب من فضيلتكم شرح هذه الآية؟","title":"ما معنى: {قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ}؟","answer":"الجواب: هذه نزلت في امرأة ظاهر منها زوجها، فأتت إلى النبي ﷺ تخبره بأن زوجها ضعيف كبير السن وعاجز ليس به حاجة إلى النساء، وتطلب السماح ببقائها عنده، فأخبر الله جل وعلا عنها في قوله سبحانه: قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ ۝ الَّذِينَ يُظَاهِرُونَ مِنْكُمْ مِنْ نِسَائِهِمْ [المجادلة:2] إلى آخره.\nفالمقصود أنه ظاهر منها، فأفتاه النبي ﷺ بأن عليه الكفارة، عليه عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكيناً، فأخبره أنه عاجز عن الصيام وعن العتق فأمره النبي ﷺ أن يطعم ستين مسكيناً، وهذا هو الحكم في كل من ظاهر من امرأته، إذا قال لزوجته: هي علي حرام، أو هي كظهر أمي، أو هي محرمة علي كظهر أمي، أو كظهر أختي، أو جدتي، أو ما أشبه ذلك فإن هذا يسمى ظهاراً، وهو محرم لا يجوز، ليس للمسلم أن يظاهر؛ لأن الله قال فيه سبحانه: وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا [المجادلة:2] فهو منكر وزور ليست امرأته محرمة عليه وليست كأمه، بل هي أباحها الله له، فليس له أن يقول: هي علي كظهر أمي أو هي محرمة ليس له ذلك، ومتى قال ذلك فعليه التوبة والاستغفار وعليه الكفارة، وهي عتق رقبة مؤمنة، فإن لم يجد صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكيناً، ثلاثين صاعاً كل صاع بين اثنين، من التمر أو من الرز أو من غيرهما من قوت البلد قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3] قبل أن يقربها، هذا هو الذي بينه الله سبحانه في كتابه العظيم، وبينه رسوله عليه الصلاة والسلام. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7820/ما-معنى-قد-سمع-الله-قول-التي-تجادلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25105.mp3","categories":["التفسير"]},{"id":9714,"question":"سماحة الشيخ، تقول هذه السائلة -مقيمة في جدة- هل قراءة القرآن الكريم بغير تفسير ليس عليه أجر، هل هذا صحيح؟","title":"حكم قراءة القرآن لمن لا يعرف تفسيره","answer":"الجواب: ليس بصحيح، بل إذا قرأ بالتدبر والتعقل له أجر ولو كان ما يفهم كثيراً، قراءته بالتدبر والتعقل والخشوع له أجر في ذلك: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] فعليه التدبر والتعقل والقراءة بخضوع وعدم عجلة، وهذا له أجر عظيم. نعم.","link":"https://binbaz.org.sa/fatwas/7868/حكم-قراءة-القران-لمن-لا-يعرف-تفسيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27208.mp3","categories":["التفسير"]},{"id":9715,"question":"تقول السائلة: ما هي كتب التفسير الذي تنصحونني بالمداومة على قراءتها؟","title":"كتب التفسير التي ينصح بقراءتها","answer":"الجواب: أحسنها فيما نعلم تفسير ابن جرير وتفسير ابن كثير وتفسير البغوي، لكن تفسير ابن كثير أحسنها؛ لأنه يعتني بالأحاديث ويعتني بالعقيدة السلفية، هذا تفسير جيد وإن كان مطولًا، ولكن نوصيك بالتدبر، دعي عنك كتب التفسير، نوصيك بقراءة القرآن بتدبر وتعقل، واسألي أهل العلم عما أشكل عليك من طريق الهاتف من طريق المكاتبة اسأليهم عما أشكل عليك من الآيات، وإذا كان عندك علم وراجعتي تفسير ابن جرير أو ابن كثير أو البغوي للفائدة فهذا طيب. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7870/كتب-التفسير-التي-ينصح-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27209.mp3","categories":["التفسير"]},{"id":9725,"question":"يقول: ما المقصود بالإنفاق في قوله  في سورة الفرقان: وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا[الفرقان:67]؟","title":"ما المقصود بالإنفاق في: {وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا}؟","answer":"الجواب: المراد الإنفاق على البيت على أهل البيت على الزوجة والأولاد والخدم يتوسط لا يسرف ولا يبخل بينهما: لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا (لم يقتروا): لم يبخلوا ..، يعني: تكون نفقته وسطاً هذا هو المشروع، هذا هو وصف عباد الرحمن أهل الخير والإيمان، لا يسرفون في النفقات ولا يبخلون ولكن وسط. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7880/ما-المقصود-بالانفاق-في-والذين-اذا-انفقوا-لم-يسرفوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27216.mp3","categories":["التفسير"]},{"id":9915,"question":"هذه رسالة وردت إلينا من فهد رشيد الحسن من العراق محافظة ديالي يقول في رسالته: قال المولى في كتابه الكريم: فَضَّلَ اللَّهُ الْمُجَاهِدِينَ عَلَى الْقَاعِدِينَ أَجْرًا عَظِيمًا [النساء:95] فهل المقصود بالمجاهدين هنا هم المجاهدون في سبيل الله فقط، أم أن الجهاد يصح في سبيل العرض أو الشرف أو الأرض أو الوطن أو نحو ذلك أفيدونا أفادكم الله؟","title":"ما المقصود بالمجاهدين في: {فَضَّلَ اللَّهُ الْمُجَاهِدِينَ عَلَى الْقَاعِدِينَ}؟","answer":"الجواب: الجهاد إذا أطلق فهو الجهاد في سبيل الله: قيل: يا رسول الله! الرجل يقاتل شجاعةً ويقاتل حميةً ويقاتل رياء أي ذلك في سبيل الله؟ فقال المصطفى عليه الصلاة والسلام: من قاتل لتكون كلمة الله هي العليا فهو في سبيل الله لكن يجب على المسلم أن يدافع عن وطنه من الكفرة والمعتدين، ويدافع عن عرضه وعن دمه وعن ماله، وإذا قتل فهو شهيد؛ لما ثبت عنه ﷺ أنه قال: من قتل دون دينه فهو شهيد، ومن قتل دون ماله فهو شهيد، ومن قتل دون أهله فهو شهيد وثبت عنه عليه السلام: أنه جاءه رجل فقال: يا رسول الله! الرجل يأتيني يريد مالي؟ قال: لا تعطه مالك، قال: فإن قاتلني؟ قال: قاتله، قال: فإن قتلني؟ قال: فأنت شهيد، قال: فإن قتلته؟ قال: فهو في النار خرجه الإمام مسلم في صحيحه.\nفهذا يدل على أنه إذا قاتل دون ماله فهو شهيد مظلوم، لكن القتال في سبيل الله عند الإطلاق هو الجهاد في سبيل الله جهاد الكفار وجهاد المعتدين من البغاة وقطاع الطريق هو الجهاد في سبيل الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8084/ما-المقصود-بالمجاهدين-في-فضل-الله-المجاهدين-على-القاعدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_268/26805.mp3","categories":["التفسير"]},{"id":10062,"question":"يسأل أحد الإخوة المستمعين هو (م. ع. ك) ويقول: قال تعالى: وَاللَّهُ فَضَّلَ بَعْضَكُمْ عَلَى بَعْضٍ فِي الرِّزْقِ فَمَا الَّذِينَ فُضِّلُوا بِرَادِّي رِزْقِهِمْ عَلَى مَا مَلَكَتْ أَيْمَانُهُمْ فَهُمْ فِيهِ سَوَاءٌ أَفَبِنِعْمَةِ اللَّهِ يَجْحَدُونَ [النحل:71]؟","title":"معنى قوله تعالى: (وَاللَّهُ فَضَّلَ بَعْضَكُمْ عَلَى بَعْضٍ..)","answer":"الجواب: على ظاهرها الله فضل الناس بعضهم على بعض، هذا تاجر وهذا فقير، وهذا تجارته أكثر من الآخر وليس التاجر بدافع أمواله لمماليكه، بل ينفق عليهم ويحسن إليهم ولا يعطيهم أمواله بل ينفق عليهم ويحسن إليهم ويساعدهم ببعض المال، ومن طبيعة الإنسان أنه لا يدفع أمواله لمماليكه وهذا أمر معلوم بالفطرة والعقل كما دل عليه الشرع ودلت عليه الأدلة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8222/معنى-قوله-تعالى-والله-فضل-بعضكم-على-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30306.mp3","categories":["التفسير"]},{"id":10080,"question":"المستمع (م. ع. ع) من الأفلاج بعث يسأل ويقول: قال الله تعالى: فَنَادَاهَا مِنْ تَحْتِهَا أَلَّا تَحْزَنِي [مريم:24]، من هو المنادي؟ هل هو عيسى عليه السلام؟","title":"من المقصود في قوله تعالى: (فَنَادَاهَا مِنْ تَحْتِهَا..)","answer":"الجواب: الصواب أنه عيسى، نعم، فالله أنطقه وتكلم، ولهذا لما سألوها عن أمرها أشارت إليه فقالوا: كَيْفَ نُكَلِّمُ مَنْ كَانَ فِي الْمَهْدِ صَبِيًّا [مريم:29]، فتكلم: قَالَ إِنِّي عَبْدُ اللَّهِ [مريم:30]، فدل على أنها قد علمت أنه يتكلم وهو في المهد بكلامه لها سابقاً بقوله: أَلَّا تَحْزَنِي قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا [مريم:24].\nفالمقصود أن الصواب في الآية أن المتكلم من تحتها هو عيسى عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8244/من-المقصود-في-قوله-تعالى-فناداها-من-تحتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30407.mp3","categories":["التفسير"]},{"id":10174,"question":"المستمع (أ. ج. غ) يمني الجنسية بعث يسأل عن تفسير بعض الآيات بدأها بقوله تعالى: وَهَلْ أَتَاكَ نَبَأُ الْخَصْمِ إِذْ تَسَوَّرُوا الْمِحْرَابَ [ص:21] يقول: أرجو أن تفسروا هذه الآيات إلى قوله سبحانه: فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ [ص:24].","title":"ما معنى: {وَهَلْ أَتَاكَ نَبَأُ الْخَصْمِ} القصة؟","answer":"الجواب: الآية واضحة؛ فإنه أتاه ملكان وتسورا عليه المحراب وأخبراه أنهما خصمان، وقد بيَّن الله القصة في الآية واضحة  وبيَّن داود ما رآه في موضوعهما، فليس في الآية إشكال، أما ما يحكيه القصاص وبعض المفسرين من الحكايات في ذلك فلا ينبغي أن يعتمد عليها، بل ينبغي أن يؤخذ بظاهر القرآن ويكفي، والله أعلم بما وراء ذلك، أما الحكايات التي فيها أن داود فعل كذا وفعل كذا هذا لا، لا يعتمد عليه، نسأل الله السلامة. نعم. المقدم: اللهم آمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8351/ما-معنى-وهل-اتاك-نبا-الخصم-القصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30812.mp3","categories":["التفسير"]},{"id":10187,"question":"يسأل عن السامري الذي أضل قوم موسى.","title":"حقيقة السامري","answer":"الجواب:  شخص من اليهود نسأل الله العافية، أضلهم وتحمل أوزاراً عظيمة نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8366/حقيقة-السامري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30908.mp3","categories":["التفسير"]},{"id":10190,"question":"يسأل عن السامري الذي أضل قوم موسى.","title":"حقيقة السامري","answer":"الجواب:  شخص من اليهود نسأل الله العافية، أضلهم وتحمل أوزاراً عظيمة نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8366/حقيقة-السامري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30908.mp3","categories":["التفسير"]},{"id":10388,"question":"ما مدى التوفيق بين الآية الكريمة وبين قول الرسول ﷺ: بأن الله يغفر جميع الذنوب إلا الغيبة فلا يغفرها لنا، إلا بأن نستسمح الشخص المغتاب، أما الآية فهي قوله تعالى: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]؟","title":"الجمع بين: {وَيَغْفِرُ مَا دُونَ ذَلِكَ} و «يغفر جميع الذنوب إلا الغيبة»","answer":"الجواب: الآية عامة والحديث إلا الغيبة ليس بصحيح لا أصل له، والآية عامة تعم جميع الذنوب كلها تحت المشيئة، الغيبة والقتل وجميع الذنوب حتى القتل الذي أعظم من الغيبة، تحت المشيئة لكن حق المخلوق لا يضيع الله جل وعلا يعوضه عن حقه إذا تاب توبة صادقة، يعوض المغتاب عن حقه، الذي اغتابه غيره.\nفالحاصل: أن الذنوب كلها تحت المشيئة سواء كانت الذنوب تتعلق بحق الله، أو كانت تتعلق بحق المخلوق كالغيبة والقتل والنميمة ونحو ذلك فكلها تحت مشيئة الله، إن شاء سبحانه غفر لصاحبها وإن شاء عذبه بها ما لم يتب، أما إذا تاب فإنها تمحى عنه الذنوب بالتوبة، ولكن حق المخلوق لا يضيع عليه بل يجازيه الله عن حقه الذي تاب صاحبه منه، يجازيه الله ، ويرضيه عن ذلك جل وعلا، إذا صدق التائب في توبته، فالله يرضي عنه المظلوم بما يشاء .\nوالواجب على الظالم أن يستسمح المظلوم إذا استطاع إذا كان موجودًا، يقول: فعلت كذا يا أخي! إن كان مال يرد عليه ماله، إن كان عمل يوجب القصاص مكنه من القصاص، إن كان غيبة قال له: يا أخي! أنا اغتبتك فسامحني واعف عني، فإن سمح وإلا أعطاه حقه مكنه من القصاص رد عليه المال دعا له، وذكره بالخير في المجالس التي ذكره فيها بالسوء، يذكره بأعماله الطيبة التي يعلمها عنه حتى يكون ذلك قائمًا مقام غيبته له.\nوإذا كان يخشى أنه إذا أخبره بالغيبة أنه يحصل فساد فلا يخبره ولكن يدعو له ويترحم عليه، ويذكره بمحاسنه التي يعلمها عنه وخصاله الطيبة التي يعلمها عنه في المجالس والمجامع التي اغتابه فيها، حتى يكون هذا مقام هذا، والله المستعان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8560/الجمع-بين-ويغفر-ما-دون-ذلك-و-يغفر-جميع-الذنوب-الا-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33909.mp3","categories":["التفسير","الحكم على الأحاديث"]},{"id":10568,"question":"المستمع (ر. ع. م) يسأل عن تفسير قول الحق تبارك وتعالى: أعوذ بالله من الشيطان الرجيم: وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ [الرحمن:6].","title":"معنى قوله تعالى: (وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ)","answer":"الجواب: على ظاهر الآية سجود يليق بهما، والله يعلم كيفيته سبحانه وتعالى، كما قال في الآية الأخرى سبحانه و ...: أَلَمْ تَرَ أَنَّ اللَّهَ يَسْجُدُ لَهُ مَنْ فِي السَّمَوَاتِ وَمَنْ فِي الأَرْضِ وَالشَّمْسُ وَالْقَمَرُ وَالنُّجُومُ وَالْجِبَالُ وَالشَّجَرُ وَالدَّوَابُّ [الحج:18] فكما أنها تسبح هي تسجد أيضاً، وهذا التسبيح وهذا السجود كلاهما يليق بهذه المخلوقات، لا يعلم كيفيته إلا الذي خلقها ، تسبيح بني آدم معروف سجودهم معروف، وسجود الشجر والجبال الله يعلمه ، وهكذا سجود الشمس والقمر سجود يليق بهذه المخلوقات، الله يعلم كيفيته . نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8750/معنى-قوله-تعالى-والنجم-والشجر-يسجدان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32310.mp3","categories":["التفسير"]},{"id":10571,"question":"أخيراً يسأل ويقول: يقول الله تعالى أعوذ بالله من الشيطان الرجيم: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] ويقول تعالى: وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَه [الزلزلة:8] اجمعوا لنا بين هاتين الآيتين الكريمتين جزاكم الله خيراً؟","title":"معنى قوله تعالى: (إِنْ تَجْتَنِبُوا كَبَائِرَ ...)","answer":"الجواب: الآية الأولى عامة تعم الكفار والمسلمين، وأن العبد إذا تجنب ما هو من كبائر الذنوب كالشرك بالله والزنا والسرقة وشرب الخمر وأشباه ذلك من المعاصي الكبيرة، كالعقوق للوالدين أو أحدهما وأكل الربا ونحو ذلك، فإن الله يكفر عنه السيئات الصغائر التي ليس فيها وعيد، باجتنابه الكبائر يكفر الله له الصغائر.\nفالمسلم تكفر عنه الصغائر باجتنابه الكبائر، والكافر إذا أسلم وترك الشرك واستقام على الدين كفر الله عنه الصغائر باجتنابه الكبائر.\nوأما الآية الكريمة فليس بينها وبين الآية مخالفة وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَه [الزلزلة:8] يعني: يره إن لم يكفر فإذا كان تجنب الكبائر كفرت عنه الصغائر، وقد يراه.......\nبسبب اجتنابه الكبائر، وهكذا النصوص كلها الجمع بينها هكذا، يقول النبي ﷺ: الصلوات الخمس ......\nوأخبر النبي ﷺ أنه قال: من توضأ نحو وضوئي هذا ........ ...\n....... الصغائر إلا بالتوبة، فإذا تجنب العبد الكبائر أو تاب إلى الله منها توبة صادقة غفر الله له الصغائر  فضلاً منه وإحساناً جل وعلا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8746/معنى-قوله-تعالى-ان-تجتنبوا-كباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32306.mp3","categories":["التفسير"]},{"id":10605,"question":"المستمع محمد علي من السودان يسأل عن تفسير قول الحق تبارك وتعالى: قَالَ إِنَّمَا أَنَا رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلامًا زَكِيًّا [مريم:19]؟","title":"تفسير قوله تعالى: (قَالَ إِنَّمَا أَنَا رَسُولُ رَبِّكِ)","answer":"الجواب: هذا يقوله جبرائيل عليه الصلاة والسلام، يقوله لـمريم، والغلام الزكي هو عيسى عليه الصلاة والسلام، وهذا بأمر الله جل وعلا، كما أمره أن ينفخ فيها فحملت بأسباب النفخة، فأتت بهذا المولود الكريم وهو عيسى ابن مريم عليه الصلاة والسلام وهو عبد الله ورسوله، خلقه الله من أنثى وهي مريم الصديقة بدون أب، قال الله له: (كن فكان) كما قال تعالى في قصة آدم: إِنَّ مَثَلَ عِيسَى عِنْدَ اللَّهِ كَمَثَلِ آدَمَ خَلَقَهُ مِنْ تُرَابٍ ثُمَّ قَالَ لَهُ كُنْ فَيَكُونُ [آل عمران:59]، فالمقصود أن عيسى خلق من أنثى بلا ذكر وليس له أب، بل قال الله له: (كن فكان) بالنفخة التي نفخها جبرائيل في مريم حتى حملت بذلك، كما قال جل وعلا: وَالَّتِي أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِنْ رُوحِنَا وَجَعَلْنَاهَا وَابْنَهَا آيَةً لِلْعَالَمِينَ [الأنبياء:91]، وهي مريم رضي الله عنها، المقصود أن النفخة هي نفخة من جبرائيل وهو رسول الله إليها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8784/تفسير-قوله-تعالى-قال-انما-انا-رسول-ربك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32611.mp3","categories":["التفسير"]},{"id":10622,"question":"رسالة وصلت إلى البرنامج من المستمع: أحمد عوض السيد عبدالقادر سوداني مقيم في الطائف، أخونا يسأل ويقول: في حديث عن رسول الله ﷺ، رواه أنس  قال: من أحب أن يبسط له في رزقه، وينسأ له في أثره فليصل رحمه وأنا أعلم أن هناك آيات من القرآن من بينها: إذَا جَاءَ أَجَلُهُمْ لا يَسْتَأْخِرُونَ سَاعَةً وَلا يَسْتَقْدِمُونَ [الأعراف:34] كيف نوفق بين هذه الآية وبين ما في ذلكم الحديث؟","title":"الجمع بين: «من أحب أن يبسط» وقوله: {إذَا جَاءَ أَجَلُهُمْ}","answer":"الجواب: لا منافاة بين الحديث والآيات، فكون الإنسان يبسط له في الرزق وينسأ له في الأجل بسبب صلة الرحم أو بسبب بر الوالدين لا يمنع قوله تعالى: وَلَنْ يُؤَخِّرَ اللَّهُ نَفْسًا إِذَا جَاءَ أَجَلُهَا [المنافقون:11] فالمعنى: أن الله جل وعلا يجعل صلة رحمه وبر والديه من أسباب تأخير أجله في الأزل السابق والقدر السابق، فالله جل وعلا يعلم أن هذا يصل رحمه ويبر والديه، فلهذا أجل له زيادة في العمر، وفسح له في العمر، وذاك يقطع رحمه ويعق والديه فلم يفسح له في العمر وجعل عمره كذا لحكمة بالغة، وقد يطول عمر هذا العاق وعمر هذا العاصي ويعجل أجل المطيع لأسباب أخرى وحكمة بالغة من الله ، وفي الحديث الصحيح: لا يرد القدر إلا الدعاء، ولا يزيد في العمر إلا البر يعني: بر الوالدين.\nفهو من جنس حديث أنس: من أحب أن يبسط له في رزقه يقول النبي ﷺ: من أحب أن يبسط له في رزقه وأن ينسأ له في أجله فليصل رحمه وصلة الرحم وبر الوالدين وكثرة الدعاء في طول الحياة على خير من أسباب تأخير الأجل، فيما مضى في علم الله، ليس معناه أن هذا قد كتبه الله يموت في كذا ثم أخر، لا المقصود أن الله جل وعلا جعل بر هذا لوالديه، وصلته لأرحامه، وكثرة دعائه من أسباب تأخير أجله الذي مضى به علم الله، فعلم الله لا يتغير ، ولا يعقبه جهل ، ولا يسبقه جهل، بل علم الله شامل ، لا يعتريه جهل ولا نقص، فهذا إذا جاء أجله تمت حياته والآخر كذلك، والآخر كذلك، وكلٌ له أسبابه، هذا أطيل في أجله لبره وصلة رحمه وكثرة دعاءه، وهذا عجل له الأجل لأسبابٍ أخرى، وهذا مد له في الأجل لأسبابٍ أخرى، فربك حكيم جل وعلا، وليس هناك منافاة بين الأسباب؛ لأن الآجال معلقة بأسبابها، والأرزاق معلقة بأسبابها، والله هو المقدر لهذا ولهذا .","link":"https://binbaz.org.sa/fatwas/8798/الجمع-بين-من-احب-ان-يبسط-وقوله-اذا-جاء-اجلهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32710.mp3","categories":["التفسير","شروح الحديث"]},{"id":10658,"question":"وَعَلَّمَ آدَمَ الأَسْمَاءَ كُلَّهَا [البقرة:31] ما هي هذه الأسماء؟","title":"الأسماء التي علم الله آدم إياها","answer":"الجواب: مثل ما قال ربنا الأسماء كلها، علمه الأسماء كلها أسماء الإبل، أسماء الغنم، أسماء البقر، أسماء بني آدم ، أسماء الملائكة، إلى غير ذلك، الأسماء كلها، عامة.\nالمقدم: عامة؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8849/الاسماء-التي-علم-الله-ادم-اياها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32915.mp3","categories":["التفسير"]},{"id":10737,"question":"يقول أخونا أيضاً: أرجو تفسير قوله تعالى أعوذ بالله من الشيطان الرجيم: قَالَ رَبِّ فَأَنْظِرْنِي إِلَى يَوْمِ يُبْعَثُونَ ۝ قَالَ فَإِنَّكَ مِنَ الْمُنْظَرِينَ ۝ إِلَى يَوْمِ الْوَقْتِ الْمَعْلُومِ ۝ قَالَ رَبِّ بِمَا أَغْوَيْتَنِي لَأُزَيِّنَنَّ لَهُمْ فِي الأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ ۝ إِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ [الحجر:36-40] صدق الله العظيم، ماذا يقصد الشيطان بالتزيين والغواية وما هي؟","title":"تفسير قوله تعالى: (قَالَ رَبِّ فَأَنْظِرْنِي إِلَى يَوْمِ)","answer":"الجواب: مقصود الشيطان بذلك أنه يعمل ما يستطيع لإغواء الناس، وصدهم عن الحق وإخراجهم من الهدى إلى الضلالة حتى يكونوا معه في الجحيم، قال تعالى: إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا إِنَّمَا يَدْعُوا حِزْبَهُ لِيَكُونُوا مِنْ أَصْحَابِ السَّعِيرِ [فاطر:6]. فهو يدعونا إلى أن نكون معه في النار؛ لأن الله وعده النار وحتم له بالنار وأنظره إلى يوم القيامة ابتلاءً وامتحاناً، حتى يتبين من يطيع الله ورسوله ممن يطيع الشيطان ويوافقه.\nوهو أيضاً يزين لهم الباطل ويحسن لهم المعاصي ويدعوهم إليها ويسهلها عليهم، ويقول لهم: افعلوا كذا الله غفور رحيم اللهم تواب كريم حتى يزين لهم الباطل، ويقول: تمتع بهذا بالزنا بالخمر بأنواع الباطل، كما يزين له الشرك إذا استطاع حتى يدعوه إلى الكفر بالله والضلال، فعدو الله يغوي الناس ويزين لهم الباطل حتى يكونوا معه في النار؛ لأنه ابتلي بهذا البلاء لعنه الله وطرده ووعده النار لاستكباره وإبائه من السجود لـآدم وعصيانه ربه فاستحق لعنة الله وغضبه وطرده من رحمته، وأنه توعده بالنار والخلود فيها.\nقال تعالى: قَالَ فَالْحَقُّ وَالْحَقَّ أَقُولُ ۝ لَأَمْلأَنَّ جَهَنَّمَ مِنْكَ وَمِمَّنْ تَبِعَكَ مِنْهُمْ أَجْمَعِينَ [ص:84-85] فالعدو الشيطان قد وعده الله النار وحتم له دخولها، فهو حريص غاية الحرص على إغواء بني آدم، وتزيين الباطل لهم حتى يكونوا معه في النار، وهكذا هو أيضاً شياطين الجن حريصة أيضاً على إغواء حتى الجن، فهم حريصون على إغواء الجن معهم وعلى إغواء الإنس، كما أن شياطين الإنس كذلك حريصون على إغواء الإنس حتى يكونوا معهم في السعير، كما قال جل وعلا: وَكَذَلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا شَيَاطِينَ الإِنسِ وَالْجِنِّ يُوحِي بَعْضُهُمْ إِلَى بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُورًا وَلَوْ شَاءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ [الأنعام:112].\nوالله جل وعلا ابتلى هؤلاء وهؤلاء ابتلى الجن والإنس بالشياطين المتمردين الخارجين عن طاعة الله من الإنس والجن، حتى يدعوا الناس إلى الباطل ويزينوا لهم الباطل.\nفالواجب على المكلفين من الرجال والنساء الحذر من الشياطين، وكل من دعاك إلى عصيان الله متعمداً فهو شيطان إما إنسي وإما جني، فالذي يملي عليك الباطل في قلبك هو من شياطين الجن، والذي يدعوك لها ظاهراً من الإنس هو من شياطين الإنس، الذي يقول لك: افعل الزنا، اشرب الخمر، اقتل فلان بغير حق، أو يدعوك إلى الكفر والضلال إلى عبادة الأموات والاستغاثة بالأموات، أو إلى عبادة الأصنام أو الملائكة أو الجن، كل هؤلاء من الشياطين.\nفليس لك أن تطيعهم يجب عليك أن تعصيهم حتى لا تكون معهم في النار وفي السعير، وإياك أن تخدع بهم وتزيينهم للباطل وتحسينهم للمعاصي، بل يجب أن تطيع الله ورسوله وأن تستقيم على أمر الله وأن تبتعد عن محارم الله وأن تستعين بربك جل وعلا تقول: اللهم اهدني صراطك المستقيم، اللهم أصلح قلبي وعملي، اللهم أعذني من شياطين الإنس والجن، اللهم اكفني شرهم، تستعيذ بالله من شياطين الإنس والجن تحذرهم، وإذا وقع في قلبك شيء فاعرضه على ما قاله الله ورسوله فإن كان مما يوافق قول الله ورسوله فهذا حق اقبله، وإن كان يخالف أمر الله ورسوله فهو من الشيطان.\nوإن أشكل عليك فاسأل أهل العلم والإيمان، أهل البصيرة من علماء المسلمين، أهل الهدى اسألهم عما أشكل عليك، هل هذا حق أو باطل، إذا كنت لست بعالم، وإن كنت طالب علم فانظر في الأدلة من كلام الله وكلام رسوله عليه الصلاة والسلام حتى تعرف الحق من الباطل، وحتى لا تشتبه عليك الأمور التي يدعوا إليها الشياطين من الإنس والجن بما قاله الله ورسوله، والله يقول سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]، ويقول سبحانه: وَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ [فصلت:36] .\nوالنزغات التي من الشيطان هي ما يملي عليك الشيطان ويقع في قلبك من دواعي الباطل هي من نزغات الشياطين شياطين الجن، وقد يتمثل الجن للناس ويدعونهم إلى الباطل في صور رجال من بني آدم أو في صور النساء، قد يتمثلون ويدعون إلى الشرك والباطل، فإياك أن تطيع من أمرك بالباطل، ولو كان أخاك ولو كان أباك، ولو كان صديقك لا تطع أحداً في الباطل أبداً.\nيقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فمن أمرك بالخير وطاعة الله ورسوله فهو مشكور وهذا يطاع في الخير، أما من دعاك إلى المعاصي والشرك فلا وإن كان قريباً وإن كان صديقاً، وإن كان أميراً، وإن كان أباً، وإن كان أماً، فليس لك أن تطيع أحداً في معاصي الله .\nوإياك أن تغتر بالخداع وتزيين الباطل وتلبيس الحق بالباطل من شياطين الإنس والجن احذرهم، حتى لا يجروك إلى النار، وحتى لا يقودوك إلى السعير بسبب الخداع وتزيين الباطل، ولا حول ولا قوة إلا بالله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8913/تفسير-قوله-تعالى-قال-رب-فانظرني-الى-يوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_345/34504.mp3","categories":["التفسير"]},{"id":10738,"question":"يسأل أيضاً عن تفسير قول الحق تبارك وتعالى أعوذ بالله من الشيطان الرجيم: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا [مريم:71]؟","title":"تفسير قوله تعالى: (وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا..)","answer":"الجواب: هذا الورود هو المرور على الصراط، يوم القيامة ينصب للناس جسر على جهنم يمرون عليه، فالمؤمنون يمرون عليه ويسلمون إلى الجنة، وبعض العصاة يسقط وبعض العصاة ينجو، والكفار لا يستطيعون المرور عليه بل يساقون إلى النار نسأل الله العافية، فالناس واردون إلى هذا الصراط المؤمنون يردون ويمرون سالمين، كما قال : وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا ۝ ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا [مريم:71-72] فالله ينجي المتقين ويمرون سالمين من يمر كالبرق ومنهم من يمر كالريح، ومنهم من يمر كلمح البصر ومنهم دون ذلك، على حسب أعمالهم الصالحة، وعليه كلاليب على الجسر كلاليب من جانبيه، لا يعلم قدرها إلا الله سبحانه وتعالى تخطف الناس بأعمالهم السيئة، فمنهم من يخطف وينجو ويخدش وينجو، ومنهم من يسقط في النار نسأل الله العافية بمعاصيه، اللهم سلم سلم، والأنبياء على حافتي الصراط يقولون: اللهم سلم سلم، دعوة الأنبياء اللهم سلم سلم ذلك الوقت.\nفكل الناس الذين دخلوا في الإسلام يمرون على هذا الصراط، فالمؤمن السليم ينجو، وبعض العصاة ينجو، وبعض العصاة يخدش وينجو بعض العصاة يسقط لشدة معاصيه ويعذب على قدر معاصيه، ثم يخرجه الله من النار بتوحيده وإسلامه إلى الجنة.\nأما الكفار فلا يستطيعون بل يساقون إلى النار ويحشرون إليها؛ لأنهم من أهلها وقد أعدت لهم نسأل العافية، فهم واردوها وصائرون إليها نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيراً ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8914/تفسير-قوله-تعالى-وان-منكم-الا-واردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_345/34505.mp3","categories":["التفسير"]},{"id":10752,"question":"يسأل أيضاً ويقول: فسروا لنا قوله تعالى: وَإِذَا بَطَشْتُمْ بَطَشْتُمْ جَبَّارِينَ [الشعراء:130]؛ لأن بعض الناس عندنا يستدلون بهذه الآية كمسوغ لأخذ المال ولو بالقوة خاصة من الأغنياء؟ أفيدونا جزاكم الله خيرا.","title":"تفسير قوله تعالى: (وَإِذَا بَطَشْتُمْ بَطَشْتُمْ جَبَّارِينَ ...)","answer":"الجواب: هذه ذم الله بها عاد قوم هود ذمهم الله بهذا وأنهم ظلمة يبطشون بالناس بغير حق ويظلمونهم بالضرب والقتل ونهب الأموال هذا ذم لهم وعيب لهم فلا يجوز ذلك، بل الواجب على المسلم أن لا يأخذ المال إلا بحقه، وأن لا يضرب أحداً إلا بحقه، لابد ليس له التعدي على الناس ولا البطش بالناس، بل يطلب الحق بطريقه الشرعي إن كان له حق يطلبه من طريق المحكمة من طريق الإصلاح من طريق الإمارة، لا يبطش بالناس بالظلم والعدوان والإيذاء، ولا يظلمهم في نهب أموالهم بالمصادرة والبطش، بل الواجب عليه أن يأخذ حقه من طريقه الشرعي، ومن بابه الشرعي، فهذا ذم وعيب لعاد الذين أهلكهم الله بالريح العقيم، كانوا يظلمون الناس ويتعدون على الناس نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8929/تفسير-قوله-تعالى-واذا-بطشتم-بطشتم-جبارين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34612.mp3","categories":["التفسير"]},{"id":10761,"question":"يسأل ويقول: يقول الله تعالى في كتابه الكريم وفي سورة الزمر: يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ فِي ظُلُمَاتٍ ثَلاثٍ [الزمر:6] ما معنى الآية الكريمة؟ وما المقصود بالظلمات؟ جزاكم الله خيراً؟","title":"ما معنى: {يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ}؟","answer":"الجواب: المراد كما قال أهل العلم: أنه يطورهم سبحانه خلقاً بعد خلق أطوار، كما قال تعالى: وَقَدْ خَلَقَكُمْ أَطْوَارًا [نوح:14] فهم ينقلون من طور إلى طور، من طور النطفة في الأربعين الأولى إلى طور العلقة في الأربعين الثانية، إلى طور المضغة في الأربعين الثالثة، إلى حيوان يتحرك في بطن أمه وينمو، ثم بعد ذلك تلده إنساناً تاماً، ثم ينمو وهكذا.\nفالحاصل أنهم أطوار في الرحم من نطفة إلى علقة إلى مضغة ثم بعد المضغة تخليق سمع وبصر وأيدي وأرجل إلى غير ذلك، حتى يتم خلقه ثم تلده بإذن الله.\nوالظلمات الثلاث بينها أهل العلم: ظلمة البطن هذه واحدة.\nوظلمة الرحم الذي فيه الجنين ثانية، وظلمة المشيمة وهي كساء يكون فيه الطفل تسمى: المشيمة، هذه ثلاث ظلمات، هو في كيس ثم في الرحم ثم في البطن ثلاثة أشياء ظلمة بعد ظلمة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8938/ما-معنى-يخلقكم-في-بطون-امهاتكم-خلقا-من-بعد-خلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34708.mp3","categories":["التفسير"]},{"id":10776,"question":"نعود مع مطلع هذه الحلقة إلى رسالة أحد الإخوة المستمعين من نيجيريا في مدينة لاجوس هو المستمع زكريا محمد حسن ، أخونا زكريا عرضنا له سؤال في حلقة مضت وفي هذه الحلقة يسأل عن تفسير آية، هي قول الحق تبارك وتعالى: أعوذ بالله من الشيطان الرجيم: إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُوْلَئِكَ كَانَ عَنْهُ مَسْئُولًا [الإسراء:36].","title":"تفسير قوله تعالى: (إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ...)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه الآية الكريمة مضمونها التحذير من أن تسمع ما لا يحل لك، أو تنظر إلى ما لا يحل لك، أو تعتقد ما لا يحل لك، فأنت مسئول عما سمعت وعما نظرت إليه وعما اعتقدته بقلبك، والفؤاد: هو القلب، فالإنسان مسئول عن سمعه وبصره وفؤاده.\nفعلى المؤمن أن يتقي الله في سمعه وبصره وقلبه، وأن لا يسمع ما حرم الله عليه من سماع الأغاني وآلات اللهو أو سماع الغيبة والنميمة لما فيهما من الضرر العظيم أو ما أشبه ذلك مما يضر سماعه، بل يستمع الخير كاستماعه للقرآن الكريم أو للسنة المطهرة أو للأحاديث المفيدة، وسماعه لكلام أهله المباح أو كلام إخوانه وما أشبه ذلك مما هو مباح أما المحرم فليحذر.\nومن ذلك أن يستمع لقوم يكرهون سماعه ولا يرضون أن يسمع حديثهم فلا يجوز له ذلك، كما في الحديث الصحيح عن رسول الله ﷺ أنه قال: من تسمع حديث قوم وهم له كارهون صب في أذنيه الآنك يوم القيامة رواه البخاري ، والآنك يعني: الرصاص، هذا تحذير من سماع أحاديث الناس وهم يكرهون ذلك، كأن تستمع لهم من عند الباب سراً أو من طاقة أو من سماعة التلفون، أو أشباه ذلك، ليس لك أن تستمع حديث قوم يكرهون ذلك لهذا الحديث العظيم، وهو قوله ﷺ: من تسمع حديث قوم وهم له كارهون صب في أذنيه الآنك يوم القيامة يعني: الرصاص نسأل الله العافية.\nوهكذا البصر أنت مأمور بغض البصر عما حرم الله، غض البصر عن النسوان عن النساء، لئلا تفتن بهن، كما قال جل وعلا: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ [النور:30] تغض بصرك عما حرم الله عليك من النساء الأجنبيات، كزوجة أخيك أو زوجة عمك أو ما أشبه ذلك من غير المحارم.\nوهكذا عن المردان إذا خشي الفتنة تغض بصرك عن النظر إلى الأمرد إذا خشيت الفتنة وهكذا مما أشبه ذلك مما يحرم النظر إليه كعورات الناس، ليس لك أن تنظر عورات الناس ولا من خلال بيوتهم؛ لأنك ممنوع من ذلك.\nوهكذا يجب عليك أن تحذر الاعتقادات الباطلة، بل يجب أن تنزه قلبك وعقلك عما حرم الله، فلا تعتقد ما حرم الله عليك من حل ما حرم الله، أو اعتقاد عدم وجوب ما أوجب الله، أو عمل بقلبك لما حرم الله، كاعتقاد -مثلاً- أن الزنا حلال هذا من مرض القلب، وهو كفر نسأل الله العافية، وهكذا اعتقاد أن شرب الخمر حلال هذا من مرض القلب وهو كفر أكبر نسأل الله العافية.\nوهكذا سوء ظنك بالله وسوء ظنك بإخوانك من غير دليل أيضاً من أمراض القلب، وهكذا قنوطك من رحمة الله وأمنك من مكر الله كلها أعمال قلبية خطيرة منكرة من كبائر الذنوب، وهكذا النفاق مرض قلبي، كونك تظهر الإسلام وتعتقد الكفر في الباطن في القلب تعتقد أن الرسول ليس بصادق، أو أن الدين ليس بحق أو ما أشبه هذا من اعتقادات أهل النفاق.\nوالخلاصة: أن السمع والبصر والفؤاد كلها يجب أن تصان عما حرم الله، عليك أن تصون سمعك عما حرم الله، وبصرك عما حرم الله، وقلبك عما حرم الله، وأن تنظر وتسمع لما ينفعك ويرضي الله عنك، أو ما أباح الله لك، وتعتقد في قلبك ما شرعه الله وما أباح الله، تعمل بذلك كحب الله ورسوله.. خوف الله ورجائه، كل هذه أعمال قلبية مفروضة، حسن الظن بالله، اعتقاد أنه الواحد الأحد المستحق للعبادة، واعتقاد ما أوجب الله عليك كالصلاة والصوم تعتقد هذا بقلبك أن الله أوجب الصلاة على المكلفين من المسلمين، أوجب الزكاة لمن لديه مال فيه الزكاة، أوجب صوم رمضان لمن استطاع ذلك، أوجب الحج على من استطاع ذلك وهكذا.\nوأنت مسئول عن هذه كلها يوم القيامة فإن كنت حافظت عليها وصنتها سلمت وحمدت العاقبة، أما إن كنت أسأت التصرف ولم تصنها عما حرم الله فإنك على خطر عظيم، وفيه تفصيل كما تقدم. نعم.\nالمقدم: جزاكم الله خيراً ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8949/تفسير-قوله-تعالى-ان-السمع-والبصر-والفواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_349/34901.mp3","categories":["التفسير"]},{"id":10794,"question":"يقول: أرجو أن تتكرموا بتفسير قول الحق -تبارك وتعالى- في سورة مريم: أعوذ بالله من الشيطان الرجيم: فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا  ۝إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا فَأُوْلَئِكَ يَدْخُلُونَ الْجَنَّةَ وَلا يُظْلَمُونَ شَيْئًا [مريم:59-60] رجل كان في شبابه يعمل كثيرًا من الكبائر، ويترك الصلاة، ثم تاب واهتدى، وأقبل على الصلاة، ويستشهد كثيرًا بهذه الآية، ما هو قولكم شيخ عبدالعزيز؟ جزاكم الله خيرًا.","title":"ما معنى: {فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلاةَ}؟","answer":"الجواب:  نعم، هذه الآية تدل على عظم جريمة من أضاع الصلاة، يقول سبحانه: فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ [مريم: 59] وخلف بالتسكين هو خلف السوء، يعني الذي يأتي بعد الصالح وهو على غير هدى يقال له: خلف فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ [مريم: 59] يعني: قوم جاؤوا بعدهم، ليسوا على استقامة، بل على إضاعة للصلوات، وركوب للمحارم، ولهذا قال: وَاتَّبَعُوا الشَّهَوَاتِ [مريم: 59] يعني: المحرمة كالزنا، وشرب المسكرات، واللواط، وأكل الربا وغير ذلك مما حرم الله، فَسَوْفَ يَلْقَوْنَ غَيًّا [مريم: 59] يعني خسارًا ودمارًا، وعاقبة سيئة، وقال بعض المفسرين: غيًا: يعني وادي في جهنم، يعني في واد في جهنم خبيثًا طعمه، بعيدًا قعره، نسأل الله العافية. وبكل حال فالذي يضيع الصلوات، ويتركها قد أتى منكرًا عظيمًا، وهو كافر عند جمع من أهل العلم، وإن لم يجحد الوجوب. أما إذا جحد الوجوب قال: إنها لا تجب صار كافرًا عند الجميع -نسأل الله العافية- لكن لو تركها تهاونًا، وهو يعلم أنها واجبة عليه، لكن يتساهل فهذا هو محل الخلاف بين أهل العلم. والصواب أنه يكفر بذلك، لقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ولم يقل: إذا جحد وجوبها، وقال -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، في أدلة أخرى غير هذين الحديثين. فيجب على كل مؤمن ومؤمنة العناية بالصلاة والمحافظة عليها طاعة لله وتعظيمًا له، كما قال سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] قال : وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43]. كذلك يحذر الشهوات التي حرم الله عليه من فعل المعاصي، يجب الحذر منها أينما كان في السفر والإقامة في الغيبة والشهادة، في جميع الأحوال، كالزنا، والمآكل المحرمة، والمشارب المحرمة كالخمر، وغير هذا مما حرم الله  لكن متى تاب تاب الله عليه، إذا تاب من ذلك فالكفر أعظم الذنوب، إذا تاب صاحبه تاب الله عليه، ولهذا قال تعالى: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا [مريم:60]. فإذا ندم على ما مضى منه، وأقلع، وعزم ألا يعود، واستقام على الصلاة وغيرها مما أوجب الله، وعلى ترك ما حرم الله، فله الجنة والكرامة، كما قال في آية الفرقان : وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا [الفرقان:68] يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:69] هذا وعيدهم إذا ماتوا على الشرك، أو على قتل النفس بغير حق، أو على الزنا، هذا وعيدهم، نسأل الله العافية. ثم قال: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا [الفرقان:70] فإذا تاب من الشرك والقتل والزنا أبدل الله السيئات حسنات، لو صحت التوبة، وأتبعها بالعمل الصالح، بدل الله سيئاته حسنات، وغفر له . كما قال  في الآية الأخرى: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] وقال سبحانه في آية الزمر: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]  والمعنى للتائبين، أجمع العلماء على أن المراد بذلك التائبون، من تاب تاب الله عليه، وغفر له جميع ذنوبه. فالواجب التوبة، والبدار بها، ولا يقنط ولا ييأس، بل يحسن ظنه بربه، ويبادر بالتوبة، ويتبعها بالعمل الصالح، بالصلوات التطوع.. الصدقات.. عيادة المريض.. الأمر بالمعروف والنهي عن المنكر.. الدعوة إلى الله، إلى غير هذا من وجوه الخير التي تكون تارة واجبة، كالأمر بالمعروف، وتكون تارة مستحبة. فالمقصود أن يتبع توبته بالأعمال الصالحات من واجب ومستحب، ويحافظ على الصلوات الخمس، ويؤدي الزكاة، ويصوم رمضان، ويحج البيت، ويأمر بالمعروف، وينهى عن المنكر، ويدعو إلى الله، ويتعاطى ما يسر الله له من النوافل وغيرها من الطاعات التي أوجبها على عباده  وذلك من الدلائل على صدق التوبة، كونه يتبعها بالعمل الصالح من الدلائل على صدق التوبة، واستقامة صاحبها عليها. نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8976/ما-معنى-فخلف-من-بعدهم-خلف-اضاعوا-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35206.mp3","categories":["التفسير"]},{"id":10812,"question":"المستمع عمران موسى من جمهورية مصر العربية بعث بسؤال يقول فيه: ما تفسير قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم: وَمَنْ لَمْ يَحْكُمْ بِمَا أَنزَلَ اللَّهُ فَأُوْلَئِكَ هُمُ الْكَافِرُونَ [المائدة:44]؟","title":"ما معنى: {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنزَلَ اللَّهُ فَأُوْلَئِكَ هُمُ الْكَافِرُونَ}؟","answer":"الجواب:  المعروف عند أهل العلم مثلما قال ابن عباس أنه كفر دون كفر، إذا كان يعتقد أن حكم الله هو الواجب، وأن الحكم بغير ما أنزل الله لا يجوز، ولكن حكم بغير ما أنزل الله لأسباب أخرى، فإنه حينئذٍ يكون فاسقًا وظالمًا وكافرًا، لكنه ظلم دون ظلم، وفسق دون فسق، وكفر دون كفر؛ لأنه يعرف أنه ظالم، وأنه مخطي، وأنه عاصٍ لله، ولكن حمله على الحكم بغير ما أنزل الله أسباب اعتقد أنها مبررة لعمله السيئ، كأخذ الرشوة، ووجوده في الإمارة والسلطنة، وما أشبه ذلك، فهذا كفر دون كفر، وظلم دون ظلم، وفسق دون فسق. أما من حكم بغير ما أنزل الله يعتقد جواز ذلك، أو أنه أفضل من حكم الله؛ فهذا كافر كفرًا أكبر، بعض الناس -نعوذ بالله- يعتقد أن الحكم بما أنزل الله مضى زمانه، وأنه لا يليق بأهل الزمان، وهذا من أعظم الكفر، نسأل الله العافية. كذلك لو اعتقد أنه يسوغ، أو أنه مفضول، ولكن يسوغ وإلا حكم الله أفضل، كل هذا كفر، لابد يعتقد أن حكم الله هو الواجب، وهو اللازم، وأن الحكم بغير ما أنزل الله أمر يجب طرحه يجب تركه، وأنه منكر. فأما إذا استساغه وجوزه ولو رأى أن الشريعة أفضل منه؛ فإنه يكون كافراً، نسأل الله العافية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8985/ما-معنى-ومن-لم-يحكم-بما-انزل-الله-فاولىك-هم-الكافرون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35307.mp3","categories":["التفسير"]},{"id":10871,"question":"ننتقل إلى موضوع آخر وسؤال آخر لإخوتنا من السودان، هو طلب تفسير آية من سورة النور، وهي قول الحق -تبارك وتعالى- أعوذ بالله من الشيطان الرجيم: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ وَاللَّهُ وَاسِعٌ عَلِيمٌ [النور:32]؟","title":"ما معنى: {وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ}؟","answer":"الجواب:  على ظاهرها، الرب -جل وعلا- يأمر عباده أن ينكحوا الأيامى وهن اللاتي لا أزواج لهن، وكذلك الصالحين من عبادهم وإمائهم أن يزوجوهم حتى لا يتعطل المؤمن والمؤمنة؛ لأن العزوبة فيها خطر عظيم، فينبغي إنكاح الرجال والنساء، فينكح الأيامى، وينكح الصالحين من العباد والإماء، فينكح الأيامى يزوجهن على الأكفاء إذا خطبن، ولا يترك العباد والإماء، عبده يزوجه، وأمته يزوجها حتى لا تقع الفاحشة، ولا تقع الكارثة نعم، وإذا تسرى سرية، أمته جعلها سرية له وأحصنها فلا بأس إذا كانت مملوكة له، أو يزوجها حتى لا تتعطل، وهكذا عبده يزوجه ولا يعطله؛ لأنه مثل الحر يحتاج إلى ما يعفه، وهي تحتاج إلى ما يعفها إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]. والمتزوج إذا كان عنده قدره يتزوج، يغنيه الله من جهة النفقة، لا يتعطل مادام عنده قدرة على الزواج، يتزوج ثم يتعاطى الأسباب التي تعينه على النفقة في المستقبل. أما إن كان عاجزًا ما عنده قدرة مثل قال الله بعدها: وَلْيَسْتَعْفِفِ الَّذِينَ لا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِه [النور:33]، فالذي لا يجد يعني الطول -المهر- يعني يستعفف حتى يغنيهم الله من فضله، وهذا معنى قوله سبحانه: وَلْيَسْتَعْفِفِ الَّذِينَ لا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِه [النور:33]، يعني لا يجدون الطول، يعني مهور النساء فإنه يتعفف، ويصبر حتى يغنيهم الله، فيجد الطول الذي يقدمه للمرأة، ومن قدر فإنه يتزوج، ثم يفعل الأسباب التي تعينه على النفقة كما في الآيات السابقة: إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]، إذا استطاعوا الزواج يتزوجوا، والله يغنيهم بعد ذلك يعني فيما يعينهم على النفقة، نعم. المقدم: جزاكم الله خيرًا.  الشيخ: ويحتمل أيضًا مِنْ عِبَادِكُمْ وَإِمَائِكُمْ [النور: 32] أن المراد يعني جنس بني آدم، يعني كلهم عبيد، وكلهم إماء لله، ولهذا قال: إِنْ يَكُونُوا فُقَرَاءَ [النور:32]، فهذا يقتضي أن المراد به الأحرار، سموا عبادًا وإماء، هم عباد الله، وإماء الله، وسموا عبادكم، وإمائكم، يعني موجودين لديكم بينكم من أولاد وإخوة وأشباه ذلك، فإن الآية تشمل هذا وهذا .. فالسيد يزوج أمته التي لا يتسراها، ويزوج عبده الذي هو مملوك لا يهملهما، ويزوج أيضًا بنيه وبناته، فهم عباد لله، فالإضافة عبادكم وإمائكم يعني: عباده الذين هم من جنسكم، وإيمائكم، يعني: بينكم، يعني: كلهن إماء لله، وكلهم عباد لله، وأضيفوا إلى المسلمين والمخاطبين؛ لأنهم بعضهم، وجزء منهم، فهم عبادهم وإماؤهم، يعني: الذين يوجدون بينكم من ذكور وإناث، فهم عبيدالله، وإماء الله، فينبغي أن تسعوا لتزويجهم، سواء كانوا أبناء أو إخوة أو أصدقاء أو غيرهم. فالمسلم أخو المسلم يعينه على الزواج، ويعينه على إعفاف فرجه، ويعين أخته في الله على إعفاف فرجها، يكون من باب التعاون على البر والتقوى، ومن باب وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، فأمروا بتزويج العباد، والإماء، يعني: عباد الله، وإماء الله؛ لأنهم إخوتهم في الله، أو بنوهم، أو إخوتهم من النسب، أو أعمامهم، أو بنو إخوتهم، فأرشدوا إلى أن يزوجوهم، ويعينوهم؛ لأنهم فيما بينهم إخوة، وإن كانوا ليسوا أولادًا له، ولا إخوة له، فالإسلام يجمعهم، والدين يجمعهم، فهم إخوة في الله  ولهذا أمروا بأن يتعاونوا على البر والتقوى قال: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، المسلم أخو المسلم لا يظلمه ولا يحقره الحديث، وقال -عليه الصلاة والسلام-: من كان في حاجة أخيه كان الله في حاجته متقف عليه، وقال -عليه الصلاة والسلام-: والله في عون العبد ما كان العبد في عون أخيه. فمساعدة الرجال والنساء في الزواج من إخوانهم في الله هذا شيء طيب، ومن التعاون على الخير، ومن العون على الخير، وكل مسلم مأمور بهذا، مأمور بأن يعين على الخير، يعين أخاه على الزواج، يعين أخته في الله على الزواج حتى لا يبقى أعزب، لا رجال ولا نساء، وبهذا يحصل الخير العظيم للمسلمين، والتناسل، وكثرة الأمة، وإعفاف الفروج، غض الأبصار، كل هذا يحصل بهذا التعاون، هذا إذا حملنا الآية على جنس العباد، جنس الإماء، وإن لم يكونوا مماليك؛ لأنهم عبيد الله، وهم إخواننا. فالواجب على المسلمين التعاون فيما بينهم في تزويج الرجال والنساء، الأيامى: اللاتي لا أزواج لهن، سواء كن ثيبات أو أبكارًا، وجنس العباد، وجنس النساء من حيث الإطلاق في تزويجهم، والعناية بإعفاف فروجهم، وغض أبصارهم بالتعاون فيما بين المسلمين، هذا يسلم ربع المهر، وهذا نصف المهر، وهذا جزء من المهر حتى يتزوج الناس، ولا يتعطلوا، نعم والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9052/ما-معنى-وانكحوا-الايامى-منكم-والصالحين-من-عبادكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35806.mp3","categories":["التفسير"]},{"id":10906,"question":"تسأل عن تفسير قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ ظَالِمِي أَنفُسِهِمْ قَالُوا فِيمَ كُنتُمْ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الأَرْضِ قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا فَأُوْلَئِكَ مَأْوَاهُمْ جَهَنَّمُ وَسَاءَتْ مَصِيرًا [النساء:97].","title":"معنى قوله تعالى: (إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ)","answer":"الجواب:  هذه الآية الكريمة ذكر العلماء أنها نزلت في أناس تخلفوا في مكة، ولم يهاجروا مع النبي ﷺ فلما كانت غزوة بدر أجبرهم الكفار على الخروج معهم، وحضروا القتال، فنزلت الآية الكريمة فيهم لما قتل من قتل منهم، وهي قوله -جل وعلا-: إن الذين توفاهم الملائكة ظالمي أنفسهم المعنى: ظالمي أنفسهم بالإقامة بين أظهر المشركين، وهم قادرون على الهجرة، قَالُوا فِيمَ كُنْتُمْ يعني: قالت لهم الملائكة: فيم كنتم؟ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الْأَرْضِ يعني: في أرض مكة قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً يعني: قالت لهم الملائكة: أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا فَأُوْلَئِكَ مَأْوَاهُمْ جَهَنَّمُ وَسَاءَتْ مَصِيرًا ۝ إِلَّا الْمُسْتَضْعَفِينَ [النساء:97-98] الآية. فهم متوعدون بالنار؛ لأنهم أقاموا بين أظهر الكفار من دون عذر، وكان الواجب عليهم أن يهاجروا إلى بلاد الإسلام إلى المدينة المنورة، فلما أجبروا على الخروج، وأكرهوا صار ذلك ليس عذرًا لهم، وكان عملهم سببًا لهذا الإكراه وسببًا لهذا الخروج، فجاء فيهم هذا الوعيد، لكونهم عصوا الله بإقامتهم مع القدرة على الهجرة، ولم يكفروا؛ لأنهم مكرهون، أخرجوا إلى ساحة القتال، ولم يقاتلوا، لكن قتلوا، قتل من قتل منهم، أما لو قاتلوا وهم مختارون راضون غير مكرهين لكانوا كفارًا؛ لأن من ظاهر الكفار وساعدهم يكون كافرًا مثلهم، لكن هؤلاء لم يقاتلوا، وإنما أكرهوا على الحضور، وتكثير السواد فقط فقتلوا من غير أن يقاتلوا. وقال آخرون من أهل العلم: إنهم كفروا بذلك؛ لأنهم أقاموا من غير عذر، ثم خرجوا معهم، وفي إمكانهم التملص، والخروج من بين الكفرة في الطريق، أو حين التقاء الصفين، وفي إمكانهم أن يلقوا السلاح، ولا يقاتلوا، وبكل حال فهم بين أمرين: من قاتل منهم وهو غير مكره فهو كافر، حكمه حكم الكفرة الذين قتلوا، وليس له عذر في أصل الإكراه؛ لأنه لما أكره باشر وقاتل ورضي بمساعدة الكفار، فصار معهم، وصار مثلهم، ودخل في قوله تعالى: وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَإِنَّهُ مِنْهُمْ [المائدة:51] وقد أجمع العلماء -رحمهم الله-: على أن من ظاهر الكفار على المسلمين، وساعدهم بالسلاح، أو بالمال فإنه يكون كافرًا بالله مرتدًا عن الإسلام. أما من أكره ولم يقاتل، ولم يرض بقتال أهل الإسلام، ولم يوافق على ذلك، ولكن أجبر وأكره بالقوة والرباط والإكراه حتى وصل إلى ساحة القتال، ولم يقاتل فهذا يكون عاصيًا بأصل إقامته، ومتوعد على ذلك بالنار؛ لأنه أقام معهم من دون عذر. ولهذا ذكر ابن كثير -رحمه الله- وجماعة آخرون من أهل العلم: أن الإقامة بين أظهر الكفار وهو عاجز عن إظهار دينه محرمة بالإجماع، ليس للمسلم أن يقيم بين الكفار وهو يقدر على الهجرة، وهو لا يستطيع إظهار دينه، بل هو مغلوب على أمره، بل يجب عليه أن يهاجر بإجماع المسلمين لهذه الآية الكريمة؛ لأن الله وصفهم بأنهم ظلموا أنفسهم بهذه الإقامة، وتوعدهم بالنار، فدل ذلك على أنهم قد عصوا الله في هذه الإقامة. والهجرة لم تنقطع ما دام هناك دينان فالهجرة باقية، وإنما الذي انقطع الهجرة من مكة لما فتحت، قال النبي ﷺ فيها: لا هجرة بعد الفتح يعني: من مكة؛ لأنها صارت بلد إسلام بعدما فتحها الله على نبيه ﷺ صارت بلد إسلام، فقال فيها النبي ﷺ: لا هجرة بعد الفتح يعني: من مكة بعد فتحها، أما الهجرة في أصلها فهي باقية، ولهذا في الحديث الآخر لا تنقطع الهجرة حتى تنقطع التوبة، فكل بلد ظهر فيها الكفار، ولم يستطع المسلم فيها إظهار دينه، ولا إقامة دينه، وهو يستطيع الخروج فإنه يلزمه أن يهاجر، فإن أقام كان عاصيًا بالإجماع. أما المستضعف من الرجال والنساء والولدان فقد عذرهم الله، وهم الذين لا يستطيعون حيلة لعدم النفقة، أو لأنهم مقيدون مسجونون، أو لا يهتدون سبيلًا؛ لأنهم جهال بالطريق، لا يعرفون الطريق، لو خرجوا هلكوا، لا يعرفون السبيل فهم معذورون حتى يسهل الله لهم فرجًا ومخرجًا من بين أظهر المشركين، والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9075/معنى-قوله-تعالى-ان-الذين-توفاهم-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36002.mp3","categories":["التفسير"]},{"id":10910,"question":"تسأل عن تفسير قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ ظَالِمِي أَنفُسِهِمْ قَالُوا فِيمَ كُنتُمْ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الأَرْضِ قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا فَأُوْلَئِكَ مَأْوَاهُمْ جَهَنَّمُ وَسَاءَتْ مَصِيرًا [النساء:97].","title":"معنى قوله تعالى: (إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ)","answer":"الجواب:  هذه الآية الكريمة ذكر العلماء أنها نزلت في أناس تخلفوا في مكة، ولم يهاجروا مع النبي ﷺ فلما كانت غزوة بدر أجبرهم الكفار على الخروج معهم، وحضروا القتال، فنزلت الآية الكريمة فيهم لما قتل من قتل منهم، وهي قوله -جل وعلا-: إن الذين توفاهم الملائكة ظالمي أنفسهم المعنى: ظالمي أنفسهم بالإقامة بين أظهر المشركين، وهم قادرون على الهجرة، قَالُوا فِيمَ كُنْتُمْ يعني: قالت لهم الملائكة: فيم كنتم؟ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الْأَرْضِ يعني: في أرض مكة قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً يعني: قالت لهم الملائكة: أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا فَأُوْلَئِكَ مَأْوَاهُمْ جَهَنَّمُ وَسَاءَتْ مَصِيرًا ۝ إِلَّا الْمُسْتَضْعَفِينَ [النساء:97-98] الآية. فهم متوعدون بالنار؛ لأنهم أقاموا بين أظهر الكفار من دون عذر، وكان الواجب عليهم أن يهاجروا إلى بلاد الإسلام إلى المدينة المنورة، فلما أجبروا على الخروج، وأكرهوا صار ذلك ليس عذرًا لهم، وكان عملهم سببًا لهذا الإكراه وسببًا لهذا الخروج، فجاء فيهم هذا الوعيد، لكونهم عصوا الله بإقامتهم مع القدرة على الهجرة، ولم يكفروا؛ لأنهم مكرهون، أخرجوا إلى ساحة القتال، ولم يقاتلوا، لكن قتلوا، قتل من قتل منهم، أما لو قاتلوا وهم مختارون راضون غير مكرهين لكانوا كفارًا؛ لأن من ظاهر الكفار وساعدهم يكون كافرًا مثلهم، لكن هؤلاء لم يقاتلوا، وإنما أكرهوا على الحضور، وتكثير السواد فقط فقتلوا من غير أن يقاتلوا. وقال آخرون من أهل العلم: إنهم كفروا بذلك؛ لأنهم أقاموا من غير عذر، ثم خرجوا معهم، وفي إمكانهم التملص، والخروج من بين الكفرة في الطريق، أو حين التقاء الصفين، وفي إمكانهم أن يلقوا السلاح، ولا يقاتلوا، وبكل حال فهم بين أمرين: من قاتل منهم وهو غير مكره فهو كافر، حكمه حكم الكفرة الذين قتلوا، وليس له عذر في أصل الإكراه؛ لأنه لما أكره باشر وقاتل ورضي بمساعدة الكفار، فصار معهم، وصار مثلهم، ودخل في قوله تعالى: وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَإِنَّهُ مِنْهُمْ [المائدة:51] وقد أجمع العلماء -رحمهم الله-: على أن من ظاهر الكفار على المسلمين، وساعدهم بالسلاح، أو بالمال فإنه يكون كافرًا بالله مرتدًا عن الإسلام. أما من أكره ولم يقاتل، ولم يرض بقتال أهل الإسلام، ولم يوافق على ذلك، ولكن أجبر وأكره بالقوة والرباط والإكراه حتى وصل إلى ساحة القتال، ولم يقاتل فهذا يكون عاصيًا بأصل إقامته، ومتوعد على ذلك بالنار؛ لأنه أقام معهم من دون عذر. ولهذا ذكر ابن كثير -رحمه الله- وجماعة آخرون من أهل العلم: أن الإقامة بين أظهر الكفار وهو عاجز عن إظهار دينه محرمة بالإجماع، ليس للمسلم أن يقيم بين الكفار وهو يقدر على الهجرة، وهو لا يستطيع إظهار دينه، بل هو مغلوب على أمره، بل يجب عليه أن يهاجر بإجماع المسلمين لهذه الآية الكريمة؛ لأن الله وصفهم بأنهم ظلموا أنفسهم بهذه الإقامة، وتوعدهم بالنار، فدل ذلك على أنهم قد عصوا الله في هذه الإقامة. والهجرة لم تنقطع ما دام هناك دينان فالهجرة باقية، وإنما الذي انقطع الهجرة من مكة لما فتحت، قال النبي ﷺ فيها: لا هجرة بعد الفتح يعني: من مكة؛ لأنها صارت بلد إسلام بعدما فتحها الله على نبيه ﷺ صارت بلد إسلام، فقال فيها النبي ﷺ: لا هجرة بعد الفتح يعني: من مكة بعد فتحها، أما الهجرة في أصلها فهي باقية، ولهذا في الحديث الآخر لا تنقطع الهجرة حتى تنقطع التوبة، فكل بلد ظهر فيها الكفار، ولم يستطع المسلم فيها إظهار دينه، ولا إقامة دينه، وهو يستطيع الخروج فإنه يلزمه أن يهاجر، فإن أقام كان عاصيًا بالإجماع. أما المستضعف من الرجال والنساء والولدان فقد عذرهم الله، وهم الذين لا يستطيعون حيلة لعدم النفقة، أو لأنهم مقيدون مسجونون، أو لا يهتدون سبيلًا؛ لأنهم جهال بالطريق، لا يعرفون الطريق، لو خرجوا هلكوا، لا يعرفون السبيل فهم معذورون حتى يسهل الله لهم فرجًا ومخرجًا من بين أظهر المشركين، والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9075/معنى-قوله-تعالى-ان-الذين-توفاهم-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36002.mp3","categories":["التفسير"]},{"id":11064,"question":"السائل حمد عبدالله سوداني مقيم بالغرمة، يستفسر عن الآية الكريمة في سورة طه: وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنكًا وَنَحْشُرُهُ يَوْمَ الْقِيَامَةِ أَعْمَى ۝ قَالَ رَبِّ لِمَ حَشَرْتَنِي أَعْمَى وَقَدْ كُنتُ بَصِيرًا ۝ قَالَ كَذَلِكَ أَتَتْكَ آيَاتُنَا فَنَسِيتَهَا وَكَذَلِكَ الْيَوْمَ تُنسَى [طه: 124- 126]، يقول: هل هذه الآية على كل شخص يغفل عن ذكر الله؟ أفيدوني بذلك.","title":"تفسير قوله تعالى: (ومن أعرض...)","answer":"الجواب:  هذا وعيد شديد فيمن أعرض عن ذكر الله، وعن طاعته، فلم يؤد حق الله هذا جزاؤه، تكون معشيته ضنكا وإن كان في مال كثير وسعة، لكن يجعل الله في عيشته ضنكًا لما يقع في قلبه من الضيق والحرج والمشقة، فلا ينفعه وجود المال، يكون في حرج، وفي مشقة بسبب إعراضه عن ذكر الله، وعن طاعة الله -جل وعلا- ثم يحشر يوم القيامة أعمى. فالمقصود أن هذا فيمن أعرض عن طاعة الله، وعن حقه -جل وعلا- ولم يبال بأمر الله، بل ارتكب محارمه، وترك طاعته -جل وعلا- فهذا جزاؤه، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9242/تفسير-قوله-تعالى-ومن-اعرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28812.mp3","categories":["التفسير"]},{"id":11138,"question":"ننتقل بعد هذا إلى رسالة وصلت إلينا من ضواحي ينبع البحر، باعث الرسالة مستمع يقول: مناحي مسعد سليم الجهني، أخونا يسأل تفسير قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَنْ تَحْبَطَ أَعْمَالُكُمْ وَأَنْتُمْ لا تَشْعُرُونَ [الحجرات:2]؟","title":"ما معنى: {لا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ}؟","answer":"الجواب:  الآية واضحة، فالله سبحانه ينهى الصحابة أن يرفعوا أصواتهم فوق صوت النبي، وينهاهم أن يجهروا له بالقول كجهر بعضهم لبعض، يأمرهم بالآداب الشرعية أن يتأدبوا عنده، ويخفضوا أصواتهم عند صوته، إذا خاطبوه لا يرفعون أصواتهم، بل ... يخفضونها وهكذا لا يجهرون عنده بالقول في حديثهم، بل يسرون ويخافتون تأدبًا معه -عليه الصلاة والسلام- وكان عمر  إذا كلمه كلمه .....  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9314/ما-معنى-لا-ترفعوا-اصواتكم-فوق-صوت-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36914.mp3","categories":["التفسير"]},{"id":11148,"question":"أيضًا تطلب من سماحتكم تفسير قول الله : ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ [البقرة:187] وضحوا لنا ذلك توضيحًا كافيًا جزاكم الله خيرًا.","title":"تفسير قوله تعالى: (ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ)","answer":"الجواب:  معناه أن الصائم يمسك عن المفطرات إلى غروب الشمس، هذا معنى: ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ [البقرة:187] يعني: أمسكوا عن المفطرات من طعام أو شراب وغيرهما إلى غروب الشمس، وإذا كان غيمًا فإلى غلبة الظن إذا غلب على الظن غروب الشمس بسبب الساعات، أو غيرها كفى ذلك، والحمد لله.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9324/تفسير-قوله-تعالى-ثم-اتموا-الصيام-الى-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_370/37004.mp3","categories":["التفسير"]},{"id":11151,"question":"أيضًا تطلب من سماحتكم تفسير قول الله : ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ [البقرة:187] وضحوا لنا ذلك توضيحًا كافيًا جزاكم الله خيرًا.","title":"تفسير قوله تعالى: (ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ)","answer":"الجواب:  معناه أن الصائم يمسك عن المفطرات إلى غروب الشمس، هذا معنى: ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ [البقرة:187] يعني: أمسكوا عن المفطرات من طعام أو شراب وغيرهما إلى غروب الشمس، وإذا كان غيمًا فإلى غلبة الظن إذا غلب على الظن غروب الشمس بسبب الساعات، أو غيرها كفى ذلك، والحمد لله.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9324/تفسير-قوله-تعالى-ثم-اتموا-الصيام-الى-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_370/37004.mp3","categories":["التفسير"]},{"id":11340,"question":"هذا السائل عبدالرحمن محمد الولاية الشمالية السودان يقول: أرجو من فضيلة الشيخ تفسير الآية الكريمة من سورة عبس: ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ ۝ ثُمَّ إِذَا شَاءَ أَنْشَرَهُ ۝ كَلَّا لَمَّا يَقْضِ مَا أَمَرَهُ [عبس:21-23]، مع العلم بأنني قرأت في تفسير ابن كثير ولم أفهم الشرح، مأجورين؟","title":"تفسير قوله تعالى: (ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ)","answer":"الجواب:  الآية الكريمة واضحة ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ [عبس:21] إلى آخر الآية، أن الله -جل وعلا- يميت الناس، هذه الدنيا دار متاع، ومؤقتة ولها نهاية، كما قال -جل وعلا-: مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَى [طه:55]، وقال -جل وعلا-: قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ [الأعراف:25]، ثم يخرجهم يوم القيامة، كَلَّا لَمَّا يَقْضِ مَا أَمَرَهُ [عبس:23]، ظاهر الآية -والله أعلم- أن الإنسان يموت وقد يكون هناك أشياء لم يقضها من الشؤون التي أمر بها؛ لأن الإنسان قد يفجأه الأجل قد يحل به الموت وهناك أشياء لم يقضها. فالعاقل والحازم هو الذي يبادر ويسارع في أداء ما أوجب الله عليه وترك ما حرم الله عليه قبل أن يهجم عليه الأجل يكون هذا من الحزم أن يبادر ويسارع إلى قضاء ما أوجب الله عليه وترك ما حرم الله عليه قبل أن يهجم عليه الأجل وهو لم يقض ما أمره الله به، يعني: قد فرط وأضاع، وهذا مثل قوله -جل وعلا- في كتابه الكريم: سَابِقُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ [الحديد:21] وَسَارِعُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ [آل عمران:133]، فهذا كله من باب الحيطة للمؤمن أن يسارع ويسابق حتى لا يهجم الأجل وقد فرط. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9522/تفسير-قوله-تعالى-ثم-اماته-فاقبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29303.mp3","categories":["التفسير"]},{"id":11444,"question":"أيضًا تسأل تفسير قول الله تعالى: ذَرْنِي وَمَنْ خَلَقْتُ وَحِيدًا ۝ وَجَعَلْتُ لَهُ مَالًا مَمْدُودًا ۝ وَبَنِينَ شُهُودًا ۝ وَمَهَّدْتُ لَهُ تَمْهِيدًا ۝ ثُمَّ يَطْمَعُ أَنْ أَزِيدَ ۝ كَلَّا إِنَّهُ كَانَ لِآيَاتِنَا عَنِيدًا [المدثر:11-16]؟","title":"تفسير قوله تعالى: (ذَرْنِي وَمَنْ خَلَقْتُ وَحِيدًا...) الآيات","answer":"الجواب:  المشهور عند المفسرين أن هذه الآيات نزلت في الوليد بن المغيرة ، وكان من كبار الكفار، ومن صناديدهم، وهذا وعيد من الله ذَرْنِي وَمَنْ [المدثر:11]، هذا وعيد من الله لهذا الرجل إذا استمر على كفره وضلاله، نعوذ بالله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9653/تفسير-قوله-تعالى-ذرني-ومن-خلقت-وحيدا-الايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38127.mp3","categories":["التفسير"]},{"id":11471,"question":"بعد هذا رسالة بعث بها المستمع عز الدين حسن يقول: فسروا لنا قول الحق -تبارك وتعالى-: عَبَسَ وَتَوَلَّى ۝ أَنْ جَاءَهُ الأَعْمَى ۝ وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّى [عبس:1-3]؟","title":"تفسير أوائل سورة عبس","answer":"الجواب:  هذه الآية تفسيرها ظاهر واضح، وهي لها سبب، وهو أن النبي ﷺ كان مشغولًا ببعض كبار قريش في مكة قبل الهجرة؛ رجاء أن يسلموا، ويهديهم الله؛ لينتفع بهم المسلمون، وكان لديه ابن أم مكتوم، فحصل من النبي ﷺ بعض الإعراض عنه مشغولًا بهؤلاء الجماعة؛ فعاتبه الله في ذلك، والأمر واضح، نعم. لا تحتاج تفسير، نعم.  المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9652/تفسير-اواىل-سورة-عبس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38126.mp3","categories":["التفسير"]},{"id":11477,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، حماة، باعث الرسالة المستمع أنور الحسين أخونا يقول: أرجو أن تتفضلوا بتفسير قول الله تعالى: الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ فَاسْأَلْ بِهِ خَبِيرًا [الفرقان:59]، جزاكم الله خيرًا.","title":"ما معنى: {ثُمَّ اسْتَوَى عَلَى الْعَرْشِ}؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. هذه الآية من آيات الصفات، فالله -جل وعلا- بين فيها، وفي غيرها أنه خالق السماوات والأرض، وما بينهما، فهو الخلاق العليم لكل شيء، لا خالق سواه، ولا رب سواه  قال تعالى: اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ [الزمر:62]، وقال سبحانه: وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا [الفرقان:2]، وقوله: ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ [الفرقان:59]، هذا وصف لنفسه بأنه استوى على العرش، وهذا في سبعة مواضع من القرآن، قال -جل وعلا- في سورة طه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، وفي سورة الأعراف: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54]. فهذه الآية العظيمة وما جاء في معناها في المواضع السبعة كلها دالة على إثبات الاستواء، وأن الله -جل وعلا- استوى على العرش استواءً يليق بجلاله، وعظمته، لا يشابه خلقه في شيء من صفاته، بل هو سبحانه له صفات خاصة تليق به على أكمل وجه، وخير وجه، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، قال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، قال : هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65]، قال سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74]. فالاستواء هو العلو والارتفاع، يعني: ارتفع فوق العرش، وعلا فوق العرش ارتفاعًا يليق بجلاله، لا يشابه خلقه في استوائهم على سطوحهم، أو على سفنهم، أو على سياراتهم، لا، استواء يليق به، وارتفاع يليق به، لا يشابه خلقه في شيء من صفاته، لكنه العلو، ولهذا يقال: استوى على السفينة، يعني: صار فوقها، استوى على السطح؛ صار فوقها، استوى على الدابة؛ صار فوقها، فالاستواء على الشيء العلو فوقه، والارتفاع فوقه، لكن استواء الرب يليق به، لا يشابه المخلوقات في استوائها. وهكذا بقية الصفات، الرحمة رحمة تليق بالله، فهو الرَّحْمَنِ الرَّحِيمِ [الفاتحة:3]، رحمته خاصة وعامة تعم المخلوقات كلهم، ورحمته خاصة بالمؤمنين تخصهم، وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا [الأحزاب:43]، إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ [التوبة:117]. فالمقصود: أن الرحمة وصف خاص غير الإرادة، بعض أهل العلم يأول يقول: الرحمن معناه: إرادة الإنعام، والرحمة إرادة الإنعام، هذا غلط، هذا تأويل، والصواب عند أهل السنة أن الرحمة غير الإرادة، الإرادة صفة مستقلة، له سبحانه إرادتان: قدرية، وشرعية.  فالقدرية مثل قوله -جل وعلا-: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]  ومثل قوله -جل وعلا-: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ [الأنعام:125]. وهناك شرعية مثل قوله -جل وعلا-: يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ الَّذِينَ مِنْ قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ [النساء:26] إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا [الأحزاب:33] هذه إرادة شرعية، يعني: أراد الله شرعًا أن يطهر أهل بيت النبي ﷺ وأراد شرعًا أن يبين للناس أحكام دينهم، ويفهمهم إياه، لكن من الناس من يفهم ويتعلم، ومن الناس من يعرض، ليس كلهم مهتدين. أما الإرادة القدرية فهي نافذة، لا يمنعها شيء، كما قال : إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]، هذه إرادة قدرية نافذة، وهكذا قوله جل وعلا: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ [الأنعام:125]، هذه إرادة كونية، إذا أراد الله هداية العبد إرادة كونية؛ شرح صدره للإسلام ومن عليه بالقبول حتى يهتدي. وهكذا الغضب صفة خاصة تليق بالله، بعض العلماء يقول: إرادة الانتقام، وهذا غلط، الإرادة غير الانتقام، الإرادة شيء، والغضب شيء آخر، والغضب يوصف الله به كما قال -جل وعلا-: وَغَضِبَ اللَّهُ عَلَيْهِ [النساء:93] يعني: قاتل النفس. فالمقصود: أن الغضب وصف لله، يغضب على أعدائه غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:7]، من اليهود والنصارى والكفرة مغضوب عليهم، غضب الله وصف يليق بالله، لا يشابه الخلق فيه، كالرضا وكالرحمة وكإلارادة وغير ذلك صفة مستقلة، فهو رحيم بالمؤمنين، رحيم بالناس، ويغضب على من عصاه، وخالف أمره، وغضبه يليق به، لا يشابه غضب المخلوقين، كما أن رضاه لا يشابه رضا المخلوقين، وهكذا استواءه، وهكذا محبته، وهكذا رحمته، كلها صفات حق، لا تشابه صفات المخلوقين عند أهل السنة والجماعة؛ لأن الله سبحانه يقول: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، هو سبحانه الرحمن، وهو الرحيم موصوفًا بالرحمة، صفة تليق بالله، لا يشابه فيها خلقه -جل وعلا- يغضب على من عصاه غضبًا يليق بالله، لا يشابه خلقه في غضبهم.  وهكذا إرادته، وهكذا يده، وهكذا سمعه، وبصره، كلها صفات تليق بالله، لا يشابه خلقه في شيء من صفاته -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم. من الأسئلة التي يسألها أخونا حول هذه الآية الكريمة سؤال يقول: هل الأيام المذكورة في هذه الآية الكريمة هي كأيامنا، أم أن اليوم بألف سنة كما في بعض الآيات الكريمة؟ الشيخ: الله أعلم، لكن ظاهر إطلاق الرب -جل وعلا- أنها كأيامنا، يعني: أطلق بالنسبة للستة الأيام، ويحتمل أنها كل يوم بألف كما قال -جل وعلا-: وَإِنَّ يَوْمًا عِنْدَ رَبِّكَ كَأَلْفِ سَنَةٍ مِمَّا تَعُدُّونَ [الحج:47]، لكن إطلاقه الآيات في هذا يدل على أنها كأيامنا، وهو سبحانه قادر أن يخلق كل شيء في لحظة، كن فيكون، لكنه -جل وعلا- خلقها في أيام؛ ليعلم عباده تنظيم أمورهم، وتنظيم أعمالهم حتى لا يعجلوا، فهو  قادر على أن يخلقها في لحظة، ومع هذا خلقها في ستة أيام، وهو قادر على أن يخلقها في أقل من ذلك -جل وعلا- لتعليم عباده وتوجيههم إلى العناية بالأمور، وعدم العجلة في الأمور؛ حتى يوقعوا الأشياء، ويوجدوها على الوجه الذي يليق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9655/ما-معنى-ثم-استوى-على-العرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38201.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":11480,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، حماة، باعث الرسالة المستمع أنور الحسين أخونا يقول: أرجو أن تتفضلوا بتفسير قول الله تعالى: الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ فَاسْأَلْ بِهِ خَبِيرًا [الفرقان:59]، جزاكم الله خيرًا.","title":"ما معنى: {ثُمَّ اسْتَوَى عَلَى الْعَرْشِ}؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. هذه الآية من آيات الصفات، فالله -جل وعلا- بين فيها، وفي غيرها أنه خالق السماوات والأرض، وما بينهما، فهو الخلاق العليم لكل شيء، لا خالق سواه، ولا رب سواه  قال تعالى: اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ [الزمر:62]، وقال سبحانه: وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا [الفرقان:2]، وقوله: ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ [الفرقان:59]، هذا وصف لنفسه بأنه استوى على العرش، وهذا في سبعة مواضع من القرآن، قال -جل وعلا- في سورة طه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، وفي سورة الأعراف: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54]. فهذه الآية العظيمة وما جاء في معناها في المواضع السبعة كلها دالة على إثبات الاستواء، وأن الله -جل وعلا- استوى على العرش استواءً يليق بجلاله، وعظمته، لا يشابه خلقه في شيء من صفاته، بل هو سبحانه له صفات خاصة تليق به على أكمل وجه، وخير وجه، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، قال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، قال : هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65]، قال سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74]. فالاستواء هو العلو والارتفاع، يعني: ارتفع فوق العرش، وعلا فوق العرش ارتفاعًا يليق بجلاله، لا يشابه خلقه في استوائهم على سطوحهم، أو على سفنهم، أو على سياراتهم، لا، استواء يليق به، وارتفاع يليق به، لا يشابه خلقه في شيء من صفاته، لكنه العلو، ولهذا يقال: استوى على السفينة، يعني: صار فوقها، استوى على السطح؛ صار فوقها، استوى على الدابة؛ صار فوقها، فالاستواء على الشيء العلو فوقه، والارتفاع فوقه، لكن استواء الرب يليق به، لا يشابه المخلوقات في استوائها. وهكذا بقية الصفات، الرحمة رحمة تليق بالله، فهو الرَّحْمَنِ الرَّحِيمِ [الفاتحة:3]، رحمته خاصة وعامة تعم المخلوقات كلهم، ورحمته خاصة بالمؤمنين تخصهم، وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا [الأحزاب:43]، إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ [التوبة:117]. فالمقصود: أن الرحمة وصف خاص غير الإرادة، بعض أهل العلم يأول يقول: الرحمن معناه: إرادة الإنعام، والرحمة إرادة الإنعام، هذا غلط، هذا تأويل، والصواب عند أهل السنة أن الرحمة غير الإرادة، الإرادة صفة مستقلة، له سبحانه إرادتان: قدرية، وشرعية.  فالقدرية مثل قوله -جل وعلا-: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]  ومثل قوله -جل وعلا-: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ [الأنعام:125]. وهناك شرعية مثل قوله -جل وعلا-: يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ الَّذِينَ مِنْ قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ [النساء:26] إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا [الأحزاب:33] هذه إرادة شرعية، يعني: أراد الله شرعًا أن يطهر أهل بيت النبي ﷺ وأراد شرعًا أن يبين للناس أحكام دينهم، ويفهمهم إياه، لكن من الناس من يفهم ويتعلم، ومن الناس من يعرض، ليس كلهم مهتدين. أما الإرادة القدرية فهي نافذة، لا يمنعها شيء، كما قال : إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]، هذه إرادة قدرية نافذة، وهكذا قوله جل وعلا: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ [الأنعام:125]، هذه إرادة كونية، إذا أراد الله هداية العبد إرادة كونية؛ شرح صدره للإسلام ومن عليه بالقبول حتى يهتدي. وهكذا الغضب صفة خاصة تليق بالله، بعض العلماء يقول: إرادة الانتقام، وهذا غلط، الإرادة غير الانتقام، الإرادة شيء، والغضب شيء آخر، والغضب يوصف الله به كما قال -جل وعلا-: وَغَضِبَ اللَّهُ عَلَيْهِ [النساء:93] يعني: قاتل النفس. فالمقصود: أن الغضب وصف لله، يغضب على أعدائه غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:7]، من اليهود والنصارى والكفرة مغضوب عليهم، غضب الله وصف يليق بالله، لا يشابه الخلق فيه، كالرضا وكالرحمة وكإلارادة وغير ذلك صفة مستقلة، فهو رحيم بالمؤمنين، رحيم بالناس، ويغضب على من عصاه، وخالف أمره، وغضبه يليق به، لا يشابه غضب المخلوقين، كما أن رضاه لا يشابه رضا المخلوقين، وهكذا استواءه، وهكذا محبته، وهكذا رحمته، كلها صفات حق، لا تشابه صفات المخلوقين عند أهل السنة والجماعة؛ لأن الله سبحانه يقول: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، هو سبحانه الرحمن، وهو الرحيم موصوفًا بالرحمة، صفة تليق بالله، لا يشابه فيها خلقه -جل وعلا- يغضب على من عصاه غضبًا يليق بالله، لا يشابه خلقه في غضبهم.  وهكذا إرادته، وهكذا يده، وهكذا سمعه، وبصره، كلها صفات تليق بالله، لا يشابه خلقه في شيء من صفاته -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم. من الأسئلة التي يسألها أخونا حول هذه الآية الكريمة سؤال يقول: هل الأيام المذكورة في هذه الآية الكريمة هي كأيامنا، أم أن اليوم بألف سنة كما في بعض الآيات الكريمة؟ الشيخ: الله أعلم، لكن ظاهر إطلاق الرب -جل وعلا- أنها كأيامنا، يعني: أطلق بالنسبة للستة الأيام، ويحتمل أنها كل يوم بألف كما قال -جل وعلا-: وَإِنَّ يَوْمًا عِنْدَ رَبِّكَ كَأَلْفِ سَنَةٍ مِمَّا تَعُدُّونَ [الحج:47]، لكن إطلاقه الآيات في هذا يدل على أنها كأيامنا، وهو سبحانه قادر أن يخلق كل شيء في لحظة، كن فيكون، لكنه -جل وعلا- خلقها في أيام؛ ليعلم عباده تنظيم أمورهم، وتنظيم أعمالهم حتى لا يعجلوا، فهو  قادر على أن يخلقها في لحظة، ومع هذا خلقها في ستة أيام، وهو قادر على أن يخلقها في أقل من ذلك -جل وعلا- لتعليم عباده وتوجيههم إلى العناية بالأمور، وعدم العجلة في الأمور؛ حتى يوقعوا الأشياء، ويوجدوها على الوجه الذي يليق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9655/ما-معنى-ثم-استوى-على-العرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38201.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":11519,"question":"تسأل أختنا عن هاروت وماروت وعن قصتهما إذا أمكن؟ جزاكم الله خيرًا.","title":"حقيقة هاروت وماروت","answer":"الجواب:  المعروف عند العلماء أنهما ملكان أنزلا ليعلمان الناس السحر، بعد البيان والإيضاح، فهما ملكان هذا المشهور، ويعلمان الناس السحر، لكن ينذرانهم، ويخبرانهم أنه لا يجوز هذا التعلم، هذا فيما ذكر جمع من المفسرين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9701/حقيقة-هاروت-وماروت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38417.mp3","categories":["التفسير"]},{"id":11532,"question":"بعد هذا رسالة بعث بها المستمع: عبدالقادر عمر عيدروس من جدة يقول: صومالي. أستفسر عن تفسير قول الحق -تبارك وتعالى-: يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105]؟","title":"ما معنى: {لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ}؟","answer":"الجواب:  معنى الآية: أن على المؤمن أن يجاهد نفسه، وأن يتقي الله، فيطيع أوامره، وينتهي عن نواهيه، ولا يضره من ضل إذا اهتدى هو واستقام على أمر الله، ومن ذلك أن يأمر بالمعروف، وينهى عن المنكر، ويدعو إلى الله، ويقوم بالواجب الذي عليه لأهل بيته من نصيحتهم، وتوجيههم، وأمرهم، ونهيهم؛ لأنه لا تتم الهداية إلا بهذا، الله يقول: إِذَا اهْتَدَيْتُمْ [المائدة:105]، فلا تتم الهداية إلا بقيامه بما أوجب الله عليه، وقد يظن بعض الناس أن معناه: أنه لا يضره من عصى وكفر ولو أنه جالسه أو آكله، أو لم يضره إن لم ينهه، لا، هذا يضره، فالواجب عليه أن يأمر بالمعروف، وينهى عن المنكر، ويرشد إلى الخير حتى يكون مهتديًا، وقد خطب الصديق  لما تولى الخلافة؛ خطب الناس، وقرأ لهم هذه الآية، وقال: أيها الناس إنكم تقرؤون هذه الآية، وتضعونها في غير موضعها، وإني سمعت النبي يقول ﷺ يقول: إن الناس إذا رأوا المنكر، فلم يغيروه؛ أوشك أن يعمهم الله بعقابه. فالمعنى: أن على المؤمن أن يأمر بالمعروف، وينهى عن المنكر، ولا يقل: أنا سالم، ولم أفعل المنكر، لا. لابد ينهى أخاه عن المنكر، لابد يأمره بالمعروف، ولا تتم الهداية إلا بهذا، وإلا فقد يضر نفسه لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ وهو إذا لم يأمر بالمعروف، ولم ينه عن المنكر، لا تحصل له الهداية الكاملة، يكون ناقص الهداية حتى يؤدي الواجب الذي عليه من جهة الأمر بالمعروف والنهي عن المنكر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9711/ما-معنى-لا-يضركم-من-ضل-اذا-اهتديتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38507.mp3","categories":["التفسير"]},{"id":11541,"question":"قال الله تعالى: يس ۝ وَالْقُرْآنِ الْحَكِيمِ ۝ إِنَّكَ لَمِنَ الْمُرْسَلِينَ [يس:1-3]، فسروا لنا هذه الآية، جزاكم الله خيرًا؟","title":"تفسر آيات من أول سورة يس","answer":"الجواب:  (يس): هذه من جملة الحروف المقطعة التي ابتدأ الله بها سبحانه جملة من السور مثل: (الم - الر- المص- حم - عسق) هذه حروف مقطعة، الصواب فيها عند أهل العلم أنها لا يعرف معناها بالتعيين، ولله فيها الحكمة البالغة . وقال بعضهم: إن الله جعلها مفتاحًا للسور، كما جعل (الحمد لله) مفتاحًا للفاتحة، ومفتاحًا لسورة سبأ ولسورة فاطر، وجعل  (سبحان) مفتاحًا لسورة بني إسرائيل، هو  الحكيم العليم، جل وعلا. أما قوله: (والقرآن الحكيم) فهذا قسم من الله، حلف، بالقرآن كما في سورة ص وَالْقُرْآنِ ذِي الذِّكْرِ [ص:1]. يقسم سبحانه أن محمد من المرسلين -عليه الصلاة والسلام- (إنك لمن المرسلين) يقسم، ويحلف -جل وعلا- أن نبيه محمد ﷺ من المرسلين، كما قال -جل وعلا-: وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ [آل عمران:144]، وقال سبحانه في سورة محمد: مُحَمَّدٌ رَسُولُ اللَّهِ [الفتح:29] فهو رسول الله، كما أخبر الله في كتابه، وأقسم عليه  وهو رسول الله بإجماع المسلمين، بإجماع أهل العلم والإيمان من أهل السنة والجماعة، هو رسول الله حقًا، من كذب بذلك؛ فهو كافر، ومن قال: إنه رسول للعرب دون العجم؛ فهو كافر، هو رسول الله إلى جميع الثقلين الجن والإنس، كما قال تعالى: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا [الأعراف:158]، قال تعالى: وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا [سبأ:28].  فهو رسول الله إلى العرب والعجم والذكور والإناث والحكام والمحكومين والملوك والرؤساء والجن والإنس، هو رسول الله إلى الجميع -عليه الصلاة والسلام- من أجاب دعوته، واتبع شريعته؛ فاز بالسعادة والجنة والكرامة، ومن حاد عن سبيله، واتبع غير هداه باء بالخيبة والندامة وصار من أهل النار يوم القيامة، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9724/تفسر-ايات-من-اول-سورة-يس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29508.mp3","categories":["التفسير"]},{"id":11545,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع أحمد صالح عبدالله مظفر -فيما يبدو- يمني الجنسية وهو من ذمار، أخونا يسأل عن تفسير قول الحق -تبارك وتعالى- أعوذ بالله من الشيطان الرجيم: فَمَنِ اتَّبَعَ هُدَايَ فَلا يَضِلُّ وَلا يَشْقَى ۝ وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنكًا [طه:123-124]، صدق الله العظيم، تفضلوا سماحة الشيخ بتفسير هذه الآيات لهذا المستمع، جزاكم الله خيرًا.","title":"ما معنى: {فَمَنِ اتَّبَعَ هُدَايَ فَلا يَضِلُّ وَلا يَشْقَى}؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد ذكر علماء التفسير عند هذه الآية ما يشرح معناها ويوضح معناها، قال الله -جل وعلا- في كتابه العظيم في سورة طه: قَالَ اهْبِطَا مِنْهَا جَمِيعًا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُمْ مِنِّي هُدًى فَمَنِ اتَّبَعَ هُدَايَ فَلا يَضِلُّ وَلا يَشْقَى  ۝ وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنكًا وَنَحْشُرُهُ يَوْمَ الْقِيَامَةِ أَعْمَى [طه: 123- 124]. قال ابن عباس -رضي الله تعالى عنهما- في الآية: تكفل الله لمن اتبع هدى الله أن لا يضل في الدنيا، ولا يشقى في الآخرة، والمعنى: أن من اتبع الهدى، واستقام على الحق الذي بعث الله به نبيه محمد -عليه الصلاة والسلام- فإنه لا يضل في الدنيا، بل يكون مهتديًا مستقيمًا، ولا يشقى في الآخرة، بل له الجنة والكرامة، وهدى الله هو ما دل عليه كتابه العظيم القرآن وسنة نبيه -عليه الصلاة والسلام- من فعل الأوامر، وترك النواهي، وتصديق الأخبار التي أخبر الله بها ورسوله، والإقامة عند حدود الله، وعدم تجاوزها، هذا هو الهدى. فاتباع الهدى هو تصديق الأخبار، وطاعة الأوامر، وترك النواهي، والوقوف عند حدود الله، فلا يتعدى ما حد الله له، ولا يقع في محارم الله  من استقام على هذا؛ طاعة لله، وإخلاصًا له، ومحبة له، وتعظيمًا له، وإيمانًا به وبرسله، فإنه لا يضل في الدنيا، بل هو على الهدى، ولا يشقى في الآخرة، بل هو سعيد في الدنيا والآخرة. ومن أعرض عن ذكر الله يعني: عن كتابه، وسنة نبيه -عليه الصلاة والسلام- ولم يتبع الهدى؛ فإن له معيشة ضنكًا، والله -جل وعلا- يبتليه بالمعيشة الضنك، وهي ما يقع في قلبه من القلق والضيق والحرج، ولو أعطي الدنيا كلها، فإنما يقع في قلبه من الضيق والحرج والشك والريب، هو العيشة الضنك، وهذا من العقاب المعجل، وله يوم القيامة العذاب الأليم في دار الهوان، في دار الجحيم، ومع هذا يحشره الله أعمى يوم القيامة. فعلى العبد أن يحذر معصية الله، وأن ينقاد لشرع الله، وأن يستقيم على هداه، الذي جاء به كتابه الكريم، وسنة رسوله الأمين، وأن يستقيم على الحق أينما كان، فهذا هو اتباع الهدى، والله سبحانه هو الموفق لعباده، فعلى المسلم والمسلمة الضراعة إلى الله، كل مؤمن ومؤمنة يضرع إلى الله، يسأله سبحانه التوفيق والهداية، ويجتهد في التفقه في الدين، والتعلم والتبصر، فيتدبر كتاب الله، ويكثر من تلاوته حتى يستقيم على الأوامر، وينتهي عن النواهي، وحتى يصدق أخبار الله عما كان وما يكون، وهكذا يعتني بالسنة، سنة الرسول ﷺ حفظًا ودراسة ومذاكرة مع العلماء وطلبة العلم حتى يستقيم على الحق، ويسأل عما أشكل عليه، الذي لا يعلم يسأل أهل العلم، ويتبصر ويتفقه حتى يستقيم على هدى، وحتى يكون سيره إلى الله عن علم بما قاله الله ورسوله، إما بطلبه للعلم واجتهاده في الخير، وإما بسؤاله أهل العلم، كما قال الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]. ومن صدق في الطلب والضراعة إلى الله، واجتهد في ذلك، وأخلص لله قصده، وابتعد عن مساخط الله، وجالس العلماء، وسألهم عما يجهله من دينه، فالله سبحانه يعينه ويوفقه، كما قال : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] .. وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِِ يُسْرًا [الطلاق:4] قال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَتَّقُوا اللَّهَ يَجْعَلْ لَكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّئَاتِكُمْ وَيَغْفِرْ لَكُمْ [الأنفال:29] والفرقان: هو الهدى والنور. فمن اتقى الله، واجتهد في طلب العلم، وسأل عما أشكل عليه، وأخلص لله في ذلك؛ فالله سبحانه يجعل له فرقانًا يعطيه العلم، ويوفقه، ويهديه سبحانه، فضلًا منه وإحسانًا -جل وعلا- هذا شأنه -جل وعلا- مع أوليائه، وأهل طاعته، والصادقين في محبته، واتباع ما يرضيه سبحانه، هو أهل الجود والفضل يهديهم ويعينهم ويوفقهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9728/ما-معنى-فمن-اتبع-هداي-فلا-يضل-ولا-يشقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_296/29601.mp3","categories":["التفسير"]},{"id":11579,"question":"أيضًا يطلب رأي سماحتكم في تفسير القرطبي؟","title":"تقييم تفسير الإمام القرطبي","answer":"الجواب:  كذلك تفسير القرطبي، تفسير مفيد وجيد، ولكن مثل غيره، يؤخذ من قوله ويترك، ما خالف الدليل يترك، من كلام القرطبي أو ابن جرير أو ابن كثير أو غيرهم، كل مفسر قد يقع له بعض الأخطاء، قد يصحح بعض الأحاديث الضعيفة، قد يضعف بعض الأحاديث الصحيحة، إما لكونه تكلم من حفظه فغلط، أو لأنه نسي ما سبق له أن علمه في شأن هذا الحديث، أو شأن هذا الحكم، فأهل العلم يعرضون ما ذكره علماء التفسير وغيرهم على الكتاب والسنة، فما وافق الحق قبل من القرطبي وغيره، وما خالفه رد، وليس بمعصوم لا هو، ولا غيره من أهل العلم من أهل التفسير وغيرهم، ولكن كتابه مفيد جدًا، كثير الفائدة، قد عني فيه بالأدلة والأحكام، وهو كتاب مفيد جدًا، وهو مفسر ملهم موفق، لكنه ليس بمعصوم، كل يؤخذ من قوله ويترك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9762/تقييم-تفسير-الامام-القرطبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29803.mp3","categories":["التفسير"]},{"id":11595,"question":"بعد هذا رسالة بعث بها المستمع: حامد موسى علي يسأل تفسير قول الحق -تبارك وتعالى-: لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَدْخُلُوا بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَاعٌ لَكُمْ [النور:29] وهل المقصود الدخول فقط، أم الدخول والإقامة؟ جزاكم الله خيرًا.","title":"تفسير قوله تعالى:( لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَدْخُلُوا...)","answer":"الجواب:  هذا نص الآية ليس عليهم بأس في الدخول لأخذ متاعهم، إذا صار فيها متاع لهم: سيارة يأخذها، أثاث يأخذه لا بأس؛ لأن هذا شيء لا يضر السكن يفرغه لأهله. أما أن يقيم بها فهذا فيه تفصيل: إن كانت مسموحًا بها للناس يسكنوا فيها؛ فلا بأس أن يسكن بها، يكون صاحبها طالبًا الأجر، كالمساكن التي توقف على عابر السبيل. أما إذا كان صاحب السكن لم يأذن به للناس، ولم يجعله سبيلًا للناس، بل ترك سكنه لعارض من العوارض؛ فلا يسكن إلا بإذنه، لكن إذا كان فيه متاع لك تدخل تأخذه لا بأس، تأخذ متاعك من سيارة، أو فراش، أو غير ذلك، وأما السكن فيه فلابد من الاستئذان، إلا أن يكون قد أعد لحاجة الناس، وتبرع به صاحبه لحاجة الناس وقفًا؛ فلا بأس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9787/تفسير-قوله-تعالى-ليس-عليكم-جناح-ان-تدخلوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38713.mp3","categories":["التفسير"]},{"id":11642,"question":"المستمع أبو بكر من جدة بعث يسأل سماحتكم ويقول: أرجو أن تتفضلوا بتفسير قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ [المائدة:101]؟","title":"ما معنى: {لا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ}؟","answer":"الجواب:  هذه الآية الكريمة وجه الله بها الصحابة  أن يسألوا النبي ﷺ عن أشياء إن تبد لهم تسؤهم، قال: بل عليهم أن ينتظروا حتى ينزل القرآن، إلا إذا نزل بهم نازلة، أو أشكل عليهم شيء من أحكام الله يسألون، أما التعنت والسؤال عن أشياء ليس لهم بها حاجة، ولم تنزل عليهم، فهم نصحوا ألا يسألوا، ولكن يسأل الإنسان عما أهمه، وعما نزل به حتى يعرف الحق من الباطل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، سماحة الشيخ! الذين يصرفون معنى هذه الآية الكريمة إلى الفتوى هل هم على حق؟ الشيخ: لا ليس بصواب، الإنسان يسأل عما أشكل عليه، يجب عليه.. الله قال: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] لكن كونه يسأل عن أشياء لا دخل له فيها، أو يبحث عن عيوب الناس، وإن تبد له تسؤهم، هذا معروف، منهي عن هذا الشيء؛ لأن هذا قد يفضي إلى معرفة عورات الناس، وتتبع عوراتهم، وهذا لا يجوز، الرسول  يقول: لا تتبع عورات أخيك ونهى عن اتباع العورات، وقال: إنك إن تتبع عورات المسلمين؛ تفسدهم. فالحاصل أنه لا ينبغي للإنسان أن يتتبع عورات أخيه، بل يحذر السؤال عما ليس له فيه شأن: من حسن إسلام المرء تركه ما لا يعنيه فليس له أن يسأل عن أشياء قد تسؤه وتضره، كيف حال فلان من جهة كذا يسأل عن هل هو يتعاطى كذا الزنا؟ هل هو يتعاطى كذا؟ هل هو يتعاطى كذا؟ هل هو يشرب الخمر؟ ما دام ظاهره الخير؛ يترك، ولا يتعرض له، نعم. المقصود التنقيب عن أحوال الناس؛ ليعرف عوراتهم، وهذا لا يجوز. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9816/ما-معنى-لا-تسالوا-عن-اشياء-ان-تبد-لكم-تسوكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38903.mp3","categories":["التفسير"]},{"id":11730,"question":"كذلك قوله سبحانه: وَكَفَى بِاللَّهِ حَسِيبًا [النساء:6] وَكَفَى بِاللَّهِ شَهِيدًا [النساء:79] فَمَا لَهُ مِنْ قُوَّةٍ وَلا نَاصِرٍ [الطارق:10]، اشرحوا لي هذه الأجزاء من الآيات الكريمة؟ جزاكم الله خيرًا.","title":"ما معنى: {وَكَفَى بِاللَّهِ حَسِيبًا}، {وَكَفَى بِاللَّهِ شَهِيدًا}؟","answer":"الجواب:  هذا معناه ظاهر وَكَفَى بِاللَّهِ حَسِيبًا [النساء:6]، وَكَفَى بِاللَّهِ وَكِيلًا [النساء:81]، هو  الحسيب بعباده، والوكيل عليهم، والكفيل لهم، حسبنا الله ونعم الوكيل وَكَفَى بِاللَّهِ حَسِيبًا [النساء:6] وَكَفَى بِاللَّهِ وَكِيلًا [النساء:81]  ولا يمكن أن يخرج عن قدرته وعزته أحد  والله  إذا أراد شيئًا لا يمنعه أحد، بل قدره نافذ سبحانه في عباده صالحهم وطالحهم، فهو -جل وعلا- المتصرف في عباده كيف يشاء، لا راد لقضائه، ولا غالب لأمره  وهو على كل شيء قدير، نعم. المقدم: جزاكم الله خيرًا، وهل تعتبر تلك الكلمات (شهيدًا) و(حسيبًا) و(ناصر) من صفات الله ؟ الشيخ: هو الشهيد على عباده إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ شَهِيدٌ [الحج:17]، يعلم أحوالهم، ويشهدها، وهو حسيب عليهم، كفيل لهم -جل وعلا- حسبنا الله ونعم الوكيل، هو الكفيل، وهو الحسيب -جل وعلا- وهو الناصر نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ [الأنفال:40]  من نصره الله فهو المنصور، ومن خذله الله فهو المخذول، لا يجد الناس لهم من دون الله من ولي ولا نصير، ولهذا يقول -جل وعلا-: إِنْ يَنْصُرْكُمُ اللَّهُ فَلا غَالِبَ لَكُمْ وَإِنْ يَخْذُلْكُمْ فَمَنْ ذَا الَّذِي يَنْصُرُكُمْ مِنْ بَعْدِهِ [آل عمران:160] فالله -جل وعلا- بيده النصر، وبيده الخذلان، وبيده العطاء، وبيده المنع، وبيده الحياة، وبيده الموت، فهو سبحانه المالك لكل شيء، والمتصرف في عباده بما يشاء . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9913/ما-معنى-وكفى-بالله-حسيبا-وكفى-بالله-شهيدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42111.mp3","categories":["التفسير"]},{"id":11948,"question":"أرجو أن تبينوا لي: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22]؟","title":"معنى قوله تعالى: (وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ)","answer":"الجواب:  يقول الله -جل وعلا-: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ إِلَّا مَا قَدْ سَلَفَ [النساء:22] كانوا في الجاهلية يتساهلون في هذا، فأنزل الله  النهي عن ذلك، فليس للإنسان أن ينكح زوجة أبيه، ولا زوجة جده المطلقة، أو التي مات عنها، سواء كان الجد من جهة الأم، أو من جهة الأب، حرم الله نكاح زوجات الآباء مطلقًا من جهة الأب، أو من جهة الأم، سواء كن مطلقات، أو مات عنهن أزواجهن، فهن محارم لأولاد أزواجهن، وأولاد أولادهم، وإن نزلوا، نعم، من الرضاع والنسب جميعًا، من النسب والرضاع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10133/معنى-قوله-تعالى-ولا-تنكحوا-ما-نكح-اباوكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42812.mp3","categories":["التفسير"]},{"id":12128,"question":"أرجو تفسير قول الحق -تبارك وتعالى-: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ [النساء:3].. الآية؟","title":"ما معنى: {فَانكِحُوا مَا طَابَ لَكُم مِنَ النِّسَاءِ}؟","answer":"الجواب:  معناها أن الرجل يشرع له نكاح اليتيمة التي عنده إذا كانت مناسبة له، ويعطيها مهرها الواجب وينكحها بالوجه الشرعي، كبنت عمه اليتيمة عنده، أو بنت خاله اليتيمة، يشرع له أن يتزوجها إذا رغبت فيه، إذا وافقت على ذلك، وعليه أن يعطيها المهر المعتاد وألا يظلمها، فإن خاف ألا يقوم بالواجب وألا يقسط في حقها؛ لأنها تحت يده فليزوجها غيره، وليتزوج من سواها حتى لا يظلمها، إما أن يعطيها حقها كاملًا إذا رضيت به، وإما أن يزوجها غيره، ولا يتساهل يقول: هذه يتيمتي ويكفيها نصف المهر، لا، ما يصلح، قد تستحي ولا تطلب، لكن ينصفها، يعطيها حقها كاملًا، وإلا فليزوجها غيره، فإذا لم يتزوجها؛ يلتمس سواها النساء كثير، وله السعة في هذا إن شاء تزوج ثنتين، إن شاء تزوج ثلاث، وإن شاء تزوج أربع. وهذه الآية تعطي أن نكاح الثنتين والثلاث والأربع أفضل؛ لأن الله قال: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ [النساء:3] ما قال: فانكحوا واحدة، قال: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ [النساء:3]، فدل على أنه يختار ويتأمل، يتزوج ثنتين، يتزوج ثلاثًا، يتزوج أربعًا؛ لأن في ذلك إعفافًا له، وإعفافًا لهن أيضًا، وفي ذلك أيضًا طلب الولد، فإن وجود زوجتين، أو ثلاث، أو أربع في الغالب يكون أكثر للأولاد وأكثر للأمة، مع إعفافه نفسه، ومع إعفافه هؤلاء النسوة ثنتين أو ثلاثًا أو أربعًا، فيه مصالح كثيرة، تزوج بثنتين، أو ثلاثً أو أربعً فيه مصالح كثيرة. فلا ينبغي للمرأة العاقل، ما ينبغي للمؤمنة أن تأبى ذلك، ولا أن تكره ذلك والحمد لله، إذا عدل فيها وأدى الواجب؛ فالحمد لله، أما إذا جار وظلم؛ لها الحق أن تأبى، وأن تطلب العدل، ولهذا قال سبحانه: فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3]، إذا خاف ألا يقوم بالواجب؛ يكتفي بواحدة، والحمد لله. أما إذا كان عنده قدرة في بدنه، وفي ماله يستطيع أن يقوم بالثنتين أو بالثلاث أو بالأربع فالسنة له أن يعدد، وأن يصبر، ويقوم بالواجب، كما فعله النبي ﷺ فإنه عدد -عليه الصلاة والسلام- تزوج في المدينة تسعًا، جمع بين تسع، وفي مكة خديجة وحدها، ثم تزوج بعدها سودة، وعائشة، ثم في المدينة تزوج بقية نسائه حتى بلغن تسعًا، والله يقول: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]. لكن الأمة تقصر على أربع، الرسول ﷺ قصر الأمة على أربع، وأمر من كانت عنده خامسة، أو أكثر أن يفارق الزائدة، لما أسلموا، أمرهم أن يمسكوا أربعًا، وأن يفارقوا ما زاد على أربع، فاستقرت الشريعة على أن الرجل من الأمة له أن يجمع أربعًا فأقل، أما التسع؛ فهذا خاص بالنبي -عليه الصلاة والسلام- ليس للأمة بل هذا من خصائص النبي عليه الصلاة والسلام. وإذا خاف الرجل ألا يعدل؛ اكتفى بواحدة، وإذا تزوج ثنتين، أو ثلاثًا، أو أربعًا؛ فالواجب عليه العدل في القسمة والنفقة وما يستطيع من العشرة الطيبة، والكلام الطيب، وحسن البشر، وطيب الكلام، يعدل في ذلك، وأما المحبة فهذا إلى الله، ليس في قدرته أن تكون المحبة سواء، وهكذا الجماع ليس في قدرته ذلك، فإن الجماع تبع المحبة وتبع الشهوة، فيجتهد في العدل مهما أمكن، ويعفو الله عما عجز عنه، في الحديث الصحيح يقول ﷺ: كان يقسم بين نسائه ويعدل.. كان يقسم ﷺ بين نسائه ويعدل، ويقول: اللهم هذا قسمي فيما أملك فلا تلمني فيما تملك ولا أملك. فالمؤمن يقسم ويعدل حسب الطاقة يسوي بينهن في قسمته وفي وجهه وكلامه، وبشره لهن ومعاشرتهن الطيبة، أما المحبة؛ فهذا بيد الله، ليس بيده هو، قد تكون هذه أحب من هذه، ولكن لا يجوز أن يحمله على الجور. وهكذا الشهوة قد يشتهي هذه للجماع أكثر؛ فلا يضره هذا؛ لأن هذا ليس باختياره، وليس في قدرته، بل هذا يتبع المحبة والشهوة، إنما الواجب العدل في القسمة هذه ليلة، وهذه لها ليلة، هذه لها يوم، وهذه لها يوم، ينفق على هذه ما يليق بها، وهذه ما يليق بها وأولادها، كل على حسب حالته، هذه عندها ولدان، هذه عندها ثلاثة، عندها أربعة، هذه ثوبها طويل، وهذه طويلة، وهذه قصيرة، كل واحدة لها كفايتها، نعم، وكفاية أولادها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10313/ما-معنى-فانكحوا-ما-طاب-لكم-من-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43813.mp3","categories":["التفسير"]},{"id":12149,"question":"يسأل أيضًا أخونا من جنوب الهند أحمد علي عن أفضل كتب التفسير التي تنصحونه باقتنائها؟ جزاكم الله خيرًا.","title":"أفضل كتب في التفسير","answer":"الجواب:  أفضلها تفسير ابن جرير ، وتفسير ابن كثير .. تفسير البغوي، هذه تفاسير عظيمة مهمة مفيدة عظيمة، ومن التفاسير الطيبة: تفسير القرطبي ، تفسير الشوكاني، فيها خير كثير، ولكن لابد من بعض الأشياء التي قد تنتقد، فالإنسان يحذر ما فيه خطأ، ويسأل أهل العلم عما يشكل عليه. والكتب كل الكتب لا تخلو ما عدا كتاب الله  القرآن هو المعصوم المحفوظ، أما كتب الناس قد يقع فيها بعض الغلط، فالمؤمن يستفيد من الكتب الطيبة العظيمة، وإذا أشكل عليه شيء سأل أهل العلم عما أشكل عليه، سأل من هو أعلم منه عما أشكل عليه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10334/افضل-كتب-في-التفسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_440/44006.mp3","categories":["التفسير"]},{"id":12247,"question":"فسروا لنا قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ [المائدة:89] الآية، وهل كفارة اليمين يجب أن تكون بالترتيب؟","title":"ما معنى: {لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ}؟","answer":"الجواب:  الآية الكريمة فسرها أهل العلم، وبينوا معناها وهي قوله سبحانه في سورة المائدة: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ [المائدة:89]، وفي سورة البقرة: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ [البقرة:225] فما عقد عليه القلب، وكسبه القلب؛ فالعبد مؤاخذ به من الأيمان، وكفارتها كما بين الله في سورة المائدة: إِِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ [المائدة:89] هذه مخيرة ليس بها ترتيب، إن شاء كفر بالإطعام، وإن شاء كفر بالكسوة، وإن شاء كفر بالعتق هو مخير؛ لأنها أتى (بأو)  وأو للتخيير، فإن عجز عن الثلاث؛ فإنه يصوم ثلاثة أيام، إذا عجز عن الإطعام والكسوة والعتق؛ فإنه يصوم ثلاثة أيام، والأفضل أن تكون متتابعة، وهذا إذا كان عامدًا لليمين، قاصدًا لها، كاسبًا لها. أما إذا مرت على لسانه من غير قصد، ولا تعمد لليمين؛ فليس عليه فيها شيء، تعتبر لغوًا، أو حلف يظن أنه صادق، يعتقد أنه صادق، قال: والله! ما فعلت كذا، والله! لأفعلن كذا، والله لقد فعلت كذا، قال: والله! لقد فعلت كذا، يظن أنه فعله، يعتقد أنه فعله، ثم بان أنه لم يفعل؛ فليس عليه شيء، أو والله لقد رأيت فلانًا يعتقد أنه رآه، ثم تبين أنه غيره؛ فلا شيء عليه على الصحيح، وهذا من لغو اليمين؛ لأنه ما قصد الكذب، وإنما حلف يقصد صدق نفسه، يعتقد أنه صادق، فهو داخل في اليمين اللاغية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10436/ما-معنى-لا-يواخذكم-الله-باللغو-في-ايمانكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44811.mp3","categories":["التفسير"]},{"id":12285,"question":"يا أم أيمن سنعود إلى بقية أسئلتك في حلقة قادمة -إن شاء الله تعالى- أما الآن فهذه رسالة بعثت بها مستمعة من المملكة الأردنية الهاشمية، تقول عن نفسها: إنها فلسطينية الجنسية، ولاجئة اسمها وصال تيسير الأعور الأخت وصال، تسأل عددًا من الأسئلة من بينها سؤال يقول: ما معنى الأحرف التي تكون في بداية بعض السور مثل: الم [البقرة:1] و المص [الأعراف:1] إلى آخر ذلك؟","title":"معنى الحروف المقطعة التي في فواتح سور القرآن","answer":"الجواب:  هذه الأحرف اختلف علماء التفسير في معناها، والأرجح فيها: أنه لا يعلم معناها إلا الله  ولا يجوز أن يبت في معناها إلا بدليل واضح، ولكنها من آيات الله سبحانه الدالة على أن هذا القرآن العظيم المعجز العظيم الذي هو كتاب الله، مركب من هذه الحروف، التي جعلها الله فواتح للسور؛ ليدل عباده على أن هذا الكلام العظيم لهذه الحروف فيه الدلالة على كل خير، والدعوة إلى كل خير، والتحذير من كل شر، وهو من هذه الحروف المعتادة التي ينطق بها الناس، الله تكلم به سبحانه وهو كلامه جل وعلا لا يشابه كلام غيره  وهو أفضل كلام، وأصدق كلام، نعم. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10485/معنى-الحروف-المقطعة-التي-في-فواتح-سور-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45205.mp3","categories":["التفسير"]},{"id":12286,"question":"تسأل عن تفسير قول الحق -تبارك وتعالى-: وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ [الرحمن:6] هل هو النجم الذي في السماء، أم هو النجم النباتي؟","title":"تفسير قوله تعالى: (والنجم والشجر يسجدان)","answer":"الجواب:  المشهور -والله أعلم- في هذا هو نجم السماء عند الإطلاق، كما في قوله تعالى: وَالنَّجْمِ إِذَا هَوَى [النجم:1] فَلا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ [الواقعة:75] والمراد به نجوم السماء، والشجر يكفي عن النجم المسمى من الشجر نجمًا، فالنجم يسجد سجودًا يليق به، والشجر كذلك، ولا يعلم كيفية سجودهما إلا هو  لكن من علامات ذلك ذلهما، وخضوعهما لمدبرهما ، فهما مخلوقان ذليلان مدبران مسيران. أما كيفية السجود من النجم، ومن الشجر فالله هو الذي يعلمها  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10486/تفسير-قوله-تعالى-والنجم-والشجر-يسجدان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45206.mp3","categories":["التفسير"]},{"id":12427,"question":"يسأل تفسير قول الله تعالى: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ وَلا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذَا أَمِنتُمْ فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ [البقرة:196] الآية؟","title":"تفسير قوله تعالى: (وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ...)","answer":"الجواب:  الآية على ظاهرها، من دخل في الحج، أو في العمرة؛ يلزمه الإتمام، وإن كانت نافلة، فإذا أحرم الرجل، أو المرأة بالحج، أو بالعمرة فإنه يلزمهما الإتمام لقوله سبحانه: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ بخلاف النوافل الأخرى ما يلزم لو شرع في الصلاة نافلة له أن يقطعها، أو في الصوم نافلة له أن يقطعه، لكن الحج خاصة، والعمرة من شرع فيهما؛ فعليه الإتمام من الرجل والمرأة، ولو كانا نافلة، ولو كانت نافلتين: الحج نافلة، أو العمرة نافلة، متى شرع فيهما، أو في أحدهما؛ وجب الإتمام، نعم. المقدم: وبقية الآية بقية تفسير كلمات الآية؟ الشيخ: فَإِنْ أُحْصِرْتُمْ [البقرة: 196] معناه: ظاهر يعني: إذا لم يستطع الإتمام أحصر، بأن ذهبت نفقته، أو مرض، ما يستطيع يذبح، ينحر هدي شاة، أو بدنة أو بقرة، ثم يحلق رأسه، أو يقصر ويحل والحمد لله، مثل ما فعل النبي ﷺ لما أحصر في الحديبية، ومنعه الكفار أمر بالنحر والحلق نحر هديه، ثم حلق وتحلل هذا معنى: فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة: 196] يعني: فإن أحصرتم عن الحج، ومنعتم أو العمرة، فانحروا ما تيسر من الهدي: يذبح شاة، أو سبع بدنة، أوسبع بقرة، ثم يحلق رأسه، ويقصر ويحل وإن كان حج الفريضة يقضي بعد حين، إن كان قد حج فالحمد لله، وإن كان هذا حج الفريضة، أو عمرة الفريضة يأتي بها إذا تيسر له ذلك ........ المقدم: والنافلة وإذا كان نافلة؟ الشيخ: انتهت ....... ما عليه قضاء، لأن النبي ﷺ ما أمر الذين أحصروا أن يقضوا ... عمرة الحديبية، ما أمرهم أن يقضوا. المقدم: نعم، نعم، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10639/تفسير-قوله-تعالى-واتموا-الحج-والعمرة-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40308.mp3","categories":["التفسير"]},{"id":12485,"question":"يقول الله -جل وعلا- في سورة النمل: قَالَ عِفْريتٌ مِنَ الْجِنِّ أَنَا آتِيكَ بِهِ قَبْلَ أَنْ تَقُومَ مِنْ مَقَامِكَ وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمِينٌ ۝ قَالَ الَّذِي عِنْدَهُ عِلْمٌ مِنَ الْكِتَابِ أَنَا آتِيكَ بِهِ قَبْلَ أَنْ يَرْتَدَّ إِلَيْكَ طَرْفُكَ [النمل:40] من الذي عنده علم من الكتاب، أهو من الجن، أم من الملائكة؟","title":"المراد بقوله تعالى: (قَالَ الَّذِي عِنْدَهُ عِلْمٌ مِنَ الْكِتَابِ...)","answer":"الجواب:  الله أعلم، قال بعض أهل العلم: إنه شخص يقال له: آصف عند سليمان، وأن عنده معلومات، ولكن ليس هناك دليل يوضح من هو المراد، فالله أعلم بذلك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10704/المراد-بقوله-تعالى-قال-الذي-عنده-علم-من-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40615.mp3","categories":["التفسير"]},{"id":12490,"question":"يسأل سماحتكم تفسير سورة التكاثر إذا أمكن؟","title":"تفسير سورة التكاثر","answer":"الجواب:  الله يقول سبحانه محذرًا عباده من التكاثر الذي يصدهم عن الخير، ويشغلهم عن الحق، يقول سبحانه: أَلْهَاكُمُ التَّكَاثُرُ ۝ حَتَّى زُرْتُمُ الْمَقَابِرَ [التكاثر:1-2] أخبر سبحانه عن أكثر الخلق أنه ألهاهم التكاثر، يعني: في الأموال والأولاد، وغير ذلك من حظوظ الدنيا، حتى ماتوا.. حتى زاروا القبور.  والمقصود: التحذير من هذا الشيء، والترهيب، وأن تجتهدوا في طاعة الله ورسوله، وألا يشغلهم التكاثر عما يرضي الله، ويقرب لديه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10695/تفسير-سورة-التكاثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40606.mp3","categories":["التفسير"]},{"id":12503,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المرسل (س. ع) يسأل ويقول: أرجو أن تتفضلوا بتفسير قول الله تعالى : سَمَّاعُونَ لِلْكَذِبِ أَكَّالُونَ لِلسُّحْتِ فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِنْ تُعْرِضْ عَنْهُمْ فَلَنْ يَضُرُّوكَ شَيْئًا وَإِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [المائدة:42].","title":"تفسير قوله تعالى: (سَمَّاعُونَ لِلْكَذِبِ أَكَّالُونَ لِلسُّحْتِ...)","answer":"الجواب:  هذه الآية الكريمة فيها وصف جماعة من اليهود بأنهم سماعون للكذب، أكالون للسحت، يعني: يصغون إلى الكذابين، ويأخذون بقول الكذابين، ومع هذا يأكلون الحرام، السحت: هو الحرام من الربا وغيره، هذا وصف كثير من اليهود، اليهود الذين غضب الله عليهم، هذه وصفهم، قال تعالى: فَبِظُلْمٍ مِنَ الَّذِينَ هَادُوا حَرَّمْنَا عَلَيْهِمْ طَيِّبَاتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَنْ سَبِيلِ اللَّهِ كَثِيرًا ۝ وَأَخْذِهِمُ الرِّبَا وَقَدْ نُهُوا عَنْهُ وَأَكْلِهِمْ أَمْوَالَ النَّاسِ بِالْبَاطِلِ [النساء:160-161] فالسماع للكذب هو الذي يعمل بالكذب، ويصغي إليه، وينفذه، نسأل الله العافية. ومع ذلك يأكلون السحت، يعني: يأكلون الحرام، الرسول ﷺ خير إذا جاؤوه أن يحكم بينهم، أو يعرض عنهم، إذا وصلوا إليه؛ يتحاكموا، خير بين الحكم بينهم، أو تركهم، والإعراض عنهم، وإن حكم فالواجب أن يحكم بالقسط، يعني: بالحق، ثم أمره الله أن يحكم بينهم فقال: وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنزَلَ اللَّهُ [المائدة:49] فاستقر الأمر على أنهم متى جاؤوه، وتحاكموا إليه؛ فإنه يحكم بينهم بالحق، سواءً كانوا يهودًا، أو نصارى، أو غيرهم من الكفرة، إذا جاؤوا إلى الحاكم الشرعي يتنازعون فإنه يحكم بينهم بالحق، كما قال -جل وعلا-: وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنزَلَ اللَّهُ [المائدة:49].  فالواجب الحكم بينهم بالقسط، وهو الحق عملًا بالآيات الأخرى، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10711/تفسير-قوله-تعالى-سماعون-للكذب-اكالون-للسحت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40705.mp3","categories":["التفسير"]},{"id":12538,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع مستور حامد عبدالله السواط من طريق الجنوب، أخونا مستور بعث بجمع كبير من الأسئلة، في أحد أسئلته يسأل عن تفسير آية الكرسي، فلو سمحتم سماحة الشيخ تتفضلون بتفسيرها له؟","title":"تفسير آية الكرسي وفضلها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فآية الكرسي هي أعظم آية في كتاب الله بنص الرسول -عليه الصلاة والسلام- وهي قوله : اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] هذه آية الكرسي، وهي آية طويلة، وهي أعظم آية في كتاب الله، قد اشتملت على معاني عظيمة من جهة توحيد الله، وإثبات أسمائه وصفاته، وعموم علمه وقدرته -جل وعلا- فقوله سبحانه: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] هذه معنى كلمة التوحيد: لا إله إلا الله، فإن معناها: الله لا إله إلا هو، يعني: لا معبود حق إلا هو، الله لا معبود حق سواه، والإله هو المعبود، والتأله هو التعبد. فمعنى لا إله أي: لا مألوه، والمألوه معناه المعبود، أي: لا معبود حق إلا الله، وهو الحي القيوم  الحي الذي لا يموت، ولا يعتريه سنة وهي النعاس، ولا نوم وهو ما فوق النعاس، لكمال حياته، فلا نوم ولا موت ولا نعاس ولا غفلة، بل هو في غاية من العلم والقدرة والبصيرة بأحوال العباد : اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] فهو حي حياة كاملة، لا يعتريها نقص، ولا ضعف، ولا غفلة، ولا نوم، ولا نعاس، ولا موت، ولا غير ذلك من الآفات. وهو القيوم القائم على أمر عباده، والمقيم لهم سبحانه، وهو المقيم لمخلوقاته، وهو الحافظ لمخلوقاته، فلا قوام للعباد، ولا للمخلوقات إلا به  فهو الذي أقام السماوات، وأقام الأرض، وأقام كل شيء، كما قال سبحانه: وَمِنْ آيَاتِهِ أَنْ تَقُومَ السَّمَاءُ وَالأَرْضُ بِأَمْرِهِ [الروم:25] وهو المقيم للخلائق، والحافظ لها، والموجد لها، والمعدم لها؛ فهو على كل شيء قدير  ولهذا قال بعدها: لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ [البقرة:255] يعني: لا تصيبه، ولا تعتريه سنة، وهي النعاس، وهي النوم الخفيف، ولا نوم وهو النوم الثقيل، فلا يعتريه غفلة، ولا نعاس، ولا نوم، ولا موت، بل حياته كاملة . ثم قال : لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ [البقرة:255] يعني: هو المالك لكل شيء، هو المالك للسماء وما فيها، والأرض وما فيها، كما قال -جل وعلا- في آخر سورة المائدة: لِلَّهِ مُلْكُ السَّمَوَاتِ وَالأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [المائدة:120] وقال في آية أخرى لِلَّهِ مُلْكُ السَّمَوَاتِ وَالأَرْضِ [الشورى:49] فهو سبحانه المالك للسماوات والمالك للأرض، والمالك لما فيهما، والمالك لكل شيء، جل وعلا. ثم قال سبحانه: مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ [البقرة:255] أي: لا أحد يستطيع يشفع إلا بإذنه سبحانه، يعني: يوم القيامة لا يتقدم أحد يشفع حتى النبي محمد ﷺ إلا بإذنه، حتى يأذن له، وما ذاك إلا لعظم مقامه وجبروته، وكونه سبحانه المستحق لأن يعظم ويجل، وألا يتقدم بين يديه إلا بإذنه : فإذا اشتد الكرب يوم القيامة بالناس؛ فزع المؤمنون إلى أبيهم آدم؛ ليشفع لهم إلى الله حتى يقضي بينهم، فيعتذر آدم، ثم يحيلهم على نوح ، فيأتون نوحًا؛ فيعتذر -عليه الصلاة والسلام- ويقول: اذهبوا إلى إبراهيم ، فيأتون إبراهيم فيعتذر ويقول: اذهبوا إلى موسى، فيأتون موسى؛ فيعتذر، وكل واحد يقول: نفسي نفسي، فيقول لهم موسى: اذهبوا إلى عيسى ، فيأتون عيسى فيقول: نفسي نفسي، اذهبوا إلى محمد -عليه الصلاة والسلام- فيأتون محمدًا -عليه الصلاة والسلام- فيقول: أنا لها -عليه الصلاة والسلام- ثم يتقدم، فيسجد بين يدي ربه، ويحمد بمحامد عظيمه، ويثني عليه سبحانه بمحامد يفتحها عليه، ثم يقال له: يا محمد! ارفع رأسك، وقل يسمع، وسل تعط، واشفع تشفع، فعند ذلك يشفع -عليه الصلاة والسلام- في الناس أن يقضي الله بينه. فيقضي الله بين عباده بشفاعته، ثم بعد القضاء يصير أهل الجنة إلى الجنة، وأهل النار إلى النار: فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ [الشورى:7] ويوقف أهل الجنة، لا يدخلونها حتى يشفع فيهم -عليه الصلاة والسلام- فيشفع لأهل الجنة حتى يفتح لهم أبوابها بشفاعته -عليه الصلاة والسلام- أما في الدنيا فكل إنسان يدعو ربه، مأمور بالدعاء كما قال تعالى: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] كونه يدعو ربه، ويسأل ربه أن يغفر له، ويدخله الجنة، وينجيه من النار، ويطلب من إخوانه أن يدعو له، أن الله يغفر له، لا بأس بهذا، لكن يوم القيامة، لا أحد يتقدم إلا بإذنه  الأنبياء وغيرهم لا أحد يشفع إلا بإذنه : مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ [البقرة:255] قال تعالى: وَكَمْ مِنْ مَلَكٍ فِي السَّمَوَاتِ لا تُغْنِي شَفَاعَتُهُمْ شَيْئًا إِلَّا مِنْ بَعْدِ أَنْ يَأْذَنَ اللَّهُ لِمَنْ يَشَاءُ وَيَرْضَى [النجم:26]  وقال تعالى: وَلا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى [الأنبياء:28]. فالشفاعة لا تكون إلا لمن رضي الله قوله وعمله، وهم أهل التوحيد والإيمان، هم الذين يشفع فيهم الأنبياء، أما أهل الشرك فلا شفاعة لهم، كما قال تعالى: فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشَّافِعِينَ [المدثر:48] قال تعالى: مَا لِلظَّالِمِينَ مِنْ حَمِيمٍ وَلا شَفِيعٍ يُطَاعُ [غافر:18] الظالمين: يعني: المشركين، معنى الظالمين، يعني: المشركين، الظلم إذا أطلق هو الشرك: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] فمعنى قوله سبحانه: مَا لِلظَّالِمِينَ [غافر:18] يعني: ما للمشركين مِنْ حَمِيمٍ وَلا شَفِيعٍ يُطَاعُ [غافر:18] فالمشرك لا تنفعه الشفاعة، ولا يشفع فيه الرسول ﷺ ولا المؤمنون، بل ليس له إلا النار يوم القيامة -نعوذ بالله من ذلك- وإنما الشفاعة لأهل التوحيد والإيمان، ولعصاة الموحدين، أما الشفاعة في أهل الموقف فهي عامة لأهل الموقف كلهم من الكفار وغيرهم في أن يقضى بينهم، فهذه شفاعة عامة في القضاء بين الناس، يشفع فيهم النبي ﷺ للقضاء بينهم، فيقضي الله بينهم سبحانه بحكمه العدل -جل وعلا- كما تقدم. ثم قال سبحانه: يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ [البقرة:255] يعني: هو العالم بأحوال عباده، لا يخفى عليه خافية -جل وعلا- يعلم ما بين أيديهم، وما خلفهم، ما مضى، وما يأتي، ويعلم أحوال عباده الماضين والآخرين، ويعلم كل شيء : إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ [الأنفال:75] وقال تعالى: ولا يحيطون بشيء من علمه إلا بما شاء فهم لا يحيطون بشيء من علمه، إلا بما أطلعهم عليه  أما هو فهو العالم بأحوال عباده كلهم ماضيها ولاحقها، يعلم أحوالهم، وما صدر منهم، وما ماتوا عليه، وما لهم في الآخرة، يعلم كل شيء  قال تعالى: لِتَعْلَمُوا أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا [الطلاق:12] وقال سبحانه: إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ [الأنفال:75] ويقول هنا: يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ [البقرة:255] فهم لا يعلمون ما عنده إلا بتعليمه  بإطلاعه لهم على يد الرسل -عليهم الصلاة والسلام- أو بما يجري الله لهم في الدنيا من مخلوقات، وأرزاق، وأشياء يطلعهم عليها . ثم قال: وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ [البقرة:255] الكرسي: مخلوق عظيم فوق السماء السابعة غير العرش، قال ابن عباس: هو موضع القدمين قدمي الرب  وقال بعض أهل العلم: إنه العرش؛ لأن العرش يسمى كرسيًا، والمشهور الأول: أنه مخلوق عظيم فوق السماء السابعة، غير العرش الذي هو عرش الله  يعني فوقه الله  المذكور في قوله سبحانه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] وفي قوله -جل وعلا-: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] في سبعة مواضع من كتاب الله، ذكر فيها استواءه على العرش  وهو مخلوق عظيم، قد أحاط بالمخلوقات، وهو سقفها، قال فيه -جل وعلا-: وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَانِيَةٌ [الحاقة:17] يعني: يوم القيامة. وَلا يَئُودُهُ حِفْظُهُمَا [البقرة:255] يعني: لا يكرث الرب، ولا يثقله، ولا يشق عليه حفظ المخلوقات  هو الحافظ للسماوات، وهو الحافظ للأرض وما فيهما، ولا يشق عليه ذلك، ولا يكرثه، ولا يثقله  لأنه القادر على كل شيء، ولهذا قال سبحانه: وَلا يَئُودُهُ حِفْظُهُمَا [البقرة:255] يعني: لا يكرثه، ولا يثقله، ولا يشق عليه، بل هو القادر على كل شيء . وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] له العلو المطلق، علو الذات فوق العرش، وعلو القهر والسلطان، وعلو الشرف والقدر  فله العلو الكامل  فهو العالي فوق جميع خلقه -جل وعلا- فوق العرش، وهو العالي من جهة كمال أسمائه وصفاته وسلطانه وقدرته -جل وعلا- وله الشرف والفضل، فهو أفضل شيء، وأشرفه  فله علو القهر والسلطان وعلو الشرف والقدر وعلو المكان  فوق العرش، قال تعالى: فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12] وقال تعالى هنا: وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] فهو العلي فوق جميع خلقه، القادر على كل شيء، العظيم السلطان، المتصرف في عباده كيف يشاء، وهو العظيم الذي لا أعظم منه، فله العظمة الكاملة  فلا أعظم منه، ولا أكبر، ولا أعلم، ولا أقدر . فهذه الآية العظيمة فيها هذه الصفات العظيمة، ولهذا صارت أفضل آية في كتاب الله، وأعظم آية في كتاب الله؛ لكونها اشتملت على هذه المعاني العظيمة، والأوصاف العظيمة للرب  وأنه الحي القيوم، وأنه لا معبود بحق سواه، وأنه كامل الحياة، لا تعتريه سنة ولا نوم، وأنه المالك لكل شيء، وأنه العالم بكل شيء، وأنه لا يؤوده حفظ مخلوقاته، ولا يشق عليه ذلك، بل هو القادر على كل شيء  وأن كرسيه قد وسع السماوات والأرض  وأنه لا يشفع أحد عنده إلا بإذنه لكمال قدرته وكمال عظمته، وأنه العلي العلو المطلق، كعلو الذات، وعلو القهر والسلطان، وعلو الشرف والقدر، وهو العظيم الذي لا أعظم منه  عظيم في ذاته، عظيم في أسمائه وصفاته وأفعاله، قاهر فوق عباده كما قال -جل وعلا-: وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ [الأنعام:18] وهو القائل -جل وعلا-: إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [البقرة:20] وقال سبحانه: وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُقْتَدِرًا [الكهف:45]. وبهذا يعلم كل مؤمن، وكل مؤمنة عظم شأن هذه الآية، وأنها آية عظيمة مشتملة على صفات عظيمة، ولهذا صارت بحق أعظم آية في كتاب الله  بنص المصطفى محمد -عليه الصلاة والسلام- والله ولي التوفيق. المقدم: الله ولي التوفيق، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10739/تفسير-اية-الكرسي-وفضلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_409/40901.mp3","categories":["التفسير"]},{"id":12572,"question":"فسروا لنا قول الحق -تبارك وتعالى-: وَإِذْ قَالَ رَبُّكَ لِلْمَلائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِنْ صَلْصَالٍ مِنْ حَمَإٍ مَسْنُونٍ [الحجر:28]؟","title":"ما معنى: {وَإِذْ قَالَ رَبُّكَ لِلْمَلائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِنْ صَلْصَالٍ}؟","answer":"الجواب:  هذا هو آدم -عليه الصلاة والسلام- خلقه الله من طين من التراب، فالصلصال هو الطين الذي يبس حتى صار له صلصلة، والحمأ المسنون هو الطين الذي صار له رائحة لطول مكثه مع الماء. فالحاصل: أن الله خلقه من صلصال من حمإ مسنون وهو التراب الذي مزج بالماء حتى صار له صلصله، وحتى أنتن فصار حمأً له رائحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10777/ما-معنى-واذ-قال-ربك-للملاىكة-اني-خالق-بشرا-من-صلصال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45704.mp3","categories":["التفسير"]},{"id":12585,"question":"المستمع عمر الدين السيلاني من كلومبو بسيرلنكا بعث برسالة ضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: يقول العلم: إن الإنسان يفكر بالمخ، ولكن هناك بعض الآيات في القرآن الكريم، وكذلك بعض الأحاديث للنبي ﷺ تشير إلى القلب مثلًا: أَوَلَيْسَ اللَّهُ بِأَعْلَمَ بِمَا فِي صُدُورِ الْعَالَمِينَ [العنكبوت:10] ثم قول الرسول ﷺ: ألا وإن في الجسد مضغة إذا صلحت؛ صلح الجسد كله، وإذا فسدت؛ فسد الجسد كله، ألا وهي القلب أرجو التوضيح زادكم الله من علمه؟","title":"وجه كون التفكير بالمخ وكون القلب محل الصلاح والفساد","answer":"الجواب:  ليس هناك منافاة بين ما في النصوص في أن القلب هو محل الصلاح والفساد، وما يقول الأطباء من جهة المخ، فإن الدماغ له صلة بالقلب، والقلب له صلة بالدماغ، كما قال أهل العلم، ولهذا قال -جل وعلا- في كتابه العظيم : أَفَلَمْ يَسِيرُوا فِي الأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَا [الحج:46] فجعل العقل يتعلق بالقلب، فالعقل محله القلب، ولكن له صلة بالدماغ، إذا خرب الدماغ اختل العقل، فالقلب له ارتباط بالدماغ، والدماغ له ارتباط بالقلب، فإذا اختل هذا؛ اختل هذا، وإذا اختل هذا؛ اختل هذا، فليس هناك منافاة بين ما قاله الأطباء عن الدماغ، وبين ما دل عليه القرآن والسنة من أن القلب هو محل الصلاح والفساد.  فالقلب متى صلح؛ صلح الجسد كله كما في الحديث، ومتى فسد؛ فسد الجسد كله؛ لأنه محل الإيمان، محل الخوف من الله، ومحل تعظيم حرمات الله، لكن له ارتباط بالدماغ، فإذا اختل الدماغ؛ اختل القلب، وهذا معروف عند الأطباء، معروف بالتجارب، فإنه متى أصيب الرجل في رأسه؛ اختل شعوره كثيرًا في كثير من الأحيان بالضربة التي تكون في رأسه. فالحاصل: أن الرأس له صلة بالقلب، والقلب له صلة بالدماغ، فلا منافاة بين هذا وهذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10793/وجه-كون-التفكير-بالمخ-وكون-القلب-محل-الصلاح-والفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41208.mp3","categories":["التفسير","شروح الحديث"]},{"id":12588,"question":"من الجمهورية الجزائرية المستمع مصطفى بن أحمد، الأخ مصطفى له جمع من الأسئلة من بينها سؤال عن قول الحق -تبارك وتعالى-: لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ [الواقعة:79] من هم المذكورون في هذه الآية؟","title":"معنى قوله تعالى: (لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ)","answer":"الجواب:  الصواب أن المراد بذلك: المطهرون من الأحداث، من الجنابة والحدث الأصغر، فلا يمس المصحف إلا المطهر الذي على طهارة من الحدث الأصغر والأكبر جميعًا، ولهذا كتب النبي ﷺ إلى أهل اليمن: أن لا يمس القرآن إلا طاهر وكان الصحابة -رضي الله عنهم- يُفْتُون بأن لا يمسه إلا طاهر، يعني: من كان على طهارة من الحدثين الأكبر والأصغر، وهو القرآن الكريم، ولهذا قال بعده: تَنزِيلٌ مِنْ رَبِّ الْعَالَمِينَ [الواقعة:80]. أما قراءته فلا بأس أن يقرأ، وإن كان على غير طهارة صغرى، أما الكبرى؛ فلا بد منها حتى ولو كان من غير المصحف لا يقرأ وهو جنب، أما من عليه حدث أصغر؛ فلا بأس أن يقرأه عن ظهر قلب، ولا يشترط فيه الطهارة، لكن لا يمس المصحف إلا بطهارة. واختلف العلماء في الحائض والنفساء، هل هما كالجنب، أم لهما أن تقرأا عن ظهر قلب؛ لأن مدتهما تطول، والصواب أنهما ليستا كالجنب؛ لأن مدتهما تطول؛ فلا تقاسان على الجنب، والصواب: أن لهما القراءة عن ظهر قلب كالمحدث حدثًا أصغر. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10790/معنى-قوله-تعالى-لا-يمسه-الا-المطهرون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45708.mp3","categories":["التفسير"]},{"id":12722,"question":"المستمع العراقي عكال سعود دانوك بعث برسالة ضمنها جمعًا من الأسئلة، من بينها سؤال يسأل فيه عن تفسير قول الحق -تبارك وتعالى- أعوذ بالله من الشيطان الرجيم: إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا إِنَّمَا يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا وَسَيَصْلَوْنَ سَعِيرًا [النساء:10]؟","title":"تفسير قوله تعالى: (إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ...)","answer":"الجواب:  الآية واضحة، يجب على من يلي اليتيم أن يحذر أكل مالهم بغير حق، لا يجوز له أكل أموالهم بغير حق، الواجب عليه أن يتقي الله، وأن يحسن في أموالهم؛ لأن الله يقول سبحانه: وَلا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [الأنعام:152] فالواجب على أولياء الأيتام أن يحسنوا ولا يجوز لهم أكلها بغير حق، قال الله تعالى: وَمَنْ كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِِ  [النساء:6] فإذا كان فقيرًا؛ يتصرف فيها، ويتجر فيها، ويأكل منها بالمعروف، وإذا كان غنيًا؛ فليستعفف عنها إلا إذا فرض له الحاكم القاضي أجرة معلومة على تجارته فيها، جعل له نصف الربح، أو ثلث الربح، أو ربع الربح، أو خمس الربح؛ فلا بأس.  المقصود: أنه لا يأكلها ظلمًا، بل هو متوعد بالنار إذا أكلها ظلمًا، وهكذا غيره من باب أولى، من الناس إذا تعرض لأموال اليتامى بغير حق؛ فهو متوعد بالنار، وإن كان ليس وليًا لهم من باب أولى، فليس لوليهم، ولا غيره أن يأكل أموالهم بالباطل، ليس له إلا ما شرع الله، وما أباح الله  من أكله معهم إذا كان فقيرًا، وتعففه إذا كان غنيًا، أو ما يعطيه إياه الحاكم، ويقدر له الحاكم الشرعي من الأجرة على قيامه على أموالهم، وتعبه في أموال اليتامى، أو جزءًا من الربح إذا كان يتجر فيها، كنصف الربح، أو ثلث الربح، أو ربع الربح، ونحو ذلك، هذا لا بأس به، وهو يرجع إلى القاضي، إلى الحاكم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10935/تفسير-قوله-تعالى-ان-الذين-ياكلون-اموال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46010.mp3","categories":["التفسير"]},{"id":12790,"question":"المستمع مطر أبو سلمى من جدة بعث برسالة ضمنها جمعًا من الأسئلة من بينها سؤال يقول: لماذا سميت سورة التوبة بهذا الاسم؟","title":"سبب تسمية سورة التوبة بهذا الاسم","answer":"الجواب:  لأن فيها التوبة، تاب الله على النبي ﷺ والمهاجرين، تاب فيها على الثلاثة الذين خلفوا، ولهذا سميت التوبة، كما سميت البقرة سورة البقرة؛ لأن فيها ذكر البقرة، وهكذا سميت آل عمران آل عمران؛ لأن فيها إِنَّ اللَّهَ اصْطَفَى آدَمَ وَنُوحًا وَآلَ إِبْرَاهِيمَ وَآلََ عِمْرَانَ [آل عمران:33] وهكذا سميت سورة الأنفال؛ لأن في أولها يَسْأَلُونَكَ عَنِ الأَنْفَالِ [الأنفال:1] نعم. المقدم: جزاكم الله خيرًا لماذا هذه السورة لم تبدأ (بسم الله الرحمن الرحيم)؟ الجواب: لأن عثمان  والصحابة في وقته لما جمعوا القرآن؛ شكوا هل هي مستقلة، أو مع الأنفال، فلم يضعوا بينها تسمية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11004/سبب-تسمية-سورة-التوبة-بهذا-الاسم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46110.mp3","categories":["التفسير"]},{"id":12805,"question":"المستمع (أ. ع. ز) من المزاحمية بعث يسأل عن تفسير قول الحق -تبارك وتعالى-: وَمَا كَانَ صَلاتُهُمْ عِنْدَ الْبَيْتِ إِلَّا مُكَاءً وَتَصْدِيَةً [الأنفال:35].","title":"ما معنى: {وَمَا كَانَ صَلاتُهُمْ عِنْدَ الْبَيْتِ إِلَّا مُكَاءً وَتَصْدِيَةً}؟","answer":"الجواب: هذه صلاة أهل الجاهلية كفار قريش ومن كان معهم عند البيت المكاء والتصدية، المكاء الصفير، والتصدية: الصفيق، فكان من عادتهم التصفيق بالأيدي، والصفير؛ فنهي المسلمون عن مثل عملهم، فلا يجوز للمسلم أن يتعاطى الصفير والتصفيق في عباداته، ولا عند المسجد الحرام، ولا في أعماله الأخرى؛ بل التصفيق للنساء، والرجل يتكلم، وإذا نابه شيء؛ يسبح في الصلاة: سبحان الله، سبحان الله، ولا يجوز له يستعمل الصفير، يستعمل الكلام الذي يحتاج إليه، دون الصفير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11019/ما-معنى-وما-كان-صلاتهم-عند-البيت-الا-مكاء-وتصدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46210.mp3","categories":["التفسير"]},{"id":12812,"question":"سماحة الشيخ بقي من وقت هذه الحلقة ما يقرب من سبع دقائق، أرجو أن تتفضلوا فيه بإجابة الأخوات عن تفسير قول الحق -تبارك وتعالى-: بَلِ السَّاعَةُ مَوْعِدُهُمْ وَالسَّاعَةُ أَدْهَى وَأَمَرُّ [القمر:46] وقوله تعالى: يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا ۝ فِيمَ أَنْتَ مِنْ ذِكْرَاهَا ۝ إِلَى رَبِّكَ مُنتَهَاهَا ۝ إِنَّمَا أَنْتَ مُنذِرُ مَنْ يَخْشَاهَا ۝ كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلَّا عَشِيَّةً أَوْ ضُحَاهَا [النازعات:45-46].","title":"أمر يوم القيامة وهول قيام الساعة","answer":"الجواب:  هذا يدل على عظم الأمر يوم القيامة، وأنها أدهى وأمر مما يقع في الدنيا، خطب الساعة عظيم، وهولها كبير، فلهذا قال -جل وعلا-: فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَى [النازعات:34] سماها: طامة، وقال: فَإِذَا جَاءَتِ الصَّاخَّةُ [عبس:33] وقال: هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ [الغاشية:1] قال: إِذَا وَقَعَتِ الْوَاقِعَةُ [الواقعة:1] قال: الْحَاقَّةُ ۝ مَا الْحَاقَّةُ [الحاقة:1-2]: الْقَارِعَةُ ۝ مَا الْقَارِعَةُ [القارعة:1-2] كل هذا يوم القيامة، ولا يعلم متى تقوم إلا الله  هو الذي يعلم متى تقوم، وإذا قامت فالناس بعد ذلك يرون الدنيا كلا شيء، كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلَّا عَشِيَّةً أَوْ ضُحَاهَا [النازعات:46] كأنهم لبثوا إلا ساعة من نهار؛ لعظم الهول. فالمقصود: أن الساعة أمرها عظيم، وخطبها شديد، فالواجب على جميع المكلفين من الرجال والنساء الإعداد لهذا اليوم، والحذر من الغفلة، وهو يوم عظيم خطير، قال فيه -جل وعلا-: هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ۝ وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ ۝ عَامِلَةٌ نَاصِبَةٌ ۝ تَصْلَى نَارًا حَامِيَةً [الغاشية:1-4] تعمل على غير هدى، تعمل على غير هدى بغير الإخلاص لله، أو بغير المتابعة للرسول ﷺ فلها النار يوم القيامة، قال -جل وعلا-: فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَى ۝ يَوْمَ يَتَذَكَّرُ الإِنسَانُ مَا سَعَى ۝ وَبُرِّزَتِ الْجَحِيمُ لِمَنْ يَرَى ۝ فَأَمَّا مَنْ طَغَى ۝ وَآثَرَ الْحَيَاةَ الدُّنْيَا ۝ فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَى [النازعات:34-39] طغى يعني: تجاوز الحدود، يعني: لم يلتزم بأمر الله، بل تعدى الحدود، فله النار يوم القيامة. وفي آية عبس فَإِذَا جَاءَتِ الصَّاخَّةُ  ۝ يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ ۝ وَأُمِّهِ وَأَبِيهِ ۝ وَصَاحِبَتِهِ وَبَنِيهِ ۝ لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ [عبس:34-37]. فالعاقل يعد العدة لهذا اليوم العظيم ولا يتساهل، وذلك بطاعة الله والاستقامة على أمره، والحذر من مناهيه، مع الوقوف عند حدوده  هذا هو الطريق، وهذا هو السبيل الذي جعله الله سببًا للنجاة يوم القيامة، وليحذر الغفلة عن هذا اليوم العظيم، واتباع الهوى، وطاعة الشيطان، فإن هذا فيه العاقبة الوخيمة، وسوء المصير، ولا حول ولا قوة إلا بالله، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/11026/امر-يوم-القيامة-وهول-قيام-الساعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46217.mp3","categories":["التفسير"]},{"id":12814,"question":"المستمع فيصل الوهيبي يقول: أرجو أن تشرحوا لي قول الحق -تبارك وتعالى- أعوذ بالله من الشيطان الرجيم: مَا أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ اللَّهِ وَمَا أَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ [النساء:79].","title":"ما معنى: {مَا أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ اللَّهِ}؟","answer":"الجواب:  معناها: أن ما أصابك من حسنة؛ فمن الله، هو الذي تفضل بها عليك، وهداك لها، وأعانك عليها، وهو المتفضل سبحانه، وهو الجواد الكريم، وقد سبق بها القدر، ومع هذا تفضل عليك، فأعانك عليها، وهداك لها، حتى فعلتها من صلاة وغيرها.  وما أصابك من سيئة فمن نفسك، من معصية أو غيرها، فمن أسباب نفسك، من معاصيك، أو تساهلك، وعدم قيامك بالواجب، وقد سبق في علم الله أنها تقع، لكن أنت بأفعالك السبب في وقوعها، من معاصيك، أو تفريطك، وعدم أخذك بالأسباب الشرعية، فإذا أخذ مالك، سرق مالك؛ لأنك ما قفلت الباب، أو ما فعلت ما ينبغي من حراسته؛ فأنت السبب. وكذلك إذا وقعت في المعصية فأنت السبب؛ لأنك أنت الذي فعلتها، وأنت الذي تساهلت فيها، وأنت الذي سعيت إليها، وإن كانت بقدر سابق، لكن من أسبابك، أنت لك أسباب، لك فعل، لك قدرة، لك عقل، فمن نفسك، وإن كانت بقدر الله، ولهذا بعدها : قُلْ كُلٌّ مِنْ عِنْدِ اللَّهِ [النساء:78] يعني: بقدر الله، لكن الطاعة من فضله، والمعصية من أسباب تفريطك، وأسبابك الأخرى التي تساهلت بها، حتى وقعت المعصية، أو وقع المرض، أو وقعت السرقة، أو وقع الهدم، أو الانقلاب، أو ما أشبه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11028/ما-معنى-ما-اصابك-من-حسنة-فمن-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46302.mp3","categories":["التفسير"]},{"id":12815,"question":"مستمع بعث برسالة ضمنها جمعًا من الأسئلة، ووقع في نهاية رسالته بالحروف (ع. غ. ع) من الجمهورية العراقية، يقول: فسروا لنا قول الحق -تبارك وتعالى-: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:116].","title":"ما معنى: {إِنَّ اللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ}؟","answer":"الجواب:  هذه الآية على ظاهرها يخبر سبحانه أنه لا يغفر الشرك لمن مات عليه، إذا مات على الشرك؛ لا يغفر له، إذا مات يسب الدين، يسأل الأموات، ويستغيث بالأموات، أو بالملائكة، أو بالجن، أو بالأصنام يدعوهم، يسألهم النصر، يسألهم الغوث، شفاء المرضى، إلى غير هذا، هذا إذا مات على هذا؛ لا يغفر له إلى النار، نعوذ بالله. وهكذا على الصحيح لو مات تاركًا للصلاة لا يصلي ...... لا يغفر له؛ لأنه مات على الكفر بالله، أو مات جاحدًا للصلاة، جاحدًا للزكاة، جاحدًا لصيام رمضان، جاحدًا للحج مع الاستطاعة؛ يكون إلى النار، ما يغفر له -نعوذ بالله- أو مات يسب الدين، أو يستهزئ بالدين، أو ينكر الآخرة والجنة، أو النار أو الجنة، هذا كله كفر بالله، وشرك به سبحانه، من مات عليه؛ فإنه لا يغفر له أبدًا -نسأل الله العافية- بل له النار أبد الآباد. أما من مات على المعصية وهي التي دون الشرك، مات على الزنا ما تاب، أو على الخمر، أو على الربا، أو العقوق لوالديه، أو أحدهما، أو قطيعة الرحم، أو ما أشبه ذلك من المعاصي.. لم يتب؛ هذا تحت مشيئة الله، إن شاء الله غفر له سبحانه بتوحيده وإسلامه وطاعته الأخرى، وإن شاء ربنا سبحانه أدخله النار، وعذبه فيها على قدر المعصية التي مات عليها، ثم يخرج من النار إلى الجنة بعدما يمحص في النار ويطهر. والناس في النار على حسب أعمالهم، العصاة إذا دخلوا النار على حسب أعمالهم، منهم من تطول مدته، ويخلد فيها خلودًا له نهاية، ومنهم من لا تطول مدته لقلة معاصيه إذا دخل النار، قال تعالى: وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا ۝ إِلَّا مَنْ تَابَ وَآمَنَ [الفرقان:69-70] فذكر أنه يخلد المشرك والزاني والقاتل، لكن الخلود مختلف: خلود المشرك لا ينتهي أبدًا، وخلود القاتل إذا كان ما استحل القتل والزاني إذا كان ما استحل الزنا، بل مات على معصية هذا خلود له نهاية، إذا انتهت المدة التي أرادها الله؛ خرج من النار، بعد التطهير والتمحيص. وهكذا قوله -جل وعلا-: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] هذا جزاؤه إن جازاه.. وإن عفا عنه سبحانه هو العفو الغفور، وإن جازاه؛ لأنه مات على التوحيد والإيمان، لكنه قاتل؛ فهذا لخلوده نهاية، ما هو بمثل خلود الكفار، خلوده له نهاية، إذا انتهت المدة؛ أخرجه الله من النار بتوحيده وإسلامه الذي مات عليه. وهكذا بقية العصاة إذا دخلوا النار؛ لهم مدة ينتهون إليها، ثم يخرجون، إما بشفاعة الشفعاء، كالنبي ﷺ أو بشفاعة الملائكة أو الأفراط أو المؤمنين، وبعضهم يخرج بدون شفاعة أحد، بل برحمة الله فقط، إذا ... مضت المدة؛ رحمه الله، وأخرجه سبحانه من دون شفاعة أحد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11029/ما-معنى-ان-الله-لا-يغفر-ان-يشرك-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46303.mp3","categories":["التفسير"]},{"id":12861,"question":"مستمع بعث يسأل عن قول الحق -تبارك وتعالى-: إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ [البقرة:173] ويسأل ما هو الدم المحرم؟","title":"ما المقصود بالدم في: {إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ}؟","answer":"الجواب:  الدم المحرم هو المسفوح، كما في آية الأنعام: قُلْ لا أَجِدُ فِي مَا أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَى طَاعِمٍ يَطْعَمُهُ إِلَّا أَنْ يَكُونَ مَيْتَةً أَوْ دَمًا مَسْفُوحًا [الأنعام:145] المسفوح: هو المراق، وهو الذي ينصب من الذبيحة عند الذبح، تهراق منها، هذا يقال له: مسفوحًا، هذا هو المحرم، أما ما يكون في العروق، يبقى في العروق؛ فهذا ليس بمحرم، يبقى في داخلها، في عروقها، في لحومها؛ ليس بمحرم، إنما هو المسفوح الذي ينصب منها عند ذبحها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11076/ما-المقصود-بالدم-في-انما-حرم-عليكم-الميتة-والدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46511.mp3","categories":["التفسير"]},{"id":12882,"question":"مستمع من السودان: هو إدريس محمد آدم بعث برسالة ضمنها سؤالًا واحدًا، يقول فيه: يقول الله تعالى في كتابه العزيز في سورة (يس): وَجَاءَ مِنْ أَقْصَى الْمَدِينَةِ رَجُلٌ يَسْعَى .. [يس:20] أرجو من سماحة شيخنا التكرم بالإجابة على الأسئلة التالية حول هذا النص، ما هي تلك المدينة المقصودة في الآية، وما اسم الرجل المذكور في الآية الكريمة؟","title":"ما المقصود بالرجل والمدينة في: {وَجَاءَ مِنْ أَقْصَى الْمَدِينَةِ رَجُلٌ يَسْعَى}؟","answer":"الجواب: لا أدري، الله أعلم. نعم. المقدم: ننتقل إلى رسالة أخرى؟ الشيخ: نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11097/ما-المقصود-بالرجل-والمدينة-في-وجاء-من-اقصى-المدينة-رجل-يسعى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46614.mp3","categories":["التفسير"]},{"id":12917,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها جمعًا من الأسئلة، من بين أسئلته سؤال عن تفسير آية من كتاب الله، نص الآية: أعوذ بالله من الشيطان الرجيم وَكَذَلِكَ زَيَّنَ لِكَثِيرٍ مِنَ الْمُشْرِكِينَ قَتْلَ أَوْلادِهِمْ شُرَكَاؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا عَلَيْهِمْ دِينَهُمْ وَلَوْ شَاءَ اللَّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ [الأنعام:137] فسروا لنا هذه الآية؟ جزاكم الله خيرًا.","title":"تفسير قوله تعالى: (وَكَذَلِكَ زَيَّنَ لِكَثِيرٍ مِنَ الْمُشْرِكِينَ ...)","answer":"الجواب:  هذه الآية الكريمة على ظاهرها (شركاؤهم): معبوداتهم من دون الله، زينوا لهم زين لهم الشيطان الذين هم عبدوه من دون الله، وزين لهم معبوداتهم من دون الله أن يقتلوا أولادهم ظلمًا وعدوانا، وقالوا في هذا: إن قتل البنت خشية العار، وقتل الولد خشية الحاجة والفقر، فنهاهم الله عن هذا بقوله -جل وعلا-: وَلا تَقْتُلُوا أَوْلادَكُمْ مِنْ إِمْلاقٍ نَحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ [الأنعام:151] ولهذا قال -جل وعلا-: لِيُرْدُوهُمْ وَلِيَلْبِسُوا عَلَيْهِمْ دِينَهُمْ [الأنعام:137] يعني: ليشبهوا عليهم دينهم وليهلكوهم. فالواجب الحذر من طاعة الشياطين الذين يدعون إلى الشرك بالله، وإلى قتل الأولاد بغير حق، وإلى كل فجور وظلم، وسماهم الله شركاء؛ لأنهم شركوهم مع الله في العبادة، وأطاعوهم في معاصي الله، والشرك به، فسموا شركاء؛ لأجل ذلك، والله سبحانه ليس له شريك، بل هو الواحد الأحد، الذي يستحق العبادة دون كل ما سواه -جل وعلا- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11132/تفسير-قوله-تعالى-وكذلك-زين-لكثير-من-المشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46902.mp3","categories":["التفسير"]},{"id":13026,"question":"في سورة الذاريات آية تقول: وَفِي السَّمَاءِ رِزْقُكُمْ وَمَا تُوعَدُونَ [الذاريات:22] وفي سورة أخرى: فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِنْ رِزْقِهِ وَإِلَيْهِ النُّشُورُ [الملك:15] اجمعوا لي بين هاتين الآيتين، وفسروهما؟ جزاكم الله خيرًا.","title":"الجمع بين: {وَفِي السَّمَاءِ رِزْقُكُمْ وَمَا تُوعَدُونَ} و {فَامْشُوا فِي مَنَاكِبِهَا}","answer":"الجواب:  وَفِي السَّمَاءِ رِزْقُكُمْ [الذاريات:22] يعني: من عند الله -جل وعلا- هو الرزاق  إِنَّ اللَّهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ [الذاريات:58] هو الذي يرزق عباده، ويقدر لهم ما شاء  هذا يربح في زراعته، وفي تجارته، وفي أعماله، وهذا يخسر كثيرًا، وهذا يخسر قليلًا، فهو المقدر  وهو الموفق والهادي والرزاق -جل وعلا- فالرزق منه  وهو الذي ينزل الأمطار، ويكون بها الأرزاق الكثيرة أيضًا  وفي الأرض تنبت الخيرات بسبب الأمطار من ثمار والفواكه والزروع وغير ذلك، وفيها الحيوانات النافعة المباحة، وفيها غير ذلك مما ينفع الناس، كلها من رزق الله . وفي الأرض أيضًا طلب الرزق بالتجارة، والبيع والشراء، والأعمال الأخرى التي يعملها الناس في الخياطة، في التجارة، في النجارة، في عمل البناء، في غير هذا، كل هذه من أسباب الرزق، لكن الرزاق في السماء هو الله وحده  نعم. المقدم: عن الآية الثانية فَامْشُوا فِي مَنَاكِبِهَا [الملك:15]؟ الشيخ: هذه الآية لطلب الرزق. المقدم: طلب الرزق. الشيخ: يمشي في الأرض، يسافر إذا دعت الحاجة، يطلب الرزق في التجارة، وفي غيرها، وهكذا يخرج من بيته إلى كذا، وإلى كذا، يطلب الرزق إلى العمل، هذا يخرج يعمل في البناء، هذا يخرج يعمل في المزرعة، هذا يخرج يعمل في كذا يطلب الرزق، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11243/الجمع-بين-وفي-السماء-رزقكم-وما-توعدون-و-فامشوا-في-مناكبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47206.mp3","categories":["التفسير"]},{"id":13048,"question":"السؤال الثاني في رسالة السائلة من جمهورية مصر العربية تقول: ما معنى الآية الكريمة: وَلَئِنْ سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ [التوبة:65] سورة التوبة، إلى قوله تعالى: بِأَنَّهُمْ كَانُوا مُجْرِمِينَ [التوبة:66] وعلى من نزلت هذه الآية يا فضيلة الشيخ؟","title":"معنى قوله تعالى: (وَلَئِنْ سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ...)","answer":"الجواب:  هؤلاء القوم في غزوة تبوك تكلموا بكلام ما هو بطيب؛ فأنزل الله فيهم هذه الآية الكريمة: وَلَئِنْ سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ  ۝  لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66] كان أناس قالوا كلامًا قبيحًا: ما رأينا مثل قرائنا هؤلاء أرغب بطونًا، ولا أكذب ألسنًا، ولا أجبن عند اللقاء، يعنون الرسول وأصحابه -عليه الصلاة والسلام- وهذه ردة، استهزاء؛ فلهذا حكم الله عليهم بقوله: لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ إِنْ نَعْفُ عَنْ طَائِفَةٍ مِنْكُمْ [التوبة:66] وهو الذي أنكر نُعَذِّبْ طَائِفَةً بِأَنَّهُمْ كَانُوا مُجْرِمِينَ [التوبة:66].  فالمقصود: أن الذي يستهزئ بالدين بالرسول ﷺ أو بالقرآن أو بالإسلام يكون كافرا، نسأل الله العافية، نعم. المقدم: اللهم آمين، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/11265/معنى-قوله-تعالى-ولىن-سالتهم-ليقولن-انما-كنا-نخوض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50508.mp3","categories":["التفسير"]},{"id":13063,"question":"ننتقل إلى رسالة بعثت بها السائلة أسماء حلمي من جمهورية مصر العربية محافظة كفر الشيخ تقول: أستفسر عن الآية الكريمة: وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ [البقرة:233] كيف ذلك في حالة لمن أراد أن يتم الرضاعة بدون أن يحدث الحمل، أرجو الإفادة بذلك؛ لأن هذه المسألة مهمة جدًا في حياتي، ولظروفي الصعبة جدًا في حالة الإنجاب المستمر، جزاكم الله خيرًا؟","title":"تفسير قوله تعالى: (وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ...)","answer":"الجواب:  على المرأة والرجل التعاون في هذا الأمر، فهي ترضع حولين كاملين لمن أراد أن يتم الرضاعة، أما إذا اتفقت مع الزوج في عدم الإتمام، وأن يقطعاه، ويفصلاه، ويعطياه اللبن الخارجي، ويعطياه ما يقوم مقام الرضاع، فلا بأس إذا اتفقا لقوله سبحانه: فَإِنْ أَرَادَا فِصَالًا عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلا جُنَاحَ عَلَيْهِمَا [البقرة:233] إذا اتفقا على فصله، وعدم إرضاعه بعد السنة، أو بعد أشهر؛ فلا حرج في ذلك، ويغذيانه بالأشياء الأخرى، أما إذا توافقا، وتراضيا على الاستمرار؛ فإنها ترضع حولين كاملين. وللزوج أن يعزل عنها حتى لا تحمل، ولها أن تأخذ الحبوب؛ حتى تحمل وقت الرضاع، لا حرج إذا كانت لا تضرها الحبوب، وإن فطماه واتفقا على فطامه لسنة، أو أقل من سنة، وغذياه بغير ذلك؛ فلا بأس، الأمر واسع، والحمد لله، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11280/تفسير-قوله-تعالى-والوالدات-يرضعن-اولادهن-حولين-كاملين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50523.mp3","categories":["التفسير"]},{"id":13121,"question":"بعض الكتاب الإسلاميين يحمل كثيرًا على ابن كثير، ويرجح ابن الجوزية في بعض الشروح، فما هو رأيكم؟","title":"أفضلية تفسير ابن كثير على تفسير ابن الجوزي","answer":"الجواب:  تفسير ابن كثير تفسير عظيم، تفسير سلفي، على طريقة أهل السنة والجماعة، ويمتاز بالعناية بالأحاديث، وتطريقها، وعزوها إلى مخرجيها، فلا أعلم له نظيرًا، كتاب عظيم، ليس له نظير من جهة العناية بتفسير القرآن بالآيات والأحاديث، لكن يفوقه بعض التفاسير الأخرى في العناية بالمعاني والقراءات. أما من جهة تفسير القرآن بالقرآن، والعناية بالعقيدة السلفية، والعناية بالأحاديث؛ فليس له نظير فيما أعلم، لا ابن الجوزي ولا غيره، وابن الجوزي له أغلاط في العقيدة. المقدم: هذا يقول ابن الجوزية.  الشيخ: لا ابن الجوزي غير ابن قيم الجوزية.  المقدم: نعم. الشيخ: تفسيره تفسير مفيد، ولكن تفسير ابن كثير يمتاز عليه من جهات كثيرة -كما تقدم- ويمتاز على غيره من التفاسير أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11344/افضلية-تفسير-ابن-كثير-على-تفسير-ابن-الجوزي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47316.mp3","categories":["التفسير"]},{"id":13123,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الدمام، وباعثها المستمع عبدالرحمن الدوسري، الأخ عبدالرحمن يسأل ويقول في أول أسئلته ما معنى قول الحق -تبارك وتعالى-: وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ [المؤمنون:3]؟","title":"تفسير قوله تعالى: (والذين هم عن اللغو معرضون)","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد قال الله -جل وعلا- في كتابه العظيم في وصف عباده المؤمنين، قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ ۝ وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ [المؤمنون:1-3] فسر العلماء (اللغو) بأمور ثلاثة: أحدها: الشرك؛ لأنه باطل ولاغي، يجب اطراحه، والحذر منه. الثاني: المعاصي؛ لأنها باطلة أيضًا يجب الحذر منها. الثالث: كل شيء لا فائدة فيه، ولا مصلحة فيه، فهو من اللغو، والمؤمن يجتنبه، وهكذا المؤمنة. وكل التفاسير صحيحة، فإن المؤمنين يجتنبون الشرك كله بأنواعه، ويجتنبون المعاصي، ويحذرونها، ويجتنبون أيضًا كل شيء لا فائدة فيه، ولا مصلحة؛ لأنه يشغلهم عما هو أهم، فهكذا ينبغي للمؤمن أن يكون حذرًا من أنواع الشرك كلها، ومن سائر ما حرم الله من المعاصي، وحذرًا أيضًا مما يشغله عما هو أهم من الأشياء التي لا فائدة فيها، من قول، أو عمل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11346/تفسير-قوله-تعالى-والذين-هم-عن-اللغو-معرضون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47401.mp3","categories":["التفسير"]},{"id":13131,"question":"المستمع حمد القحطاني من هجرة طريف بعث يسأل ويقول: أرجو منكم تفسير سورة الكوثر؟","title":"تفسير سورة الكوثر","answer":"الجواب: يقول الله سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ [الكوثر:1] هذا خطاب للنبي ﷺ والكوثر: نهر في الجنة رآه لما عرج به -عليه الصلاة والسلام- نهر عظيم في الجنة، يصب منه ميزابان يوم القيامة في حوضه ﷺ الذي في الموقف يوم القيامة. فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] يعني: شكرًا لله، صل له ما أمرك الله به من الصلاة، وقال بعضهم: معناه صلاة العيد (وانحر) يعني: اذبح الضحايا، والآية أعم، تعم الصلوات كلها، وتعم النحر كله، من الضحايا، وغير الضحايا، كلها تنحر لله سبحانه، لا لغيره -جل وعلا- ولكن صلاة العيد، وذبح النحر داخل في ذلك. (فصل لربك) لا لغيره، يعني: صل له وحده  الصلوات الخمس، صلاة العيد، وصلاة الجمعة كلها لله وحده، وهكذا صلاة النافلة كلها لله. وهكذا النحر، كما قال تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ [الأنعام:162]. فالصلاة لله، والنحر لله، كما أن الصدقة لله، والسجود لله، والدعاء لله، ليس لمسلم أن يدعو غير الله، ولا أن يسجد لغير الله، ولا أن ينحر لغير الله، بل يجب أن تكون أعماله لله وحده . إِنَّ شَانِئَكَ هُوَ الأَبْتَرُ [الكوثر:3] (الشانئ): المبغض المعادي، و(الأبتر): هو الناقص المقطوع، فالمبغض للنبي ﷺ وشانئه هو الأبتر في الدنيا والآخرة، المقطوع الصلة بالله -عز وجل-والصلة بأسباب السعادة، وليس له إلا النار، نعوذ بالله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11364/تفسير-سورة-الكوثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47409.mp3","categories":["التفسير"]},{"id":13200,"question":"سماحة الشيخ! يستفسر عن الآية الكريمة أيضًا يقول: يقول الله -تبارك وتعالى- في كتابه الكريم في سورة يوسف وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلا أَنْ رَأَى بُرْهَانَ رَبِّهِ كَذَلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ [يوسف:24] يقول: ما هو البرهان الذي رآه يوسف  من ربه؟","title":"ما معنى: {‌وَلَقَدْ ‌هَمَّتْ ‌بِهِ ‌وَهَمَّ ‌بِهَا}؟","answer":"الجواب:  يوسف -عليه الصلاة والسلام- هم بها، وهمت به بعد المراودة، لكن الله عصمه وحماه منها وسلم، وهذا البرهان لم يرد فيه نص واضح، شيء أراه الله إياه حتى كف عن هذا الأمر، ولم يقدم عليه، وحماه الله من ذلك؛ لأنه كان من عباد الله المخلصين، الذين خلصهم الله لعباداته وطاعته ونبوته -عليه الصلاة والسلام- قال بعض السلف: إنه رأى أصوات يعقوب أمامه، وقال قوم آخرون شيئًا آخر غير ذلك. فالمقصود: أن هذا البرهان لم يرد فيه عن النبي ﷺ ما يفسره، وأقوال بني إسرائيل لا يعول عليها، فهو برهان أراه الله إياه، أوجب له الكف والحذر؛ لأن الله جعله من عباده المخلصين، الذين يطهرون من مثل هذا الأمر؛ ولهذا قال سبحانه: كَذَلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ [يوسف:24] يعني: مطهرين من هذه الفواحش، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11472/ما-معنى-ولقد-همت-به-وهم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52002.mp3","categories":["التفسير"]},{"id":13202,"question":"هذا السائل الذي رمز لاسمه فهد عبدالله، الجمهورية اليمنية، يقول في هذا  سماحة الشيخ! سؤالي: يقول الله -تبارك وتعالى- في كتابه الكريم في سورة يس: وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ [يس:38] ما المقصود بهذه الآية الكريمة؟ وما هو مستقر الشمس، جزاكم الله خيرًا؟","title":"معنى قوله تعالى: (والشمس تجري لمستقر لها)","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.  أما بعد: فقد فسر النبي ﷺ هذا المستقر، وقال لأبي ذر: أتدري ما مستقرها يا أبا ذر؟ قلت: لا. قال: مستقرها سجودها تحت العرش كانت إذا وازت العرش؛ سجدت سجودًا يليق بها، الله هو الذي يعلم به سبحانه وكيفيته. تَجْرِي لِمُسْتَقَرٍّ لَهَا [يس:38] يعني: إذا حاذت العرش؛ سجدت سجودًا يليق بها، لا يعلمه إلا الله  هو الذي يعلم كيفيته، ثم تستمر، يؤذن لها، فتستمر حتى تطلع من مطلعها، فإذا جاء آخر الزمان قيل لها: ارجعي من حيث جئت؛ فترجع، فتطلع من مغربها. فالمستقر محاذاتها للعرش، فإذا حاذت العرش في وسط السير؛ سجدت، ثم تستمر بعدما يؤذن لها في السير، فتطلع من مطلعها، وإذا أراد الله طلوعها من المغرب قيل لها: ارجعي من حيث جئت، فتطلع من مغربها في آخر الزمان، وذلك من أشراط الساعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11471/معنى-قوله-تعالى-والشمس-تجري-لمستقر-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52001.mp3","categories":["التفسير"]},{"id":13254,"question":"على بركة الله نبدأ هذا اللقاء برسالة وصلت من السائل إبراهيم أبو حامد يقول في هذا  ما هي الأمانة الواردة في قوله تعالى: إِنَّا عَرَضْنَا الأَمَانَةَ عَلَى السَّمَوَاتِ وَالأَرْضِ وَالْجِبَالِ [الأحزاب:72] نرجو منكم التوجيه؟","title":"ما المقصود بالأمانة في: {إِنَّا عَرَضْنَا الأمَانَةَ}؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذه الأمانة أوضحها العلماء في كتب التفسير هي دين الإسلام، هي ما شرع الله لعباده من فرائض، ومن محرمات يجب على المكلفين أداء الفرائض، وترك المحارم، وهذه أمانة، قال -جل وعلا-: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58] وقال تعالى: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8] وقال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27] وقال : إِنَّا عَرَضْنَا الأَمَانَةَ عَلَى السَّمَوَاتِ وَالأَرْضِ وَالْجِبَالِ فَأَبَيْنَ أَنْ يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا الإِنْسَانُ إِنَّهُ كَانَ ظَلُومًا جَهُولًا [الأحزاب:72] فهي ما أوجب الله علينا من التوحيد الذي هو أصل الدين، وإخلاص العبادة لله وحده. وهكذا ما أوجب الله علينا من اتباع الرسول ﷺ، والإيمان بأنه رسول الله، والإيمان بكل ما أخبر الله به ورسوله من أمر الجنة والنار، والساعة والجنة، وغير ذلك، والحساب، والجزاء كل ذلك داخل في الأمانة. وهكذا الإيمان بالصلاة والزكاة والصيام والحج والجهاد، والأمر بالمعروف، والنهي عن المنكر، كل ذلك داخل في الأمانة، لابد أن تؤدى هذه الأمور على الوجه الذي شرعه الله، كل ذلك أمانة. وهكذا ترك المحارم أمانة، فالواجب على كل مسلم أن يتقي الله، وأن يؤدي فرائض الله، وأن يحذر محارم الله، وهذا العمل هو أداء الأمانة. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11539/ما-المقصود-بالامانة-في-انا-عرضنا-الامانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50901.mp3","categories":["التفسير"]},{"id":13255,"question":"يقول هذا السائل: أرجو تفسير الآية الكريمة: أعوذ بالله من الشيطان الرجيم: إِنَّا عَرَضْنَا الأَمَانَةَ عَلَى السَّمَوَاتِ وَالأَرْضِ وَالْجِبَالِ فَأَبَيْنَ أَنْ يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا الإِنْسَانُ إِنَّهُ كَانَ ظَلُومًا جَهُولًا [الأحزاب:72] يرجو تفسير لهذه الآية؟","title":"ما معنى: {إِنَّا عَرَضْنَا الأَمَانَةَ عَلَى السَّمَوَاتِ وَالأَرْضِ}؟","answer":"الجواب: الأمانة هي حق الله على عباده، وما شرعه لهم من توحيده، والإخلاص له، وسائر ما أوجب عليهم من صلاة وغيرها، وترك ما حرم الله عليهم، وهكذا حقوق العباد من حق الوالدين، وحق الرحم، وغير ذلك. فالأمانة ما أمر الله به، وما أوجبه على عباده، يجب أن يؤدوا هذه الأمانة على الوجه المشروع، كما قال تعالى: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58] ويقول سبحانه: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27]. فالمؤمن إذا أحرم هذا الإحرام، يعني الإحرام العام ينبغي له أن يجتهد في أداء ما فرض الله عليه، وإذا دخل في الصلاة يؤدي ما أوجب الله عليه، وإذا دخل في الصوم يؤدي ما أوجب الله عليه، وفي الزكاة يؤدي ما أوجب الله عليه، وهكذا كلها أمانات، فالحج أمانة، والصوم أمانة، والزكاة أمانة، والصلاة أمانة .. بر الوالدين أمانة .. ترك المحارم أمانة، فالواجب أداؤها بطيب نفس، وإخلاص، والرغبة فيما عند الله، فإذا دخل في الصلاة؛ دخل بانشراح صدر، ورغبة بما عند الله؛ حتى يؤديها كاملة، وهكذا يخرج الزكاة عن طيب نفس، يرجو ما عند الله، وهكذا يصوم رمضان صيامًا شرعيًا بعيدًا عما حرم الله، وهكذا إذا حج يصون حجه عما حرم الله عليه، وهكذا بقية الأمور. فإن هذه الأمانة لا يساويها شيء، بل هي الأمانة العظمى، وهي دين الله -جل وعلا- ولهذا عرضها على السموات والأرض والجبال؛ فأبين أن يحملنها، وأشفقن منها؛ لعظم شأنها. فالواجب على المكلف من بني آدم أن يعتني بها، وأن يؤديها كاملة على وجه الإخلاص لله، في فعل الواجبات، وفي ترك المحارم، يرجو ثواب الله، ويخشى عقاب الله سبحانه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11540/ما-معنى-انا-عرضنا-الامانة-على-السموات-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51401.mp3","categories":["التفسير"]},{"id":13288,"question":"قال الله تعالى: وَقَالُوا رَبَّنَا عَجِّلْ لَنَا قِطَّنَا قَبْلَ يَوْمِ الْحِسَابِ [ص:16] ما هو القط المذكور في الآية سماحة الشيخ؟","title":"ما معنى: {وَقَالُوا رَبَّنَا عَجِّلْ لَنَا قِطَّنَا}؟","answer":"الجواب:  نصيبهم الذي لهم من الخير يبونه في الدنيا، هذا ينتقد عليهم ذلك، المقصود: عَجِّلْ لَنَا قِطَّنَا قَبْلَ يَوْمِ الْحِسَابِ [ص:16] يعني: نصيبنا، وجزاءنا في الدنيا، عجله في الدنيا، نصيبهم وجزاؤهم من خير وشر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11573/ما-معنى-وقالوا-ربنا-عجل-لنا-قطنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50918.mp3","categories":["التفسير"]},{"id":13304,"question":"على بركة الله نبدأ هذا اللقاء بسؤال لأحد الإخوة (ع. أ. أ) يقول: ما معنى القنوط من رحمة الله، وذلك من الكتاب والسنة؟ جزاكم الله خيرًا يا سماحة الشيخ.","title":"معنى القنوط من رحمة الله","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالقنوط من رحمة الله هو اليأس، كونه لا يرجو الله يقنط أن الله يغفر له، وأن الله يرحمه، هذا من الكبائر، من كبائر الذنوب، ربنا -جل وعلا- نهى عن هذا، قال -جل وعلا-: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53]، وقال تعالى: إِنَّهُ لا يَيْئَسُ مِنْ رَوْحِ اللَّهِ إِلَّا الْقَوْمُ الكَافِرُونَ [يوسف:87] فلا يجوز لأحد أن يقنط من رحمة الله، يعني: ييئس لكفره أو لمعاصيه، بل عليه التوبة، والرجوع إلى الله، والإنابة إليه، وله البشرى بأن الله يقبل توبته، ويعظم أجره، ويجازيه على ما فعل من الخير. أما اليأس والقنوط لأجل سوء العمل فهذا من تزيين الشيطان، ولا يجوز، بل يجب على العبد الحذر من ذلك، وأن لا يقنط ولا ييئس، بل يرجو رحمة ربه، يرجو أن الله يتوب عليه، يرجو أن الله يتقبل عمله، فلا ييئس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11590/معنى-القنوط-من-رحمة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52201.mp3","categories":["التفسير","الأخلاق المذمومة"]},{"id":13306,"question":"هذا سائل للبرنامج الحقيقة السائل لم يكتب الاسم في هذه الرسالة، يقول: ورد في الحديث عن النبي ﷺ بأنه يأتي رجال يوم القيامة ولهم أعمال كالجبال، فيجعلها الله هباءً منثورًا؛ لأنهم لم يحفظوا الله بالغيب، هل هذا ينطبق على من انتهك حرمات الله بالغيب، ثم تاب، أفيدونا بذلك؟","title":"بيان من تكون أعمالهم هباءً منثورًا يوم القيامة","answer":"الجواب: هذه أعمال المشركين، قال الله -جل وعلا-: وَقَدِمْنَا إِلَى مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاءً مَنْثُورًا [الفرقان:23] وقال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال تعالى: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ [المائدة:5] هذه أعمال الكفار، من قدم يوم القيامة، وهو مشرك، لم يتب قبل الموت، أعماله حابطة تكون هباءً منثورًا. أما أصحاب المعاصي فهم على خطر، ولكن ليسوا داخلين في هذه الآية، وهي قوله -جل وعلا-: وَقَدِمْنَا إِلَى مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاءً مَنْثُورًا [الفرقان:23] العاصي على خطر والله -جل وعلا- قال في حقه: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] فهو تحت مشيئة الله، إن شاء الله عفا عنه وأدخله الجنة بتوحيده وطاعته، وإن شاء عاقبه على بعض المعاصي التي مات عليها لم يتب، وأما هؤلاء الذين تكون أعمالهم هباءً منثورًا فهؤلاء هم الكفرة بالله -نسأل الله العافية-. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11592/بيان-من-تكون-اعمالهم-هباء-منثورا-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52112.mp3","categories":["التفسير","الرقائق"]},{"id":13364,"question":"أخوكم في الله بندر عبد الله يقول في هذا  ما هو تفسير الآية الكريمة: يَرَوْنَهُمْ مِثْلَيْهِمْ رَأْيَ الْعَيْنِ [آل عمران:13] في سورة آل عمران، علمًا بأن الآية ذكرت في سورة التوبة؟الشيخ: سورة الأنفال.المقدم: أو سورة الأنفال؟","title":"تفسير قوله تعالى {يَرَوْنَهُمْ مِثْلَيْهِمْ رَأْيَ الْعَيْنِ}","answer":"الجواب: المقصود أن هذا يوم بدر، والله -جل وعلا- قضى بحكمه العدل  أن يقللهم في أعينهم هؤلاء وهؤلاء: وَإِذْ يُرِيكُمُوهُمْ إِذِ الْتَقَيْتُمْ فِي أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِي أَعْيُنِهِمْ لِيَقْضِيَ اللَّهُ أَمْرًا كَانَ مَفْعُولًا [الأنفال:44] فلما تقاربوا؛ صار كل واحد يرى صاحبه قليلًا، لما تقاربوا؛ الصحابة يرونهم قليلين، والكفار يرون الصحابة قليلًا؛ حتى يتمكن بعضهم من بعض، حتى يعني يندفع بعضهم إلى البعض، حتى حكم الله بينهم، وقتل الله صناديدهم، ونصر المسلمين عليهم، وكانوا أولًا يرونهم مثليهم، قيل: المسلمون يرون الكفار مثليهم. وقيل: الكفار يرون المسلمين مثليهم، فلما دنا بعضهم من بعض، واتصل بعضهم ببعض؛ صار كل واحد يرى خصمه أقل منه؛ حتى يقدم هذا على هذا، وهذا على هذا: وَإِذْ يُرِيكُمُوهُمْ إِذِ الْتَقَيْتُمْ فِي أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِي أَعْيُنِهِمْ لِيَقْضِيَ اللَّهُ أَمْرًا كَانَ مَفْعُولًا وَإِلَى اللَّهِ تُرْجَعُ الأُمُورُ [الأنفال:44]  فالله -جل وعلا- جعل تقليل هؤلاء في وجه هؤلاء، وهؤلاء في وجه هؤلاء من أسباب الإقدام؛ حتى التحم الجميع، ونصر الله المسلمين، وأذل الكافرين. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11650/تفسير-قوله-تعالى-يرونهم-مثليهم-راي-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52406.mp3","categories":["التفسير"]},{"id":13476,"question":"سنعود إلى أسئلتك الباقية يا أخت (ج. ع) من الجمهورية اليمنية في حلقة قادمة -إن شاء الله تعالى- أما الآن فننتقل إلى رسالة المستمعة أم معاذ تقول في رسالتها: ما معنى قوله تعالى: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا [مريم:71]؟ وهل حقًا أن المؤمن التقي يدخل النار ويعذب؟","title":"تفسير قوله تعالى {وإن منكم إلا واردها}","answer":"الجواب: الآية فسرها النبي ﷺ وأن المراد بالورود المرور على الصراط، فالكل يمر على الصراط، والصراط منصوب على متن جهنم، فالكافر لا يمر، يسقط في النار، يساق إلى النار، ويدخل في النار -نسأل الله العافية- والمؤمن ينجو، ولا يسقط فيها، ولهذا قال سبحانه: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا  ۝ ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا [مريم: 71- 72] فالكفار يساقون إليها والمسلمون يمرون على الصراط وينجون. ومن المسلمين من يخدش، ثم ينجو، ومنهم من يسقط في النار بأسباب معاصيه، فهذا يوجب الحذر، وأن يستقيم المؤمن على تقوى الله، ويحذر معصيته، حتى ينجيه الله من النار حال المرور، وقبل المرور. والمقصود: أن الورود هو المرور، فيمر المتقون والمؤمنون، ولا يضرهم شيء والحمد لله، ويمر أقوام، أما الكافرون فلا يمرون، بل يساقون إلى النار، وقد يسقط بعض المارين من المسلمين بأسباب معاصيه، فيبقى في النار ما شاء الله، ثم يخرجه الله من النار بأسباب موته على التوحيد والإسلام. هذا الذي عليه أهل السنة والجماعة أن العصاة يدخل بعضهم النار، ويعذبون فيها بسبب معاصيهم، لكن لا يخلدون، بل لهم أمد ينتهون إليه، فإذا تم الأمد، وانتهى ما قسمه الله، وما قدره الله عليهم من عذاب أخرجوا من النار إلى الجنة، ولا يبقى في النار إلا الكفار يخلدون فيها أبد الآباد، نعوذ بالله من ذلك.  وأما المتقون فإنهم يمرون ولا يسقطون، كما قال جل وعلا: ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا [مريم:72] نسأل الله السلامة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11779/تفسير-قوله-تعالى-وان-منكم-الا-واردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47805.mp3","categories":["التفسير"]},{"id":13540,"question":"سماحة الشيخ! على بركة الله نبدأ هذا اللقاء بسؤال من السائل محمد سعيد يستفسر عن معنى قوله تعالى: عَلَى شَفَا جُرُفٍ هَارٍ فَانْهَارَ بِهِ فِي نَارِ جَهَنَّمَ [التوبة:109] يقول: ما هو الذي ينهار به في هذا الجرف؟ أفيدونا جزاكم الله خيرًا.","title":"معنى قوله تعالى {على شفا جرف هار...}","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذه الآية يفسرها ما قبلها، يقول -جل وعلا-: وَالَّذِينَ اتَّخَذُوا مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًا بَيْنَ الْمُؤْمِنِينَ وَإِرْصَادًا لِمَنْ حَارَبَ اللَّهَ وَرَسُولَهُ مِنْ قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَا إِلَّا الْحُسْنَى وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَاذِبُونَ  ۝  لا تَقُمْ فِيهِ أَبَدًا لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَنْ تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ  ۝  أَفَمَنْ أَسَّسَ بُنْيَانَهُ عَلَى تَقْوَى مِنَ اللَّهِ وَرِضْوَانٍ خَيْرٌ أَمْ مَنْ أَسَّسَ بُنْيَانَهُ عَلَى شَفَا جُرُفٍ هَارٍ فَانْهَارَ بِهِ فِي نَارِ جَهَنَّمَ وَاللَّهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ [التوبة:107-109]. يبين  أن ما فعله المنافقون من تعمير مسجد للضرار، كان المنافقون بنوا بيتًا سموه مسجدًا وقالوا: إنه لذوي الحاجة في الليلة الشاتية، والمطيرة، وكان هذا عند عزمه ﷺ على التوجه إلى تبوك، وطلبوا منه أن يصلي فيه، فقال: نحن على سفر، ولكن إذا رجعنا؛ صلينا فيه إن شاء الله فلما رجع ودنا من المدينة جاء خبره من السماء أنه مسجد ضرار، وأنه فعله المنافقون مضارة لمسجد قباء، وقال الله له فيه: لا تَقُمْ فِيهِ أَبَدًا لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ [التوبة:108] وهو مسجد النبي ﷺ ومسجد قباء خير من هذا المسجد الذي أسسوه على البلاء والفساد والقصد الفاسد، وكانوا يقولون: إنه يأتي أبو عامر الفاسق، إنسان كان يقال له: الراهب، يريدون أنه ينزل فيه، ويكون حربًا للرسول ﷺ ولأصحابه. فأطلع الله -جل وعلا- نبيه على مقصدهم الخبيث، ونهاه أن يقوم فيه، لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَنْ تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ [التوبة:108] ثم قال سبحانه: أَفَمَنْ أَسَّسَ بُنْيَانَهُ عَلَى تَقْوَى مِنَ اللَّهِ وَرِضْوَانٍ خَيْرٌ [التوبة:109] كمسجد قباء ومسجد النبي ﷺ، لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَنْ تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ [التوبة:108] ثم قال سبحانه: أَفَمَنْ أَسَّسَ بُنْيَانَهُ عَلَى تَقْوَى مِنَ اللَّهِ وَرِضْوَانٍ خَيْرٌ أَمْ مَنْ أَسَّسَ بُنْيَانَهُ عَلَى شَفَا جُرُفٍ هَارٍ فَانْهَارَ بِهِ فِي نَارِ جَهَنَّمَ [التوبة:109] يعني: كهؤلاء الذين أسسوا هذا البناء، وهو سبب لسقوطهم في جهنم... بنيانهم هذا. المقصود: وعيدهم هم، وإلا البنيان ليس المقصود البنيان، المقصود: أنهم أسسوا عملهم الخبيث على شفا جرف هار، فإن هذا الذي أسسوه -وهو قصدهم أن يأتي أبو عامر الفاسق ويحارب النبي ﷺ ويحارب المسلمين- أن هذا أساس خبيث .. أساس باطل .. أساس يقود أهله إلى أن يهوي بهم في جهنم، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11854/معنى-قوله-تعالى-على-شفا-جرف-هار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51901.mp3","categories":["التفسير"]},{"id":13543,"question":"السائلة التي رمزت لاسمها (م. س. المالكي) تقول: أستفسر عن الآية الكريمة: أَفَلا يَنْظُرُونَ إِلَى الإِبِلِ كَيْفَ خُلِقَتْ [الغاشية:17]؟","title":"تفسير قوله تعالى {أفلا ينظرون إلى الإبل كيف خلقت}","answer":"الجواب: المقصود: أن الله -جل وعلا- يحث عباده، يحثهم على النظر في مخلوقاته لما فيها من العبر والدلائل على قدرته العظيمة، وأنه رب العالمين، وأنه المستحق للعبادة، ولهذا يقول: أَفَلا يَنْظُرُونَ إِلَى الإِبِلِ كَيْفَ خُلِقَتْ [الغاشية:17].  هذه الإبل التي جعلها الله للناس متاعًا يحملون عليها أثقالهم، ويأكلون من لحومها، ويشربون من ألبانها، ويوقدون من بعرها، ويستمتعون بجلودها، لهم فيها منافع عظيمة، لهم فيها منافع كثيرة وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ [المؤمنون:22] كما قال -جل وعلا-: وَالأَنْعَامَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ وَمَنَافِعُ وَمِنْهَا تَأْكُلُونَ ۝ وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ ۝ وَتَحْمِلُ أَثْقَالَكُمْ إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الأَنفُسِ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَحِيمٌ [النحل:5-7]. فهي آية، مخلوق عظيم فيه منافع كثيرة، الله يقول: أَفَلا يَنْظُرُونَ إِلَى الإِبِلِ كَيْفَ خُلِقَتْ [الغاشية:17] ينظرون ما فيها من المنافع العظيمة، والعبر في خلقتها وفي منافعها. وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ [الغاشية:19] هذه الجبال العظيمة، وما فيها من الآيات والعبر، كلها من آياته العظيمة التي خلقها لعباده ليعتبروا.  وهكذا السماء كيف رفعت هذه السماء فوقنا، وزينها الله بالنجوم.. بالشمس والقمر، وهكذا الأرض: كَيْفَ سُطِحَتْ [الغاشية:20] بسطها لعباده، فهذه آيات أربع إِلَى الإِبِلِ كَيْفَ خُلِقَتْ [الغاشية:17] وَإِلَى السَّمَاءِ كَيْفَ رُفِعَتْ [الغاشية:18] وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ [الغاشية:19] وَإِلَى الأَرْضِ كَيْفَ سُطِحَتْ [الغاشية:20]. وهكذا غيرها من البحار والأنهار والأشجار والشمس والقمر واختلاف الليل والنهار وغيره، كله آيات، كما قال -جل وعلا-: إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ وَاخْتِلافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الأَلْبَابِ [آل عمران:190] نعم. الله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11861/تفسير-قوله-تعالى-افلا-ينظرون-الى-الابل-كيف-خلقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51903.mp3","categories":["التفسير"]},{"id":13545,"question":"أيضًا تستفسر عن الآية الكريمة: وَصَلِّ عَلَيْهِمْ إِنَّ صَلاتَكَ سَكَنٌ لَهُمْ [التوبة:103] تقول: ما المقصود بالصلاة هنا؟","title":"تفسير قوله تعالى {وصل عليهم إن صلاتك سكن لهم}","answer":"الجواب: المقصود: الدعاء، أن يدعو لهم، خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا وَصَلِّ عَلَيْهِمْ [التوبة:103] يعني: يأخذ الصدقة منهم، ويدعو لهم بالتوفيق والرحمة والخلف الجزيل، هذا معنى (صل عليهم) يعني: يدعو لهم بالبركة، بارك الله لكم، أثابكم الله، تقبل الله منكم، زادكم الله من فضله، وما أشبه ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/11865/تفسير-قوله-تعالى-وصل-عليهم-ان-صلاتك-سكن-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51904.mp3","categories":["التفسير"]},{"id":13752,"question":"أحد الإخوة المستمعين بعث برسالة يقول: سوداني مقيم في المملكة يسأل عن تفسير قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48].","title":"تفسير قوله: {إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ}","answer":"الجواب: هذه الآية على ظاهرها، تدل على أن من مات على الشرك؛ فله النار -والعياذ بالله- مخلدًا فيها، لا يغفر له أبدًا، إذا كان قد بلغته الدعوة، أما من مات على ما دون الشرك من المعاصي؛ فهو تحت مشيئة الله عند أهل السنة والجماعة؛ لهذه الآية العظيمة، فإذا مات على الزنا، أو على شرب الخمر، أو العقوق، أو نحو هذا من المعاصي؛ فهو تحت مشيئة الله، إن شاء الله غفر له، وإن شاء عذبه على قدر المعصية التي مات عليها، ثم بعد التطهير يخرجه الله من النار. هذا هو الحق عند أهل السنة والجماعة، إذا مات على معصية غير مكفرة، ولم يستحلها؛ مات وهو يتعاطى الخمر، أو الربا، أو العقوق، أو الغيبة، أو النميمة هذا تحت مشيئة الله، إن شاء الله غفر له، وعفا عنه بفضله وإحسانه، قد يكون هذا من أسباب أعماله الصالحة، وإن شاء -جل وعلا- عاقبه على قدر معصيته عقوبة تليق به سبحانه، فإنه الغفور والجواد الكريم  فيعاقبه كما يشاء سبحانه على معصيته التي مات عليها، ولم يتب بما يشاء  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12114/تفسير-قوله-ان-الله-لا-يغفر-ان-يشرك-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48119.mp3","categories":["التفسير"]},{"id":13861,"question":"الأخوان يطلبون من سماحتكم تفسير قول الحق تبارك وتعالى أعوذ بالله من الشيطان الرجيم: فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ ۝ وَيَمْنَعُونَ الْمَاعُونَ [الماعون:4-7]؟","title":"تفسير قوله تعالى {فويل للمصلين...}","answer":"الجواب: الآية على ظاهرها، والويل إشارة إلى شدة العذاب، والله سبحانه يتوعد المصلين الموصوفين بهذه الصفات التي ذكرها سبحانه، وهي قوله: عَنْ صَلاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ ۝ وَيَمْنَعُونَ الْمَاعُونَ [الماعون:7] ليس السهو بمعنى الترك، فإن الترك كفر أكبر -نسأل الله العافية- ولكنه نوع من التساهل كتأخيرها عن أدائها في الجماعة والتهاون في بعض مكملاتها التي يجب أن تفعل.. ونحو ذلك مما يتعلق بالنقص فيها فهذا فيه الوعيد، أما إذا تركها عمدًا فهذا يكون كافرًا كفرًا أكبر وإن لم يجحد وجوبها في أصح قولي العلماء، لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، ولقوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه.\nفهذان الحديثان وما جاء في معناهما حجة قائمة وهو برهان ساطع في كفر تارك الصلاة نعوذ بالله وإن لم يجحد وجوبها، لكن إذا تساهل فيها بأن تساهل في أدائها ولم يؤدها كما يجب أو تأخر عن أدائها في الجماعة فهذا يعتبر من السهو عنها، أما السهو فيها فهذا ليس به شيء وليس فيه وعيد فقد سها النبي ﷺ وسها المسلمون، السهو يقع من المؤمن في الصلاة، كما بين النبي ﷺ أحكامه، ولكن المقصود السهو عنها وذلك بالتساهل والتهاون في أدائها كما أوجب الله، وأعظم من ذلك وأدهى وأمر الرياء نسأل الله العافية كعمل المنافقين، فإن المنافق كفره أشد من كفر الكافر، فإذا صلاها رياءً لا عن إيمان بأنها فرض عليه فإنه يكون كافرًا وصلاته باطلة، فإن صلاها رياءً نافلة بطلت أيضًا، فالواجب أن يصلي المؤمن لله وحده يريد وجهه الكريم ويريد الثواب عنده ، ولعلمه بأن الله فرض عليه الصلاة -الصلوات الخمس- فيؤديها إخلاصًا لله وطاعة لله وتعظيمًا له وطلبًا لمرضاته .\nومن صفاتهم أنهم يمنعون الماعون، الماعون فسر بالزكاة وأنهم يمنعون الزكاة؛ لأن الزكاة قرينة الصلاة كما قال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ [البينة:5] قال تعالى: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] وقال قوم آخرون من أهل العلم: إنه العارية التي يحتاجها الناس ويضطرون إليها، كالدلو لجلب الماء، والميزان للحاجة، والقدر للحاجة ونحو ذلك ولكن منع الزكاة أعظم وأكبر، فينبغي للمؤمن أن يكون حريصًا على أداء ما أوجب الله وعلى مساعدة إخوانه عند الحاجة بالعارية؛ لأنها تنفع إخوانه وتنفعه أيضاً ولا تضره، فينبغي له أن يساعد بالماعون الذي يحتاجه جيرانه وإخوانه من قدر أو ميزان أو دلو أو غير هذا مما يحتاجه الجيران، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/12231/تفسير-قوله-تعالى-فويل-للمصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60303.mp3","categories":["التفسير"]},{"id":13864,"question":"الأخوان يطلبون من سماحتكم تفسير قول الحق تبارك وتعالى أعوذ بالله من الشيطان الرجيم: فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ ۝ وَيَمْنَعُونَ الْمَاعُونَ [الماعون:4-7]؟","title":"تفسير قوله تعالى {فويل للمصلين...}","answer":"الجواب: الآية على ظاهرها، والويل إشارة إلى شدة العذاب، والله سبحانه يتوعد المصلين الموصوفين بهذه الصفات التي ذكرها سبحانه، وهي قوله: عَنْ صَلاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ ۝ وَيَمْنَعُونَ الْمَاعُونَ [الماعون:7] ليس السهو بمعنى الترك، فإن الترك كفر أكبر -نسأل الله العافية- ولكنه نوع من التساهل كتأخيرها عن أدائها في الجماعة والتهاون في بعض مكملاتها التي يجب أن تفعل.. ونحو ذلك مما يتعلق بالنقص فيها فهذا فيه الوعيد، أما إذا تركها عمدًا فهذا يكون كافرًا كفرًا أكبر وإن لم يجحد وجوبها في أصح قولي العلماء، لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، ولقوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه.\nفهذان الحديثان وما جاء في معناهما حجة قائمة وهو برهان ساطع في كفر تارك الصلاة نعوذ بالله وإن لم يجحد وجوبها، لكن إذا تساهل فيها بأن تساهل في أدائها ولم يؤدها كما يجب أو تأخر عن أدائها في الجماعة فهذا يعتبر من السهو عنها، أما السهو فيها فهذا ليس به شيء وليس فيه وعيد فقد سها النبي ﷺ وسها المسلمون، السهو يقع من المؤمن في الصلاة، كما بين النبي ﷺ أحكامه، ولكن المقصود السهو عنها وذلك بالتساهل والتهاون في أدائها كما أوجب الله، وأعظم من ذلك وأدهى وأمر الرياء نسأل الله العافية كعمل المنافقين، فإن المنافق كفره أشد من كفر الكافر، فإذا صلاها رياءً لا عن إيمان بأنها فرض عليه فإنه يكون كافرًا وصلاته باطلة، فإن صلاها رياءً نافلة بطلت أيضًا، فالواجب أن يصلي المؤمن لله وحده يريد وجهه الكريم ويريد الثواب عنده ، ولعلمه بأن الله فرض عليه الصلاة -الصلوات الخمس- فيؤديها إخلاصًا لله وطاعة لله وتعظيمًا له وطلبًا لمرضاته .\nومن صفاتهم أنهم يمنعون الماعون، الماعون فسر بالزكاة وأنهم يمنعون الزكاة؛ لأن الزكاة قرينة الصلاة كما قال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ [البينة:5] قال تعالى: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] وقال قوم آخرون من أهل العلم: إنه العارية التي يحتاجها الناس ويضطرون إليها، كالدلو لجلب الماء، والميزان للحاجة، والقدر للحاجة ونحو ذلك ولكن منع الزكاة أعظم وأكبر، فينبغي للمؤمن أن يكون حريصًا على أداء ما أوجب الله وعلى مساعدة إخوانه عند الحاجة بالعارية؛ لأنها تنفع إخوانه وتنفعه أيضاً ولا تضره، فينبغي له أن يساعد بالماعون الذي يحتاجه جيرانه وإخوانه من قدر أو ميزان أو دلو أو غير هذا مما يحتاجه الجيران، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/12231/تفسير-قوله-تعالى-فويل-للمصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60303.mp3","categories":["التفسير"]},{"id":14005,"question":"أعوذ بالله من الشيطان الرجيم، قال تعالى: طه ۝ مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى ۝ إِلَّا تَذْكِرَةً لِمَنْ يَخْشَى [طه:1-3] ما معنى هذه الآيات؟ جزاكم الله خيرا، والسؤال لأخينا عبد الله محمد علي عتش.","title":"ما معنى: {طه * مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى}؟","answer":"الجواب: على ظاهرها، طه [طه:1] هذه من الحروف المقطعة، مثل الم [البقرة:1] ومثل حم ۝ عسق [الشورى:1-2] ومثل: ص [ص:1] و ق [ق:1] هذه حروف مقطعة، الأكثر من أهل العلم أنهم يقولون فيها: الله أعلم بمعانيها ، والله جعلها فواتح لكثير من السور، للدلالة على أن القرآن مؤلف من هذه الحروف التي يعرفها الناس.\nأما قوله: مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى ۝ إِلَّا تَذْكِرَةً لِمَنْ يَخْشَى [طه:2-3] هذا واضح، الله ما أنزل القرآن ليشقى الرسول ﷺ ويتعب، ولكن أنزله تذكرة، للتذكرة والعمل والاستفادة، الله أنزل كتابه العظيم تذكرةً للمؤمنين، ولنبيه ﷺ؛ حتى يعملوا به ويستقيموا عليه، وفيه الراحة والطمأنينة، وفيه السعادة العاجلة والآجلة، وليس فيه الشقاء بل فيه الراحة والطمأنينة وفيه التقرب إلى الله، والأنس بمناجاته وذكره ، وليس منزلًا ليشقى به النبي ﷺ أو العبد لا، بل ليستريح به وليتنعم به وليستفيد منه وليعمل به، وليفوز بالجنة والسعادة بعمله به واستقامته عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12422/ما-معنى-طه-ما-انزلنا-عليك-القران-لتشقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48309.mp3","categories":["التفسير"]},{"id":14013,"question":"رسالة وصلت إلى البرنامج من ليبيا باعثها أخ لنا من هناك يقول: محمد إبراهيم حميد ، أخونا محمد يسأل ويقول: أرجو من سماحة الشيخ تفسير قوله تعالى في كتابه العزيز في سورة الأنبياء بسم الله الرحمن الرحيم: وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ[الأنبياء:107].","title":"تفسير قوله تعالى: {وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ}","answer":"الجواب: الآية على ظاهرها، الله سبحانه أرسل نبيه محمد ﷺ رحمة للعالمين، هو رسول الله إلى الجن والإنس.. إلى الجميع، كما قال تعالى: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا[الأعراف:158]، وقال سبحانه: وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا[سبأ:28]، فهو رسول الله إلى الجميع، وهو رحمة الله إلى العالمين بأسباب رسالته وطاعة أوامره، ينزل الغيث وينتفع العالم كله؛ الدواب والشجر والجن والإنس والحيوانات، وتقوم الحجة على الكافر ويبلغ الرسالة فهو رحمة للعالمين جميعًا، فمن دخل في رسالته صارت الرحمة كاملة في حقه ودخل الجنة ونجا من النار، ومن لم يدخل قامت عليه الحجة وانتفت المعذرة وصار بذلك قد رحم من جهة بلاغه ومن جهة إنذاره حتى لا يقول: ما جاءني بشير ولا نذير، هذا نوع من الرحمة. ثم ما يحصل من الخير من الغيث لينتفع به الكافر والمسلم، وما يحصل من الأمن بالعهود والمواثيق يحصل به الرحمة والخير للمسلم والكافر.. إلى أشباه ذلك من الخيرات التي تقع بأسباب هذه الرسالة حتى للكافر حتى للدواب، فهو رسول الله ﷺ رحمة للعالمين جميعًا، لكن من دخل في الإسلام واستقام على الدين صارت الرحمة في حقه أكثر وأكمل، ومن لم يدخل في دين الله ناله من الرحمة بقدر ما حصل له من الخير من غيث وأمن ورزق واسع بأسباب هذه الرسالة، ومن أمره في بلاده بالعهود والمواثيق التي بينه وبين المسلمين.. إلى غير ذلك من أنواع الرحمة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12434/تفسير-قوله-تعالى-وما-ارسلناك-الا-رحمة-للعالمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61104.mp3","categories":["التفسير"]},{"id":14161,"question":"هنا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها جمعًا من الأسئلة من بينها سؤال عن تفسير قول الحق تبارك وتعالى: أعوذ بالله من الشيطان الرجيم: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ ۝ وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنتُمْ تَعْلَمُونَ [البقرة:278-280] صدق الله العظيم، فسروا لنا هذه الآيات لو سمحتم وما هو رأس المال المذكور في هذه الآية؟","title":"ما معنى: {اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا}؟","answer":"الجواب: كان أهل الجاهلية قبل البعثة بعثة النبي ﷺ يرابون، يبيعون المتاع من أرض أو إبل أو غير ذلك بالثمن إلى أجل فإذا حل الأجل وصار المدين معسرًا قالوا له: إما أن تعطينا حقنا وإما أن تربي، إما أن تقضي وإما أن تربي، المعنى: إما أن تعطينا حقنا الآن أو نزيد عليك في المال ونؤخر الأجل نفسح لك في الأجل، فإن كان عنده مال سلم لهم وإلا رضي بهذا.\nفإذا كانت القيمة مثلًا مائة ريال قالوا: نؤجلك أيضًا ستة أشهر أو عشرة أشهر تكون المائة مائة وعشرين مائة وثلاثين هذه الزيادة في مقابل الأجل الجديد، وهذا معنى: إما أن تربي وإما أن تقضي، تربي يعني: تقبل الزيادة تعطيه الزيادة وهي الربا، وإما أن تقضينا حقنا الآن، فلما جاء الله بالإسلام نهاهم عن هذا وخطبهم النبي في حجة الوداع عليه الصلاة والسلام وأخبرهم أن الربا موضوع، وأن لكل واحد رأس ماله فقط، وأنزل الله جل وعلا هذه الآيات، يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ [البقرة: 278-279]. فأمرهم سبحانه أن يذروا يعني: يتركوا ما بقي من الربا لهم في ذمم الناس، ويأخذوا رأس المال فإذا كانت السلعة بمائة وأمهلوه وزادوا عليه عشرين يتركون العشرين أو ثلاثين يتركون الثلاثين يأخذوا رأس المال فقط والزيادة يتركونها، هذا معنى: وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا [البقرة:278]، وإذا كانوا قد قبضوا رأس المال وبقي الربا يتركونه ما يأخذون الربا يكفيهم رأس المال، ثم قال: فَإِنْ لَمْْ تَفْعَلُوا [البقرة:279] يعني: فإن لم تدعوا الربا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ [البقرة:279] يعني: فاعلموا بحرب يعني: اعلموا أنكم محاربون لله ورسوله وهذا وعيد عظيم لم يأت مثله في شيء من المعاصي، وهو يدل على عظم جريمة الربا وأنها جريمة عظيمة وكبيرة عظيمة.\nولهذا ثبت عنه ﷺ: أنه لعن آكل الربا وموكله وكاتبه وشاهديه وقال: هم سواء، فالربا من أقبح الكبائر، وفي الحديث الصحيح يقول ﷺ: اجتنبوا السبع الموبقات قالوا: وما هن يا رسول الله؟! قال: الشرك بالله، والسحر، وقتل النفس التي حرم الله إلا بالحق، وأكل الربا فجعله الرابع وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف يعني: يوم الحرب وقذف المحصنات الغافلات المؤمنات فجعل الربا من السبع الموبقات يعني: المهلكات. ثم قال سبحانه: وَإِنْ تُبْتُمْ [البقرة:279] يعني: من الربا فَلَكُمْ رُءُوسُُ أَمْوَالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ [البقرة:279]، يعني: لهم رأس المال فقط وهو المبلغ الذي بيعت به السلعة إلى أجل، الزيادة تبطل فإذا كان باع المطية أو السيارة إلى رمضان مثلًا من عام ألف وأربعمائة وإحدى عشر بألف ريال بعشرة آلاف بخمسين ألف ريال ثم حل الثمن فإنه يأخذ رأس المال فقط ولا يطلب زيادة وإن أعسر ننظره؛ ولهذا قال: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ[البقرة:280]، إذا جاء رمضان قال: أنا ما عندي أنا: معسر وثبت إعساره فإنه يمهل بدون زيادة ولا يأخذ ربا، هذا هو معنى قوله جل وعلا: وَإِنْ تُبْتُم فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ [البقرة:279] يعني: إذا تبتم من الربا فلكم رءوس أموالكم التي عند الناس ما بعد قبضتموها لا تَظْلِمُونَ وَلا تُظْلَمُونَ [البقرة:279] يقبض رأس المال ويترك الربا الزيادة وإن كان قد قبض رأس المال وبقيت الزيادة يترك الزيادة لا يأخذها لا تَظْلِمُونَ بأخذ الزيادة وَلا تُظْلَمُونَ بمنعكم من رأس المال لكم رأس المال، فأنت لا تظلم بمنعك من رأس مالك لا، تعطى رأس مالك، وليس لك أن تظلم أخاك بأخذ الربا بل لك رأس المال فقط.\nفإن كان المدين معسرًا عاجزًا بالبينة الشرعية فإنه يمهل ولا يطالب بالزيادة لقوله سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنتُمْ تَعْلَمُونَ [البقرة:280]، إن تصدق عليه وأبرأه فجزاه الله خيرًا هذا طيب، وإلا فالواجب الإنظار إلى ميسرة، يقول أنا أنظرك إلى ميسرة، والواجب على المدين تقوى الله إن كان صادقًا في الإعسار فعليه أن يتقي الله ويتسبب حتى يحضر المال، وإن كان كاذبًا فقد ظلم أخاه فليتق الله وليؤد حقه إذا ادعى الإعسار وهو يكذب.\nالمقصود: أن المدين عليه أن يتقي الله فإن كان صادقًا في الإعسار وجب إمهاله وإن ثبت أنه مليء وجب أخذ الحق منه والحاكم ينظر في ذلك ويعتني، وإذا كان صاحب الدين يعلم أنه معسر فلا حاجة إلى المحكمة يمهله وينظره حتى يحصل له اليسر وإن تصدق عليه وسامحه فقد فعل خيرًا كثيرًا، يقول النبي ﷺ: من سره أن ينفس الله عنه كربات يوم القيامة فلينفس عن معسر أو يضع عنه، من سره أن ينفس الله عنه كرب يوم القيامة فلينفس عن معسر أو يضع عنه، ينفس أي: بإنظاره أو يضع عنه يعني: بالصدقة عليه، وفي الحديث الآخر: من أنظر معسرًا أو وضع له أظله الله يوم القيامة يوم لا ظل إلا ظله، وهذا فضل عظيم.\nفينبغي للمؤمن إذا عرف أن أخاه معسر -المدين- أن ينظره أو يسامحه الدين كله أو بعضه يرجو ما عند الله من المثوبة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12604/ما-معنى-اتقوا-الله-وذروا-ما-بقي-من-الربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48508.mp3","categories":["التفسير"]},{"id":14186,"question":"أخونا يقول: سمعت عن قصة الخضر مع موسى عليه السلام، أرجو أن تتفضلوا بذكر السورة التي وردت فيها تلكم القصة، وخاصة ما حدث من بناء الخضر للجدار لأهل القرية رغم أنهم لم يحسنوا الضيافة؟","title":"اسم السورة التي وردت فيها قصة الخضر","answer":"الجواب: قصة الخضر ثابتة في كتاب الله العظيم في سورة الكهف تقرأ سورة الكهف فتجدها، والخضر على الصحيح نبي من الأنبياء، هذا هو الصحيح، ولهذا علمه الله أشياء ما علمها موسى عليه الصلاة والسلام، ولهذا رغب موسى في صحبته ليتعلم منه ما أخبره الله به؛ لأنه أخبره  بأن في مجمع البحرين بأن لنا في مجمع البحرين عبدًا فذهب فطلب موسى لقياه ليتعلم منه فأذن الله له في ذلك واجتمع به في مجمع البحرين وقص الله علينا قصتهم في سورة الكهف وهي قصة واضحة وبينة لا تحتاج إلى شرح. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/12639/اسم-السورة-التي-وردت-فيها-قصة-الخضر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48602.mp3","categories":["التفسير"]},{"id":14342,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من جمهورية مصر العربية هو عمر غانم إبراهيم، أخونا عمر له ثلاثة أسئلة في أحد أسئلته يسأل عن تفسير الجلالين، يقول: إن هذا التفسير مشتمل على كثير من الأحاديث، والمؤلف لا يقول إلا قال الرسول ﷺ، ولكن ليس يخرج الأحاديث فهل كل الأحاديث الواردة في تفسير الجلالين من الأحاديث الصحيحة؟","title":"هل كل الأحاديث في تفسير الجلالين صحيحة؟","answer":"الجواب: تفسير الجلالين تفسير مفيد مختصر نافع، لكن فيه أحاديث ضعيفة، وفيه تأويل لبعض الصفات، فينبغي التحرز من ذلك وأن لا يعتمد عليه في هذه الأمور، وطالب العلم يراجع ما فيه ويسأل أهل العلم عما أشكل عليه حتى لا يقع في الغلط؛ لأن السيوطي رحمه الله ليس بمحقق في معرفة الأحاديث صحيحها من سقيمها، وله كتابه المعروف الجامع الصغير والجامع الكبير فيها الضعيف وفيها الصحيح.  فالجلالين تفسير الجلالين له وللمحلي مشترك بينه وبين المحلي فيه أحاديث ضعيفة، وفيه أشياء تخالف العقيدة الصحيحة، فينبغي للمؤمن الذي يطالعه ألا يعتمد عليه، بل يراجع كلام أهل العلم من أهل السنة والجماعة فيما أشكل عليه من جهة العقيدة، ويراجع كلام أئمة الحديث فيما رأى فيه من الأحاديث الضعيفة، يعني من الأحاديث التي لا يدري عنها مثل: تلخيص الحبير للحافظ ابن حجر ، مثل: نصب الراية للزيلعي، وغيرها من الكتب التي توضح الصحيح من الضعيف. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12821/هل-كل-الاحاديث-في-تفسير-الجلالين-صحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62304.mp3","categories":["التفسير"]},{"id":14371,"question":"ما الفرق بين الهلع والجزع؟","title":"الفرق بين الهلع والجزع","answer":"الجواب: الهلع يطلق على الجميع، إِنَّ الإِنسَانَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا [المعارج:19-21] من هلعه من ضعفه وقلة صبره، يكون جزوع ومنوع، جزوع عندما يصيبه نكبة، منوع عندما يحصل له المال بسبب شدة البخل، فهو صفته هلوع إلا من رحمه الله، ورزقه البصيرة والاستقامة، وثبات القلب على الحق هذا يسلمه الله من هذا. لكن جنس الإنسان هلوع إلا من رزقه الله الإيمان والثبات والحق والاستقامة، فإنه لا يكون هلوعًا، إن مسه الشر صبر، وجاهد نفسه في إبعاده، وإن مسه الخير شكر الله، وأنفقه في وجوه البر، فهو شكور عند الرخاء، صبور عند البلاء، هكذا المؤمن، لكن غالب الناس ليس كذلك هلوع، غالب الخلق هلوع، ليس عنده صبر وعند الشدة، وليس عنده شكر عند الرخاء، هذه حال غالب الناس. أما المؤمن لا، شكور عند الرخاء، صبور عند البلاء، كما قال ﷺ: عجبًا لأمر المؤمن إن أمره كله له خير، إن أصابته ضراء صبر فكان خيرًا له، وإن أصابته سراء شكر فكان خيرًا له هكذا المؤمن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12852/الفرق-بين-الهلع-والجزع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55113.mp3","categories":["التفسير"]},{"id":14380,"question":"هذا السائل سليمان من الأردن يقول: أستفسر عن الآية الكريمة في قوله تعالى: إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ ظَالِمِي أَنفُسِهِمْ قَالُوا فِيمَ كُنتُمْ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الأَرْضِ قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا [النساء:97].","title":"تفسير قوله تعالى: {إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ ظَالِمِي أَنفُسِهِمْ..}","answer":"الجواب: هذه الآية فيمن تخلف عن الهجرة بغير عذر شرعي، الله -جل وعلا- عتب عليهم ذلك، فالواجب على من كان بين المشركين، ولا يظهر دينه أن يهاجر، ولا يجوز له التأخر عن الهجرة، سماهم ظَالِمِي أَنْفُسِهِمْ[النساء: 97] يعني: بترك الهجرة؛ لأن ترك الهجرة مع القدرة معصية، فالواجب على من كان بين المشركين أن يهاجر وينتقل إلى بلاد المسلمين إذا قدر؛ لهذه الآية الكريمة؛ ولقول النبي ﷺ: أنا بريء من كل مسلم يقيم بين المشركين ويروى عنه  أنه قال: من جامع المشرك وسكن معه فهو مثله. فالواجب على من كان بين المشركين أن ينتقل وأن يهاجر إذا استطاع ذلك، إِلَّا الْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ لا يَسْتَطِيعُونَ حِيلَةً وَلا يَهْتَدُونَ سَبِيلًا * فَأُوْلَئِكَ عَسَى اللَّهُ أَنْ يَعْفُوَ عَنْهُمْ وَكَانَ اللَّهُ عَفُوًّا غَفُورًا [النساء:98-99] من عجز فلا حرج عليه، لكن من قدر أن ينتقل من بلاد الشرك إلى بلاد الإسلام وجب عليه أن يهاجر، وصار بقاؤه بين المشركين ظلمًا لنفسه، ومعصية يستحق عليها العقوبة؛ ولهذا توعدهم بالنار، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12861/تفسير-قوله-تعالى-ان-الذين-توفاهم-الملاىكة-ظالمي-انفسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55203.mp3","categories":["التفسير"]},{"id":14390,"question":"يسأل عن الآية الكريمة: إِنَّا أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَاحِدَةً فَكَانُوا كَهَشِيمِ الْمُحْتَظِرِ [القمر:31]؟","title":"تفسير قوله تعالى: {إِنَّا أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَاحِدَةً..}","answer":"الجواب: هؤلاء أصحاب ثمود، عذبوا لما عصوا وخالفوا، وعقروا الناقة، أرسل الله الصيحة، فكانوا كهشيم المحتظر، نعوذ بالله، هذا جزاؤهم في الدنيا، غير جزاؤهم في الآخرة والعذاب في الآخرة، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12872/تفسير-قوله-تعالى-انا-ارسلنا-عليهم-صيحة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55213.mp3","categories":["التفسير"]},{"id":14412,"question":"يقول السائل: ما الفرق بين الأيام المعدودات والأيام المعلومات؟","title":"الفرق بين الأيام المعدودات والمعلومات","answer":"الجواب: الله -جل وعلا- بين المعدودات، وهي أيام التشريق وَاذْكُرُوا اللَّهَ فِي أَيَّامٍ مَعْدُودَاتٍ فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلا إِثْمَ عَلَيْهِ [البقرة:203] هذه ثلاثة؛ الحادي عشر، والثاني عشر، والثالث عشر، هذه المعدودات.  والمعلومات أيام العشر، مع أيام التشريق. وقال جماعة: إنها أيام العشر فقط. وقال آخرون: إنها أيام العشر مع أيام التشريق كلها معلومات يكبر فيها، يكبر المسلمون فيها من أول العشر إلى غروب الشمس من يوم الثالث عشر لِيَشْهَدُوا مَنَافِعَ لَهُمْ وَيَذْكُرُوا اسْمَ اللَّهِ فِي أَيَّامٍ مَعْلُومَاتٍ عَلَى مَا رَزَقَهُمْ مِنْ بَهِيمَةِ الأَنْعَامِ[الحج:28] فيذكروا الله في الأيام المعلومات من أول الشهر إلى نهاية اليوم الثالث عشر إلى غروب الشمس، يكبروا الله، ويذكروه سبحانه، فهي أيام عظيمة فاضلة، والثلاثة منها معدودات، وهي الأخيرة الحادي عشر والثاني عشر والثالث عشر، وهي أيام منى، وأيام رمي الجمار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12894/الفرق-بين-الايام-المعدودات-والمعلومات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55309.mp3","categories":["التفسير"]},{"id":14417,"question":"شعبان صبحي، من جمهورية مصر العربية، يقول: أستفسر عن الآية الكريمة في سورة الفلق: وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ [الفلق:3].","title":"تفسير قوله تعالى: {وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ}","answer":"الجواب: فسر بالقمر، وفسر بالليل، الغاسق: الليل، إذا أقبل الليل قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ[الفلق:1] الفلق: الصبح مِنْ شَرِّ مَا خَلَقَ * وَمِنْ شَرِّ غَاسِقٍ [الفلق:2-3] إقبال الليل، هذا هو المشهور، وفسر بالقمر، والأقرب والأظهر -والله أعلم- أنه إقبال الليل، نعم.","link":"https://binbaz.org.sa/fatwas/12899/تفسير-قوله-تعالى-ومن-شر-غاسق-اذا-وقب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55313.mp3","categories":["التفسير"]},{"id":14445,"question":"السائلة أم خالد من الرياض، تقول: ما تفسير هذه الآية: خُلِقَ الإِنسَانُ مِنْ عَجَلٍ [الأنبياء:37] في سورة الأنبياء؟","title":"تفسير قوله تعالى: {خُلِقَ الإِنسَانُ مِنْ عَجَلٍ}","answer":"الجواب: على ظاهرها، خلق آدم خلقه الله من تراب، وفي الآية الأخرى من طين، تراب لما عجن بالماء صار طينًا، ثم صار طينًا لازبًا، ثم حمأ مسنونًا، ثم صلصال كالفخار، جاء في الحديث: أنه لما نفخت فيه الروح أراد أن يقوم قبل أن تسكن الروح بدنه من عجلته؛ ولهذا قال تعالى: خُلِقَ الإِنسَانُ مِنْ عَجَلٍ [الأنبياء:37] وقال -جل وعلا-: وَكَانَ الإِنسَانُ عَجُولًا [الإسراء:11]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12912/تفسير-قوله-تعالى-خلق-الانسان-من-عجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55403.mp3","categories":["التفسير"]},{"id":14446,"question":"في سؤالها الثاني تقول في الآية الكريمة: وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ [الأنبياء:41] ما سبب نزول هذه الآية؟","title":"سبب نزول قوله تعالى: {وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ...}","answer":"الجواب: سببها التسلية للرسول ﷺ، يقول: لا تجزع، فقد استهزئ بالرسل من قبلك فإن قريشًا تستهزئ به، وكفارهم وغير كفارهم يستهزئون به، فالله يسليه ويعزيه ويقول له: لا تألم من هذا، ولا تحزن من هذا، فإن الرسل قبلك كذلك قد استهزئ بهم، فلك فيهم الأسوة، كما كذبوا كذبت، وكما استهزئ بهم استهزئ بك، فلا بد من الصبر؛ ولهذا قال في الآية الأخرى: فَاصْبِرْ كَمَا صَبَرَ أُوْلُوا الْعَزْمِ مِنَ الرُّسُلِ وَلا تَسْتَعْجِلْ لَهُمْ [الأحقاف:35]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12913/سبب-نزول-قوله-تعالى-ولقد-استهزى-برسل-من-قبلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55404.mp3","categories":["التفسير"]},{"id":14453,"question":"السائل محمود فتحي محمد يقول: من هو ذو القرنين؟ وما هي قصته؟","title":"ما هي قصة ذي القرنين؟","answer":"الجواب: قصته في القرآن ذكرها الله في القرآن، يكفي ما في القرآن واضح، ذكرها الله في آخر سورة الكهف، فاقرأ سورة الكهف، وتعرفها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12924/ما-هي-قصة-ذي-القرنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55411.mp3","categories":["التفسير"]},{"id":14552,"question":"السائل شعبان صبحي، من جمهورية مصر العربية، ومقيم بالقريات، يستفسر عن الآيتين الكريمتين في سورة البروج: وَشَاهِدٍ وَمَشْهُودٍ [البروج:3] من هو الشاهد ومن هو المشهود في هذه الآية؟","title":"تفسير قوله تعالى: {وَشَاهِدٍ وَمَشْهُودٍ}","answer":"الجواب: للعلماء في هذا كلام كثير، وأحسن ما قيل فيه: أن الشاهد يوم الجمعة، والمشهود يوم عرفة، يوم الجمعة شاهد، ومشهود يوم الجمعة، يشهده الناس الحجاج، وقيل غير ذلك، لكن هذا أحسن ما قيل، وَالسَّمَاءِ ذَاتِ الْبُرُوجِ ۝ وَالْيَوْمِ الْمَوْعُودِ [البروج:1-2] يوم القيامة، وَشَاهِدٍ [البروج:3] يوم الجمعة، وَمَشْهُودٍ [البروج:3] يوم عرفة، هذا هو أحسن ما قيل في ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13049/تفسير-قوله-تعالى-وشاهد-ومشهود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55512.mp3","categories":["التفسير"]},{"id":14553,"question":"الآية الثانية يا سماحة الشيخ: قُتِلَ أَصْحَابُ الأُخْدُودِ [البروج:4] يقول: من هم أصحاب الأخدود؟","title":"من هم أصحاب الأخدود؟","answer":"الجواب: جماعة من الكفرة والظلمة عذبوا المؤمنين، بأن أخدوا لهم أخاديد، وجعلوا فيها النيران، نسأل الله العافية، الله -جل وعلا- ذمهم، قال: قُتِلَ أَصْحَابُ الأُخْدُودِ ۝ النَّارِ ذَاتِ الْوَقُودِ ۝ إِذْ هُمْ عَلَيْهَا قُعُودٌ ۝ وَهُمْ عَلَى مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ [البروج:4-7] يعني: ناس من الكفرة الملحدين ظلموا المؤمنين، وجعلوا لهم خدودًا عذبوا من لم يطاوعهم. نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13050/من-هم-اصحاب-الاخدود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55513.mp3","categories":["التفسير"]},{"id":14563,"question":"على بركة الله، نبدأ هذا اللقاء برسالة وصلت من السائلة (ج. ج) من جمهورية مصر العربية، تقول: أرجو من سماحة الشيخ أن يبين لي في الآية الكريمة: لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] هل ذلك في الميراث فقط؟ أم في جميع الأشياء من مأكل ومشرب وملبس، وسواء كان الأولاد أطفال صغار أم رجال ونساء كبار؟ وجهونا في ضوء ذلك يا سماحة الشيخ.","title":"تفسير قوله تعالى: {لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ}","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالتفضيل بين الذكر والأنثى في الميراث هو نص القرآن الكريم، قال الله -جل وعلا-: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] في سورة النساء، وقال في آخرها: يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلالَةِ إِنْ امْرُؤٌ هَلَكَ لَيْسَ لَهُ وَلَدٌ وَلَهُ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ وَهُوَ يَرِثُهَا إِنْ لَمْ يَكُنْ لَهَا وَلَدٌ فَإِنْ كَانَتَا اثْنَتَيْنِ فَلَهُمَا الثُّلُثَانِ مِمَّا تَرَكَ وَإِنْ كَانُوا إِخْوَةً رِجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ يُبَيِّنُ اللَّهُ لَكُمْ أَنْ تَضِلُّوا وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ [النساء:176] ، هذا في المواريث. أما غير المواريث ففيه تفصيل: إذا كان عند الإنسان أولاد بعضهم أغنياء وبعضهم فقراء، فإنه يلزمه إذا كان قادرًا أن ينفق على الفقراء، حتى يسد حاجتهم.  وأما الأغنياء فلا يلزمه أن يعطيهم مثلما يعطي الفقراء؛ لأن هذه ليست عطية، ولا مواريث، إنما هي نفقة واجبة، وهكذا لو كان عنده أطفال نساء وذكور كبار أغنياء، فإنه ينفق على النساء حاجاتهن، وليس للذكور حق في ذلك؛ لأنها من باب النفقة لا من باب العطية، ولا من باب الإرث، وإنما التسوية في العطية، كما قال النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم يسوى بينهم في العطية كالإرث للذكر مثل حظ الأنثيين إذا أعطى الذكر ألفين أعطى الأنثى ألف غير النفقة. أما النفقة فإنها على حسب الحاجة، فإذا كان الولد غنيًا، والبنت فقيرة، أنفق على البنت والعكس إذا كان الولد فقيرًا والبنت غنية أنفق على الولد ولا يلزمه في هذا التسوية ولا التفضيل، وهذا أمر معلوم عند جميع أهل العلم، وفق الله الجميع، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/13060/تفسير-قوله-تعالى-للذكر-مثل-حظ-الانثيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55601.mp3","categories":["التفسير"]},{"id":14606,"question":"هذا السائل صالح محمد من اليمن، يقول في هذا ما المقصود في قوله تعالى في سورة يوسف رَوْحِ اللَّهِ [يوسف:87] في الآية رقم السابعة والثمانين؟ جزاكم الله خيرًا.","title":"بيان المقصود بقوله تعالى: (رَوْحِ اللَّهِ)","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nالمعنى: النهي عن اليأس من رحمة الله وإحسانه وجوده، رَوْحِ اللَّهِ رحمته وإحسانه إلى عباده، وإنعامه عليهم -جل وعلا-، الإنسان منهي عن اليأس، يقول -جل وعلا- في الآية الأخرى: لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53] فسرها قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53] في سورة يوسف: وَلا تَيْئَسُوا مِنْ رَوْحِ اللَّهِ [يوسف:87] يعني: من رحمته وإحسانه وفرجه وتيسيره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13098/بيان-المقصود-بقوله-تعالى-روح-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55901.mp3","categories":["التفسير"]},{"id":14611,"question":"هذا سائل للبرنامج، أرسل بمجموعة من الأسئلة، يقول في هذا  خلق الله  السماوات والأرض في ستة أيام، وقد ورد هذا في القرآن الكريم؛ ولقد قال الله  في سورة فصلت: قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِالَّذِي خَلَقَ الأَرْضَ فِي يَوْمَيْنِ [فصلت:9] وفي قوله تعالى: فَقَضَاهُنَّ سَبْعَ سَمَوَاتٍ فِي يَوْمَيْنِ [فصلت:12] ما المقصود في الآيتين؟جزاكم الله خيراً.","title":"مدة خلق السماوات والأرض","answer":"الجواب: خلق السماوات والأرض كلها في ستة أيام، وما بينهما أيضًا، فبدأ بخلق الأرض في يومين، ثم استوى إلى السماء، وخلق السماء في يومين، ثم دحا الأرض في أربعة أيام: وَالأَرْضَ بَعْدَ ذَلِكَ دَحَاهَا ۝ أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا [النازعات:30-31]، فِي أَرْبَعَةِ أَيَّامٍ سَوَاءً لِلسَّائِلِينَ [فصلت:10] فالأرض خلقها في يومين، ودحوها في أربعة أيام، دحها بعد الخلق، دَحَاهَا ۝ أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا ۝ وَالْجِبَالَ أَرْسَاهَا [النازعات:30-32] فهذه ستة أيام، السماوات والأرض في ستة أيام، أصل السماء في يومين، والأرض في يومين ودحو الأرض في أربعة أيام، ، فالله -جل وعلا- دحاها يعني: أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا [النازعات:31] فخلقها ودحوها في أربعة أيام والسماء في يومين الجميع ستة أيام؛ ولهذا قال بعدها: فَقَضَاهُنَّ سَبْعَ سَمَوَاتٍ فِي يَوْمَيْنِ وَأَوْحَى فِي كُلِّ سَمَاءٍ أَمْرَهَا [فصلت:12] نعم، الله أكبر. المقدم: الله أكبر، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13107/مدة-خلق-السماوات-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55905.mp3","categories":["التفسير","مسائل متفرقة في العقيدة"]},{"id":14640,"question":"الرسالة التالية: رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أخوكم في الإسلام من العراق صلاح محمد شعبان، سؤالي: أرجو أن تتفضلوا بتفسير الآية الكريمة، وهي قوله تعالى: أعوذ بالله من الشيطان الرجيم: أَلَمْ تَرَ إِلَى الَّذِينَ خَرَجُوا مِنْ دِيَارِهِمْ وَهُمْ أُلُوفٌ حَذَرَ الْمَوْتِ [البقرة:243] الآية؟","title":"تفسير قوله تعالى: {أَلَمْ تَرَ إِلَى الَّذِينَ خَرَجُوا...}","answer":"الجواب: على ظاهرها، على ظاهرها، أن يبين  أن الفرار من الموت لا يمنع الموت، ولا يمنع من قدر الله شيء ، فالواجب على المؤمن أن يستعد للقاء الله، وأن يعمل الصالحات، وأن يتوب من السيئات، حتى إذا هجم عليه الأجل إذا هو قد استعد للقاء ربه بطاعته، والتوبة إليه.  أما فراره من بلد إلى بلد، أو من مستشفى إلى مستشفى؛ ليسلم من الموت، فهذا لا ينجيه من عذاب الله، ولا يمنع الموت من المجيء إليه، الأجل متى وصل لم يمنع منه مانع، كما قال : وَلَنْ يُؤَخِّرَ اللَّهُ نَفْسًا إِذَا جَاءَ أَجَلُهَا [المنافقون:11] قال سبحانه: إِذَا جَاءَ أَجَلُهُمْ فَلا يَسْتَأْخِرُونَ سَاعَةً وَلا يَسْتَقْدِمُونَ [يونس:49] ولهذا قال: فَقَالَ لَهُمُ اللَّهُ مُوتُوا ثُمَّ أَحْيَاهُمْ [البقرة:243]. فالمقصود: أن الخروج من البلاد، أو من القبيلة، أو من إقليم إلى إقليم، أو من حي إلى حي لأجل خوف الموت لا يمنع من الموت، كما قال الله سبحانه: أَيْنَمَا تَكُونُوا يُدْرِكُّمُ الْمَوْتُ وَلَوْ كُنتُمْ فِي بُرُوجٍ مُشَيَّدَةٍ [النساء:78] فالموت لا بد منه، كما قال سبحانه: كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ الْقِيَامَةِ [آل عمران:185].\nفالواجب الإعداد للموت، والتأهب بالأعمال الصالحات، بأداء فرائض الله، بترك محارم الله، بالوقوف عند حدود الله، بالتوبة إليه من سائر المعاصي، بالتعاون على الخير، بالتواصي بالحق، والصبر عليه، هذا هو الواجب على أهل الإسلام، ولا ينبغي أن يغرهم الشيطان بأن صحتهم أو فرارهم إلى مستشفيات راقية، أو إلى بلاد صحية، أو إلى غير هذا من أسباب الحياة، أو من أسباب الرفاة، أو من أسباب الصحة لا ينبغي أن يغرهم هذا، فإن الموت لا يمنعه مانع، ولو كان في أصح البلاد، ولو كان في أرقى مستشفى، متى جاء الأجل لم يمنعه مانع، كما سمعت من الآيات الكريمات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13157/تفسير-قوله-تعالى-الم-تر-الى-الذين-خرجوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62710.mp3","categories":["التفسير","الرقائق"]},{"id":14692,"question":"في آخر أسئلة هذه السائلة من مكة المكرمة (ن. ش. ح) تستفسر عن الآية الكريمة في سورة المائدة: مَا جَعَلَ اللَّهُ مِنْ بَحِيرَةٍ وَلا سَائِبَةٍ وَلا وَصِيلَةٍ وَلا حَامٍ [المائدة:103]؟","title":"تفسير قوله تعالى: {مَا جَعَلَ اللَّهُ مِنْ بَحِيرَةٍ...}","answer":"الجواب: هذه أشياء كان الجاهلية يفعلونها، ثم نسخها الله، وأنكر عليهم، البحيرة والسائبة هذه كلها أشياء جاهلية، يفعلونها، فأنكرها الله عليهم، ونهاهم عنها وأبطلها، والله -جل وعلا- أباح لهم إبلهم وبقرهم وغنمهم، وليس فيه بحيرة الأصنام ولا سائبة ولا وصيلة ولا حام.  وقد فسر العلماء هذه الأشياء في كتب التفسير، فمن أراد ذلك يراجع تفسير ابن كثير وتفسير البغوي وغيرهما من التفاسير يجد مطلوبه -إن شاء الله-.","link":"https://binbaz.org.sa/fatwas/13185/تفسير-قوله-تعالى-ما-جعل-الله-من-بحيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56017.mp3","categories":["التفسير"]},{"id":14693,"question":"الآية الكريمة سماحة الشيخ: وَأُحْضِرَتِ الأَنفُسُ الشُّحَّ [النساء:128] تريد تفسيرًا لها أيضًا؟","title":"تفسير قوله تعالى: {وَأُحْضِرَتِ الأَنفُسُ الشُّحَّ}","answer":"الجواب: هذا مثلما ظاهر القرآن، الأنفس من صفاتها الشح والبخل، إلا من رحم الله، فالواجب على المؤمن أن يتقي ذلك، ويحذر الشح والبخل، ويعتاد الجود والسخاء، وعدم البخل والشح.  يقول النبي ﷺ: اتقوا الشح، فإنه أهلك من كان قبلكم والله يقول سبحانه في كتابه العظيم: وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [الحشر:9] من صفات العباد الشح والبخل إلا من عصم الله، إلا من رحم الله، والشح: الحرص على المال بكل وسيلة من حلال وحرام، ثم إذا وجده بخل به، فالشحيح حريص على طلب المال بكل طريق، ثم إذا وجده بخل به أيضًا، والشح شره عظيم؛ ولهذا قال سبحانه: وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [الحشر:9] ويقول النبي ﷺ: اتقوا الشح، فإنه أهلك من كان قبلكم واتقوا الظلم، فإن الظلم ظلمات يوم القيامة الله المستعان. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13188/تفسير-قوله-تعالى-واحضرت-الانفس-الشح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56018.mp3","categories":["الأخلاق المذمومة","التفسير"]},{"id":14783,"question":"يستفسر عن الآية الكريمة في سورة النمل، أعوذ بالله من الشيطان الرجيم: وَتَرَى الْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِيَ تَمُرُّ مَرَّ السَّحَابِ صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ إِنَّهُ خَبِيرٌ بِمَا تَفْعَلُونَ [النمل:88]؟","title":"تفسير قوله تعالى: {وَتَرَى الْجِبَالَ تَحْسَبُهَا جَامِدَةً...}","answer":"الجواب: هذا يوم القيامة، تمر مر السحاب، يوم القيامة كما قال -جل وعلا-: وَيَسْأَلُونَكَ عَنِ الْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّي نَسْفًا [طه:105] وفي الآية الأخرى: وَسُيِّرَتِ الْجِبَالُ فَكَانَتْ سَرَابًا [النبأ:20] يعني: يوم القيامة، نعم ما هو في الدنيا، هي في الدنيا راكدة هادئة ثابتة، الله أرساها وجعلها أوتادًا للأرض في حال الدنيا، قال تعالى: وَأَلْقَى فِي الأَرْضِ رَوَاسِيَ أَنْ تَمِيدَ بِكُمْ [النحل:15]، رَوَاسِيَ يعني الجبال، أَنْ تَمِيدَ يعني: لئلا تميد بكم؛ لئلا تضطرب بكم، ويوم القيامة تسير هذه الجبال، وتذهب وتضمحل، كما قال تعالى: وَسُيِّرَتِ الْجِبَالُ فَكَانَتْ سَرَابًا [النبأ:20] قال تعالى: وَيَسْأَلُونَكَ عَنِ الْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّي نَسْفًا  ۝ فَيَذَرُهَا قَاعًا صَفْصَفًا ۝ لا تَرَى فِيهَا عِوَجًا وَلا أَمْتًا [طه:105-107]، نعم.","link":"https://binbaz.org.sa/fatwas/13272/تفسير-قوله-تعالى-وترى-الجبال-تحسبها-جامدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56110.mp3","categories":["التفسير"]},{"id":14787,"question":"أيضًا يستفسر عن الآية الكريمة سماحة الشيخ: أَفَلا يَرَوْنَ أَنَّا نَأْتِي الأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا أَفَهُمُ الْغَالِبُونَ [الأنبياء:44]؟","title":"ما معنى: {أَفَلا يَرَوْنَ أَنَّا نَأْتِي الأَرْضَ نَنقُصُهَا}؟","answer":"الجواب: ذكر جمع من أهل العلم أن نقصها من أطرافها موت العلماء، وأن العلماء يموتون شيئًا فشيئًا، وتشتد غربة الإسلام، كما قال النبي ﷺ: بدأ الإسلام غريبًا، وسيعود غريبًا كما بدأ ومن غربته قلة العلماء، نعم.","link":"https://binbaz.org.sa/fatwas/13274/ما-معنى-افلا-يرون-انا-ناتي-الارض-ننقصها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56111.mp3","categories":["التفسير"]},{"id":14789,"question":"في آخر أسئلته يستفسر عن هذه الآية: وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالأَعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا... [النحل:67] الآية؟","title":"تفسير قوله تعالى: {وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالأَعْنَابِ...}","answer":"الجواب: هذا كان في أول الإسلام يتخذون من ثمرات النخيل والأعناب السكر -الخمر- حين كانت مباحة، ثم نسخ الله ذلك وحرمها في قوله -جل وعلا-: إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ [المائدة:90] في سورة المائدة فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ [المائدة:90] والنبي ﷺ: «لعن الخمر وشاربها، وساقيها، وحاملها والمحمولة إليه، وعاصرها ومعتصرها، وبائعها ومشتريها، وآكل ثمنها» وكانت في الأول مباحة يشربها الناس في مكة، وفي أول الإسلام، في أول الهجرة، ثم حرمها الله في المدينة، ولعن شاربها، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13277/تفسير-قوله-تعالى-ومن-ثمرات-النخيل-والاعناب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56112.mp3","categories":["التفسير"]},{"id":14827,"question":"من السودان هذه الرسالة بعث بها المستمع هشام عثمان عبدالله، يقول في رسالته:قال الله تعالى في كتابه الكريم: وَإِذْ قُلْنَا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ كَانَ مِنَ الْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ أَفَتَتَّخِذُونَهُ وَذُرِّيَّتَهُ أَوْلِيَاءَ مِنْ دُونِي وَهُمْ لَكُمْ عَدُوٌّ بِئْسَ لِلظَّالِمِينَ بَدَلًا [الكهف:50] هذه الآية توضح لنا أن الله عندما أمر الملائكة بالسجود لـ آدم ولم يسجد إبليس، فكيف يؤاخذه الله  على أمر لم يدخل إبليس في نطاقه؛ لأنه ليس من الملائكة، ما دام إبليس من الجن وليس من الملائكة فكيف يشمله أمر السجود؟","title":"كيف شمل إبليس أمر السجود وهو ليس من الملائكة؟","answer":"الجواب: العلماء لهم في هذا قولان: أحدهما: أنه من الملائكة، من طائفة يقال لهم: الجن، من الملائكة، فلهذا شمله الأمر، وحكم الله عليه بالبعد واللعنة؛ لأنه عصى الأمر.\nوالأمر الثاني: أنه كان معهم، يتعبد معهم، وأنه خوطب معهم، وأمر معهم بأن يسجد؛ لأنه كان معهم، وقد صحبهم في العبادة، فلهذا ورد عليه الأمر معهم، فعصى فعاقبه الله باللعنة والطرد؛ بسبب عصيانه للأوامر الموجهة إليه، وإن كان ليس منهم عنصرًا فهو منهم في العمل، وقد وجه إليه الخطاب والأمر معهم، فعصى واستكبر، فلهذا أصابته العقوبة، وحلت عليه اللعنة. إما لكونه منهم وهم طائفة يقال لهم: الجن، أو لأنه صار معهم، وتلبس بأعمالهم وصحبهم في أعمالهم، وصدر الأمر إليه وإليهم جميعًا، فلما وجه إليه الأمر معهم صار مستحقًا للعنة بعصيانه واستكباره، وهذا أمر واضح، والقولان مشهوران للعلماء؛ أحدهما: أنه منهم فلا إشكال في ذلك، والثاني: أنه أبو الجن، أو جن معروفين من الثقل الثاني وهو كـ آدم للإنس، ولكنه صار مع الملائكة حين الأمر، ووجه إليه الأمر معهم، وصار مأمورًا كما أنهم مأمورون، فلهذا استحق اللعنة والطرد باستكباره وعصيانه، نعم.","link":"https://binbaz.org.sa/fatwas/13337/كيف-شمل-ابليس-امر-السجود-وهو-ليس-من-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64316.mp3","categories":["مسائل متفرقة في العقيدة","التفسير"]},{"id":14875,"question":"المستمع محمد الهاشم من الأردن، بعث يسأل ويقول: فسروا لي قول الحق -تبارك وتعالى- أعوذ بالله من الشيطان الرجيم، بسم الله الرحمن الرحيم: الرَّحْمَنُ ۝ عَلَّمَ الْقُرْآنَ [الرحمن:1-2].","title":"تفسير قوله تعالى: {الرَّحْمَنُ * عَلَّمَ الْقُرْآنَ}","answer":"الجواب: على ظاهرها، الرحمن سبحانه علم نبيه القرآن، هو الذي علمه بواسطة جبرائيل، وهو الذي يعلم عباده إذا وفقهم حفظوه وقرؤوه، وهو المعلم لهم سبحانه، والموفق لهم -جل وعلا-، وإن كان لا يعلمهم بصوته سبحانه، لكن علم جبرائيل، وجبرائيل علم النبي ﷺ، وقد سمع النبي ﷺ من كلام ربه، حين عرج به إلى السماء سمع كلام ربه ، وهكذا موسى سمع كلام ربه.  لكن تعليم القرآن كان بواسطة جبرائيل -عليه الصلاة والسلام-، والله علم عباده القرآن بواسطة من يعلمهم، ومن يتلوه عليهم ويلقنهم، فهو المعلم، هو الذي وفق المعلمين وهداهم وأعانهم، فهو المعلم وهو الموفق -جل وعلا-، وهو الهادي  بفضله وإحسانه، وما يجعله في القلوب ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13373/تفسير-قوله-تعالى-الرحمن-علم-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64516.mp3","categories":["التفسير"]},{"id":15069,"question":"على بركة الله، نبدأ هذا اللقاء بتفسير الآية الكريمة، يطلب الأخ تفسير هذه الآيات: أعوذ بالله من الشيطان الرجيم: شَهِدَ اللَّهُ أَنَّهُ لا إِلَهَ إِلَّا هُوَ وَالْمَلائِكَةُ وَأُوْلُوا الْعِلْمِ قَائِمًا بِالْقِسْطِ [آل عمران:18]؟","title":"تفسير قوله تعالى: {شَهِدَ اللَّهُ أَنَّهُ لا إِلَهَ إِلَّا هُوَ...}","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذه الآية الكريمة من أعظم الآيات الواردة في إثبات توحيد الله ، والشهادة بأنه سبحانه هو المعبود بالحق، يبين فيها -جل وعلا- أنه شهيد بنفسه، وهو أعظم شاهد  أنه لا إله إلا هو، كما قال -جل وعلا-: فَاعْلَمْ أَنَّهُ لا إِلَهَ إِلَّا اللَّهُ [محمد:19] وقال سبحانه: وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ [البقرة:163] وقال سبحانه: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62]، فشهد في هذه الآية -آية آل عمران- أنه سبحانه لا إله إلا هو، المعنى: لا إله حق سواه، الآلهة كثيرة يعبدها المشركون من أصنام، وجن، وملائكة، وأشجار، وغير ذلك، لكن كلها باطلة، كلها آلهة باطلة، والإله الحق هو الله وحده ؛ ولهذا قال -جل وعلا-: شَهِدَ اللَّهُ أَنَّهُ لا إِلَهَ إِلَّا هُوَ [آل عمران:18] وشهد له بذلك أيضًا الملائكة الكرام، وهم من أعدل الشهود، وشهد بذلك أيضًا أولو العلم الذين عرفوا الحق، ودانوا به، وهم أولو العلم بالقرآن والسنة، يشهدون أيضًا لله بالوحدانية. وهذه الآية فيها منقبة عظيمة للملائكة ولأولي العلم، وأن الله استشهدهم على وحدانيته؛ لأنهم يعلمون ذلك، وهم عدول، فالملائكة من خير عباد الله، كما قال الله -جل وعلا-: وَهُمْ مِنْ خَشْيَتِهِ مُشْفِقُونَ ۝ لا يَسْبِقُونَهُ بِالْقَوْلِ وَهُمْ بِأَمْرِهِ يَعْمَلُونَ ۝ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى وَهُمْ مِنْ خَشْيَتِهِ مُشْفِقُونَ [الأنبياء:27-28] فيشهدون لربهم بأنه الإله الحق  منهم: جبرائيل وميكائيل وإسرافيل، وغيرهم، وهكذا أولو العلم من سابق الزمان، وآجل الزمان، من عهد آدم -عليه الصلاة والسلام-، ومن بعده من الرسل والعلماء إلى يومنا هذا، وإلى أن يقبض الله أرواح المؤمنين في آخر الزمان، كل العلماء الذين عرفوا الحق، ودرسوا كتاب الله، وسنة رسوله ﷺ، كلهم يشهدون بأنه سبحانه هو الإله الحق، وهم خلفاء الرسل، والرسل هم أئمة العلماء، والأنبياء هم أئمة العلماء، وأتباعهم من أهل العلم يشهدون بهذا، يعني: علماء السنة، علماء الحق الذين تفقهوا في دين الله، وعرفوا ما دل عليه كتاب الله، وسنة رسوله ﷺ يشهدون أن الله سبحانه هو الإله الحق، وأنه المستحق للعبادة، وأنه هو لا إله إلا هو ولا رب سواه -جل وعلا-، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13560/تفسير-قوله-تعالى-شهد-الله-انه-لا-اله-الا-هو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56401.mp3","categories":["التفسير"]},{"id":15178,"question":"هذا سائل للبرنامج: عبدالله الحسن، يقول: أرجو من سماحة الشيخ أن يبين لي في قوله تعالى في سورة مريم يَا أُخْتَ هَارُونَ مَا كَانَ أَبُوكِ امْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا [مريم:28] وعندما أرسل الله موسى إلى فرعون في قوله تعالى: وَأَخِي هَارُونُ هُوَ أَفْصَحُ مِنِّي لِسَانًا فَأَرْسِلْهُ مَعِي رِدْءًا يُصَدِّقُنِي [القصص:34] فهل هارون أخو مريم وأخو موسى؟","title":"هل هارون أخو موسى هو أخو مريم؟","answer":"الجواب: الصواب: أن هارون أخو مريم ليس هو هارون أخو موسى؛ لأن موسى وهارون بينهما وبين زمن مريم مدة طويلة، فـهارون هذا اسم لأخ لـمريم غير هارون أخي موسى، نعم.","link":"https://binbaz.org.sa/fatwas/13669/هل-هارون-اخو-موسى-هو-اخو-مريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56420.mp3","categories":["التفسير"]},{"id":15322,"question":"هذا سائل من اليمن، إب، يقول يا سماحة الشيخ: نرجو من فضيلتكم أن تفسروا لنا الآية الكريمة: وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ [الرحمن:46]؟","title":"تفسير قوله تعالى: {ولمن خاف مقام ربه جنتان}","answer":"الجواب: هذه آيات عظيمة، تدل على أن من خاف مقام الله، فهو من أهل الجنتين العاليتين العظيمتين؛ لأن خوف الله الصادق يحمل على أداء الفرائض، وترك المحارم، والمسارعة إلى كل خير، من خاف الله صادقًا سارع إلى كل خير، وابتعد عن كل شر؛ فلهذا وعده الله الجنتين العظيمتين، وهما الجنتان العاليتان بالنسبة للجنتين الأخريين، قال تعالى: إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ [الملك:12] ومن الأجر الكبير دخول الجنة، والنجاة من النار، قال تعالى: إِنَّ الَّذِينَ هُمْ مِنْ خَشْيَةِ رَبِّهِمْ مُشْفِقُونَ  ۝ وَالَّذِينَ هُمْ بِآيَاتِ رَبِّهِمْ يُؤْمِنُونَ  ۝  وَالَّذِينَ هُمْ بِرَبِّهِمْ لا يُشْرِكُونَ  ۝  وَالَّذِينَ يُؤْتُونَ مَا آتَوا وَقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَى رَبِّهِمْ رَاجِعُونَ  ۝ أُوْلَئِكَ يُسَارِعُونَ فِي الْخَيْرَاتِ وَهُمْ لَهَا سَابِقُونَ [المؤمنون:57-61]. فالخوف إذا عظم واشتد أوجب على الخائف أداء فرائض الله، وترك محارم الله، والمسارعة إلى كل خير؛ فلهذا صار في المنزلة العالية في الجنة: وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ [الرحمن:46] ومن ادعى الخوف وهو يفرط في طاعة الله، أو يرتكب معاصي الله؛ فقد كذب؛ خوفه ضعيف، الخوف الصادق يحمل أهله على أداء فرائض الله، وترك محارم الله، والمسارعة إلى كل خير، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13822/تفسير-قوله-تعالى-ولمن-خاف-مقام-ربه-جنتان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56610.mp3","categories":["التفسير"]},{"id":15393,"question":"يستفسر عن معنى الآية الكريمة في سورة البقرة: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196]؟","title":"معنى قوله تعالى: {وأتموا الحج والعمرة لله}","answer":"الجواب: على ظاهرها، يجب على من دخل فيهما أن يتمهما؛ من أحرم بالحج يجب عليه أن يكمل، ومن أحرم بالعمرة يجب عليه أن يكمل، إلا إذا اشترط قال: إن حبسني حابس، فهو على شرطه، وإلا فالواجب أنه إذا دخل في الحج يكمل، وإذا دخل في العمرة يكمل.","link":"https://binbaz.org.sa/fatwas/13895/معنى-قوله-تعالى-واتموا-الحج-والعمرة-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56718.mp3","categories":["التفسير","حكم الحج والعمرة"]},{"id":15432,"question":"هذه رسالة من المستمع عزالدين حسن الدليمي، من العراق، محافظة الأنبار، يقول: قال الله تعالى: وَإِذْ قَالَ رَبُّكَ لِلْمَلائِكَةِ إِنِّي جَاعِلٌ فِي الأَرْضِ خَلِيفَةً قَالُوا أَتَجْعَلُ فِيهَا مَنْ يُفْسِدُ فِيهَا وَيَسْفِكُ الدِّمَاءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّي أَعْلَمُ مَا لا تَعْلَمُونَ[البقرة:30] يقول: هل معنى هذا أن الله خلق الإنسان قبل آدم  إذًا: فكيف عرفت الملائكة أن الإنسان يفسد في الأرض، ويسفك الدماء؟ وما القصد من أن الله جاعل في الأرض خليفة وخليفةً عمن؟","title":"تفسير قوله تعالى: {وَإِذْ قَالَ رَبُّكَ لِلْمَلائِكَةِ...}","answer":"الجواب: الآية الكريمة تدل على أن الله -جل وعلا- جعل هذا الإنسان، وهو آدم -عليه الصلاة والسلام- خليفةً في الأرض عمن كان فيها من أهل الفساد، وعدم الاستقامة.  وقول الملائكة يدل على أنه كان هناك قوم يفسدون في الأرض، فبنت ما قالت على ما جرى في الأرض، أو لأسباب أخرى اطلعت عليها، فقالت ما قالت، فأخبرهم الله  بأنه يعلم ما لا تعلمه الملائكة، وأن هذا الخليفة يحكم في الأرض بشرع الله، ودين الله، وينشر الدعوة إلى توحيده، والإخلاص له، والإيمان به، وهكذا ذريته بعده يكون فيهم الأنبياء، ويكون فيهم الرسل والأخيار والعلماء الصالحون والعباد المخلصون إلى غير ذلك مما حصل في الأرض من العبادة لله وحده، وتحكيم شريعته، والأمر بما أمر به، والنهي عما نهى عنه، هكذا جرى من الأنبياء والرسل والعلماء الصالحين والعباد المخلصين إلى غير ذلك، وظهر أمر الله في ذلك، وعلمت الملائكة بعد ذلك هذا الخير العظيم. ويقال: إن الذي قبل آدم إنهم طوائف من الناس، ومن الخليقة يقال لهم: الجن والحن.\nوبكل حال فهو خليفة لمن مضى قبله، وصار قبله في أرض الله، ممن يعلمهم الله ، وليس لدينا أدلة قاطعة في بيان من كان هناك قبل آدم وصفاتهم وأعمالهم، ليس هناك ما يبين هذا الأمر، لكن جعله خليفة يدل على أن هناك من قبله في الأرض فهو يخلفهم في إظهار الحق، وبيان شريعة الله التي شرع له، وبيان ما يرضي الله، ويقرب لديه، وينهى عن الفساد فيها، وهكذا من جاء بعده من ذريته قاموا بهذا الأمر العظيم من الأنبياء والصلحاء والأخيار دعوا إلى الحق، ووضحوا الحق، وأرشدوا إلى دين الله، وعمروا الأرض بطاعة الله وتوحيده، والحكم بشريعته، وأنكروا على من خالف ذلك، نعم، الله المستعان. المقدم: أحسن الله إليكم وحفظكم.","link":"https://binbaz.org.sa/fatwas/13949/تفسير-قوله-تعالى-واذ-قال-ربك-للملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_685/nour_68506.mp3","categories":["التفسير"]},{"id":15445,"question":"هذا السائل يقول: قال الله تعالى في كتابه العزيز: فَالآنَ بَاشِرُوهُنَّ وَابْتَغُوا مَا كَتَبَ اللَّهُ لَكُمْ وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ [البقرة:187] ما هو الخيط الأبيض وما هو الأسود؟ وكيف يعرف ذلك، وخاصة إذا كان في المدينة ضوء ويكثر فيها الضوء؟أفيدونا بهذا.","title":"معنى {حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ...}","answer":"الجواب: المراد بذلك الصبح والليل، الخيط الأبيض نور الصبح، والأسود ظلمة الليل، فإذا اتضح الفجر أمسك عن الأكل والشرب، الصائم، ودخل وقت صلاة الفجر، والخيط عبارة عن الصبح والليل. فالمؤمن يأكل ويشرب إذا كان في الصيام، حتى يتبين هذا، ولا يصلي صلاة الفريضة، حتى يتبين الخيط الأبيض من الخيط الأسود عن الفجر، وإذا ضبط ذلك بحساب الساعات على طريقة مضبوطة نفع ذلك، وكفى، لكن إذا كان في محل يمكن الصبح ينظر الصبح، كالذي في السفر في البر، وكأهل البوادي وكالقرى التي ما في عندهم أنوار، قد يرون الصبح بسهولة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13959/معنى-حتى-يتبين-لكم-الخيط-الابيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50014.mp3","categories":["التفسير"]},{"id":15459,"question":"هذا سؤال من المستمعة فاطمة رمضان إبراهيم، من بورسودان، تقول: ما هو القول الصحيح في عدد أهل الكهف؟ وهل هم أصحاب الصخرة أم أنهم غيرهم؟ فإن كان كذلك فمن هم إذًا أصحاب الصخرة؟ وما هي قصتهم؟","title":"من هم أصحاب الكهف وأصحاب الصخرة؟","answer":"الجواب: أهل الكهف بيَّنهم الله في كتابه العظيم، والأقرب مثل ما قال جماعة من أهل العلم أنهم سبعة، وثامنهم كلبهم، هذا هو الأقرب والأظهر، وهم أناس مؤمنون، فتية آمنوا بربهم، وزادهم الله هدىً، وفارقوا قومهم من أجل الشرك والكفر، فلما توفاهم الله بعد ذلك بعدما ناموا المدة الطويلة، توفاهم الله بعد ذلك على دينهم الحق، هؤلاء هم أهل الكهف كما بيَّن الله في كتابه، فتية آمنوا بربهم، وزادهم الله هدى، وناموا النومة الطويلة بإذن الله، ثم ماتوا بعد ذلك وبنى عليهم بعض أهل الغلبة هناك من الأمراء والرؤساء مسجدًا. وقد أخطؤوا في ذلك وغلطوا؛ لأن القبور لا يبنى عليها، الرسول ﷺ نهى عن ذلك، وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وحذر من البناء على القبور وتجصيصها، واتخاذ المساجد عليها، كل هذا نهى عنه النبي ﷺ ولعن من فعله. فلا يجوز للمسلمين أن يبنوا على القبور مساجد، ولا قبابًا ولا غير ذلك، بل تكون القبور ضاحية، ضاحيةً للشمس والأمطار ليس عليها بناء لا قبة ولا مسجد ولا غير ذلك، هكذا كانت قبور المسلمين في عهد النبي ﷺ وفي عهد الخلفاء الراشدين، حتى غيَّر الناس بعد ذلك، وبنوا على القبور، وهذا من الجهل والغلط، قال النبي ﷺ: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد قالت عائشة -رضي الله عنها-: \"يحذر ما صنعوا\" وقال -عليه الصلاة والسلام- لما أخبرته أم حبيبة و أم سلمة في أرض الحبشة لما كانتا في أرض الحبشة عن كنيسة فيها تصاوير قال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور ثم قال: أولئك أشرار الخلق عند الله فأخبر أنهم شرار الخلق بسبب بناؤهم على القبور واتخاذهم الصور عليها، نسأل الله السلامة.\nوقال -عليه الصلاة والسلام- فيما رواه جندب في صحيح مسلم: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك فنهى ﷺ عن اتخاذ القبور مساجد وحذر من هذا، وبيَّن أنه من عمل من قبلنا العمل المذموم، فلا يجوز للمسلمين أن يتخذوا قبابًا، ولا مساجد على قبور أمواتهم، بل هذا منكر ومن وسائل الشرك، نعم.\nالمقدم: عن سؤاله عن أصحاب الصخرة؟\nالشيخ: أما أصحاب الصخرة فهم أناس خرجوا يتمشون فآواهم المبيت والمطر إلى غار في جبل، فلما دخلوا انحدرت عليهم صخرة فسدت عليهم باب الغار، فقالوا فيما بينهم: لا ينجيكم من هذا إلا أن تدعوا الله بصالح أعمالكم التي فعلتوها لله، فقال أحدهم: اللهم إنه كان لي أبوان شيخان كبيران، وكنت لا أغبق قبلهما أهلاً ولا مالًا -الغبوق: سقي اللبن الحليب-، قال فنأى بي طلب الشجر ذات ليلة فلم أرح عليهما، يعني: الإبل إلا وقد ناما فوقفت بالقدح أنتظر استيقاظهما، فلم يستيقظا حتى برق الصبح، والصبية يتضاغون تحت قدمي، اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك، فافرج عنا ما نحن فيه، فانفرجت الصخرة شيئًا قليلاً لا يستطيع معه الخروج. ثم قال الثاني: اللهم إنه كانت لي ابنة عم، وكنت أحبها كأشد ما يحب الرجال النساء، وإني أردتها على نفسها فأبت فألمت بها سنة -يعني: حاجة في بعض السنين- فجاءت إلي تطلبني فقلت لها: لا حتى تمكنيني من نفسك، فوافقت على ذلك على مائة وعشرين دينار، فسلمها لها، فلما جلس بين رجليها، قالت: اتق الله، ولا تفض الخاتم إلا بحقه، فقام خوفًا من الله، وتركها، وترك الذهب لها، ثم قال: اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة أيضًا لكن لا يستطيعون الخروج. ثم قال الثالث: اللهم إني استأجرت أجراء فأعطيت كل أجير حقه إلا أجيرًا واحدًا كان فرق من أرز فتركه فثمرته له حتى اشتريت منه رقيقًا وإبلًا وبقرًا وغنمًا، فجاء بعد ذلك، وقال: أعطني حقي، فقلت: يا عبدالله، كل هذا من حقك، فقال: اتق الله، ولا تستهزئ بي، فقلت له: إني لا أستهزئ بك، بل هذا كله من حقك، فأخذه واستاقه جميعًا، اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك، فافرج عنا ما نحن فيه، فانفرجت الصخرة وخرجوا يمشون. فهذا دليل على أن الله على كل شيء قدير، وأنه سبحانه هو يبتلي عباده بالسراء والضراء، وهذا الحديث صحيح رواه البخاري ومسلم في الصحيحين عن ابن عمر عن النبي ﷺ، هو حديث صحيح فيه عبرة، وفيه إرشاد إلى الضراعة إلى الله، وسؤاله عند الكروب والشدات، وأنه سبحانه قريب مجيب يسمع دعاء الداعي، ويجيب دعوته إذا شاء ، وأن الأعمال الصالحات من أسباب تفريج الكروب، ومن أسباب تيسير الأمور، ومن أسباب إزالة الشدة، والمؤمن إذا وقع في الشدة يضرع إلى الله ويسأله، ويتوسل إليه بأعماله الصالحة بإيمانه بالله ورسوله بتوحيده والإخلاص له، والإخلاص لله. فهذه هي الأسباب وهذه هي الوسائل الشرعية، والله سبحانه من فضله وإحسانه يجيب دعوة المضطر، ويرحم عبده المؤمن، ويجيب سؤاله كما قال سبحانه: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ[البقرة:186] وهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ[غافر:60] وهو القائل : أَمَّنْ يُجِيبُ الْمُضطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ[النمل:62] . فهؤلاء مضطرون نزل بهم أمر عظيم، وكربة شديدة، فسألوا الله بصالح الأعمال، فأجاب الله دعاءهم، وفي هذا من الفوائد فضل بر الوالدين، وأن بر الوالدين من أفضل القربات، ومن أسباب تفريج الكروب، وتيسير الأمور، وهكذا العفة عن الزنا والحذر من الزنا من الأعمال الصالحات، ومن أسباب تفريج الكروب، ومن أسباب النجاة من كل شدة، وهكذا أداء الأمانة والنصح في أداء الأمانة من أعظم الأسباب في تفريج الكروب، ومن أفضل الأعمال الصالحات، فهذه الأعمال الصالحة من أسباب النجاة في الدنيا، والنجاة في الآخرة.\nالمقدم: هل يعلم الزمان الذي حدثت فيه هذه القصة؟ الشيخ: كان فيمن قبلنا، قبل مبعث النبي ﷺ، وأما الزمان فلا نعلمه، لكنه فيمن قبلنا قبل بعثة النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/13993/من-هم-اصحاب-الكهف-واصحاب-الصخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68706.mp3","categories":["مسائل متفرقة في العقيدة","التفسير"]},{"id":15593,"question":"وهذه رسالة في البداية بعث بها المستمع (ح. م . ص) من جدة، ضمنها ثلاثة أسئلة:في سؤاله الأول يقول: ما معنى قوله تعالى: إِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ[البقرة:284]؟ وكيف نجمع بين معناها وبين الحديث الشريف الذي معناه: أن الله تعالى تجاوز عن أمة محمد ما حدثت به أنفسها ما لم تفعله أو تتكلم به؟ نعم.","title":"الجمع بين: {إِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ...}و«إن الله تجاوز عن أمتي»","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذه الآية الكريمة قد أشكلت على كثير من الصحابة  لما نزلت، وهي قوله تعالى: لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ[البقرة:284] شق عليهم هذا الأمر، وجاؤوا إلى النبي ﷺ وذكروا أن هذا شيء لا يطيقونه، فقال لهم ﷺ: أتريدون أن تقولوا كما قال من قبلكم: سمعنا وعصينا؟ قولوا: سمعنا وأطعنا فقالوا: سمعنا وأطعنا، فلما قالوها وذلت بها ألسنتهم، أنزل الله بعدها قوله سبحانه: آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۝ لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286] الآية. فسامحهم الله، وعفا ، ونسخ ما دل عليه مضمون هذه الآية، وأنهم لا يؤاخذون إلا بما عملوا، وبما أصروا عليه، وثبتوا عليه، وأما ما يخطر من الخطرات في النفوس والقلوب، فهذا معفو عنه؛ ولهذا صح عن رسول الله ﷺ أنه قال: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تكلم فزال هذا الأمر، والحمد لله، وصار المؤمن غير مؤاخذ إلا بما عمله، أو قاله، أو أصر عليه بقلبه عملًا بقلبه، كإصراره على ما يقع له من الكبر والنفاق، ونحو ذلك. أما الخواطر التي تعرض، والشكوك التي تعرض ثم تزول بالإيمان واليقين، فهذه لا تضر، بل هي عارضة من الشيطان، ولا تضر؛ ولهذا لما قال الصحابة: «يا رسول الله، إن أحدنا يجد في قلبه ما لئن يخر من السماء أسهل عليه من أن ينطق به -أو كما قالوا- قال: ذاك صريح الإيمان وفي لفظ: تلك الوسوسة فهي من الشيطان، إذا رأى من المؤمن الصدق والإخلاص، وصحة الإيمان، والرغبة فيما عند الله، وسوس عليه بعض الشيء، وألقى في قلبه خواطر خبيثة، فإذا جاهدها وحاربها بالإيمان والتعوذ بالله من الشيطان، سلم من شرها؛ ولهذا جاء في الحديث الآخر يقول -عليه الصلاة والسلام-: لا يزال الناس يتساءلون حتى يقولوا: هذا الله خلق كل شيء فمن خلق الله؟ فمن وجد ذلك فليقل: آمنت بالله ورسله وفي لفظ: فليستعذ بالله ولينته. فهذا يدلنا على أن الإنسان عرضة للوساوس الشيطانية، فإذا عرض له وساوس خبيثة، وخطرات منكرة، فليبتعد عنها؛ وليقل: آمنت بالله ورسله، أعوذ بالله من الشيطان الرجيم؛ ولينته، ولا يلتفت إليها، فإنها باطلة ولا تضره، وهي من الخطرات التي عفا الله عنها ، نعم.","link":"https://binbaz.org.sa/fatwas/14136/الجمع-بين-ان-تبدوا-ما-في-انفسكم-وان-الله-تجاوز-عن-امتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_694/nour_69401.mp3","categories":["التفسير","شروح الحديث"]},{"id":15594,"question":"هذا السائل محمد إمام حسن، مصري، يعمل بالجوف، يقول: يقول الله تعالى: وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ[الشورى:30] ويقول: قُلْ لَنْ يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا[التوبة:51] فما معنى الآيتين؟ وكيف نجمع بينهما؟ علمًا أن ظاهرهما التعارض.","title":"الجمع بين آيتين في كسب الإنسان وما كتب الله عليه","answer":"الجواب: ليس هناك تعارض يا أخي، فالله -جل وعلا- بيّن لنا أن ما أصابنا هو بأسباب كسبنا، وبين أن ما يقع هو بقضائه وقدره، قُلْ لَنْ يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا[التوبة:51] فقد سبق علمه وقدره بكل شيء، ولكنه سبحانه علق ما أصابنا مما يضرنا أنه بأسباب معاصينا، وإن كانت مكتوبة مقدرة، لكن لنا كسب، ولنا عمل، ولنا اختيار، فكل شيء يقع بقدر من الطاعات والمعاصي، فما وقع منا من معاصي فهو معتبر من كسبنا، ومن عملنا، ونحن مؤاخذون به، إذا فعلناه، وعندنا عقولنا، فنحن مؤاخذون به؛ ولهذا قال سبحانه: وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ[الشورى:30] وفي الآية الأخرى: مَا أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ اللَّهِ وَمَا أَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ[النساء:79] فلا تنافي بين القدر وبين العمل، فالقدر سابق، ولله الحجة البالغة ، والأعمال أعمالنا، فالزنا وشرب الخمر، وترك الصلاة والعقوق وقطيعة الرحم من أعمالنا، ونحن نستحق عليها العقوبة بسبب تفريطنا وتقصيرنا؛ لأن لنا اختيارًا، ولنا عملًا ينسب إلينا، وإن كان سبق في علم الله كتابته وتقديره، فالقدر ليس حجة على فعل المعايب والمنكرات.  فالله له  الحكمة البالغة فيما مضى به قدره وعلمه وكتابته، ونحن مسئولون عن أعمالنا وعن أخطائنا وتقصيرنا ومؤاخذون بذلك إلا أن يعفو ربنا عنا. وبهذا تعلم أنه لا منافاة بين الآيتين، فإحداهما تدل على أن أعمالنا من كسبنا، وأنا نستحق عليها العقوبة؛ لأنها أعمال لنا باختيارنا، والآية الأخرى تدل على أنه قد مضى في علم الله كتابتها وتقديرها، وقد صح عن رسول الله ﷺ أنه قال: إن الله قدر مقادير الخلائق قبل أن يخلق السماوات والأرض بخمسين ألف سنة، وعرشه على الماء فهو سبحانه الحكيم العليم العالم بكل شيء الذي سبق علمه بكل شيء  وكتب كل شيء.  وفي الآية الأخرى يقول : مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الأَرْضِ وَلا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا إِنَّ ذَلِكَ عَلَى اللَّهِ يَسِيرٌ[الحديد:22] فكتاب الله سابق، وعلمه سابق ، وقدره سابق، وأعمالنا محصاة علينا، ومنسوبة إلينا، ومكتوبة علينا، وهي من كسبنا وعملنا واختيارنا. فنجزى على الطيب الجزاء الحسن من الطاعات، وأنواع الخير والذكر، ونستحق العقاب على سيئها من العقوق والزنا والسرقة وسائر المعاصي والمخالفات، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/14142/الجمع-بين-ايتين-في-كسب-الانسان-وما-كتب-الله-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_694/nour_69405.mp3","categories":["التفسير"]},{"id":15639,"question":"وهذه أولى الرسائل وردت من المستمع: عبدالجليل عبدالله الحجاج من القطيف تاروت، ضمن رسالته سؤالين:سؤاله الأول يقول فيه: قال الله تعالى في القرآن الكريم: أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَئِنَّا لَمَبْعُوثُونَ[الصافات:16] يقول: لماذا قدمت كلمة التراب قبل العظام، بينما العظام هي تتحول إلى تراب؟ وهل هناك سر بلاغي في ذلك أم لا؟","title":"سر تقديم التراب على العظام في آية الصافات","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذا السؤال لا أعلم معنى واضحًا أستطيع الجزم به في وجه تقديم التراب على العظام، ولكن قد يقال -والله أعلم- والعلم عند الله : أنه قدم التراب؛ لأن التراب أشد في المعجزة؛ لأن إعادة من كان ترابًا أعظم من إعادة من هو عظام، ولم تزل حاله عظامًا، فبدأ بالأشد وهو التراب على ما هو أخف وهو العظام، فإعادة من هو عظام أسهل في الظاهر من إعادة من قد ذهب وصار ترابًا، هذا هو الأظهر، والله أعلم. أما الجزم فإلى الله  هو الأعلم بكل شيء، لكن هذا هو الظاهر أنه السر في ذلك البداءة بالأشد في القدرة والأعظم في...، للدلالة على أن المعيد لهذا الإنسان قادر على كل شيء ، فإن إعادة من كان ترابًا أشد في الظاهر من إعادة من كان عظامًا فقط.\nفإذا ذكر هذا وهذا، كان من باب بيان كمال قدرته ، نعم. المقصود: أنهم سألوا عن هذا؛ لأن من كان ترابًا أشد بدؤوا بالتراب؛ لأن إعادة من كان ترابًا أشد وأدل على القدرة، على كمال القدرة ممن لم يزل عظامًا، نعم.","link":"https://binbaz.org.sa/fatwas/14191/سر-تقديم-التراب-على-العظام-في-اية-الصافات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_698/nour_69801.mp3","categories":["التفسير"]},{"id":15684,"question":"أما الآن فننتقل إلى رسالة المستمعة: أم معاذ، تقول في رسالتها: ما معنى قوله تعالى: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا [مريم:71]؟ وهل حقًا أن المؤمن التقي يدخل النار ويعذب؟","title":"تفسير قوله تعالى: {وإن منكم إلا واردها}","answer":"الجواب: الآية فسرها النبي ﷺ، وأن المراد بالورود: المرور على الصراط، فالكل يمر على الصراط، والصراط: منصوب على متن جهنم، فالكافر لا يمر يسقط في النار، يساق إلى النار، ويدخل في النار، نسأل الله العافية، والمؤمن ينجو، ولا يسقط فيها؛ ولهذا قال سبحانه: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا ۝ ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا [مريم:71-72] فالكفار يساقون إليها، والمسلمون يمرون على الصراط وينجون.\nومن المسلمين من يخدش، ثم ينجو، ومنهم من يسقط في النار بأسباب معاصيه. فهذا يوجب الحذر، وأن يستقيم المؤمن على تقوى الله، ويحذر معصيته حتى ينجيه الله من النار حال المرور، وقبل المرور. والمقصود: أن الورود هو: المرور، فيمر المتقون والمؤمنون ولا يضرهم شيء والحمد لله. وأما الكافرون فلا يمرون، بل يساقون إلى النار، وقد يسقط بعض المارين من المسلمين بأسباب معاصيهم، فيبقى في النار ما شاء الله، ثم يخرجه الله من النار بأسباب موته على التوحيد والإسلام، هذا الذي عليه أهل السنة والجماعة: أن العصاة يدخل بعضهم النار، ويعذبون فيها بسبب معاصيهم، لكن لا يخلدون، بل لهم أمد ينتهون إليه، فإذا تم الأمد وانتهى ما قسمه الله، وما قدره الله عليهم من العذاب يخرجون من النار إلى الجنة، ولا يبقى في النار إلا الكفار، يخلدون فيها أبد الآباد، نعوذ بالله من ذلك. وأما المتقون فإنهم يمرون، ولا يسقطون، كما قال -جل وعلا-: ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا [مريم:72] نسأل الله السلامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14235/تفسير-قوله-تعالى-وان-منكم-الا-واردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57205.mp3","categories":["التفسير"]},{"id":15751,"question":"أيضًا يسأل تفسير قول الحق -تبارك وتعالى-: لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِنْ فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ[البقرة:226].","title":"تفسير قوله تعالى: {لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ...}","answer":"الجواب: الآية في الإيلاء، والإيلاء: اليمين، يؤلون يعني: يحلفون لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ [البقرة: 226] يحلفون من نسائهم أن لا يطؤوهن أربعة فوق أربعة أشهر، فإذا قال: والله لا أطؤك خمسة أشهر أو سنة؛ فإنه يوقف بعد مضي أربعة أشهر:  لو تربص أربعة أشهر فقط، فإن فاء -رجع- ووطئها؛ فالحمد لله، وعليه كفارة اليمين. وإن لم يرجع، وطلبت إيقافه؛ فالحاكم الشرعي يوقفه، ويقول له: إما أن تفيء، وإما أن تطلق، حسب طلبها، وإن سمحت وتركته حتى يتمِّم يمينه فلا بأس. فإذا قال: والله لا أطؤك خمسة أشهر، أو ستة أشهر، يعني: أكثر من أربعة أشهر؛ فهي بالخيار: إن صبرت؛ فلا بأس، ولا كفارة عليه. وإن لم تصبر فلها أن تطالب بأن يفيء بعد أربعة أشهر، يعني: بأن يطأها، فإذا وطئها كفر عن يمينه؛ لأنه وطئها قبل أن تتم المدة، وعليه كفارة يمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14340/تفسير-قوله-تعالى-للذين-يولون-من-نساىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74102.mp3","categories":["الإيلاء","التفسير"]},{"id":15808,"question":"رسالة من المستمع عبدالله خليفة من الزلفي، يقول: أنا من المتابعين لبرنامجكم نور على الدرب، والحمد لله، وأريد من سماحتكم التكرم بالإجابة على هذا السؤال وهو:قال الله تعالى: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ[البقرة:225] الآية، ما معنى اللغو في الأيمان؟جزاكم الله خيرًا.","title":"معنى اللغو في الأيمان","answer":"الجواب: الآية واضحة، يقول سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ[البقرة:225] وفي الآية الأخرى: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ[المائدة:89] كسب القلوب نيتها وقصدها، فكسب القلوب: الإيمان بالله والمحبة لله والخوف من الله، والرجاء له  كل هذا من كسب القلوب، وهكذا نية الحالف يعني: قصده اليمين، وإقراره عليها، هذا من كسب القلوب. أما اللغو كونه يتكلم باليمين من غير قصد جرت على لسانه، من غير قصد، والله ما أقوم، والله ما أتكلم، والله ما أذهب إلى كذا، ما نواها، ما تعمدها، جرت على لسانه، لكن من غير قصد، يعني: من غير قصد عقد اليمين على هذا الشيء، من غير قصد القلب أنه يفعل هذا الشيء هذا هو لغو اليمين، قول الرجل: لا والله، وبلى والله، كما جاء هذا المعنى عن عائشة وغيرها -رضي الله عن الجميع-. أما إذا نوى اليمين بقلبه وقصدها، قال: والله ما أكلم فلانًا، قاصدًا بقلبه أنه ما يكلمه، أو والله ما أزوره، أو والله ما أفعل كذا، ما أشرب الدخان، والله ما أشرب الخمر، فهذا عليه كفارة اليمين، إذا نقض يمينه عليه كفارة اليمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فإن عجز عن الثلاثة صام ثلاثة أيام؛ لقوله -جل وعلا-: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ[المائدة:89] الآية في سورة المائدة. والمقصود: أن الأيمان اللاغية هي التي لا تقصد تجري على اللسان من غير قصد، فهذا يسمى لغو اليمين، وليست منعقدة، وليست من كسب القلوب، أما إذا عقدها قاصدًا لها بقلبه، فهذا من كسب القلوب، وهذا من تعقيد الأيمان، فعلى صاحب هذه اليمين إذا خالفها أن يكفر كفارة اليمين كما تقدم، فإذا قال: والله لا أكلم فلانًا قاصدًا، ثم كلمه عليه كفارة اليمين، والله لا أزوره ثم زاره عليه كفارة اليمين، والله لا أسافر إلى كذا ثم سافر عليه كفارة اليمين، بخلاف ما إذا مر على لسانه اليمين من غير قصد ما تعمده ولا قصده، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14396/معنى-اللغو-في-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74311.mp3","categories":["التفسير"]},{"id":15820,"question":"يستفسر عن الآية الكريمة يا سماحة الشيخ ثُمَّ إِذَا شَاءَ أَنْشَرَهُ [عبس:22].","title":"تفسير قوله تعالى: {ثم إذا شاء أنشره}","answer":"الجواب: أنشره يعني: بعثه من قبره يوم القيامة، يبعثهم من قبورهم إذا شاء، لا يعلم متى هذا؟ إلا الله ، متى تقوم الساعة؟ لا يعلم هذا إلا الله ، نعم.","link":"https://binbaz.org.sa/fatwas/14409/تفسير-قوله-تعالى-ثم-اذا-شاء-انشره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57512.mp3","categories":["التفسير"]},{"id":15883,"question":"رسالة أخرى من مستمع رمز إلى اسمه بالحروف (ف. أ) من الرياض، يقول: كيف نجمع بين قوله ﷺ: سبعون ألفًا من أمتي يدخلون الجنة بلا حساب ولا عقاب أو كما قال ﷺ، وبين قوله -تبارك وتعالى-: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا[مريم:71]؟","title":"الجمع بين حديث السبعين ألفًا والورود على جهنم","answer":"الجواب: ليس بين الآية وبين الحديث اختلاف، والورود: هو المرور على الصراط، وكل الناس يمرون عليه، كل أهل الجنة يمرون عليه؛ لأنه الطريق إلى دخول الجنة، فالصراط منصوب على متن جهنم، فيمر أولهم عليه كالبرق وكلمح البصر، ثم كالريح، ثم كالطير، ثم كأجاود الخيل، والركاب تجري بهم أعمالهم، فهذا مرور ليس فيه عذاب، وإنما هو مرور بغير عذاب إلا من أراد الله -جل وعلا- تعذيبه من العصاة الذين قد تخطفهم الكلاليب، ويسقطون في النار لمعاصيهم وكبائرهم التي لم يتوبوا إلى الله منها،.....، بكلاليب تخطف الناس بأعمالهم، لا يعلم قدرها إلا الله ، فمن الناس من يمر يمشي، ومنهم من يمر يزحف، ومنهم من تخدشه الكلاليب ولكن يسلم، ومنهم من يخدش ويلقى في النار بسبب معاصيه وكبائره التي مات عليها.  أما الكفار فإنهم لا يمرون عليه، بل يساقون إلى النار، نسأل الله العافية. فالحاصل: أن هذا المرور لا بد منه، وهو الورود المذكور في قوله تعالى: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا ۝ ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا[مريم:71-72] فالمتقون ينجيهم الله ويمرون، والظالمون يساقون إلى جهنم ويدخلونها، والعصاة على خطر عظيم، منهم من ينجى، ومنهم من يسلم، ومنهم من يدخل النار، ويعذب بقدر معاصيه، ثم يخرجه الله منها بفضل رحمته ؛ لأنه مات على التوحيد والإسلام.  وتحل الشفاعة، فالنبي ﷺ يشفع، والملائكة يشفعون، والمؤمنون يشفعون، والأفراط يشفعون، أما الكفار فإنهم لا شفاعة فيهم، بل خلودهم في النار دائم، قال الله تعالى: فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشَّافِعِينَ[المدثر:48]، مَا لِلظَّالِمِينَ مِنْ حَمِيمٍ وَلا شَفِيعٍ يُطَاعُ[غافر:18].\nفالكفار مخلدون في النار، وليس فيهم شفاعة، وإنما الشفاعة للعصاة الذين يدخلون النار بمعاصيهم، فإنه يشفع فيهم الأنبياء، ويشفع نبينا ﷺ في عصاة أمته، ويشفع المؤمنون، وتشفع الأفراط، ويبقى بقية في النار من أهل المعاصي، يخرجهم الله من النار -سبحانه- بفضل رحمته، بعدما يمضي فيهم أمر الله، وتنتهي مدة عذابهم في النار، يخرجهم الله منها بسبب توحيدهم وإسلامهم، إلى نهر يقال له: نهر الحياة، فينبتون فيه كما تنبت الحبة في حميل السيل كما جاءت به الأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14476/الجمع-بين-حديث-السبعين-الفا-والورود-على-جهنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74503.mp3","categories":["التفسير"]},{"id":15889,"question":"يسأل تفسير بعض الآيات الكريمة: منها قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ ۝ أَلَمْ تَرَ أَنَّهُمْ فِي كُلِّ وَادٍ يَهِيمُونَ ۝ وَأَنَّهُمْ يَقُولُونَ مَا لا يَفْعَلُونَ[الشعراء:224-226].","title":"تفسر قوله تعالى: {وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ...}","answer":"الجواب: على ظاهر الآية، غالب الشعراء هكذا، يقولون ما لا يفعلون، وفي كل وادٍ يهيمون، تراه يتكلم هنا أو هنا أو هنا بغير حقيقة، بل أشياء يتخيلها، ثم يتكلم فيها، أو يكذب لحاجات في نفسه أو لأسباب أخرى، إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ[الشعراء:227] استثناهم الله -جل وعلا- فهم الذين أشعارهم طيبة ومفيدة، كـحسان بن ثابت  شاعر الرسول ﷺ، كعب بن مالك، وعبدالله بن رواحة وغيرهم من شعراء المؤمنين، ثم من بعدهم في عهد التابعين وعهد أتباع التابعين إلى يومنا هذا. فالمؤمنون أشعارهم مفيدة ونافعة، مثلما قال النبي ﷺ: إن من الشعر حكمة والنبي ﷺ أمر حسان أن يهجو قريش، أن يهجو الكفار، وقال: إنه أشد عليهم من وقع النبل وقال: اللهم أيده بروح القدس يعني: جبرائيل. فالشعر الذي يصدر من المؤمن في نصر الحق وتأييده، وفي ذم الباطل وتفنيده، أمر مطلوب، وصاحبه مشكور ومأجور، وهؤلاء هم المراد في قوله سبحانه: إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ[الشعراء:227] استثناهم الله من الشعراء المذمومين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14482/تفسر-قوله-تعالى-والشعراء-يتبعهم-الغاوون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74509.mp3","categories":["التفسير"]},{"id":15892,"question":"يسأل تفسير قول الحق -تبارك وتعالى-: وَمَثَلُ الَّذِينَ يُنفِقُونَ أَمْوَالَهُمُ ابْتِغَاءَ مَرْضَاةِ اللَّهِ وَتَثْبِيتًا مِنْ أَنْفُسِهِمْ كَمَثَلِ جَنَّةٍ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَآتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِنْ لَمْ يُصِبْهَا وَابِلٌ فَطَلٌّ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ[البقرة:265].","title":"تفسير قوله تعالى: {وَمَثَلُ الَّذِينَ يُنفِقُونَ أَمْوَالَهُمُ...}","answer":"الجواب: على ظاهر الآية، يبين سبحانه أن من تصدق وأنفق في سبيل الله ابتغاء وجه الله عن صدق وإخلاص لله، وسخاوة من نفسه، فإن الله يضاعف له هذه الصدقة، كما أن الجنة تؤتي ثمارها، يعني: البستان يؤتي ثماره طيبة إذا أصابه الوابل الطيب المناسب، وتعطي ثمارها العظيمة وبركاتها الكثيرة. فالحاصل: أنّ هذا الرجل الذي ينفق عن إيمان وإخلاص وصدق بكسب حلال، يريد وجه الله، يضاعف الله له الأجور مضاعفات كثيرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14485/تفسير-قوله-تعالى-ومثل-الذين-ينفقون-اموالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74512.mp3","categories":["التفسير"]},{"id":16097,"question":"على أي دين أصحاب الكهف سماحة الشيخ؟!","title":"ما دين أصحاب الكهف؟","answer":"الجواب: ظاهر القرآن أنهم على دين الحنيفية، التوحيد على الإسلام. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14740/ما-دين-اصحاب-الكهف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57917.mp3","categories":["التفسير"]},{"id":16133,"question":"بعد هذا رسالة من أحد الإخوة المستمعين يقول عبدالله حامد صالح أخونا له جمع من الأسئلة، يقول: فسروا لنا قول الحق -تبارك وتعالى-: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ [المائدة:89] إلى آخر الآية؟ جزاكم الله خيرًا.","title":"تفسير قوله تعالى: {لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ}","answer":"الجواب: يقول سبحانه في سورة المائدة: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية، ويقول سبحانه في سورة البقرة: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ وَاللَّهُ غَفُورٌ حَلِيمٌ [البقرة:225]. والمعنى أن الأيمان التي تمر على الإنسان من غير قصد لا يؤاخذ بها، ولا كفارة فيها، تجري على لسانه من دون قصد لعقدها في عرض كلامه: والله! ما صار كذا، والله! صار كذا، يتحدث من غير قصد اليمين، هذا هو اللغو في اليمين كما قالت عائشة، وجماعة من السلف، لغو اليمين أن يقول الرجل: لا والله، وبلى والله، في عرض كلامه. أما إذا قصد بقلبه كسب قلبه بذلك يعني: أراد بقلبه اليمين على أنه ما يفعل كذا، أو أنه يترك كذا؛ فهذا يؤاخذ بها إذا أخل بها عليه الكفارة؛ لأن الله قال: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ [البقرة:225] وفي آية المائدة: بِمَا عَقَّدْتُمُ الأَيْمَانَ [المائدة:89] يعني: بما قصدتم من عقدها، وأردتم ذلك، فإذا قال: والله! لا أكلم فلانًا؛ قاصدًا فإذا كلمه؛ فعليه كفارة اليمين، إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فإن عجز ولم يستطع؛ صام ثلاثة أيام. أو قال: والله! ما أزور فلانًا، ثم زاره؛ عليه كفارة يمين، أو قال لزوجته: والله! ما تكلمي فلانًا، أو والله ما تخرجي من البيت اليوم، أو هذه الليلة، أو أبدًا.. أو ما أشبه ذلك، إذا خرجت؛ عليه كفارة اليمين. وهكذا ما أشبه ذلك؛ لأن هذه أيمان مقصودة، قد كسبها القلب، وعقدها صاحبها؛ فيكون فيها الكفارة، والكفارة -كما سمعتم في الآية الكريمة- إطعام عشرة مساكين من أوسط ما تطعمون أهليكم، يعني: طعام الوسط، تمر من الرز، من الحنطة إذا كان معه إدام يكون أفضل، وهكذا إذا صنع لهم الطعام، ودعوا إليه في البيت، أو المطعم، غداء، أو عشاء، وجبة واحدة تكفي، وجبة واحدة. أو كسوتهم يكسوهم... أو إزار ورداء لكل واحد، يعني: قميص أو إزار ورداء، أو يعتق رقبة عبد وإلا عبدة، فإذا لم يستطع هذه الثلاث؛ انتقل إلى الصوم، صام ثلاثة أيام، والأفضل أن تكون متتابعة، ثلاثة أيام والأفضل تتابعها، وقال بعض أهل العلم: يجب تتابعها، فالأفضل للمؤمن أن يتابعها هذه الثلاثة، عند العجز عن الإطعام، والكسوة، والعتق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14788/تفسير-قوله-تعالى-لا-يواخذكم-الله-باللغو-في-ايمانكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71304.mp3","categories":["التفسير","الأيمان والنذور"]},{"id":16199,"question":"نرجو أن توضحوا لنا هذه الآية الكريمة: إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ [التوبة:37] الآية؟","title":"تفسير قوله تعالى: {إنما النسيء زيادة في الكفر...}","answer":"الجواب: مثلما بين -جل وعلا- في الآية نفسها قال: إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا [التوبة:37] يعني: من طريقة الكفرة أنهم يحرمون النسيء، والنسيء محرم يجعلونه صفرًا، وصفر يجعلونه محرمًا، تارة وتارة، فتارة يبقون محرمًا محرمًا، وصفرًا حلًا، وتارة يعكسون، فيجعلون محرمًا صفرًا، ويستحلونه ويؤخرون محرمًا إلى صفر يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا وهذا من جهلهم، وضلالهم، وتبديلهم، ولهذا قال سبحانه: إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا لِيُوَاطِئُوا عِدَّةَ مَا حَرَّمَ اللَّهُ فَيُحِلُّوا مَا حَرَّمَ اللَّهُ [التوبة:37]. يقولون: الشهور أربعة: رجب، وذو القعدة، وذو الحجة، والمحرم، هذه أربعة، فإذا حرمنا صفرًا، وأحلينا محرمًا؛ فالشهور أربعة ما غيرنا إلا أنا قدمنا وأخرنا، وهذا ضلال؛ لأنهم خالفوا شرع الله، شرع الله جعل محرمًا ما جعل صفرًا، فلهذا قال: يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا [التوبة:37] وجعله سبحانه زيادة في الكفر، يعني: تغييرهم شرائع الله زيادة في الكفر، نسأل الله العافية. فالواجب بقاء الشهور على حالها محرمة، رجب وحده بين جمادى وشعبان، وثلاثة متوالية: ذو القعدة، وذو الحجة، والمحرم، هذا هو الواجب، أما أن يؤخر محرم إلى صفر، ويقدم صفر إلى محرم؛ هذا باطل، هذا من جهلهم، وضلالهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14866/تفسير-قوله-تعالى-انما-النسيء-زيادة-في-الكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80606.mp3","categories":["التفسير"]},{"id":16226,"question":"السائلة أم مريم تقول: أود من سماحة الشيخ أن يفسر هذه الآية: وَلا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُوْلَئِكَ كَانَ عَنْهُ مَسْئُولًا [الإسراء:36]؟","title":"ما معنى: {وَلا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ}؟","answer":"الجواب: على ظاهرها: أن الله ينهى عن كون الإنسان يتكلم فيما لا يعلم ولا تقف ما ليس لك به علم يعني: لا تقل في شيء ليس لك به علم، بل تثبت إن السمع يقول: سمعت كذا، وهو ما سمع وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَئِكَ كَانَ عَنْهُ مَسْئُولًا [الإسراء: 36] الإنسان مسؤول عن سمعه، وقلبه، وبصره، فالواجب عليه ألا يقول: سمعت كذا إلا عن بصيرة، ولا يقل: نظرت كذا إلا عن بصيرة، ولا يحكي عن، أو يعتقد بقلبه شيئًا إلا عن بصيرة، لابد هو مسؤول. فالواجب عليه أن يتثبت، وأن يعتني؛ حتى لا يتكلم إلا عن علم، ولا يفعل إلا عن علم، ولا يعتقد إلا عن علم؛ ولهذا قال -جل وعلا-: إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُوْلَئِكَ كَانَ عَنْهُ مَسْئُولًا [الإسراء:36] فالإنسان يتثبت في الأمور، والله يقول -جل وعلا-: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] جعل القول على الله بغير علم فوق هذه الأشياء كلها.  فالواجب على الإنسان أن يتعلم حتى يقول عن علم، يتبصر فلا يقول: سمعت، ولا يقول: رأيت، ولا يقول كذا وكذا إلا عن بصيرة عن علمـ نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14902/ما-معنى-ولا-تقف-ما-ليس-لك-به-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58014.mp3","categories":["التفسير"]},{"id":16235,"question":"من المستمع خالد إبراهيم من مكة المكرمة رسالة وضمنها بعض الأسئلة، في أحدها يقول: نرجو من سماحتكم أن تفسروا قوله تعالى: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا [مريم:71] لأن بعض الناس يسيئون فهمها، فيعتقدون أن الناس كلهم سوف يدخلون النار، وكلهم سوف يحاسب بعمله، فإن شاء الله أخرج من يشاء، ويبقي من يشاء، جزاكم الله خيرًا.","title":"تفسير قوله تعالى: {وإن منكم إلا واردها...}","answer":"الجواب: هذه الآية الكريمة فسرها النبي ﷺ وهي قوله : وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا [مريم:71] يعني: النار، كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا [مريم:71] ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا [مريم:72] فسرها النبي ﷺ بأن الورود المرور والعرض عليها، هذا هو الورود، يعني: مرور المسلمين عليها إلى الجنة، ولا يضرهم ذلك، منهم من يمر كلمح البصر، ومنهم من يمر كالبرق، ومنهم من يمر كالريح، ومنهم من يمر كأجاود الخيل والركاب، تجري بهم أعمالهم، ولا يدخلون النار، المؤمن لا يدخل النار، بل يمر مرورًا لا يضره ذلك. فالصراط جسر على متن جهنم، يمر عليه الناس، وقد يسقط بعض الناس؛ لشدة معاصيه، وكثرة معاصيه، فيعاقب بقدر معاصيه، ثم يخرجه الله من النار إذا كان موحدًا مؤمنًا، وأما الكفار فلا يمرون، بل يساقون إلى النار، ويحشرون إليها، نعوذ بالله من ذلك. لكن بعض العصاة الذين لم يعف الله عنهم قد يسقط بمعاصيه التي مات عليها، لم يتب كالزنا، وشرب المسكر، وعقوق الوالدين، وأكل الربا، وأشباه ذلك من المعاصي الكبيرة، صاحبها تحت مشيئة الله، كما قال الله سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]. فهو سبحانه لا يغفر الشرك لمن مات عليه، ولكنه يغفر ما دون ذلك من المعاصي لمن يشاء  وبعض أهل المعاصي لا يغفر له، يدخل النار، كما تواترت بذلك الأحاديث عن رسول الله -عليه الصلاة والسلام- فقد صح عن رسول الله ﷺ في الأحاديث الكثيرة أن بعض العصاة يدخل النار، ويقيم فيها ما شاء الله، فقد تطول إقامته لكثرة معاصيه التي لم يتب منها، وقد تقل. ويشفع النبي ﷺ في العصاة عدة شفاعات، يحد الله له حدًا فيخرجهم من النار فضلًا منه  عليهم؛ لأنهم ماتوا على التوحيد والإسلام، لكن لهم معاصي لم يتوبوا منها، وهكذا تشفع الملائكة، يشفع المؤمنون، يشفع الأفراط، ويبقى أناس في النار من العصاة لا يخرجون بالشفاعة، فيخرجهم الله -جل وعلا- فضلًا منه  يخرجهم من النار بفضله؛ لأنهم ماتوا على التوحيد، ماتوا على الإسلام، لكن لهم معاص ماتوا عليها، لم يتوبوا، فعذبوا من أجلها، ثم بعد مضي المدة التي كتبها الله عليهم، وبعد تطهيرهم بالنار يخرجهم الله من النار إلى الجنة؛ فضلًا منه . وبما ذكرنا يتضح معنى الورود، وأن قوله سبحانه: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا [مريم:71] يعني: المرور فقط لأهل الإيمان، وأن بعض العصاة قد يسقط في النار، ولهذا في الحديث: فناج مسلم، ومكدس في النار فالمؤمن السليم ينجو، وبعض العصاة كذلك، وبعض العصاة قد يخر، ويسقط، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14939/تفسير-قوله-تعالى-وان-منكم-الا-واردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80709.mp3","categories":["التفسير"]},{"id":16303,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع حسن بن عبدالكريم محمود، أخونا حسن يسأل تفسير قول الحق -تبارك وتعالى-: وَلَقَدْ كَذَّبَ أَصْحَابُ الْحِجْرِ الْمُرْسَلِينَ [الحجر:80] يقول: معلوم أن قوم صالح لم يرسل إليهم إلا سيدنا صالح، فلماذا ذكرت كلمة المرسلين بالجمع؟","title":"تفسير قوله تعالى: {ولقد كذب أصحاب الحجر المرسلين}","answer":"الجواب: ذكر العلماء في هذا أن من كذب رسولًا؛ فقد كذب المرسلين؛ لأن الحكم واحد، فالتكذيب للواحد منهم تكذيب لهم؛ لأنهم بعثوا من عند الله بالآيات، والمعجزات، فمن كذبه؛ فحكمه حكم من كذب الجميع، ولهذا قال في حقهم وفي حق غيرهم: كَذَّبَتْ عَادٌ الْمُرْسَلِينَ [الشعراء:123] كَذَّبَتْ ثَمُودُ الْمُرْسَلِينَ [الشعراء:141] من هذا الباب؛ لأنهم لما كذبوا نبيهم مع قيام الحجة القاطعة على صدقه؛ فهم في الحقيقة مكذبون لغيره -نسأل الله السلامة- نعم.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14999/تفسير-قوله-تعالى-ولقد-كذب-اصحاب-الحجر-المرسلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81002.mp3","categories":["التفسير"]},{"id":16310,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع حسن بن عبدالكريم محمود، أخونا حسن يسأل تفسير قول الحق -تبارك وتعالى-: وَلَقَدْ كَذَّبَ أَصْحَابُ الْحِجْرِ الْمُرْسَلِينَ [الحجر:80] يقول: معلوم أن قوم صالح لم يرسل إليهم إلا سيدنا صالح، فلماذا ذكرت كلمة المرسلين بالجمع؟","title":"تفسير قوله تعالى: {ولقد كذب أصحاب الحجر المرسلين}","answer":"الجواب: ذكر العلماء في هذا أن من كذب رسولًا؛ فقد كذب المرسلين؛ لأن الحكم واحد، فالتكذيب للواحد منهم تكذيب لهم؛ لأنهم بعثوا من عند الله بالآيات، والمعجزات، فمن كذبه؛ فحكمه حكم من كذب الجميع، ولهذا قال في حقهم وفي حق غيرهم: كَذَّبَتْ عَادٌ الْمُرْسَلِينَ [الشعراء:123] كَذَّبَتْ ثَمُودُ الْمُرْسَلِينَ [الشعراء:141] من هذا الباب؛ لأنهم لما كذبوا نبيهم مع قيام الحجة القاطعة على صدقه؛ فهم في الحقيقة مكذبون لغيره -نسأل الله السلامة- نعم.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14999/تفسير-قوله-تعالى-ولقد-كذب-اصحاب-الحجر-المرسلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81002.mp3","categories":["التفسير"]},{"id":16369,"question":"هذا سائل من الرياض يقول: في الآية الكريمة عندما تحدث الله -تبارك وتعالى- عن أهل الجنة، وأهل النار قال: خَالِدِينَ فِيهَا إِلَّا مَا شَاءَ اللَّهُ [الأنعام:128] ؟.","title":"تفسير قوله تعالى: {خَالِدِينَ فِيهَا إِلَّا مَا شَاءَ اللَّهُ}","answer":"الجواب: هذا حمله بعض العلماء على البرزخ، يعني: إِلَّا مَا شَاءَ اللَّهُ يعني: البرزخ، أو وقوفهم في الموقف يوم القيامة قبل دخول الجنة والنار، هذا محل المشيئة، وإلا أهل الجنة إذا دخلوها يستقرون فيها أبد الآباد، وهكذا أهل النار من الكفرة يستقرون فيها أبد الآباد، وإنما يخرج منها أهل المعاصي إذا دخلها بعض أهل المعاصي يخرجون منها بعد التطهير، والتمحيص، يخرجهم الله من النار إلى الجنة، وأما الكفار فهم دائمون فيها أبد الآباد. أما قوله -جل وعلا-: خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَوَاتُ وَالأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ [هود:107] يعني: مدة وجودهم في البرزخ، أو في موقف القيامة قبل انصرافهم إلى الجنة والنار، في الموقف وقت الحساب والجزاء، وقت الحساب والنظر في كتبهم، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15069/تفسير-قوله-تعالى-خالدين-فيها-الا-ما-شاء-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58115.mp3","categories":["التفسير"]},{"id":16426,"question":"يقول في سورة سبأ: بسم الله الرحمن الرحيم الْحَمْدُ لِلَّهِ الَّذِي لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ وَلَهُ الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ [سبأ:1] يقول: ما هي سبأ؟","title":"بيان معنى (سبأ)","answer":"الجواب: لقوله في السورة: لَقَدْ كَانَ لِسَبَإٍ فِي مَسْكَنِهِمْ آيَةٌ [سبأ:15] وسبأ محل في اليمن يقال له: سبأ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15123/بيان-معنى-سبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58127.mp3","categories":["التفسير"]},{"id":16490,"question":"في آخر أسئلة السائل طاهر آدم من غانا غرب أفريقيا، يستفسر عن الآية الكريمة يا سماحة الشيخ، يقول: ما معنى قوله تعالى: إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلافٍ أَوْ يُنفَوْا مِنَ الأَرْضِ ذَلِكَ لَهُمْ خِزْيٌ فِي الدُّنيَا وَلَهُمْ فِي الآخِرَةِ عَذَابٌ عَظِيمٌ [المائدة:33] يقول: وما سبب نزول هذه الآية؟","title":"تفسير قوله تعالى: {إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ...}","answer":"الجواب: هذه نزلت في المحاربين، وهم قطاع الطريق الذين يؤذون الناس في الطرقات، يقتلون، وينهبون الأموال في الطرقات، أو في البلد، هؤلاء هذا حكمهم، ونزلت في العرنيين الذين اشتكوا مرض بطونهم، وأرشدهم النبي ﷺ إلى أن يخرجوا إلى إبل الصدقة، فيكونوا فيها، فلما صحوا؛ قتلوا راعي النبي ﷺ وأخذوا الإبل، وشردوا بها، فألحقهم النبي ﷺ جيشًا، فأدركوهم، وأخذوا الإبل منهم، وأمسكوهم، فعاقبهم النبي ﷺ بهذه العقوبة؛ لأنهم قطاع طريق، اعتدوا على إبل النبي ﷺ. فهؤلاء يسمون: محاربين، ويسمون: قطاع الطريق، فولي الأمر له الخيار إن شاء قتلهم، وإن شاء صلبهم، وإن شاء قطع أيديهم، وأرجلهم من خلاف، وإن شاء نفاهم من الأرض، هذا إلى ولي الأمر، وإذا كانوا قتلوا؛ يقتلوا، وإذا أخذوا المال إن شاء قتل، وإن شاء قطع أيديهم وأرجلهم من خلاف، وإن شاء صلبهم، هذا لولي الأمر، يجتهد ولي الأمر فيما يراه مصلحة للمسلمين. ويقال لهم: المحاربون، ويقال لهم: قطاع الطريق، ونفيهم من الأرض، قال بعض أهل العلم: يعني حبسهم حتى لا يؤذوا الناس، وقال آخرون من أهل العلم: إنهم يشردون، ما يتركون يؤون البلد، كلما أووا إلى بلد؛ يشردون منها، حتى يتوبوا توبة صحيحة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15200/تفسير-قوله-تعالى-انما-جزاء-الذين-يحاربون-الله-ورسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58217.mp3","categories":["التفسير"]},{"id":16553,"question":"مع بداية هذه الحلقة نعود إلى رسالة وصلت إلى البرنامج من الطائف، وباعثها المستمع محمد أحمد إبراهيم العظيمي، أخونا محمد عرضنا بعض أسئلة له في حلقة مضت، وبقي له في هذه الحلقة بعض الأسئلة، فيسأل أول سؤال في هذه الحلقة عن تفسير آية من كتاب الله، هي قول الحق -تبارك وتعالى- أعوذ بالله من الشيطان الرجيم: يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنْكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلاثَ مَرَّاتٍ مِنْ قَبْلِ صَلاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّهِيرَةِ وَمِنْ بَعْدِ صَلاةِ الْعِشَاءِ ثَلاثُ عَوْرَاتٍ لَكُمْ لَيْسَ عَلَيْكُمْ وَلا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُمْ بَعْضُكُمْ عَلَى بَعْضٍ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الآيَاتِ وَاللَّهُ عَلِيمٌ حَكِيمٌ[النور:58]؟","title":"تفسير قوله تعالى: {يا أيها الذين آمنوا ليستأذنكم...}","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالآية واضحة في معناها، وأن المماليك، وهكذا الأولاد الذين لم يبلغوا الحلم يعني: ما بلغوا خمسة عشر سنة، ولا احتلموا بشيء آخر من إنبات، أو احتلام؛ هؤلاء عليهم أن يستأذنوا على أهلهم في هذه الأوقات الثلاثة؛ لأنها أوقات عورة، قبل صلاة الفجر؛ لأن الناس إذا خلا بعضهم إلى بعض قد يظهر منهم بعض الشيء، فيستأذن عليهم. وهكذا وقت الظهيرة قبيل الظهر، وإذا كان عادتهم بعد الظهر كذلك؛ لأن عادة الناس سابقًا الراحة قبل الظهر القائلة. وهكذا بعد صلاة العشاء في هذه الأوقات الثلاثة يستأذنون، أما ما سواه فلا يحتاج؛ لأنهم طوافون عليهم، من أهل البيت؛ فلا حرج بعد ذلك. فالمقصود: أنهم في هذه الأوقات الثلاثة يستأذنون، ولو كان مملوكًا، ولو كان صغيرًا لم يبلغ؛ لئلا يرى عورة، وما سواها فالأمر فيه واسع، نعم. المقدم: جزاكم الله خيرًا. الشيخ: نعم.  المقدم: سماحة الشيخ، هل تراعى عادات الناس، وتغير أحوالهم من زمان إلى زمان؟ الشيخ: نعم، العلة مفهومة، إذا صارت العورة تبدو في وقت آخر مثل: بعد الظهر بدل القائلة، أو بعد صلاة الفجر بدل ما قبل الفجر، كذلك يستأذن. المقدم: جزاكم الله خيرًا. الشيخ: نعم. المقدم: هل يلحق الخدم في المنزل بهذا الحكم؟ الشيخ: نعم، الخدم مثل المماليك. المقدم: كالمماليك. الشيخ: إذا صاروا يدخلون، ويخرجون في حاجات المنزل. المقدم: نعم. الشيخ: مثل المماليك، نعم. المقدم: جزاكم الله خيرًا، إذًا عليهم أن يؤدبوا بهذه الآداب. الشيخ: نعم يستأذنوا كما أمر الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15294/تفسير-قوله-تعالى-يا-ايها-الذين-امنوا-ليستاذنكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75801.mp3","categories":["التفسير"]},{"id":16620,"question":"ما معنى قول الله تعالى في سورة الرحمن: كُلُّ مَنْ عَلَيْهَا فَانٍ ۝ وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالإِكْرَامِ [الرحمن:26-27]؟","title":"معنى قوله تعالى: {كل من عليها فان...}","answer":"الجواب: الظاهر في الآية الأرض كل ما كان على الأرض هو فانٍ، الجبال تدك، والأشجار والأحجار تذهب، والجن والإنس يموتون، والحيوانات تموت، ما يبقى شيء، إلا الله  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15352/معنى-قوله-تعالى-كل-من-عليها-فان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75822.mp3","categories":["التفسير"]},{"id":16624,"question":"سماحة الشيخ! ما هو تفسير قوله تعالى: وَلَقَدْ يَسرْنَا الْقُرْآنَ لِلذكْرِ فَهَلْ مِنْ مُدكِرٍ [القمر:17]؟","title":"تفسير قوله تعالى: {ولقد يسرنا القرآن للذكر...}","answer":"الجواب: عامة الآية، قال بعضهم: معناه: هل من طالب للعلم فيعان عليه، ولكنها في القرآن أخص، والمعنى أن الله يسره للحفظ، والفهم، والتدبر، فجدير بالمؤمن، والمؤمنة العناية بهذا القرآن حفظًا وتلاوة، وتدبرًا ومذاكرة، فالطالب يذاكر مع زميله، ومع زملائه، والطالبة كذلك مع زميلاتها، ومع المدرسة، ومع أخيها، ومع أبيها من باب التعاون على البر والتقوى، كل واحد يبذل وسعه مع زميله، مع أبيه، مع أخيه، مع أمه إن كانت تحفظ، وهكذا البنت مع أمها، مع أبيها، مع أخيها، مع المدرسة، مع الزميلات، ومتى صدق الطالب والطالبة يسر الله... وَلَقَدْ يَسرْنَا الْقُرْآنَ لِلذكْرِ [القمر:17] فالله يسره للذكر، ومن الذكر حفظه، وتدبره، وتعقله، والإكثار من تلاوته، والعناية بالعمل به، كل هذا من الذكر، فالذكر يكون قلبيًا ولسانيًا وعمليًا. وطلب العلم من ذلك كونه يدرس القرآن لطلب العلم، والتفقه في الدين، ولو ما حفظه يعان على ذلك، إذا صلحت نيته، وإذا حفظه كان أكمل وأكمل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15360/تفسير-قوله-تعالى-ولقد-يسرنا-القران-للذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_759/nour_75904.mp3","categories":["التفسير"]},{"id":16633,"question":"يسأل ويقول: ما هو تفسير الآية الكريمة بسم الله الرحمن الرحيم: إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ [القدر:1] هل القرآن نزل جملة واحدة، لقد سألت، وقالوا لي: إنه نزل من اللوح المحفوظ، فهل هذا صحيح؟ جزاكم الله خيرًا.","title":"تفسير قوله تعالى: {إنا أنزلناه في ليلة القدر}","answer":"الجواب: القرآن الكريم نزل على رسول الله ﷺ منجمًا على حسب الحاجة والأسباب، وكان أول ما نزل سورة (اقرأ) في ليلة القدر، فصدق على ذلك أنه أنزل في ليلة القدر، وأنه أنزل في رمضان؛ لأن أوله نزل في ليلة القدر في رمضان، هذا هو ظاهر الأدلة الشرعية؛ لأن كثيرًا من القرآن نزل في مكة في غير رمضان، وكثير منه نزل في المدينة في غير رمضان، لم يزل ينزل منجمًا على الرسول ﷺ بحسب الحوادث، والأسباب، وسورة المائدة نزلت في آخر حياته ﷺ ونزل في يوم الجمعة في يوم عرفة في حجة الوداع، في السنة العاشرة من حياته ﷺ ومن هجرته... من حياته بعد الهجرة هذه الآية: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلامَ دِينًا [المائدة:3] هذه الآية نزلت في يوم الجمعة، وهو واقف بعرفة -عليه الصلاة والسلام- سنة عشر من الهجرة. وقال ابن عباس  وجماعة: إنه أنزل إلى السماء الدنيا في رمضان في ليلة القدر، إلى بيت العزة، بيت في السماء الدنيا يقال له: بيت العزة، وكل سماء فيها بيت للملائكة يتعبدون فيه، وبيت العزة بيت في السماء الدنيا يتعبد فيه الملائكة، وفي السماء السابعة البيت المعمور، يتعبد به الملائكة أيضًا وهو على .... الكعبة في الأرض، يقول فيه النبي ﷺ: إنه يدخله كل يوم يعني: البيت المعمور سبعون ألف ملك، ثم لا يعودون إليه آخر ما عليهم وهذا يدل على كثرة الملائكة، وأن كل يوم يدخل البيت المعمور منهم سبعون ألف ملك للعبادة، ثم لا يعودون إليه أبدًا. فعلى هذا القول - قول ابن عباس - أنه أنزل إلى بيت العزة جملة واحدة، ثم نزل منجمًا في ثلاث وعشرين سنة على حسب الحوادث والأسباب، وهذا قول قوي، أخذ به جمع من أهل العلم، والأول أظهر، وأنه أنزل من عند الله -جل وعلا- بواسطة جبرائيل على النبي ﷺ في ثلاث وعشرين سنة، وأن أوله أنزل في ليلة القدر في رمضان، والله ولي التوفيق  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15369/تفسير-قوله-تعالى-انا-انزلناه-في-ليلة-القدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76002.mp3","categories":["التفسير"]},{"id":16687,"question":"ما هو تفسير قوله -تبارك وتعالى- أعوذ بالله من الشيطان الرجيم: إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ [فاطر:28].","title":"تفسير قوله تعالى: {إنما يخشى الله من عباده العلماء}","answer":"الجواب: هذه الآية العظيمة فيها الثناء العظيم على أهل العلم بالله، وبدينه، وعلى رأسهم الرسل، والأنبياء -عليهم الصلاة والسلام- هم أئمة العلماء، وهم رؤوس العلماء، ثم العلماء بشريعة الله بعد الأنبياء، والرسل هم خلفاء الرسل، وهم أهل الخشية لله الخشية الكاملة.  فالمعنى: إنما يخشى الله خشية كاملة: العلماء بالله، وبدينه، وبأسمائه، وصفاته، وحقه على عباده، وكمال قدرته، وكمال علمه، وليس معناه نفي الخشية عن غير العلماء، كل مسلم يخشى الله، كل مسلم ومسلمة يخشى الله. لكن الخشية تتفاوت، كل من كان أعلم بالله؛ صارت خشيته أكبر، وأعظم وأكمل، والرسل أكمل الناس خشية، وأكملهم، وأفضلهم نبينا محمد -عليه الصلاة والسلام- فقد صح عنه أنه قال -عليه الصلاة والسلام-: أما والله إني لأخشاكم لله، وأتقاكم له عليه الصلاة والسلام. والرسل جميعًا هم أخشى الناس لله، والأنبياء كذلك، ثم يليهم العلماء بالله، وبدينه، وهم يتفاوتون في الخشية لله على حسب علمهم وتقواهم لله  ثم يليهم أهل الإيمان من غير أهل العلم في الخشية لله  فكل مسلم له نصيبه في خشية الله، وكل مسلمة كذلك، لكن على حسب العلم بالله، وبدينه يكون تفاوت الخشية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15449/تفسير-قوله-تعالى-انما-يخشى-الله-من-عباده-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82005.mp3","categories":["التفسير"]},{"id":16693,"question":"يقول أرجو تفسير هذه الآية الكريمة: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31]؟","title":"ما معنى: {خُذُوا زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ}؟","answer":"الجواب: على ظاهرها، السنة أن يأخذ المؤمن زينته إذا ذهب للصلاة، يعني: ملابسه الحسنة الجميلة، واحتج بها العلماء أيضًا على وجوب ستر العورة، ولكن الآية فوق ذلك، تدل على أنه يشرع له مع ستر العورة أخذ الزينة، وأن تكون عليه الملابس الحسنة الجميلة عند قيامه بين يدي الله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15460/ما-معنى-خذوا-زينتكم-عند-كل-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82010.mp3","categories":["التفسير"]},{"id":16765,"question":"كما يسأل عن تفسير قول الحق -تبارك وتعالى-: وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ قَالَ مَنْ يُحْيِ الْعِظَامَ وَهِيَ رَمِيمٌ ۝ قُلْ يُحْيِيهَا الَّذِي أَنشَأَهَا أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ ۝ الَّذِي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الأَخْضَرِ نَارًا فَإِذَا أَنْتُمْ مِنْهُ تُوقِدُونَ [يس:79-80]؟","title":"تفسير قوله تعالى: {وضرب لنا مثلًا ونسي خلقه...}","answer":"الجواب: الذي خلق الخلق من الطين، وخلق آدم من الطين، وخلق ذريته من ماء مهين سبحانه، هو الذي يحيي العظام وهي رميم يوم القيامة، يعيدها كما بدأها، وتخرج من قبورها بعدما يتم خلقها بإذنه  فيرجع كل شيء إلى ابن آدم مما ذهب منه، ويفنى منه كل شيء إلا عجب الذنب، ثم يعيده الله كما كان  ويبعثه ليجازيه بأعماله يوم القيامة. فالذي أحياها أول مرة من الطين، ومن ماء مهين، هو الذي يعيدها يوم القيامة بعدما صارت رميمًا وترابًا، وهو الذي جعل له من الشجر الأخضر نارًا أيضًا هو بقدرته  جعل له من الشجر الأخضر نارًا، ومن الحجر نارًا، ومن الكبريت نارًا، هذا خلقه . يقول أئمة اللغة: في كل شجر نار، واستمجد، والمرخ، والعفار، يعني: المرخ، والعفار ناره أكثر إذا حك بعضه ببعض، ثم هو الحطب توقد به النيران، ويستوقد به الناس، وهو من الشجر، أخضر، ثم ييبس، ويستعمل، توقد منه النار أيضًا، جميع أنواع الشجر .... من قبل مجيء الكهرباء، الناس على الله، ثم على هذا الحطب. فالمقصود: أن الشجر إذا يبس يستوقد في النار، وينتفع به، وبعض الشجر الأخضر كذلك يستوقد منه النار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15532/تفسير-قوله-تعالى-وضرب-لنا-مثلا-ونسي-خلقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82208.mp3","categories":["التفسير"]},{"id":16769,"question":"كذلك رسالة من المستمع (ن. ع) من الموصل، بعث بها ويسأل فيها أيضًا عن تفسير قول الحق -تبارك وتعالى-: فَقَبَضْتُ قَبْضَةً مِنْ أَثَرِ الرَّسُولِ [طه:96] يقول: إنه رجع إلى عدة مصادر، لكنه لم يفهم تفسير هذا الجزء من هذه الآية الكريمة، ويرجو من سماحتكم تفسيرها، جزاكم الله خيرًا.","title":"تفسير قوله تعالى: {فقبضت قبضة من أثر الرسول}","answer":"الجواب: الله المستعان، هذا يؤجل إلى وقت آخر. المقدم: جزاكم الله خيرًا، إن شاء الله.","link":"https://binbaz.org.sa/fatwas/15533/تفسير-قوله-تعالى-فقبضت-قبضة-من-اثر-الرسول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82209.mp3","categories":["التفسير"]},{"id":16775,"question":"كما يسأل عن تفسير قول الحق -تبارك وتعالى-: وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ قَالَ مَنْ يُحْيِ الْعِظَامَ وَهِيَ رَمِيمٌ ۝ قُلْ يُحْيِيهَا الَّذِي أَنشَأَهَا أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ ۝ الَّذِي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الأَخْضَرِ نَارًا فَإِذَا أَنْتُمْ مِنْهُ تُوقِدُونَ [يس:79-80]؟","title":"تفسير قوله تعالى: {وضرب لنا مثلًا ونسي خلقه...}","answer":"الجواب: الذي خلق الخلق من الطين، وخلق آدم من الطين، وخلق ذريته من ماء مهين سبحانه، هو الذي يحيي العظام وهي رميم يوم القيامة، يعيدها كما بدأها، وتخرج من قبورها بعدما يتم خلقها بإذنه  فيرجع كل شيء إلى ابن آدم مما ذهب منه، ويفنى منه كل شيء إلا عجب الذنب، ثم يعيده الله كما كان  ويبعثه ليجازيه بأعماله يوم القيامة. فالذي أحياها أول مرة من الطين، ومن ماء مهين، هو الذي يعيدها يوم القيامة بعدما صارت رميمًا وترابًا، وهو الذي جعل له من الشجر الأخضر نارًا أيضًا هو بقدرته  جعل له من الشجر الأخضر نارًا، ومن الحجر نارًا، ومن الكبريت نارًا، هذا خلقه . يقول أئمة اللغة: في كل شجر نار، واستمجد، والمرخ، والعفار، يعني: المرخ، والعفار ناره أكثر إذا حك بعضه ببعض، ثم هو الحطب توقد به النيران، ويستوقد به الناس، وهو من الشجر، أخضر، ثم ييبس، ويستعمل، توقد منه النار أيضًا، جميع أنواع الشجر .... من قبل مجيء الكهرباء، الناس على الله، ثم على هذا الحطب. فالمقصود: أن الشجر إذا يبس يستوقد في النار، وينتفع به، وبعض الشجر الأخضر كذلك يستوقد منه النار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15532/تفسير-قوله-تعالى-وضرب-لنا-مثلا-ونسي-خلقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82208.mp3","categories":["التفسير"]},{"id":16889,"question":"أحد الإخوة المستمعين وقع في نهاية رسالته يقول: الشمري يسأل عن تفسير جمع من الآيات القرآنية، أعوذ بالله من الشيطان الرجيم: قال الله تعالى: أَوْلَى لَكَ فَأَوْلَى [القيامة:34] ما معنى هذه الآية الكريمة؟","title":"تفسير قول الله تعالى: {أولى لك فأولى}","answer":"الجواب: معناها التحثيث، والترهيب، والحث على التوبة، والرجوع إلى الله، وأن الواجب على المؤمن أن يبادر بالتوبة إلى الله، والرجوع إليه، فإن هذا أولى له من الاستمرار في باطله، نسأل الله السلامة، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15647/تفسير-قول-الله-تعالى-اولى-لك-فاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76505.mp3","categories":["التفسير"]},{"id":16918,"question":"يسألون عن أفضل كتابٍ لتفسير القرآن الكريم؟ ويسألون سماحتكم عن رأيكم في تفسير ابن كثير؟","title":"أفضل كتب تفسير القرآن الكريم","answer":"الجواب: أحسن كتاب فيما علمت في التفسير: تفسير ابن جرير، وتفسير ابن كثير، وتفسير البغوي، هذه الثلاثة أحسن التفاسير، ثم يليها تفسير القرطبي -جيد ومفيد- تفسير الشوكاني -جيد ومفيد- ولكن كل واحد لا يغني عن الآخر، كل واحد لا يغني عن الآخر، وطالب العلم يميز بين الأخطاء، فقد تقع أخطاء في بعض الروايات، يعتمدها بعضهم، قد تكون أحاديث ضعيفة عند ابن جرير، أو عند ابن كثير، أو عند غيرهم، فطالب العلم لابد ينظر في الأسانيد، ويعتني إذا كان من أهل الفن، يعرف صحة السند، وعدم صحة السند، كذلك الأقوال يعرضها على الأصول الشرعية، والقواعد الشرعية، إذا كانت الأقوال مختلفة، حتى يتميز له الصواب من غيره، وهكذا بعض المفسرين يؤولون الصفات، كما قد يقع في تفسير القرطبي.  فلا بد يكون طالب العلم عنده بصيرة فيمن يتأول الصفات، أو يرجح بعض الأقوال المرجوحة؛ حتى يختار ما هو الأفضل، وحتى ينبه على الخطأ، ولا هناك كتاب يسلم من الأخطاء، إلا كتاب الرب -جل وعلا- إلا كتاب الله  هو المعصوم المحفوظ، ليس فيه خطأ، بل هو محفوظ، أما كتب الناس فقد يقع فيها الخطأ من جهة المؤلف، وقد يقع فيها خطأ من جهة الكاتب، قد يقع فيها خطأ من جهة الطابع، فطالب العلم ينظر، ويتحرى، وإذا اشتبه عليه شيء؛ سأل أهل العلم، حتى يتميز له الحق من الباطل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15685/افضل-كتب-تفسير-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82605.mp3","categories":["التفسير"]},{"id":16935,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، باعثها المستمع خالد الأحمد، الأخ خالد يسأل سماحتكم -جزاكم الله خيرًا- تفسير سورة البروج؟","title":"تفسير سورة البروج","answer":"الجواب: ..... قد ذكر الله -جل وعلا- في البروج حالة الذين اعتدوا على المسلمين، وحرقوهم، وفتنوهم تحذيرًا للمسلمين من أعمالهم الخبيثة، وحثًا على الصبر على ما يبتلى به العبد، ولهذا قال -جل وعلا-: وَالسَّمَاءِ ذَاتِ الْبُرُوجِ ۝ وَالْيَوْمِ الْمَوْعُودِ ۝ وَشَاهِدٍ وَمَشْهُودٍ [البروج:1-3]. أقسم بالسماء  ذات البروج، وهي النجوم العظام في قول جماعة من المفسرين، والله يقسم من خلقه بما يشاء  له أن يقسم بالسماء، وبغيرها، كما أقسم بالطور، وبالذاريات، وبالضحى، والليل إذا يغشى، إلى غير ذلك؛ لأنها آيات دالة على قدرته العظيمة، وأنه الخلاق العليم  وأنه القادر على كل شيء.  أما العبد فليس له أن يحلف إلا بالله، المخلوق ليس له أن يحلف إلا بربه، ولا يجوز الحلف بالأنبياء، ولا بالملائكة، ولا بالأمانة، ولا بالأصنام، ولا بشرف فلان، ولا غير ذلك، يقول النبي ﷺ: من كان حالفًا فليحلف بالله، أو ليصمت ويقول -عليه الصلاة والسلام-: من حلف بشيء دون الله؛ فقد أشرك خرجه الإمام أحمد بإسناد صحيح في أحاديث كثيرة، ومنها قوله -عليه الصلاة والسلام-: من حلف بالأمانة فليس منا وقوله سبحانه: وَالْيَوْمِ الْمَوْعُودِ [البروج:2] يعني: يوم القيامة. وقوله: وَشَاهِدٍ وَمَشْهُودٍ [البروج:3] الشاهد: هو يوم الجمعة في قول جماعة من أهل العلم، والمشهود: هو يوم عرفة؛ لأنه يشهده الأمم الكثيرة من الحجاج، وهما يومان عظيمان، يوم الجمعة هو خير أيام الأسبوع، وأفضلها، فيه خلق آدم، وفيه أدخل الجنة، وفيه أخرج منها، وفيه تقوم الساعة، وفيه ساعة لا يرد فيها سائل، يستجيب الله فيها الدعاء، ويوم عرفة فيها وقفة الحجاج، وفيها دنو الرب من عباده  كما في الحديث الصحيح يقول النبي ﷺ: ما من يوم أكثر عتيقًا من النار من يوم عرفة، وإن الله سبحانه ليدنو، فيباهي بأهل الموقف الملائكة، فيقول: ماذا أراد هؤلاء ويقول فيه النبي ﷺ: الحج عرفة. وسئل النبي ﷺ عن صوم يوم عرفة -يعني: لغير الحجاج- فقال: يكفر الله به السنة التي قبلها، والتي بعدها أما الحجاج فلا يشرع لهم الصيام، بل ينهون عن صيام يوم عرفة في حال الحج، السنة أن يقف الحاج مفطرًا، لا صائمًا، كما وقف النبي ﷺ في حجة الوداع مفطرًا. وقوله -جل وعلا-: قُتِلَ أَصْحَابُ الأُخْدُودِ ۝ النَّارِ ذَاتِ الْوَقُودِ ۝ إِذْ هُمْ عَلَيْهَا قُعُودٌ ۝ وَهُمْ عَلَى مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ[البروج:4-7] يبين  عظم جريمة أهل الأخدود، ولهذا قتل أصحاب الأخدود، يعني: لعنوا بجريمتهم العظيمة الشنعاء، حيث ألقوا المؤمنين في الأخدود إذا لم ينقادوا لباطلهم، فهذا يحذر من الاستجابة لأهل الباطل، ويدل على أن الواجب على المؤمن أن يحذر أسباب الهلاك، وأن يبتعد عن الباطل وأهله. وفي شريعة محمد ﷺ شرع الله للمكره أن يدفع الإكراه بالاستجابة لما طلب منه مع طمأنينة قلبه بالإيمان، وهذا من فضل الله  أن المكره إذا أكره على الكفر، والضلال فله أن ينطق به؛ متابعة لهم، ودفعًا للظلم مع إيمان قلبه، وطمأنينة قلبه بالإيمان، ويسمى المكره كما في قوله -جل وعلا-: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالإِيمَانِ [النحل:106] فإذا ألزموه بالكفر، أو يحرقوه، أو يقتلوه، أو يضربوه؛ فله أن ينطق بالكفر، مع الإيمان والطمأنينة في القلب، كما فعل بعض الصحابة في عهد النبي ﷺ وأذن لهم النبي بذلك -عليه الصلاة والسلام- فالإكراه بالضرب، أو القتل، أو نحو ذلك مما يضر العبد ضررًا بينًا يبيح له أن يتكلم بكلمة الكفر إذا كان قلبه مطمئنًا بالإيمان، وإنما قالها موافقة على دفع الشر باللسان فقط. وهذا من رحمة الله لهذه الأمة، وإحسانه إليها  قال تعالى: وَمَا نَقَمُوا مِنْهُمْ [البروج:8] يعني: من هؤلاء الذين ألقوا في النار، وهم أصحاب الأخدود، وما نقم منهم المشركون، والكفار الظلمة إِلَّا أَنْ يُؤْمِنُوا بِاللَّهِ الْعَزِيزِ الْحَمِيدِ [البروج:8] يعني: ما عابوا عليهم، ولا عاقبوهم إلا من أجل إيمانهم، وهذا عيب، هو محل المدح، هو عيب عند أهل الباطل، ولكنه مدح، وشرف لأهل الإيمان، فنسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15709/تفسير-سورة-البروج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_720/nour_72001.mp3","categories":["التفسير"]},{"id":16987,"question":"يسأل عن تفسير قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم لِلرِّجَالِ نَصِيبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالأَقْرَبُونَ وَلِلنِّسَاءِ نَصِيبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ نَصِيبًا مَفْرُوضًا[النساء:7]؟","title":"تفسير قوله تعالى: {للرجال نصيب مما ترك الوالدان…}","answer":"الجواب: على ظاهر الآية الكريمة حق لِلرِّجَالِ نَصِيبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالأَقْرَبُونَ وَلِلنِّسَاءِ نَصِيبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ نَصِيبًا مَفْرُوضًا[النساء:7] أجملها هنا، وبيّنها في الآيات الأخرى، بيّنها فيما بعدها من الآيات الآتية: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ[النساء:11].. إلى آخر الآيات. فمن الرجال: الزوج يرث زوجته، والأب يرث أولاده، والأم ترث أولادها، وهكذا الإخوة، وهكذا البنون يرثون من آبائهم وأمهاتهم، فالرجال والنساء يتوارثون، كل يعطى حقه المفصل في آيات المواريث، في سورة النساء في أولها، وفي آخرها، وفي الأحاديث الصحيحة، الرجل والمرأة كل يعطى حقه نصيبًا مفروضًا، كما بيَّن سبحانه أن للرجل النصف من زوجته إذا كان ما لها أولاد، والربع إذا كان لها أولاد ولو واحدًا، والزوجة تعطى الربع من زوجها إذا كان ما له أولاد، وإذا كان له أولاد ولو من غيرها؛ تعطى الثمن، والأب يعطى السدس إذا كان لولده أولاد، والأم كذلك تعطى السدس، وإذا كان ليس له أولاد تعطى الثلث إلا أن يكون له إخوة فإنها تعطى السدس، والأب إذا كان ليس لولده أولاد يأخذ المال كله إذا كان مال له يأخذه عصبًا، أو فرضًا مقدرًا لا عصبًا، وهكذا بقية الورثة، كلهم داخلون في الآية الكريمة لِلرِّجَالِ نَصِيبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالأَقْرَبُونَ [النساء:7] للرجال: جنس يشمل الآباء، والأولاد، والإخوة، وهكذا النساء: يشمل الأمهات، والزوجات، والبنات، والأخوات، فصل الله مواريثهم كلها . نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15766/تفسير-قوله-تعالى-للرجال-نصيب-مما-ترك-الوالدان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_766/nour_76606.mp3","categories":["التفسير"]},{"id":17067,"question":"نعود إلى رسالة السائل: فرحان حمد، يقول: ما تفسير قوله تعالى: فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالأَرْضُ وَمَا كَانُوا مُنظَرِينَ [الدخان:29] ؟","title":"تفسير قوله تعالى: {فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالأَرْضُ...}","answer":"الجواب:  ذكر العلماء في هذا أنهم ليس لهم أعمالٌ صالحة، وأن السماء والأرض تبكي إذا فقدت الأعمال الصالحة من أهل الخير. أما هؤلاء لا خير فيهم، وليس لهم أعمال تصعد، فلهذا لا تبكي عليهم السماء، ولا الأرض لعدم أعمالهم الطيبة، نسأل الله العافية.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15872/تفسير-قوله-تعالى-فما-بكت-عليهم-السماء-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58807.mp3","categories":["التفسير"]},{"id":17347,"question":"من ليبيا المستمع إسماعيل الأمين عيسى رسالة يسأل فيها عن تفسير بعض الآيات، يقول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم وَإِنْ يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ وَإِلَى اللَّهِ تُرْجَعُ الأُمُورُ [فاطر:4]؟","title":"تفسير قوله تعالى: {وإن يكذبوك فقد كذبت رسل من قبلك}","answer":"الجواب: الرب -جل وعلا- يسلي نبيه ﷺ، ويصبره حتى لا يجزع من تكذيب قومه له، فقد كذبت أقوام كثيرة لرسلها -عليهم الصلاة والسلام- فيقول له: وَإِنْ يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ [فاطر:40] يعني: لك فيهم أسوة، فلا تجزع، وعليك بالصبر، ولهذا قال في الآية الأخرى: فَاصْبِرْ كَمَا صَبَرَ أُوْلُوا الْعَزْمِ مِنَ الرُّسُلِ وَلا تَسْتَعْجِلْ لَهُمْ [الأحقاف:35]، وقال: وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا [الطور:48] فالله يأمر نبيه بالصبر، والتأسي بالرسل الماضين، فقد كذبوا، وأوذوا، فصبروا، فهو كذلك عليه أن يصبر كما صبروا، وأن يتحمل كما تحملوا، وله عند الله الأجر العظيم، والخير الكثير، والله سبحانه هو الذي يهدي من يشاء، قال تعالى: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272] وقال سبحانه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56] فلا بد من التحمل والصبر. والله -جل وعلا- هو الحكيم العليم فيما يأمر به، وفيما ينهى عنه، وفي توفيق هذا للإسلام، والطاعة، وخذلان الآخر حتى لا يسلم، ولا يقبل الحق، هو الحكيم العليم -جل وعلا- فعلى العبد أن يسأل الله التوفيق، وأن يستعين به على الخير، وأن يحذر الشر، وأسبابه، وأن يصبر كما صبر غيره، وهكذا الرسل -عليهم الصلاة والسلام- عليهم أن يصبروا، وعلى نبينا ﷺ أن يصبر كما صبر من قبله. وأما الآية الأخرى ففيها التحذير من الاغترار بالدنيا، والاغترار بالشيطان وهو الغرور، يعني: يجب على المؤمن أن يحذر الدنيا وشهواتها الفاتنة ولهذا قال -جل وعلا-: يَا أَيُّهَا النَّاسُ إِنَّ وَعْدَ اللَّهِ حَقٌّ [فاطر:5] وعده لكم بالحساب، والجزاء، والجنة، والنار، وقيام الساعة كله حق، لابد من قيام القيامة، ولابد من الجزاء على الأعمال، ولابد من الجنة لأهل الإيمان، والتقوى والنار لأهل الكفر، والنفاق كله حق. ولهذا قال: فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا [فاطر:5]، يعني: بزينتها، وأموالها، وشهواتها، ومآكلها، ومشاربها، وغير ذلك مما فيها، فهي دار الزوال، دار الفناء، كما قال تعالى: كُلُّ مَنْ عَلَيْهَا فَانٍ [الرحمن:26] وقال سبحانه: وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ الْغُرُورِ [آل عمران:185]. فلا يليق بالعاقل المؤمن.. لا يليق به أن يغتر بها، وزينتها، وأهلها، وما أعطوا من الدنيا، بل يحذر، ويستعد للآخرة، ويستعين بنعم الله على طاعة الله، ولا يغتر بالشيطان، وهو الغرور، فإنه يزين للناس الباطل، ويغرهم، ويدعوهم إلى الركون للدنيا، ويدعوهم إلى التكذيب بالآخرة، ويزين لهم هذه العاجلة، وربما زين لهم الإصرار على المعاصي، وقال: التوبة بعد ذلك، إذا لم يجد حيلة في تكذيبهم، وإنكارهم للآخرة، زين لهم أنهم يتساهلون بالمعاصي، وقال: في إمكانكم التوبة بعد ذلك، والله غفور رحيم، ونحو هذا مما يغرهم به. فالواجب الحذر من طاعة الغرور الشيطان، والحذر من المعاصي كلها، والبدار بالتوبة عند وجود المعصية؛ ولهذا قال بعدها: إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا [فاطر:6] يعني: عاملوه معاملة الأعداء، فهو عدو مبين، ثم قال سبحانه: إِنَّمَا يَدْعُوا حِزْبَهُ يعني: أتباعه لِيَكُونُوا مِنْ أَصْحَابِ السَّعِيرِ [فاطر:6] هذه مهمته، وهذه دعوته، وهذا سبيله، الدعوة إلى النار. فالواجب على العاقل أن يحذر هذا العدو المبين، وألا يطيعه فيما يدعو إليه من الباطل، وأن يحذر وساوسه، وما يزينه من المعاصي؛ لعله ينجو. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16204/تفسير-قوله-تعالى-وان-يكذبوك-فقد-كذبت-رسل-من-قبلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83404.mp3","categories":["التفسير"]},{"id":17401,"question":"تستفسر عن الآية الكريمة سماحة الشيخ في قوله تعالى: يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَاءُ [النحل:93].","title":"تفسير قوله تعالى: {يضل من يشاء ويهدي من يشاء}","answer":"الجواب: على ظاهرها، هو الذي يهدي من يشاء  الهداية بيده -جل وعلا- يهدي من يشاء، ويضل من يشاء، ليست بيد العبد، العبد ليس بيده إلا دعاء الله، والضراعة إليه، والعمل بطاعته، والجد في الطاعة، والله الموفق، يهدي من يشاء، ويضل من يشاء، له الحكمة البالغة . ولكن العبد يسأل ربه الهداية، كما قال -جل وعلا- في سورة الفاتحة: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] والله يقول -جل وعلا-: كلكم ضال إلا من هديته، فاستهدوني أهدكم هكذا جاء في الحديث الصحيح القدسي، فالمؤمن، والعبد يسأل ربه الهداية، والتوفيق، والصلاح، ويحرص على أسباب الخير، ويصحب الأخيار.. هكذا، ويسأل ربه الهداية، ربنا هو الذي يهدي من يشاء، نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16263/تفسير-قوله-تعالى-يضل-من-يشاء-ويهدي-من-يشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77105.mp3","categories":["التفسير"]},{"id":17404,"question":"تستفسر عن الآية الكريمة سماحة الشيخ في قوله تعالى: يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَاءُ [النحل:93].","title":"تفسير قوله تعالى: {يضل من يشاء ويهدي من يشاء}","answer":"الجواب: على ظاهرها، هو الذي يهدي من يشاء  الهداية بيده -جل وعلا- يهدي من يشاء، ويضل من يشاء، ليست بيد العبد، العبد ليس بيده إلا دعاء الله، والضراعة إليه، والعمل بطاعته، والجد في الطاعة، والله الموفق، يهدي من يشاء، ويضل من يشاء، له الحكمة البالغة . ولكن العبد يسأل ربه الهداية، كما قال -جل وعلا- في سورة الفاتحة: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] والله يقول -جل وعلا-: كلكم ضال إلا من هديته، فاستهدوني أهدكم هكذا جاء في الحديث الصحيح القدسي، فالمؤمن، والعبد يسأل ربه الهداية، والتوفيق، والصلاح، ويحرص على أسباب الخير، ويصحب الأخيار.. هكذا، ويسأل ربه الهداية، ربنا هو الذي يهدي من يشاء، نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16263/تفسير-قوله-تعالى-يضل-من-يشاء-ويهدي-من-يشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77105.mp3","categories":["التفسير"]},{"id":17453,"question":"السؤال الثاني في هذه الرسالة، والتي بعث بها مستمع لم يذكر الاسم يقول: نرجو تفسير الآية الكريمة في قوله تعالى: كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ [القصص:88]؟","title":"تفسير قوله تعالى: {كل شيء هالك إلا وجهه}","answer":"الجواب: على ظاهرها كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ [القصص:88]، كل الناس يموتون، كل الناس يموتون إلا الرب -جل وعلا- فإنه الحي الذي لا يموت، كما قال سبحانه: وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لا يَمُوتُ [الفرقان:58] فهو سبحانه الباقي الدائم لا يموت -جل وعلا- أما بنو آدم، والملائكة كلهم يموتون، ثم يحييهم الله -جل وعلا- يوم القيامة، ويجازيهم بأعمالهم كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ [آل عمران:185] وكُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ [القصص:88] ويقول -جل وعلا-: وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالإِكْرَامِ [الرحمن:27] كُلُّ مَنْ عَلَيْهَا فَانٍ ۝ وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالإِكْرَامِ [الرحمن:26-27] فهو سبحانه الحي الذي لا يموت، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16322/تفسير-قوله-تعالى-كل-شيء-هالك-الا-وجهه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77210.mp3","categories":["التفسير"]},{"id":17462,"question":"هذا سائل من اليمن يقول في هذا  سماحة الشيخ! ما هو تفسير هذه الآية الكريمة: أَلا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ۝ الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ [يونس:62-63]؟","title":"ما معنى: {أَلا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ}؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. فهذه الآية الكريمة فيها بيان حال أولياء الله، وأنهم لا خوف عليهم ولا حزن عليهم؛ لإيمانهم وتقواهم يقول -جل وعلا-: أَلا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ[يونس:62]، ثم فسرهم فقال: الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ[يونس:63].  فأولياء الله: هم أهل الإيمان والتقوى، هم الذين أخلصوا لله العبادة، واستقاموا على دينه، واتقوه -جل وعلا- فأدوا فرائضه، وتركوا محارمه، ووقفوا عند حدوده، هؤلاء هم أولياء الله، أهل الإيمان والتقوى .. أهل البصيرة .. أهل الصدق الذين أخلصوا لله العبادة، ولم يشركوا به شيئًا، ثم أدوا فرائضه، وابتعدوا عن محارمه، ووقفوا عند حدوده، هؤلاء هم أولياء الله، ليس عليهم خوف، ولا حزن، بل لهم الجنة والكرامة والسعادة، لهذه الآية الكريمة: أَلا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ۝ الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ[يونس:62-63] لا خوف عليهم في المستقبل، ولا يحزنوا على ما خلفوا في الدنيا. وهم المذكورون في قوله -جل وعلا-: إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُوْلَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ ۝ جَزَاؤُهُمْ عِنْدَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ذَلِكَ لِمَنْ خَشِيَ رَبَّهُ[البينة:7-8] وفي قوله سبحانه: إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا ۝ خَالِدِينَ فِيهَا لا يَبْغُونَ عَنْهَا حِوَلًا[الكهف:107-108]، والآيات في هذا المعنى كثيرة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16330/ما-معنى-الا-ان-اولياء-الله-لا-خوف-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77301.mp3","categories":["التفسير"]},{"id":17578,"question":"من الجمهورية العربية السورية محافظة حمص مستمع رمز إلى اسمه بالحروف ( ص. ح. ج ) يسأل عن تفسير قول الحق تبارك وتعالى: عَلَيْكُمْ أَنفُسَكُمْ لا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ [المائدة:105]؟ وهل معنى هذا أن نترك الأمر بالمعروف والنهي عن المنكر؟","title":"تفسير قوله تعالى: {عليكم أنفسكم...}","answer":"الجواب: الآية الكريمة تدل على أن الواجب على الإنسان أن يعتني بنفسه وأن يهتم بها، وأن يجتهد في صلاحها، ولا يضره من ضل بعد ذلك إذا اهتدى، الإنسان مسئول عن نفسه ولا يضره ضلال غيره، يقول الله جل وعلا: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [فاطر:18]، وفي الحديث الصحيح يقول النبي ﷺ: لا يجني الجاني إلا على نفسه، فعلى المؤمن أن يسعى في صلاح نفسه واستقامتها على طاعة الله ورسوله، ولا يضره من ضل إذا اهتدى. والذي يترك الأمر بالمعروف والنهي عن المنكر ما اهتدى، فهو ناقص الهداية ناقص الإيمان، فالمعنى أنه لا يضره من ضل إذا أدى الواجب الذي عليه، ومن الواجب عليه أن يأمر بالمعروف وينهى عن المنكر، هذا من الواجب عليه، وقد خطب الصديق  أبو بكر الناس، وقال لهم: إن بعض الناس يقرأ هذه الآية ويضعونها في غير موضعها، وإني سمعت النبي يقول ﷺ: إن الناس إذا رأوا المنكر فلم يغيروه أوشك أن يعمهم الله بعقابه. ومراده  أنه ما يكون مهتدي من ضيع الأمر بالمعروف والنهي عن المنكر، يكون ناقص الهداية ناقص الإيمان ضعيف الإيمان، فمعنى إذا اهتديم يعني: إذا أديتم الواجب الذي عليكم وتركتم ما حرم الله عليكم، لا يضركم من ضل بعد ذا... لا يضرك ضلال أبيك ولا أخيك ولا أهل بلدك ولا الناس كلهم، لا يضرك، إذا أديت الواجب واجتهدت في الواجب فإنه لا يضرك من ضل، وربك يقول سبحانه: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [فاطر:18]. لكن إذا قصرت في الواجب عليك يضرك، فإذا كنت لا تدعو إلى الله ولا تأمر بالمعروف ولا تنهى عن المنكر، ولا تؤدي ما أوجب الله عليك لحق أولادك أو لحق زوجتك أو لحق جيرانك، فأنت ناقص الهداية حينئذ، يضرك ذلك، حتى تؤدي الواجب الذي عليك لله ولعباده.\nومن حق الله عليك أن تؤدي ما أوجب عليك من الطاعات وأن تترك ما حرم الله عليك، ومن حق الله عليك أن تأمر بالمعروف وأن تنهى عن المنكر، وأن تنصح لله ولعباده، وأن تدعو إلى الله على حسب طاقتك، ومن الحق عليك أيضًا أن تؤدي حق زوجتك وأولادك بنصيحتهم وتوجيههم إلى الخير، وتربيتهم التربية الإسلامية، وأن تقوم بحق جيرانك من إكرامهم والإحسان إليهم، وكف الأذى عنهم، وإكرام ضيفك.. إلى غير هذا من الحقوق، فالذي لا يؤدي الحقوق التي عليه ما يسمى مهتدي، يسمى ناقص الهداية، ضعيف الإيمان، حتى يؤدي الواجبات التي عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16509/تفسير-قوله-تعالى-عليكم-انفسكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_839/nour_83910.mp3","categories":["التفسير"]},{"id":17586,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين وقع في أول رسالته بقوله: أنا المواطن (أ. ع. م) ، أخونا له جمع من الأسئلة من بينها يسأل عن تفسير قول الله تعالى: إِنَّ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَاسْتَكْبَرُوا عَنْهَا لا تُفَتَّحُ لَهُمْ أَبْوَابُ السَّمَاءِ وَلا يَدْخُلُونَ الْجَنَّةَ حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ وَكَذَلِكَ نَجْزِي الْمُجْرِمِينَ [الأعراف:40]؟","title":"تفسير قوله تعالى: {إن الذين كذبوا بآياتنا واستكبروا عنها...}","answer":"الجواب: على ظاهرها، من كذب بآيات الله واستكبر عن اتباع الحق فهكذا شأنه، لا ترفع روحه إلى السماء بل ترد إلى الأرض وإلى جسده حتى يمتحن ويختبر ويعاقب في قبره ثم تنقل إلى النار نسأل الله العافية، كما قال تعالى في آل فرعون : النَّارُ يُعْرَضُونَ عَلَيْهَا [غافر:46] يعني: على النار غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ [غافر:46]، وهكذا غيرهم، من استكبر عن الحق ولم يتبع الهدى لا تفتح له أبواب السماء ولا تصعد روحه إلى السماء ولا إلى الله  بل ترد إلى جسدها الخبيث وتعاقب في قبرها مع عقوبة النار يوم القيامة نسأل الله العافية، وكذلك لا يدخلون الجنة أبدًا، ولهذا بين سبحانه أنه لا يدخل الجنة حتى يلج الجمل في سم الخياط، ومعلوم أن الجمل لا يلج في سم الخياط، سم الخياط يعني: خرق الإبرة، والمقصود: أن هذا مستحيل أن يدخل الجنة، كما أن دخول الجمل في سم الخياط مستحيل فهكذا دخولهم الجنة لكفرهم وضلالهم مستحيل دخولهم الجنة، بل هم إلى النار أبد الآباد، نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16515/تفسير-قوله-تعالى-ان-الذين-كذبوا-باياتنا-واستكبروا-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84102.mp3","categories":["التفسير"]},{"id":17618,"question":"نعود في هذه الحلقة إلى رسالة إحدى الأخوات المستمعات، وهي (س. س) من المدينة المنورة حيث عرضنا جملة من أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل عن تفسير قول الحق تبارك وتعالى: قِيلَ لَهَا ادْخُلِي الصَّرْحَ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَنْ سَاقَيْهَا قَالَ إِنَّهُ صَرْحٌ مُمَرَّدٌ مِنْ قَوَارِيرَ قَالَتْ رَبِّ إِنِّي ظَلَمْتُ نَفْسِي وَأَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ رَبِّ الْعَالَمِينَ [النمل:44] أرجو من سماحتكم تفسير هذه الآية؟","title":"تفسير قوله تعالى: {قِيلَ لَهَا ادْخُلِي الصَّرْحَ...}","answer":"الجواب: الآية ظاهرة ليس فيها خفاء، هذا صرح عند سليمان ممرد بالقوارير ظنته ماء وكشفت عن ساقيها تحسب أنه ماء يخاض وإذا هو ليس بماء يخاض، ثم ظهر لها صحة ما دعاها إليه سليمان من دين الله وتوحيده فأخبرت أنها ظلمت نفسها بالكفر وأنها أسلمت مع سليمان لله رب العالمين بالدخول في الإسلام وقبول دعوة سليمان لها إلى الإسلام ثم تزوجها بعد ذلك عليه الصلاة والسلام.\nالمقصود أن الآية واضحة، وكان لكشف ساقيها أثرًا فيما ذكره المفسرون في تزوج سليمان لها لما رأى قدميها، والخاطب والراغب في النكاح له أن ينظر إلى قدميها وإلى وجهها وإلى يديها لا حرج في ذلك، وصار هذا الكشف سببًا لرغبة سليمان فيها فيما ذكر المفسرون، أما كونه وضع الصرح على هذه الصفة فهذا له أسباب اقتضت ذلك، رأى سليمان أن يضعه على هذه الصفة لأسباب رآها عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.\nالشيخ: الله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/16550/تفسير-قوله-تعالى-قيل-لها-ادخلي-الصرح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_843/nour_84303.mp3","categories":["التفسير"]},{"id":17632,"question":"أيضًا تصف حالها وتقول: إنها تقرأ بعض الآيات لكنها لا تفهمها؟","title":"الحث على الاستعانة بكتب التفسير في فهم القرآن","answer":"الجواب: عليها أن تقرأ قراءة واضحة وأن تتدبر وتتعقل وسوف تفهم ما يسر الله، وإذا لم تفهم تراجع كتب التفسير مثل الجلالين مثل ... البغوي مثل ابن كثير مثل تفسير الشوكاني تستعين بالتفاسير تستفيد، أو تسأل أهل العلم عما أشكل عليها من طريق الهاتف، من طريق المكاتبة، الحمد لله طرق العلم ميسرة، فإذا أشكل على الإنسان شيء من الآيات ما فهمها كاتب أهل العلم أو راجع كتب التفسير إن كان عنده كتب التفسير، إذا كان يقرأ حتى يستفيد، والحمد لله الآن الأشياء متيسرة بالمكاتبة وبالهاتف. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16574/الحث-على-الاستعانة-بكتب-التفسير-في-فهم-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84412.mp3","categories":["التفسير","القرآن وعلومه","مس المصحف"]},{"id":17659,"question":"أختكم فاطمة العتيبي تقول من عفيف، تقول: أرجو من سماحة الشيخ حفظه الله أن يفسر هذه الآية الكريمة من سورة النور في قوله تعالى: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ ... [النور:31]..إلى آخر الآية؟","title":"تفسير قوله تعالى: {وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ...}","answer":"الجواب: هذه واضحة، على المؤمنة أن تغض بصرها عند الرجال إلا عند الحاجة في الطريق، لا تمد بصرها للشهوة، أما عند النظر للحاجة للطريق فلا بأس، ومع حفظ الفروج: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] البعولة: الأزواج، أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ... [النور:31].. إلى آخر الآية، لا تبدي وجهها وقدميها ويديها إلا للزوج، أو من ذكروا في الآية الكريمة، والآية واضحة والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/16589/تفسير-قوله-تعالى-وقل-للمومنات-يغضضن-من-ابصارهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59429.mp3","categories":["التفسير","قضايا المرأة"]},{"id":17813,"question":"مناف من اليمن له هذا السؤال يقول: ما تفسير هذه الآية الكريمة في قوله تعالى: مَرَجَ الْبَحْرَيْنِ يَلْتَقِيَانِ ۝ بَيْنَهُمَا بَرْزَخٌ لا يَبْغِيَانِ ۝ فَبِأَيِّ آلاءِ رَبِّكُمَا تُكَذِّبَانِ [الرحمن:11-13]؟","title":"تفسير قول الله تعالى: {مرج البحرين يلتقيان...}","answer":"الجواب: على ظاهرها، الله جعل بين البحر المالح والحلو حاجز بقدرته العظيمة، هذا على حدة وهذا على حدة، لا يختلطان، هذا حلو وهذا مر مالح، فضلًا منه جل وعلا ورحمة منه لعباده، فهذا البحر له حلاوته، وهذا له ملوحته، وكل منهما فيه مصالحه. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16804/تفسير-قول-الله-تعالى-مرج-البحرين-يلتقيان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59719.mp3","categories":["التفسير"]},{"id":17837,"question":"نختم هذا اللقاء بسؤال السائل (حسن أ) يستفسر عن الآية الكريمة، ما تفسير الآية الكريمة: بَلَى مَنْ كَسَبَ سَيِّئَةً وَأَحَاطَتْ بِهِ خَطِيئَتُهُ فَأُوْلَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ[البقرة:81]؟","title":"تفسير قوله تعالى: {بلى من كسب سيئة...}","answer":"الجواب: هذه في المشركين يعني: سيئة شرك وخطيئة الشرك والكفر فهؤلاء هم المخلدون في النار، أما العاصي فهو تحت المشيئة كالزاني والسارق إذا لم يستحل ذلك، والعاق لوالديه، وشارب الخمر، والمرابي هؤلاء تحت المشيئة كما قال الله سبحانه في سورة النساء في موضعين من سورة النساء: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ[النساء:48].\nفالشرك والكفر لا يغفر إذا مات عليه الإنسان، الشرك الأكبر والكفر الأكبر هذا لا يغفر صاحبه مخلد في النار، أما الشرك الأصغر والكفر الأصغر فهذا صاحبه على خطر، فإن رجحت حسناته سلم من دخول النار، وإذا عذب على قدر ما مات عليه من الشرك الأصغر والكفر الأصغر، وهكذا أصحاب المعاصي إن عفا الله عنهم، وإلا عذبوا على قدر معاصيهم؛ تعذيبًا مؤقتًا، ثم يخرجهم الله من النار إلى الجنة إذا كانوا ماتوا على التوحيد والإسلام، لكن مات وهو زاني ما تاب، مات وهو سارق ما تاب، مات وهو عاق لوالديه ما تاب، مات وهو يأكل الربا، أو يشرب الخمر ما تاب؛ هذا تحت المشيئة بعضهم يعفو الله عنه، وبعضهم يدخل النار، ويعذب في النار على قدر المعصية التي فعلها، واستمر عليها، ثم يخرجه الله من النار بفضل رحمته جل وعلا إلى الجنة.\nولا يخلد في النار أبد الآباد إلا الكفار الكفر الأكبر والشرك الأكبر هم الذين يخلدون في النار أبد الآباد، كما قال الله في حقهم: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ[البقرة:167]، وقال في شأنهم سبحانه: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ[المائدة:37]، نسأل الله العافية.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16830/تفسير-قوله-تعالى-بلى-من-كسب-سيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77910.mp3","categories":["التفسير"]},{"id":17878,"question":"يستفسر عن الآية الكريمة يقول في الآية الكريمة: لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ[البقرة:226] ما معنى كلمة الإيلاء؟","title":"تفسير قوله تعالى: {للذين يؤلون من نسائهم}","answer":"الجواب: الآية: لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ[البقرة:226] يؤلون: يحلفون، الألية: اليمين، فإذا قال: والله ما أطؤك، والله ما أجامعك؛ فله مهلة أربعة أشهر، فإما أن يفي ويطأ وإما أن يطلق إذا كانت المرأة تطالب بذلك لقوله تعالى: لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِنْ فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ ۝ وَإِنْ عَزَمُوا الطَّلاقَ فَإِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ[البقرة:226-227]. فإذا كانت الزوجة تطالب تقول: إما أن يفي وإما أن يطلق، فالقاضي .. المحكمة تلزمه تقول له: إما أن تفي تجتمع بأهلك وتحسن العشرة وتجامع أهلك؛ وإلا فالطلاق، أما إذا كانت المرأة تسمح تقول: لا، ..... .......... فلا حرج ولو زاد على أربعة، لكن إذا كانت تطالب تقول: لا، أبي حقي، إما أن يفي ويطأ، ويجامعني، ويحسن العشرة، وإما أن يطلق فإنه يحبس يمنع يحبس حتى إما أن يطلق وإما أن يفي.\nالمقدم: جزاكم الله خيرًا وبارك فيكم على هذا التوجيه المبارك سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16883/تفسير-قوله-تعالى-للذين-يولون-من-نساىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78006.mp3","categories":["الإيلاء","التفسير"]},{"id":17901,"question":"تقول: من هم المحسنون الذين ورد ذكرهم في كثير من الآيات القرآنية؟ وهل المعنى واحد؟","title":"معنى الإحسان والمقصود بالمحسنين","answer":"الجواب: يقول الله : وَأَحْسِنُوا إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ [البقرة:195]، ويقول جل وعلا: إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا وَالَّذِينَ هُمْ مُحْسِنُونَ [النحل:128]، فالإحسان: هو أداء الواجبات وترك المحرمات والاجتهاد في أنواع الخير زيادة على ذلك من الصدقة على الفقير ومواساة المحتاج، والإعانة على الخير، وعيادة المريض، الشفاعة في حق المظلوم ونصره، ردع الظالم، تشميت العاطس، رد السلام، البداءة بالسلام، الأمر بالمعروف، النهي عن المنكر، الدعوة إلى الله، تعليم الناس الخير.. هكذا أهل الإحسان هم الذين يؤدون الواجبات وينتهون عن المحرمات، ومع ذلك يجتهدون في وجوه الخير، وأعمال الخير الذي لا تجب عليهم يجتهدون فيها حتى يستوفوا منها الخير الكثير كما في الحديث يقول ﷺ لما سئل عن الإحسان قال: أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك.\nفالمحسن يعبد الله كأنه يراه كأنه يشاهده، فإن لم يستحق هذه الدرجة عمل على أن الله يراقبه، وأن الله  يطلع على أعماله وهو يستحضر هذه المشاهدة، يستحضرها حتى يكون ذلك أشجع له على فعل الخيرات والمسارعة إلى الطاعات والكف عن المحرمات والعناية بالواجبات.. هكذا المحسن، يحرص على كل خير من واجب ومستحب ويتباعد عن كل شر وعن كل ما ينبغي تركه ولو كان غير محرم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16940/معنى-الاحسان-والمقصود-بالمحسنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84613.mp3","categories":["التفسير","الرقائق"]},{"id":17913,"question":"تسأل سماحتكم: عما تطمئنون إليه في تفسير مثل قوله تعالى: لا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ [القيامة:1]، لا أُقْسِمُ بِهَذَا الْبَلَدِ [البلد:1] ونحو ذلك؟","title":"ما معنى: {لَا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ} و{لَا أُقْسِمُ بِهَذَا الْبَلَدِ}؟","answer":"الجواب: المعروف عند العلماء أن (لا) نافية لما يقوله المشركون، ليس الأمر كما قال المشركون من كذا وكذا بخلاف الحق، ثم قال: (أقسم) فهي نافية لشيءٍ محذوف، وأقسم ثابتة، مثبتة. وقال بعضهم: إنها صلة -يعني: زائدة- يستعملها العرب من غير قصد لمعناها، والمعنى: أقسم بيوم القيامة، أقسم بهذا البلد، أن الله يقسم بها ، والمشهور هو الأول؛ أنها نفي لأشياء لا كما يقول المشركون من تكذيب الرسول ﷺ، أو إنكار القرآن، أو ما أشبه ذلك، مما يقوله أهل الشرك، بل ما قالوه باطل، وأقسم بيوم القيامة، أقسم بها ...إلخ. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16922/ما-معنى-لا-اقسم-بيوم-القيامة-ولا-اقسم-بهذا-البلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72817.mp3","categories":["التفسير"]},{"id":18006,"question":"يسأل عن تفسير قوله تعالى: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]؟","title":"تفسير قوله تعالى: {ولله الأسماء الحسنى فادعوه بها}","answer":"الجواب: يقول الله سبحانه: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، منها: الرحمن.. الرحيم.. السميع.. البصير.. القدير.. القوي.. الحكيم.. وغيره من أسماء الله المذكورة في القرآن أو في السنة الصحيحة يدعى بها، تقول: يا رحمن! يا رحيم! اغفر لي ارحمني، يا سميع يا بصير! الطف بي، يا جواد يا كريم يا حي يا قيوم! يا ذا الجلال والإكرام! ارحمني.. إلى غير هذا، هذا معناه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17022/تفسير-قوله-تعالى-ولله-الاسماء-الحسنى-فادعوه-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84909.mp3","categories":["التفسير"]},{"id":18029,"question":"أختنا من السودان (ع. ن. س) من الشمالية تسأل - أيضًا - وتقول: قال  -أعوذ بالله من الشيطان الرجيم-: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48].. وقال تعالى: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا.. [النساء:93] الآية، أرجو من سماحة الشيخ أن يتفضل بالجمع بين الآيتين الكريمتين؟","title":"الجمع بين آية مغفرة الذنوب وتخليد القاتل في النار","answer":"الجواب: ليس هناك بحمد الله اختلاف، فالآية الأولى فيها بيانه سبحانه لعباده أن ما دون الشرك تحت مشيئته، قد يغفره فضلًا منه سبحانه، وقد يعاقب من مات على المعصية بقدر معصيته؛ لانتهاكه حرمات الله، ولتعاطيه ما يوجب غضب الله، أما الشرك فإنه لا يغفر من مات عليه فإنه لا يغفر له، بل له النار مخلدًا فيها أبد الآباد ، نعوذ بالله من ذلك. وأما الآية الثانية ففيها الوعيد لمن قتل نفسًا بغير حق، بأنه يعذب، وأن الله يغضب عليه بذلك، ولهذا قال سبحانه: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93]، معنى ذلك أن هذا هو جزاؤه إن جازاه سبحانه، فهو مستحق لذلك، وإن عفا سبحانه فهو أهل العفو وأهل المغفرة جل وعلا. وقد يعذب بما ذكر الله مدة من الزمن في النار ثم يخرجه الله من النار، وهذا الخلود خلود مؤقت، ليس مثل خلود الكفار، فإن الخلود خلودان: خلود دائم أبدًا لا ينتهي، وهذا هو خلود الكفار في النار، كما قال الله سبحانه في شأنهم: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167]، هكذا في سورة البقرة، وقال في سورة المائدة: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37]. أما العصاة: من قاتل النفس بغير حق، والزاني، والعاق لوالديه، وآكل الربا، وشارب المسكر؛ إذا ماتوا على هذه المعاصي، وهكذا أشباههم فهم تحت مشيئة الله، كما قال سبحانه: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]. فإن شاء جل وعلا عفا عنهم لأعمالهم الصالحة التي ماتوا عليها، أو لتوحيدهم وإخلاصهم لله، وكونهم مسلمين، أو بشفاعة الشفعاء فيهم مع توحيدهم وإخلاصهم، وقد يعاقبهم سبحانه ولا يحصل لهم عفو، فيعاقبون بإدخالهم النار وتعذيبهم فيها على قدر معاصيهم، ثم يخرجون منها، كما تواترت بذلك الأحاديث عن رسول الله عليه الصلاة والسلام أنه يشفع في العصاة من أمته، وأن الله يحد له حدًا في ذلك عدة مرات، يشفع ويخرج جماعة بإذن الله، ثم يعود فيشفع، ثم يعود فيشفع، ثم يعود فيشفع عليه الصلاة والسلام، أربع مرات، وهكذا الملائكة، وهكذا المؤمنون، وهكذا الأفراط، كلهم يشفعون ويخرج الله من النار بشفاعتهم من شاء  ويبقى في النار بقية من العصاة من أهل التوحيد والإسلام، فيخرجهم الرب سبحانه بفضله ورحمته بدون شفاعة أحد، ولا يبقى في النار إلا من حكم عليه القرآن بالخلود الأبدي -نسأل الله السلامة- وهو الكفار. وبهذا تعلم السائلة الجمع بين الآيتين، وما جاء في معناهما من النصوص، وأن أحاديث الوعد لمن مات على الإسلام على عمومها، إلا من أراد الله تعذيبه وشاء الله تعذيبه لمعصيته، فهو سبحانه الحكيم العليم في ذلك، يفعل ما يشاء، ويحكم ما يريد جل وعلا. ومنهم من لا يعذب فهذا فضلًا من الله لأسباب كثيرة: من أعمال صالحة، ومن شفاعة الشفعاء، وفوق ذلك رحمته وفضله  لمن بقي فيها من العصاة، لمن بقي في النار من العصاة، والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17055/الجمع-بين-اية-مغفرة-الذنوب-وتخليد-القاتل-في-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59905.mp3","categories":["التفسير"]},{"id":18078,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من المستمع: فاروق حسين إبراهيم، الأخ فاروق يسأل: تفسير قول الحق تبارك وتعالى: أعوذ بالله من الشيطان الرجيم: وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ[الضحى:11].","title":"تفسير قوله تعالى: {وأما بنعمة ربك فحدث}","answer":"الجواب: الآية على ظاهرها، الله أمر نبيه ﷺ أن يتحدث بنعم الله جل وعلا، وهذا من الشكر؛ لأن التحدث بالنعم من شكر الله  فالنعمة شكرها يكون بأمورٍ ثلاثة: الاعتراف بها باطنًا، وأنها من الله، ومن فضله ، والتحدث بها ظاهرًا بلسانه، والأمر الثالث: صرفها في مرضاة المنعم بها  والاستعانة بها على طاعة الله جل وعلا. فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ ۝ وَأَمَّا السَّائِلَ فَلا تَنْهَرْ ۝ وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ [الضحى:9-11] هذا خطاب للنبي ﷺ، وهكذا كل مسلم، وكل مسلمة؛ عليهما التحدث بنعم الله، نشكر الله على ذلك، الله أنعم علينا بنعمٍ كثيرة، نحمده على هذا، نشكره على هذا، يتحدث بنعم الله، نعمة السمع، البصر، الصحة، المال، الولد، الزوجة، الزوج، يتحدث بنعم الله، ويشكره سبحانه، يشكره على ذلك بطاعته، وترك معصيته. فلابد من الأمور الثلاثة: الإيمان بذلك في الباطن، وأن هذه من نعم الله، سواءٌ صحة، أو ولد، أو مال، يؤمن بقلبه أن هذا من نعم الله، وأنه سبحانه المحصي لذلك، ويتحدث بها بلسانه، بهذه النعم، ويشكر الله عليها بلسانه، ويشكر الله أيضًا بعمله، وذلك بطاعة الله في هذه النعمة، من أجل أن يستعين بها على طاعة الله، وأن يصرفها في مرضاته سبحانه، لا في المعاصي. نعم. المقدم: جزاكم الله خيرًا، إذًا هذا هو تفسير الآية الكريمة: وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ [الضحى:11]. الشيخ: نعم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17113/تفسير-قوله-تعالى-واما-بنعمة-ربك-فحدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73002.mp3","categories":["التفسير"]},{"id":18107,"question":"سؤال ورد إلى البرنامج من المستمع حسين إسماعيل العيدروس اليمن الديمقراطية حضرموت، يسأل عن تفسير قول الحق تبارك وتعالى، أعوذ بالله من الشيطان الرجيم: يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ فِي ظُلُمَاتٍ ثَلاثٍ [الزمر:6]، ما معنى الظلمات الثلاث؟ جزاكم الله خيراً.","title":"تفسير قوله تعالى: {يخلقكم في بطون أمهاتكم...}","answer":"الجواب: ذكر أهل العلم رحمة الله عليهم في التفسير أن معنى الآية: أن العبد يطور في الرحم خلقًا بعد خلق، أولًا يخلقه الله نطفة من مني المرأة ومني الرجل جميعًا أمشاج، ثم تحول هذه النطفة إلى علقة قطعة من الدم وهذا طور ثاني، ثم هذه العلقة يخلقها الله مضغة قطعة لحم بقدر ما يمضغ الماضغ، ثم يكون في هذه المضغة التخليق من الرأس والرجلين واليد ونحو ذلك، هذا معنى يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ [الزمر:6] يعني: تطوير يطور في بطن أمه خلقًا بعد خلق من طور إلى طور. وأما فِي ظُلُمَاتٍ ثَلاثٍ [الزمر:6] فسرها العلماء بأن الظلمات الثلاث هي: ظلمة الرحم، وظلمة المشيمة التي فيها الرحم، وظلمة البطن؛ بطن المرأة، فهي ظلمات ثلاث وفي الرحم، ثم في كيس المشيمة، ثم بعد ذلك ومن وراء البطن في داخل البطن داخل بطنها، فظلمة في بطن ظلمة، ظلمة الرحم، وظلمة المشيمة التي هي كيس يكون فيه الولد يكون فيه الرحم، كيس يكون فيه الولد ثم ظلمة الرحم ثم ظلمة البطن، والمشيمة تسقط في الغالب تسقط مع الولد أو بعده، هذا الكيس اللي يكون فيه الولد في بطن الرحم، ثم الرحم ظلمة ثانية، ثم البطن ظلمة ثالثة، وربك حكيم عليم  لا إله إلا هو. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17142/تفسير-قوله-تعالى-يخلقكم-في-بطون-امهاتكم","audio":"","categories":["التفسير"]},{"id":18113,"question":"أخونا له أسئلة أخرى فيسأل مثلًا ويقول: ما هو تفسير قوله تعالى أعوذ بالله من الشيطان الرجيم: مَا دَامَتِ السَّمَوَاتُ وَالأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ [هود:107]، في قوله تعالى في سورة هود: فَأَمَّا الَّذِينَ شَقُوا فَفِي النَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ ۝ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَوَاتُ وَالأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِمَا يُرِيدُ [هود:106-107]، والآية التي بعدها؟","title":"معنى قوله تعالى: {ما دامت السموات والأرض...}","answer":"الجواب: اختلف كلام أهل التفسير في هذا الاستثناء، وأحسن ما قيل في ذلك: أن الاستثناء يراد به ما يقع حال القيامة في موقف القيامة، وما يقع في حال القبور، كل هذا مستثنى، فإن المؤمنين والكافرين كلهم لهم نصيبهم، المؤمن له نصيبه من نعيم الله في قبورهم وفي موقفهم يوم القيامة وما يحصل لهم من التسهيل واللطف، والكافرون لهم نصيبهم من العذاب في المقابر وفي موقفهم أمام الله يوم القيامة. أما بعد دخول النار فليس فيها استثناء فأهل النار مخلدون أبد الآباد وهم الكفار، وأهل الجنة مخلدون في دار النعيم أبد الآباد لا يضعنون منها ولا يموتون ولا تخرب بلادهم، وهكذا الكفرة مخلدون في نار جهنم عند أهل السنة والجماعة مخلدون فيها أبد الآباد لا تخرب ولا يخرجون منها، كما قال الله  في أهل النار: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37]، وقال سبحانه: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167].  قال في أهل الجنة: خَالِدِينَ فِيهَا أَبَدًا [النساء:57]، فأهل الجنة دائمًا في نعيمهم وفي سرورهم وفي حبرتهم، لا يضعنون ولا تخرب بلادهم: إِنَّ الْمُتَّقِينَ فِي مَقَامٍ أَمِينٍ ۝  فِي جَنَّاتٍ وَعُيُونٍ ۝ يَلْبَسُونَ مِنْ سُندُسٍ وَإِسْتَبْرَقٍ مُتَقَابِلِينَ ۝ كَذَلِكَ وَزَوَّجْنَاهُمْ بِحُورٍ عِينٍ ۝ يَدْعُونَ فِيهَا بِكُلِّ فَاكِهَةٍ آمِنِينَ ۝ لا يَذُوقُونَ فِيهَا الْمَوْتَ إِلَّا الْمَوْتَةَ الأُولَى وَوَقَاهُمْ عَذَابَ الْجَحِيمِ ۝ فَضْلًا مِنْ رَبِّكَ ذَلِكَ هُوَ الْفَوْزُ الْعَظِيمُ [الدخان:51-57]، قال سبحانه: إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ ۝ ادْخُلُوهَا بِسَلامٍ آمِنِينَ ۝ وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ إِخْوَانًا عَلَى سُرُرٍ مُتَقَابِلِينَ ۝ لا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُمْ مِنْهَا بِمُخْرَجِين [الحجر:45-48]، في آيات كثيرات كلها دالة على خلود هؤلاء وخلود هؤلاء، أهل الجنة مخلدون فيها أبد الآباد، وأهل النار مخلدون فيها أبد الآباد يعني الكفرة. وقد ذهب بعض السلف إلى أن النار لها نهاية وأن أهلها يخرجون منها بعد النهاية أو يموتون فيها، وهذا القول شاذ عند أهل السنة والجماعة لا أساس له من الصحة، والذي عليه جمهور أهل السنة والجماعة: أن النار دائمة أبدًا، وأن أهلها مخلدون فيها أبد الآباد لا تخرب ولا يخرج منها أهلها، بل هم في عذاب دائم وخلود دائم، وهي باقية مقيمة لابِثِينَ فِيهَا أَحْقَابًا [النبأ:23] لا تنتهي، هكذا أخبر ربنا  في قوله سبحانه: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167]، يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37]، كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا [الإسراء:97]، فَذُوقُوا فَلَنْ نَزِيدَكُمْ إِلَّا عَذَابًا [النبأ:30]. ومن قال: إن لها أمدًا فهو قول ضعيف شاذ لا يعول عليه عند أهل السنة والجماعة. وأما العصاة من الموحدين فهؤلاء عند أهل السنة والجماعة إذا دخلوا النار لا يخلدون فيها، بل يقيمون فيها ما شاء الله، ثم يخرجهم الله منها فضلًا منه ورحمة ؛ لأنهم ماتوا على التوحيد والإسلام، لكن لهم معاصي ماتوا عليها لم يتوبوا منها، هؤلاء إذا دخلوا النار لا يخلدون عند أهل السنة والجماعة خلافًا للخوارج وخلافًا للمعتزلة ومن سار على مذهبهم من أهل البدع. أما أهل السنة والجماعة فمجمعون إجماعًا قطعيًا على أن العصاة لا يخلدون في النار، بل لهم أمد ينتهون إليه، كما دلت على ذلك الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام في الصحيحين وغيرهما: \"أن الرسول ﷺ يشفع للعصاة فيحد الله له حد، فيخرجهم من النار، ثم يعود فيشفع، ثم يعود فيشفع، ثم يعود فيشفع وفي كل مرة يحد الله له حدًا فيخرجهم من النار\"، وهكذا الملائكة، وهكذا المؤمنون، وهكذا الأفراط يشفعون كما صحت به الأخبار عن رسول الله عليه الصلاة والسلام، ثم يبقى بقية في النار لم تشملهم الشفاعات فيخرجهم الله سبحانه برحمته جل وعلا، كما صح بذلك الحديث عن رسول الله عليه الصلاة والسلام، وهذا هو الحق الذي لا ريب فيه، وهو قول أهل السنة والجماعة قاطبة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17149/معنى-قوله-تعالى-ما-دامت-السموات-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_851/nour_85102.mp3","categories":["التفسير"]},{"id":18115,"question":"السؤال الأخير لأخينا من الأردن عن قوله تعالى أعوذ بالله من الشيطان الرجيم: وَلا يَزَالُونَ مُخْتَلِفِينَ ۝ إِلَّا مَنْ رَحِمَ رَبُّكَ وَلِذَلِكَ خَلَقَهُمْ [هود:118-119]، وأيضًا: يسأل عن قوله تعالى: وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً وَلا يَزَالُونَ مُخْتَلِفِينَ ۝ إِلَّا مَنْ رَحِمَ رَبُّكَ وَلِذَلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ [هود:118-119]؟","title":"معنى قوله تعالى: {ولا يزالون مختلفين إلا من رحم ربك}","answer":"الجواب: ليس في هذا إشكال، الله سبحانه هو الحكيم العليم، ولو شاء لجمع الناس على الهدى، كما قال جل وعلا: وَلَوْ شَاءَ اللَّهُ لَجَمَعَهُمْ عَلَى الْهُدَى فَلا تَكُونَنَّ مِنَ الْجَاهِلِينَ [الأنعام:35]، قال سبحانه: وَلَوْ شِئْنَا لَآتَيْنَا كُلَّ نَفْسٍ هُدَاهَا وَلَكِنْ حَقَّ الْقَوْلُ مِنِّي لَأَمْلأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ [السجدة:13]، فالله سبحانه لو شاء لهداهم أجمعين جل وعلا، لكن له الحكمة البالغة والحجة الدامغة في إدخال من عصاه وخالف أمره، وأشرك به سبحانه النار لظلمه نفسه وتعديه حدود ربه ومخالفته ما جاءت به الرسل.  وله الحكمة البالغة والفضل الواسع على أوليائه وأهل طاعته في إدخالهم الجنة وإنجائهم من النار؛ لأنهم أطاعوا أمره واتبعوا شريعته ووقفوا عند حدوده، فجازاهم سبحانه أحسن الجزاء، هو جل وعلا خلقهم ليرحمهم، خلقهم لإدخالهم الجنة وإنجائهم من النار إذا قاموا بحقه واستقاموا على دينه، فإذا خرجوا عن طاعته وخرجوا عما أمرهم به، فقد توعدهم بالنار جزاءً وفاقًا لأعمالهم القبيحة وخروجهم عن طاعة ربهم  واتباعهم لأهوائهم، قال جل وعلا: فَأَمَّا مَنْ طَغَى ۝ وَآثَرَ الْحَيَاةَ الدُّنْيَا ۝ فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَى [النازعات:37-39]، قال سبحانه: وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40-41]. فهم مؤاخذون بأعمالهم القبيحة من كفر ونفاق ومعاصي كما أن أهل الجنة مجزيون بأعمالهم الطيبة وطاعتهم لربهم وإحسانهم في خدمته سبحانه جازاهم جل وعلا بكرامته وإدخالهم جنته والنظر إلى وجهه الكريم يوم القيامة وهم في دار النعيم، فضلًا منه وإحسانًا، هذا فضله جل وعلا، ولهذا قال جل وعلا: وَلا يَزَالُونَ مُخْتَلِفِينَ ۝ إِلَّا مَنْ رَحِمَ رَبُّكَ [هود:118-119]. فالمرحومون هم أهل السعادة والنجاة، وهم الذين خلقوا ليرحمهم  بتوفيقه وهدايته جل وعلا، وأولئك حرموا هذه الرحمة وحرموا هذا الخير بأعمالهم القبيحة، وابتعادهم عن طاعته وإيثارهم أهواءهم، فلما فعلوا ذلك استحقوا نقمته وغضبه ، والاختلاف واقع ومكتوب عليهم بسبب ما يقدمونه من أعمال سيئة، وبسبب اتباعهم لأهوائهم وشهواتهم وإيثارها على الحق وقع الاختلاف، فمن رحمه الله سلم من ذلك واتبع الحق، ومن لم يوفق لرحمة الله ولم يهد لسبيل الهدى بقي في ضلاله وعماه واختلافه، نسأل الله العافية، وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ [فصلت:46]، بل يجازيهم بأعمالهم، فمن عمل الصالحات وتابع المصطفى عليه الصلاة والسلام وتابع من قبله من الرسل رزقوا من ربهم فضله وإحسانه وفازوا بجنته وكرامته، ومن تابع الهوى وعصى الرسل وآثر الدنيا على الآخرة باء بالخيبة والندامة واستحق العقاب من ربه  على عمله الخبيث وعلى انحرافه عن طاعة مولاه . نعم.","link":"https://binbaz.org.sa/fatwas/17154/معنى-قوله-تعالى-ولا-يزالون-مختلفين-الا-من-رحم-ربك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_851/nour_85103.mp3","categories":["التفسير"]},{"id":18214,"question":"يقول الله  في كتابه المبين في سورة الصف الآية الرابعة عشرة: أعوذ بالله من الشيطان الرجيم. بسم الله الرحمن الرحيم: يَا أَيُّهَا الَّذِينَ آَمَنُوا كُونوا أَنصَارَ اللَّهِ كَمَا قَالَ عِيسَى ابْنُ مَرْيَمَ لِلْحَوَارِيِّينَ مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ [الصف:14]، أورد هذه الآية الكريمة مستمع من السودان، هو عمر سمير داود يسأل عن تفسير هذه الآية الكريمة، ويقول: بالذات: كيف قال عيسى: (من أنصاري) ثم (قال الحواريون نحن أنصار الله) ولم يقولوا: نحن أنصارك؟","title":"ما معنى: {يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا أَنْصَارَ اللَّهِ}؟","answer":"الجواب: الآية واضحة أن يكونوا أنصار الله، فأمر المؤمنين أن يكونوا أنصار الله، وأنصار الله هم أنصار دينه، الله ليس بحاجة إلى أحد من الناس، الله سبحانه غني عن عباده، ليس بحاجة إليهم، فأنصار الله هم أنصار دينه، والدعاة إليه وحماته حتى يظهر بين الناس وحتى يلتزمه الناس، كما قال : يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَنصُرُوا اللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ [محمد:7]، (تنصروا الله) أي: تنصروا دينه وشريعته وما أمر به، وتنصروا ترك محارمه وهكذا قوله سبحانه: وَلَيَنصُرَنَّ اللَّهُ مَنْ يَنصُرُهُ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ ۝ الَّذِينَ إِنْ مَكَّنَّاهُمْ فِي الأَرْضِ أَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنْكَرِ [الحج:40-41]. هذا نصر الله، بإقام الصلاة وإيتاء الزكاة، والأمر بالمعروف والنهي عن المنكر، والدعوة إلى الله ، وإقامة الجهاد في سبيل الله وردع المبطلين عن باطلهم وإقامة الحدود عليهم إلى غير ذلك، هذا هو النصر لدين الله، ومنه حديث ابن عباس المشهور: احفظ الله يحفظك، أي: احفظ دين الله باتباعه والاستقامة عليه يحفظك سبحانه؛ لأن الجزاء من جنس العمل، ومن حفظ الله باتباع دينه حفظه الله، ومن نصر الله نصره الله، فمعنى قوله سبحانه: يَا أَيُّهَا الَّذِينَ آَمَنُوا كُونوا أَنصَارَ اللَّهِ [الصف:14]، يعني: كونوا من أنصار دين الله، كونوا من أتباع الشرع ودعاة الحق والأمر بالمعروف والنهي عن المنكر. ثم ذكر عن عيسى عليه الصلاة والسلام أنه قال: من أنصاري؟ قال للحواريين من أنصاري إلى الله، يعني: من أنصاري إلى التوجه إلى الله والدعوة إليه، واتباع شريعته، هكذا ينبغي لأهل الإيمان أن يكونوا أنصاراً لله وأنصاراً للرسل، وأنصاراً لدعاة الحق، فمعنى: (من أنصاري إلى الله) يعني: من أنصاري في الدعوة إلى الله والتوجيه إليه، وإقامة دينه؟ (فقال الحواريون) وهم الأنصار، الحواري: هو الناصر، سمي حواري لنصرته للحق وقيامه بالحق، مثل قول النبي ﷺ: لكل نبي حواري، وحواريي الزبير يعني: ابن العوام، لما انتدب إلى الأحزاب بأمره عليه الصلاة والسلام. فالحواريون هم الأنصار، هم أنصار الحق، فقالوا هم في هذه الآية نَحْنُ أَنصَارُ اللَّهِ [الصف:14]؛ لأنهم يعلمون أن نصر النبي نصر لله، فلم يقولوا: أنصارك، أتوا بالأمر الأعلى الذي هو مقصود عيسى عليه الصلاة والسلام، فلهذا قالوا: (نحن أنصار الله)، يعني: نحن الأنصار الذين دعوتهم إلى أن نكون معك في نصر دين الله، فهو قال: (من أنصاري إلى الله، قالوا: نحن أنصار الله) يعني: نحن الأنصار الذين ينصرون دين الله، وينصرون الدعاة إليه ومنهم عيسى عليه الصلاة والسلام، فهم أتوا بعبارة أكمل وأعظم وأشرف في حقهم حيث قالوا: نحن أنصار الله؛ لأن أنصار الرسل هم أنصار الله، من نصر الرسول فقد نصر الله، ومن نصر الحق فقد نصر الله، فهم اختاروا هذه الكلمة التي هي مقصود عيسى عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17285/ما-معنى-يا-ايها-الذين-امنوا-كونوا-انصار-الله","audio":"","categories":["التفسير"]},{"id":18228,"question":"أخٌ لنا من الدمام يقول (م. أ. ح. ج)، أخونا له سؤالان عن شرح آياتٍ من القرآن الكريم، في سؤاله الأول يقول: أرجو أن تتفضلوا بشرح الآيات التالية بعد: أعوذ بالله من الشيطان الرجيم: فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَه ۝ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَه [الزلزلة:7، 8].","title":"تفسير قوله تعالى: {فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ ...} [الزلزلة:7]","answer":"الجواب: هاتان الآيتان الكريمتان على ظاهرهما، وسمَّاها النبي ﷺ الآية الفاذة الجامعة، يعني: أنها جمعت الخير والشر، ففيها الترغيب والترهيب، والحث على الخير، والتحذير من الشر، وأن العبد لا يضيع عليه شيءٌ من عمله الصالح، وأن سيئاته سوف يلقاها ويراها إلا أن يتوب الله عليه ويعفو عنه؛ ولهذا قال سبحانه: فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَه [الزلزلة:7]. وهذا يدل على أنه لا يضيع لك شيءٌ من أعمالك الصالحة، بل تُحصى لك، وتُكتب لك، وتوفاها يوم القيامة، كما قال  في الآية الأخرى: إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا [النساء:40]، فهو لا يظلم أحدًا مثقال ذرَّةٍ، بل هو  الحكم العدل، يُعطي كل عاملٍ بعمله: وَلَا يَظْلِمُ رَبُّكَ أَحَدًا [الكهف:49] ، وإن كانت الزِّنَة لخيرٍ ضُوعِف: وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا [النساء:40] يعني: وإن تكن الفعلة التي فعلها الإنسان حسنةً ضاعفها الله له: وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا  [النساء:40]. فأنت -يا أخي- عليك أن تحذر السيئات: دقيقها وجليلها، صغيرها وكبيرها، وألا تحتقر شيئًا منها، فإن معظم النار يكون من مُستصغر الشَّرر، فلا تحقر سيئةً أبدًا، وقد جاء عن النبي ﷺ أنه قال: إياكم ومُحقِّرات الذنوب، فإنها تجتمع على العبد حتى تُهلكه، وفي لفظٍ ثانٍ: إن لها من الله طالبًا. فعلى كل مؤمنٍ، وعلى كل مؤمنةٍ الحذر من جميع السيئات، كما أنه ينبغي لكل مؤمنٍ ولكل مؤمنةٍ الاستكثار من الحسنات، والحرص على فعل الخير وإن كان قليلًا؛ ولهذا قال عليه الصلاة والسلام في الحديث الصحيح: اتَّقوا النار ولو بشق تمرةٍ، فمَن لم يجد فبكلمةٍ طيبةٍ. وصحَّ عن عائشة رضي الله عنها أنها قالت: جاءت امرأةٌ ومعها ابنتان تشحذ -تسأل-، فأعطيتها ثلاث تمراتٍ، فأعطت كل واحدةٍ من بنتيها تمرةً، ورفعت الثالثة لتأكلها، فنظرت إليها ابنتاها تستطعمانها الثالثة، فشقتها بينهما، ولم تأكل شيئًا، فأعجبني أمرها، فلما جاء النبي ﷺ أخبرته بشأنها، فقال: إن الله أوجب لها بذلك الجنة. هذا شق تمرةٍ، ورحمةٌ من والدةٍ لابنتيها حصل لها بذلك الوعد بالجنة على هذه الرحمة، وهذا الإحسان، وهذه الشفقة بشيءٍ قليلٍ. فينبغي للمؤمن ألا يحقر شيئًا من الحسنات، فإذا وجد شيئًا يجود به على الفقير والمحتاج فلا يحقره: تمرة، درهم، نصف درهم، أقل، أكثر، فالمحتاج ينفعه كل شيءٍ، وتجتمع عنده التمرات والأشياء القليلة من النقود وتنفعه. فهذا معنى الآية الكريمة: الحث على تحصيل الخيرات ولو قليلة، ولو دقيقة، والحذر من الشرور وإن كانت قليلةً؛ فإنها تجتمع حتى تهلك العبد، كما أن الخير -وإن قلَّ- يجتمع حتى ينفع العبد في آخرته، وفي دنياه، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/17271/تفسير-قوله-تعالى-فمن-يعمل-مثقال-ذرة-الزلزلة7","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_857/nour_85702.mp3","categories":["التفسير"]},{"id":18230,"question":"أخٌ لنا من الدمام يقول (م. أ. ح. ج)، أخونا له سؤالان عن شرح آياتٍ من القرآن الكريم، في سؤاله الأول يقول: أرجو أن تتفضلوا بشرح الآيات التالية بعد: أعوذ بالله من الشيطان الرجيم: فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَه ۝ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَه [الزلزلة:7، 8].","title":"تفسير قوله تعالى: {فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ ...} [الزلزلة:7]","answer":"الجواب: هاتان الآيتان الكريمتان على ظاهرهما، وسمَّاها النبي ﷺ الآية الفاذة الجامعة، يعني: أنها جمعت الخير والشر، ففيها الترغيب والترهيب، والحث على الخير، والتحذير من الشر، وأن العبد لا يضيع عليه شيءٌ من عمله الصالح، وأن سيئاته سوف يلقاها ويراها إلا أن يتوب الله عليه ويعفو عنه؛ ولهذا قال سبحانه: فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَه [الزلزلة:7]. وهذا يدل على أنه لا يضيع لك شيءٌ من أعمالك الصالحة، بل تُحصى لك، وتُكتب لك، وتوفاها يوم القيامة، كما قال  في الآية الأخرى: إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا [النساء:40]، فهو لا يظلم أحدًا مثقال ذرَّةٍ، بل هو  الحكم العدل، يُعطي كل عاملٍ بعمله: وَلَا يَظْلِمُ رَبُّكَ أَحَدًا [الكهف:49] ، وإن كانت الزِّنَة لخيرٍ ضُوعِف: وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا [النساء:40] يعني: وإن تكن الفعلة التي فعلها الإنسان حسنةً ضاعفها الله له: وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا  [النساء:40]. فأنت -يا أخي- عليك أن تحذر السيئات: دقيقها وجليلها، صغيرها وكبيرها، وألا تحتقر شيئًا منها، فإن معظم النار يكون من مُستصغر الشَّرر، فلا تحقر سيئةً أبدًا، وقد جاء عن النبي ﷺ أنه قال: إياكم ومُحقِّرات الذنوب، فإنها تجتمع على العبد حتى تُهلكه، وفي لفظٍ ثانٍ: إن لها من الله طالبًا. فعلى كل مؤمنٍ، وعلى كل مؤمنةٍ الحذر من جميع السيئات، كما أنه ينبغي لكل مؤمنٍ ولكل مؤمنةٍ الاستكثار من الحسنات، والحرص على فعل الخير وإن كان قليلًا؛ ولهذا قال عليه الصلاة والسلام في الحديث الصحيح: اتَّقوا النار ولو بشق تمرةٍ، فمَن لم يجد فبكلمةٍ طيبةٍ. وصحَّ عن عائشة رضي الله عنها أنها قالت: جاءت امرأةٌ ومعها ابنتان تشحذ -تسأل-، فأعطيتها ثلاث تمراتٍ، فأعطت كل واحدةٍ من بنتيها تمرةً، ورفعت الثالثة لتأكلها، فنظرت إليها ابنتاها تستطعمانها الثالثة، فشقتها بينهما، ولم تأكل شيئًا، فأعجبني أمرها، فلما جاء النبي ﷺ أخبرته بشأنها، فقال: إن الله أوجب لها بذلك الجنة. هذا شق تمرةٍ، ورحمةٌ من والدةٍ لابنتيها حصل لها بذلك الوعد بالجنة على هذه الرحمة، وهذا الإحسان، وهذه الشفقة بشيءٍ قليلٍ. فينبغي للمؤمن ألا يحقر شيئًا من الحسنات، فإذا وجد شيئًا يجود به على الفقير والمحتاج فلا يحقره: تمرة، درهم، نصف درهم، أقل، أكثر، فالمحتاج ينفعه كل شيءٍ، وتجتمع عنده التمرات والأشياء القليلة من النقود وتنفعه. فهذا معنى الآية الكريمة: الحث على تحصيل الخيرات ولو قليلة، ولو دقيقة، والحذر من الشرور وإن كانت قليلةً؛ فإنها تجتمع حتى تهلك العبد، كما أن الخير -وإن قلَّ- يجتمع حتى ينفع العبد في آخرته، وفي دنياه، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/17271/تفسير-قوله-تعالى-فمن-يعمل-مثقال-ذرة-الزلزلة7","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_857/nour_85702.mp3","categories":["التفسير"]},{"id":18255,"question":"يقول هذا السائل: ما معنى الورود في قوله تعالى: وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا[مريم:71]؟","title":"معنى الورود في قوله تعالى: {وإن منكم إلا واردها}","answer":"الجواب: هذا بيَّنه النبي ﷺ وأن الورود المراد بذلك المرور على الصراط، فالمسلم يمر على الصراط وينجو، وقد يقع بعض أهل المعاصي، وأما الكفار فإنهم يساقون إليها، ويردونها، ويحشرون إليها، والعياذ بالله. فلا بد من المرور، فالمؤمن يمر وينجو، والكافر يساق إليها ويدخلها، وبعض العصاة قد يخدش على الصراط وينجو، وقد يسقط بسبب معاصيه ثم لا يخلد، العاصي لا يخلد في النار إذا مات على الزنا أو اللواط أو الربا، أو عقوق الوالدين، أو غير هذا من المعاصي ولم يتب فهو تحت مشيئة الله، إن شاء الله غفر له، وأدخله الجنة بتوحيده، وإيمانه، وحسناته، وإن شاء أدخله النار بمعاصيه، فإذا طهر فيها ومحص أخرج منها إلى الجنة، كما قال الله سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ[النساء:48] . فأخبر سبحانه أن الشرك لا يغفر لمن مات عليه، أما ما دون الشرك فقد يغفر وقد يعفى عنه لتوبة، والتائب يتوب الله عليه، وقد يعفى عنه لحسنات كثيرة، وأعمال صالحة قدمها، أو بشفاعة بعض الشفعاء، كما تواترت الأخبار عن رسول الله ﷺ أنه يشفع في جماعة من العصاة فيخرجهم الله من النار، وهكذا يشفع غيره. والمقصود أن العاصي تحت مشيئة الله، إذا مات على الإسلام لكن عنده معاصي لم يتب منها، فهو تحت مشيئة الله  إن شاء غفر الله له وأدخله الجنة، وإن شاء عذبه على قدر معاصيه، ثم يخرجه الله من النار، بشفاعة بعض الشفعاء، أو بمجرد رحمته سبحانه وجوده جل وعلا. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17304/معنى-الورود-في-قوله-تعالى-وان-منكم-الا-واردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78311.mp3","categories":["التفسير"]},{"id":18294,"question":"قال الله تعالى: إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ بِهِ لِغَيْرِ اللَّهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلا عَادٍ فَلا إِثْمَ عَلَيْهِ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ [البقرة:173]، اشرحوا لي هذه الآية الكريمة، ولاسيما كلمة (الدم) هل كان الناس يأكلون الدم قبل نزول هذه الآية؟","title":"تفسير قوله تعالى: {إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ...}","answer":"الجواب: نعم، كانت العرب تأكل الدم وتشرب الدم، وإذا احتاجوا فصدوا الإبل وشربوا الدماء، فالله نهاهم عن هذا، إذا كان مسفوحًا، وهو الذي يصب من العروق وغير العروق، أما الدم الجامد كالكبد، فهذا لا بأس إذا أكل الإنسان الكبد، لأنها ليست دمًا مسفوحًا فلا حرج في ذلك، وكانت الجاهلية يأكلون الدم، يفصدون الحيوانات ويشربون من دمائها، فحرم الله عليهم ذلك، وبين سبحانه في الآية الأخرى أَوْ دَمًا مَسْفُوحًا[الأنعام:145]، يعني: مراقًا، فهذا هو وجه تحريم الدم، هو المراق؛ لأنه من سنة الجاهلية؛ ولأن في ذلك ضررًا على شاربه. والميتة معروفة، ولحم الخنزير معروف، وما أهل به لغير الله: هو الذي يذبح لغير الله كالذبيحة تذبح للجن أو للأصنام أو للكواكب، هذه الذبيحة محرمة؛ لأنها ذبحت لغير الله، فمن اضطر إلى الميتة أو غيرها فله الأكل من ذلك، غير باغ ولا عاد غير ظالم ولا باغ على إخوانه المسلمين، فالباغي والعادي فسر بأنواع منها: البغاة يخرجون على السلطان، فهم الظالمون بذلك، ومنها المتعدي الذي يتعدى بأكله من الميتة بغير ضرورة ولا حاجة، فلا يسمى مضطرًا. وبعض أهل العلم ذكر في ذلك أمرًا آخر وهو أن يسافر سفرًا يعتبر معصية، ويعتبر متعديًا أيضًا، فليس له رخصة، ولكن الأقرب -والله أعلم- أنه مقيد بأن يكون أكله غير باغ ولا عاد، إنما ضرورة، أكل للضرورة .... لا يجد شيئًا، أما إذا تعدى بأن أكل من غير ضرورة، أو تعاطى من الميتة بغير ضرورة، فيسمى باغ ويسمى عاديًا متعد لحدود الله ، أما إذا اضطر إلى ذلك بسبب سفر معصية، أو شبه ذلك مما قد يوقعه في الحاجة والضرورة إلى الميتة، فهو داخل في الآية الكريمة؛ لأن الآية مجملة غَيْرَ بَاغٍ وَلا عَادٍ. فالباغي: هو الذي يتعدى الحدود، ويبغي على الناس، والعادي: الذي كذلك يتعدى على الناس إما بكونه يأكل بغير ضرورة، أو يبغي على الناس ويتعدى عليهم بدون حق بدون سبب شرعي، هذا هو الذي يمتنع عليه هذه الأشياء، وإنما يكون مضطرًا إذا كان لا يجد شيئًا، حتى يخاف على نفسه فيأكل من الميتة أو من الخنزير، أو ما أهل به لغير الله أو من الدم للضرورة التي وقع فيها. نعم، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17345/تفسير-قوله-تعالى-انما-حرم-عليكم-الميتة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91209.mp3","categories":["التفسير"]},{"id":18430,"question":"الرسالة التالية وصلت إلى البرنامج من العراق نينوى وباعثها أخ لنا من هناك يقول: (خ. ي. أ) أخونا له مجموعة من الأسئلة يسأل في سؤاله الأول عن تفسير قول الحق تبارك وتعالى -وأرجو أن يكون قد كتب الآية صحيحة -: وَإِنْ مِنْ قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ الْقِيَامَةِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا كَانَ ذَلِكَ فِي الْكِتَابِ مَسْطُورًا [الإسراء:58] ، يسأل عن تفسير هذه الآية يا شيخ عبد العزيز .","title":"تفسير قوله تعالى: {وإن من قرية إلا نحن مهلكوها...}","answer":"الجواب: على ظاهرها: (إن) معناها النافية، يعني: ما من قرية إلا نحن مهلكوها قبل يوم القيامة أو معذبوها عذابًا شديدًا، أي: ما من قرية إلا ويصيبها شيء كما قال جل وعلا قبل يوم القيامة، أو معذبوها عذابًا شديدًا وهذا معناه أن هذه القرى كلها تذهب، كلها تنتهي، ولا يبقى شيء، فإن القيامة إذا قامت ذهب كل شيء، يقول جل وعلا: وَيَسْأَلُونَكَ عَنِ الْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّي نَسْفًا  ۝  فَيَذَرُهَا قَاعًا صَفْصَفًا ۝ لا تَرَى فِيهَا عِوَجًا وَلا أَمْتًا [طه:105-107] ، حتى الجبال تذهب، حتى الجبال هذه الرواسي العظيمة، فهذه القرى تذهب ولا يبقى على الأرض شيء بالكلية عند قيام الساعة. فأما يعني يقال قبل يوم القيامة، فقد تذهب بعون الله عند قيام الساعة بدكها وذهابها، وقد تذهب بعقوبة عاجلة بسبب معاصي أهلها وكفرهم وضلالهم كما جرى لقوم لوط، خسف الله بهم مدائنهم حتى هلكوا عن آخرهم، فالمقصود أنه يقول جل وعلا : وَإِنْ مِنْ قَرْيَةٍ يعني: ما من قرية إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ الْقِيَامَةِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا. هذه القرى والمدن لابد أن تذهب قبل يوم القيامة، إما بعقوبة عاجلة وإما بمجيء القيامة، فإذا جاءت القيامة اندك كل شيء، وهذه الحصون العظيمة والقرى العظيمة والبيوت كلها تذهب حتى الجبال تسير. نعم. الله المستعان.","link":"https://binbaz.org.sa/fatwas/17510/تفسير-قوله-تعالى-وان-من-قرية-الا-نحن-مهلكوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91405.mp3","categories":["التفسير"]},{"id":18448,"question":"ما سبب تكرار آية: فَبِأَيِّ آلاءِ رَبِّكُمَا تُكَذِّبَانِ [الرحمن:13]؟","title":"سبب تكرار قوله تعالى: {فبأي آلا ربكما تكذبان}","answer":"الجواب: السبب والله أعلم: التنبيه على عظم الآيات، وأنها كلها جديرة بأن تشكر؛ لأن المحسن بها هو الله  فينبغي للمؤمن أن يشكرها دائمًا، وأن يصدق بما دلت عليه من حق الله وتوحيده وأنه رب العالمين، وأنه الخلاق العليم، وأنه المستحق لأن يُعبد ويطاع، فهي نعم امتن الله بها وأحسن بها إلى عباده، فلا ينبغي للمؤمن من الجن والإنس أن يكذب شيء من ذلك بل الواجب أن يشكر هذه النعم، يعني: أن يشكر الله عليها سبحانه وأن يستعين بها على طاعته سبحانه، وأن يستفيد منها في سلامة إيمانه وقوة إيمانه وفي خوفه من الله وتعظيمه لله وحقه  الله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/17538/سبب-تكرار-قوله-تعالى-فباي-الا-ربكما-تكذبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86504.mp3","categories":["التفسير"]},{"id":18485,"question":"يستفسر في الفقرة الأخيرة عن آية في سورة يوسف، في قوله تعالى: وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلا أَنْ رَأَى بُرْهَانَ رَبِّهِ كَذَلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ[يوسف:24]؟","title":"تفسير قوله تعالى: {ولقد همت به وهم بها...}","answer":"الجواب: على ظاهرها، لما اشتدت المراودة منها همَّ بها، وهمَّت به، لكن الله عصمه، وحفظه عليه الصلاة والسلام، ورأى برهانًا منعه من ذلك، فهذا من فضل الله عليه. أما قول بعض الناس: إنه همَّ بضربها، هذا ما له أصل ليس بشيء، همَّ بها همًّا يعني: بالفاحشة؛ إلا أن الله حفظه وصانه؛ لأنه من عباد الله المخلصين، وسلم من شرها، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17582/تفسير-قوله-تعالى-ولقد-همت-به-وهم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78523.mp3","categories":["التفسير"]},{"id":18499,"question":"سماحة الشيخ! يقول: في الآية الكريمة نقرأ الآية: إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُوْلَئِكَ كَانَ عَنْهُ مَسْئُولًا[الإسراء:36] يريد تفسيرًا للآية يا شيخ.","title":"تفسير قوله تعالى: {إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ ...}","answer":"الجواب: على ظاهرها، الإنسان مسئول عن سمعه، وعن بصره، وعن فؤاده، عن قلبه وعقله، هل استعمله في طاعة الله، أو في محارم الله، الأمر عظيم، السمع يسمع الشر، والخير، والبصر كذلك، والقلب كذلك يعقل الشر والخير، فالواجب على كل مكلف أن يصون سمعه عما حرم الله، وأن يصون بصره عما حرم الله، وأن يعمر قلبه بتقوى الله، ويحذر محارم الله، فيخاف الله ويحبه، ويخشاه جل وعلا ويخلص له في العمل، ويحذر خلاف ذلك من النفاق والكبر وغير هذا من أعمال القلوب السيئة، والعقل يسمى فؤادًا، والقلب يسمى فؤادًا. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17591/تفسير-قوله-تعالى-ان-السمع-والبصر-والفواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78602.mp3","categories":["التفسير"]},{"id":18500,"question":"في الآية الكريمة يقول: قُلْ هُوَ الَّذِي أَنشَأَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالأَبْصَارَ وَالأَفْئِدَةَ..[الملك:23] الآية ما هو الفؤاد في هذه الآية؟","title":"معنى الفؤاد","answer":"الجواب: الفؤاد مثل ما تقدم، هو القلب وهو العقل؛ لأن القلب يعقل به قال تعالى: أَفَلَمْ يَسِيرُوا فِي الأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَا[الحج:46] ويسمى فؤاد، فالقلب يسمى الفؤاد، وهو محل العقل أيضًا، وهو مسؤول، مسؤول عن ما عمل من خير وشر، فخوف الله، ومحبة الله وخشيته، والإخلاص له؛ هذه عمل طيب، والنفاق، والرياء، والكبر، وأشباه ذلك من أعمال القلوب السيئة، نسأل الله العافية. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17592/معنى-الفواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78603.mp3","categories":["التفسير"]},{"id":18538,"question":"يسأل سماحتكم تفسير قول الحق -تبارك وتعالى-: أعوذ بالله من الشيطان الرجيم: وَكُنْتُمْ عَلَى شَفَا حُفْرَةٍ مِنَ النَّارِ فَأَنْقَذَكُمْ مِنْهَا [آل عمران:103].","title":"تفسير قوله تعالى: {وَكُنْتُمْ عَلَى شَفَا حُفْرَةٍ...}","answer":"الجواب: كل من كان على الكفر بالله، ثم تاب فهو على شفا حفرة من النار، فإذا كان كافرًا بأي نوع من أنواع الكفر بعبادة الأوثان والأصنام، وعبادة الأولياء والأنبياء بسب الدين بأي ذنب من الذنوب، فهو على حفرة من النار، على شفا حفرة من النار، متى مات صار إليها، نسأل الله العافية.  لكن إذا منّ الله عليه بالتوبة، فقد أنقذه الله، وكان الصحابة الذين هداهم الله للإسلام على هذه الصفة، على شفا حفرة من النار لكفرهم، فلما هداهم الله للإسلام، وتابعوا النبي ﷺ أنقذهم الله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17639/تفسير-قوله-تعالى-وكنتم-على-شفا-حفرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73311.mp3","categories":["التفسير"]},{"id":18664,"question":"يستفسر عن الآية الكريمة في قوله تعالى: ليس عَلَى الأَعْرَجِ حَرَجٌ[النور:61] فما معنى هذه الآية؟","title":"تفسير قوله تعالى: {ليس على الأعمى حرج...}","answer":"الجواب: يعني: في الجهاد لَيْسَ عَلَى الأَعْمَى حَرَجٌ وَلا عَلَى الأَعْرَجِ حَرَجٌ وَلا عَلَى الْمَرِيضِ حَرَجٌ[النور:61] كل هؤلاء ليس عليهم حرج، ليس عليهم جهاد، الأعرج والأعمى والمريض؛ لأنهم ما يستطيعون الجهاد، الأعرج يضعف عن اللحاق بالعدو، والهروب من العدو إذا دعت الحاجة إلى ذلك، والمريض كذلك، والأعمى كذلك، فليس عليهم حرج في الجهاد، ليس عليهم جهاد يعني، نعم. المقدم: أحسن الله إليكم سماحة الشيخ","link":"https://binbaz.org.sa/fatwas/17783/تفسير-قوله-تعالى-ليس-على-الاعمى-حرج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78803.mp3","categories":["التفسير"]},{"id":18711,"question":"من الإمارات العربية المتحدة رسالة بعثت بها الأخت (ص.ع) تسأل تفسير قول الحق -تبارك وتعالى- أعوذ بالله من الشيطان الرجيم : لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [البقرة:284].","title":"ما معنى: {وَإِنْ تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ}؟","answer":"الجواب: هذه الآية لما نزلت شقت على أصحاب النبي ﷺ فجاؤوا إلى النبي ﷺ وسألوه، فأنزل الله بعدها: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]. فما يقع في الصدور من الوساوس، ولا ينطق به اللسان، ولا يعمل به، بل يعرض ويزول؛ لا يؤاخذ به الإنسان، يعفى عنه، وإنما تكون المؤاخذة بالعمل أو القول؛ لقول النبي ﷺ: إن الله تجاوز عن أمتي ما حدثت به أنفسها، ما لم تعمل أو تكلم فالوساوس التي تعرض وتزول لا تضر الإنسان، إلا إذا قال أو عمل عملًا واعتقده بقلبه أو بجوارحه: كالتكبر بالقلب، التكبر والرياء بالقلب؛ فهذا يؤاخذ به؛ لأنه عمل. وهكذا قول تكلم بلسانه أو بجوارحه، أما الوساوس التي تعرض على الإنسان، ولكن لا تستقر تذهب وليست بمستقرة، هذه يعفى عنها؛ لقوله ﷺ: إن الله تجاوز عن أمتي ما حدثت به أنفسها، ما لم تعمل أو تكلم ولعموم قوله -جل وعلا-: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] إذ الوساوس لا يطيق العبد السلامة منها، ولكن يحذر أن يعمل بالوسوسة الرديئة، عليه الحذر من العمل بالوساوس الرديئة، بل يحذرها ويتركها، ويعرض عنها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17819/ما-معنى-وان-تبدوا-ما-في-انفسكم-او-تخفوه-يحاسبكم-به-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73517.mp3","categories":["التفسير"]},{"id":18737,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين بدأها بقوله: نحمد الله  على أن من علينا ببرنامج (نور على الدرب) ونشكر علماءنا الأفاضل، وندعو لهم بالتوفيق والسداد في تبصير الأمة المسلمة بأمور دينها ودنياها، نرجو أن يجيب على هذه الأسئلة سماحة الشيخ عبد العزيز بن باز، مقدم الأسئلة: أبو مؤمن خلف الله علي مصري يعمل باليمن.أخونا يسأل في سؤاله الأول ويقول: سألني أخ مسلم: أين الله؟ فقلت له: في السماء، فقال لي: فما رأيك في قوله تعالى: وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ [البقرة:255] وذكر آيات كثيرة، ثم قال: لو زعمنا أن الله في السماء؛ لحددنا جهة معينة، فما رأي سماحتكم في ذلك؟ وهل هذه الأسئلة من الأمور التي نهينا عن السؤال عنها؟","title":"الدليل على علو الله فوق العرش","answer":"الجواب: قد أصبت في جوابك، وهذا الجواب الذي أجبت به هو الجواب الذي أجاب به النبي -عليه الصلاة والسلام-، فالله -جل وعلا- في السماء، في العلو  كما قال : أَأَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الأَرْضَ فَإِذَا هِيَ تَمُورُ ۝ أَمْ أَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ [الملك:16-17] وقال -جل وعلا-: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] وقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54]. فهو  فوق العرش في جهة العلو، فوق جميع الخلق، عند جميع أهل العلم من أهل السنة، قد أجمع أهل السنة والجماعة -رحمة الله عليهم- على أن الله في السماء فوق العرش فوق جميع الخلق ، وهذا هو المنقول عن رسول الله ﷺ وعن أصحابه  وعن أتباعهم بإحسان، كما أنه موجود في كتاب الله القرآن. وقد سأل النبي ﷺ جارية جاء بها سيدها ليعتقها، فقال لها الرسول ﷺ: أين الله؟ قالت: في السماء، قال: من أنا؟ قالت: أنت رسول الله، قال: أعتقها، فإنها مؤمنة رواه مسلم في الصحيح، فالرسول ﷺ أقر هذه الجارية على الجواب، الذي قلته أنت، قال لها: أين الله؟ قالت: في السماء، قال: من أنا؟ قالت: أنت رسول الله، قال: أعتقها، فإنها مؤمنة وما ذاك إلا لأن إيمانها بأن الله في السماء يدل على إخلاصها لله، وتوحيدها لله، وأنها مؤمنة به سبحانه، وبعلوه فوق جميع خلقه، وبرسوله محمد -عليه الصلاة والسلام- حيث قالت: أنت رسول الله. \nأما قوله -جل وعلا-: وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ [البقرة:255] هذا لا ينافي ذلك، الكرسي فوق السماوات، والعرش فوق الكرسي، والله فوق العرش، فوق جميع الخلق  وتحديد الجهة لا مانع منه جهة العلو، بأن الله في العلو. وإنما يشبه بهذا بعض المتكلمين وبعض المبتدعة، ويقولون: ليس في جهة، وهذا كلام فيه تفصيل، فإن أرادوا: ليس في جهة مخلوقة، وأنه ليس في داخل السماوات، وليس في داخل الأرض، ونحو هذا صحيح، أما إن أرادوا أنه ليس في العلو، هذا باطل، وهذا خلاف ما دل عليه كتاب الله، وما دلت عليه سنة رسول الله -عليه الصلاة والسلام-، وما دل عليه إجماع سلف الأمة. فقد أجمع علماء الإسلام أن الله في السماء فوق العرش، فوق جميع الخلق، والجهة التي هو فيها جهة العلو، وهي ما فوق جميع الخلق، وهذه الأسئلة ليست بدعة، ولم ننه عنها، بل هذه الأسئلة مأمور بها نعلمها الناس، كما سأل عنها النبي ﷺ قال: أين الله وسأله أبو رزين قال: أين ربنا؟ فأخبره أنه في العلو ، فالله  في العلو في جهة العلو فوق السماوات، فوق العرش، فوق جميع الخلق، وليس في الأرض، ولا في داخل الأرض، ولا في داخل السماوات.    ومن قال: إن الله في الأرض، وأن الله في كل مكان كـالجهمية والمعتزلة ونحوهم فهو كافر عند أهل السنة والجماعة؛ لأنه مكذب لله ولرسوله في إخبارهما بأنه سبحانه في السماء فوق العرش -جل وعلا-، فلا بد من الإيمان بأن الله فوق العرش، فوق جميع الخلق، وأنه في السماء، يعني: في العلو، معنى السماء يعني: العلو، فالسماء يطلق على معنيين: أحدهما: السماوات المبنية، يقال لها: سماء.\nوالثاني: العلو، يقال له: سماء، فالله سبحانه في العلو، في جهة العلو فوق جميع الخلق، وإذا أريد: السماء المبينة المعنى هو: عليها، في يعني: على، في السماء يعني: على السماء وفوقها، كما قال الله سبحانه: فَسِيرُوا فِي الأَرْضِ [آل عمران:137] سيروا في الأرض يعني: عليها فوقها، وكما قال الله  عن فرعون أنه قال: لَأُصَلِّبَنَّكُمْ فِي جُذُوعِ النَّخْلِ [طه:71] يعني: على جذوع النخل، فلا منافاة بين قول من قال: في السماء يعني: على السماء، وبين من قال: إنه في العلو؛ لأن السماء المراد به العلو، فالله في العلو، فوق السماوات فوق جميع الخلق، وفوق العرش . ومن قال: معنى في: على، يعني: أنه فوق السماوات المبنية فوقها، ولا شك أنه فوقها، فوق العرش، فوق جميع الخلق ، فأنت على عقيدة صالحة، وأبشر بالخير، والحمد لله الذي هداك لذلك، ولا تلتفت إلى أقوال المشبهين والملبسين؛ فإنهم في ضلال. وأنت بحمد الله ومن معك على هذه العقيدة أنتم على الحق في إيمانكم بأن الله في السماء، فوق العرش، فوق جميع الخلق ، وعلمه في كل مكان -جل وعلا-، ولا يشابه الخلق في شيء من صفاته ، وليس في حاجة إلى العرش، ولا إلى السماء، بل هو غني عن كل شيء ، والسماوات مفتقرة إليه، والعرش مفتقر أيضًا، وهو الذي أقام العرش، وهو الذي أقام الكرسي، وهو الذي أقام السماوات، وهو الذي أمسكها ، كما قال : وَمِنْ آيَاتِهِ أَنْ تَقُومَ السَّمَاءُ وَالأَرْضُ بِأَمْرِهِ [الروم:25] قال سبحانه: إِنَّ اللَّهَ يُمْسِكُ السَّمَوَاتِ وَالأَرْضَ أَنْ تَزُولا [فاطر:41] فالله الذي أمسك السماوات، وأمسك العرش، وأمسك هذه المخلوقات، فلولا إمساكه لها، وإقامته لها؛ لاندك بعضها على بعض، ولكنه -جل وعلا- هو الذي أقامها وأمسكها حتى يأتي أمر القيامة، فإذا جاء يوم القيامة صار لها حال أخرى. فهو سبحانه على كل شيء قدير، وبكل شيء عليم، وهو العالي فوق جميع خلقه، وصفاته كلها علا، وأسماؤه كلها حسنى، فالواجب على أهل العلم والإيمان أن يصفوا الله سبحانه بما وصف به نفسه، وبما وصفه به رسوله -عليه الصلاة والسلام-، من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، بل مع الإيمان بأنه سبحانه لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17882/الدليل-على-علو-الله-فوق-العرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87509.mp3","categories":["التفسير","الأسماء والصفات","فتاوى متنوعة"]},{"id":18762,"question":"في ثاني أسئلة هذا السائل من تونس يقول: في الآية الكريمة وفي سورة الرحمن قال الله تعالى: وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالإِكْرَامِ [الرحمن:27] وفي آية أخرى: تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلالِ وَالإِكْرَامِ[الرحمن:78] الأولى بالرفع والثانية بالكسر، فأفيدونا عن الآيتين.","title":"توجيه الرفع والجر في قوله تعالى: {ذو الجلال} و{ذي الجلال}","answer":"الجواب: الأولى وصف للوجه: وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالإِكْرَامِ [الرحمن:27] وصف لوجهه بأنه: ذو الجلال، وهو الرب سبحانه؛ لأن تعبير الوجه معناه للكل، وجهه ذو الجلال وهو ذو الجلال . والثانية الأخيرة: آية الرحمن وصف للرب: تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلالِ وَالإِكْرَامِ [الرحمن:78] يعني: هو نعت للرب وصف للرب بأنه هو ذو الجلال، ووجهه ذو الجلال  وجهه عظيم، وذاته عظيمة  هو ذو الجلال من جهة وجهه، وذو الجلال من جهة ذاته . المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/17894/توجيه-الرفع-والجر-في-قوله-تعالى-ذو-الجلال-وذي-الجلال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79020.mp3","categories":["التفسير"]},{"id":18788,"question":"يقول الله : وَالْحَافِظِينَ فُرُوجَهُمْ وَالْحَافِظَاتِ [الأحزاب: 35] هل تذكر كلمة الفرج في كتاب ربنا، ويقصد بها عضو التناسل في كل من الذكر والأنثى، نرجو الإفادة مع شرح الآية؟جزاكم الله خيرًا.","title":"تفسير قوله تعالى: {والحافظين فروجهم والحافظات}","answer":"الجواب: نعم، المراد بذلك حفظ الفرج الذي هو فرج المرأة، وفرج الرجل، يعني: حفظ فرجها عن غير زوجها وسيدها، وحفظ فرجه عن غير زوجته وأمته، والمعنى: أن المؤمن والمؤمنة قد حفظا فروجهما عن الزنا، واللواط، والله سبحانه يقول: إنّ الْمُسْلمين والْمُسْلمات والْمُؤْمنين والْمُؤْمنات والْقانتين والْقانتات والصّادقين والصّادقات والصّابرين والصّابرات والْخاشعين والْخاشعات والْمُتصدّقين والْمُتصدّقات والصّائمين والصّائمات والْحافظين فُرُوجهُمْ والْحافظات والذّاكرين اللّه كثيرًا والذّاكرات أعدّ اللّهُ لهُمْ مغْفرةً وأجْرًا عظيمًا [الأحزاب:35]. فهذه آية عظيمة ذكر سبحانه لهؤلاء الأصناف العشرة أنه أعد لهم مغفرة وأجرًا عظيمًا، بسبب أعمالهم الطيبة من إسلامهم، وإيمانهم، وقنوتهم، وصدقاتهم، وخشوعهم، وصيامهم، وحفظ فروجهم، وذكرهم الله ، وصبرهم، إلى غير ذلك مما هو معروف من خصال أهل الإيمان. فالحاصل: من قوله: وَالْحَافِظِينَ فُرُوجَهُمْ وَالْحَافِظَاتِ [الأحزاب: 35] يعني: الحافظين فروجهم عن الزنا واللواط، والحافظات فروجهن عن الزنا ونحوه كاللواط، وهو: الوطء في الدبر؛ لأنه ليس للزوج أن يطأ زوجته إلا في قبلها، وليس له أن يطأها في دبرها، هذه يقال لها: اللواطة الصغرى، فليس لها أن يطأها إلا في محل الحرث، وهو الفرج، وهو القبل، وليس له أن يطأ أمته -وهي: السرية- إلا في فرجها، وهو القبل، ليس له أن يطأها في دبرها. والسرية هي التي يملكها بالسبي من الكفار، أو بالشراء، أو بالإرث الشرعي، وهكذا المرأة مباحة لسيدها الذي ملكها بالسبي الشرعي أو بالشراء الشرعي، أو بالإرث الشرعي، كما أنها مباحة لزوجها، ولكن بقيد ما ذكره الله، وهو الفرج، فليس لأحدهما تعدي حدود الله ؛ ولهذا قال  في كتابه الكريم في سورة المؤمنون: قدْ أفْلح الْمُؤْمنُون ۝ الّذين هُمْ في صلاتهمْ خاشعُون ۝ والّذين هُمْ عن اللّغْو مُعْرضُون ۝ والّذين هُمْ للزّكاة فاعلُون ۝ والّذين هُمْ لفُرُوجهمْ حافظُون ۝ إلّا على أزْواجهمْ أوْ ما ملكتْ أيْمانُهُمْ فإنّهُمْ غيْرُ ملُومين ۝ فمن ابْتغى وراء ذلك فأُوْلئك هُمُ الْعادُون [المؤمنون:1-7] فمن ابتغى وراء ما أباح الله فهو العادي، يعني: الظالم المعتدي لحدود الله. فالواجب على كل مؤمن أن يلزم حد الله سبحانه، وأن يحرص على العفة عما حرم الله، فيطأ زوجته فيما أباح الله، في الفرج، في القبل، ولا يطأها في الدبر، ولا في الحيض، ولا في النفاس، ولا في حال إحرامها، يطأها في وقت الإباحة، وهكذا سريته التي هي أمته مملوكته، بالملك الشرعي. والمرأة كذلك عليها أن تحفظ فرجها، إلا من زوجها وسيدها الشرعي، وعليها أن تحذر ما حرم الله من الزنا، وما يلحق بالزنا من الوطء في الدبر، من زوجها أو غير زوجها، كل ذلك حرام، من زوجها ومن غير زوجها، كما أن الزنا حرام، فهكذا الوطء في الدبر حرام، ولو من زوجها، ليس له أن يطأها في دبرها، ولا سيدها ليس له أن يطأها في دبرها، فالمؤمنة الكاملة هي التي حفظت فرجها إلا من زوجها وسيدها فيما أباح الله، والمؤمن الكامل هو الذي حفظ فرجه إلا مما أباح الله من زوجته الشرعية، وأمته الشرعية، في محل الوطء، وهو القبل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17923/تفسير-قوله-تعالى-والحافظين-فروجهم-والحافظات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87604.mp3","categories":["التفسير"]},{"id":18796,"question":"يسأل سؤالًا آخر أخونا عن تفسير قوله تعالى -بعد أعوذ بالله من الشيطان الرجيم-: حُرّمتْ عليْكُمُ الْميْتةُ والدّمُ ولحْمُ الْخنزير وما أُهلّ لغيْر اللّه به والْمُنْخنقةُ والْموْقُوذةُ والْمُتردّيةُ والنّطيحةُ وما أكل السّبُعُ إلّا ما ذكّيْتُمْ وما ذُبح على النُّصُب وأنْ تسْتقْسمُوا بالأزْلام [المائدة:3]، أرجو تفسير هذه الآية.وهل النطيحة إذا ذبحت وهي حية تعتبر حرام؟ وهل المقصود من النطيحة هي التي تنطحها شاة أخرى؟ أرجو الإجابة عن ذلك جزاكم الله خيرًا.","title":"تفسير قوله تعالى: {حرمت عليكم الميت...}","answer":"الجواب: الآية واضحة، يقول سبحانه: حُرّمتْ عليْكُمُ الْميْتةُ  [المائدة: 3] الميتة -معروفة- التي تموت حتف أنفها، هذه حرام، سواء كانت بقرة، أو ناقة، أو شاة، أو ظبي، أو أرنب، أو دجاجة، أو غير ذلك.\nوالدّمُ هو المسفوح الذي يسيل من البهيمة عند ذبحها، وهكذا يسيل من الجروح، هذا نجس محرم؛ لقوله في الآية الأخرى أَوْ دَمًا مَسْفُوحًا [الأنعام:145] أما الدم الذي يكون في العروق، وفي داخل اللحوم، هذا لا، لا يحرم، ولا حرج فيه. ولحْمُ الْخنزير معروف، الخنازير معروفة كلها محرمة بإجماع المسلمين، وإن أكلها النصارى فإن أكلهم لها حرام عليهم ومنكر، ولكنهم كفار لا يرعون حدود الله. وما أُهلّ لغيْر اللّه به كذلك الذي يذبح لغير الله؛ كالتي تذبح للجن أو تذبح للأصنام، أو للكواكب أو للزار، يذبح شاة أو بقرة أو بعير، يذبحه للجن يتقرب إلى الجن يخاف منهم، أو يذبح للأصنام أو لأصحاب القبور، يتقرب إليهم بالذبائح كما يفعل بعض الجهلة، أو يذبحه للكواكب؛ للثريا أو لكذا أو للشمس أو غير ذلك، هذه يقال لها: ذبيحة ميتة، يقال لها: مهلة لغير الله، يعني: نحرت لغير الله، وسمي عليها غير الله ، هذه ميتة مثل ذبائح المشركين. والْمُنْخنقةُ هي التي تخنق بالحبل، أو باليدين يخنقها إنسان، مثل: فيها حبل في رقبتها، فانخنقت به وماتت، أو خنقها غيرها جرها عليها حتى ماتت، هذه يقال لها: منخنقة. والْموْقُوذةُ هي التي تضرب بشيء ثقيل، مثل: شاة يضربونها بالخشب، أو بالأحجار حتى ماتت، هذه يقال لها: موقوذة، وهكذا لو ضربها بخشبة، أو بالرمح بحافة الرمح، سماها النبي ﷺ: وقيذة؛ لأنها ماتت بالمثقل، بحافة وعرض الرمح مثلًا، أو بخشبة، أو بحجر سقط عليها، أو باب سقط عليها حتى ماتت، يقال لها: وقيذة وموقوذة، كل هذا محرم. والْمُتردّيةُ : التي تسقط من جبل، أو من سطح طابق أعلى، أو تسقط في حفرة أو في بئر وتموت. والنّطيحةُ : هي التي تنطحها أختها، عنز نطحتها عنز، خروف نطحه خروف، بقرة نطحتها بقرة، ثور نطحه ثور، وهكذا، فالمتناطحتان إذا ماتتا أو ماتت إحداهما فهي ميتة، إلا أن تدرك وهي حية وتذكى؛ تحل، وهكذا الموقوذة وهكذا المتردية، كلها إذا أدركها صاحبها أو إنسان مسلم أدركها حية ما بعد ماتت وذكاها؛ حلت. وهكذا ما أكله السبع: ما نيبه السبع الذئب، أو الأسد أو النمر طعنها بنابه، ولكن أدركها صاحبها حية ثم ذبحها فإنها تحل أيضًا. وهكذا وَمَا ذُبِحَ عَلَى النُّصُبِما ذبحه الكفار على أصنامهم؛ لأصنامهم، يذبحونه تعظيمًا لأصنامهم، هذا مثل ما أهل به لغير الله، ميتة؛ ولهذا قال بعده: إلّا ما ذكّيْتُمْ فما ذكي ذكاه المسلمون وهو حي فإنه حلال، وهكذا ما ذكاه أهل الكتاب: اليهود والنصارى إذا ذكاه على الوجه الشرعي؛ فإنه يحل، إذا أدرك حيًا قبل أن يموت، بأن أدركه يتحرك رجله أو يده أو ذنبه أو ما..، يعني: المقصود أدركه حيًا، نعم. المقدم: نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17929/تفسير-قوله-تعالى-حرمت-عليكم-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87607.mp3","categories":["التفسير"]},{"id":18852,"question":"رسالة وصلت إلى البرنامج من جيزان، وباعثها أخونا عبد الغني محمد عبد السلام، أخونا عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل عن تفسير قوله تعالى في سورة النور -بعد أعوذ بالله من الشيطان الرجيم -: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ وَاللَّهُ سَمِيعٌ عَلِيمٌ [النور:60]. أرجو من سماحة الشيخ أن يتكرم بتفسير هذه الآية الكريمة.","title":"تفسير قوله تعالى: {والقواعد من النساء ...}","answer":"الجواب: هذه الآية الكريمة يراد منها: العجائز اللاتي قد انتهت رغبتهن في النكاح؛ فلا بأس أن يضعن ثيابهن، ولا يتحجبن تحجب الشابات إذا كن بهذه الصفة، كما قال الله : وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ [النور:60] فهما شرطان: كونها من القواعد، وكونها غير متبرجة بالزينة التي تدعو الرجال إلى الميل إليها، والرغبة فيها. ثم بين  أن استعفافهن -وإن كن قواعد- خير لهن، وأبعد من الفتنة، وهذا يبين لنا أمورًا، منها: أن الشابة ليس لها أن تضع ثوبها، بل عليها أن تستتر، وأن تحتجب، كما قال الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] تكون ساترة لبدنها وشعرها ووجهها وأطرافها. وهكذا قوله سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب: ما يطرح على المرأة من فوق رأسها تستر به بدنها، علاوة على القميص الذي عليها. وهكذا قوله -جل وعلا-: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31].. الآية، فعليها أن تستر زينتها، ولا تبدي زينتها إلا للمحارم -كما بينه الله - والوجه من أعظم الزينة، والشعر من أعظم الزينة، تستر بدنها، وتستر شعرها ووجهها وأطرافها، إلا عن محرمها وهو أخوها وعمها ونحوهما. أما العجوز التي لا تريد النكاح ولا تبرج بزينة؛ فلا حرج أن تطرح الثوب والجلباب الذي عليها، فيبدو وجهها مثلًا، يبدو أطرافها، أطراف يديها؛ فلا بأس بذلك، وقال بعض أهل العلم: حتى الشعر الذي هو شعر الرأس إذا كانت لا تشتهى وليست بمتزينة، ولا تريد النكاح، ولكن مثلما قال الله  -استعفافها خير لها- ولو كانت كبيرة السن، ولو كانت غير متزينة ولا متبرجة، ولو كانت لا تريد النكاح؛ فإن كل ساقطة لها لاقطة، فينبغي للعجوز التعفف، ولو كانت كبيرة السن، ولو كانت غير متبرجة، ولو كانت لا تريد النكاح، كما ربنا : وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60]. لكن لو كشفت وجهها، أو طرحت عنها الجلباب الذي عليها وهي غير متبرجة، وغير تريد النكاح، وليس فيها فتنة، بل كبر السن ظاهر عليها؛ بحيث لا يميل إليها الرجال، جاز لها أن تفعل ذلك، بأن تكون مكشوفة الوجه، ليس عليها الجلباب الذي يفعله الشابات، ولكن كونها تفعل الجلباب، وكونها تستر وجهها وتستر نفسها، هذا خير لها وأكبر، وأعظم في حقها، وأبعد عن الفتنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18011/تفسير-قوله-تعالى-والقواعد-من-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_879/nour_87906.mp3","categories":["التفسير"]},{"id":18989,"question":"يسأل - أيضًا - أخونا عن تفسير قول الحق تبارك وتعالى: قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ وَلا نُشْرِكَ بِهِ شَيْئًا وَلا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ[آل عمران:64]؟","title":"ما معنى: {‌قُلْ ‌يَا أَهْلَ ‌الْكِتَابِ ‌تَعَالَوْا ‌إِلَى ‌كَلِمَةٍ ‌سَوَاءٍ}؟","answer":"الجواب: هذه الآية عظيمة، أمر الله نبيه ﷺ أن يدعو أهل الكتاب وهم اليهود والنصارى إلى كلمة وهي كلمة التوحيد لا إله إلا الله، مع شهادة أن محمدًا رسول الله. سواء يعني: فصل بيننا وبينكم، نستوي نحن وأنتم فيها، كلنا سواء فيها، علينا جميعًا أن نعبد الله وحده دون ما سواه . وعلينا ألا نشرك به شيئًا، لا نشرك به لا صنمًا، ولا نبيًا، ولا جنيًا، ولا شجرًا، ولا حجرًا، ولا غير ذلك. ولا يتخذ بعضنا بعضًا أربابًا من دون الله ليس لنا أن يتخذ بعضنا بعضًا أربابًا من دون الله، فليس للإنس أن يتخذ بعضهم بعضًا، ولا للجن، ولا للملائكة، ولا غيرهم، كلهم يجب عليهم أن يعبدوا الله وحده، كما قال تعالى في الآية الأخرى في سورة آل عمران: وَلا يَأْمُرَكُمْ أَنْ تَتَّخِذُوا الْمَلائِكَةَ وَالنَّبِيِّينَ أَرْبَابًا أَيَأْمُرُكُمْ بِالْكُفْرِ بَعْدَ إِذْ أَنْتُمْ مُسْلِمُونَ[آل عمران:80] فلا يجوز لأحد أن يتخذ ربًا مع الله يعبده، ويستغيث به، أو يصلي له، أو يسجد له، أو نحو ذلك. بل الجميع عباد الله، يجب عليهم أن يخصوا الله بالعبادة أينما كانوا من دعاء وخوف، ورجاء وصلاة وصوم، وذبح ونذر.. وغير ذلك. فإن تولوا يعني: فإن تولى هؤلاء من اليهود والنصارى، وأعرضوا عن قبول الحق، فقولوا: اشهدوا، يعني: قولوا لهم مشافهة وصريحًا: إنا مسلمون، يعني اشهدوا أنا مسلمون وأنتم كفار: يعني اشهدوا علينا أنا مسلمون يعني: منقادون لله، موحدون له، معظمون له، خاضعون له، نعبده وحده دون كل ما سواه. خلافًا لكم، نعم، الله المستعان. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18150/ما-معنى-قل-يا-اهل-الكتاب-تعالوا-الى-كلمة-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_793/nour_79303.mp3","categories":["التفسير"]},{"id":18990,"question":"سماحة الشيخ! من محاسن الأقدار أن سماحتكم استشهدتم بالآية من سورة الزمر، وأخونا يسأل -أيضًا- عن تفسيرها، فيقول: فسروا لنا قول الحق تبارك وتعالى: أَلا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ[الزمر:3].","title":"تفسير قوله تعالى: {ألا لله الدين الخالص...}","answer":"الجواب: مثل ما تقدم. نعم، هم اتخذوهم - عبدوهم - من دون الله ليقربوهم إلى الله زلفى فقولهم: مَا نَعْبُدُهُمْ[الزمر:3] يعني يقولون: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى[الزمر:3] وقبلها يقول جل وعلا: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ[الزمر:2] ثم قال سبحانه: أَلا لِلَّهِ الدِّينُ الْخَالِصُ[الزمر:3] يعني العبادة الخالصة له وحده جل وعلا، ليس له شريك في ذلك كما قال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ[البينة:5] في سورة البينة، وقال جل وعلا: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ[غافر:14] ولهذا قال سبحانه: أَلا لِلَّهِ الدِّينُ الْخَالِصُ[الزمر:3]. ثم قال: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى[الزمر:3] يعني يقولون -هؤلاء المتخذون يقولون-: ما نعبدهم يعني هؤلاء الآلهة من أصنام، وأشجار، وأحجار، وملائكة، وأنبياء وغيرهم: إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى[الزمر:3] يعني: ما نعبدهم لأنهم يخلقون، أو يرزقون، أو ينفعون، أو يضرون لا، هم يعرفون أن الله هو النافع الضار، يعرف المشركون الأولون من قريش وغيرهم، يعرفون أن الله هو النافع الضار، هو الخلاق الرزاق، هو المدبر، هو المحي، المميت، يعرفون هذا كما قال جل وعلا آمرًا نبيه أن يسألهم قال سبحانه لنبيه: قُلْ مَنْ يَرْزُقُكُمْ مِنَ السَّمَاءِ وَالأَرْضِ أَمَّنْ يَمْلِكُ السَّمْعَ وَالأَبْصَارَ وَمَنْ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَنْ يُدَبِّرُ الأَمْر[يونس:31] قال تعالى: فَسَيَقُولُونَ اللَّهُ[يونس:31] يعني يقوله المشركون، قال تعالى: فَقُلْ أَفَلا تَتَّقُونَ[يونس:31]. يعني: قل لهم يا محمد: أفلا تتقون الإشراك بالله، وأولها يقول سبحانه: (قل) يعني: قل يا محمد! للناس -لقريش وغيرهم- من يرزقكم من السماء والأرض يعني: من هو الذي يرزقهم من السماء والأرض؟ يعني: يرزق العباد من السماء والأرض، يرزقهم من السماء بالمطر وغيره، ومن الأرض بالنبات الذي ينبته الله، والثمار، والحيوانات التي في الأرض، والمعادن وغير ذلك. أَمَّنْ يَمْلِكُ السَّمْعَ وَالأَبْصَارَ[يونس:31] هو اللي يملك سمع الناس وأبصارهم، وَمَنْ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَنْ يُدَبِّرُ الأَمْرَ[يونس:31] يعني في العالم كله، قال الله تعالى: فَسَيَقُولُونَ اللَّهُ[يونس:31] يعني هؤلاء المشركون يقولون: الله، هو المدبر للأمور، وهو الخلاق وهو الرزاق، وهو النافع الضار، وهو الذي يحيي ويميت  فسر إخراج الحي من الميت إخراج المسلم من الكافر. نعم. والميت من الحي، الكافر من المسلم، وفسر بإخراج البيضة من الدجاجة، والدجاجة من البيضة، والنبات من الأرض الميتة. كل هذا إخراج، نوع من إخراج الحي من الميت، والميت من الحي، سبحان الله. فالمقصود أن المشركين من عبدة الأوثان يعرفون الله سبحانه هو النافع الضار، وهو مدبر الأمور، وهو الخلاق الرزاق، ولكنهم يعبدون الآلهة ليشفعوا لهم، وليقربوهم إلى الله زلفى، لا لأنهم ينفعون ويضرون، بخلاف الكفار المشركين المتأخرين، هؤلاء قد وقعوا في الشرك الأكبر من جهة الربوبية. بعض المشركين المتأخرين شركهم أكبر من أولئك المشركين؛ لأنهم أشركوا مع الله في الربوبية، وظنوا أن بعض آلهتهم يدبرون الأمور، ويتصرفون في الأمور، وينفعون ويضرون. وأن الله جعل لهم هذا، وهذا باطل، هذا كفر بالربوبية، شرك بالربوبية أعظم وأقبح من شرك قريش وأشباههم. قال الله تعالى: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ[الزمر:3] فسماهم كذبة في قولهم إنهم يقربونهم إلى الله زلفى. كفار لأنهم عبدوهم مع الله، ودعوهم، واستغاثوا بهم، ونذروا لهم، وتقربوا لهم، فصاروا بهذا كفاراً، ولهذا قال سبحانه: إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ[الزمر:3] يعني لا يوفقه لقبول الحق، وإلا الهداية البلاغ قد بلغهم سبحانه بالرسل، والكتب، لكن لا يهدي: لا يوفقهم بسبب إعراضهم عن الحق، واستكبارهم عن الحق، وعنادهم للرسل، نسأل الله العافية والسلامة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18149/تفسير-قوله-تعالى-الا-لله-الدين-الخالص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_793/nour_79302.mp3","categories":["التفسير"]},{"id":18991,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المواطن بشير محمد حسين من ليبيا أخونا بشير عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة بقي له عدد من الأسئلة، في مجموعة من أسئلته يسأل عن تفسير بعض آيات من القرآن الكريم، إحداها هذا السؤال يقول: فسروا لنا قول الحق تبارك وتعالى: أعوذ بالله من الشيطان الرجيم وَاتَّخَذُوا مِنْ دُونِ اللَّهِ آلِهَةً لَعَلَّهُمْ يُنصَرُونَ ۝ لا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُحْضَرُونَ ۝ فَلا يَحْزُنْكَ قَوْلُهُمْ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ[يس:74-76]؟","title":"تفسير قوله تعالى: {واتخذوا من دون الله آلهةً...} الآيات","answer":"الجواب: بسم الله الرحمن الرحيم، والحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالآية واضحة في بيان حال المشركين الذين بعث فيهم عليه الصلاة والسلام من قريش وغيرهم، وأنهم اتخذوا من دون الله آلهة من الأصنام، والأشجار، والأحجار، والملائكة، والأنبياء وغيرهم. فإن آلهة المشركين أنواع كثيرة، وهم فعلوا هذا لعلهم ينصرون، يرجون نصرهم، ويرجون شفاعتهم، كما قال جل وعلا عنهم في آية أخرى: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ[يونس:18] يعني شفعاؤنا في نصرهم لنا، وإعانتهم لنا على أعدائنا، وفي شفاء مرضانا، وفي غير ذلك. وقال في الآية الأخرى في سورة تنزيل الزمر: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى[الزمر:3] فهم عبدوهم لينصروهم، ويقربوهم ويشفعوا لهم، ثم بيَّن سبحانه أنهم لا يستطيعون نصرهم، هذه الآلهة ما تستطيع نصرهم، ولا نصر نفسها - أيضًا - كما قال جل وعلا في سورة الأعراف: أَيُشْرِكُونَ مَا لاَ يَخْلُقُ شَيْئًا وَهُمْ يُخْلَقُونَ ۝ وَلاَ يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلاَ أَنفُسَهُمْ يَنصُرُونَ[الأعراف:191-192] فهم لا يستطيعون نصر عابديهم، ولا نصر أنفسهم، بل النصر من عند الله جل وعلا، هو اللذي ينصر من يشاء ، كما قال تعالى: وَمَا النَّصْرُ إِلَّا مِنْ عِنْدِ اللَّهِ الْعَزِيزِ الْحَكِيمِ[آل عمران:126] وَهُمْ لَهُمْ جُندٌ مُحْضَرُونَ[يس:75] يوم القيامة ضدهم، محضرون معهم يوم القيامة في النار، كلهم يعذبون جميعًا، وهذا في الآلهة المعبودة من دون الله برضاها كـفرعون، والنمرود، والأصنام وأشباههم فهم معهم في النار. أما الملائكة والأنبياء فهم برآء منهم، لا يرضون بعبادتهم إياهم، كما قال جل وعلا عن الملائكة: تَبَرَّأْنَا إِلَيْكَ مَا كَانُوا إِيَّانَا يَعْبُدُونَ[القصص:63]. فالمقصود أن هؤلاء الأصنام الذين هم معهم يوم القيامة في النار، هم الذين عبدوهم من دون الله من جمادات كالأصنام، والأشجار، أو آلهة من الجن أو من الإنس رضوا بذلك، فهم معهم في النار. أما من لم يرض بذلك من الأنبياء، والملائكة، والصالحين فهم ليسوا معهم، بل الله قد أجارهم منهم، وحماهم منهم، وهم برآء منهم، بل العابدون هم اللي في النار الذين عبدوا غير الله وأشركوا بالله. وأما المعبودون الذين لم يرضوا بذلك كالملائكة، والرسل، والأنبياء، والصالحين؛ فإنهم لا يرضون أن يعبدوا من دون الله، بل يتبرءون من ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18147/تفسير-قوله-تعالى-واتخذوا-من-دون-الله-الهة-الايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_793/nour_79301.mp3","categories":["التفسير"]},{"id":18996,"question":"أيضًا يسأل عن تفسير قول الحق تبارك وتعالى: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدِ افْتَرَى إِثْمًا عَظِيمًا[النساء:48]؟","title":"ما معنى: {إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ}؟","answer":"الجواب: هذه الآية آية عظيمة، وهي آية محكمة نزلت في أهل الشرك إذا ماتوا على الشرك، إذا مات المشرك لا يغفر له، أما إذا أسلم، وتاب إلى الله؛ يغفر له، لكن إذا مات على الشرك فإنه لا يغفر له، ولهذا قال سبحانه في هذه الآية في موضعين من سورة النساء: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ[النساء:48] يعني لا يغفر له ذنوبه بل يدخله بها النار، كما قال في الآية الأخرى: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ[المائدة:72] فالمشرك إذا مات على الشرك لا يغفر له، بل له النار أبدًا، أبد الآباد، والجنة عليه حرام، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ[الأنعام:88]. فالمقصود أن الشرك هو أعظم الذنوب، وأقبح القبائح، فمن مات عليه لم يتب لا يغفر له، والجنة عليه حرام بنص هذه الآية، وهو قوله سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ[النساء:48] ثم قال سبحانه: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ[النساء:48] يعني ما دون الشرك من الذنوب كالزنا، والعقوق، والخمر ونحو ذلك تحت مشيئة الله، إن شاء الله غفر لصاحبه يوم القيامة بأعماله الصالحة الأخرى، وبحسناته الأخرى، فضلًا من الله وجودًا وكرمًا. وإن شاء عاقبه على قدر معاصيه التي مات عليها من عقوق لوالديه أو أحدهما، من شرب مسكر، من زنا، من غيبة، من نميمة، من غير ذلك، ثم قال سبحانه: وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدِ افْتَرَى إِثْمًا عَظِيمًا[النساء:48] وفي الآية الأخيرة في سورة النساء فَقَدْ ضَلَّ ضَلالًا بَعِيدًا[النساء:116] فالمشرك ضال ضلالًا بعيدًا، وقد افترى على الله إثمًا عظيمًا حين ظن أن الله يجيز هذا الشيء ويرضاه، فعبد الأنداد والأصنام من دون الله، يظن أن هذا مرضٍ لله، وهذا باطل، وقد افترى على الله إثمًا عظيمًا بهذا الظن السيء. والخلاصة أن من مات على الشرك لا يغفر له، والجنة عليه حرام، من عرب وعجم، ومن جن وإنس، ومن مات على ما دون الشرك من المعاصي، فهو تحت مشيئة الله خلافًا للمعتزلة والخوارج، ومن سار على مذهبهم من سائر المبتدعة، فإن الخوارج والمعتزلة ومن سار على مذهبهم يرون العاصي مخلد في النار، وأنه لا يغفر له إذا مات على الزنا يروه مخلدًا في النار، أو الخمر يروه مخلدًا في النار هذا باطل، بل هو تحت مشيئة الله، إن شاء الله غفر له، ومحا عنه سيئاته، وأدخله الجنة بتوحيده، وإسلامه، وأعماله الصالحة الأخرى. وإن شاء عذبه على قدر معاصيه، يعذب في النار ما شاء الله، ثم يخرج من النار، عند أهل السنة والجماعة وهم الصحابة  وأتباعهم بإحسان، يعذب ما شاء الله قد تطول مدته، وقد تقصر على حسب أعماله السيئة، ثم يخرج من النار، لا يخلد في النار، لا يخلد في النار إلا المشركون إلا الكفرة.\nأما العاصي الموحد المسلم لا يخلد في النار إذا دخلها، يعذب على قدر معاصيه التي مات عليها لم يتب، ثم يخرجه الله من النار إلى الجنة، عند أهل الحق عند أهل السنة والجماعة بإجماع أهل السنة والجماعة خلافًا للخوارج والمعتزلة ومن سار على منهجهم من الإباضية. فالمقصود أن هذا القول باطل، وأن العاصي المسلم الموحد تحت مشيئة الله لا يكفر، ولا يخلد في النار، فـالخوارج يقولون: كافر إذا زنى كفر ، إذا سرق كفر ، إذا شرب الخمر كفر ، هذا باطل، يكون عاصي وليس بكافر، لكن إيمانه ضعيف. ولهذا جاء في الحديث أنه  قال: لا يزني الزاني حين يزني وهو مؤمن يعني: الإيمان الكامل، ولا يسرق حين يسرق وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن يعني الإيمان الكامل، عنده أصل الإيمان لكنه عاصي، إيمانه ضعيف، ولهذا نفي عنه، يعني نفي عنه كماله، بدليل أنه ﷺ لم يحكم على الزاني بالردة، ولا على السارق بل جاء النص القرآني بأن الزاني يجلد مائة جلدة يعني إذا كان بكرًا، والزانية كذلك، وإذا كان الزاني محصنًا فإنه يرجم كما صحت به السنة، ونزل به قرآن نسخ لفظه، وبقي حكمه، فهو جلد حدًا، ورجم حدًا، وصلى عليهم النبي ﷺ لما رجموا. والسارق تقطع يده وليس بكافر، ولو كان كافرًا يقتل لقول النبي ﷺ: من بدل دينه فاقتلوه فلو كان السارق كافرًا قتل ما قطعت يده. هكذا شارب الخمر لو كان كافرًا قتل، ولكن يجلد أربعين جلدة، ثم رأى عمر  والصحابة جعلها ثمانين، فيجلد ثمانين جلدة، فقول الخوارج والمعتزلة من أبطل الباطل. فليس بكافر في الأصل إذا كان موحدًا يعبد الله وحده، وليس عنده ناقض من نواقض الإسلام، وليس بمخلد في النار إذا مات على معصيته وهو موحد مسلم، ولكنه إذا لم يعف الله عنه يعاقب على قدر ذنبه، حسب حكمة الله ومشيئته . ثم يخرجه الله من النار بعد التطهير والتمحيص إلى الجنة، ولا يخلد في النار إلا الكفار، ما يخلد في النار إلا الكفار الذين حكم الشرع بكفرهم وخروجهم من الإسلام، أو ارتدوا بعد إسلامهم - ارتدوا عن الإسلام وصاروا كفارًا - هؤلاء يخلدون في النار بإجماع المسلمين كما قال تعالى في حقهم وأشباههم: وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ[البقرة:167] وقال فيهم سبحانه: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ[المائدة:37] قال في حقهم: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ[البقرة:167]. هذا هو الحق، وهذه مسألة مهمة عظيمة يجب على من كان عنده شيء من إشكال أن يعتني بهذا المقام، وأن يعرف حقيقة مذهب أهل السنة والجماعة، وأن يحذر قول الخوارج والمعتزلة ومن سار على منهجهم من أهل الباطل الذين يقولون: إن العاصي كافر كالزاني ونحوه، أو يقولون: إنه مخلد في النار كل هذا باطل. فالعاصي المسلم الموحد ليس بكافر، وليس مخلدًا في النار، ولكن إن دخلها يعذب على قدر جريمته، ثم يخرج منها إلى الجنة، كما تواترت بذلك الأحاديث عن رسول الله ﷺ وأجمع عليه أهل السنة والجماعة، وثبت عنه ﷺ في الصحيحين وغيرهما: أنه يشفع في العصاة عدة شفاعات، فيخرج الله من النار أقوامًا كثيرين قد امتحشوا، قد احترقوا، يخرجهم الله بشفاعته عليه الصلاة والسلام، ويخرج الله أيضًا من النار بشفاعة الملائكة والأنبياء الآخرين والرسل، والمؤمنين والأفراط، يخرج الله جمًا غفيرًا من النار بالشفاعة، ولا يبقى في النار موحد. وبعد الشفاعات يقول جل وعلا: شفعت الأنبياء، وشفعت الملائكة، وشفع المؤمنون، ولم يبق إلا رحمة أرحم الراحمين، فيخرج الله من النار أقوامًا بغير شفاعة أحد، يخرجهم من النار سبحانه؛ لأنهم كانوا يقولون: لا إله إلا الله، كانوا موحدين مسلمين، دخلوا النار بمعاصيهم، فلما عوقبوا بقدر معاصيهم أخرجهم الله من النار بتوحيدهم، وإسلامهم، وسلامتهم من الشرك، هذا قول أهل الحق من أهل السنة والجماعة، وهم أصحاب النبي ﷺ وأتباعهم بإحسان  وأرضاهم، وجعلنا من أتباعهم بإحسان. فالواجب على كل مؤمن وكل طالب علم أن يعتني بهذا المقام، حتى يبصر الناس، وحتى يوضح لهم بطلان قول المبتدعة من الخوارج والمعتزلة في هذا الباب، ومن سار على نهجهم الباطل، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم. الشيخ: الله المستعان.","link":"https://binbaz.org.sa/fatwas/18158/ما-معنى-ان-الله-لا-يغفر-ان-يشرك-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_794/nour_79404.mp3","categories":["التفسير"]},{"id":19007,"question":"يسأل ويقول: فسروا لي هذه الآيات جزاكم الله خيرًا، قال الله تعالى: وَلَمَّا فَتَحُوا مَتَاعَهُمْ وَجَدُوا بِضَاعَتَهُمْ رُدَّتْ إِلَيْهِمْ قَالُوا يَا أَبَانَا مَا نَبْغِي هَذِهِ بِضَاعَتُنَا رُدَّتْ إِلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ذَلِكَ كَيْلٌ يَسِيرٌ[يوسف:65] ما هو المتاع؟ وما المقصود بالبضاعة؟ جزاكم الله خيرًا.","title":"تفسير قول الله تعالى: {ولما فتحوا متاعهم ...}","answer":"الجواب: يوسف عليه الصلاة والسلام أمر فتيانه أن يجعلوا نقود إخوته في متاعهم؛ حتى يستعينوا بها على الرجوع للميرة بأخيهم الذي طلب أن يأتوا به فلما فتحوا متاعهم، المتاع: الأثاث الذي معهم، المزايد والخروج التي فيها حاجاتهم، يقال لها: متاع، وجدوا الدراهم معهم، فقالوا: ما نبغي: ما لنا حجة، يعني: هذا معنا فلوس نستطيع نرجع ونشتري ميرة أخرى، ومع هذا نزداد كيل بعير إذا كان معنا أخونا، في إبل عاشر يكون عندهم عشرة أحمال. فطلبوا من أبيهم أن يرسله معهم، ما دامت النقود موجودة، ويزدادون حمل بعير، هذا شيء فيه مصلحة، الدراهم موجودة، ووجود أخ معهم يحقق رغبة العزيز وهو يوسف عليه الصلاة والسلام، ومع هذا يزدادون كيل بعير، على ظنهم أنه يرجع معهم بحمل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18169/تفسير-قول-الله-تعالى-ولما-فتحوا-متاعهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79510.mp3","categories":["التفسير"]},{"id":19017,"question":"المستمع علي عبد المطلب صالح سوداني مقيم في المملكة يسأل عن تفسير قول الحق تبارك وتعالى أعوذ بالله من الشيطان الرجيم: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ وَاللَّهُ سَمِيعٌ عَلِيمٌ [النور:60]؟","title":"تفسير قوله تعالى: {والقواعد من النساء ...}","answer":"الجواب: أوضح العلماء رحمة الله عليهم أنهن العجائز اللاتي لا يلتفت إليهن ولا يرغب فيهن لكبر سنهن وضعفهن وعدم تبرجهن بالزينة هؤلاء لهم الكشف تكشف عن وجهها وعن يديها لا بأس بذلك. واستعفافها وتسترها خير لها وأفضل؛ لأنه كما قيل كل ساقطة لها لاقطة، فقد تبتلى بمن يفتن بها، لكن الأصل الجواز إذا كانت بهذه الصفة عجوز كبيرة السن لا تشتهى ولا يمال إليها، ولا ترجو النكاح، ومع ذلك ملابسها وحالتها ليس فيها زينة، وليس فيها تبرج لا من جهة الملابس، ولا من جهة الكحل، ولا من جهة الأصباغ، ولا من جهة ما يفتن، بعيدة عن هذه الأشياء. فإذا كانت بحالة لا يرغب فيها لكبر سنها وعجزها وعدم تبرجها بالزينة؛ فإنه لا حرج عليها في الكشف، يعني: وضع الثياب التي على وجهها ألا تستر وجهها، قال بعضهم: ولا رأسها أيضًا؛ لأنها لا تشتهى، لكن تعففها مثلما قال ربنا سبحانه: وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60] تعففها بالتستر وبالحجاب أولى لها وأبعد لها عن الخطر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18186/تفسير-قوله-تعالى-والقواعد-من-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92704.mp3","categories":["التفسير","قضايا المرأة"]},{"id":19120,"question":"تسأل سماحتكم عن تفسير قول الحق تبارك وتعالى: مَرَجَ الْبَحْرَيْنِ يَلْتَقِيَانِ ۝ بَيْنَهُمَا بَرْزَخٌ لا يَبْغِيَانِ [الرحمن:19-20]، هل هذان البحران في الدنيا أم في الآخرة؟","title":"ما معنى: {مَرَجَ الْبَحْرَيْنِ يَلْتَقِيَانِ * بَيْنَهُمَا بَرْزَخٌ لا يَبْغِيَانِ}؟","answer":"الجواب: لا، في الدنيا، فالبحار تختلط، ثم إذا أراد الله تمييزها تميزت هذا من هذا، وخرج ماء النهر وحده وماء البحر وحده، بَيْنَهُمَا بَرْزَخٌ لا يَبْغِيَانِ [الرحمن:20]، يعني: لا يبغي هذا على هذا، فالأنهار تجري على حالها حلوة، والبحار على حالها مالحة، وبينهما برزخ لا يبغي هذا على هذا، ينفصل هذا عن هذا. نعم، الله المستعان. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18303/ما-معنى-مرج-البحرين-يلتقيان-بينهما-برزخ-لا-يبغيان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73708.mp3","categories":["التفسير"]},{"id":19130,"question":"من المستمع: حلمي أبو سمرة رسالة يسأل فيها عن تفسير آية الاستئذان الواردة في سورة النور جزاكم الله خيرًا، وأحسن إليكم.","title":"تفسير آية الاستئذان الواردة في سورة النور","answer":"الجواب: آية النور آية الاستئذان واضحة يقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنْكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلاثَ مَرَّاتٍ مِنْ قَبْلِ صَلاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّهِيرَةِ وَمِنْ بَعْدِ صَلاةِ الْعِشَاءِ ثَلاثُ عَوْرَاتٍ لَكُمْ لَيْسَ عَلَيْكُمْ وَلا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُمْ بَعْضُكُمْ عَلَى بَعْضٍ[النور:58]. فالمؤمن إذا كان -عنده - معه ملك يمين يستأذن عليهم؛ لأنه قد يكون في حالة وقد يكون في حالة لا ترضى، لا يرضون أن يروا عليها، فيستأذن عليهم في هذه الأوقات، وهكذا أهل بيته يستأذن عليهم في الأوقات الثلاثة التي بيَّنها الله جل وعلا في هذه الآية الكريمة، حتى لا يراهن على حال ما تناسب. مِنْ قَبْلِ صَلاةِ الْفَجْرِ[النور: 58] يعني: آخر الليل.\nوَحِينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّهِيرَةِ[النور: 58] يعني: القائلة.\nوَمِنْ بَعْدِ صَلاةِ الْعِشَاءِ[النور: 58]. يعني هذه الأوقات قد يتساهل فيها أهل البيت في عدم التحرج من ستر العورة، قد تكون ملك اليمين على حالة غير مناسبة، وقد ينكشف منها بعض الشيء. المقصود أنه في هذه الأحوال قد يتساهل أهل البيت في وقت الظهيرة، وقبل صلاة الفجر، وبعد صلاة العشاء. كل هذه الأوقات فيها خلوة الإنسان بنفسه فليستأذن إذا دخل عليهم يستأذن سواء كان ملك يمين، أو صبي لم يبلغ الحلم، وإن كان صبي؛ لأنه قد لا يرضون أن يطلع على شيء من حالاتهم في هذه الأوقات الثلاثة. فالخادم سواء كان مملوكًا وكما نصت عليه الآية، أو غير مملوك من باب أولى، وهكذا من لم يبلغ الحلم من الصبيان يستأذن في هذه الأوقات الثلاثة، وغير الصبي من باب أولى، الكبير من باب أولى. والمقصود من هذا التحرز من كونه يرى أهل البيت على حالة غير مناسبة، فإذا استأذن استعدوا، وحرصوا على أن يكونوا على حالة حسنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18312/تفسير-اية-الاستىذان-الواردة-في-سورة-النور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79711.mp3","categories":["التفسير"]},{"id":19248,"question":"يسأل سماحتكم فيقول: فسروا لنا قول الحق تبارك وتعالى: إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ [فاطر:28]؟","title":"ما معنى: {إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ}؟","answer":"الجواب: هذه الآية الكريمة تدل على فضل العلماء، وأنهم أهل الخشية لله، يعني: الخشية الكاملة، وعلى رأسهم الأنبياء والرسل عليهم الصلاة والسلام، هم أئمة العلماء، وهم رءوس العلماء وأئمتهم، وكل عالم بشريعة الله فهو من أتباعهم بإحسان إذا استقام على الطريق، فإنه يخشى الله أكمل من غيره، وكل مؤمن يخشى الله  وكل مؤمنة كذلك، لكن العالم أشد خشية وأكثر خشية؛ لما عنده من العلم بالله وبصفاته وبعذابه وعقابه وبكرامته وإنعامه، فهو أعلم الناس بالله على حسب ما أعطاه الله من العلم، فالعلماء هم ورثة الأنبياء، وهم أكمل الناس خشية لله  بعد الأنبياء والرسل، وكل مؤمن له نصيبه من خشية الله، وهكذا المؤمنة، لكن العلماء بالله الذين أعطاهم الله العلم والبصيرة في دينه والاستقامة عليه، هم أخشى الناس لله بعد الأنبياء. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18441/ما-معنى-انما-يخشى-الله-من-عباده-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73811.mp3","categories":["التفسير"]},{"id":19285,"question":"تسأل عن تفسير قول الحق تبارك وتعالى: أعوذ بالله من الشيطان الرجيم: إِنَّ اللَّهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا [البقرة:26]؟","title":"ما معنى: {إِنَّ اللَّهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً}؟","answer":"الجواب: على ظاهر الآية إن الله لا يستحي الحياء يوصف به الرب جل وعلا، كما في الحديث: إن ربكم حيي كريم وفي الحديث الآخر: أن ثلاثةً دخلوا المسجد والنبي ﷺ يذكر الناس، فجاء أحدهم فجلس في الحلقة يستمع، والثاني جلس خلفها، والثالث خرج، فلما فرغ النبي من حديثه عليه الصلاة والسلام، قال: ألا أنبئكم بشأن الثلاثة؟ قالوا: بلى يا رسول الله. قال: أما أحدهم فآوى فآواه الله، وأما الثاني فاستحيا فاستحيا الله منه، وأما الثالث فأعرض فأعرض الله عنه، متفق على صحته. فالمعنى أنه يوصف ربنا بالحياء على الوجه الذي يليق به، هي ليس من جنس حيائنا، حياء الله يليق به، لا يعلم كيفيته إلا هو سبحانه وتعالى، مثلما نصفه بأنه يضحك، ويغضب، ويرضى، ويرحم، ويحب، ويكره، كل ذلك على الوجه الذي يليق به : إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ [البقرة:222]، إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8]، إن الله يرضى لكم ثلاثًا، يضحك الله إلى رجلين يقتل أحدهما الآخر كلاهما يدخل الجنة، إلى أحاديث أخرى. فالمقصود أن الله جل وعلا موصوف بالصفات التي أخبر بها عن نفسه، أو أخبر بها رسوله عليه الصلاة والسلام في الأحاديث الصحيحة، لكن على الوجه اللائق بالله، نمرها كما جاءت كما قال أهل السنة والجماعة، نمرها كما جاءت مع الإيمان بها واعتقاد أنها حق، وأنها تليق بالله لا يشابه فيها خلقه سبحانه وتعالى، كما قال : قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:1-4]، وقال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، وقال سبحانه: فلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74]. قال مالك رحمه الله مالك بن أنس إمام دار الهجرة في زمانه في القرن الثاني، وهكذا قال سفيان الثوري وابن عيينة وقول إسحاق بن راهويه والأوزاعي وأشباههم قالوا في آيات الصفات وأحاديثها: أمروها كما جاءت، أمروها بلا كيف. يعني: أمروها واعتقدوا معناها، وأنه حق لائق بالله لا يشابه في ذلك خلقه، فهكذا الحياء: إِنَّ اللَّهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً [البقرة:26]، وفي آية الأحزاب: وَاللَّهُ لا يَسْتَحْيِي مِنَ الْحَقِّ [الأحزاب:53]، فهو سبحانه لا يستحي أن يضرب الأمثال بالبعوضة، أو بالعنكبوت، أو بالذباب، كما وقع في سورة العنكبوت، وفي سورة الحج ضرب المثل بالذباب، كل هذا حق لبيان الحق وإيضاح الحق لعباده  فليس في هذا حياء، وكذلك رسله وأنبياؤه وأهل العلم لا يستحون أن يوضحوا للناس الحق بالأمثال، وإن كانت الأمثال بأشياء حقيرة من الدواب. فربنا يوصف بالحياء، ويقال: إنه حيي كريم، ويقال: إنه لا يستحي من كذا وكذا على الوجه اللائق بالله، لا يشابه خلقه في شيء من صفاته، ولا يماثلهم، بل هو موصوف بصفات الكمال على الوجه اللائق بالله، ولا يعلم كيفيتها إلا هو، فهو يضحك ولا نعلم كيف يضحك، الله الذي يعلم هذا سبحانه، لكن نعلم أنه ضحك ليس مثلنا، بل هو ضحك كامل يليق بالله لا يشابه ضحك المخلوقين، كذلك يرضى ونعلم أنه يرضى، ولكن ليس كرضانا، نعلم أنه يرحم ليس كرحمتنا، نعلم أنه يغضب ليس كغضبنا، نعلم أنه سميع ليس كأسماعنا.. بصير ليس كأبصارنا، وليس كإبصارنا وسمعنا، كل هذا يليق بالله، وهكذا بقية الصفات، كلها تليق بربنا لا يشابه فيه خلقه في وجه من الوجوه، خلافاً لأهل البدع من الجهمية والمعتزلة ومن شاركهم في بعض ذلك كـالأشاعرة، وما أشبه ذلك. الواجب على المسلم أن يتقي الله، وأن يسير على منهج رسول الله ﷺ، وعلى منهج أئمة السنة لـأهل السنة والجماعة ، وذلك بالإيمان بأسماء الله وصفاته وإمرارها كما جاءت واعتقاد أنها حق، وأنها لائقة بالله وأنه سبحانه ليس له مثيل، ولا شبيه ولا نظير، وأنه أعلم بصفاته وكيفيتها من خلقه : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، فنمرها كما جاءت، ونقول: إنها حق، لكن من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، بل نقول كما قال السلف الصالح: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، . المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/18490/ما-معنى-ان-الله-لا-يستحيي-ان-يضرب-مثلا-ما-بعوضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89307.mp3","categories":["التفسير"]},{"id":19330,"question":"رسالة وصلت إلى البرنامج من العراق، وباعثها أخونا محمد حسين علي حموري أو حموري، أخونا له مجموعة من الأسئلة، يسأل في سؤاله الأول عن تفسير قوله تعالى: بعد أعوذ بالله من الشيطان الرجيم: هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ [الفجر:5]؟","title":"تفسير قوله تعالى: (هل في ذلك قسم لذي حجر)","answer":"الجواب: الحجر: هو العقل والله يقول سبحانه: وَالْفَجْرِ ۝ وَلَيَالٍ عَشْرٍ ۝ وَالشَّفْعِ وَالْوَتْرِ ۝ وَاللَّيْلِ إِذَا يَسْرِ ۝ هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ [الفجر:1-5].\nفهذه الآية تبين أن هذه الأقسام عظيمة أقسم الله بها سبحانه، وهو جل وعلا يقسم بما يشاء  لا أحد يتحجر عليه  وإنما أقسم بها؛ لأنها من آياته الدالة على قدرته العظيمة وأنه رب العالمين، فقال: وَالْفَجْرِ [الفجر:1]، وهو انفلاق الصبح بعد ذهاب الليل.\nوَلَيَالٍ عَشْرٍ [الفجر:2]، فسرت هذه الليالي بليالي عشر ذي الحجة، وبليالي العشر الأخيرة من رمضان فهي كلها معظمة. وَالشَّفْعِ وَالْوَتْرِ [الفجر:3]، الشفع الاثنين والأربعة والستة ونحو ذلك، والوتر الواحد والثلاثة والخمسة ونحو ذلك، كلها من آيات الله  جعل شفعًا ووترًا في مخلوقاته جل وعلا وهي من آياته  السماوات سبع وتر، والأرض سبع وتر، والعرش واحد وتر والكرسي واحد وتر، وجعل أشياء شفعًا كالليل والنهار شفعًا والذكر والأنثى شفعًا وغير ذلك، كما قال سبحانه: وَمِنْ كُلِّ شَيْءٍ خَلَقْنَا زَوْجَيْنِ [الذاريات:49]. وَاللَّيْلِ إِذَا يَسْرِ [الفجر:4]، كذلك من آياته هذا الليل حين يأتي بظلامه والنهار حين يأتي بضيائه كلها من آياته . ثم قال بعدها: هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ [الفجر:5]، فالمعنى -والله أعلم-: هل في ذلك قسم لذي حجر، لذي عقل، ليس يقتضي أن يخالف، بل يجب على المؤمن أن يتدبر ويتعقل ويعرف أنه سبحانه إنما أقسم بهذه الأقسام لدلالة عباده على عظم هذه المخلوقات وأنها من الدلائل على قدرته العظيمة ووحدانيته  وأنه لا يجوز للمؤمن أن يخالف ما دلت عليه فيشرك بالله ويعبد معه سواه وهو الخلاق لهذه الأشياء القائم بأرزاق العباد إلى غير هذا . ويحتمل معنى آخر هو أنه سبحانه يريد هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ [الفجر:5]، ليقسم به أولى من هذه الأقسام التي فيها دلائل على قدرته العظيمة، مع أنه سبحانه حرم القسم بغيره جل وعلا، قال النبي ﷺ: من كان حالفًا فليحلف بالله أو ليصمت.\nفليس لأحد أن يقسم إلا بربه ﷺ. فالآية فيها شيء من الغموض، لكن يحتمل أن المراد أن هذا القسم كافٍ في الدلالة على عظمة هذه المخلوقات، وأنها من دلائل قدرته العظيمة، ويحتمل أن المعنى: هل في ذلك لذي حجر قسم آخر ينبغي أن يقسم به للدلالة على توحيد الله والدعوة إلى عبادته والإخلاص له  هذا -والله أعلم- من المعنى، ويحتمل معنى آخر ولعلنا نعود إلى ذلك في حلقة أخرى ليزيد البيان والإيضاح لما قاله أهل العلم.","link":"https://binbaz.org.sa/fatwas/18541/تفسير-قوله-تعالى-هل-في-ذلك-قسم-لذي-حجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_897/nour_89705.mp3","categories":["التفسير"]},{"id":19375,"question":"يسأل الأخوان عن تفسير قول الحق تبارك وتعالى أعوذ بالله من الشيطان الرجيم: وَأَلَّوِ اسْتَقَامُوا عَلَى الطَّرِيقَةِ لَأَسْقَيْنَاهُمْ مَاءً غَدَقًا [الجن:16] ؟","title":"تفسير قوله تعالى: (وألو استقاموا على الطريقة ...)","answer":"الجواب: الآية على ظاهرها، وهذا وعد من الله  أن الناس لو استقاموا على الطريقة التي رسم الله لهم من اتباع الشرع وطاعة الأوامر وترك النواهي لأسقاهم الله الغيث الكثير الذي ينفعهم في حروثهم وفي آبارهم وفي سائر شئونهم. ولكن بسبب التفريط والإضاعة والتساهل قد يؤخذ الناس بأنواع العقوبات التي منها الجدب والقحط ومنع الغيث، كما قال جل وعلا: وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ [الشورى:30] وقال جل وعلا: وَلَقَدْ أَخَذْنَا آلَ فِرْعَوْنَ بِالسِّنِينَ وَنَقْصٍ مِنَ الثَّمَرَاتِ [الأعراف:130] . فالحاصل أن القوم قد يعاقبون بالجدب والقحط لمعاصيهم، وقد ينزل الله عليهم الغيث ويمنحهم من فضله أنواع الخيرات بسبب طاعاتهم واستقامتهم على أمر الله. وقد يبتلي بعض عباده بالسراء على معاصيهم لعلهم يرجعون، لعلهم ينتبهون، كما قال تعالى: سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لا يَعْلَمُونَ [القلم:44]، وَأُمْلِي لَهُمْ إِنَّ كَيْدِي مَتِينٌ [الأعراف:183].\nفالواجب الحذر وأن لا يغتر الإنسان بإملاء الله وإمهاله له على ما هو عليه من المعاصي مع وجود النعم العظيمة والخير الكثير، فقد يكون استدارجًا. المقدم: جزاكم الله خيرًا، إذًا الطريقة ليست هي إحدى الطرق الصوفية كما يزعم بعض الصوفية .\nالشيخ: لا لا، الطريقة الإسلامية المشروعة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18596/تفسير-قوله-تعالى-والو-استقاموا-على-الطريقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93405.mp3","categories":["التفسير"]},{"id":19401,"question":"تسأل أختنا أم عبد الله عن تفسير قول الحق تبارك وتعالى أعوذ بالله من الشيطان الرجيم: إِنَّمَا ذَلِكُمُ الشَّيْطَانُ يُخَوِّفُ أَوْلِيَاءَهُ فَلا تَخَافُوهُمْ وَخَافُونِ إِنْ كُنْتُمْ مُؤْمِنِينَ [آل عمران:175] وهل تنطبق هذه الآية على الذي يخاف وهو في منزله؟","title":"تفسير قوله تعالى: (إنما ذلكم الشيطان يخوف أولياءه ...)","answer":"الجواب: هذه الآية نزلت في قصة المسلمين يوم أحد لما كان الشيطان يخوف المسلمين من رجوع الكفار إليهم وقتالهم قال الله جل وعلا: إِنَّمَا ذَلِكُمُ الشَّيْطَانُ يُخَوِّفُ أَوْلِيَاءَهُ [آل عمران:175] المعنى: يخوفكم بأوليائه يعني: يعظمهم في صدوركم ويجعلهم عظماء في صدور المسلمين حتى يخافوهم حتى يحذروهم فلا يجاهدوا، فبين  أن هذا غلط وأنه من الشيطان ونهاهم عن خوفهم فقال: (فلا تخافوهم) يعني: لا تخافوا أعداء الله الخوف الذي يجعلكم تجبنون عن قتالهم. أما الخوف الذي يوجب الإعداد لجهادهم والأهبة والحذر هذا مطلوب قال تعالى: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60] وقال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا خُذُوا حِذْرَكُمْ [النساء:71] فالذي لا يخاف عدوه لا يعد له العدة، فالواجب أن يعد العدة لعدوه من السلاح والزاد والقوة في الجهاد وجمع الصفوف والتشجيع على القتال والإقدام ونحو ذلك، لكن لا يخافهم خوفًا يجعله يجبن منهم ويتأخر عن قتالهم هذا هو المنهي عنه فإن الشيطان يعظم الكفار في صدور المسلمين حتى يخافوهم وحتى يجبنوا عن قتالهم. فهذا هو المعنى في قوله: فَلا تَخَافُوهُمْ يعني: لا تخافوهم الخوف الذي يمنعكم من قتالهم وجهادهم أو يجعلكم تجبنون عن قتالهم هذا هو المنهي عنه، أما الخوف الذي يوجب الإعداد لهم وأخذ الحذر فهذا مطلوب على المسلم أن يخاف شرهم وأن يحذر مكائدهم فيعد العدة، عليه أن يعد العدة اللازمة من السلاح ومن الحرس ونشر العيون التي تعرف أحوالهم حتى لا يهجموا على المسلمين، ولهذا قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا خُذُوا حِذْرَكُمْ [النساء:71] وقال سبحانه: وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ الصَّلاةَ فَلْتَقُمْ طَائِفَةٌ مِنْهُمْ مَعَكَ وَلْيَأْخُذُوا أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا فَلْيَكُونُوا مِنْ وَرَائِكُمْ وَلْتَأْتِ طَائِفَةٌ أُخْرَى لَمْ يُصَلُّوا فَلْيُصَلُّوا مَعَكَ وَلْيَأْخُذُوا حِذْرَهُمْ وَأَسْلِحَتَهُمْ وَدَّ الَّذِينَ كَفَرُوا لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُمْ مَيْلَةً وَاحِدَةً [النساء:102] فدل ذلك على أنهم مأمورون بأن يأخذوا حذرهم وأن يخافوا شر عدوهم ويخافوا مكائده فيكونون على حذر وعلى أهبة وعلى استعداد حتى لا يهجم عليهم العدو على غفلة وعلى غرة. فالمقصود: أن الخوف المنهي عنه غير الخوف المأمور به، الخوف المنهي عنه هو الذي يدعو إلى الجبن والتأخر وتعظيم الكفار ونشر الذعر بين الناس هذا منكر، أما الخوف الذي معناه الإعداد لهم والجد في حفظ أماكن المسلمين وثغورهم حتى لا يهجم عليهم العدو هذا أمر مطلوب. المقدم: جزاكم الله خيرًا، إذاً الآية الكريمة هي نص على باب الجهاد في سبيل الله، وليست على الخوف الذي ذكرته أختنا خوف الإنسان وهو في بيته. الشيخ: لا، هذا شيء آخر، خوف البيت هذا لا وجه له إذا كان البيت مأمون ومنغلق فالحمد لله، وإذا كان هناك شيء يخشى منه فالواجب على أهل البيت أن يسدوه إن كان فيه مداخل عليهم يسدوها، إن كان هناك يعني ما يخشى منه فيكون عندها من يؤنسها إلى غير ذلك من الأسباب، المؤمن يأخذ بالأسباب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18627/تفسير-قوله-تعالى-انما-ذلكم-الشيطان-يخوف-اولياءه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93508.mp3","categories":["التفسير"]},{"id":19403,"question":"من العراق الأنبار هذه رسالة بعث بها الأخ أبو بكر الهيتي -فيما يبدو-، أخونا يقول في رسالته يوجد حديث عند الإمام البخاري مروي عن رسول الله ﷺ: أن الميت يعذب ببكاء أهله عليه وحديث آخر عن سيدتنا عائشة أم المؤمنين رضي الله عنها ترفض هذا القول وتقول: «حسبكم القرآن وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] » فما جوابكم أثابكم الله عن هذه المسألة، هل الميت يعذب ببكاء أهله عليه؟ أم أنه لَيْسَ لِلإِنسَانِ إِلَّا مَا سَعَى[النجم:39] وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] ؟","title":"الجمع بين: {وَلَا تَزِرُ وَازِرَةٌ} و«إن الميت يعذب ببكاء أهله»","answer":"الجواب: ليس هناك تعارض بين الأحاديث ولا بين آية التي ذكرتها عائشة رضي الله عنها وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164]، فقد ثبت عن رسول الله ﷺ من حديث ابن عمر ومن حديث المغيرة ومن غيرهما في الصحيحين ليس في البخاري وحده بل في الصحيحين البخاري ومسلم جميعًا وفي غيرهما أن النبي ﷺ قال: إن الميت يعذب بما يناح عليه وفي الرواية الأخرى: ببكاء أهله عليه والمراد بالبكاء: يعني: النياحة رفع الصوت. أما البكاء الذي هو دمع العين فهذا لا يضر، إنما الذي يضر النياحة رفع الصوت، والرسول ﷺ قصد بهذا منع الناس من النياحة على موتاهم، وأن يتحملوا الصبر ويكفوا عن النوح ولا بأس بدمع العين، كما قال عليه الصلاة والسلام لما مات ابنه إبراهيم العين تدمع والقلب ليحزن ولا نقول إلا ما يرضي الرب وإنا بفراقك يا إبراهيم لمحزونون. فالميت يعذب بالنياحة عليه من أهله وكيفية العذاب الله أعلم بكيفية العذاب الذي يحصل له بهذه النياحة وهذا مستثنى من قوله تعالى: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] فإن القرآن والسنة لا يتعارضان بل يصدق أحدهما الآخر ويفسر أحدهما الآخر، فالآيات عامة والحديث خاص والسنة تخص القرآن وتبين معناه، فيكون تعذيب الميت بنياحة أهله عليه مستثنى من الآية الكريمة ولا تعارض بينها وبين الأحاديث، وأما قول عائشة رضي الله عنها فهذا من اجتهادها وحرصها على الخير وفهمها، وما قاله النبي ﷺ مقدم على قولها وعلى رأيها.","link":"https://binbaz.org.sa/fatwas/18629/الجمع-بين-ولا-تزر-وازرة-وان-الميت-يعذب-ببكاء-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93510.mp3","categories":["التفسير","شروح الحديث"]},{"id":19447,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين هو المستمع المطالب إبراهيم محمد ، الأخ يسأل ويقول: فسروا لنا قول الحق تبارك وتعالى: وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى [الضحى:5]؟","title":"تفسير قوله تعالى: (وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى)","answer":"الجواب: جاء في النصوص أن الله وعده، الرب -جل وعلا- وعد النبي ﷺ أنه مغيث لأمته، ومن ذلك أنه يأذن له في الشفاعة، فيشفع لهم في دخول الجنة ويشفع في كثير منهم دخل النار أن يخرج منها، وهذا مما أعطاه الله عليه الصلاة والسلام، وهكذا الشفاعة لأهل الموقف حتى يقضى بينهم، كل هذا مما خصه الله به، الشفاعة في أهل الموقف والشفاعة في أهل الجنة حتى يدخلوها. وأعطاه الله أيضًا الشفاعة في العصاة من الذين دخلوا النار من أمته أن يشفع فيهم، كونه يشفع في عدد كبير ويحد الله له حدًا، ولكن هذا ليس خاصًا به، الشفاعة لمن دخل النار ليس خاصًا بالنبي ﷺ، بل يشفع فيهم المؤمنون والملائكة والأفراط، فليست هذه خاصة به ﷺ، أما الشفاعة في أهل الموقف حتى يقضى بينهم، والشفاعة في أهل الجنة حتى يدخلوها، هذه خاصة به ﷺ. وله شفاعة ثالثة خاصة به، وهي الشفاعة في عمه أبي طالب حتى خفف عنه، كان في غمرات النار، فشفع فيه ﷺ حتى صار في ضحضاح من النار، لكنه لم يخرج من النار، بل يبقى في النار، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18688/تفسير-قوله-تعالى-ولسوف-يعطيك-ربك-فترضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74016.mp3","categories":["التفسير"]},{"id":19451,"question":"المستمع عايض محسن حاضر الغامدي من ضواحي الباحة يسأل عن تفسير قول الحق تبارك وتعالى، أعوذ بالله من الشيطان الرجيم: وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلاةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ[البقرة:45]؟","title":"تفسير قوله تعالى: (واستعينوا بالصبر والصلاة ...)","answer":"الجواب: على ظاهرها، الرب جل وعلا يأمر بالاستعانة بالصبر والصلاة في أمور الدنيا والدين، وكان النبي ﷺ إذا حزبه شيء فزع إلى الصلاة، فالصلاة من أعظم الأسباب على تيسير الأمور، وحل المشاكل؛ فإذا أهمه شيء، دين، أو ظالم، أو شبه ذلك، صلى ودعا ربه، واستغاث به أن يقضي دينه، وأن يكفيه شر الظالم، وأن يعينه على ذكره وشكره، ويصبر أيضًا على المشاق في طلب الرزق، وفي طاعة الله، وترك معصيته، يصبر، يخالف هواه، ويستعين بالله على ذلك، ويؤدي ما أوجب الله عليه من الصلاة في الجماعة من بر والديه، من صلة أرحامه، من قضاء الدين، من غير هذا مما أمر الله به، يصبر، ولا يتبرم، ولا يكسل ولا يضعف، بل يصبر على أداء الواجبات، وعلى ترك المحرمات، ويستعين بالله في ذلك، ويؤدي الصلاة كما أمر الله، الفرض والنفل كما أمر الله. ويستعين بها - يعني: بفعلها - على طاعة الله، وعلى أداء الحقوق، فإن الصلاة نعم العون، يصلي ويذكر الله، ويدعوه ويستعين به في سجوده، وبين السجدتين، وفي آخر الصلاة يرفع يديه، ويدعو ربه يقول: اللهم يسر لي كذا، اللهم أعطني كذا بعدما يسلم، أو في أي وقت يرفع يديه، ويدعو ربه، ويستجير به، ويسأله أن يعينه على قضاء الدين، وأن يعينه على سلامته من الظالم، أن يعينه على أداء الحج، أن يعينه على بر الوالدين إلى غير ذلك، يضرع إلى الله ويسأله. والصلاة تعينه على ذلك فإنها عبادة عظيمة، فإذا صلى وسأل ربه، وضرع إليه؛ أن يعينه على مهماته كان ذلك حسنًا طيبًا نافعًا، وقوله سبحانه: وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ[البقرة:45] يعني: شاقة، الصلاة تشق على الكسالى وضعفاء الإيمان، لكن الخاشعين المؤمنين الصادقين ميسرة عليهم، سهلة عليهم، لمعرفتهم بفضلها، وعظيم الأجر فيها، فهم يبادرون لها، ويسارعون إليها بنشاط، وقوة، ورغبة؛ لأنهم عرفوا قدرها، وعرفوا شأنها، فهي لا تشق عليهم، ولكنها تشق على الكسالى وضعفاء الإيمان الذين ليس عندهم بصيرة بشأن الصلاة وعظمها، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا، وتقبل منكم.","link":"https://binbaz.org.sa/fatwas/18718/تفسير-قوله-تعالى-واستعينوا-بالصبر-والصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94410.mp3","categories":["التفسير"]},{"id":19613,"question":"سماحة الشيخ هذا السائل يقول: ما هو تفسير هذه الآية الكريمة: إِنَّ الَّذِينَ لا يَرْجُونَ لِقَاءَنَا وَرَضُوا بِالْحَيَاةِ الدُّنْيَا وَاطْمَأَنُّوا بِهَا وَالَّذِينَ هُمْ عَنْ آيَاتِنَا غَافِلُونَ [يونس:7] الآية؟","title":"ما معنى: {إِنَّ الَّذِينَ لَا يَرْجُونَ لِقَاءَنَا وَرَضُوا بِالْحَيَاةِ الدُّنْيَا}؟","answer":"الجواب: هذا على ظاهرها، يعني: آثرها على الآخرة، رضوا بالحياة واطمأنوا بها وغفلوا عن الآخرة، ولم يؤدوا ما أوجب الله، ولم يجتهدوا في أداء حق الله، بل آثروا الدنيا على الآخرة، وصار همهم شهواتهم وقضاء أوطارهم من الدنيا، ونسوا الآخرة، ولم يوحدوا الله، ولم يعبدوه، ولم يؤدوا فرائضه، ولم يتركوا محارمه، فلهم النار يوم القيامة -نسأل الله العافية- لأنهم صاروا من أهل الدنيا، آثروها على الآخرة. نعم. نسأل الله العافية. المقدم: نسأل الله العافية، جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18882/ما-معنى-ان-الذين-لا-يرجون-لقاءنا-ورضوا-بالحياة-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94920.mp3","categories":["التفسير"]}]
